/**
 * The Afterglow's fog (version 2): a glowing, opaque medium raymarched through a slab around the game
 * plane (at reduced resolution, its jitter averaged over frames). Light scatters off every free
 * electron, so the eye sees only a short way in: the fog shines by its own heat, coloured by the true
 * blackbody colour of its temperature (blue-white, white, then candle orange as the era cools).
 *
 * Every sound wave is a spherical shell around the point it was rung (the waves are evaluated once a
 * frame into a small 3D field the march samples). Crests are compressed, denser and hotter, so they
 * shine brighter (radiance climbs with the fourth power of temperature); troughs are thinner and
 * cooler. A shell seen edge-on is crossed along a long path, so each ring shows a crisp limb-bright
 * rim with a dimmer face, and where crests cross the fronts add up and flare.
 *
 * As electrons are captured the fog thins and breaks into wisps (the cool troughs clear first), so the
 * eye reaches deeper: far wisps veiled, near ones sharp. Behind it all lies the imprint of every wave,
 * the future cosmic microwave background. At First Light a clearing front sweeps out from the centre,
 * the last of the fog flares and dissolves, and the imprint is left as a mottled pattern of light.
 */
import { FULLSCREEN_VS, Program, Target, drawFullscreen, type GLCaps } from '../../render/gl';
import { HEADER } from '../../render/glsl';
import { NOISE_SIZE, noiseVolume } from '../../render/noise3d';
import type { LayerFrame, RenderLayer } from '../../render/renderer';
import type { VolumeFront, VolumeLight } from '../../render/volume';

export const MAX_WAVES = 32;
const MAX_LIGHTS = 12;
const MAX_FRONTS = 6;

export interface AfterglowBgParams {
  temp: number;
  /** Purely visual temperature: eases toward `temp` after each step so the palette breathes. */
  visTemp: number;
  /** Fog thickness: the free-electron fraction (1 = fully ionized). */
  fog: number;
  /** 0 → 1 during First Light: the frozen pattern brightens. */
  reveal: number;
  /** 0 → 1 during First Light: the clearing front's progress from the centre outward. */
  clear: number;
  pulse: number;
  waveWidth: number;
  /** x, y, radius, amplitude per wave. */
  waves: Float32Array;
  waveCount: number;
  /** World rectangle the imprint grid covers. */
  rect: [number, number, number, number];
  /** 1 / standard deviation of the imprint, so its pattern always shows with full contrast. */
  impScale: number;
}

/** The imprint grid the fog hides (the future microwave background). */
export interface Imprint {
  width: number;
  height: number;
  data: () => Float32Array;
  version: () => number;
}

export interface FogConfig {
  /** March resolution relative to the scene, and steps per ray (both scaled by the quality level). */
  scale: number;
  steps: number;
  /** How far in front of the plane the slab starts, how far behind it ends, the camera distance. */
  near: number;
  depth: number;
  focal: number;
  /** Absorption per unit at full ionization: the fog's opacity (1 / the mean free path). */
  kappa: number;
  /** Emission scale. */
  brightness: number;
  /** How bright the crests' cores glow (per unit of path, relative to the bath). */
  crest: number;
  /** The fronts' thin cores: brightness, and gaussian half-width (world units). */
  fronts: number;
  coreWidth: number;
  /** How much the fog billows (0: a smooth bath). */
  billow: number;
  /** World units per noise tile, and tiles per second of churning. */
  noiseScale: number;
  boil: number;
}

export function defaultFog(): FogConfig {
  return { scale: 0.5, steps: 32, near: 120, depth: 900, focal: 1600, kappa: 0.009, brightness: 0.055, crest: 0.03, fronts: 1.6, coreWidth: 2.4, billow: 1, noiseScale: 1150, boil: 0.006 };
}

/** The sound field as 3D shells: one layer per depth (|z|; the field is mirror-symmetric about the plane). */
const WAVE_FS = HEADER + /* glsl */ `
in vec2 vUv;
out vec4 outColor;
uniform vec4 uRegion;
uniform float uZ;
uniform float uWidth;
uniform vec4 uWaves[${MAX_WAVES}];
uniform int uWaveCount;
void main() {
  vec2 xy = mix(uRegion.xy, uRegion.zw, vUv);
  float d = 0.0;
  float core = 0.0;
  float z2 = uZ * uZ;
  for (int i = 0; i < ${MAX_WAVES}; i++) {
    if (i >= uWaveCount) break;
    vec4 w = uWaves[i];
    vec2 dv = xy - w.xy;
    float x = (sqrt(dot(dv, dv) + z2) - w.z) / uWidth;
    float x2 = x * x;
    float e = exp(-0.5 * x2);
    d += w.w * (1.0 - x2) * e;
    // The crest's narrow core: where the compression is sharpest.
    float e2 = e * e;
    float e4 = e2 * e2;
    core += w.w * e4 * e4 * e2;
  }
  outColor = vec4(clamp(d, -1.4, 1.4), min(core, 2.0), 0.0, 1.0);
}`;

/**
 * The imprint as light, shared by the march (faint, behind the fog) and the full-resolution pass (the
 * revealed pattern, crisp). Expects uImprint, uRect, uImpSize, uImpScale and N() (the noise texture).
 */
const FROZEN = /* glsl */ `
/** Cubic B-spline weights (for smooth reconstruction of the coarse imprint grid). */
vec4 bspline(float v) {
  vec4 n = vec4(1.0, 2.0, 3.0, 4.0) - v;
  vec4 s = n * n * n;
  float x = s.x;
  float y = s.y - 4.0 * s.x;
  float z = s.z - 4.0 * s.y + 6.0 * s.x;
  return vec4(x, y, z, 6.0 - x - y - z) * (1.0 / 6.0);
}

float bicubic(sampler2D tex, vec2 uv, vec2 size) {
  vec2 st = uv * size - 0.5;
  vec2 f = fract(st);
  st -= f;
  vec4 xc = bspline(f.x);
  vec4 yc = bspline(f.y);
  vec4 c = st.xxyy + vec2(-0.5, 1.5).xyxy;
  vec4 s = vec4(xc.xz + xc.yw, yc.xz + yc.yw);
  vec4 o = (c + vec4(xc.yw, yc.yw) / s) / size.xxyy;
  float s0 = texture(tex, o.xz).r;
  float s1 = texture(tex, o.yz).r;
  float s2 = texture(tex, o.xw).r;
  float s3 = texture(tex, o.yw).r;
  float sx = s.x / (s.x + s.y);
  float sy = s.z / (s.z + s.w);
  return mix(mix(s3, s2, sx), mix(s1, s0, sx), sy);
}

/**
 * The frozen pattern as light: hot spots (dense, compressed) blaze gold-white, cold spots fall to a
 * deep ember red, with radiance climbing steeply between them, and finer mottling inside the broad
 * pattern (the smallest ripples, damped but not gone).
 */
vec3 frozen(vec2 xy) {
  vec2 raw = (xy - uRect.xy) / (uRect.zw - uRect.xy);
  vec2 iuv = clamp(raw, 0.0, 1.0);
  // Nothing was imprinted outside the grid: the pattern ends there instead of smearing its edge.
  vec2 out2 = abs(raw - iuv) * (uRect.zw - uRect.xy) / 120.0;
  float inside = exp(-dot(out2, out2));
  float v = clamp(bicubic(uImprint, iuv, uImpSize) * uImpScale, -2.6, 2.6);
  // The finer mottling comes from the noise's own octaves, sampled turned and at unrelated scales so
  // its tiling never lines up into a lattice.
  vec2 r = mat2(0.825, 0.565, -0.565, 0.825) * xy;
  vec3 q = vec3(r / 170.0, 0.37 + xy.y / 3100.0);
  float fine = (N(q) - 0.5) * 0.9 + (N(q * 2.13 + vec3(0.31, 0.57, 0.11)) - 0.5) * 0.6;
  float t = clamp(0.45 + 0.19 * v + 0.11 * fine, 0.0, 1.0);
  // Deep crimson where it is coldest, through orange and gold to white-hot: saturated, over black.
  vec3 c = mix(vec3(0.6, 0.01, 0.03), vec3(1.0, 0.1, 0.02), smoothstep(0.1, 0.4, t));
  c = mix(c, vec3(1.0, 0.36, 0.04), smoothstep(0.35, 0.62, t));
  c = mix(c, vec3(1.0, 0.68, 0.22), smoothstep(0.6, 0.84, t));
  c = mix(c, vec3(1.0, 0.92, 0.75), smoothstep(0.84, 1.0, t));
  float t3 = t * t * t;
  return c * (0.0015 + 3.0 * t3 * t3) * inside;
}
`;

const MARCH_FS = HEADER + /* glsl */ `
precision highp sampler3D;
in vec2 vUv;
out vec4 outColor;
uniform sampler3D uWave;
uniform sampler3D uNoise;
uniform sampler2D uImprint;
uniform vec4 uView;
uniform vec4 uRegion;
uniform float uZMax;
uniform float uFocal;
uniform float uDepth;
uniform float uNear;
uniform float uTime;
uniform float uFrame;
uniform int uSteps;
uniform float uNoiseScale;
uniform float uBoil;
uniform float uBillow;
uniform float uKappa;
uniform float uBright;
uniform float uCrest;
uniform float uAmpNorm;
uniform float uLogT;
uniform float uFog;
uniform float uReveal;
uniform float uClear;
uniform float uPulse;
uniform vec4 uRect;
uniform vec2 uImpSize;
uniform float uImpScale;
uniform vec4 uLight[${MAX_LIGHTS}];
uniform vec3 uLightCol[${MAX_LIGHTS}];
uniform int uLightCount;
uniform vec4 uFront[${MAX_FRONTS}];
uniform vec3 uFrontCol[${MAX_FRONTS}];
uniform int uFrontCount;

float N(vec3 p) { return texture(uNoise, p).r; }
${FROZEN}
/** Shadow, body and highlight colours of the bath at log10 temperature lk (the blackbody locus, hand-keyed). */
void palette(float lk, out vec3 sh, out vec3 md, out vec3 hi) {
  float w1 = smoothstep(3.48, 3.72, lk);
  float w2 = smoothstep(3.72, 3.97, lk);
  float w3 = smoothstep(3.97, 4.35, lk);
  sh = mix(mix(mix(vec3(0.42, 0.035, 0.03), vec3(0.34, 0.08, 0.2), w1), vec3(0.18, 0.12, 0.42), w2), vec3(0.08, 0.07, 0.55), w3);
  md = mix(mix(mix(vec3(1.0, 0.36, 0.07), vec3(1.0, 0.68, 0.36), w1), vec3(0.86, 0.84, 1.0), w2), vec3(0.34, 0.5, 1.0), w3);
  hi = mix(mix(mix(vec3(1.0, 0.72, 0.36), vec3(1.0, 0.93, 0.78), w1), vec3(1.0, 0.98, 0.96), w2), vec3(0.88, 0.94, 1.0), w3);
}

/** Interleaved gradient noise (Jimenez 2014): a spatially even jitter that converges fast over frames. */
float ign(vec2 p) { return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715)))); }

void main() {
  vec2 ndc = vUv * 2.0 - 1.0;
  vec3 onPlane = vec3(uView.x + ndc.x * uView.z, uView.y - ndc.y * uView.w, 0.0);
  vec3 cam = vec3(uView.xy, -uFocal);
  vec3 dir = normalize(onPlane - cam);
  float t0 = (-uNear - cam.z) / dir.z;
  float t1 = (uDepth - cam.z) / dir.z;
  float stepLen = (t1 - t0) / float(uSteps);
  float t = t0 + stepLen * fract(ign(gl_FragCoord.xy) + uFrame * 0.6180339887);

  vec3 sh, md, hi;
  palette(uLogT, sh, md, hi);
  // Hotter baths shine brighter; warm light needs more energy to read as glowing rather than brown.
  float heat = clamp(1.0 + 0.16 * (uLogT - 3.48), 1.0, 1.6);
  float warm = mix(1.7, 1.0, smoothstep(3.8, 4.1, uLogT));
  float glow = uBright * heat * warm * (1.0 + uPulse);
  // The fog breaks into veils as electrons are caught: what still holds is where the billows are
  // densest and the plasma most compressed; the cool troughs clear first.
  float thr = 1.1 - 1.3 * uFog;
  // Everywhere, the light reaches farther as the free electrons thin out.
  float thin = mix(0.3, 1.0, uFog);
  float R = uClear * 2.6 - 0.15;
  // Warm light needs wider colour ratios to read as glowing rather than brown (the tonemapper greys
  // out modest ones), most of all candle orange.
  float sat = mix(1.9, 1.15, smoothstep(3.62, 4.05, uLogT));
  sh = pow(sh, vec3(sat));
  md = pow(md, vec3(sat));
  hi = pow(hi, vec3(mix(sat, 1.0, 0.5)));
  vec2 wspan = uRegion.zw - uRegion.xy;

  vec3 L = vec3(0.0);
  float T = 1.0;
  // How much of the light from the game plane gets through the fog in front of it.
  float T0 = 1.0;
  for (int i = 0; i < 96; i++) {
    if (i >= uSteps || T < 0.01) break;
    vec3 p = cam + dir * t;
    if (p.z < 0.0) T0 = T;
    vec3 wuv = vec3((p.xy - uRegion.xy) / wspan, abs(p.z) / uZMax);
    vec2 wave = texture(uWave, wuv).rg * uAmpNorm;
    float d = wave.r;
    vec3 q = p / uNoiseScale;
    float tb = uTime * uBoil;
    float n = N(q + vec3(0.0, 0.0, tb)) * 0.7 + N(q * 2.9 + vec3(0.41, 0.13, tb * 1.7)) * 0.3;
    float ns = clamp((n - 0.5) * 2.4 + 0.5, 0.0, 1.0);
    float hold = smoothstep(thr - 0.07, thr + 0.1, ns + 0.3 * d);
    float rim = 0.0;
    if (uClear > 0.0) {
      // First Light: a clearing front sweeping out across the plane, frayed by the billows; the last
      // fog at its edge flares as its electrons are caught.
      float dist = length(p.xy - uView.xy) / uView.w + 0.35 * (n - 0.5);
      rim = exp(-pow((dist - R) / 0.07, 2.0)) * (1.0 - uClear) * hold;
      hold *= smoothstep(R - 0.2, R + 0.06, dist);
    }
    // Where no fog holds, the light passes through untouched: nothing to add, nothing to dim.
    if (hold + rim < 0.002) {
      t += stepLen;
      continue;
    }
    // Local temperature relative to the bath: compressed plasma is hotter (T grows as δ/3, drawn a
    // little stronger so the waves read), and the billows carry a faint unevenness of their own.
    float tl = max(0.2, 1.0 + 0.36 * d + 0.06 * uBillow * (n - 0.5));
    float tl2 = tl * tl;
    float rad = tl2 * tl2;
    vec3 col = mix(md, hi, smoothstep(1.0, 1.3, tl));
    col = mix(sh, col, smoothstep(0.5, 0.97, tl));
    // The edges of the veils, where the last free electrons are being caught, glow hotter (each capture
    // gives off light) while the gaps between them open to the dark.
    float edge = 4.0 * hold * (1.0 - hold) * (1.0 - uFog);
    vec3 S = col * rad * glow * (1.0 + 3.0 * edge) + hi * rim * glow * 6.0;
    // The crest core glows thin (a shell of compressed light), so a shell seen edge-on, crossed along a
    // long path, shows a crisp limb-bright rim over a dimmer face; the billows fray it.
    vec3 crest = hi * wave.g * exp(-p.z * p.z / 8000.0) * (0.55 + 0.9 * n) * glow * uCrest * hold;
    vec3 lit = vec3(0.0);
    for (int k = 0; k < ${MAX_LIGHTS}; k++) {
      if (k >= uLightCount) break;
      vec3 dl = p - uLight[k].xyz;
      float r = uLight[k].w;
      float qq = 1.0 + dot(dl, dl) / (r * r);
      lit += uLightCol[k] / (qq * sqrt(qq));
    }
    for (int k = 0; k < ${MAX_FRONTS}; k++) {
      if (k >= uFrontCount) break;
      float x = (length(p - vec3(uFront[k].xy, 0.0)) - uFront[k].z) / uFront[k].w;
      lit += uFrontCol[k] * exp(-x * x);
    }
    S += lit;
    // Opacity follows the free electrons: denser in crests, thinner in troughs, gone where atoms hold them.
    float kap = uKappa * thin * max(hold, rim) * max(0.0, 1.0 + 0.9 * d) * (0.85 + 0.3 * uBillow * n);
    float a = kap * stepLen;
    float e = exp(-a);
    L += T * (S * (1.0 - e) + crest * stepLen);
    T *= e;
    t += stepLen;
  }
  // What the fog hides: the imprint of every wave, faint until First Light reveals it (the revealed
  // pattern is drawn at full resolution, over the cleared field).
  L += T * frozen(onPlane.xy) * 0.06;
  outColor = vec4(L, T0);
}`;

/** Folds this frame's march into the running average, reprojected with the camera (as the plasma does). */
const ACCUM_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uCur;
uniform sampler2D uPrev;
uniform vec4 uView;
uniform vec4 uPrevView;
uniform float uSpread;
uniform float uBlend;
uniform vec2 uTexel;
out vec4 outColor;
void main() {
  vec4 cur = texture(uCur, vUv);
  vec2 ndc = vUv * 2.0 - 1.0;
  vec2 w = uView.xy + vec2(ndc.x, -ndc.y) * uView.zw * uSpread;
  vec2 pn = (w - uPrevView.xy) / (uPrevView.zw * uSpread);
  vec2 puv = vec2(pn.x, -pn.y) * 0.5 + 0.5;
  if (uBlend >= 1.0 || any(lessThan(puv, vec2(0.0))) || any(greaterThan(puv, vec2(1.0)))) {
    outColor = cur;
    return;
  }
  vec4 lo = cur;
  vec4 hi = cur;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec4 n = texture(uCur, vUv + vec2(float(x), float(y)) * uTexel);
      lo = min(lo, n);
      hi = max(hi, n);
    }
  }
  vec4 prev = clamp(texture(uPrev, puv), lo, hi);
  outColor = mix(prev, cur, uBlend);
}`;

const COMPOSITE_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uSrc;
out vec4 outColor;
void main() { outColor = vec4(texture(uSrc, vUv).rgb, 1.0); }`;

/**
 * The fronts at full resolution: each wave's crest, where it meets the game plane (the limb of its
 * shell), as a thin bright core, frayed by the billows and flaring where fronts cross (brighter than
 * the sum of their parts), seen through as much fog as lies in front of the plane.
 */
const FRONT_FS = HEADER + /* glsl */ `
precision highp sampler3D;
in vec2 vUv;
out vec4 outColor;
uniform vec4 uView;
uniform vec4 uWaves[${MAX_WAVES}];
uniform int uWaveCount;
uniform float uCoreWidth;
uniform float uGain;
uniform vec3 uColor;
uniform float uTime;
uniform float uBoil;
uniform float uNoiseScale;
uniform float uAmpRef;
uniform float uClear;
uniform float uReveal;
uniform sampler2D uFog;
uniform sampler3D uNoise;
uniform sampler2D uImprint;
uniform vec4 uRect;
uniform vec2 uImpSize;
uniform float uImpScale;
float N(vec3 p) { return texture(uNoise, p).r; }
${FROZEN}
void main() {
  vec2 ndc = vUv * 2.0 - 1.0;
  vec2 xy = vec2(uView.x + ndc.x * uView.z, uView.y - ndc.y * uView.w);
  // Upgrades ring louder: a little brighter, never a wash of white.
  float loud = pow(uAmpRef / 0.34, 0.3) * 0.34;
  float sum = 0.0;
  float sq = 0.0;
  float wake = 0.0;
  for (int i = 0; i < ${MAX_WAVES}; i++) {
    if (i >= uWaveCount) break;
    vec4 w = uWaves[i];
    // Diffusion (Silk damping) widens a front as it spreads: young fronts are sharp, old ones soft.
    float width = uCoreWidth * (1.0 + w.z / 260.0);
    float x = (length(xy - w.xy) - w.z) / width;
    if (x > 4.0 || x < -40.0) continue;
    // Young fronts burn; damped ones fade much faster than their amplitude, and the sharp front itself
    // diffuses away within a few hundred units (the smallest scales damp first), leaving the broad
    // wave to the fog.
    float rel = min(1.2, w.w / uAmpRef);
    float a = loud * rel * rel * sqrt(rel) * exp(-w.z / 240.0) / (1.0 + w.z / 260.0);
    // A sharp leading edge, and behind it the plasma still glowing as it relaxes.
    float c = a * exp(-x * x);
    sum += c;
    sq += c * c;
    wake += a * (x < 0.0 ? exp(x / 7.0) * (1.0 - exp(x * 1.5)) : 0.0);
  }
  // First Light: behind the clearing front, the frozen pattern of every wave, as light.
  float cleared = uClear > 0.0 ? smoothstep(-0.1, 0.05, uClear * 2.6 - 0.15 - length(xy - uView.xy) / uView.w) : 0.0;
  vec3 cmb = uReveal > 0.0 ? frozen(xy) * 0.94 * uReveal * mix(1.0, 2.2, uReveal) * cleared : vec3(0.0);
  if (sum + wake < 1e-4) {
    outColor = vec4(cmb, 0.0);
    return;
  }
  float flare = sum * sum - sq;
  vec3 q = vec3(xy / (uNoiseScale * 0.45), uTime * uBoil * 2.0);
  float n = texture(uNoise, q).r * 0.65 + texture(uNoise, q * 3.1 + 0.37).r * 0.35;
  float fray = smoothstep(0.25, 0.75, n);
  float seen = 0.3 + 0.7 * texture(uFog, vUv).a;
  // At First Light the sound stops where the fog has cleared: nothing is left to push back.
  seen *= 1.0 - cleared;
  // A white-hot core in a sheath of the plasma's own colour.
  vec3 core = mix(uColor, vec3(1.0), 0.35) * (sum * (0.25 + 1.5 * fray) + 6.0 * flare);
  vec3 sheath = uColor * wake * (0.4 + 0.8 * fray) * 0.16;
  outColor = vec4((core + sheath) * uGain * seen + cmb, 0.0);
}`;

/** Size of the sound field's 3D grid at High (x, y over the view, z over the slab's depth). */
const WAVE_GRID: [number, number, number] = [240, 140, 20];

export class Fog implements RenderLayer {
  readonly stage = 'media' as const;
  config: FogConfig;
  /** Refilled by the caller every frame. */
  lights: VolumeLight[] = [];
  fronts: VolumeFront[] = [];
  private gl: WebGL2RenderingContext | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private waveProg: Program | null = null;
  private march: Program | null = null;
  private accum: Program | null = null;
  private comp: Program | null = null;
  private frontProg: Program | null = null;
  private noise: WebGLTexture | null = null;
  private waveTex: WebGLTexture | null = null;
  private waveFbo: WebGLFramebuffer | null = null;
  private waveSize: [number, number, number] = [0, 0, 0];
  private imprintTex: WebGLTexture | null = null;
  private imprintVersion = -1;
  private target: Target | null = null;
  private history: [Target, Target] | null = null;
  private fresh = true;
  private prevView = new Float32Array(4);
  private frameNo = 0;
  private time = 0;
  private region = new Float32Array(4);
  private lightA = new Float32Array(MAX_LIGHTS * 4);
  private lightC = new Float32Array(MAX_LIGHTS * 3);
  private frontA = new Float32Array(MAX_FRONTS * 4);
  private frontC = new Float32Array(MAX_FRONTS * 3);

  constructor(
    private readonly params: AfterglowBgParams,
    private readonly imprint: Imprint,
    config: Partial<FogConfig> = {},
  ) {
    this.config = { ...defaultFog(), ...config };
  }

  init(gl: WebGL2RenderingContext, caps: GLCaps, emptyVao: WebGLVertexArrayObject): void {
    this.gl = gl;
    this.vao = emptyVao;
    this.waveProg = this.march = this.accum = this.comp = this.frontProg = null;
    if (!caps.hdr) return;
    try {
      this.waveProg = new Program(gl, FULLSCREEN_VS, WAVE_FS, 'fog:waves');
      this.march = new Program(gl, FULLSCREEN_VS, MARCH_FS, 'fog:march');
      this.accum = new Program(gl, FULLSCREEN_VS, ACCUM_FS, 'fog:accumulate');
      this.comp = new Program(gl, FULLSCREEN_VS, COMPOSITE_FS, 'fog:composite');
      this.frontProg = new Program(gl, FULLSCREEN_VS, FRONT_FS, 'fog:fronts');
    } catch (e) {
      console.error(e);
      this.waveProg = this.march = this.accum = this.comp = this.frontProg = null;
      return;
    }
    const noise = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_3D, noise);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    gl.texImage3D(gl.TEXTURE_3D, 0, gl.R8, NOISE_SIZE, NOISE_SIZE, NOISE_SIZE, 0, gl.RED, gl.UNSIGNED_BYTE, noiseVolume());
    setFilter3d(gl, gl.REPEAT);
    this.noise = noise;
    this.waveTex = gl.createTexture();
    this.waveFbo = gl.createFramebuffer();
    this.waveSize = [0, 0, 0];
    const imp = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, imp);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.bindTexture(gl.TEXTURE_2D, null);
    this.imprintTex = imp;
    this.imprintVersion = -1;
    this.target = new Target(gl, 1, 1, true);
    this.history = [new Target(gl, 1, 1, true), new Target(gl, 1, 1, true)];
    this.fresh = true;
  }

  /** Allocates the sound field's 3D grid at a new size (the quality level changed). */
  private sizeWaves(nx: number, ny: number, nz: number): void {
    const gl = this.gl!;
    const [ox, oy, oz] = this.waveSize;
    if (nx === ox && ny === oy && nz === oz) return;
    this.waveSize = [nx, ny, nz];
    gl.bindTexture(gl.TEXTURE_3D, this.waveTex);
    gl.texImage3D(gl.TEXTURE_3D, 0, gl.RG16F, nx, ny, nz, 0, gl.RG, gl.HALF_FLOAT, null);
    setFilter3d(gl, gl.CLAMP_TO_EDGE);
  }

  draw(frame: LayerFrame): void {
    const gl = this.gl;
    const m = this.march;
    const acc = this.accum;
    const wp = this.waveProg;
    if (!gl || !m || !acc || !wp || !this.comp || !this.frontProg || !this.noise || !this.waveTex || !this.waveFbo || !this.imprintTex || !this.target || !this.history) return;
    const c = this.config;
    const P = this.params;
    const q = frame.quality;
    const v = frame.view;
    this.time += frame.dt;
    gl.disable(gl.BLEND);

    // 1. The sound field, over the region the rays cross (wider at the back of the slab, in perspective).
    const nx = Math.max(64, Math.round(WAVE_GRID[0] * q.volume));
    const ny = Math.max(36, Math.round(WAVE_GRID[1] * q.volume));
    const nz = Math.max(8, Math.round(WAVE_GRID[2] * q.steps));
    this.sizeWaves(nx, ny, nz);
    // Past about half the slab's depth the far edges clamp: by then the fog has veiled them.
    const spread = ((c.focal + 0.5 * c.depth) / c.focal) * 1.04;
    const rg = this.region;
    rg[0] = v[0] - v[2] * spread;
    rg[1] = v[1] - v[3] * spread;
    rg[2] = v[0] + v[2] * spread;
    rg[3] = v[1] + v[3] * spread;
    const zMax = Math.max(c.depth, c.near);
    wp.use().f1('uWidth', P.waveWidth).i1('uWaveCount', P.waveCount);
    gl.uniform4fv(wp.loc('uRegion'), rg);
    gl.uniform4fv(wp.loc('uWaves'), P.waves);
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.waveFbo);
    gl.viewport(0, 0, nx, ny);
    for (let k = 0; k < nz; k++) {
      gl.framebufferTextureLayer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, this.waveTex, 0, k);
      wp.f1('uZ', ((k + 0.5) / nz) * zMax);
      drawFullscreen(gl, this.vao!);
    }

    // 2. The imprint, re-uploaded when it changes.
    const imp = this.imprint;
    gl.activeTexture(gl.TEXTURE2);
    gl.bindTexture(gl.TEXTURE_2D, this.imprintTex);
    const iv = imp.version();
    if (iv !== this.imprintVersion) {
      this.imprintVersion = iv;
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.R16F, imp.width, imp.height, 0, gl.RED, gl.FLOAT, imp.data());
    }

    // 3. The march. Lower quality: fewer steps at a lower resolution, more frames averaged.
    const t = this.target;
    const [prev, next] = this.history;
    const scale = c.scale * q.volume;
    const steps = Math.max(6, Math.min(96, Math.round(c.steps * q.steps)));
    const blend = Math.min(1, 0.24 * (steps / Math.max(6, c.steps)));
    const w0 = t.width;
    const h0 = t.height;
    t.resize(frame.scene.width * scale, frame.scene.height * scale);
    prev.resize(t.width, t.height);
    next.resize(t.width, t.height);
    if (t.width !== w0 || t.height !== h0) this.fresh = true;

    const nl = Math.min(MAX_LIGHTS, this.lights.length);
    for (let i = 0; i < nl; i++) {
      const L = this.lights[i];
      this.lightA.set([L.x, L.y, L.z, Math.max(1, L.radius)], i * 4);
      this.lightC.set(L.color, i * 3);
    }
    const nf = Math.min(MAX_FRONTS, this.fronts.length);
    for (let i = 0; i < nf; i++) {
      const f = this.fronts[i];
      this.frontA.set([f.x, f.y, f.radius, Math.max(1, f.width)], i * 4);
      this.frontC.set(f.color, i * 3);
    }

    t.bind();
    m.use().f1('uFocal', c.focal).f1('uDepth', c.depth).f1('uNear', c.near).f1('uTime', this.time).f1('uZMax', zMax);
    m.f1('uFrame', (this.frameNo = (this.frameNo + 1) % 1024));
    m.f1('uAmpNorm', Math.pow(0.34 / Math.max(0.05, this.ampRef), 0.7));
    m.f1('uNoiseScale', c.noiseScale).f1('uBoil', c.boil).f1('uBillow', c.billow).f1('uKappa', c.kappa).f1('uBright', c.brightness).f1('uCrest', c.crest);
    m.f1('uLogT', Math.log10(Math.max(1000, P.visTemp))).f1('uFog', P.fog).f1('uReveal', P.reveal).f1('uClear', P.clear).f1('uPulse', P.pulse);
    const r = P.rect;
    m.f4('uRect', r[0], r[1], r[2], r[3]).f2('uImpSize', imp.width, imp.height).f1('uImpScale', P.impScale);
    gl.uniform1i(m.loc('uSteps'), steps);
    gl.uniform4fv(m.loc('uView'), v);
    gl.uniform4fv(m.loc('uRegion'), rg);
    gl.uniform4fv(m.loc('uLight'), this.lightA);
    gl.uniform3fv(m.loc('uLightCol'), this.lightC);
    gl.uniform1i(m.loc('uLightCount'), nl);
    gl.uniform4fv(m.loc('uFront'), this.frontA);
    gl.uniform3fv(m.loc('uFrontCol'), this.frontC);
    gl.uniform1i(m.loc('uFrontCount'), nf);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_3D, this.waveTex);
    m.i1('uWave', 0);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_3D, this.noise);
    m.i1('uNoise', 1);
    m.i1('uImprint', 2);
    drawFullscreen(gl, this.vao!);
    gl.activeTexture(gl.TEXTURE2);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_3D, null);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_3D, null);

    // 4. Into the running average, reprojected at the depth most of the light comes from.
    next.bind();
    acc.use().i1('uCur', 0).i1('uPrev', 1).f1('uBlend', this.fresh ? 1 : blend);
    const z = Math.min(c.depth, -c.near + 0.5 / Math.max(1e-5, c.kappa * Math.max(0.2, P.fog)));
    acc.f1('uSpread', (c.focal + z) / c.focal).f2('uTexel', 1 / t.width, 1 / t.height);
    gl.uniform4fv(acc.loc('uView'), v);
    gl.uniform4fv(acc.loc('uPrevView'), this.fresh ? v : this.prevView);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, prev.tex);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, t.tex);
    drawFullscreen(gl, this.vao!);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.activeTexture(gl.TEXTURE0);
    this.history = [next, prev];
    this.prevView.set(v);
    this.fresh = false;

    // 5. Into the scene (the fog is the backdrop: everything else draws over it).
    frame.scene.bind();
    this.comp.use().i1('uSrc', 0);
    gl.bindTexture(gl.TEXTURE_2D, next.tex);
    drawFullscreen(gl, this.vao!);

    // 6. The fronts' thin cores at full resolution, added over it.
    if (P.waveCount > 0 || P.reveal > 0) {
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE);
      const f = this.frontProg.use();
      const hot = this.crestColor;
      f.f1('uCoreWidth', c.coreWidth).f1('uGain', c.fronts * (1 - P.reveal)).f3('uColor', hot[0], hot[1], hot[2]);
      f.f1('uReveal', P.reveal).f4('uRect', r[0], r[1], r[2], r[3]).f2('uImpSize', imp.width, imp.height).f1('uImpScale', P.impScale);
      gl.activeTexture(gl.TEXTURE2);
      gl.bindTexture(gl.TEXTURE_2D, this.imprintTex);
      f.i1('uImprint', 2);
      f.f1('uTime', this.time).f1('uBoil', c.boil).f1('uNoiseScale', c.noiseScale).i1('uWaveCount', P.waveCount);
      f.f1('uAmpRef', Math.max(0.05, this.ampRef)).f1('uClear', P.clear);
      gl.uniform4fv(f.loc('uView'), v);
      gl.uniform4fv(f.loc('uWaves'), P.waves);
      gl.activeTexture(gl.TEXTURE1);
      gl.bindTexture(gl.TEXTURE_3D, this.noise);
      f.i1('uNoise', 1);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, next.tex);
      f.i1('uFog', 0);
      drawFullscreen(gl, this.vao!);
      gl.activeTexture(gl.TEXTURE2);
      gl.bindTexture(gl.TEXTURE_2D, null);
      gl.activeTexture(gl.TEXTURE1);
      gl.bindTexture(gl.TEXTURE_3D, null);
      gl.activeTexture(gl.TEXTURE0);
    }
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.enable(gl.BLEND);
  }

  /** The fronts' colour: the bath's highlight, a little hotter (linear, unit brightness). */
  crestColor: [number, number, number] = [0.85, 0.92, 1.0];
  /** A freshly rung wave's amplitude now (upgrades raise it): the waves are drawn relative to it. */
  ampRef = 0.34;

  dispose(): void {
    const gl = this.gl;
    if (!gl) return;
    this.waveProg?.dispose();
    this.frontProg?.dispose();
    this.march?.dispose();
    this.accum?.dispose();
    this.comp?.dispose();
    if (this.noise) gl.deleteTexture(this.noise);
    if (this.waveTex) gl.deleteTexture(this.waveTex);
    if (this.waveFbo) gl.deleteFramebuffer(this.waveFbo);
    if (this.imprintTex) gl.deleteTexture(this.imprintTex);
    this.target?.dispose();
    for (const h of this.history ?? []) h.dispose();
    this.waveProg = this.march = this.accum = this.comp = this.frontProg = null;
    this.noise = this.waveTex = this.imprintTex = null;
    this.waveFbo = null;
    this.target = this.history = null;
  }
}

function setFilter3d(gl: WebGL2RenderingContext, wrap: number): void {
  gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  for (const w of [gl.TEXTURE_WRAP_S, gl.TEXTURE_WRAP_T, gl.TEXTURE_WRAP_R]) gl.texParameteri(gl.TEXTURE_3D, w, wrap);
  gl.bindTexture(gl.TEXTURE_3D, null);
}
