/**
 * Colour science shared by the CPU side (particle colours, the UI accent) and mirrored in GLSL.
 * All colours are linear sRGB unless named otherwise.
 */

export type RGB = [number, number, number];

/**
 * Chromaticity of a blackbody at temperature T (Kim et al. 2002 fit to the Planckian locus),
 * converted to linear sRGB and normalised so the brightest channel is 1.
 * Below ~1,700 K the colour is held at deep red; above 25,000 K at the blue-white limit, which is
 * where the locus converges anyway (an infinitely hot body is pale blue, not violet).
 */
export function blackbody(kelvin: number): RGB {
  const T = Math.min(Math.max(kelvin, 1667), 25000);
  const t = 1 / T;
  let x: number;
  if (T <= 4000) x = -0.2661239e9 * t * t * t - 0.2343589e6 * t * t + 0.8776956e3 * t + 0.17991;
  else x = -3.0258469e9 * t * t * t + 2.1070379e6 * t * t + 0.2226347e3 * t + 0.24039;
  let y: number;
  if (T <= 2222) y = -1.1063814 * x ** 3 - 1.3481102 * x ** 2 + 2.18555832 * x - 0.20219683;
  else if (T <= 4000) y = -0.9549476 * x ** 3 - 1.37418593 * x ** 2 + 2.09137015 * x - 0.16748867;
  else y = 3.081758 * x ** 3 - 5.8733867 * x ** 2 + 3.75112997 * x - 0.37001483;
  const X = x / y;
  const Z = (1 - x - y) / y;
  let r = 3.2406 * X - 1.5372 - 0.4986 * Z;
  let g = -0.9689 * X + 1.8758 + 0.0415 * Z;
  let b = 0.0557 * X - 0.204 + 1.057 * Z;
  r = Math.max(r, 0);
  g = Math.max(g, 0);
  b = Math.max(b, 0);
  const m = Math.max(r, g, b);
  return [r / m, g / m, b / m];
}

export function srgbToLinear(c: number): number {
  return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
}

export function linearToSrgb(c: number): number {
  const v = Math.min(Math.max(c, 0), 1);
  return v <= 0.0031308 ? v * 12.92 : 1.055 * v ** (1 / 2.4) - 0.055;
}

/** "#ff8844" → linear RGB. */
export function hex(h: string): RGB {
  const n = parseInt(h.replace('#', ''), 16);
  return [
    srgbToLinear(((n >> 16) & 255) / 255),
    srgbToLinear(((n >> 8) & 255) / 255),
    srgbToLinear((n & 255) / 255),
  ];
}

/** Linear RGB → CSS hex, for driving UI accent variables from the universe's temperature. */
export function toCss(c: RGB): string {
  const to = (v: number) =>
    Math.round(linearToSrgb(v) * 255)
      .toString(16)
      .padStart(2, '0');
  return `#${to(c[0])}${to(c[1])}${to(c[2])}`;
}

export function mix(a: RGB, b: RGB, t: number): RGB {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

export function scale(c: RGB, k: number): RGB {
  return [c[0] * k, c[1] * k, c[2] * k];
}

/** Relative luminance (linear). */
export function luma(c: RGB): number {
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
