<!--
  One phenomenon in the frame's list: name, level, cost. Hover or focus reveals what it does (the
  exact effect, now → next, and its line of physics). Click buys; Shift buys ten, Ctrl the most.
-->
<script lang="ts">
  import { energy, type NumParts } from '../../core/format';
  import type { PhenomenonDef } from '../../core/phenomena';
  import Num from '../common/Num.svelte';
  import { game, track, ui } from '../store.svelte';
  import { buyAmount, buyByClick, energyUnit, planBuy } from '../view';

  let { def, hotkey }: { def: PhenomenonDef; hotkey: number | null } = $props();
  const g = game();
  const id = $props.id();
  const born = performance.now();

  const v = $derived.by(() => {
    track();
    const lvl = g.level(def.id);
    const maxed = g.isMaxed(def.id);
    const p = planBuy(g, def, buyAmount(def, ui.ctrl, ui.shift));
    const text = def.effectText?.(lvl) ?? '';
    const preview = def.shows && !text && !maxed ? g.preview(def.id) : null;
    const now: NumParts | null = preview && def.shows ? def.shows.format(preview.now) : null;
    const next: NumParts | null = preview && def.shows ? def.shows.format(preview.next) : null;
    return {
      lvl,
      maxed,
      n: p.n,
      cost: energy(p.cost, energyUnit(g), g.state.settings.notation),
      can: !maxed && !g.inFinale && p.cost <= g.energy,
      text,
      now,
      next,
      fresh: performance.now() - born < 1200,
    };
  });

  const buy = (e: MouseEvent) => buyByClick(g, def, e);
</script>

{#snippet what()}
  <div class="reveal" id="{id}-what">
    <div>
      {#if v.text}
        <p class="effect">{v.text}</p>
      {:else if v.now && v.next && def.shows}
        <p class="effect">
          <Num parts={v.now} /><span class="to" aria-hidden="true"> → </span><span class="sr-only"> becomes </span><Num parts={v.next} />
          {def.shows.label}
        </p>
      {/if}
      <p class="physics faint">{def.physics}</p>
    </div>
  </div>
{/snippet}

{#if v.maxed}
  <!-- svelte-ignore a11y_no_noninteractive_tabindex (focusable so keyboard players can read what it does) -->
  <div class="row reveal-host known" tabindex="0" aria-label="{def.name}, {def.max === 1 ? 'known' : `level ${v.lvl}, the most there is`}" aria-describedby="{id}-what">
    <span class="key"></span>
    <span class="n">{def.name}</span>
    <span class="l">{def.max === 1 ? '' : v.lvl}</span>
    <span class="c">{def.max === 1 ? 'known' : 'max'}</span>
    {@render what()}
  </div>
{:else}
  <button
    class="row reveal-host"
    class:poor={!v.can}
    class:fresh={v.fresh}
    onclick={buy}
    aria-label="{def.name}{v.lvl ? `, level ${v.lvl}` : ''}"
    aria-describedby="{id}-cost {id}-what"
    aria-keyshortcuts={hotkey !== null ? String(hotkey) : undefined}
  >
    <span class="key" aria-hidden="true">{hotkey ?? ''}</span>
    <span class="n">{def.name}</span>
    <span class="l">{v.lvl || ''}</span>
    <span class="c" id="{id}-cost">
      <span class="sr-only">{v.can ? 'Costs' : 'Needs'}</span>
      {#if v.n > 1}<span class="times">×{v.n}</span>{/if}<Num parts={v.cost} />
    </span>
    {@render what()}
  </button>
{/if}

<style>
  .row {
    pointer-events: auto;
    display: grid;
    grid-template-columns: 1.1rem minmax(0, 1fr) 1.9rem auto;
    align-items: baseline;
    padding: 0.36rem 0;
    margin-left: -1.1rem;
    width: calc(100% + 1.1rem);
    cursor: pointer;
    color: #fff;
    transition: color var(--med) var(--ease);
  }
  .known {
    cursor: default;
  }
  .key {
    font-size: 0.72rem;
    color: rgb(255 255 255 / 0.3);
  }
  .n {
    font-size: 1rem;
    min-width: 0;
  }
  .l {
    font-size: 0.87rem;
    color: rgb(255 255 255 / 0.45);
    text-align: right;
  }
  .c {
    font-size: 1rem;
    text-align: right;
    padding-left: 0.9rem;
    white-space: nowrap;
  }
  .times {
    font-size: 0.8rem;
    margin-right: 0.3rem;
    color: rgb(255 255 255 / 0.5);
  }
  .row:hover .n,
  .row:focus-visible .n {
    text-decoration: underline;
    text-underline-offset: 4px;
    text-decoration-thickness: 1px;
  }
  .row:hover .key,
  .row:focus-visible .key {
    color: rgb(255 255 255 / 0.6);
  }
  .poor {
    color: rgb(255 255 255 / 0.42);
  }
  .known {
    color: rgb(255 255 255 / 0.6);
  }
  .known .c {
    font-size: 0.87rem;
    color: rgb(255 255 255 / 0.38);
  }
  .reveal {
    grid-column: 2 / -1;
  }
  /* Qualified, to outweigh the frame's reset of paragraph margins. */
  .reveal .effect {
    font-size: 0.87rem;
    color: rgb(255 255 255 / 0.72);
    margin-top: 0.2rem;
  }
  .reveal .physics {
    font-size: 0.8rem;
    line-height: 1.45;
    margin: 0.15rem 0 0.2rem;
  }
  .to {
    color: rgb(255 255 255 / 0.45);
  }
  .fresh {
    animation: arrive 1.2s var(--ease) both;
  }
  @keyframes arrive {
    from {
      opacity: 0;
      transform: translateX(calc(6px * var(--motion)));
    }
  }
</style>
