/**
 * The Afterglow simulation.
 *
 * Sound waves are rings with a Ricker profile (a crest flanked by troughs); their sum is the density
 * contrast δ anywhere. Light and matter are squeezed together, so the local temperature is T·(1 + δ/3).
 * A free electron near a nucleus is caught freely where the local temperature is below that nucleus's
 * recombination temperature, and now and then just above it; atoms in hot crests lose their electrons
 * again. Energy flows from crest crossings (compressed plasma flashing) and from captures. The running
 * integral of δ over time is the imprint: at First Light it becomes this universe's microwave
 * background and its peaks seed the next era.
 */
import type { EraModule, OfflineReport, PointerInfo, StockView } from '../../core/era';
import type { Game } from '../../core/game';
import { count, toText } from '../../core/format';
import { RateMeter } from '../../core/meter';
import { blackbody, type RGB } from '../../render/color';
import { Fx, FxPool } from '../../render/fx';
import type { Renderer } from '../../render/renderer';
import { Grid } from '../../physics/grid';
import { Particles } from '../../physics/particles';
import { MAX_WAVES, type AfterglowBgParams } from './background';
import { AfterglowLook } from './look';

const E = 0;
const HP = 1;
const H = 2;
const HE2 = 3;
const HE1 = 4;
const HE0 = 5;

/** Recombination temperature into each state (K) and energy released (eV). */
const T_CAPTURE: Record<number, number> = { [HP]: 3800, [HE2]: 16000, [HE1]: 6000 };
const BIND: Record<number, number> = { [HP]: 13.6, [HE2]: 54.4, [HE1]: 24.6 };
const NEXT: Record<number, number> = { [HP]: H, [HE2]: HE1, [HE1]: HE0 };
const PREV: Record<number, number> = { [H]: HP, [HE1]: HE2, [HE0]: HE1 };

/**
 * Recombination is not a switch. Just above a nucleus's recombination temperature a few electrons
 * still stay caught, everywhere, while the cool troughs catch them freely (the Saha balance).
 */
const SAHA_TAIL = 55;
/** Seconds without a pulse before an unplaced dark matter well settles on its own. */
const WELL_SETTLE = 6;

const WAVE_SPEED = 95;
const WAVE_WIDTH = 28;
/** Energy per second from one crossing of unit-amplitude crests, at weight 1 (eV). */
const E_CROSS = 380;
/** Unprompted pulses (the primordial ripples) ring at this share of a deliberate pulse. */
const AUTO_AMP = 0.9;
const GW = 96;
const GH = 54;

export interface AfterglowState {
  /** Real counts. */
  eFree: number;
  hp: number;
  h: number;
  he2: number;
  he1: number;
  he0: number;
  xe: number;
  wells: { x: number; y: number }[];
  everPulsed: boolean;
  everNode: boolean;
  captureRate: number;
  crossPower: number;
}

function defaults(): AfterglowState {
  return {
    eFree: 0,
    hp: 0,
    h: 0,
    he2: 0,
    he1: 0,
    he0: 0,
    xe: 1,
    wells: [],
    everPulsed: false,
    everNode: false,
    captureRate: 0,
    crossPower: 0,
  };
}

interface Wave {
  x: number;
  y: number;
  age: number;
  amp0: number;
}

interface Node {
  x: number;
  y: number;
  age: number;
}

/** Smoothstep on [0, 1], clamped. */
function smooth01(x: number): number {
  const t = Math.max(0, Math.min(1, x));
  return t * t * (3 - 2 * t);
}

/** Share of the full capture rate at a local temperature, for a nucleus that recombines below thr. */
export function captureShare(local: number, thr: number): number {
  return local <= thr ? 1 : Math.exp(-(local / thr - 1) * SAHA_TAIL);
}

function ricker(x: number): number {
  const x2 = x * x;
  return (1 - x2) * Math.exp(-0.5 * x2);
}

export class AfterglowEra implements EraModule {
  private readonly p = new Particles(700);
  private readonly grid = new Grid(40, 700);
  private readonly fx = new FxPool(700);
  private readonly s: AfterglowState;
  private readonly waveData = new Float32Array(MAX_WAVES * 4);
  private readonly bgParams: AfterglowBgParams;
  /** How it all looks (version 2): the glowing fog, the storm of specks, the point lights, the effects. */
  private readonly look: AfterglowLook;
  private readonly imprint = new Float32Array(GW * GH);
  private imprintVersion = 0;
  private imprintRow = 0;
  private waves: Wave[] = [];
  private nodes: Node[] = [];
  private crossings: { x: number; y: number; s: number }[] = [];
  private halfW = 889;
  private halfH = 500;
  private t = 0;
  private idle = 0;

  private amp = 0.34;
  private life = 6.5;
  private auto = 0;
  private crossMult = 1;
  private speed = 1;
  private wellsMax = 0;
  private heliumBonus = 1;
  private saha = 1;
  private resonance = 0;
  private lyman = 0.55;
  private captureMult = 1;

  private autoAcc = 0;
  private wellClock = 0;
  /** Seconds since the last pulse or the last well that settled by itself. */
  private quiet = 0;
  private nodeClock = 0;
  private crossSoundClock = 0;
  private hintClock = 0;
  private readonly captureMeter = new RateMeter(20);
  private intro = 0;
  private unsub: (() => void)[] = [];

  private finaleT = -1;
  private finaleDone: (() => void) | null = null;
  private tallied = false;
  private flared = false;

  constructor(private readonly g: Game) {
    const run = g.state.run;
    this.s = (run.eras.afterglow as AfterglowState | undefined) ?? defaults();
    run.eras.afterglow = this.s;
    this.bgParams = {
      temp: 3e4,
      visTemp: 3e4,
      fog: 1,
      reveal: 0,
      clear: 0,
      pulse: 0,
      waveWidth: WAVE_WIDTH,
      waves: this.waveData,
      waveCount: 0,
      rect: [-889, -500, 889, 500],
      impScale: 1,
    };
    this.look = new AfterglowLook(this.bgParams, {
      width: GW,
      height: GH,
      data: () => this.imprint,
      version: () => this.imprintVersion,
    });
  }

  // ───────────────────────────────────────── lifecycle

  enter(fresh: boolean): void {
    const g = this.g;
    if (g.renderer) this.look.attach(g.renderer);
    this.refreshStats();
    this.unsub.push(g.stats.onChange(() => this.refreshStats()));
    this.captureMeter.reset(this.s.captureRate);
    this.syncStepFlags();
    this.bgParams.temp = g.currentStep.T;
    this.bgParams.visTemp = this.bgParams.temp;
    // Helium share by number follows the helium mass fraction made in the first minutes.
    const yp = g.state.run.legacy.yp ?? 0.245;
    const heShare = yp / 4 / (yp / 4 + (1 - yp));
    if (fresh) {
      const w = this.weight;
      const nH = 150;
      const nHe = Math.max(4, Math.round((nH * heShare) / (1 - heShare)));
      for (let k = 0; k < nH; k++) this.spawnNucleus(HP);
      for (let k = 0; k < nHe; k++) this.spawnNucleus(HE2);
      for (let k = 0; k < Math.min(170, nH + 2 * nHe); k++) this.spawnElectron(null);
      this.s.hp = nH * w;
      this.s.he2 = nHe * w;
      this.s.eFree = (nH + 2 * nHe) * w;
      this.intro = 1.6;
    } else {
      this.resample();
    }
    this.updateXe();
  }

  exit(): void {
    if (this.g.renderer) this.look.detach(this.g.renderer);
    for (const u of this.unsub) u();
    this.unsub = [];
  }

  resize(halfW: number, halfH: number): void {
    this.halfW = halfW;
    this.halfH = halfH;
    this.grid.setBounds(-halfW - 100, -halfH - 100, halfW + 100, halfH + 100);
    this.bgParams.rect = [-halfW, -halfH, halfW, halfH];
  }

  private refreshStats(): void {
    const st = this.g.stats;
    this.amp = st.get('afterglow.amp') * (this.step >= 3 ? 1.3 : 1);
    this.life = st.get('afterglow.life');
    this.auto = st.get('afterglow.auto');
    this.crossMult = st.get('afterglow.crossMult');
    this.speed = st.get('afterglow.speed');
    this.wellsMax = st.get('afterglow.wells');
    this.heliumBonus = st.get('afterglow.heliumBonus');
    this.saha = st.get('afterglow.saha');
    this.resonance = st.get('afterglow.resonance');
    this.lyman = st.get('afterglow.lyman');
    this.captureMult = st.get('afterglow.captureMult');
  }

  private get step(): number {
    return this.g.state.run.step;
  }

  private get weight(): number {
    return 2e22 * 10 ** this.step;
  }

  /** The temperature below which a nucleus of this kind keeps an electron (K). */
  private threshold(kind: number): number {
    return T_CAPTURE[kind] * (kind === HP ? 1 : this.heliumBonus);
  }

  private syncStepFlags(): void {
    for (let i = 1; i <= 6; i++) this.g.setFlag(`afterglow.step${i}`, this.step >= i);
  }

  private resample(): void {
    const s = this.s;
    const total = s.hp + s.h + s.he2 + s.he1 + s.he0 || 1;
    const n = 165;
    const k = (v: number) => Math.round((v / total) * n);
    for (let j = 0; j < k(s.hp); j++) this.spawnNucleus(HP);
    for (let j = 0; j < k(s.h); j++) this.spawnNucleus(H);
    for (let j = 0; j < k(s.he2); j++) this.spawnNucleus(HE2);
    for (let j = 0; j < k(s.he1); j++) this.spawnNucleus(HE1);
    for (let j = 0; j < k(s.he0); j++) this.spawnNucleus(HE0);
    const free = Math.min(170, Math.round(s.xe * (k(s.hp) + k(s.h) + 2 * (k(s.he2) + k(s.he1) + k(s.he0)))));
    for (let j = 0; j < free; j++) this.spawnElectron(null);
  }

  private spawnNucleus(kind: number): number {
    const rng = this.g.sim;
    const i = this.p.spawn(
      kind,
      rng.range(-this.halfW + 30, this.halfW - 30),
      rng.range(-this.halfH + 30, this.halfH - 30),
      rng.range(-10, 10),
      rng.range(-10, 10),
      kind >= HE2 ? 9 : 7,
      1,
    );
    if (i >= 0) this.p.a[i] = rng.angle();
    return i;
  }

  private spawnElectron(at: { x: number; y: number } | null): number {
    const rng = this.g.sim;
    const x = at ? at.x : rng.range(-this.halfW, this.halfW);
    const y = at ? at.y : rng.range(-this.halfH, this.halfH);
    const a = rng.angle();
    return this.p.spawn(E, x, y, Math.cos(a) * 160, Math.sin(a) * 160, 3, 1);
  }

  // ───────────────────────────────────────── waves

  private pulse(x: number, y: number, amp: number): void {
    if (this.waves.length >= MAX_WAVES) {
      let weakest = 0;
      let wa = Infinity;
      this.waves.forEach((w, k) => {
        const a = w.amp0 * Math.exp(-w.age / this.life);
        if (a < wa) {
          wa = a;
          weakest = k;
        }
      });
      this.waves.splice(weakest, 1);
    }
    this.waves.push({ x, y, age: 0, amp0: amp });
  }

  /** δ at a point: the sum of every wave's ring profile. */
  private delta(x: number, y: number): number {
    let d = 0;
    for (const w of this.waves) {
      const r = Math.hypot(x - w.x, y - w.y);
      const a = w.amp0 * Math.exp(-w.age / this.life);
      d += a * ricker((r - w.age * WAVE_SPEED * this.speed) / WAVE_WIDTH);
    }
    return Math.max(-1.2, Math.min(1.2, d));
  }

  private updateWaves(dt: number): void {
    const maxR = Math.hypot(this.halfW, this.halfH) * 1.25;
    for (let k = this.waves.length - 1; k >= 0; k--) {
      const w = this.waves[k];
      w.age += dt;
      const a = w.amp0 * Math.exp(-w.age / this.life);
      if (a < 0.015 || w.age * WAVE_SPEED * this.speed > maxR) this.waves.splice(k, 1);
    }
    this.bgParams.waveCount = this.waves.length;
    this.waves.forEach((w, k) => {
      this.waveData[k * 4] = w.x;
      this.waveData[k * 4 + 1] = w.y;
      this.waveData[k * 4 + 2] = w.age * WAVE_SPEED * this.speed;
      this.waveData[k * 4 + 3] = w.amp0 * Math.exp(-w.age / this.life);
    });
  }

  /** Ring–ring intersections: where crests cross, compressed plasma flashes. Returns total strength. */
  private updateCrossings(): number {
    const out = this.crossings;
    out.length = 0;
    let power = 0;
    const ws = this.waves;
    for (let i = 0; i < ws.length; i++) {
      const a = ws[i];
      const ra = a.age * WAVE_SPEED * this.speed;
      const aa = a.amp0 * Math.exp(-a.age / this.life);
      for (let j = i + 1; j < ws.length; j++) {
        const b = ws[j];
        const rb = b.age * WAVE_SPEED * this.speed;
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const d = Math.hypot(dx, dy);
        if (d < 1 || d > ra + rb || d < Math.abs(ra - rb)) continue;
        const ab = b.amp0 * Math.exp(-b.age / this.life);
        const s = aa * ab;
        power += s;
        const l = (ra * ra - rb * rb + d * d) / (2 * d);
        const h = Math.sqrt(Math.max(0, ra * ra - l * l));
        const mx = a.x + (dx * l) / d;
        const my = a.y + (dy * l) / d;
        out.push({ x: mx + (dy * h) / d, y: my - (dx * h) / d, s });
        out.push({ x: mx - (dy * h) / d, y: my + (dx * h) / d, s });
      }
    }
    return power;
  }

  /** Dark matter clumps whether or not anyone pulses: a free well settles somewhere open. */
  private settleWell(): void {
    const rng = this.g.sim;
    this.quiet = 0;
    let best = { x: 0, y: 0 };
    let room = -1;
    for (let k = 0; k < 12; k++) {
      const x = rng.range(-this.halfW * 0.8, this.halfW * 0.8);
      const y = rng.range(-this.halfH * 0.75, this.halfH * 0.75);
      const d = Math.min(Infinity, ...this.s.wells.map((w) => Math.hypot(w.x - x, w.y - y)));
      if (d > room) {
        room = d;
        best = { x, y };
      }
    }
    this.s.wells.push(best);
    this.pulse(best.x, best.y, this.amp * 0.75);
    this.fx.spawn(Fx.Flash, best.x, best.y, 0.6, 50, 0.9, 0.55, 1.6, 60);
    this.g.renderer?.shock(best.x, best.y, 0.12, 0.6, 1);
    this.g.sfx('afterglow.pulse', best.x);
    this.g.toast('Dark matter clumped here on its own. It will keep ringing.', 'quiet');
  }

  private findResonance(): void {
    if (this.nodes.length >= 2) return;
    for (const c of this.crossings) {
      if (c.s < 0.02 || Math.abs(c.x) > this.halfW - 60 || Math.abs(c.y) > this.halfH - 60) continue;
      let hits = 0;
      for (const w of this.waves) {
        const r = Math.hypot(c.x - w.x, c.y - w.y);
        if (Math.abs(r - w.age * WAVE_SPEED * this.speed) < 9) hits++;
      }
      if (hits >= 3 && !this.nodes.some((n) => Math.hypot(n.x - c.x, n.y - c.y) < 160)) {
        this.nodes.push({ x: c.x, y: c.y, age: 0 });
        this.g.sfx('afterglow.node', c.x);
        return;
      }
    }
  }

  private updateImprint(): void {
    // A few rows per frame: the whole grid refreshes about ten times a second.
    const rows = 6;
    if (this.imprintRow === 0) {
      let sq = 0;
      for (const v of this.imprint) sq += v * v;
      const std = Math.sqrt(sq / this.imprint.length);
      this.bgParams.impScale = 1 / Math.max(0.05, std);
    }
    const sx = (2 * this.halfW) / GW;
    const sy = (2 * this.halfH) / GH;
    for (let k = 0; k < rows; k++) {
      const row = this.imprintRow;
      this.imprintRow = (this.imprintRow + 1) % GH;
      const y = -this.halfH + (row + 0.5) * sy;
      for (let col = 0; col < GW; col++) {
        const x = -this.halfW + (col + 0.5) * sx;
        const idx = row * GW + col;
        const v = this.imprint[idx] + this.delta(x, y) * 0.09;
        this.imprint[idx] = Math.max(-3, Math.min(3, v * 0.9995));
      }
    }
    this.imprintVersion++;
  }

  // ───────────────────────────────────────── captures

  private capture(e: number, n: number): void {
    const p = this.p;
    const g = this.g;
    const s = this.s;
    const w = this.weight;
    const kind = p.kind[n];
    const next = NEXT[kind];
    p.kill(e);
    p.kind[n] = next;
    s.eFree = Math.max(0, s.eFree - w);
    if (kind === HP) {
      s.hp -= w;
      s.h += w;
    } else if (kind === HE2) {
      s.he2 -= w;
      s.he1 += w;
    } else {
      s.he1 -= w;
      s.he0 += w;
    }
    const gain = BIND[kind] * w * this.captureMult;
    g.gain(gain);
    this.captureMeter.add(w);
    const x = p.x[n];
    const y = p.y[n];
    const tint = blackbody(Math.max(2000, this.bgParams.temp * 1.4));
    this.fx.spawn(Fx.Flash, x, y, 0.35, 16, tint[0] * 2, tint[1] * 2, tint[2] * 2, 20);
    const a = g.fx.angle();
    this.fx.spawn(Fx.Spark, x, y, 0.35, 3, 2.4, 2.4, 2.6, 0, Math.cos(a) * 700, Math.sin(a) * 700);
    g.sfx('afterglow.capture', x, 1, kind === HP ? 0 : 1);
    g.discover(kind === HP ? 'hydrogen-atom' : kind === HE2 ? 'helium-ion' : 'helium-atom');
    // Now and then a free electron sticks to a neutral hydrogen atom instead: H⁻.
    if (kind === HP && this.s.h > 0 && g.sim.chance(0.03)) g.discover('hydride');
    // The photon from settling into the ground state can knock a neighbor's electron loose.
    if (kind === HP && g.sim.chance(this.lyman)) {
      let target = -1;
      this.grid.near(x, y, 80, (j) => {
        if (target < 0 && j !== n && p.kind[j] === H && !p.isDead(j)) target = j;
      });
      if (target >= 0) this.ionize(target, false);
    }
  }

  private ionize(n: number, sound = true): void {
    const p = this.p;
    const s = this.s;
    const w = this.weight;
    const kind = p.kind[n];
    const prev = PREV[kind];
    if (prev === undefined) return;
    p.kind[n] = prev;
    s.eFree += w;
    if (kind === H) {
      s.h -= w;
      s.hp += w;
    } else if (kind === HE1) {
      s.he1 -= w;
      s.he2 += w;
    } else {
      s.he0 -= w;
      s.he1 += w;
    }
    this.spawnElectron({ x: p.x[n], y: p.y[n] });
    this.fx.spawn(Fx.Ring, p.x[n], p.y[n], 0.25, 4, 0.8, 0.9, 1.2, 70);
    if (sound) this.g.sfx('afterglow.ionize', p.x[n]);
  }

  private updateXe(): void {
    const s = this.s;
    const total = s.hp + s.h + 2 * (s.he2 + s.he1 + s.he0);
    s.xe = total > 0 ? Math.max(0, Math.min(1, s.eFree / total)) : 1;
  }

  // ───────────────────────────────────────── simulation

  update(dt: number): void {
    const g = this.g;
    const p = this.p;
    const rng = g.sim;
    this.t += dt;
    this.idle += dt;
    this.hintClock += dt;
    if (this.intro > 0) this.intro = Math.max(0, this.intro - dt);
    const inFinale = this.finaleT >= 0;
    const T = this.bgParams.temp;

    if (!inFinale) {
      this.autoAcc += this.auto * dt;
      while (this.autoAcc >= 1) {
        this.autoAcc -= 1;
        this.pulse(rng.range(-this.halfW * 0.9, this.halfW * 0.9), rng.range(-this.halfH * 0.9, this.halfH * 0.9), this.amp * AUTO_AMP);
      }
      this.quiet += dt;
      if (this.quiet >= WELL_SETTLE && this.s.wells.length < this.wellsMax) this.settleWell();
      this.wellClock += dt;
      if (this.wellClock >= 5 && this.s.wells.length) {
        this.wellClock = 0;
        for (const w of this.s.wells) this.pulse(w.x, w.y, this.amp * 0.75);
      }
    } else this.updateFinale(dt);

    this.updateWaves(dt);
    const power = this.updateCrossings();
    this.s.crossPower = power;
    if (!inFinale && power > 0) {
      // Sub-linear in total crossing strength: more waves always pay more, without running away.
      g.gain(Math.pow(power, 0.85) * E_CROSS * this.weight * this.crossMult * dt);
      this.crossSoundClock -= dt;
      if (this.crossSoundClock <= 0 && this.crossings.length) {
        this.crossSoundClock = 0.35;
        const c = this.crossings[rng.int(this.crossings.length)];
        g.sfx('afterglow.cross', c.x, Math.min(1, power * 3));
      }
    }
    if (this.resonance > 0 && !inFinale) {
      this.nodeClock -= dt;
      if (this.nodeClock <= 0) {
        this.nodeClock = 0.3;
        this.findResonance();
      }
    }
    for (let k = this.nodes.length - 1; k >= 0; k--) {
      this.nodes[k].age += dt;
      if (this.nodes[k].age > 3.6) this.nodes.splice(k, 1);
    }
    this.updateImprint();

    // Motion: electrons random-walk fast; nuclei and atoms drift and are rocked by passing waves.
    this.grid.build(p);
    const sq = Math.sqrt(dt);
    const wx = this.halfW - 14;
    const wy = this.halfH - 14;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const kind = p.kind[i];
      if (kind === E) {
        p.vx[i] = (p.vx[i] + rng.gauss() * 420 * sq) * Math.exp(-2.6 * dt);
        p.vy[i] = (p.vy[i] + rng.gauss() * 420 * sq) * Math.exp(-2.6 * dt);
      } else {
        let ax = rng.gauss() * 8;
        let ay = rng.gauss() * 8;
        for (const w of this.waves) {
          const dx = p.x[i] - w.x;
          const dy = p.y[i] - w.y;
          const r = Math.hypot(dx, dy) || 1;
          const x = (r - w.age * WAVE_SPEED * this.speed) / WAVE_WIDTH;
          const f = w.amp0 * Math.exp(-w.age / this.life) * x * Math.exp(-0.5 * x * x) * -70;
          ax += (dx / r) * f;
          ay += (dy / r) * f;
        }
        p.vx[i] = (p.vx[i] + ax * dt) * Math.exp(-1.8 * dt);
        p.vy[i] = (p.vy[i] + ay * dt) * Math.exp(-1.8 * dt);
      }
      if (p.x[i] > wx) p.vx[i] -= (p.x[i] - wx) * 30 * dt;
      else if (p.x[i] < -wx) p.vx[i] -= (p.x[i] + wx) * 30 * dt;
      if (p.y[i] > wy) p.vy[i] -= (p.y[i] - wy) * 30 * dt;
      else if (p.y[i] < -wy) p.vy[i] -= (p.y[i] + wy) * 30 * dt;
      p.x[i] += p.vx[i] * dt;
      p.y[i] += p.vy[i] * dt;
      p.age[i] += dt;
      p.a[i] += dt * 1.4;
    }

    if (!inFinale) {
      // Local temperature at every nucleus, then captures and crest re-ionization.
      for (let n = 0; n < p.n; n++) {
        if (p.isDead(n) || p.kind[n] === E) continue;
        const local = T * (1 + this.delta(p.x[n], p.y[n]) / 3);
        p.b[n] = local;
        const kind = p.kind[n];
        const prev = PREV[kind];
        if (prev !== undefined && local > this.threshold(prev) * 1.2 && rng.chance(0.9 * dt)) this.ionize(n);
      }
      for (let i = 0; i < p.n; i++) {
        if (p.isDead(i) || p.kind[i] !== E) continue;
        let best = -1;
        let bd = 30 * 30;
        this.grid.near(p.x[i], p.y[i], 30, (j) => {
          const k = p.kind[j];
          if (k !== HP && k !== HE2 && k !== HE1) return;
          if (p.isDead(j)) return;
          const d = (p.x[j] - p.x[i]) ** 2 + (p.y[j] - p.y[i]) ** 2;
          if (d < bd) {
            bd = d;
            best = j;
          }
        });
        if (best < 0) continue;
        if (rng.chance(2.2 * this.saha * dt * captureShare(p.b[best], this.threshold(p.kind[best])))) this.capture(i, best);
      }
    }

    p.compact();
    this.fx.update(dt);
    this.captureMeter.tick(dt);
    this.s.captureRate = this.captureMeter.rate;
    this.updateXe();
    // Visual only. During First Light the fog keeps its last thickness and the clearing front removes it.
    const bg = this.bgParams;
    if (!inFinale) bg.fog += (this.s.xe - bg.fog) * Math.min(1, dt * 1.5);
    bg.pulse *= Math.exp(-dt * 2);
    // The palette eases between steps in log temperature: a breath, not a cut.
    const lt = Math.log(bg.visTemp);
    bg.visTemp = Math.exp(lt + (Math.log(bg.temp) - lt) * Math.min(1, dt * 1.3));
  }

  // ───────────────────────────────────────── steps

  onStep(index: number): void {
    const g = this.g;
    const s = this.s;
    for (const k of ['eFree', 'hp', 'h', 'he2', 'he1', 'he0'] as const) s[k] *= 10;
    this.syncStepFlags();
    this.refreshStats();
    this.bgParams.temp = g.steps()[index].T;
    this.bgParams.pulse = Math.min(1, this.bgParams.pulse + 0.35);
    g.renderer?.camera.breathe(0.05, 1.5);
    this.hintClock = 0;
    if (index === 2 || index === 4 || index === 5) g.sfx('afterglow.milestone');
    if (index === 3) {
      g.sfx('afterglow.milestone');
      g.renderer?.shock(0, 0, 0.6, 0.5, 2.4);
    }
  }

  // ───────────────────────────────────────── finale: First Light

  finale(): Promise<void> {
    const g = this.g;
    const run = g.state.run;
    run.legacy.recombination = 1 - this.s.xe;
    run.legacy.acoustic = this.amp;
    run.artifacts.cmb = this.encodeMap();
    run.artifacts.peaks = this.findPeaks();
    this.finaleT = 0;
    this.nodes = [];
    g.sfx('afterglow.firstlight');
    g.discover('cmb');
    g.discover('bao');
    return new Promise((resolve) => {
      this.finaleDone = resolve;
    });
  }

  private updateFinale(dt: number): void {
    const g = this.g;
    const p = this.p;
    this.finaleT += dt;
    const t = this.finaleT;
    const bg = this.bgParams;
    bg.reveal = smooth01((t - 1) / 2.5);
    // The last scattering surface flares as every electron is caught, then a clearing front sweeps out.
    const flare = t < 1.1 ? 0.55 * smooth01(t / 1.1) : 0.55 * Math.exp(-(t - 1.1) * 1.6);
    bg.pulse = Math.max(bg.pulse, flare);
    bg.clear = 1 - Math.pow(1 - Math.min(1, Math.max(0, (t - 1.0) / 2.8)), 2.2);
    if (t >= 1.0 && !this.flared) {
      this.flared = true;
      g.renderer?.addFlash(0.3);
      g.renderer?.shock(0, 0, 0.5, 0.75, 2.6);
    }
    // Every remaining electron finds a nucleus.
    if (t < 2.5) {
      for (let i = 0; i < p.n; i++) {
        if (p.isDead(i) || p.kind[i] !== E || !g.fx.chance(dt * 1.6)) continue;
        let best = -1;
        let bd = Infinity;
        for (let j = 0; j < p.n; j++) {
          const k = p.kind[j];
          if (p.isDead(j) || (k !== HP && k !== HE2 && k !== HE1)) continue;
          const d = (p.x[j] - p.x[i]) ** 2 + (p.y[j] - p.y[i]) ** 2;
          if (d < bd) {
            bd = d;
            best = j;
          }
        }
        if (best >= 0) this.capture(i, best);
        else p.kill(i);
      }
    }
    // Light streams free: photons leave the clearing front and fly outward, unscattered at last.
    if (t > 1.0 && t < 4.6) {
      const n = Math.min(6, Math.floor(dt * 90 + (g.fx.chance((dt * 90) % 1) ? 1 : 0)));
      const R = (bg.clear * 2.6 - 0.15) * this.halfH;
      for (let k = 0; k < n; k++) {
        const a = g.fx.angle();
        const rr = Math.max(20, R + g.fx.range(-40, 30));
        const x = Math.cos(a) * rr;
        const y = Math.sin(a) * rr;
        if (Math.abs(x) > this.halfW + 40 || Math.abs(y) > this.halfH + 40) continue;
        const sp = g.fx.range(620, 900);
        const hot = g.fx.chance(0.3);
        this.fx.spawn(Fx.Spark, x, y, 1.1, hot ? 2.6 : 2, hot ? 3.2 : 2.6, hot ? 2.6 : 1.5, hot ? 2.0 : 0.6, 0, Math.cos(a) * sp, Math.sin(a) * sp);
      }
    }
    if (t >= 4 && !this.tallied) {
      this.tallied = true;
      g.toast(
        'First Light. The universe is transparent. This light is still traveling: in our universe it arrives as microwaves at 2.7 K.',
        'milestone',
      );
    }
    if (t >= 8.5 && this.finaleDone) {
      const done = this.finaleDone;
      this.finaleDone = null;
      done();
    }
  }

  /** The imprint, downsampled to 48×27 and quantized to a compact base64 string. */
  private encodeMap(): string {
    const W = 48;
    const Hh = 27;
    const bytes = new Uint8Array(W * Hh);
    let max = 1e-6;
    for (const v of this.imprint) max = Math.max(max, Math.abs(v));
    for (let y = 0; y < Hh; y++) {
      for (let x = 0; x < W; x++) {
        let sum = 0;
        for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 2; dx++) sum += this.imprint[(y * 2 + dy) * GW + x * 2 + dx];
        const v = sum / 4 / max;
        bytes[y * W + x] = Math.round((v * 0.5 + 0.5) * 255);
      }
    }
    let bin = '';
    for (const b of bytes) bin += String.fromCharCode(b);
    return `48x27:${btoa(bin)}`;
  }

  /** The strongest local maxima of the imprint, in normalised coordinates: "x,y,s;…". */
  private findPeaks(): string {
    const peaks: { x: number; y: number; v: number }[] = [];
    for (let y = 1; y < GH - 1; y++) {
      for (let x = 1; x < GW - 1; x++) {
        const v = this.imprint[y * GW + x];
        if (v <= 0.05) continue;
        let isMax = true;
        for (let dy = -1; dy <= 1 && isMax; dy++)
          for (let dx = -1; dx <= 1; dx++) if ((dx || dy) && this.imprint[(y + dy) * GW + x + dx] > v) isMax = false;
        if (isMax) peaks.push({ x: (x + 0.5) / GW * 2 - 1, y: (y + 0.5) / GH * 2 - 1, v });
      }
    }
    peaks.sort((a, b) => b.v - a.v);
    const top = peaks.slice(0, 14);
    const max = top[0]?.v ?? 1;
    return top.map((pk) => `${pk.x.toFixed(3)},${pk.y.toFixed(3)},${(pk.v / max).toFixed(3)}`).join(';');
  }

  // ───────────────────────────────────────── rendering

  render(r: Renderer): void {
    const p = this.p;
    const bg = this.bgParams;
    const look = this.look;
    look.begin(r);
    // The era opens in a flash of the bath's own light, settling as the fog takes shape.
    const intro = this.intro > 0 ? (this.intro / 1.6) ** 2 : 0;
    const hot = blackbody(Math.min(bg.visTemp * 1.8, 2.5e4));
    const warmth = Math.max(0, Math.min(1, (9000 - bg.visTemp) / 5000));
    look.medium(bg.fog, bg.reveal, 3 * intro, blackbody(Math.min(bg.visTemp * 1.4, 2.5e4)), this.amp, warmth);
    // The crests carry the specks with them.
    for (const w of this.waves) look.wave(w.x, w.y, w.age * WAVE_SPEED * this.speed, w.amp0 * Math.exp(-w.age / this.life));
    // Everything material steps aside quickly at First Light so the map is the only subject.
    const fade = 1 - Math.min(1, bg.reveal * 2.4);
    // Seen through the fog: the thicker it is, the dimmer what sits in it.
    const veil = 0.62 + 0.38 * (1 - bg.fog);
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const ap = Math.min(1, p.age[i] * 3) * fade;
      if (ap <= 0.002) continue;
      const x = p.x[i];
      const y = p.y[i];
      // A stable pseudo-depth per particle, so some sit a little deeper in the fog than others.
      const depth = (Math.imul(p.id[i], 2654435761) >>> 0) / 4294967296;
      switch (p.kind[i]) {
        case E:
          look.electron(x, y, p.vx[i], p.vy[i], ap * veil, depth);
          break;
        case HP:
          look.nucleus(x, y, false, ap * veil, depth);
          break;
        case HE2:
          look.nucleus(x, y, true, ap * veil, depth);
          break;
        case H:
          look.atom(x, y, false, 1, p.a[i] + i, ap, depth);
          break;
        case HE1:
          look.atom(x, y, true, 1, p.a[i] + i, ap, depth);
          break;
        case HE0:
          look.atom(x, y, true, 2, p.a[i] + i, ap, depth);
          break;
      }
    }

    // Where crests cross, squeezed plasma flares in the fog, tinted hotter than the bath.
    const list = this.crossings;
    const shown = Math.min(list.length, 48);
    for (let k = 0; k < shown; k++) {
      const c = list[k];
      look.crossing(c.x, c.y, Math.min(1, c.s * 7) * (0.55 + 0.45 * bg.fog) * fade, hot);
    }

    // Dark matter wells: an unseen tug, felt as a slow violet heartbeat.
    for (const w of this.s.wells) {
      const beat = 0.6 + 0.4 * Math.pow(0.5 + 0.5 * Math.sin(this.t * 1.26 + w.x), 2);
      look.well(w.x, w.y, beat, fade);
    }

    // Resonance nodes: a bloom of light with fronts drawing in, asking to be clicked.
    for (const n of this.nodes) {
      const a = Math.min(1, n.age * 3) * Math.min(1, (3.6 - n.age) / 0.8);
      look.node(n.x, n.y, a, n.age, hot);
    }

    this.fx.render(r, look);
    look.end();
  }

  // ───────────────────────────────────────── input

  pointer(e: PointerInfo): void {
    if (!e.primary || e.type !== 'down' || this.finaleT >= 0) return;
    this.idle = 0;
    this.quiet = 0;
    for (let k = 0; k < this.nodes.length; k++) {
      const n = this.nodes[k];
      if (Math.hypot(n.x - e.x, n.y - e.y) < 60) {
        this.nodes.splice(k, 1);
        this.s.everNode = true;
        const gain = Math.max(this.s.crossPower, 0.3) * E_CROSS * this.weight * this.crossMult * 30;
        this.g.gain(gain, n.x, n.y);
        this.pulse(n.x, n.y, this.amp * 1.4);
        this.fx.spawn(Fx.Flash, n.x, n.y, 0.5, 70, 3, 2.8, 2.6, 100);
        this.g.renderer?.shock(n.x, n.y, 0.5, 0.8, 1.1);
        this.g.sfx('afterglow.node.catch', n.x);
        return;
      }
    }
    this.s.everPulsed = true;
    this.pulse(e.x, e.y, this.amp);
    if (this.s.wells.length < this.wellsMax) {
      this.s.wells.push({ x: e.x, y: e.y });
      this.g.toast('A dark matter well. It will keep ringing here.', 'quiet');
    }
    // The thump: a hot compression flash, a quick bright front, and a refractive ripple through the fog.
    const c = blackbody(Math.min(this.bgParams.visTemp * 1.6, 2.5e4));
    this.fx.spawn(Fx.Flash, e.x, e.y, 0.32, 18, c[0] * 3, c[1] * 3, c[2] * 3, 90);
    this.fx.spawn(Fx.Ring, e.x, e.y, 0.55, 8, c[0] * 1.6, c[1] * 1.6, c[2] * 1.6, WAVE_SPEED * this.speed * 1.9);
    this.fx.spawn(Fx.Puff, e.x, e.y, 0.9, 40, c[0] * 0.35, c[1] * 0.35, c[2] * 0.35, 60);
    this.g.renderer?.shock(e.x, e.y, 0.14, 0.5, 0.9);
    this.g.sfx('afterglow.pulse', e.x);
  }

  // ───────────────────────────────────────── HUD

  stocks(): StockView[] {
    const s = this.s;
    return [
      {
        id: 'xe',
        label: 'Free electrons',
        value: s.xe,
        format: 'percent',
        hint: 'The share of electrons not yet bound into atoms. While most are free, light cannot travel.',
      },
      {
        id: 'atoms',
        label: 'Neutral atoms',
        value: Math.max(0, s.h + s.he0),
        format: 'count',
        rate: this.captureMeter.rate,
        hint: 'Hydrogen and helium that have caught their electrons.',
      },
    ];
  }

  dotScale(): { value: number; unit: string } | null {
    return { value: this.weight, unit: 'atoms' };
  }

  offline(seconds: number): OfflineReport {
    const s = this.s;
    const T = this.g.currentStep.T;
    let left = Math.min(s.eFree * 0.9, this.captureMeter.rate * seconds);
    let caught = 0;
    // Only what the bath itself lets recombine at this temperature does: helium first, hydrogen once cool enough.
    const settle = (kind: number, from: 'he2' | 'he1' | 'hp', to: 'he1' | 'he0' | 'h') => {
      if (captureShare(T, this.threshold(kind)) < 0.01) return;
      const n = Math.min(s[from], left);
      s[from] -= n;
      s[to] += n;
      s.eFree -= n;
      left -= n;
      caught += n;
    };
    settle(HE2, 'he2', 'he1');
    settle(HE1, 'he1', 'he0');
    settle(HP, 'hp', 'h');
    if (caught > 0) this.updateXe();
    return { lines: caught > 0 ? [{ label: 'Electrons caught', value: toText(count(caught)) }] : [] };
  }

  accent(): RGB {
    const c = blackbody(Math.min(this.bgParams.temp, 2e4));
    return [0.55 + 0.45 * c[0], 0.55 + 0.45 * c[1], 0.55 + 0.45 * c[2]];
  }

  hint(): string | null {
    if (this.finaleT >= 0) return null;
    if (!this.s.everPulsed && this.idle > 2) return 'Click to send a sound wave through the plasma.';
    if (this.nodes.length && !this.s.everNode) return 'Three waves meet here. Click the bright spot for a burst.';
    if (this.waves.length >= 2 && this.crossings.length === 0 && this.hintClock < 12 && this.step === 0)
      return 'Where waves cross, the plasma is squeezed and flashes. Send waves that cross.';
    if (this.step === 2 && this.hintClock < 9) return 'Helium can hold an electron now, but only where the plasma is cool: the dark gaps between waves. Send waves to open more.';
    if (this.step === 5 && this.hintClock < 9) return 'Hydrogen can form now, in the dark gaps between waves. Send more waves to open more gaps.';
    return null;
  }
}
