import { FORGE_CODEX } from './codex';
import { ELEMENT_GOAL, ForgeEra, type ForgeState } from './sim';
import { imfShareAbove } from './stars';

const fNum = (v: number): NumParts => decimal(v, 3);
const fMult = (v: number): NumParts => {
  const d = decimal(v, 3);
  return { ...d, m: '×' + d.m };
};
const fPct = (v: number): NumParts => percent(v, 3);

const J = 6.241509074e18;
const YEAR = 3.15576e7;
/** Overall price level of the era relative to its yields; tuned with tools/balance. */
const PRICE = 11;
const ZJ = 1e21 * J;

const made = (g: Game): number[] => (g.state.run.eras.forge as ForgeState | undefined)?.made ?? [];
const toward = (g: Game): number => g.energy / Math.max(1, g.nextStep?.cost ?? Infinity);
const goal = (text: string, detail: string) => (g: Game): StepGoal => ({ text, detail, progress: toward(g) });
/** What a rocky planet needs around the Sun: carbon, oxygen, silicon, iron. */
