/**
 * The audio director listens to the game and decides what it sounds like. Simulation code only
 * emits named cues ("soup.annihilate"); each era supplies its bed, key and cue implementations.
 * An era with rendered sound (version 2, `sound`) gets a bed of stems that follows how busy the
 * player is and effects played from files; the others are synthesized as before. An era whose
 * rendered files cannot all play (absent from the build, or failed) plays its synthesized sound
 * instead: a missing file never means silence.
 *
 * The era a session opens in decodes its files before the first gesture. Cues of a rendered era that
 * come before that gesture (a finale replayed after a reload) are kept and played on it, late: music
 * catches up to where it would be, effects too late to belong to anything are let go.
 */
import SOUND_FILES from 'virtual:ylem-sound-files';
import type { Game } from '../core/game';
import type { EraId } from '../core/state';
import { Bed, type BedSpec } from './bed';
import { AudioEngine } from './engine';
import { EFFECT_LATE, fadeOutVoice, playBuffer, type PlayOptions, SampleBank, type SampleVoice, startVoice, StemBed, voiceFor } from './samples';
import { bell, noise, pluck } from './patches';
import { SCALES, mtof, note, type Key } from './scales';

export interface CueParams {
  x?: number;
  intensity?: number;
  pitch?: number;
}

export interface CueContext {
  /** World x → stereo pan (−0.8 … 0.8). */
  pan(x?: number): number;
  key: Key;
}

export type CueFn = (a: AudioEngine, p: CueParams, c: CueContext) => void;

export interface EraAudio {
  bed: BedSpec;
  key: Key;
  cues: Record<string, CueFn>;
  /** Rendered sound (version 2): when present it replaces the synthesized bed and cues. */
  sound?: EraSound;
}

/** What a rendered cue can do. */
export interface SoundApi {
  /**
   * Plays a file, panned from world x if given. One not decoded yet starts when it is: music where it
   * would have reached by then, an effect from its start if only a moment late (not at all after that).
   */
  play(name: string, o?: PlayOptions & { x?: number }): SampleVoice | null;
  /** Whether a file has decoded and would play at once; one that has not is asked for (it will be next time). */
  ready(name: string): boolean;
  stop(v: SampleVoice | null, fade?: number): void;
  /** Rate-limited, density-aware gain for a frequent cue (0: skip it). */
  admit(id: string, minInterval: number): number;
  /** Seconds into the bed's loop: where its harmony is. */
  position(): number;
  /** Counts calls per name (purchases climb a scale). */
  next(counter: string): number;
  /** Ducks or restores the bed. */
  duck(level: number, seconds?: number): void;
  /** Ends the bed (a transition takes over) and holds the next era's bed for `hold` seconds. */
  handover(fade: number, hold: number): void;
}

export type SoundCue = (s: SoundApi, p: CueParams) => void;

export interface EraSound {
  /**
   * Looping stems played together; `layers` gives each stem's level for an activity of 0–1, and
   * `busy` how many events a second read as fully busy (default 4).
   */
  stems?: { id: string; names: string[]; loop: number; layers: (activity: number) => number[]; busy?: number };
  /**
   * Files it plays often, or must play on time (a finale timed to the picture): decoded when the era
   * starts. Every file a cue can play is listed here or in `lazy`: the lists are what a build ships.
   */
  load: string[];
  /**
   * Effects it plays rarely: fetched when the era starts, decoded when first asked for (they start a
   * few tens of milliseconds late) and let go again a while after they have played.
   */
  lazy?: string[];
  /**
   * Effects a second (the interface's aside) above which a flurry thins: each plays softer, so their
   * summed power holds at that rate's instead of piling up. Unset: no limit.
   */
  crowd?: number;
  cues: Record<string, SoundCue>;
}

/** Seconds the crowd's rate is measured over. */
const CROWD_SECONDS = 1.5;

/**
 * Interface sounds for eras with rendered sound, with the files each plays (an era that replaces one
 * needs none of its files). An optional one may be absent: it then falls back, quietly, to the
 * synthesized cue.
 */
const SOUND_UI: Record<string, { files: readonly string[]; lazy?: boolean; optional?: boolean; cue: SoundCue }> = {
  'ui.buy': {
    files: Array.from({ length: 8 }, (_, k) => `sfx-buy-${k}`),
    cue: (s) => {
      const g = s.admit('ui.buy', 0.05);
      if (g) s.play(`sfx-buy-${s.next('buy') % 8}`, { gain: 0.9 * g });
    },
  },
  // A step's introduction is music, heard over the effects (which duck under it).
  'ui.step': { files: ['sfx-step'], lazy: true, cue: (s) => s.play('sfx-step', { gain: 0.9, bus: 'music' }) },
  'ui.discover': {
    files: ['sfx-discover'],
    lazy: true,
    cue: (s) => {
      if (s.admit('ui.discover', 0.3)) s.play('sfx-discover', { gain: 0.8 });
    },
  },
  'ui.open': {
    files: ['sfx-combo-0'],
    cue: (s) => {
      const g = s.admit('ui.open', 0.08);
      if (g) s.play('sfx-combo-0', { gain: 0.35 * g });
    },
  },
  // A soft, muted dead stroke: the purchase cannot happen.
  'ui.deny': {
    files: ['sfx-deny'],
    optional: true,
    cue: (s) => {
      const g = s.admit('ui.deny', 0.12);
      if (g) s.play('sfx-deny', { gain: 0.9 * g });
    },
  },
};

/**
 * Every file an era with rendered sound can request, by how it is held: `eager` decoded when the era
 * starts, `lazy` when first played, `optional` (also decoded at the start) allowed to be absent. The
 * one place that says what a build must ship (src/audio/manifest.ts, checked by vite.config.ts).
 */
export function soundFiles(sound: EraSound): { eager: string[]; lazy: string[]; optional: string[] } {
  const ui = Object.entries(SOUND_UI).filter(([id]) => !sound.cues[id]);
  const of = (pick: (u: (typeof SOUND_UI)[string]) => boolean | undefined) => ui.filter(([, u]) => pick(u)).flatMap(([, u]) => u.files);
  const lazy = new Set([...(sound.lazy ?? []), ...of((u) => u.lazy && !u.optional)]);
  const eager = new Set([...(sound.stems?.names ?? []), ...sound.load, ...of((u) => !u.lazy && !u.optional)]);
  for (const n of eager) lazy.delete(n);
  return { eager: [...eager], lazy: [...lazy], optional: of((u) => u.optional).filter((n) => !eager.has(n) && !lazy.has(n)) };
}

/** Every cue an era with rendered sound answers: its own, and the shared interface ones it does not replace. */
export function renderedCues(sound: EraSound): Record<string, SoundCue> {
  return { ...Object.fromEntries(Object.entries(SOUND_UI).map(([id, u]) => [id, u.cue])), ...sound.cues };
}

/** Cues kept from before the first gesture: the latest of each, from the last two minutes. */
const DEFERRED_MAX = 64;
const DEFERRED_SECONDS = 120;

const DEFAULT_KEY: Key = { root: 60, scale: SCALES.majorPentatonic };

/** Seconds an era's bed takes to hand over to the next (the old one fades out while the new one fades in). */
export const BED_FADE = 5;

/** Interface sounds shared by every era. Quiet, short, tuned to the era's key. */
export const UI_CUES: Record<string, CueFn> = {
  'ui.buy': (a, _p, c) => {
    const g = a.admit('ui.buy', 0.05);
    if (!g) return;
    const t = a.now;
    pluck(a, mtof(note(c.key, 7)), { time: t, gain: 0.09 * g, decay: 0.35, tone: 5 });
    pluck(a, mtof(note(c.key, 9)), { time: t + 0.045, gain: 0.07 * g, decay: 0.45, tone: 5 });
  },
  'ui.deny': (a) => {
    const g = a.admit('ui.deny', 0.12);
    if (!g) return;
    pluck(a, 220, { gain: 0.06 * g, decay: 0.18, tone: 3 });
  },
  'ui.step': (a, _p, c) => {
    if (!a.admit('ui.step', 0.5)) return;
    const t = a.now;
    noise(a, { time: t, dur: 1.6, freq: 300, to: 2400, q: 0.7, gain: 0.05, attack: 0.5, bus: 'ambience' });
    [0, 2, 4].forEach((d, i) => bell(a, mtof(note(c.key, d + 7)), { time: t + 0.35 + i * 0.09, gain: 0.07, decay: 2.6, ratio: 2, bright: 0.6, bus: 'music' }));
  },
  'ui.discover': (a, _p, c) => {
    if (!a.admit('ui.discover', 0.3)) return;
    const t = a.now;
    [4, 7, 11].forEach((d, i) =>
      bell(a, mtof(note(c.key, d + 7)), { time: t + i * 0.07, gain: 0.06, decay: 2.2, ratio: 1.41, bright: 0.6 }),
    );
  },
  'ui.open': (a, _p, c) => {
    const g = a.admit('ui.open', 0.08);
    if (g) pluck(a, mtof(note(c.key, 11)), { gain: 0.045 * g, decay: 0.25, tone: 6 });
  },
};

export class AudioDirector {
  readonly engine = new AudioEngine();
  /** Told which rendered files the build has (vite.config.ts), so an absent one is never fetched. */
  private readonly bank = new SampleBank(this.engine, SOUND_FILES ? new Set(SOUND_FILES) : null);
  private bed: Bed | null = null;
  private stems: StemBed | null = null;
  /** Context time before which the next era's stems wait (a transition is still playing). */
  private holdUntil = 0;
  private readonly counters = new Map<string, number>();
  private readonly api: SoundApi;
  private era: EraAudio | null = null;
  private eraId: EraId | null = null;
  /** The era's rendered files, by how they are held (null: the era has no rendered sound). */
  private files: { eager: string[]; lazy: string[]; optional: string[] } | null = null;
  /** The era plays its synthesized sound: some of its rendered files cannot play. */
  private degraded = false;
  /** Context time the cue being played happened at (earlier than now for one kept from before the first gesture). */
  private cueAt = 0;
  /** Cues of a rendered era from before the first gesture, with the era they belong to. */
  private deferred: { id: string; p: CueParams; wall: number; era: EraId | null; sound: EraSound }[] = [];
  /** The cue being played, and how many effects have played lately (decaying over CROWD_SECONDS) as of `crowdAt`. */
  private cueId = '';
  private crowd = 0;
  private crowdAt = 0;
  private ticks = 0;
  private readonly ctx: CueContext;

  constructor(
    private readonly g: Game,
    private readonly audioFor: (era: EraId) => EraAudio | undefined,
  ) {
    this.ctx = {
      pan: (x) => {
        const half = this.g.renderer?.camera.halfW ?? 1000;
        return x === undefined ? 0 : Math.max(-0.8, Math.min(0.8, (x / half) * 0.8));
      },
      key: DEFAULT_KEY,
    };
    g.bus.on('sfx', (e) => this.cue(e.id, e));
    g.bus.on('buy', () => this.cue('ui.buy', {}));
    g.bus.on('step', () => {
      // The step introduces itself over everything: the effects duck under it for a few seconds.
      if (this.engine.ready) this.engine.duckEffects(0.32, 2.2, 1.4);
      this.cue('ui.step', {});
    });
    g.bus.on('discover', () => this.cue('ui.discover', {}));
    g.bus.on('eraStart', (e) => this.setEra(e.era));
    g.bus.on('settings', () => this.applySettings());
    g.bus.on('ui', () => {
      this.stems?.tick(0.05);
      if (++this.ticks % 100 === 0) this.bank.sweep();
    });
    this.bank.onFail = (name) => {
      const f = this.files;
      if (f && (f.eager.includes(name) || f.lazy.includes(name))) this.degrade([name]);
    };
    this.api = {
      play: (name, o = {}) => {
        const opts: PlayOptions = { ...o, at: o.at ?? this.cueAt, pan: o.pan ?? (o.x !== undefined ? this.ctx.pan(o.x) : 0), gain: (o.gain ?? 1) * this.thin(o) };
        const music = (opts.bus ?? 'sfx') !== 'sfx' || !!opts.loop;
        // An effect kept from before the first gesture belongs to nothing by now.
        if (!music && this.engine.now - (opts.at ?? 0) > EFFECT_LATE) return null;
        const buf = this.bank.get(name);
        if (buf && this.engine.running) {
          const v = playBuffer(this.engine, buf, opts);
          if (v) this.bank.played(name, this.engine.now + buf.duration);
          return v;
        }
        if (this.bank.missing(name)) return null;
        // Not decoded yet (a rare file), or the context is still starting (the first gesture): the voice
        // starts once both are ready, late. Music catches up by the wall clock, which runs while the
        // context's stands still; an effect from the first gesture plays from its start however long
        // the device took, any other from its start only if just a moment late.
        const starting = !this.engine.running;
        const meant = performance.now() - (this.engine.now - (opts.at ?? this.engine.now)) * 1000;
        const v = voiceFor(this.engine, opts);
        if (!v) return null;
        void Promise.all([this.engine.whenRunning(), buf ?? this.bank.load(name)]).then(([, b]) => {
          if (!b) return;
          const late = music || !starting ? (performance.now() - meant) / 1000 : 0;
          const end = startVoice(this.engine, v, b, { ...opts, at: this.engine.now - late });
          if (end !== null) this.bank.played(name, end);
        });
        return v;
      },
      ready: (name) => {
        if (this.bank.get(name)) return true;
        if (!this.bank.missing(name)) void this.bank.load(name);
        return false;
      },
      stop: (v, fade = 0.3) => fadeOutVoice(this.engine, v, fade),
      admit: (id, min) => this.engine.admit(id, min),
      position: () => this.stems?.position() ?? 0,
      next: (k) => {
        const n = this.counters.get(k) ?? 0;
        this.counters.set(k, n + 1);
        return n;
      },
      duck: (level, seconds = 1.5) => this.stems?.setLevel(level, seconds),
      handover: (fade, hold) => {
        this.stems?.stop(fade);
        this.stems = null;
        this.holdUntil = this.cueAt + hold;
      },
    };
    // Made now, suspended, so the era a session opens in decodes before the first gesture.
    this.engine.arm();
  }

  /** Call from every user gesture; the first that browsers accept for audio starts the era's sound. */
  unlock(): void {
    // Only the unlocking press starts it: starting it again would bring back a bed a transition has
    // just handed over.
    const first = this.engine.unlock();
    this.applySettings();
    if (!first) return;
    // What happened before it (a finale replayed after a reload) plays now, as late as it is: an
    // earlier era's cues first (a hand-over sets when this era's bed may start), then this era's bed
    // as it would have begun, then this era's cues (a hand-over among them ends that bed, as it would have).
    const kept = this.deferred;
    this.deferred = [];
    const wall = performance.now();
    const replay = (d: (typeof kept)[number]) => this.play(d.sound, d.id, d.p, this.engine.now - (wall - d.wall) / 1000);
    for (const d of kept) if (d.era !== this.eraId) replay(d);
    if (this.eraId) this.setEra(this.eraId);
    for (const d of kept) if (d.era === this.eraId && d.sound === this.sound) replay(d);
  }

  applySettings(): void {
    const s = this.g.state.settings;
    this.engine.setVolumes({ master: s.masterVolume, music: s.musicVolume, sfx: s.sfxVolume, ambience: s.ambienceVolume });
  }

  setMuted(muted: boolean): void {
    this.engine.setMuted(muted);
  }

  setEra(id: EraId): void {
    const changed = id !== this.eraId || !this.era;
    this.eraId = id;
    this.era = this.audioFor(id) ?? null;
    this.ctx.key = this.era?.key ?? DEFAULT_KEY;
    if (!this.engine.armed) return;
    if (changed || !this.files) {
      const sound = this.era?.sound;
      this.files = sound ? soundFiles(sound) : null;
      this.degraded = false;
      const f = this.files;
      const absent = f ? [...f.eager, ...f.lazy].filter((n) => this.bank.missing(n)) : [];
      if (absent.length) this.degrade(absent);
      else this.bank.prepare(f ? [...f.eager, ...f.optional.filter((n) => !this.bank.missing(n))] : [], f?.lazy ?? []);
    }
    if (this.engine.ready) this.startBed();
  }

  /** The era's rendered sound, unless it cannot all play. */
  private get sound(): EraSound | undefined {
    return this.degraded ? undefined : this.era?.sound;
  }

  /** Some of the era's rendered files cannot play: it plays its synthesized sound instead. */
  private degrade(names: string[]): void {
    if (this.degraded) return;
    this.degraded = true;
    const shown = names.slice(0, 6).join(', ') + (names.length > 6 ? ` and ${names.length - 6} more` : '');
    console.warn(`[sound] ${this.eraId}: ${names.length} rendered file(s) cannot play (${shown}); playing the synthesized sound instead`);
    // Nothing of the rendered sound will play: none of it is held.
    this.bank.prepare([], []);
    if (this.engine.ready) this.startBed();
  }

  /** Starts the era's bed (its stems, or its synthesized bed), unless it is already playing. */
  private startBed(): void {
    const sound = this.sound;
    const st = sound?.stems;
    if (st) {
      this.bed?.stop(BED_FADE);
      this.bed = null;
      if (this.stems?.id === st.id) return;
      this.stems?.stop(BED_FADE);
      const stems = (this.stems = new StemBed(this.engine, this.bank, st.id, st.names, st.loop, st.layers, st.busy));
      void stems.begin(BED_FADE, Math.max(0, this.holdUntil - this.engine.now)).then((ok) => {
        if (!ok && this.stems === stems) this.degrade([st.names[0]]);
      });
      return;
    }
    this.stems?.stop(BED_FADE);
    this.stems = null;
    // A rendered era without stems has no bed of its own.
    const spec = sound ? undefined : this.era?.bed;
    if (this.bed && spec && this.bed.spec.id === spec.id) return;
    this.bed?.stop(BED_FADE);
    this.bed = null;
    if (spec) {
      this.bed = new Bed(this.engine, spec);
      this.bed.fadeIn(BED_FADE);
    }
  }

  /** Duck or restore the ambient bed (0..1). */
  bedLevel(level: number, seconds = 1.5): void {
    this.bed?.setLevel(level, seconds);
    this.stems?.setLevel(level, seconds);
  }

  cue(id: string, p: CueParams): void {
    const sound = this.sound;
    if (!this.engine.ready) {
      // A rendered era keeps it for the first gesture (only music will still be in time by then), the
      // latest of each cue: a finale's flurry of effects must not push out the cue that began it.
      if (!sound) return;
      const wall = performance.now();
      this.deferred = this.deferred.filter((d) => wall - d.wall < DEFERRED_SECONDS * 1000 && !(d.id === id && d.era === this.eraId)).slice(-(DEFERRED_MAX - 1));
      this.deferred.push({ id, p, wall, era: this.eraId, sound });
      return;
    }
    if (sound && !id.startsWith('ui.')) this.stems?.bump();
    if (this.play(sound, id, p, this.engine.now)) return;
    const fn = this.era?.cues[id] ?? UI_CUES[id];
    fn?.(this.engine, p, this.ctx);
  }

  /**
   * Plays a cue from rendered sound, as if at context time `at`; false if `sound` has none for it (the
   * synthesized one plays instead: an era part-way rendered, or an optional interface file absent).
   */
  private play(sound: EraSound | undefined, id: string, p: CueParams, at: number): boolean {
    const rendered = sound ? renderedCues(sound)[id] : undefined;
    if (!rendered || (!sound?.cues[id] && SOUND_UI[id]?.files.every((n) => this.bank.missing(n)))) return false;
    this.cueAt = at;
    this.cueId = id;
    rendered(this.api, p);
    return true;
  }

  /** The crowd's gain for an effect about to play (1 below the era's `crowd` rate; music and the interface are never thinned). */
  private thin(o: PlayOptions): number {
    const limit = this.sound?.crowd;
    if (!limit || (o.bus ?? 'sfx') !== 'sfx' || this.cueId.startsWith('ui.')) return 1;
    const t = this.engine.now;
    this.crowd = this.crowd * Math.exp(-(t - this.crowdAt) / CROWD_SECONDS) + 1;
    this.crowdAt = t;
    const rate = this.crowd / CROWD_SECONDS;
    return rate > limit ? Math.sqrt(limit / rate) : 1;
  }

  /** QA: decoded PCM held now (bytes) and the files it is. */
  get resident(): { bytes: number; files: string[] } {
    return { bytes: this.bank.residentBytes, files: this.bank.resident };
  }
}
