/**
 * The patch that inflates: the point of light the Prologue begins with, drawn as what it is, a tiny
 * region of space about to become everything. Small, it is a white-hot point. Holding, it grows into a
 * sphere of light: its surface carries the jitter of the field inside it, born at the horizon (a fixed
 * size on the screen, as the Hubble radius is during inflation), boiling while it is that small, frozen
 * once the sphere has stretched it larger, then stretched on with the sphere. So the sphere's face
 * fills with a mottled pattern octave by octave as it grows (the seeds of every later structure), its
 * limb burns brightest, and its light spills out around it. At sixty e-folds it is larger than the
 * screen: everything in view is inside it, and reheating burns the pattern from violet to white.
 *
 * One full-screen pass over the scene, after the storm of specks: the sphere's face hides the specks
 * behind it (premultiplied: opaque inside, pure added light outside).
 */
import { bindTexture, drawFullscreen, FULLSCREEN_VS, type GLCaps, type Program, tryProgram } from '../../render/gl';
import { HEADER } from '../../render/glsl';
import { NOISE_SIZE, noiseVolume } from '../../render/noise3d';
import type { LayerFrame, RenderLayer } from '../../render/renderer';

/** Octaves of the field on the sphere, each twice as fine as the last. */
const OCTAVES = 9;

const FS = HEADER + /* glsl */ `
precision highp sampler3D;
in vec2 vUv;
out vec4 outColor;
uniform vec4 uView;
uniform vec2 uCenter;
uniform float uR;
uniform float uHorizon;
uniform float uPx;
uniform float uTime;
uniform float uBright;
uniform float uHalo;
uniform float uSurge;
uniform float uHeat;
uniform float uWhite;
uniform float uGain;
uniform sampler3D uNoise;

float N(vec3 p) { return texture(uNoise, p).r; }

/**
 * The field's jitter on the sphere at direction n: octaves twice as fine each, every one weighted by
 * how its size on the screen compares with the horizon: absent below it, boiling as it crosses it,
 * frozen and still once stretched past, and fading as it grows far past it (so what shows is spots of
 * a size, a few horizons across, with the coarser ones a faint swell under them). Returns the pattern
 * (about -1..1) and how much of it has frozen (0..1).
 */
vec2 field(vec3 n) {
  float sum = 0.0;
  float wsum = 0.0;
  float frozen = 0.0;
  for (int k = 0; k < ${OCTAVES}; k++) {
    float f = 1.6 * exp2(float(k));
    // An octave's features on the screen: the sphere's radius over its frequency, against the horizon.
    float x = log2(uR / f / uHorizon);
    float born = smoothstep(-1.0, 0.0, x);
    if (born <= 0.0) continue;
    float still = smoothstep(0.0, 1.2, x);
    float w = born * (0.3 + 0.7 * exp(-0.5 * pow((x - 2.0) / 1.3, 2.0)));
    vec3 q = n * f * 0.11 + vec3(0.37, 0.71, 0.13) * float(k);
    // Boiling: a young octave churns in time; frozen, it stops where it was.
    float v = N(q + vec3(0.0, 0.0, (1.0 - still) * uTime * 0.6)) - 0.5;
    sum += v * w;
    wsum += w * w;
    frozen += still * w;
  }
  return vec2(wsum > 0.0 ? 3.2 * sum / sqrt(wsum) : 0.0, wsum > 0.0 ? frozen / (sqrt(wsum) * 2.0) : 0.0);
}

void main() {
  vec2 ndc = vUv * 2.0 - 1.0;
  vec2 p = vec2(uView.x + ndc.x * uView.z, uView.y - ndc.y * uView.w);
  vec2 dv = p - uCenter;
  float R = max(uR, 1e-3);
  float x = length(dv) / R;
  float x2 = min(1.0, x * x);
  // How much of the ball the eye crosses here, relative to its middle: 1 at the heart, 0 at the edge.
  float depth = sqrt(max(0.0, 1.0 - x2));
  vec3 edge = vec3(0.4, 0.3, 1.0);
  vec3 mid = vec3(0.46, 0.52, 1.0);
  vec3 heartc = vec3(1.0, 0.97, 0.93);

  vec3 col = vec3(0.0);
  float alpha = 0.0;
  if (x < 1.0) {
    // A volume of light, not a body: its glow is the path through it, so it has no hard surface and
    // thins to nothing at its edge. The frozen ripples are seen through the glow, near side and far.
    vec3 nrm = vec3(dv / R, depth);
    vec2 near = field(nrm);
    vec2 far = field(vec3(nrm.xy, -depth) + vec3(0.31, 0.17, 0.53));
    float pat = 0.7 * near.x + 0.45 * far.x;
    float frozen = max(near.y, far.y);
    float lit = smoothstep(-1.3, 1.3, pat);
    float knot = smoothstep(1.1, 1.7, pat) * frozen;
    // Violet where it is thin, blue through its body, white-hot at its heart; in real range, blazing at
    // the middle and many times dimmer where it is thin.
    vec3 c = mix(edge, mid, smoothstep(0.0, 0.6, depth));
    c = mix(c, heartc, smoothstep(0.6, 1.0, depth));
    float glow = 0.4 * depth + 2.8 * pow(depth, 7.0);
    // While it is young, the point it grew from still burns at its middle.
    float young = 1.0 - smoothstep(30.0, 260.0, R);
    float heart = young * exp(-x2 / 0.025);
    c = c * glow * (0.5 + 0.8 * lit) + heartc * knot * 0.9 * depth + heartc * heart * 2.5;
    // Reheating: the frozen pattern burns from violet through rose to white, its crests first.
    float burn = clamp(uHeat * (0.55 + 0.45 * lit + 0.4 * knot), 0.0, 1.4);
    vec3 rose = vec3(1.0, 0.42, 0.5) * (0.5 + 0.7 * lit + knot);
    vec3 white = vec3(1.0, 0.97, 0.93) * (0.9 + 0.4 * lit + knot);
    c = mix(c, rose * 1.6, smoothstep(0.0, 0.6, burn) * (1.0 - smoothstep(0.6, 1.2, burn)));
    c = mix(c, white * 2.2, smoothstep(0.7, 1.3, burn));
    col = c * uBright * (1.0 + 1.5 * uSurge);
    col = mix(col, vec3(1.0, 0.98, 0.96) * 6.0, uWhite);
    // It hides what lies behind it as thickly as it is deep there.
    alpha = 0.95 * smoothstep(0.0, 0.55, depth);
  }
  // The light it spills, continuing its thin edge outward with no seam: inside, a faint violet that
  // grows toward the edge; outside, falling away with distance, scaled with the ball.
  float out1 = max(0.0, x - 1.0);
  float spill = x < 1.0 ? 0.4 * x2 * x2 : 0.35 * exp(-out1 * 6.0) + 0.05 * exp(-out1 * 2.0);
  col += edge * spill * uHalo * (1.0 + 2.0 * uSurge) * (1.0 - uWhite);
  outColor = vec4(col * uGain, alpha);
}`;

export class Patch implements RenderLayer {
  readonly stage = 'atmosphere' as const;
  /** Centre and radius (world units), set every frame. */
  x = 0;
  y = 0;
  radius = 0;
  /** The horizon: the size at which the field's jitter is born on the screen (world units). */
  horizon = 6;
  /** The face's brightness, the spilled light's, a surge at each tenth e-fold (decaying, 0–1). */
  bright = 1.2;
  halo = 1;
  surge = 0;
  /** Reheating: how hot the pattern burns (0 → 1.4), and the white flood (0 → 1). */
  heat = 0;
  white = 0;
  private gl: WebGL2RenderingContext | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private prog: Program | null = null;
  private noise: WebGLTexture | null = null;
  private time = 0;

  init(gl: WebGL2RenderingContext, _caps: GLCaps, emptyVao: WebGLVertexArrayObject): void {
    this.gl = gl;
    this.vao = emptyVao;
    this.prog = tryProgram(gl, FULLSCREEN_VS, FS, 'patch');
    const noise = gl.createTexture();
    bindTexture(gl, 0, noise, gl.TEXTURE_3D);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    gl.texImage3D(gl.TEXTURE_3D, 0, gl.R8, NOISE_SIZE, NOISE_SIZE, NOISE_SIZE, 0, gl.RED, gl.UNSIGNED_BYTE, noiseVolume());
    gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    for (const w of [gl.TEXTURE_WRAP_S, gl.TEXTURE_WRAP_T, gl.TEXTURE_WRAP_R]) gl.texParameteri(gl.TEXTURE_3D, w, gl.REPEAT);
    bindTexture(gl, 0, null, gl.TEXTURE_3D);
    this.noise = noise;
  }

  draw(frame: LayerFrame): void {
    const gl = this.gl;
    const prog = this.prog;
    if (!gl || !prog || !this.vao || !this.noise) return;
    this.time += Math.min(frame.dt, 1 / 20);
    if (this.radius <= 0 && this.white <= 0) return;
    gl.enable(gl.BLEND);
    // Premultiplied: the face covers what is behind it; the spilled light adds.
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    prog.use().f2('uCenter', this.x, this.y).f1('uR', Math.max(0.01, this.radius)).f1('uHorizon', this.horizon).f1('uPx', 1 / frame.pxPerUnit);
    prog.f1('uTime', this.time).f1('uBright', this.bright).f1('uHalo', this.halo).f1('uSurge', this.surge);
    prog.f1('uHeat', this.heat).f1('uWhite', this.white).f1('uGain', frame.gain ?? 1);
    gl.uniform4fv(prog.loc('uView'), frame.view);
    bindTexture(gl, 0, this.noise, gl.TEXTURE_3D);
    prog.i1('uNoise', 0);
    drawFullscreen(gl, this.vao);
    bindTexture(gl, 0, null, gl.TEXTURE_3D);
    gl.blendFunc(gl.ONE, gl.ONE);
  }

  dispose(): void {
    this.prog?.dispose();
    if (this.gl && this.noise) this.gl.deleteTexture(this.noise);
    this.prog = null;
    this.noise = null;
  }
}
