/**
 * Short-lived visual effects (flashes, shock rings, sparks, puffs). Purely cosmetic: they never feed
 * back into the simulation, so they use the fx random stream and can be culled freely under load.
 */
import type { Renderer } from './renderer';
import { Shape } from './sprites';

export const Fx = {
  /** Bright bloom that fades and grows. */
  Flash: 0,
  /** Expanding thin ring. */
  Ring: 1,
  /** Fast streak that fades (photons, debris). */
  Spark: 2,
  /** Soft cloud that fades (smoke, glow residue). */
  Puff: 3,
  /** A photon: drawn as a spark, or as a wave packet by a look that has one. */
  Photon: 4,
} as const;
export type Fx = (typeof Fx)[keyof typeof Fx];

/**
 * Another way to draw the same effects: an era with its own look (version 2) renders flashes as point
 * spreads that light its medium, rings as light fronts and pushes through its matter instead of drawn
 * circles, and sparks as streaks. `t` runs 0 → 1 over the effect's life.
 */
export interface FxLook {
  flash(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void;
  ring(x: number, y: number, radius: number, r: number, g: number, b: number, t: number): void;
  spark(x: number, y: number, vx: number, vy: number, size: number, r: number, g: number, b: number, t: number): void;
  puff(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void;
  /** A photon (a spark when absent). */
  photon?(x: number, y: number, vx: number, vy: number, size: number, r: number, g: number, b: number, t: number): void;
}

export class FxPool {
  n = 0;
  private x: Float32Array;
  private y: Float32Array;
  private vx: Float32Array;
  private vy: Float32Array;
  private age: Float32Array;
  private life: Float32Array;
  private size: Float32Array;
  private grow: Float32Array;
  private cr: Float32Array;
  private cg: Float32Array;
  private cb: Float32Array;
  private drag: Float32Array;
  private kind: Uint8Array;

  constructor(readonly cap = 600) {
    this.x = new Float32Array(cap);
    this.y = new Float32Array(cap);
    this.vx = new Float32Array(cap);
    this.vy = new Float32Array(cap);
    this.age = new Float32Array(cap);
    this.life = new Float32Array(cap);
    this.size = new Float32Array(cap);
    this.grow = new Float32Array(cap);
    this.cr = new Float32Array(cap);
    this.cg = new Float32Array(cap);
    this.cb = new Float32Array(cap);
    this.drag = new Float32Array(cap);
    this.kind = new Uint8Array(cap);
  }

  /**
   * `size` is the starting radius; `grow` adds world units per second (rings, flashes).
   * Colour is linear HDR intensity.
   */
  spawn(
    kind: Fx,
    x: number,
    y: number,
    life: number,
    size: number,
    r: number,
    g: number,
    b: number,
    grow = 0,
    vx = 0,
    vy = 0,
    drag = 0,
  ): void {
    if (this.n >= this.cap) return;
    const i = this.n++;
    this.kind[i] = kind;
    this.x[i] = x;
    this.y[i] = y;
    this.vx[i] = vx;
    this.vy[i] = vy;
    this.age[i] = 0;
    this.life[i] = life;
    this.size[i] = size;
    this.grow[i] = grow;
    this.cr[i] = r;
    this.cg[i] = g;
    this.cb[i] = b;
    this.drag[i] = drag;
  }

  update(dt: number): void {
    let i = 0;
    while (i < this.n) {
      this.age[i] += dt;
      if (this.age[i] >= this.life[i]) {
        const last = --this.n;
        if (i !== last) this.copy(last, i);
        continue;
      }
      const k = Math.exp(-this.drag[i] * dt);
      this.vx[i] *= k;
      this.vy[i] *= k;
      this.x[i] += this.vx[i] * dt;
      this.y[i] += this.vy[i] * dt;
      i++;
    }
  }

  private copy(from: number, to: number): void {
    this.kind[to] = this.kind[from];
    this.x[to] = this.x[from];
    this.y[to] = this.y[from];
    this.vx[to] = this.vx[from];
    this.vy[to] = this.vy[from];
    this.age[to] = this.age[from];
    this.life[to] = this.life[from];
    this.size[to] = this.size[from];
    this.grow[to] = this.grow[from];
    this.cr[to] = this.cr[from];
    this.cg[to] = this.cg[from];
    this.cb[to] = this.cb[from];
    this.drag[to] = this.drag[from];
  }

  render(r: Renderer, look?: FxLook): void {
    for (let i = 0; i < this.n; i++) {
      const t = this.age[i] / this.life[i];
      const size = this.size[i] + this.grow[i] * this.age[i];
      const red = this.cr[i];
      const grn = this.cg[i];
      const blu = this.cb[i];
      if (look) {
        const k = this.kind[i];
        if (k === Fx.Flash) look.flash(this.x[i], this.y[i], size, red, grn, blu, t);
        else if (k === Fx.Ring) look.ring(this.x[i], this.y[i], size, red, grn, blu, t);
        else if (k === Fx.Spark) look.spark(this.x[i], this.y[i], this.vx[i], this.vy[i], size, red, grn, blu, t);
        else if (k === Fx.Photon) (look.photon ?? look.spark).call(look, this.x[i], this.y[i], this.vx[i], this.vy[i], size, red, grn, blu, t);
        else look.puff(this.x[i], this.y[i], size, red, grn, blu, t);
        continue;
      }
      switch (this.kind[i]) {
        case Fx.Flash: {
          const f = (1 - t) * (1 - t);
          r.over.push(this.x[i], this.y[i], size, red * f, grn * f, blu * f, 1, Shape.Glow);
          break;
        }
        case Fx.Ring: {
          const f = Math.pow(1 - t, 1.6);
          // Constant thickness in world units, so a big ring stays a ring instead of becoming a band.
          r.over.push(this.x[i], this.y[i], size, red * f, grn * f, blu * f, 1, Shape.Shock, Math.min(0.08, (4 + 4 * t) / Math.max(size, 1)));
          break;
        }
        case Fx.Spark:
        case Fx.Photon: {
          const f = 1 - t;
          const st = 0.022;
          r.glow.push(this.x[i], this.y[i], size, red * f, grn * f, blu * f, 1, Shape.Glow, 0, 0, this.vx[i] * st, this.vy[i] * st);
          break;
        }
        default: {
          const f = (1 - t) * Math.min(1, t * 6);
          r.under.push(this.x[i], this.y[i], size, red, grn, blu, f, Shape.Puff);
        }
      }
    }
  }

  clear(): void {
    this.n = 0;
  }
}
