<!--
  One seed: its numbers against the parent's, what they would mean, what could go wrong, and (with
  Second sight) how it would end.
-->
<script lang="ts">
  import { diesYoung, fateOf, predictions, warnings, type Fate } from '../../core/multiverse';
  import type { Constants, EraId } from '../../core/state';
  import Strip from './Strip.svelte';

  let {
    c,
    parent,
    name,
    sight = false,
    onpick,
    onhover,
  }: { c: Constants; parent: Constants; name: string; sight?: boolean; onpick: () => void; onhover: (on: boolean) => void } = $props();

  const ENDS: Record<Fate, string> = {
    'heat-death': 'Ends in heat death',
    crunch: 'Ends in a Big Crunch',
    rip: 'Ends in a Big Rip',
    vacuum: 'Ends in vacuum decay',
  };

  const lines = $derived(predictions(parent, c));
  const warn = $derived(warnings(c));
  const foresight = $derived.by(() => {
    if (!sight) return null;
    for (const era of ['nucleo', 'afterglow', 'dawn'] as EraId[]) {
      const b = diesYoung(c, era);
      if (b) return `Dies young: ${b.label.toLowerCase()}`;
    }
    return ENDS[fateOf(c)];
  });
</script>

<article class="seed" onpointerenter={() => onhover(true)} onpointerleave={() => onhover(false)}>
  <header>
    <span class="label">Seed</span>
    <span class="name">{name}</span>
  </header>
  <Strip {c} {parent} />
  <ul class="pred">
    {#each lines as line (line)}
      <li>{line}</li>
    {:else}
      <li class="same">Almost exactly its parent.</li>
    {/each}
  </ul>
  {#if warn.length}
    <ul class="warn">
      {#each warn as w (w)}<li>{w}</li>{/each}
    </ul>
  {/if}
  {#if foresight}<p class="sight">{foresight}</p>{/if}
  <button class="go" onclick={onpick}>Inflate</button>
</article>

