/**
 * The Long Night thins out: a sparse minor pentatonic pad over a low drone, chords that change only
 * every 48 seconds. Feeding ticks rise in pitch as the disk fills; a spill opens with a bright bell;
 * a full spill rings a chord; an overfed disk bursts with a dull thud. A final flash is a high, glassy
 * note with a long tail; the last one closes the era on a chord that fades to nothing.
 */
import type { EraAudio } from '../../audio/director';
import { bell, noise, pluck, swell, thump } from '../../audio/patches';
import { SCALES, mtof, note, type Key } from '../../audio/scales';

const KEY: Key = { root: 38, scale: SCALES.minorPentatonic };

export const NIGHT_AUDIO: EraAudio = {
  key: KEY,
  bed: {
    id: 'night',
    chords: [
      [38, 50, 57, 62],
      [36, 48, 55, 63],
      [41, 53, 57, 60],
      [33, 45, 52, 57],
    ],
    chordSeconds: 48,
    pad: { gain: 0.04, type: 'sine', cutoff: 700, detune: 6, lfo: 0.012 },
    drone: { note: 26, gain: 0.035 },
    air: { freq: 420, q: 0.5, gain: 0.004, drift: 0.008 },
    shimmer: { gain: 0.004, rate: 0.06 },
    // Deliberately left about 3 dB under the other beds: the Long Night is the universe running down.
    level: 1,
  },
  cues: {
    'night.press': (a, p, c) => {
      const g = a.admit('night.press', 0.15);
      if (g) pluck(a, mtof(note(c.key, 9)), { gain: 0.05 * g, decay: 0.9, tone: 2.5, pan: c.pan(p.x) });
    },
    'night.feed': (a, p, c) => {
      const g = a.admit('night.feed', 0.12);
      if (!g) return;
      const step = Math.round(4 + 6 * Math.min(1.4, p.pitch ?? 0));
      bell(a, mtof(note(c.key, step)), { gain: 0.028 * g, decay: 0.8, ratio: 2, bright: 0.25, pan: c.pan(p.x) });
    },
    'night.tde': (a, p, c) => {
      const g = a.admit('night.tde', 0.5);
      if (g) noise(a, { dur: 0.9, freq: 3600, to: 600, q: 2, gain: 0.03 * g, attack: 0.02, pan: c.pan(p.x) });
    },
    'night.spill': (a, p, c) => {
      if (!a.admit('night.spill', 0.2)) return;
      const t = a.now;
      const k = p.intensity ?? 1;
      noise(a, { time: t, dur: 1.4, freq: 300, to: 3200, q: 0.8, gain: 0.045 * k, attack: 0.05, pan: c.pan(p.x) });
      bell(a, mtof(note(c.key, 12)), { time: t + 0.04, gain: 0.05 * k, decay: 2.8, ratio: 3, bright: 0.8, pan: c.pan(p.x) });
    },
    'night.full': (a, p, c) => {
      if (!a.admit('night.full', 0.4)) return;
      const t = a.now;
      noise(a, { time: t, dur: 1.8, freq: 250, to: 5200, q: 0.9, gain: 0.06, attack: 0.04, pan: c.pan(p.x) });
      [0, 2, 4].forEach((d, i) => bell(a, mtof(note(c.key, 12 + d)), { time: t + 0.05 + i * 0.06, gain: 0.05, decay: 3.5, ratio: 3, bright: 1, pan: c.pan(p.x) }));
      swell(a, [50, 57, 62, 69].map(mtof), { time: t, attack: 0.3, hold: 1.2, release: 4, gain: 0.07, cutoff: 3200 });
    },
    'night.blowout': (a, p, c) => {
      if (!a.admit('night.blowout', 0.3)) return;
      const t = a.now;
      // Pitched above the sub range (C3): the thud reads on any speaker and leaves the low end to the bed.
      thump(a, mtof(48), { time: t, gain: 0.1, dur: 0.5, pan: c.pan(p.x) });
      noise(a, { time: t, dur: 1.3, freq: 1600, to: 260, q: 0.7, gain: 0.12, attack: 0.01, pan: c.pan(p.x) });
      pluck(a, mtof(note(c.key, 6)), { time: t + 0.02, gain: 0.04, decay: 0.7, tone: 1.5, pan: c.pan(p.x) });
    },
    'night.newstar': (a, p, c) => {
      if (!a.admit('night.newstar', 0.2)) return;
      const t = a.now;
      pluck(a, mtof(note(c.key, 9)), { time: t, gain: 0.04, decay: 1.4, tone: 3, pan: c.pan(p.x) });
      pluck(a, mtof(note(c.key, 11)), { time: t + 0.14, gain: 0.035, decay: 1.6, tone: 3, pan: c.pan(p.x) });
    },
    'night.chirp': (a, p, c) => {
      const g = a.admit('night.chirp', 1.2);
      if (g) noise(a, { dur: 3, freq: 50, to: 800, q: 10, gain: 0.05 * g, attack: 2.6, pan: c.pan(p.x) });
    },
    'night.merge': (a, p, c) => {
      if (!a.admit('night.merge', 0.6)) return;
      const t = a.now;
      thump(a, mtof(50), { time: t, gain: 0.12, dur: 1.2, pan: c.pan(p.x) });
      swell(a, [50, 57, 62, 69].map(mtof), { time: t + 0.1, attack: 0.8, hold: 1.5, release: 6, gain: 0.1, cutoff: 2400 });
    },
    'night.flash': (a, p, c) => {
      if (!a.admit('night.flash', 0.3)) return;
      const t = a.now;
      bell(a, mtof(note(c.key, 19)), { time: t, gain: 0.07, decay: 7, ratio: 3.5, bright: 1.4, pan: c.pan(p.x) });
      noise(a, { time: t, dur: 2.2, freq: 8000, to: 1200, q: 1.2, gain: 0.05, attack: 0.005, pan: c.pan(p.x) });
    },
    'night.catch': (a, p, c) => {
      if (!a.admit('night.catch', 0.4)) return;
      const t = a.now;
      bell(a, mtof(note(c.key, 19)), { time: t, gain: 0.08, decay: 8, ratio: 3.5, bright: 1.5, pan: c.pan(p.x) });
      [0, 3, 5].forEach((d, i) => bell(a, mtof(note(c.key, 14 + d)), { time: t + 0.08 + i * 0.07, gain: 0.045, decay: 4, ratio: 2, bright: 0.7, pan: c.pan(p.x) }));
      noise(a, { time: t, dur: 2.4, freq: 9000, to: 1400, q: 1.2, gain: 0.06, attack: 0.005, pan: c.pan(p.x) });
    },
    'night.early': (a, p, c) => {
      const g = a.admit('night.early', 0.3);
      if (g) pluck(a, mtof(note(c.key, 4)), { gain: 0.035 * g, decay: 0.4, tone: 1.5, pan: c.pan(p.x) });
    },
    'night.milestone': (a, _p, c) => {
      const t = a.now;
      swell(a, [38, 45, 50, 57].map(mtof), { bus: 'music', time: t, attack: 2.5, hold: 1.5, release: 7, gain: 0.1, cutoff: 1200 });
      bell(a, mtof(note(c.key, 9)), { bus: 'music', time: t + 0.8, gain: 0.035, decay: 5, ratio: 2, bright: 0.2 });
    },
    'night.complete': (a) => {
      const t = a.now;
      swell(a, [26, 38, 45, 50, 57, 62].map(mtof), { time: t, attack: 5, hold: 6, release: 14, gain: 0.16, cutoff: 1600 });
    },
  },
};
