/**
 * Instanced sprite batches.
 *
 * Every particle in the game is one instance: position, radius, rotation, HDR colour, a shape id
 * and an optional velocity "stretch" that turns it into a motion-blurred capsule.
 * Sprites smaller than `minPx` are drawn at `minPx` with their brightness reduced to conserve
 * energy, so tiny fast particles never shimmer or vanish between pixels.
 */
import { HEADER } from './glsl';
import { tryProgram, type Program } from './gl';

export const Shape = {
  /** Bright core with a soft halo. Quarks, sparks, photons. */
  Glow: 0,
  /** Hollow ring with a faint halo. Antimatter (shape-coded, never colour alone). */
  Ring: 1,
  /** Very soft gaussian puff. Gas, fog, nebula. */
  Puff: 2,
  /** Shaded ball with an antialiased edge. Nucleons. Use in an alpha layer. */
  Sphere: 3,
  /** Thin expanding shock ring. Annihilation flashes, pulses. `param` = thickness. */
  Shock: 4,
  /** Star: tight core, wide halo and four diffraction spikes. `param` = spike strength. */
  Star: 5,
  /** Flat disc with an antialiased edge (markers, black hole shadows). Alpha layer. */
  Disc: 6,
} as const;
export type Shape = (typeof Shape)[keyof typeof Shape];

const FLOATS_PER_INSTANCE = 12;

const VS = HEADER + /* glsl */ `
layout(location = 0) in vec2 aCorner;
layout(location = 1) in vec4 iPosSizeRot;
layout(location = 2) in vec4 iColor;
layout(location = 3) in vec4 iShape;
uniform vec4 uView;       // centre x, y, half width, half height (world units)
uniform float uPxPerUnit;
uniform float uMinPx;
out vec2 vUv;
out vec4 vColor;
flat out int vShape;
out float vParam;
out float vStretch;
void main() {
  float size = iPosSizeRot.z;
  float px = size * uPxPerUnit;
  float gain = 1.0;
  if (px < uMinPx) {
    gain = (px * px) / (uMinPx * uMinPx);
    size = uMinPx / uPxPerUnit;
  }
  vec2 st = iShape.zw;
  float sl = length(st);
  vec2 dir = sl > 1e-6 ? st / sl : vec2(cos(iPosSizeRot.w), sin(iPosSizeRot.w));
  vec2 nrm = vec2(-dir.y, dir.x);
  float halfLen = size + sl;
  gain *= size / halfLen; // a streak spreads the same light over a longer path
  vec2 world = iPosSizeRot.xy + aCorner.x * dir * halfLen + aCorner.y * nrm * size;
  vec2 ndc = (world - uView.xy) / uView.zw;
  gl_Position = vec4(ndc.x, -ndc.y, 0.0, 1.0);
  vUv = vec2(aCorner.x * halfLen / size, aCorner.y);
  vStretch = sl / size;
  vColor = vec4(iColor.rgb * gain, iColor.a);
  vShape = int(iShape.x + 0.5);
  vParam = iShape.y;
}`;

const FS = HEADER + /* glsl */ `
in vec2 vUv;
in vec4 vColor;
flat in int vShape;
in float vParam;
in float vStretch;
uniform float uGain;      // light into the scene's range (1 with HDR)
out vec4 outColor;

float capsule(vec2 p, float s) {
  p.x = max(abs(p.x) - s, 0.0);
  return length(p);
}

void main() {
  float r = capsule(vUv, vStretch);
  if (r >= 1.0) discard;
  float win = 1.0 - r * r;
  win *= win;
  vec3 col = vColor.rgb;
  float a;
  if (vShape == 0) {
    float core = exp(-r * r * 42.0);
    a = (core + 0.3 * exp(-r * r * 6.5) + 0.06 * exp(-r * r * 1.6)) * win;
    // White-hot centre, coloured halo: how bright light actually reads.
    float peak = max(max(col.r, col.g), col.b);
    col = mix(col, vec3(peak), core * 0.6);
  } else if (vShape == 1) {
    float th = max(vParam, 0.03);
    float d = (r - 0.5) / th;
    a = (exp(-d * d) + 0.05 * exp(-r * r * 3.0)) * win;
  } else if (vShape == 2) {
    a = exp(-r * r * 3.2) * win;
  } else if (vShape == 3) {
    float aa = fwidth(r) * 1.5;
    float edge = 1.0 - smoothstep(1.0 - aa - 0.06, 1.0 - 0.06, r);
    float z = sqrt(max(0.0, 1.0 - r * r));
    vec3 n = normalize(vec3(vUv.x, -vUv.y, z));
    float diff = max(dot(n, normalize(vec3(-0.45, 0.55, 0.75))), 0.0);
    float rim = pow(1.0 - z, 2.5);
    col = vColor.rgb * (0.28 + 0.8 * diff) + vColor.rgb * rim * 0.45;
    a = edge;
  } else if (vShape == 4) {
    // Thin rings stay thin at any size, but never thinner than about a pixel (no shimmer).
    float th = max(vParam, max(0.002, fwidth(r) * 1.2));
    float d = (r - 0.82) / th;
    a = exp(-d * d) * (1.0 - smoothstep(0.9, 1.0, r));
  } else if (vShape == 5) {
    vec2 p = vUv;
    float core = exp(-r * r * 60.0) + 0.25 * exp(-r * r * 9.0);
    float spikes = exp(-abs(p.y) * 70.0) * exp(-abs(p.x) * 3.0) + exp(-abs(p.x) * 70.0) * exp(-abs(p.y) * 3.0);
    a = (core + vParam * spikes * 0.6) * win;
  } else {
    float aa = fwidth(r) * 1.5;
    a = 1.0 - smoothstep(1.0 - aa, 1.0, r);
  }
  a *= vColor.a;
  outColor = vec4(col * a * uGain, a);
}`;

export type Blend = 'add' | 'alpha';

export class SpriteBatch {
  private data: Float32Array;
  private count = 0;
  private vao: WebGLVertexArrayObject;
  private instanceBuf: WebGLBuffer;
  private cornerBuf: WebGLBuffer;

  constructor(
    private readonly gl: WebGL2RenderingContext,
    /** Null when the driver rejected it: the batch then queues and draws nothing. */
    private readonly program: Program | null,
    readonly blend: Blend,
    private capacity = 4096,
  ) {
    this.data = new Float32Array(capacity * FLOATS_PER_INSTANCE);
    const vao = gl.createVertexArray();
    const ib = gl.createBuffer();
    const cb = gl.createBuffer();
    if (!vao || !ib || !cb) throw new Error('Could not allocate sprite buffers');
    this.vao = vao;
    this.instanceBuf = ib;
    this.cornerBuf = cb;

    gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, cb);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    gl.bindBuffer(gl.ARRAY_BUFFER, ib);
    gl.bufferData(gl.ARRAY_BUFFER, this.data.byteLength, gl.DYNAMIC_DRAW);
    const stride = FLOATS_PER_INSTANCE * 4;
    for (let loc = 1; loc <= 3; loc++) {
      gl.enableVertexAttribArray(loc);
      gl.vertexAttribPointer(loc, 4, gl.FLOAT, false, stride, (loc - 1) * 16);
      gl.vertexAttribDivisor(loc, 1);
    }
    gl.bindVertexArray(null);
  }

  get size(): number {
    return this.count;
  }

  /**
   * Queue one sprite. Colour is linear HDR (values above 1 glow); `a` scales opacity/intensity.
   * `sx, sy` stretch the sprite along a world-space vector (motion blur); zero for round sprites.
   */
  push(
    x: number,
    y: number,
    radius: number,
    r: number,
    g: number,
    b: number,
    a: number,
    shape: Shape,
    param = 0,
    rot = 0,
    sx = 0,
    sy = 0,
  ): void {
    if (this.count >= this.capacity) this.grow();
    const o = this.count * FLOATS_PER_INSTANCE;
    const d = this.data;
    d[o] = x;
    d[o + 1] = y;
    d[o + 2] = radius;
    d[o + 3] = rot;
    d[o + 4] = r;
    d[o + 5] = g;
    d[o + 6] = b;
    d[o + 7] = a;
    d[o + 8] = shape;
    d[o + 9] = param;
    d[o + 10] = sx;
    d[o + 11] = sy;
    this.count++;
  }

  private grow(): void {
    this.capacity *= 2;
    const next = new Float32Array(this.capacity * FLOATS_PER_INSTANCE);
    next.set(this.data);
    this.data = next;
    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.instanceBuf);
    gl.bufferData(gl.ARRAY_BUFFER, next.byteLength, gl.DYNAMIC_DRAW);
  }

  /** `gain` takes light into the scene's range (below 1 when the scene is 8-bit). */
  draw(view: Float32Array, pxPerUnit: number, minPx: number, gain = 1): void {
    if (this.count === 0 || !this.program) return;
    const gl = this.gl;
    this.program.use();
    gl.uniform4fv(this.program.loc('uView'), view);
    this.program.f1('uPxPerUnit', pxPerUnit).f1('uMinPx', minPx).f1('uGain', gain);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.instanceBuf);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.data, 0, this.count * FLOATS_PER_INSTANCE);
    if (this.blend === 'add') gl.blendFunc(gl.ONE, gl.ONE);
    else gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    gl.bindVertexArray(this.vao);
    gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, this.count);
    gl.bindVertexArray(null);
  }

  clear(): void {
    this.count = 0;
  }

  dispose(): void {
    const gl = this.gl;
    gl.deleteVertexArray(this.vao);
    gl.deleteBuffer(this.instanceBuf);
    gl.deleteBuffer(this.cornerBuf);
  }
}

/** The sprite program, or null when the driver rejects it (sprites are then left out). */
export function createSpriteProgram(gl: WebGL2RenderingContext): Program | null {
  return tryProgram(gl, VS, FS, 'sprites');
}
