/**
 * The Forge is the warmest music in the game: a slow major harmony that keeps moving, with stars
 * being born as soft plucks pitched by their mass (heavy stars lower). Feeding a star rises in pitch
 * as it grows and rings a bell each time its fate changes. Deaths are scaled by what they are: an
 * airy chord for a planetary nebula, weight for a supernova, a blinding chord for a Type Ia, and a
 * gravitational-wave chirp that resolves into a gold chord for a kilonova.
 */
import type { EraAudio } from '../../audio/director';
import { blip, bell, noise, pluck, swell, thump } from '../../audio/patches';
import { SCALES, mtof, note, type Key } from '../../audio/scales';

const KEY: Key = { root: 41, scale: SCALES.majorPentatonic };

/** Heavier stars sound lower: about 0.5 Suns → high, 100 Suns → low. */
function massDegree(mass: number): number {
  return Math.round(14 - 3.2 * Math.log10(Math.max(0.3, mass) / 0.3));
}

export const FORGE_AUDIO: EraAudio = {
  key: KEY,
  bed: {
    id: 'forge',
    chords: [
      [41, 53, 57, 60, 67],
      [38, 50, 57, 60, 64],
      [46, 53, 58, 62, 65],
      [36, 48, 55, 60, 62],
    ],
    chordSeconds: 26,
    pad: { gain: 0.055, type: 'triangle', cutoff: 1100, detune: 6, lfo: 0.03 },
    drone: { note: 29, gain: 0.035 },
    air: { freq: 900, q: 0.5, gain: 0.008, drift: 0.02 },
    shimmer: { gain: 0.008, rate: 0.18 },
    level: 1.3,
  },
  cues: {
    'forge.birth': (a, p, c) => {
      const g = a.admit('forge.birth', 0.09);
      if (g) pluck(a, mtof(note(c.key, massDegree(p.pitch ?? 1) + 7)), { gain: 0.048 * g, decay: 0.6, tone: 4, pan: c.pan(p.x), bus: 'ambience' });
    },
    'forge.feed': (a, p, c) => {
      const g = a.admit('forge.feed', 0.2);
      if (g) blip(a, mtof(note(c.key, massDegree(p.pitch ?? 1) + 9)), { gain: 0.04 * g, dur: 0.18, drop: 0.97, pan: c.pan(p.x) });
    },
    'forge.fate': (a, p, c) => {
      if (!a.admit('forge.fate', 0.15)) return;
      const t = a.now;
      const d = massDegree(p.pitch ?? 1) + 7;
      bell(a, mtof(note(c.key, d)), { time: t, gain: 0.07, decay: 2.4, ratio: 2, bright: 0.6, pan: c.pan(p.x) });
      bell(a, mtof(note(c.key, d + 2)), { time: t + 0.09, gain: 0.05, decay: 2.2, ratio: 2, bright: 0.5, pan: c.pan(p.x) });
    },
    'forge.giant': (a, _p, c) => {
      const g = a.admit('forge.giant', 0.6);
      if (g) swell(a, [mtof(note(c.key, 2)), mtof(note(c.key, 4))], { attack: 1.2, hold: 0.4, release: 2.5, gain: 0.04 * g, cutoff: 700 });
    },
    'forge.pn': (a, p, c) => {
      const g = a.admit('forge.pn', 0.4);
      if (!g) return;
      const t = a.now;
      swell(a, [7, 9, 11, 14].map((d) => mtof(note(c.key, d))), { time: t, attack: 0.5, hold: 0.6, release: 3.5, gain: 0.06 * g, cutoff: 2600 });
      noise(a, { time: t, dur: 1.6, freq: 2400, to: 5200, q: 0.8, gain: 0.02 * g, attack: 0.4, pan: c.pan(p.x), bus: 'ambience' });
    },
    'forge.sn': (a, p, c) => {
      const g = a.admit('forge.sn', 0.25);
      if (!g) return;
      const t = a.now;
      thump(a, 38, { time: t, gain: 0.4 * g, dur: 2, pan: c.pan(p.x) });
      noise(a, { time: t, dur: 2.6, freq: 3800, to: 200, q: 0.6, gain: 0.1 * g, attack: 0.005, pan: c.pan(p.x) });
      bell(a, mtof(note(c.key, 5)), { time: t + 0.04, gain: 0.06 * g, decay: 3.6, ratio: 3.5, bright: 1.1, pan: c.pan(p.x) });
    },
    'forge.perfect': (a, p, c) => {
      if (!a.admit('forge.perfect', 0.4)) return;
      const t = a.now;
      thump(a, 33, { time: t, gain: 0.38, dur: 2.4, pan: c.pan(p.x) });
      [0, 2, 4, 7].forEach((d, i) =>
        bell(a, mtof(note(c.key, 12 + d)), { time: t + 0.03 + i * 0.05, gain: 0.07, decay: 3.2, ratio: 2, bright: 0.9, pan: c.pan(p.x) }),
      );
      noise(a, { time: t, dur: 3, freq: 5000, to: 300, q: 0.5, gain: 0.12, attack: 0.003, pan: c.pan(p.x) });
    },
    'forge.early': (a, p, c) => {
      const g = a.admit('forge.early', 0.2);
      if (g) blip(a, mtof(note(c.key, 3)), { gain: 0.03 * g, dur: 0.08, drop: 0.8, pan: c.pan(p.x) });
    },
    'forge.ia': (a, p, c) => {
      if (!a.admit('forge.ia', 0.5)) return;
      const t = a.now;
      thump(a, 30, { time: t, gain: 0.38, dur: 3, pan: c.pan(p.x) });
      noise(a, { time: t, dur: 4, freq: 6000, to: 400, q: 0.5, gain: 0.12, attack: 0.002, pan: c.pan(p.x) });
      swell(a, [41, 53, 60, 65, 69, 72].map(mtof), { time: t + 0.1, attack: 0.3, hold: 1.4, release: 6, gain: 0.16, cutoff: 4200 });
    },
    'forge.chirp': (a, p, c) => {
      // The last seconds of an inspiral: a tone sweeping up as the orbit tightens.
      const g = a.admit('forge.chirp', 1.5);
      if (g) noise(a, { dur: 2.2, freq: 120, to: 1800, q: 9, gain: 0.05 * g, attack: 1.6, pan: c.pan(p.x) });
    },
    'forge.kilonova': (a, p, c) => {
      if (!a.admit('forge.kilonova', 0.8)) return;
      const t = a.now;
      thump(a, 40, { time: t, gain: 0.4, dur: 2, pan: c.pan(p.x) });
      swell(a, [53, 57, 60, 64, 67, 72].map(mtof), { time: t + 0.05, attack: 0.6, hold: 1.6, release: 6, gain: 0.15, cutoff: 3600 });
      [0, 4, 7, 9].forEach((d, i) =>
        bell(a, mtof(note(c.key, 14 + d)), { time: t + 0.2 + i * 0.11, gain: 0.05, decay: 3.5, ratio: 2, bright: 0.7, pan: c.pan(p.x) }),
      );
    },
    'forge.merge': (a, p, c) => {
      if (!a.admit('forge.merge', 0.4)) return;
      thump(a, 28, { time: a.now, gain: 0.35, dur: 2.6, pan: c.pan(p.x) });
    },
    'forge.element': (a, p, c) => {
      // Lighter elements ring higher.
      const g = a.admit('forge.element', 0.12);
      const z = p.pitch ?? 26;
      if (g) bell(a, mtof(note(c.key, 21 - Math.round(z / 9))), { gain: 0.05 * g, decay: 2, ratio: 2, bright: 0.5, pan: c.pan(p.x) });
    },
    'forge.grb': (a, p, c) => {
      if (!a.admit('forge.grb', 0.6)) return;
      const t = a.now;
      noise(a, { time: t, dur: 1.4, freq: 8000, to: 600, q: 1.2, gain: 0.1, attack: 0.002, pan: c.pan(p.x) });
      bell(a, mtof(note(c.key, 16)), { time: t + 0.05, gain: 0.07, decay: 4, ratio: 3, bright: 1.2, pan: c.pan(p.x) });
    },
    'forge.pair': (a, p, c) => {
      if (!a.admit('forge.pair', 0.3)) return;
      const t = a.now;
      pluck(a, mtof(note(c.key, 9)), { time: t, gain: 0.05, decay: 0.8, tone: 5, pan: c.pan(p.x) });
      pluck(a, mtof(note(c.key, 11)), { time: t + 0.08, gain: 0.05, decay: 0.8, tone: 5, pan: c.pan(p.x) });
    },
    'forge.nogas': (a, p, c) => {
      const g = a.admit('forge.nogas', 0.3);
      if (g) noise(a, { dur: 0.25, freq: 300, to: 180, q: 1.5, gain: 0.025 * g, attack: 0.02, pan: c.pan(p.x) });
    },
    'forge.arm': (a, _p, c) => {
      swell(a, [0, 2, 4].map((d) => mtof(note(c.key, d + 5))), { attack: 2.5, hold: 2, release: 5, gain: 0.05, cutoff: 1200 });
    },
    'forge.sun': (a, _p, c) => {
      const t = a.now;
      swell(a, [41, 48, 53, 57, 60, 64].map(mtof), { time: t, attack: 2.2, hold: 2.4, release: 7, gain: 0.14, cutoff: 2200 });
      bell(a, mtof(note(c.key, 12)), { time: t + 1.2, gain: 0.06, decay: 4, ratio: 2, bright: 0.3 });
    },
    'forge.milestone': (a, _p, c) => {
      const t = a.now;
      swell(a, [41, 48, 53, 57, 60].map(mtof), { bus: 'music', time: t, attack: 1.6, hold: 1, release: 5, gain: 0.12, cutoff: 1800 });
      bell(a, mtof(note(c.key, 9)), { bus: 'music', time: t + 0.5, gain: 0.05, decay: 3.5, ratio: 2, bright: 0.4 });
    },
    'forge.complete': (a) => {
      const t = a.now;
      thump(a, 29, { time: t, gain: 0.3, dur: 2.8 });
      swell(a, [41, 48, 53, 57, 60, 64, 69].map(mtof), { time: t + 0.4, attack: 3, hold: 3, release: 9, gain: 0.2, cutoff: 3000 });
    },
  },
};
