/**
 * The pull-back between eras (Powers of Ten: every era ends by drawing back from it, and what it made
 * becomes a building block of the next, at a scale far larger).
 *
 * Recede: the camera draws back on an easing that keeps speeding up, the light dims, and a window
 * closing on the old frame keeps its media (fields, volumes) from spilling into the dark around it, so
 * what was on screen ends as a field of points at the centre. Hold: the next era is entered. Arrive:
 * the new era fades in at its own scale while still settling back from close, and the old frame, held
 * as a still, goes on shrinking into the centre at the rate the new camera draws back, fading out
 * inside it. One continuous motion outward, about 3.8 s in all.
 *
 * With reduce motion it is a crossfade: no camera move, the still dissolving in place.
 */
import type { Camera } from './camera';

const RECEDE = 2.1;
const ARRIVE = 1.7;
const STILL_RECEDE = 0.5;
const STILL_ARRIVE = 1.4;
/** How far the new era's camera starts in close (×): it settles back from there to its rest. */
export const CLOSE = 4;

export type PullBackPhase = 'idle' | 'recede' | 'held' | 'arrive';

const smooth = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

/**
 * Fades run in stops, not in linear light: the tonemapper is logarithmic, so a linear ramp leaves a
 * scene at 4 % looking merely dim. `v` 1 is full light, 0 is black, and 0.5 is five stops down.
 */
const FADE_STOPS = 10;
const light = (v: number) => (v <= 0 ? 0 : v >= 1 ? 1 : 2 ** (-FADE_STOPS * (1 - v)));

export class PullBack {
  phase: PullBackPhase = 'idle';
  /** Gain on the live scene, in linear light (1: untouched). */
  live = 1;
  /** Half size of the window the live scene shows through, in screen half-extents (0: none). */
  window = 0;
  /** Gain on the old frame's still (linear light), and how many times smaller than the screen it is drawn. */
  ghost = 0;
  ghostScale = 1;
  /** Set for one frame at the end of the recede: the renderer keeps that frame as the still. */
  capture = false;

  private t = 0;
  private distance = 30;
  private recedeFor = RECEDE;
  private arriveFor = ARRIVE;
  private reduced = false;
  private done: (() => void) | null = null;

  constructor(private readonly camera: Camera) {}

  /** A crossfade in place (reduce motion): the camera doesn't move. */
  get still(): boolean {
    return this.reduced;
  }

  /** True from the start of a recede to the end of the arrival (input is held off meanwhile). */
  get active(): boolean {
    return this.phase !== 'idle';
  }

  /**
   * Draws back from the scene by `distance` (×). Resolves on the frame the old scene is fully
   * receded and kept as the still: enter the next era then, and call `arrive()`.
   */
  recede(distance: number, reduceMotion: boolean, timing?: { recede: number; arrive: number }): Promise<void> {
    this.phase = 'recede';
    this.t = 0;
    this.distance = Math.max(1.5, distance);
    this.recedeFor = timing?.recede ?? RECEDE;
    this.arriveFor = timing?.arrive ?? ARRIVE;
    this.reduced = reduceMotion;
    this.capture = false;
    return new Promise((resolve) => (this.done = resolve));
  }

  /** The next era is in place: fade it in. Does nothing unless a recede just finished. */
  arrive(): void {
    if (this.phase !== 'held') return;
    this.phase = 'arrive';
    this.t = 0;
  }

  /**
   * Back at rest. Also cancels a pull-back for a reset or a new universe: a recede still pending is
   * dropped, never resolved, so the era it belonged to does not hand over into the new state.
   */
  stop(): void {
    this.phase = 'idle';
    this.camera.distance = 1;
    this.live = 1;
    this.window = 0;
    this.ghost = 0;
    this.ghostScale = 1;
    this.capture = false;
    this.done = null;
  }

  update(dt: number): void {
    this.capture = false;
    const cam = this.camera;
    if (this.phase === 'recede') {
      this.t += dt;
      const u = Math.min(1, this.t / (this.reduced ? STILL_RECEDE : this.recedeFor));
      if (this.reduced) {
        cam.distance = 1;
        this.window = 0;
        this.live = light(1 - 0.08 * smooth(0, 1, u));
      } else {
        // Log-distance on an ease-in: slow to leave, full speed at the hand-over, where the arrival's
        // ease-out takes the same speed on (so the two read as one move).
        const d = Math.exp(Math.log(this.distance) * u * u);
        cam.distance = d;
        // The old frame on screen, a hair larger than itself, opening in as the move gets going.
        this.window = (1.06 / d) * smooth(0, 0.3, u) + 4 * (1 - smooth(0, 0.3, u));
        this.live = light(1 - 0.15 * smooth(0.15, 1, u));
      }
      this.ghost = 0;
      if (u >= 1) {
        this.phase = 'held';
        this.capture = true;
        const done = this.done;
        this.done = null;
        done?.();
      }
      return;
    }
    if (this.phase === 'held') {
      // Waiting for the next era to be entered: the screen holds still (the new era may draw a frame
      // before it arrives, unseen).
      this.live = 0;
      this.ghost = 1;
      this.ghostScale = 1;
      this.window = 0;
      cam.distance = this.reduced ? 1 : 1 / CLOSE;
      return;
    }
    if (this.phase === 'arrive') {
      this.t += dt;
      const u = Math.min(1, this.t / (this.reduced ? STILL_ARRIVE : this.arriveFor));
      this.window = 0;
      if (this.reduced) {
        cam.distance = 1;
        this.ghostScale = 1;
        this.live = light(smooth(0.3, 1, u));
        this.ghost = light(1 - smooth(0, 0.7, u));
      } else {
        // A cubic ease-out in log-distance, taking on near the recede's last speed, gentle enough
        // that the new era is seen settling back as it comes out of the dark.
        const e = 1 - (1 - u) ** 3;
        cam.distance = Math.exp(-Math.log(CLOSE) * (1 - e));
        // The old frame lies at the centre of the new one: it shrinks exactly as the camera draws back.
        this.ghostScale = CLOSE * cam.distance;
        this.live = light(smooth(0, 0.7, u));
        this.ghost = light(1 - smooth(0.15, 0.85, u));
      }
      if (u >= 1) this.stop();
    }
  }
}
