<!--
  The foam: universes as soap-film bubbles drifting in the dark. The one that just ended sits large and
  warm, budding at its rim (one bud per order of magnitude of black holes it made); the seed being
  looked at lights its bud. On the first visit everything pulls back from very close.
-->
<script lang="ts">
  import { onMount } from 'svelte';

  let { buds = 12, highlight = -1, seeds = 3, pull = false }: { buds?: number; highlight?: number; seeds?: number; pull?: boolean } = $props();

  let canvas: HTMLCanvasElement;

  interface Bubble {
    x: number;
    y: number;
    r: number;
    vx: number;
    vy: number;
    hue: [number, number, number];
    a: number;
    ph: number;
  }

  onMount(() => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    let w = 0;
    let h = 0;
    let dpr = 1;
    const fit = () => {
      dpr = Math.min(2, window.devicePixelRatio || 1);
      w = window.innerWidth;
      h = window.innerHeight;
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
    };
    fit();
    window.addEventListener('resize', fit);

    // A fixed scatter (the same each visit), so the foam feels like a place.
    let seed = 7;
    const rnd = () => ((seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0) / 4294967296);
    const palette: [number, number, number][] = [
      [188, 208, 255],
      [255, 214, 170],
      [214, 190, 255],
      [170, 236, 222],
      [255, 190, 190],
    ];
    const bubbles: Bubble[] = Array.from({ length: 70 }, () => ({
      x: rnd(),
      y: rnd(),
      r: 6 + 90 * rnd() ** 2.2,
      vx: (rnd() - 0.5) * 0.004,
      vy: (rnd() - 0.5) * 0.003,
      hue: palette[Math.floor(rnd() * palette.length)],
      a: 0.05 + 0.12 * rnd(),
      ph: rnd() * 6.28,
    }));

    const film = (x: number, y: number, r: number, c: [number, number, number], a: number) => {
      const g = ctx.createRadialGradient(x, y, r * 0.55, x, y, r);
      g.addColorStop(0, `rgba(${c[0]},${c[1]},${c[2]},0)`);
      g.addColorStop(0.82, `rgba(${c[0]},${c[1]},${c[2]},${a * 0.35})`);
      g.addColorStop(0.97, `rgba(${c[0]},${c[1]},${c[2]},${a})`);
      g.addColorStop(1, `rgba(${c[0]},${c[1]},${c[2]},0)`);
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    };

    const t0 = performance.now();
    let last = t0;
    let raf = 0;
    const frame = (now: number) => {
      const t = (now - t0) / 1000;
      const dt = Math.min(0.1, (now - last) / 1000);
      last = now;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      // The pull-back: from inside the bubble to the whole foam over ~9 s.
      const k = pull ? Math.min(1, t / 9) : 1;
      const ease = 1 - (1 - k) ** 3;
      const zoom = 1 + 14 * (1 - ease);
      const hx = w * 0.5;
      const hy = h * 0.4;
      ctx.save();
      ctx.translate(hx, hy);
      ctx.scale(zoom, zoom);
      ctx.translate(-hx, -hy);
      for (const b of bubbles) {
        // Drift, wrapping around a margin just outside the screen.
        b.x = ((b.x + 0.1 + b.vx * dt) % 1.2 + 1.2) % 1.2 - 0.1;
        b.y = ((b.y + 0.1 + b.vy * dt) % 1.2 + 1.2) % 1.2 - 0.1;
        const breathe = 1 + 0.03 * Math.sin(t * 0.4 + b.ph);
        film(b.x * w, b.y * h, b.r * breathe, b.hue, b.a * ease);
      }
      // The universe that just ended.
      const R = Math.min(w, h) * 0.16;
      const glow = ctx.createRadialGradient(hx, hy, 0, hx, hy, R * 1.6);
      glow.addColorStop(0, 'rgba(255,226,190,0.10)');
      glow.addColorStop(0.6, 'rgba(255,200,150,0.05)');
      glow.addColorStop(1, 'rgba(255,190,140,0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(hx, hy, R * 1.6, 0, Math.PI * 2);
      ctx.fill();
      film(hx, hy, R, [255, 222, 186], 0.55);
      // Buds at its rim, slowly turning; the ones that would become the offered seeds come first.
      for (let i = 0; i < buds; i++) {
        const a = (i / buds) * Math.PI * 2 + t * 0.03;
        const bx = hx + Math.cos(a) * R * 1.02;
        const by = hy + Math.sin(a) * R * 1.02;
        const isSeed = i < seeds;
        const lit = i === highlight;
        const br = (isSeed ? 3.2 : 2.2) + (lit ? 4 : 0) + 0.6 * Math.sin(t * 1.3 + i);
        const bg = ctx.createRadialGradient(bx, by, 0, bx, by, br * 3);
        const al = lit ? 0.95 : isSeed ? 0.7 : 0.4;
        bg.addColorStop(0, `rgba(255,240,220,${al})`);
        bg.addColorStop(0.35, `rgba(255,220,180,${al * 0.5})`);
        bg.addColorStop(1, 'rgba(255,200,160,0)');
        ctx.fillStyle = bg;
        ctx.beginPath();
        ctx.arc(bx, by, br * 3, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', fit);
    };
  });
</script>

<canvas class="foam" bind:this={canvas} aria-hidden="true"></canvas>

<style>
  .foam {
    position: fixed;
    inset: 0;
    width: 100vw;
    height: 100vh;
    display: block;
    pointer-events: none;
  }
</style>
