/**
 * Readings and actions shared by both interfaces (the v1 HUD and the frame): how a stock, a buy and
 * the menu read from the game, so each layout only decides where and how they are drawn.
 */
import type { Game } from '../core/game';
import type { StockView } from '../core/era';
import type { PhenomenonDef } from '../core/phenomena';
import { count, decimal, energy, percent, type EnergyUnit, type NumParts } from '../core/format';
import { audio, ui, type Panel } from './store.svelte';

/** eV until the universe has crossed a joule, joules from then on. */
export function energyUnit(g: Game): EnergyUnit {
  return g.state.run.joules ? 'J' : 'eV';
}

export function formatStock(g: Game, s: StockView, value: number): NumParts {
  switch (s.format) {
    case 'energy':
      return energy(value, energyUnit(g), g.state.settings.notation);
    case 'decimal':
      return decimal(value, 3);
    case 'percent':
      return percent(value, 3);
    default:
      return count(value, g.state.settings.notation);
  }
}

/** Levels a click buys: one-shots buy one; Ctrl buys the most, Shift ten, otherwise the chosen amount. */
export function buyAmount(def: PhenomenonDef, ctrl: boolean, shift: boolean): number {
  if (def.max === 1) return 1;
  return ctrl ? Infinity : shift ? 10 : ui.buyMode;
}

/** What buying `mode` levels would take now: how many levels and their total cost (at least one level). */
export function planBuy(g: Game, def: PhenomenonDef, mode: number): { n: number; cost: number } {
  const lvl = g.level(def.id);
  const max = def.max ?? Infinity;
  const budget = g.energy;
  let n = 0;
  let cost = 0;
  while (n < mode && lvl + n < max && n < 1000) {
    const c = def.cost(lvl + n);
    if (mode === Infinity && n > 0 && cost + c > budget) break;
    if (mode === Infinity && n === 0 && c > budget) {
      cost = c;
      n = 1;
      break;
    }
    cost += c;
    n++;
  }
  return { n: Math.max(1, n), cost };
}

/** A click on a phenomenon: buys with the modifiers held, and sounds a refusal if nothing was bought. */
export function buyByClick(g: Game, def: PhenomenonDef, e: MouseEvent): void {
  if (g.buy(def.id, buyAmount(def, e.ctrlKey || e.metaKey, e.shiftKey)) === 0) audio().cue('ui.deny', {});
}

export type PhenomenonItem =
  | { kind: 'card'; def: PhenomenonDef; key: number | null }
  | { kind: 'group'; id: string; title: string; progress: [number, number] | null };

/** The era's visible phenomena in order, with group headings and the 1–9 keys of the unmaxed ones. */
export function phenomenaItems(g: Game): { items: PhenomenonItem[]; any: boolean; levelled: boolean } {
  const list = g.visiblePhenomena(g.state.run.era);
  const groups = g.eraDef.groups ?? {};
  const items: PhenomenonItem[] = [];
  const seen = new Set<string>();
  let hot = 1;
  for (const def of list) {
    if (def.group && !seen.has(def.group)) {
      seen.add(def.group);
      const gd = groups[def.group];
      items.push({ kind: 'group', id: def.group, title: gd?.title ?? def.group, progress: gd?.progress?.(g) ?? null });
    }
    items.push({ kind: 'card', def, key: !g.isMaxed(def.id) && hot <= 9 ? hot++ : null });
  }
  return { items, any: list.length > 0, levelled: list.some((d) => d.max !== 1) };
}

export const BUY_MODES = [
  { m: 1, label: '×1' },
  { m: 10, label: '×10' },
  { m: Infinity, label: 'Max' },
] as const;

/** Which menu entries exist yet, and whether the codex has entries not yet read. */
export function menuState(g: Game): { unread: boolean; codex: boolean; universe: boolean } {
  const d = g.state.codex.discovered;
  const r = g.state.codex.read;
  let unread = false;
  for (const id in d)
    if (!r[id]) {
      unread = true;
      break;
    }
  return { unread, codex: Object.keys(d).length > 0, universe: g.state.run.history.length > 1 };
}

export function togglePanel(p: Panel): void {
  ui.panel = ui.panel === p ? null : p;
  audio().cue('ui.open', {});
}

/** The next epoch step, or a refusal sound when it can't be taken yet. */
export function advance(g: Game): void {
  if (!g.advance()) audio().cue('ui.deny', {});
}
