/**
 * Thin WebGL2 helpers: capability detection, shader programs with readable errors, render targets,
 * texture binding that keeps a target from being sampled while it is drawn into, and the full-screen
 * triangle used by every post-processing pass.
 */

export interface GLCaps {
  /** Can we render into half-float targets (HDR)? */
  hdr: boolean;
  /** Can we render into sRGB-encoded 8-bit targets (the fallback without HDR)? */
  srgb: boolean;
  /** Can we linearly filter float textures? */
  floatLinear: boolean;
  maxTextureSize: number;
  renderer: string;
}

export function detectCaps(gl: WebGL2RenderingContext): GLCaps {
  const colorFloat = !!gl.getExtension('EXT_color_buffer_float');
  const colorHalf = !!gl.getExtension('EXT_color_buffer_half_float');
  const floatLinear = !!gl.getExtension('OES_texture_float_linear');
  const dbg = gl.getExtension('WEBGL_debug_renderer_info');
  return {
    hdr: colorFloat || colorHalf,
    srgb: renders(gl, gl.SRGB8_ALPHA8),
    floatLinear,
    maxTextureSize: gl.getParameter(gl.MAX_TEXTURE_SIZE) as number,
    renderer: String(dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER)),
  };
}

/** Whether a framebuffer with a texture of this format attached is complete (a 1×1 probe). */
function renders(gl: WebGL2RenderingContext, internal: number): boolean {
  const tex = gl.createTexture();
  const fbo = gl.createFramebuffer();
  if (!tex || !fbo) return false;
  gl.bindTexture(gl.TEXTURE_2D, tex);
  gl.texStorage2D(gl.TEXTURE_2D, 1, internal, 1, 1);
  gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
  const ok = gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE;
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  gl.bindTexture(gl.TEXTURE_2D, null);
  gl.deleteFramebuffer(fbo);
  gl.deleteTexture(tex);
  return ok;
}

/**
 * Without float targets the scene is kept in 8 bits per channel, sRGB-encoded (blending stays linear:
 * the GPU decodes, blends and re-encodes, and the dark end keeps its precision), with all light scaled
 * down by this range on the way in and back up when it is read. Light up to 8 (three stops above white)
 * keeps its differences, enough for bloom and glare to find the brightest points; beyond it, it clips.
 */
export const LDR_RANGE = 8;

/**
 * How a target stores light. 'half': half floats (HDR). 'srgb': 8 bits, sRGB-encoded (the fallback
 * without float targets; values above 1 clip, so light goes in scaled by 1 / LDR_RANGE). 'rgba8': plain
 * 8 bits. A boolean is the older form: true for 'half', false for 'rgba8'.
 */
export type TargetFormat = 'half' | 'srgb' | 'rgba8';

/** The format light is kept in on this device: half floats if it can render them, else sRGB 8-bit. */
export function lightFormat(caps: GLCaps): TargetFormat {
  return caps.hdr ? 'half' : caps.srgb ? 'srgb' : 'rgba8';
}

/** What light is multiplied by on its way into a target of this format (1 for HDR). */
export function lightGain(format: TargetFormat): number {
  return format === 'half' ? 1 : 1 / LDR_RANGE;
}

/**
 * What each texture unit holds on TEXTURE_2D, per context, as bound through `bindTexture`. A texture
 * still bound for sampling while its target is drawn into makes every draw that samples that unit a
 * feedback loop, which WebGL refuses without a word (nothing draws): `Target.bind` uses this to unbind
 * its own texture first, and the renderer clears every unit at the start of a frame.
 */
const units = new WeakMap<WebGL2RenderingContext, (WebGLTexture | null)[]>();

function boundUnits(gl: WebGL2RenderingContext): (WebGLTexture | null)[] {
  let u = units.get(gl);
  if (!u) units.set(gl, (u = []));
  return u;
}

/** Binds a texture for sampling on a unit (2D unless `target` says otherwise). */
export function bindTexture(gl: WebGL2RenderingContext, unit: number, tex: WebGLTexture | null, target: number = gl.TEXTURE_2D): void {
  gl.activeTexture(gl.TEXTURE0 + unit);
  gl.bindTexture(target, tex);
  if (target === gl.TEXTURE_2D) boundUnits(gl)[unit] = tex;
}

/** Leaves the first `count` texture units empty (2D and 3D), with unit 0 active. */
export function unbindTextures(gl: WebGL2RenderingContext, count = 8): void {
  for (let i = count - 1; i >= 0; i--) {
    gl.activeTexture(gl.TEXTURE0 + i);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.bindTexture(gl.TEXTURE_3D, null);
  }
  boundUnits(gl).length = 0;
}

/** Unbinds a texture from every unit it is bound on (as far as `bindTexture` knows). */
function release(gl: WebGL2RenderingContext, tex: WebGLTexture): void {
  const u = units.get(gl);
  if (!u) return;
  for (let i = 0; i < u.length; i++) {
    if (u[i] !== tex) continue;
    gl.activeTexture(gl.TEXTURE0 + i);
    gl.bindTexture(gl.TEXTURE_2D, null);
    u[i] = null;
  }
}

function annotate(source: string, log: string): string {
  const lines = source.split('\n');
  const bad = new Set<number>();
  for (const m of log.matchAll(/ERROR: \d+:(\d+)/g)) bad.add(Number(m[1]));
  return lines
    .map((l, i) => `${bad.has(i + 1) ? '>>' : '  '}${String(i + 1).padStart(4)} ${l}`)
    .join('\n');
}

function compile(gl: WebGL2RenderingContext, type: number, source: string, name: string): WebGLShader {
  const sh = gl.createShader(type);
  if (!sh) throw new Error(`Could not create shader ${name}`);
  gl.shaderSource(sh, source);
  gl.compileShader(sh);
  if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS) && !gl.isContextLost()) {
    const log = gl.getShaderInfoLog(sh) ?? '';
    gl.deleteShader(sh);
    throw new Error(`Shader "${name}" failed to compile:\n${log}\n${annotate(source, log)}`);
  }
  return sh;
}

/** A linked program with cached uniform locations (and transform-feedback outputs, if named). */
export class Program {
  readonly handle: WebGLProgram;
  private locs = new Map<string, WebGLUniformLocation | null>();

  constructor(
    private readonly gl: WebGL2RenderingContext,
    vs: string,
    fs: string,
    readonly name: string,
    varyings?: string[],
  ) {
    const v = compile(gl, gl.VERTEX_SHADER, vs, `${name}.vert`);
    const f = compile(gl, gl.FRAGMENT_SHADER, fs, `${name}.frag`);
    const p = gl.createProgram();
    if (!p) throw new Error(`Could not create program ${name}`);
    gl.attachShader(p, v);
    gl.attachShader(p, f);
    if (varyings) gl.transformFeedbackVaryings(p, varyings, gl.INTERLEAVED_ATTRIBS);
    gl.linkProgram(p);
    gl.deleteShader(v);
    gl.deleteShader(f);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS) && !gl.isContextLost()) {
      throw new Error(`Program "${name}" failed to link:\n${gl.getProgramInfoLog(p)}`);
    }
    this.handle = p;
  }

  use(): this {
    this.gl.useProgram(this.handle);
    return this;
  }

  loc(name: string): WebGLUniformLocation | null {
    let l = this.locs.get(name);
    if (l === undefined) {
      l = this.gl.getUniformLocation(this.handle, name);
      this.locs.set(name, l);
    }
    return l;
  }

  f1(name: string, x: number): this {
    this.gl.uniform1f(this.loc(name), x);
    return this;
  }
  f2(name: string, x: number, y: number): this {
    this.gl.uniform2f(this.loc(name), x, y);
    return this;
  }
  f3(name: string, x: number, y: number, z: number): this {
    this.gl.uniform3f(this.loc(name), x, y, z);
    return this;
  }
  f4(name: string, x: number, y: number, z: number, w: number): this {
    this.gl.uniform4f(this.loc(name), x, y, z, w);
    return this;
  }
  i1(name: string, x: number): this {
    this.gl.uniform1i(this.loc(name), x);
    return this;
  }
  f4v(name: string, data: Float32Array): this {
    this.gl.uniform4fv(this.loc(name), data);
    return this;
  }

  dispose(): void {
    this.gl.deleteProgram(this.handle);
  }
}

/**
 * A program, or null when the driver rejects it (the reason is logged): the pass it was for is left
 * out and everything else keeps working, at boot, when an era attaches its look, and after a lost
 * context alike.
 */
export function tryProgram(gl: WebGL2RenderingContext, vs: string, fs: string, name: string, varyings?: string[]): Program | null {
  try {
    return new Program(gl, vs, fs, name, varyings);
  } catch (e) {
    console.error(e);
    return null;
  }
}

/** A colour texture with its framebuffer (optionally wrapping around at its edges). */
export class Target {
  tex: WebGLTexture;
  fbo: WebGLFramebuffer;
  width = 0;
  height = 0;
  readonly format: TargetFormat;

  constructor(
    private readonly gl: WebGL2RenderingContext,
    width: number,
    height: number,
    format: TargetFormat | boolean,
    private readonly linear = true,
    private readonly repeat = false,
  ) {
    this.format = format === true ? 'half' : format === false ? 'rgba8' : format;
    const tex = gl.createTexture();
    const fbo = gl.createFramebuffer();
    if (!tex || !fbo) throw new Error('Could not allocate render target');
    this.tex = tex;
    this.fbo = fbo;
    this.resize(width, height);
  }

  /** Half floats (HDR). */
  get hdr(): boolean {
    return this.format === 'half';
  }

  resize(width: number, height: number): void {
    const w = Math.max(1, Math.floor(width));
    const h = Math.max(1, Math.floor(height));
    if (w === this.width && h === this.height) return;
    this.width = w;
    this.height = h;
    const gl = this.gl;
    // Bound on unit 0 just for the upload, then unbound: never left where a pass would sample it.
    release(gl, this.tex);
    bindTexture(gl, 0, this.tex);
    if (this.format === 'half') gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, w, h, 0, gl.RGBA, gl.HALF_FLOAT, null);
    else if (this.format === 'srgb') gl.texImage2D(gl.TEXTURE_2D, 0, gl.SRGB8_ALPHA8, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
    else gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
    const filter = this.linear ? gl.LINEAR : gl.NEAREST;
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter);
    const wrap = this.repeat ? gl.REPEAT : gl.CLAMP_TO_EDGE;
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, wrap);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, wrap);
    bindTexture(gl, 0, null);
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.fbo);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, this.tex, 0);
    const status = gl.checkFramebufferStatus(gl.FRAMEBUFFER);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    if (status !== gl.FRAMEBUFFER_COMPLETE && !gl.isContextLost()) {
      throw new Error(`Render target incomplete (status 0x${status.toString(16)})`);
    }
  }

  /** Binds it for drawing into, unbinding its texture from any unit first (no feedback loop). */
  bind(): void {
    const gl = this.gl;
    release(gl, this.tex);
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.fbo);
    gl.viewport(0, 0, this.width, this.height);
  }

  /** Binds its texture for sampling on a unit. */
  sample(unit: number): void {
    bindTexture(this.gl, unit, this.tex);
  }

  dispose(): void {
    this.gl.deleteTexture(this.tex);
    this.gl.deleteFramebuffer(this.fbo);
  }
}

/** Vertex shader for a single oversized triangle covering the screen; `vUv` spans 0..1. */
export const FULLSCREEN_VS = /* glsl */ `#version 300 es
out vec2 vUv;
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  vUv = p;
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`;

export function drawFullscreen(gl: WebGL2RenderingContext, emptyVao: WebGLVertexArrayObject): void {
  gl.bindVertexArray(emptyVao);
  gl.drawArrays(gl.TRIANGLES, 0, 3);
}
