<!--
  Development only (never in a release build): skip ahead to test the whole game fast. Step takes the
  next epoch step now; Era runs the rest of the era to its finale, which plays as usual. Keys: ] and }.
-->
<script lang="ts">
  import { skipEra, skipStep } from '../../dev/skip';
  import { game, track } from '../store.svelte';

  const g = game();
  const busy = $derived.by(() => {
    track();
    return g.inFinale || g.passing || g.state.meta.atMultiverse;
  });

  function onKey(e: KeyboardEvent): void {
    if (e.key !== ']' && e.key !== '}') return;
    const t = e.target as HTMLElement | null;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
    e.preventDefault();
    if (e.key === '}') skipEra(g);
    else skipStep(g);
  }
</script>

<svelte:window onkeydown={onKey} />
<div class="skip" role="group" aria-label="Skip ahead (development)">
  <button type="button" disabled={busy} onclick={() => skipStep(g)} title="Take the next step now (])">Skip step</button>
  <button type="button" disabled={busy} onclick={() => skipEra(g)} title="Run the rest of this era to its finale (})">Skip era</button>
</div>

<style>
  .skip {
    position: fixed;
    right: 12px;
    bottom: 12px;
    z-index: 60;
    display: flex;
    gap: 6px;
    font-family: var(--sans);
  }
  button {
    font: inherit;
