export class ForgeEra implements EraModule {
  private readonly p = new Particles(1400);
  private readonly fx = new FxPool(900);
  private readonly s: ForgeState;
  private readonly bgParams: ForgeBgParams;
  /** How it all looks (version 2): the disk, its stars and motes, point-light stars, shells, the stream. */
  private readonly look = new ForgeLook();
  private readonly pairs = new Map<number, Pair>();
  private readonly made = new Set<number>();
  private shells: Shell[] = [];
  private beams: Beam[] = [];
  private tiles: Tile[] = [];
  private notes: Note[] = [];
  private halfW = 889;
  private halfH = 500;
  private t = 0;
  private idle = 0;

  private sfr = 1;
  private feed = 1;
  private imf = 2.35;
  private cno = 1;
  private giant = 1;
  private winds = 0;
  private pnMult = 1;
  private sproc = 0;
  private binary = 0.12;
  private accrete = 1;
  private pulsar = 0;
  private gw = 1;
  private rproc = 0;
  private density = 0;
  private feedback = 0;
  private inflow = 1;
  private snEnergy = 1;
  private iaEnergy = 1;
  private knEnergy = 1;

  private pDown = false;
  private pX = 0;
  private pY = 0;
  private feedId = 0;
  private dragId = 0;
  private hoverId = 0;
  private hoverT = 0;
  private feedSound = 0;
  private noGas = 0;
  private stream: { x0: number; y0: number; x1: number; y1: number } | null = null;
  private armX = -99999;
  private armK = 0;
  /** Stars drawn last frame: clouds pause while the patch is full, and resume as stars die. */
  private visibleStars = 0;
  private armWait = 6;
  private readonly starMeter = new RateMeter(30);
  /** Rates for time away (saved in the state), the counters they were last measured from, and production since then. */
  private readonly rates: ForgeRates;
  private readonly last = { pn: 0, sn: 0, ia: 0, kn: 0, wd: 0, ns: 0, bh: 0, zGas: 0 };
  private readonly prodSince = new Float64Array(120);
  private syncClock = 0;
  private intro = 0;
  private unsub: (() => void)[] = [];

  private finaleT = -1;
  private finaleDone: (() => void) | null = null;
  private tallied = false;
  /** Life was found here (the Observer known, the numbers friendly), and whether it is the first time. */
  private life = false;
  private lifeFull = false;

  constructor(private readonly g: Game) {
    const run = g.state.run;
    const legacyMetals = run.legacy.metals ?? 0;
    const z0 = legacyMetals > 0 ? Math.min(1.2e-3, Math.max(5e-5, 2e-4 * (legacyMetals / 1e33) ** 0.25)) : 2e-4;
    const saved = run.eras.forge as ForgeState | undefined;
    this.s = saved ?? defaults(z0);
    if (!saved) this.s.zGas = z0 * 820;
    this.s.prod ??= {};
    this.rates = this.s.rates ??= { pn: 0, sn: 0, ia: 0, kn: 0, wd: 0, ns: 0, bh: 0, metals: 0, prod: {} };
    run.eras.forge = this.s;
    for (const z of this.s.made) this.made.add(z);
    this.bgParams = {
      glow: 0.35,
      age: 0,
      gas: 1,
      arm: -99999,
      armK: 0,
      pulse: 0,
      finale: 0,
      aspect: 16 / 9,
      clouds: new Float32Array(MAX_BG_CLOUDS * 4),
      cloudsB: new Float32Array(MAX_BG_CLOUDS * 4),
      cloudCount: 0,
      hot: new Float32Array(MAX_BG_HOT * 4),
      hotCount: 0,
    };
  }

  // ───────────────────────────────────────── lifecycle

  enter(fresh: boolean): void {
    const g = this.g;
    const s = this.s;
    if (g.renderer) this.look.attach(g.renderer);
    this.refreshStats();
    this.unsub.push(g.stats.onChange(() => this.refreshStats()));
    this.starMeter.reset(s.starRate);
    this.syncStepFlags();
    this.markRates();
    // Long-lived stars that were drawn individually rejoin as part of the disk's light (the ones
    // that matter to the player were saved and come back as they were).
    s.field += s.visibleField;
    s.visibleField = 0;
    if (s.clouds.length) {
      for (const c of s.clouds) this.spawnCloud(c.x * this.halfW, c.y * this.halfH, c.w);
    } else {
      const rng = g.sim;
      for (let k = 0; k < 8; k++) {
        this.spawnCloud(rng.range(-0.75, 0.75) * this.field, rng.range(-0.72, 0.72) * this.field, rng.range(55, 130));
      }
    }
    this.restoreBodies();
    // Hydrogen and helium are here from the start: the Big Bang made them.
    for (const z of [1, 2]) this.makeElement(z, 0, 0, false);
    // A first scattering of stars, so the galaxy is already alive.
    if (fresh) {
      const clouds = this.indicesOf(CLOUD);
      for (let k = 0; k < 40; k++) {
        const c = clouds[k % clouds.length];
        this.birth(c, sampleImf(g.sim.next(), this.birthImf), true);
      }
      this.intro = 1.4;
    }
    if (s.sunFormed) this.spawnSun();
  }

  exit(): void {
    if (this.g.renderer) this.look.detach(this.g.renderer);
    for (const u of this.unsub) u();
    this.unsub = [];
    const cam = this.g.renderer?.camera;
    if (cam) {
      cam.zoom = 1;
      cam.x = 0;
      cam.y = 0;
    }
  }

  resize(halfW: number, halfH: number): void {
    const sx = halfW / this.halfW;
    this.halfW = halfW;
    this.halfH = halfH;
    this.bgParams.aspect = halfW / halfH;
    const p = this.p;
    for (let i = 0; i < p.n; i++) p.x[i] *= sx;
  }

  private refreshStats(): void {
    const st = this.g.stats;
    this.sfr = st.get('forge.sfr');
    this.feed = st.get('forge.feed');
    this.imf = st.get('forge.imf');
    this.cno = st.get('forge.cno');
    this.giant = st.get('forge.giant');
    this.winds = st.get('forge.winds');
    this.pnMult = st.get('forge.pn');
    this.sproc = st.get('forge.sproc');
    this.binary = st.get('forge.binary');
    this.accrete = st.get('forge.accrete');
    this.pulsar = st.get('forge.pulsar');
    this.gw = st.get('forge.gw');
    this.rproc = st.get('forge.rproc');
    this.density = st.get('forge.density');
    this.feedback = st.get('forge.feedback');
    this.inflow = st.get('forge.inflow');
    this.snEnergy = st.get('forge.snEnergy');
    this.iaEnergy = st.get('forge.iaEnergy');
    this.knEnergy = st.get('forge.knEnergy');
  }

  private get step(): number {
    return this.g.state.run.step;
  }

  /** How many real stars one simulated star stands for. */
  private get weight(): number {
    return 1e3 * 10 ** this.step;
  }

  private syncStepFlags(): void {
    for (let i = 1; i <= 6; i++) this.g.setFlag(`forge.step${i}`, this.step >= i);
  }

  private indicesOf(kind: number): number[] {
    const p = this.p;
    const out: number[] = [];
    for (let i = 0; i < p.n; i++) if (!p.isDead(i) && p.kind[i] === kind) out.push(i);
    return out;
  }

  /** Half the width of the frame's square field in world units (min(76vh, 54vw) across): where clouds condense. */
  private get field(): number {
    return Math.min(0.76 * this.halfH, 0.54 * this.halfW);
  }

  // ───────────────────────────────────────── gas and metals

  private cloudRadius(w: number): number {
    return 46 + 8.5 * Math.sqrt(Math.max(0, w));
  }

  private spawnCloud(x: number, y: number, w: number): number {
    const i = this.p.spawn(CLOUD, x, y, 0, 0, this.cloudRadius(w), w);
    if (i >= 0) {
      this.p.a[i] = this.g.sim.next();
      this.p.sub[i] = this.g.sim.int(256);
    }
    return i;
  }

  private gasTotal(): number {
    const p = this.p;
    let g = this.s.diffuse;
    for (let i = 0; i < p.n; i++) if (!p.isDead(i) && (p.kind[i] === CLOUD || p.kind[i] === GAS)) g += p.w[i];
    return g;
  }

  private get metallicity(): number {
    return Math.max(0, this.s.zGas / Math.max(1, this.gasTotal()));
  }

  /**
   * The slope of the mass function clouds form stars with. Metal-poor gas cools poorly, so its
   * clouds fragment into fewer, heavier stars: the young galaxy's mass function is top-heavy, and
   * it settles toward the present-day one as the gas grows richer.
   */
  private get birthImf(): number {
    return this.imf - TOP_HEAVY * Math.max(0, 1 - Math.sqrt(this.metallicity / (0.5 * Z_SUN)));
  }

  /** Star formation speeds up in metal-rich gas, which cools far better. */
  private zFactor(z: number): number {
    return 1 + 1.8 * Math.sqrt(Math.min(1.5, z / Z_SUN));
  }

  /** Takes up to `amount` of gas from the cloud nearest (x, y), or the diffuse pool. Returns what it got and from where. */
  private takeGas(x: number, y: number, amount: number): { got: number; cx: number; cy: number } {
    const p = this.p;
    let best = -1;
    let bd = Infinity;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i) || p.kind[i] !== CLOUD || p.w[i] < 0.5) continue;
      const d = (p.x[i] - x) ** 2 + (p.y[i] - y) ** 2;
      if (d < bd) {
        bd = d;
        best = i;
      }
    }
    const z = this.metallicity;
    if (best >= 0) {
      const got = Math.min(amount, p.w[best] - 0.2);
      p.w[best] -= got;
      p.r[best] = this.cloudRadius(p.w[best]);
      this.s.zGas = Math.max(0, this.s.zGas - got * z);
      return { got, cx: p.x[best], cy: p.y[best] };
    }
    const got = Math.min(amount, this.s.diffuse);
    this.s.diffuse -= got;
    this.s.zGas = Math.max(0, this.s.zGas - got * z);
    return { got, cx: x, cy: y };
  }

  private updateGas(dt: number): void {
    const s = this.s;
    const p = this.p;
    const rng = this.g.sim;
    // Fresh gas falls in more slowly as the galaxy fills: its own feedback holds the rest off.
    s.diffuse += INFLOW_BASE * this.inflow * Math.max(0, 1 - this.gasTotal() / GAS_FULL) * dt;
    const clouds = this.indicesOf(CLOUD);
    // Diffuse gas settles onto clouds, the bigger ones faster, up to what a cloud can hold.
    if (clouds.length && s.diffuse > 0) {
      const flow = s.diffuse * (1 - Math.exp(-0.05 * dt));
      let total = 0;
      for (const i of clouds) if (p.w[i] < CLOUD_FULL) total += Math.sqrt(p.w[i] + 10);
      let moved = 0;
      for (const i of clouds) {
        if (p.w[i] >= CLOUD_FULL || total <= 0) continue;
        const add = Math.min(CLOUD_FULL - p.w[i], (flow * Math.sqrt(p.w[i] + 10)) / total);
        p.w[i] += add;
        p.r[i] = this.cloudRadius(p.w[i]);
        moved += add;
      }
      s.diffuse -= moved;
    }
    // New clouds condense when there are too few; huge ones fragment.
    if (clouds.length < CLOUD_MIN && s.diffuse > 30) {
      this.spawnCloud(rng.range(-0.75, 0.75) * this.field, rng.range(-0.72, 0.72) * this.field, 30);
      s.diffuse -= 30;
    }
    for (const i of clouds) {
      if (p.w[i] > 420 && clouds.length < CLOUD_MAX) {
        const half = p.w[i] / 2;
        p.w[i] = half;
        p.r[i] = this.cloudRadius(half);
        const a = rng.angle();
        this.spawnCloud(p.x[i] + Math.cos(a) * p.r[i], p.y[i] + Math.sin(a) * p.r[i], half);
      }
    }
  }

  /** Dying stars return gas as fast-moving debris that joins the nearest cloud it reaches. */
  private ejecta(x: number, y: number, mass: number, sub: number, speed: number): void {
    if (mass <= 0) return;
    // Debris is drawn while there is room; past that, its gas goes straight to the nearest cloud.
    if (this.p.n > this.p.cap - 320) {
      this.returnGas(x, y, mass, 0);
      return;
    }
    const rng = this.g.sim;
    const n = Math.max(4, Math.min(14, Math.round(4 + mass)));
    for (let k = 0; k < n; k++) {
      const a = rng.angle();
      const v = speed * rng.range(0.5, 1.2);
      const i = this.p.spawn(GAS, x, y, Math.cos(a) * v, Math.sin(a) * v, 4, mass / n, sub);
      if (i >= 0) this.p.life[i] = rng.range(8, 14);
      else this.s.diffuse += mass / n;
    }
  }

  // ───────────────────────────────────────── stars

  private starSize(m: number): number {
    return 3.2 + 2.6 * Math.log10(1 + luminosity(m)) ** 0.85;
  }

  private setStarMass(i: number, m: number): void {
    this.p.w[i] = m;
    this.p.r[i] = Math.max(11, this.starSize(m) * 1.1);
  }

  /**
   * A star is born inside cloud `c` (or at a given point) with mass `m`, paying for itself with the
   * cloud's gas. Returns its index, or −1 if it went straight into the unresolved disk.
   */
  private birth(c: number, m: number, allowPair: boolean, at?: { x: number; y: number }): number {
    const p = this.p;
    const g = this.g;
    const rng = g.sim;
    const s = this.s;
    const cx = at ? at.x : p.x[c];
    const cy = at ? at.y : p.y[c];
    const crowded = p.n >= p.cap - 60;
    // A star that will die must be drawn; with no room for it, the cloud keeps its gas for now.
    if (crowded && m >= ETERNAL_MASS) return -1;
    const { got } = this.takeGas(cx, cy, m);
    if (got < m * 0.6) return -1;
    m = got;
    if (m < ETERNAL_MASS && !at && (crowded || this.countOf(STAR) >= HARD_CAP)) {
      this.countBirth();
      s.field += lightUnits(luminosity(m));
      return -1;
    }
    let x = cx;
    let y = cy;
    if (!at) {
      const R = p.r[c] * 0.55;
      const a = rng.angle();
      const d = R * Math.sqrt(rng.next());
      x += Math.cos(a) * d;
      y += Math.sin(a) * d;
    }
    const i = p.spawn(STAR, x, y, 0, 0, 10, m, this.metallicity < 0.1 * Z_SUN ? 0 : 1);
    if (i < 0) {
      this.returnGas(cx, cy, m, 0);
      return -1;
    }
    this.countBirth();
    this.setStarMass(i, m);
    p.a[i] = 0;
    p.b[i] = rng.next() * Math.PI * 2;
    if (!at) g.sfx('forge.birth', x, 1, m);
    if (allowPair && rng.chance(this.binary) && p.n < p.cap - 150) {
      const q = rng.range(0.3, 1);
      const j = this.birth(c, m * q, false, { x: x + 20, y });
      if (j >= 0) {
        const sep = rng.range(16, 28);
        this.makePair(p.id[i], p.id[j], sep, rng.angle());
      }
    }
    return i;
  }

  private countOf(kind: number): number {
    return this.p.countOf(kind);
  }

  private countBirth(): void {
    this.s.stars += this.weight;
    this.starMeter.add(this.weight);
  }

  private makePair(a: number, b: number, sep: number, phase: number): void {
    const pair: Pair = { a, b, sep, phase, chirped: false, ripple: 1 };
    this.pairs.set(a, pair);
    this.pairs.set(b, pair);
  }

  private unpair(pair: Pair): void {
    this.pairs.delete(pair.a);
    this.pairs.delete(pair.b);
  }

  /** Replaces a pair member's id (a star became a remnant). */
  private repair(oldId: number, newId: number): void {
    const pair = this.pairs.get(oldId);
    if (!pair) return;
    this.pairs.delete(oldId);
    if (pair.a === oldId) pair.a = newId;
    else pair.b = newId;
    this.pairs.set(newId, pair);
  }

  /** Life left in seconds of play. */
  private remaining(i: number): number {
    const life = gameLife(this.p.w[i]);
    return Number.isFinite(life) ? (1 - this.p.a[i]) * life : Infinity;
  }

  /** Light units a star gives per second right now. */
  private starUnits(i: number): number {
    const p = this.p;
    const m = p.w[i];
    let u = lightUnits(luminosity(m));
    if (m > 1.3) u *= this.cno;
    if (p.flags[i] & F_GIANT) {
      const ph = (p.a[i] - GIANT_START) / (1 - GIANT_START);
      u *= (2 + 6 * ph) * this.giant;
    }
    return u;
  }

  private spawnSun(): void {
    const p = this.p;
    for (let i = 0; i < p.n; i++) if (!p.isDead(i) && p.flags[i] & F_SUN) return;
    const x = this.halfW * 0.38;
    const y = this.halfH * 0.3;
    const i = p.spawn(STAR, x, y, 0, 0, 12, 1, 1);
    if (i < 0) return;
    this.setStarMass(i, 1);
    p.flags[i] = F_SUN;
    p.a[i] = 0.46;
    p.b[i] = 0;
  }

  private sunIndex(): number {
    const p = this.p;
    for (let i = 0; i < p.n; i++) if (!p.isDead(i) && p.flags[i] & F_SUN) return i;
    return -1;
  }

  // ───────────────────────────────────────── elements

  private makeElement(z: number, x: number, y: number, tile = true): boolean {
    if (this.made.has(z)) return false;
    this.made.add(z);
    this.s.made.push(z);
    this.g.discover(elementCodexId(z));
    this.g.setFlag(`forge.made${z}`);
    if (tile) {
      this.tiles.push({ z, x, y, age: -0.12 * this.tiles.filter((t) => t.age < 0.3).length });
      this.g.sfx('forge.element', x, 1, z);
    }
    return true;
  }

  /**
   * Adds `amount` events' worth of production to every element of `origin` that `ok` allows (mass
   * reach, the slow process), making each one whose threshold is crossed.
   */
  private produce(origin: Origin, amount: number, x: number, y: number, ok: (e: ElementInfo) => boolean = () => true): void {
    if (amount <= 0) return;
    const prod = this.s.prod;
    for (const e of MAKEABLE) {
      if (e.origin !== origin || this.made.has(e.z) || !ok(e)) continue;
      prod[e.z] = (prod[e.z] ?? 0) + amount;
      this.prodSince[e.z] += amount;
      if (prod[e.z] >= threshold(e)) {
        delete prod[e.z];
        this.makeElement(e.z, x, y);
      }
    }
  }

  // ───────────────────────────────────────── deaths

  private gain(units: number, x?: number, y?: number): void {
    this.g.gain(units * E_UNIT * this.weight, x, y);
  }

  private die(i: number): void {
    const p = this.p;
    const g = this.g;
    const s = this.s;
    const rng = g.sim;
    const m = p.w[i];
    const x = p.x[i];
    const y = p.y[i];
    const id = p.id[i];
    const perfect = (p.flags[i] & F_PERFECT) !== 0;
    const z = this.metallicity;
    const f = fate(m);
    p.kill(i);
    if (this.feedId === id) this.feedId = 0;
    const ej = ejectedMass(m);
    s.zGas += ej * z + metalYield(m) * m * METAL_SCALE;
    if (f === 'whiteDwarf') {
      s.pn++;
      this.gain(PN_UNITS * Math.sqrt(m) * this.giant * this.pnMult, x, y);
      this.ejecta(x, y, ej * Math.min(1.5, this.pnMult), 0, 70);
      this.addShell(ShellKind.Nebula, x, y, 8, 12 + 3 * Math.min(m, 8));
      g.sfx('forge.pn', x);
      g.setFlag('forge.firstPN');
      g.discover('planetary-nebula');
      // Carbon, nitrogen and lithium from every red giant; the slow process's heavy elements need it
      // understood, and come from stars of one to four Suns.
      this.produce('lowmass', 1, x, y, (e) => e.z <= 7);
      if (m >= 1 && m <= 4) this.produce('lowmass', 0.35 * this.sproc, x, y, (e) => e.z > 7);
      const w = this.remnant(id, WD, x, y, whiteDwarfMass(m));
      if (w >= 0) {
        s.wd += this.weight;
        g.setFlag('forge.firstWD');
        g.discover('white-dwarf');
      }
      return;
    }
    // Core collapse.
    s.sn++;
    const burst = SN_UNITS * m * this.snEnergy * (perfect ? PERFECT_MULT : 1);
    this.gain(burst, x, y);
    this.ejecta(x, y, ej, 1, 170);
    this.addShell(ShellKind.Remnant, x, y, 8.5, 92);
    this.fx.spawn(Fx.Flash, x, y, 0.9, 90, 5, 4.4, 3.6, 200);
    this.fx.spawn(Fx.Flash, x, y, 0.3, 26, 6, 6, 6, 50);
    this.fx.spawn(Fx.Ring, x, y, 1.0, 20, 1.0, 0.8, 0.7, 300);
    const r = g.renderer;
    r?.shock(x, y, perfect ? 0.55 : 0.32, 0.9, 1.0);
    r?.addFlash(perfect ? 0.32 : 0.16);
    r?.addAberration(perfect ? 0.005 : 0.003);
    r?.camera.addTrauma(perfect ? 0.32 : 0.16);
    g.sfx(perfect ? 'forge.perfect' : 'forge.sn', x);
    if (perfect) {
      s.perfect++;
      this.notes.push({ text: 'Perfect collapse', x, y: y - 34, age: 0 });
    }
    g.setFlag('forge.firstSN');
    g.discover('supernova');
    // Heavier stars reach further up the table; the weak slow process needs the most massive.
    const reach = m < 12 ? 14 : m < 18 ? 21 : 37;
    this.produce('massive', Math.sqrt(m / 15) * (perfect ? 2 : 1), x, y, (e) => e.z <= reach);
    // Cosmic rays accelerated by supernova remnants chip beryllium and boron off heavier nuclei.
    if (s.sn > 3) this.produce('cosmic', 0.15, x, y);
    this.trigger(x, y);
    if (f === 'neutronStar') {
      const ni = this.remnant(id, NS, x, y, NS_REMNANT);
      if (ni >= 0) {
        s.ns += this.weight;
        g.setFlag('forge.firstNS');
        g.discover('neutron-star');
      }
    } else {
      const bi = this.remnant(id, BH, x, y, blackHoleMass(m));
      if (bi >= 0) {
        s.bh += this.weight;
        g.discover('stellar-black-hole');
      }
      // The most massive, fastest-spinning collapses can launch gamma-ray bursts.
      if (m >= 40 && rng.chance(0.2)) {
        s.grb++;
        this.beams.push({ x, y, ang: rng.angle(), age: 0 });
        this.gain(burst, x, y);
        r?.addFlash(0.2);
        g.sfx('forge.grb', x);
        g.discover('grb');
        this.produce('merger', 0.3, x, y);
      }
    }
  }

  private addShell(kind: ShellKind, x: number, y: number, life: number, size: number): void {
    this.shells.push({ kind, x, y, age: 0, life, size, seed: this.g.fx.next() * 1000 });
  }

  /** Puts a remnant where a star died and hands it the star's place in any pair. Returns its index. */
  private remnant(oldId: number, kind: number, x: number, y: number, mass: number): number {
    const p = this.p;
    const i = p.spawn(kind, x, y, 0, 0, kind === BH ? 8 : 6, mass);
    if (i < 0) {
      const pair = this.pairs.get(oldId);
      if (pair) this.unpair(pair);
      return -1;
    }
    p.b[i] = this.g.fx.next() * Math.PI * 2;
    this.repair(oldId, p.id[i]);
    return i;
  }

  /** Supernova shocks squeeze nearby clouds into making stars. */
  private trigger(x: number, y: number): void {
    if (this.feedback <= 0 || this.visibleStars >= STAR_CAP + 40) return;
    const p = this.p;
    const rng = this.g.sim;
    for (const c of this.indicesOf(CLOUD)) {
      const d = Math.hypot(p.x[c] - x, p.y[c] - y);
      if (d > 360 + p.r[c]) continue;
      const n = Math.floor(this.feedback) + (rng.chance(this.feedback % 1) ? 1 : 0);
      for (let k = 0; k < n; k++) this.birth(c, sampleImf(rng.next(), this.birthImf), true);
    }
  }

  private typeIa(wd: number): void {
    const p = this.p;
    const g = this.g;
    const s = this.s;
    const x = p.x[wd];
    const y = p.y[wd];
    const id = p.id[wd];
    const pair = this.pairs.get(id);
    if (pair) {
      const other = p.find(pair.a === id ? pair.b : pair.a);
      this.unpair(pair);
      // The companion is flung away at its orbital speed: a runaway star.
      if (other >= 0) {
        const a = Math.atan2(p.y[other] - y, p.x[other] - x);
        p.vx[other] = Math.cos(a) * 140;
        p.vy[other] = Math.sin(a) * 140;
      }
    }
    p.kill(wd);
    s.ia++;
    s.zGas += 0.7 * METAL_SCALE;
    this.gain(IA_UNITS * this.iaEnergy, x, y);
    this.ejecta(x, y, 1.4, 2, 220);
    this.addShell(ShellKind.Ia, x, y, 6, 112);
    this.fx.spawn(Fx.Flash, x, y, 1.2, 160, 7, 6.6, 5.6, 260);
    this.fx.spawn(Fx.Ring, x, y, 1.1, 24, 1.3, 1.2, 1.1, 420);
    const r = g.renderer;
    r?.shock(x, y, 0.6, 1, 1.1);
    r?.addFlash(0.4);
    r?.addAberration(0.005);
    r?.camera.addTrauma(0.3);
    g.sfx('forge.ia', x);
    g.discover('type-ia');
    this.produce('whitedwarf', 1, x, y);
    this.produce('massive', 0.5, x, y, (e) => e.z >= 14 && e.z <= 20);
    // A save from before this moment would bring the pair back to explode again.
    this.saveBodies();
  }

  /** Two compact remnants touch. */
  private compactMerge(i: number, j: number): void {
    const p = this.p;
    const g = this.g;
    const s = this.s;
    const x = (p.x[i] + p.x[j]) / 2;
    const y = (p.y[i] + p.y[j]) / 2;
    const ki = p.kind[i];
    const kj = p.kind[j];
    const mass = p.w[i] + p.w[j];
    const pair = this.pairs.get(p.id[i]);
    if (pair) this.unpair(pair);
    if (ki === WD && kj === WD) {
      // Two white dwarfs together are past the Chandrasekhar limit.
      p.w[i] = Math.max(CHANDRASEKHAR, mass);
      p.kill(j);
      this.typeIa(i);
      return;
    }
    p.kill(i);
    p.kill(j);
    const nsCount = (ki === NS ? 1 : 0) + (kj === NS ? 1 : 0);
    const kilonova = nsCount === 2 || (nsCount === 1 && (ki === BH || kj === BH) && g.sim.chance(0.6));
    const bi = p.spawn(BH, x, y, 0, 0, 8, mass * 0.95);
    if (bi >= 0) p.b[bi] = g.fx.next() * Math.PI * 2;
    s.bh += this.weight;
    for (let k = 0; k < 4; k++) this.fx.spawn(Fx.Ring, x, y, 1.6 + k * 0.3, 10, 0.5, 0.55, 0.8, 260 + k * 60);
    if (kilonova) {
      s.kn++;
      this.gain(KN_UNITS * this.knEnergy, x, y);
      this.ejecta(x, y, 0.6, 3, 200);
      this.addShell(ShellKind.Kilonova, x, y, 5.5, 46);
      this.fx.spawn(Fx.Flash, x, y, 1.1, 120, 6, 4.2, 2.2, 200);
      const r = g.renderer;
      r?.shock(x, y, 0.5, 0.9, 1.0);
      r?.addFlash(0.3);
      r?.camera.addTrauma(0.25);
      g.sfx('forge.kilonova', x);
      g.setFlag('forge.firstKilonova');
      g.discover('kilonova');
      this.produce('merger', 1 + 0.5 * this.rproc, x, y);
    } else {
      this.gain(MERGE_UNITS, x, y);
      this.fx.spawn(Fx.Flash, x, y, 0.6, 40, 1.2, 1.3, 2, 60);
      g.renderer?.shock(x, y, 0.4, -0.7, 1.0);
      g.sfx('forge.merge', x);
    }
    this.saveBodies();
  }

  // ───────────────────────────────────────── simulation

  update(dt: number): void {
    const g = this.g;
    const p = this.p;
    const s = this.s;
    this.t += dt;
    this.idle += dt;
    if (this.intro > 0) this.intro = Math.max(0, this.intro - dt);
    const inFinale = this.finaleT >= 0;
    if (inFinale) this.updateFinale(dt);

    if (!inFinale) {
      this.updateGas(dt);
      this.updateArm(dt);
      this.formStars(dt);
      if (s.noon > 0) s.noon = Math.max(0, s.noon - dt);
    }
    this.updateFeeding(dt);
    this.updateDrag(dt);
    this.updatePairs(dt, inFinale);

    let light = s.field;
    let visibleField = 0;
    let stars = 0;
    let remnants = 0;
    const hot: number[] = [];
    const wrapW = this.halfW + 70;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const kind = p.kind[i];
      p.age[i] += dt;
      if (kind === GAS) {
        const k = Math.exp(-0.7 * dt);
        p.vx[i] *= k;
        p.vy[i] *= k;
        p.x[i] += p.vx[i] * dt;
        p.y[i] += p.vy[i] * dt;
        p.life[i] -= dt;
        if (this.debrisToCloud(i)) continue;
        if (p.life[i] <= 0) {
          s.diffuse += p.w[i];
          p.kill(i);
        }
        continue;
      }
      // Everything else rides the galaxy's rotation; members of pairs are placed by their orbit.
      if (!this.pairs.has(p.id[i]) && p.id[i] !== this.dragId) {
        p.x[i] += (SHEAR * p.y[i] + p.vx[i]) * dt;
        p.y[i] += p.vy[i] * dt;
        p.vx[i] *= Math.exp(-0.25 * dt);
        p.vy[i] *= Math.exp(-0.25 * dt);
        if (p.x[i] > wrapW) p.x[i] -= 2 * wrapW;
        else if (p.x[i] < -wrapW) p.x[i] += 2 * wrapW;
        if (p.y[i] > this.halfH + 60 || p.y[i] < -this.halfH - 60) p.vy[i] -= Math.sign(p.y[i]) * 20 * dt;
      }
      if (kind === STAR) {
        stars++;
        const flags = p.flags[i];
        if (flags & F_RETIRE) {
          p.life[i] -= dt;
          if (p.life[i] <= 0) {
            // Only a star that is still small joins the disk; one that was fed since stays.
            if (p.w[i] < ETERNAL_MASS && !(flags & F_FED)) {
              s.field += this.starUnits(i);
              p.kill(i);
              continue;
            }
            p.flags[i] &= ~F_RETIRE;
            p.life[i] = Infinity;
          }
        }
        const u = this.starUnits(i);
        light += u;
        if (p.w[i] < ETERNAL_MASS && !this.kept(i)) visibleField += u;
        if (p.w[i] >= NS_MASS) hot.push(i);
        if (inFinale || flags & F_SUN) continue;
        const life = gameLife(p.w[i]);
        if (!Number.isFinite(life)) continue;
        p.a[i] += dt / life;
        const f = fate(p.w[i]);
        if (f === 'whiteDwarf' && p.a[i] >= GIANT_START && !(flags & F_GIANT)) {
          p.flags[i] |= F_GIANT;
          g.sfx('forge.giant', p.x[i]);
          g.setFlag('forge.firstGiant');
          g.discover('red-giant');
        }
        if (f !== 'whiteDwarf' && this.remaining(i) <= COUNTDOWN) p.flags[i] |= F_COUNTDOWN;
        // Winds from massive stars return gas while they live, never enough to change their fate.
        if (this.winds > 0 && p.w[i] >= NS_MASS) {
          const floor = p.w[i] >= BH_MASS ? BH_MASS + 0.5 : NS_MASS + 0.5;
          const dm = Math.min(Math.max(0, p.w[i] - floor), this.winds * p.w[i] * dt);
          if (dm > 0) {
            this.setStarMass(i, p.w[i] - dm);
            this.returnGas(p.x[i], p.y[i], dm, dm * (this.metallicity + 0.02 * METAL_SCALE));
          }
        }
        if (p.a[i] >= 1) this.die(i);
      } else if (kind === WD || kind === NS || kind === BH) {
        remnants++;
        if (kind === NS && this.pulsar > 0) light += lightUnits(this.pulsar);
      } else if (kind === CLOUD) {
        p.b[i] *= Math.exp(-0.8 * dt);
      }
    }
    // Hot young stars light up the clouds around them.
    if (hot.length) {
      for (const c of this.indicesOf(CLOUD)) {
        let heat = 0;
        for (const i of hot) {
          const d2 = (p.x[i] - p.x[c]) ** 2 + (p.y[i] - p.y[c]) ** 2;
          const R = p.r[c] * 1.4;
          if (d2 < R * R) heat += 0.25 + 0.05 * Math.log10(luminosity(p.w[i]));
        }
        p.b[c] = Math.max(p.b[c], Math.min(2, heat));
      }
    }
    light += this.xrbUnits();
    s.visibleField = visibleField;
    if (light > 0) g.gain(light * E_UNIT * this.weight * dt);

    this.visibleStars = stars;
    if (stars > STAR_CAP) this.retireStars(Math.min(8, stars - STAR_CAP));
    if (remnants > REMNANT_CAP) this.retireRemnant();

    p.compact();
    this.fx.update(dt);
    this.ageVisuals(dt);
    this.starMeter.tick(dt);
    s.starRate = this.starMeter.rate;
    if (this.noGas > 0) this.noGas -= dt;

    this.syncClock -= dt;
    if (this.syncClock <= 0) {
      this.syncClock = 1;
      this.sync();
    }
    this.updateBackground(dt);
  }

  private returnGas(x: number, y: number, mass: number, metals: number): void {
    const p = this.p;
    let best = -1;
    let bd = Infinity;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i) || p.kind[i] !== CLOUD) continue;
      const d = (p.x[i] - x) ** 2 + (p.y[i] - y) ** 2;
      if (d < bd) {
        bd = d;
        best = i;
      }
    }
    if (best >= 0) p.w[best] += mass;
    else this.s.diffuse += mass;
    this.s.zGas += metals;
  }

  /** Returns true if debris particle `i` reached a cloud and joined it. */
  private debrisToCloud(i: number): boolean {
    const p = this.p;
    for (let c = 0; c < p.n; c++) {
      if (p.isDead(c) || p.kind[c] !== CLOUD) continue;
      const R = p.r[c] * 0.8;
      if ((p.x[c] - p.x[i]) ** 2 + (p.y[c] - p.y[i]) ** 2 < R * R) {
        p.w[c] += p.w[i];
        p.r[c] = this.cloudRadius(p.w[c]);
        p.kill(i);
        return true;
      }
    }
    return false;
  }

  private formStars(dt: number): void {
    // The drawn patch holds a representative sample; past it, the clouds wait (stars you start always form).
    if (this.visibleStars >= STAR_CAP + 40) return;
    const p = this.p;
    const rng = this.g.sim;
    const zf = this.zFactor(this.metallicity);
    const burst = this.s.noon > 0 ? 3 : 1;
    const armBoost = 2 + 0.6 * this.density;
    for (const c of this.indicesOf(CLOUD)) {
      const w = p.w[c];
      if (w < 2) continue;
      let rate = SF_RATE * this.sfr * zf * burst * (w / 100) ** 1.4;
      if (this.armK > 0 && this.inArm(p.x[c], p.y[c])) {
        rate *= armBoost;
        p.b[c] = Math.max(p.b[c], 0.8 * this.armK);
      }
      p.a[c] += rate * dt;
      let guard = 0;
      while (p.a[c] >= 1 && guard++ < 4) {
        p.a[c] -= 1;
        if (this.birth(c, sampleImf(rng.next(), this.birthImf), true) >= 0) this.g.discover('imf');
      }
    }
  }

  private inArm(x: number, y: number): boolean {
    return Math.abs(x - this.armX - y * 0.35) < 230;
  }

  /** Spiral density waves: an arm sweeps across the patch, setting its clouds alight. */
  private updateArm(dt: number): void {
    if (this.density <= 0) {
      this.armK = Math.max(0, this.armK - dt);
      return;
    }
    const span = this.halfW + 500;
    if (this.armX < -span) {
      this.armWait -= dt;
      if (this.armWait > 0) return;
      this.armX = -span + 1;
      this.g.sfx('forge.arm');
    }
    const period = Math.max(30, 70 - 6 * this.density);
    this.armX += ((2 * span) / period) * dt;
    this.armK = Math.min(1, this.armK + dt * 0.8);
    if (this.armX > span) {
      this.armX = -span - 1;
      this.armWait = 8;
      this.armK = 0;
    }
  }

  private updateFeeding(dt: number): void {
    this.stream = null;
    if (!this.pDown || !this.feedId || this.finaleT >= 0) return;
    const p = this.p;
    const g = this.g;
    const i = p.find(this.feedId);
    if (i < 0 || p.kind[i] !== STAR || p.flags[i] & (F_COUNTDOWN | F_GIANT | F_SUN)) return;
    const m = p.w[i];
    if (m >= MAX_MASS) {
      g.discover('eddington');
      return;
    }
    const want = Math.min(MAX_MASS - m, (m * FEED_BASE * this.feed + 0.12) * dt);
    const { got, cx, cy } = this.takeGas(p.x[i], p.y[i], want);
    if (got <= 1e-6) {
      this.noGas = 2;
      return;
    }
    const before = fate(m);
    const nm = m + got;
    this.setStarMass(i, nm);
    // Growing doesn't kill a star outright: it keeps at least a few seconds of life.
    const life = gameLife(nm);
    if (Number.isFinite(life)) p.a[i] = Math.min(p.a[i], 1 - Math.min(1, 3 / life));
    p.flags[i] = (p.flags[i] | F_FED) & ~F_RETIRE;
    p.life[i] = Infinity;
    this.s.everFed = true;
    this.stream = { x0: cx, y0: cy, x1: p.x[i], y1: p.y[i] };
    const after = fate(nm);
    if (after !== before) {
      g.sfx('forge.fate', p.x[i], 1, nm);
      this.fx.spawn(Fx.Ring, p.x[i], p.y[i], 0.6, this.starSize(nm), 1.4, 1.2, 0.9, 90);
    }
    if (nm > 2) g.discover('mass-luminosity');
    this.feedSound -= dt;
    if (this.feedSound <= 0) {
      this.feedSound = 0.22;
      g.sfx('forge.feed', p.x[i], 1, nm);
    }
  }

  private updateDrag(dt: number): void {
    if (!this.dragId) return;
    const p = this.p;
    const i = p.find(this.dragId);
    if (i < 0) {
      this.dragId = 0;
      return;
    }
    const k = Math.min(1, dt * 12);
    p.x[i] += (this.pX - p.x[i]) * k;
    p.y[i] += (this.pY - p.y[i]) * k;
  }

  private updatePairs(dt: number, inFinale: boolean): void {
    const p = this.p;
    const seen = new Set<Pair>();
    for (const pair of this.pairs.values()) {
      if (seen.has(pair)) continue;
      seen.add(pair);
      const i = p.find(pair.a);
      const j = p.find(pair.b);
      if (i < 0 || j < 0) {
        this.unpair(pair);
        continue;
      }
      const mi = p.w[i];
      const mj = p.w[j];
      const ki = p.kind[i];
      const kj = p.kind[j];
      const compactI = ki !== STAR;
      const compactJ = kj !== STAR;
      // Inspiral: gravitational waves shrink the orbit of two dead stars.
      if (compactI && compactJ && !inFinale) {
        pair.sep -= INSPIRAL * this.gw * (22 / pair.sep) ** 3 * dt;
        pair.ripple -= dt;
        if (pair.ripple <= 0) {
          pair.ripple = Math.max(0.15, pair.sep / 18);
          this.fx.spawn(Fx.Ring, (p.x[i] + p.x[j]) / 2, (p.y[i] + p.y[j]) / 2, 1.1, pair.sep, 0.13, 0.16, 0.26, 75);
        }
        if (!pair.chirped && pair.sep < 11 && (ki !== WD || kj !== WD)) {
          pair.chirped = true;
          this.g.sfx('forge.chirp', p.x[i]);
        }
        if (pair.sep < 6.5) {
          this.compactMerge(i, j);
          continue;
        }
      }
      // A white dwarf steals gas from a living companion, faster once the companion swells.
      if (!inFinale && ((ki === WD && kj === STAR) || (kj === WD && ki === STAR))) {
        const wd = ki === WD ? i : j;
        const donor = ki === WD ? j : i;
        // Mostly once the companion swells into a giant and overflows onto the white dwarf.
        const rate = ACCRETE_RATE * this.accrete * (p.flags[donor] & F_GIANT ? 1 : 0.15);
        const dm = Math.min(rate * dt, Math.max(0, p.w[donor] - 0.3));
        p.w[wd] += dm;
        this.setStarMass(donor, p.w[donor] - dm);
        this.g.setFlag('forge.accreting');
        if (p.w[wd] >= CHANDRASEKHAR) {
          this.typeIa(wd);
          continue;
        }
      }
      // Black holes feeding on a companion shine as X-ray binaries (light counted in xrbUnits).
      if (!inFinale && ((ki === BH && kj === STAR) || (kj === BH && ki === STAR))) {
        const donor = ki === BH ? j : i;
        this.setStarMass(donor, Math.max(0.3, p.w[donor] - 0.004 * dt));
      }
      if (compactI && compactJ) this.g.setFlag('forge.compactPair');
      // Orbit about the centre of mass, which itself rides the galaxy's rotation.
      const cx = (p.x[i] * mi + p.x[j] * mj) / (mi + mj) + SHEAR * p.y[i] * dt;
      const cy = (p.y[i] * mi + p.y[j] * mj) / (mi + mj);
      pair.phase += 2.2 * (22 / pair.sep) ** 1.5 * dt;
      const c = Math.cos(pair.phase);
      const sn = Math.sin(pair.phase);
      const fi = mj / (mi + mj);
      const fj = mi / (mi + mj);
      p.x[i] = cx + c * pair.sep * fi;
      p.y[i] = cy + sn * pair.sep * fi;
      p.x[j] = cx - c * pair.sep * fj;
      p.y[j] = cy - sn * pair.sep * fj;
    }
  }

  private xrbUnits(): number {
    const p = this.p;
    let u = 0;
    const seen = new Set<Pair>();
    for (const pair of this.pairs.values()) {
      if (seen.has(pair)) continue;
      seen.add(pair);
      const i = p.find(pair.a);
      const j = p.find(pair.b);
      if (i < 0 || j < 0) continue;
      if ((p.kind[i] === BH && p.kind[j] === STAR) || (p.kind[j] === BH && p.kind[i] === STAR)) u += XRB_UNITS;
    }
    return u;
  }

  /** The oldest small stars nobody is using fade into the disk's unresolved glow, keeping their light. */
  private retireStars(n: number): void {
    const p = this.p;
    for (let k = 0; k < n; k++) {
      let best = -1;
      for (let i = 0; i < p.n; i++) {
        if (p.isDead(i) || p.kind[i] !== STAR || !this.retirable(i)) continue;
        if (best < 0 || p.age[i] > p.age[best]) best = i;
      }
      if (best < 0) return;
      const pair = this.pairs.get(p.id[best]);
      if (pair) {
        const other = p.find(pair.a === p.id[best] ? pair.b : pair.a);
        this.unpair(pair);
        if (other >= 0) {
          p.flags[other] |= F_RETIRE;
          p.life[other] = 1.5;
        }
      }
      p.flags[best] |= F_RETIRE;
      p.life[best] = 1.5;
    }
  }

  /** A small star can join the disk if it is alone, or paired with another small star nobody fed. */
  private retirable(i: number): boolean {
    const p = this.p;
    if (p.w[i] >= ETERNAL_MASS || p.flags[i] & (F_RETIRE | F_SUN | F_FED)) return false;
    const pair = this.pairs.get(p.id[i]);
    if (!pair) return true;
    const j = p.find(pair.a === p.id[i] ? pair.b : pair.a);
    return j < 0 || (p.kind[j] === STAR && p.w[j] < ETERNAL_MASS && !(p.flags[j] & (F_FED | F_SUN)));
  }

  private retireRemnant(): void {
    const p = this.p;
    let best = -1;
    for (let i = 0; i < p.n; i++) {
      const k = p.kind[i];
      if (p.isDead(i) || (k !== WD && k !== NS && k !== BH) || this.pairs.has(p.id[i]) || p.id[i] === this.dragId) continue;
      if (best < 0 || p.age[i] > p.age[best]) best = i;
    }
    if (best >= 0) p.kill(best);
  }

  private ageVisuals(dt: number): void {
    for (const sh of this.shells) sh.age += dt;
    this.shells = this.shells.filter((sh) => sh.age < sh.life);
    for (const b of this.beams) b.age += dt;
    this.beams = this.beams.filter((b) => b.age < 1.4);
    for (const t of this.tiles) t.age += dt;
    this.tiles = this.tiles.filter((t) => t.age < 2.6);
    for (const n of this.notes) n.age += dt;
    this.notes = this.notes.filter((n) => n.age < 1.8);
  }

  /** Saves what a reload needs (the clouds' gas and the player's pieces) and measures the rates time away is credited at. */
  private sync(): void {
    const p = this.p;
    const out: ForgeState['clouds'] = [];
    for (const i of this.indicesOf(CLOUD)) out.push({ x: p.x[i] / this.halfW, y: p.y[i] / this.halfH, w: p.w[i] });
    this.s.clouds = out;
    this.saveBodies();
    if (this.finaleT < 0) this.trackRates(1);
    if (this.metallicity >= 0.1 * Z_SUN) this.g.discover('metallicity');
  }

  /** Whether a reload brings this body back as it is (otherwise a small star rejoins the disk's light). */
  private kept(i: number): boolean {
    const p = this.p;
    const k = p.kind[i];
    if (k === WD || k === NS || k === BH) return true;
    if (k !== STAR || p.flags[i] & F_SUN) return false;
    return p.w[i] >= ETERNAL_MASS || (p.flags[i] & F_FED) !== 0 || this.pairs.has(p.id[i]);
  }

  private saveBodies(): void {
    const p = this.p;
    const bodies: SavedBody[] = [];
    const at = new Map<number, number>();
    const r = (v: number) => Math.round(v * 1e4) / 1e4;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i) || !this.kept(i)) continue;
      at.set(p.id[i], bodies.length);
      bodies.push({ k: p.kind[i], x: r(p.x[i] / this.halfW), y: r(p.y[i] / this.halfH), m: r(p.w[i]), a: r(p.a[i]), f: p.flags[i] & (F_FED | F_GIANT) });
    }
    const pairs: NonNullable<ForgeState['pairs']> = [];
    const seen = new Set<Pair>();
    for (const pair of this.pairs.values()) {
      if (seen.has(pair)) continue;
      seen.add(pair);
      const a = at.get(pair.a);
      const b = at.get(pair.b);
      if (a !== undefined && b !== undefined) pairs.push({ a, b, sep: pair.sep, phase: pair.phase });
    }
    this.s.bodies = bodies;
    this.s.pairs = pairs;
  }

  /** Brings back the stars, remnants and pairs a save kept. */
  private restoreBodies(): void {
    const s = this.s;
    const p = this.p;
    if (!s.bodies?.length) return;
    const ids: number[] = [];
    for (const b of s.bodies) {
      const kind = b.k === STAR || b.k === WD || b.k === NS || b.k === BH ? b.k : -1;
      const i = kind < 0 || !(b.m > 0) ? -1 : p.spawn(kind, b.x * this.halfW, b.y * this.halfH, 0, 0, kind === BH ? 8 : 6, b.m);
      ids.push(i >= 0 ? p.id[i] : 0);
      if (i < 0) continue;
      p.b[i] = this.g.fx.next() * Math.PI * 2;
      if (kind !== STAR) continue;
      this.setStarMass(i, b.m);
      p.a[i] = Math.min(0.999, Math.max(0, b.a));
      p.flags[i] = b.f & (F_FED | F_GIANT);
    }
    for (const pr of s.pairs ?? []) {
      const a = ids[pr.a];
      const b = ids[pr.b];
      if (a && b && a !== b && !this.pairs.has(a) && !this.pairs.has(b)) this.makePair(a, b, Math.max(7, pr.sep), pr.phase);
    }
  }

  /** Folds the last `dt` seconds into the rates time away is credited at (a one-minute average). */
  private trackRates(dt: number): void {
    const s = this.s;
    const r = this.rates;
    const last = this.last;
    const k = 1 - Math.exp(-dt / RATE_WINDOW);
    for (const key of RATE_KEYS) {
      r[key] += ((s[key] - last[key]) / dt - r[key]) * k;
      last[key] = s[key];
    }
    r.metals += ((s.zGas - last.zGas) / dt - r.metals) * k;
    last.zGas = s.zGas;
    for (const e of MAKEABLE) {
      const v = (r.prod[e.z] ?? 0) * (1 - k) + (this.prodSince[e.z] / dt) * k;
      this.prodSince[e.z] = 0;
      if (this.made.has(e.z) || v < 1e-6) delete r.prod[e.z];
      else r.prod[e.z] = v;
    }
  }

  /** Starts measuring from the counters as they are now (after a reload or a step's ×10). */
  private markRates(): void {
    const s = this.s;
    for (const key of RATE_KEYS) this.last[key] = s[key];
    this.last.zGas = s.zGas;
  }

  private updateBackground(dt: number): void {
    const bp = this.bgParams;
    const p = this.p;
    bp.glow = 0.35 + 0.32 * Math.log10(1 + this.s.field / 8);
    bp.age = Math.min(1, (this.step / 6) * 0.8 + Math.min(0.2, this.metallicity / Z_SUN / 5));
    bp.gas = Math.min(1, this.gasTotal() / 800);
    bp.arm = this.armX;
    bp.armK = this.armK;
    bp.pulse *= Math.exp(-dt * 2);
    let n = 0;
    for (let i = 0; i < p.n && n < MAX_BG_CLOUDS; i++) {
      if (p.isDead(i) || p.kind[i] !== CLOUD) continue;
      bp.clouds[n * 4] = p.x[i];
      bp.clouds[n * 4 + 1] = p.y[i];
      bp.clouds[n * 4 + 2] = p.r[i] * 1.3;
      bp.clouds[n * 4 + 3] = p.b[i];
      bp.cloudsB[n * 4] = p.sub[i];
      bp.cloudsB[n * 4 + 1] = p.w[i] / 120;
      n++;
    }
    bp.cloudCount = n;
    // The hottest stars blow ionized bubbles into the clouds: keep the brightest few, by luminosity.
    const hot = bp.hot;
    let h = 0;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i) || p.kind[i] !== STAR || p.w[i] < NS_MASS || p.flags[i] & F_GIANT) continue;
      const L = luminosity(p.w[i]);
      const k = Math.min(1, Math.max(0.3, 0.3 + 0.2 * Math.log10(L / 2000))) * Math.min(1, p.age[i] * 0.8);
      let slot = h;
      if (h < MAX_BG_HOT) h++;
      else {
        slot = -1;
        let weakest = k;
        for (let s = 0; s < MAX_BG_HOT; s++) {
          if (hot[s * 4 + 3] < weakest) {
            weakest = hot[s * 4 + 3];
            slot = s;
          }
        }
        if (slot < 0) continue;
      }
      hot[slot * 4] = p.x[i];
      hot[slot * 4 + 1] = p.y[i];
      hot[slot * 4 + 2] = 34 + 16 * Math.log10(Math.max(1, L / 1000));
      hot[slot * 4 + 3] = k;
    }
    bp.hotCount = h;
  }

  // ───────────────────────────────────────── steps

  onStep(index: number): void {
    const g = this.g;
    const s = this.s;
    s.stars *= 10;
    s.wd *= 10;
    s.ns *= 10;
    s.bh *= 10;
    this.markRates();
    this.syncStepFlags();
    this.bgParams.pulse = Math.min(1, this.bgParams.pulse + 0.3);
    g.renderer?.camera.breathe(0.05, 1.5);
    if (index >= 2 && index < 5) g.sfx('forge.milestone');
    if (index === 2) {
      s.noon = 90;
      g.discover('cosmic-noon');
    }
    if (index === 3) g.discover('thin-disk');
    if (index === 4) g.discover('acceleration');
    if (index === 5) {
      s.sunFormed = true;
      this.spawnSun();
      g.discover('the-sun');
      g.sfx('forge.sun');
      g.toast('Somewhere in an ordinary arm of the galaxy, an ordinary yellow star has formed.', 'milestone');
    }
  }

  /**
   * What "Today" still needs: how many elements are left, how many each origin has not made yet,
   * and how many of the left must come from neutron-star mergers because nothing else makes enough
   * (the rapid process: every other origin together falls short of the goal).
   */
  static todayNeeds(made: readonly number[]): TodayNeeds {
    const left = Math.max(0, ELEMENT_GOAL - made.length);
    const open: Partial<Record<Origin, number>> = {};
    for (const e of MAKEABLE) if (!made.includes(e.z)) open[e.origin] = (open[e.origin] ?? 0) + 1;
    let others = 0;
    for (const [o, n] of Object.entries(open)) if (o !== 'merger') others += n;
    return { left, open, fromMergers: Math.max(0, left - others) };
  }

  /** Why the Sun can't form yet: the elements a rocky planet needs, made in this universe. */
  static sunBlocker(made: readonly number[]): string | null {
    const need: [number, string][] = [
      [6, 'carbon'],
      [8, 'oxygen'],
      [14, 'silicon'],
      [26, 'iron'],
    ];
    const missing = need.filter(([z]) => !made.includes(z)).map(([, name]) => name);
    if (!missing.length) return null;
    if (missing.length > 2) return `Needs ${missing.length} more elements of a rocky planet`;
    return `Needs ${missing.join(' and ')}`;
  }

  static todayBlocker(made: readonly number[]): string | null {
    const left = ELEMENT_GOAL - made.length;
    if (left <= 0) return null;
    const what = `Needs ${left} more of ${ELEMENT_GOAL} elements`;
    // Name the missing route once the rest of the table can no longer cover the gap on its own.
    const others = MAKEABLE.filter((e) => e.origin !== 'merger' && !made.includes(e.z)).length;
    return others < left ? `${what}; some come only from merging neutron stars` : what;
  }

  // ───────────────────────────────────────── finale: today

  finale(): Promise<void> {
    const g = this.g;
    const run = g.state.run;
    const s = this.s;
    // Someone who knows what to look for, in a universe like ours, finds a pale blue dot.
    this.life = g.knowledge('observer') > 0 && lifeNoticed(run.constants);
    this.lifeFull = this.life && !g.state.meta.endingSeen;
    run.legacy.elements = s.made.length;
    run.legacy.metallicity = this.metallicity;
    run.legacy.whiteDwarfs = s.wd;
    run.legacy.neutronStars = s.ns;
    g.tally('blackHoles', 'forge', s.bh);
    run.legacy.galaxyStars = s.stars;
    this.feedId = 0;
    this.dragId = 0;
    this.finaleT = 0;
    g.sfx('forge.complete');
    return new Promise((resolve) => {
      this.finaleDone = resolve;
    });
  }

  private updateFinale(dt: number): void {
    const g = this.g;
    this.finaleT += dt;
    const raw = this.finaleT;
    const cam = g.renderer?.camera;
    const sun = this.sunIndex();
    const ease = (u: number) => u * u * (3 - 2 * u);
    // Reduce motion: the dive to the Sun and back is a third as deep.
    const zoom = (z: number) => (g.state.settings.reduceMotion ? 1 + (z - 1) * 0.3 : z);
    // With life found, the camera stays on the Sun a while (much longer the first time: the ending).
    const hold = this.lifeFull ? 31 : this.life ? 7 : 0;
    if (hold > 0 && raw >= 4.5 && raw < 4.5 + hold) {
      this.updateLife(raw - 4.5, dt);
      if (cam && sun >= 0) {
        const k = ease(Math.min(1, (raw - 4.5) / 3.5));
        cam.zoom = zoom(3.2 + 5.8 * k);
        cam.x = this.p.x[sun] + 2.5 * k;
        cam.y = this.p.y[sun] - 1 * k;
      }
      return;
    }
    const t = raw >= 4.5 ? raw - hold : raw;
    if (cam && sun >= 0) {
      const sx = this.p.x[sun];
      const sy = this.p.y[sun];
      if (t < 4.5) {
        const k = ease(Math.min(1, t / 3.5));
        cam.zoom = zoom(1 + 2.2 * k);
        cam.x = sx * k;
        cam.y = sy * k;
      } else {
        // Drawing back to the whole galaxy (Powers of Ten): a steady move outward in log-distance,
        // re-centring on the galaxy as it comes into view, so the Sun is left a point on its arm.
        // Reduce motion keeps the move (the galaxy is its point) but makes it slower.
        const u = Math.min(1, (t - 4.5) / (g.state.settings.reduceMotion ? 7.5 : 5.5));
        const z0 = zoom(3.2);
        const zf = cam.viewHeight / GALAXY_VIEW;
        cam.zoom = Math.exp(Math.log(z0) + (Math.log(zf) - Math.log(z0)) * ease(u));
        const h0 = cam.viewHeight / (2 * z0);
        const c = Math.min(1, Math.max(0, (cam.viewHeight / (2 * cam.zoom) - h0) / (GALAXY_VIEW / 2 - h0)));
        cam.x = sx + (GALAXY_CENTRE[0] - sx) * GALAXY_RECENTRE * c;
        cam.y = sy + (GALAXY_CENTRE[1] - sy) * GALAXY_RECENTRE * c;
      }
      this.bgParams.finale = 1 - Disk.patchShown(cam.viewHeight / (2 * cam.zoom));
    }
    if (t >= 9.5 && !this.tallied) {
      this.tallied = true;
      const s = this.s;
      g.toast(`Today. ${toText(count(s.stars))} stars, and ${s.made.length} of the 83 elements that can survive from a star until today.`, 'milestone');
    }
    if (t >= 13 && this.finaleDone) {
      const done = this.finaleDone;
      this.finaleDone = null;
      done();
    }
  }

  /** The pale blue dot, and (the first time) the ending's movements, `lt` seconds into the hold. */
  private updateLife(lt: number, dt: number): void {
    const g = this.g;
    const at = (s: number) => lt >= s && lt - dt < s;
    if (at(1.5)) g.discover('pale-blue-dot');
    if (!this.lifeFull) {
      if (at(2)) g.toast('One of these stars has a small rocky planet, and on it, something looking back.', 'milestone');
      return;
    }
    if (at(3.5)) {
      // Seen once: a reload partway through gives the one-line version, not the whole ending again.
      g.state.meta.endingSeen = true;
      g.persist();
      g.bus.emit('ending', { phase: 'words' });
    }
    if (at(16.5)) g.bus.emit('ending', { phase: 'light' });
    if (at(22.5)) g.bus.emit('ending', { phase: 'title' });
    if (at(30)) g.bus.emit('ending', { phase: 'done' });
  }

  // ───────────────────────────────────────── rendering

  render(r: Renderer, dt: number): void {
    const p = this.p;
    const t = this.t;
    const look = this.look;
    const bp = this.bgParams;
    let lens = -1;
    const far = bp.finale;
    const fin = 1 - far;
    look.begin(r);
    look.medium(bp.glow, bp.age, bp.gas, bp.arm, bp.armK, bp.pulse, far);
    const sun = this.sunIndex();
    if (sun >= 0) look.armThrough(p.x[sun], p.y[sun]);
    for (let k = 0; k < bp.cloudCount; k++) {
      const o = k * 4;
      look.cloud(bp.clouds[o], bp.clouds[o + 1], bp.clouds[o + 2], bp.clouds[o + 3], bp.cloudsB[o + 1], bp.cloudsB[o]);
    }
    // Each hot star's bubble grows to its Strömgren radius as the star settles in.
    for (let k = 0; k < bp.hotCount; k++) {
      const o = k * 4;
      const s = bp.hot[o + 3];
      look.bubble(bp.hot[o], bp.hot[o + 1], bp.hot[o + 2] * (0.55 + 0.6 * s), s);
    }
    // The pale blue dot beside the Sun.
    if (this.life && this.finaleT >= 5.5 && sun >= 0) {
      const f = Math.min(1, (this.finaleT - 5.5) / 2.5) * fin;
      r.top.push(p.x[sun] + 5.5, p.y[sun] - 2.2, 1.15, 0.42 * f, 0.62 * f, 1.15 * f, 1, Shape.Glow);
    }
    if (fin > 0.01) {
      for (let i = 0; i < p.n; i++) {
        if (p.isDead(i)) continue;
        switch (p.kind[i]) {
          case STAR:
            this.renderStar(i, fin);
            break;
          case WD:
            look.whiteDwarf(p.x[i], p.y[i], Math.max(0.45, 1 - p.age[i] / 90) * fin);
            break;
          case NS:
            look.pulsar(p.x[i], p.y[i], t * 3.2 + p.b[i], fin);
            if (this.dragId === p.id[i] || (this.hoverId === p.id[i] && !this.pairs.has(p.id[i]))) look.reticle(p.x[i], p.y[i], 14, [0.72, 0.8, 1.0], 0.8);
            break;
          case BH: {
            const R = 4 + 1.6 * Math.log2(p.w[i] / 5 + 1);
            look.blackHole(p.x[i], p.y[i], R, fin);
            if (lens < 0 || p.w[i] > p.w[lens]) lens = i;
            if (this.dragId === p.id[i] || (this.hoverId === p.id[i] && !this.pairs.has(p.id[i]))) look.reticle(p.x[i], p.y[i], R * 2.6, [0.85, 0.78, 0.7], 0.8);
            break;
          }
          case GAS:
            look.debris(p.x[i], p.y[i], p.vx[i], p.vy[i], GAS_COLORS[p.sub[i]] ?? GAS_COLORS[0], Math.min(1, p.life[i] / 2) * fin);
            break;
        }
      }
      // The heaviest black hole bends the light around it: the renderer's refraction, held still on it for
      // exactly one frame, every frame (a shock lives 1.5 frames, fading to a third: nine times the strength).
      if (lens >= 0 && dt > 0) r.shock(p.x[lens], p.y[lens], 9 * 0.7 * fin, 0, 1.5 * dt);
      this.renderPairs(fin);
      this.renderShells(fin);
      const st = this.stream;
      if (st) look.stream(st.x0, st.y0, st.x1, st.y1, t, fin);
    }
    for (const b of this.beams) look.beam(b.x, b.y, b.ang, Math.pow(1 - b.age / 1.4, 2));
    // Seen from far, the Sun is a point on its arm, marked.
    if (far > 0.3 && sun >= 0) look.marker(p.x[sun], p.y[sun], r.camera.halfH / 500, Math.min(1, (far - 0.3) / 0.4));
    this.fx.render(r, look);
    if (this.intro > 0) {
      const a = Math.pow(this.intro / 1.4, 2);
      r.over.push(0, 0, Math.max(this.halfW, this.halfH) * 2.6, 1.4 * a, 1.2 * a, 1.6 * a, 1, Shape.Puff);
    }
    look.end();
  }

  private renderStar(i: number, fin: number): void {
    const p = this.p;
    const look = this.look;
    const t = this.t;
    const m = p.w[i];
    const flags = p.flags[i];
    const x = p.x[i];
    const y = p.y[i];
    const L = luminosity(m);
    const giant = (flags & F_GIANT) !== 0;
    const ph = giant ? Math.min(1, (p.a[i] - GIANT_START) / (1 - GIANT_START)) : 0;
    const c = blackbody(giant ? 3300 + 1500 * (1 - ph) : temperature(m));
    let shown = L;
    let k = 1;
    if (giant) {
      // A red giant swells and brightens, and near its end it pulses (a Mira variable).
      shown = L * (2 + 40 * ph);
      if (ph > 0.6) k *= 0.8 + 0.2 * Math.sin(t * 6 + p.b[i]);
    }
    const countdown = (flags & F_COUNTDOWN) !== 0;
    let rem = 0;
    if (countdown) {
      rem = Math.max(0, this.remaining(i));
      const urgency = 1 - rem / COUNTDOWN;
      k *= 0.8 + 0.35 * Math.max(0, Math.sin(t * (6 + 22 * urgency)));
    }
    const appear = Math.min(1, p.age[i] * 3);
    const fade = flags & F_RETIRE ? Math.max(0, p.life[i] / 1.5) : 1;
    const a = appear * fade * fin;
    // A newborn star is still wrapped in the dust it formed from: dim and red, clearing over a few seconds.
    const embed = Math.max(0, 1 - p.age[i] / 2.5) * 0.8;
    look.star(x, y, c, shown, k * a, embed, giant ? 1 + 0.5 * ph : 1);
    // Luminous stars light the dust around them (reflection nebulae) and make the motes near them glint.
    if (shown > 40 && a > 0.02) {
      const lg = Math.log10(shown);
      const e = 0.004 * lg * a;
      look.light(x, y, 26 + 22 * lg, [c[0] * e, c[1] * e, c[2] * e], 0.3 * lg * a);
    }
    if (giant) look.light(x, y, 22 + 30 * ph, [0.3 * ph * a, 0.09 * ph * a, 0.045 * ph * a]);
    const size = this.starSize(m);
    if (countdown) {
      // The ring closes exactly as the core collapses: press on that beat.
      const near = rem <= PERFECT_WINDOW;
      look.circle(x, y, size * (1.2 + 5 * (rem / COUNTDOWN)), near ? [1.0, 0.86, 0.5] : [1.0, 0.7, 0.36], (near ? 1.5 : 0.75) * fin, (near ? 0.22 : 0.08) * fin, 2.2);
    }
    if (p.id[i] === this.feedId && this.pDown) look.reticle(x, y, Math.max(12, size * 2) + 1.5 * Math.sin(t * 8), [1.0, 0.7, 0.78], 1);
    else if (p.id[i] === this.hoverId) look.reticle(x, y, Math.max(11, size * 1.8), [0.85, 0.87, 0.95], 0.75);
    if (flags & F_SUN && this.finaleT < 0) look.reticle(x, y, 15, [1.0, 0.86, 0.6], 0.6 + 0.2 * Math.sin(t * 1.5));
  }

  private renderPairs(fin: number): void {
    const p = this.p;
    const seen = new Set<Pair>();
    for (const pair of this.pairs.values()) {
      if (seen.has(pair)) continue;
      seen.add(pair);
      const i = p.find(pair.a);
      const j = p.find(pair.b);
      if (i < 0 || j < 0) continue;
      const ki = p.kind[i];
      const kj = p.kind[j];
      const feeds = (ki === WD || ki === BH) && kj === STAR ? [i, j] : (kj === WD || kj === BH) && ki === STAR ? [j, i] : null;
      if (!feeds) continue;
      // Gas streams from the companion onto the dead star and swirls into a hot disk.
      const [acc, donor] = feeds;
      const flick = 0.85 + 0.15 * Math.sin(this.t * 17 + p.b[acc]);
      this.look.accretion(p.x[donor], p.y[donor], p.x[acc], p.y[acc], p.kind[acc] === BH, flick * fin, this.t);
      if (p.kind[acc] === WD) {
        // How close the white dwarf is to the limit: a thin arc that closes at 1.4 Suns.
        this.look.gauge(p.x[acc], p.y[acc], 12, Math.min(1, (p.w[acc] - 0.5) / (CHANDRASEKHAR - 0.5)), fin);
      }
    }
  }

  private renderShells(fin: number): void {
    const look = this.look;
    for (const sh of this.shells) {
      const u = sh.age / sh.life;
      // Every shell swells in over its first moments and thins away to nothing.
      const f = Math.pow(1 - u, 1.6) * Math.min(1, sh.age * 2.5) * fin;
      if (f <= 0.002) continue;
      const { x, y } = sh;
      const s = sh.seed % 7;
      switch (sh.kind) {
        case ShellKind.Nebula: {
          // A planetary nebula, small and slow (the Ring, the Helix): a limb-bright shell of hydrogen and
          // nitrogen red around a teal glow of oxygen, the white dwarf at its heart.
          const rho = sh.size * (0.35 + 0.65 * (1 - Math.pow(1 - Math.min(1, u * 1.6), 2)));
          const R = rho * 1.9;
          look.shell({ x, y, radius: R, width: 1.2 + R * 0.09, rim: [0.55 * f, 0.1 * f, 0.14 * f], inner: [0.02 * f, 0.12 * f, 0.1 * f], broken: 0.3, seed: s }, f * R);
          look.shell({ x, y, radius: R * 0.8, width: 1 + R * 0.08, rim: [0.05 * f, 0.3 * f, 0.26 * f], inner: [0, 0, 0], broken: 0.15, seed: s + 2.1 }, f * R * 0.8);
          break;
        }
        case ShellKind.Remnant: {
          // A supernova remnant (the Veil, the Crab): broken filaments of hydrogen-alpha red with oxygen
          // teal just inside, and while it is young a blue-white synchrotron glow at its heart.
          const R = 8 + sh.size * (1 - Math.pow(1 - u, 2.4));
          const young = Math.max(0, 1 - u * 2.5);
          look.shell({ x, y, radius: R, width: 1.4 + R * 0.035, rim: [0.75 * f, 0.13 * f, 0.17 * f], inner: [0.08 * young * f, 0.11 * young * f, 0.24 * young * f], broken: 0.85, seed: s }, f * R * 2);
          look.shell({ x, y, radius: R * 0.93, width: 1.2 + R * 0.03, rim: [0.06 * f, 0.36 * f, 0.3 * f], inner: [0, 0, 0], broken: 0.75, seed: s + 3.3 }, f * R);
          if (young > 0) look.light(x, y, R * 0.8, [0.04 * young * f, 0.06 * young * f, 0.12 * young * f]);
          break;
        }
        case ShellKind.Ia: {
          // A Type Ia remnant (Tycho, Kepler): nearly round and fine, pale gold with a blue edge.
          const R = 10 + sh.size * (1 - Math.pow(1 - u, 2.2));
          look.shell({ x, y, radius: R, width: 1.2 + R * 0.025, rim: [0.6 * f, 0.48 * f, 0.33 * f], inner: [0.03 * f, 0.025 * f, 0.02 * f], broken: 0.35, seed: s }, f * R * 2);
          look.shell({ x, y, radius: R * 1.03, width: 1 + R * 0.02, rim: [0.14 * f, 0.23 * f, 0.52 * f], inner: [0, 0, 0], broken: 0.4, seed: s + 5.1 }, f * R);
          break;
        }
        case ShellKind.Kilonova: {
          // Freshly made lanthanides: the ejecta glow blue-white for a moment, then cool to red-gold.
          const R = 5 + sh.size * (1 - Math.pow(1 - u, 2));
          const cool = Math.min(1, u * 2.2);
          const cr = (1.3 + 0.2 * cool) * f;
          const cg = (1.1 - 0.75 * cool) * f;
          const cb = (1.2 - 1.05 * cool) * f;
          look.shell({ x, y, radius: R, width: 1.5 + R * 0.08, rim: [cr * 0.4, cg * 0.4, cb * 0.4], inner: [cr * 0.12, cg * 0.12, cb * 0.12], broken: 0.5, seed: s }, f * R * 2);
          look.light(x, y, R * 1.5, [cr * 0.05, cg * 0.05, cb * 0.05]);
          break;
        }
      }
    }
  }

  // ───────────────────────────────────────── input

  private nearest(x: number, y: number, kinds: readonly number[], reach: (i: number) => number, ok: (i: number) => boolean = () => true): number {
    const p = this.p;
    let best = -1;
    let bd = Infinity;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i) || !kinds.includes(p.kind[i]) || !ok(i)) continue;
      const d = (p.x[i] - x) ** 2 + (p.y[i] - y) ** 2;
      const R = reach(i);
      if (d < R * R && d < bd) {
        bd = d;
        best = i;
      }
    }
    return best;
  }

  pointer(e: PointerInfo): void {
    if (!e.primary) return;
    this.pX = e.x;
    this.pY = e.y;
    const p = this.p;
    if (e.type === 'move') {
      if (!this.pDown) {
        const h = this.nearest(e.x, e.y, [STAR, NS, BH], (i) => (p.kind[i] === STAR ? p.r[i] + 8 : 22));
        const id = h >= 0 ? p.id[h] : 0;
        if (id !== this.hoverId) {
          this.hoverId = id;
          this.hoverT = this.t;
        }
      }
      return;
    }
    if (e.type === 'up' || e.type === 'cancel') {
      this.pDown = false;
      this.feedId = 0;
      if (this.dragId) this.dropRemnant();
      return;
    }
    // Press.
    this.idle = 0;
    this.pDown = true;
    if (this.finaleT >= 0) return;
    const g = this.g;
    // A collapsing star: pressing on the last beat makes a perfect collapse.
    const cd = this.nearest(e.x, e.y, [STAR], (i) => p.r[i] + 16, (i) => (p.flags[i] & F_COUNTDOWN) !== 0);
    if (cd >= 0) {
      if (this.remaining(cd) <= PERFECT_WINDOW) {
        p.flags[cd] |= F_PERFECT;
        this.die(cd);
      } else {
        g.sfx('forge.early', p.x[cd]);
        this.fx.spawn(Fx.Ring, p.x[cd], p.y[cd], 0.3, 10, 0.5, 0.25, 0.2, 60);
      }
      return;
    }
    // A lone neutron star or black hole: pick it up.
    const rem = this.nearest(e.x, e.y, [NS, BH], () => 24, (i) => !this.pairs.has(p.id[i]));
    if (rem >= 0) {
      this.dragId = p.id[rem];
      this.s.everDragged = true;
      return;
    }
    const st = this.nearest(e.x, e.y, [STAR], (i) => p.r[i] + 6);
    if (st >= 0) {
      if (p.flags[st] & F_SUN) {
        this.notes.push({ text: 'The Sun', x: p.x[st], y: p.y[st] - 26, age: 0 });
        return;
      }
      this.feedId = p.id[st];
      return;
    }
    // Inside a cloud: a dense core collapses into a new star, and holding feeds it.
    const c = this.nearest(e.x, e.y, [CLOUD], (i) => p.r[i] * 0.95, (i) => p.w[i] >= 0.6);
    if (c >= 0) {
      const ni = this.birth(c, 0.35, false, { x: e.x, y: e.y });
      if (ni >= 0) {
        this.feedId = p.id[ni];
        this.s.everCreated = true;
        g.sfx('forge.birth', e.x, 1, 0.35);
        this.fx.spawn(Fx.Ring, e.x, e.y, 0.5, 24, 0.8, 0.45, 0.5, -30);
      }
      return;
    }
    this.noGas = 1.5;
    g.sfx('forge.nogas', e.x);
    this.fx.spawn(Fx.Ring, e.x, e.y, 0.4, 8, 0.25, 0.2, 0.25, 40);
  }

  /** Dropped near another lone remnant, a neutron star or black hole joins it in a tight orbit. */
  private dropRemnant(): void {
    const p = this.p;
    const i = p.find(this.dragId);
    this.dragId = 0;
    if (i < 0) return;
    const j = this.nearest(p.x[i], p.y[i], [NS, BH], () => 70, (k) => k !== i && !this.pairs.has(p.id[k]));
    if (j < 0) return;
    this.makePair(p.id[i], p.id[j], 18, Math.atan2(p.y[i] - p.y[j], p.x[i] - p.x[j]));
    this.g.setFlag('forge.compactPair');
    this.g.sfx('forge.pair', p.x[i]);
  }

  // ───────────────────────────────────────── HUD

  labels(): WorldLabel[] {
    const p = this.p;
    const out: WorldLabel[] = [];
    const info = (i: number, tone: 'value' | 'quiet', id: string) => {
      const m = p.w[i];
      const y = p.y[i] - Math.max(18, this.starSize(m) * 2.4);
      const fateText = FATE_TEXT[fate(m) as Fate];
      out.push({ id: `${id}-a`, x: p.x[i], y: y - 14, text: `${m < 10 ? m.toFixed(1) : Math.round(m)} Suns · ${fateText}`, tone });
      out.push({ id: `${id}-b`, x: p.x[i], y, text: m < ETERNAL_MASS ? `lives ${lifeText(m)}` : `lives about ${lifeText(m)}`, tone: 'quiet', opacity: 0.85 });
    };
    if (this.finaleT < 0) {
      const fi = this.feedId && this.pDown ? p.find(this.feedId) : -1;
      if (fi >= 0) info(fi, 'value', 'feed');
      else if (this.hoverId && this.t - this.hoverT > 0.3) {
        const h = p.find(this.hoverId);
        if (h >= 0 && p.kind[h] === STAR && !(p.flags[h] & F_SUN)) info(h, 'quiet', 'hover');
        else if (h >= 0 && (p.kind[h] === NS || p.kind[h] === BH)) {
          const name = p.kind[h] === NS ? 'Neutron star' : `Black hole · ${Math.round(p.w[h])} Suns`;
          out.push({ id: 'hover-r', x: p.x[h], y: p.y[h] - 24, text: name, tone: 'quiet' });
        }
      }
    }
    const sun = this.sunIndex();
    // Offsets that stay the same on screen while the finale's camera moves (world units per unit at rest).
    const px = this.g.renderer ? this.g.renderer.camera.halfH / 500 : 1;
    if (sun >= 0 && this.bgParams.finale < 0.3) {
      const f = this.finaleT >= 0 ? Math.min(1, Math.max(0, (this.finaleT - 1.2) / 1.5)) : 0.75;
      out.push({ id: 'sun', x: p.x[sun], y: p.y[sun] - 26 * px, text: 'The Sun', tone: 'quiet', opacity: f });
      if (this.finaleT >= 0) out.push({ id: 'sun-age', x: p.x[sun], y: p.y[sun] + 26 * px, text: '4.6 billion years old', tone: 'quiet', opacity: f * 0.8 });
    }
    if (sun >= 0 && this.bgParams.finale > 0.6) {
      out.push({ id: 'sun-far', x: p.x[sun], y: p.y[sun] - 34 * px, text: 'The Sun', tone: 'quiet', opacity: Math.min(1, (this.bgParams.finale - 0.6) * 2.5) });
    }
    for (const tl of this.tiles) {
      if (tl.age < 0) continue;
      const el = MAKEABLE.find((e) => e.z === tl.z);
      if (!el) continue;
      const rise = 1 - Math.pow(1 - Math.min(1, tl.age / 2.2), 2);
      const op = tl.age < 0.25 ? tl.age / 0.25 : tl.age > 1.9 ? Math.max(0, (2.6 - tl.age) / 0.7) : 1;
      out.push({ id: `tile-${tl.z}`, x: tl.x, y: tl.y - 30 - 46 * rise, text: el.symbol, sub: String(el.z), tone: 'tile', color: ORIGIN_COLOR[el.origin], opacity: op });
    }
    for (const n of this.notes) {
      out.push({ id: `note-${n.text}-${n.x.toFixed(0)}`, x: n.x, y: n.y - 16 * n.age, text: n.text, tone: 'value', opacity: Math.max(0, 1 - n.age / 1.8) });
    }
    return out;
  }

  stocks(): StockView[] {
    const s = this.s;
    const out: StockView[] = [
      { id: 'stars', label: 'Stars', value: s.stars, format: 'count', rate: this.starMeter.rate, hint: 'Stars born in this galaxy so far.' },
      { id: 'gas', label: 'Gas', value: this.gasTotal() * this.weight, format: 'count', hint: 'Cold gas left to make stars, in Suns. Dying stars give most of theirs back, richer in metals.' },
      { id: 'metals', label: 'Metals', value: this.metallicity, format: 'percent', ours: Z_SUN, hint: 'The share of the gas heavier than helium. The Sun was born with about 1.4 %.' },
      { id: 'elements', label: 'Elements', value: s.made.length, format: 'count', hint: 'Elements made in this universe, of the 83 that can survive from a star until today.' },
    ];
    if (s.bh > 0) out.push({ id: 'bh', label: 'Black holes', value: s.bh, format: 'count', hint: 'What the heaviest stars leave behind. Remember them.' });
    return out;
  }

  dotScale(): { value: number; unit: string } | null {
    return { value: this.weight, unit: 'stars' };
  }

  /**
   * Time away: the galaxy goes on at the rates it had (§5.9). Stars are born, die and leave
   * remnants, the gas grows richer, and every element on its way gets what it was getting. The
   * energy all this gave is the core's measured rate; nothing here adds more.
   */
  offline(seconds: number): OfflineReport {
    const s = this.s;
    const r = this.rates;
    const lines: OfflineReport['lines'] = [];
    const stars = this.starMeter.rate * seconds;
    s.stars += stars;
    if (stars > 0) lines.push({ label: 'Stars born', value: toText(count(stars)) });
    for (const key of ['wd', 'ns', 'bh'] as const) s[key] += Math.max(0, r[key]) * seconds;
    const events = (key: 'pn' | 'sn' | 'ia' | 'kn', label: string) => {
      const n = Math.floor(Math.max(0, r[key]) * seconds);
      s[key] += n;
      if (n > 0) lines.push({ label, value: toText(count(n)) });
    };
    events('sn', 'Supernovae');
    events('pn', 'Planetary nebulae');
    events('ia', 'Type Ia supernovae');
    events('kn', 'Kilonovae');
    // Metals pile up, but never past where metal-rich gas stops forming stars any faster.
    const cap = 1.5 * Z_SUN * this.gasTotal();
    if (r.metals > 0 && s.zGas < cap) s.zGas = Math.min(cap, s.zGas + r.metals * seconds);
    const made: string[] = [];
    for (const e of MAKEABLE) {
      const rate = r.prod[e.z];
      if (!rate || this.made.has(e.z)) continue;
      s.prod[e.z] = (s.prod[e.z] ?? 0) + rate * seconds;
      if (s.prod[e.z] >= threshold(e)) {
        delete s.prod[e.z];
        this.makeElement(e.z, 0, 0, false);
        made.push(e.symbol);
      }
    }
    if (made.length) lines.push({ label: made.length === 1 ? 'New element' : 'New elements', value: made.length <= 6 ? made.join(' ') : String(made.length) });
    this.markRates();
    return { lines };
  }

  accent(): RGB {
    const age = this.bgParams.age;
    return [1, 0.58 + 0.22 * age, 0.62 - 0.12 * age];
  }

  hint(): string | null {
    if (this.finaleT >= 0) return null;
    const s = this.s;
    const p = this.p;
    if (this.noGas > 0) return 'No gas there. Press inside a cloud.';
    if (!s.everCreated && !s.everFed && this.idle > 3) return 'Press inside a cloud to start a star. Hold to feed it.';
    if (s.everFed && s.sn === 0 && this.idle > 8) return 'Feed a star past eight Suns and it will end as a supernova.';
    if (s.perfect === 0 && s.sn < 6) {
      for (let i = 0; i < p.n; i++) if (!p.isDead(i) && p.flags[i] & F_COUNTDOWN) return 'Press the star just as the ring closes.';
    }
    // Also when only the rapid process can finish the table for "Today".
    if ((s.kn === 0 && !s.everDragged) || (this.step >= 5 && ForgeEra.todayNeeds(s.made).fromMergers > 0)) {
      let lone = 0;
      for (let i = 0; i < p.n; i++) if (!p.isDead(i) && p.kind[i] === NS && !this.pairs.has(p.id[i])) lone++;
      if (lone >= 2) return 'Drag one neutron star onto another.';
    }
    if (this.gasTotal() < 40) return 'The clouds are running thin. Dying stars give their gas back.';
    return null;
  }
}

