<!--
  Shared shell for side panels (Codex, Universe, Settings): slides in from the right, Esc closes.
  Opening moves keyboard focus into the panel; closing hands it back to where it was.
-->
<script module lang="ts">
  /** Where focus was before the first of a run of panels opened (switching panels keeps it). */
  let returnTo: HTMLElement | null = null;
</script>

<script lang="ts">
  import { onMount, type Snippet } from 'svelte';
  import { fly } from 'svelte/transition';
  import { still, ui } from '../store.svelte';

  let { title, children, wide = false }: { title: string; children: Snippet; wide?: boolean } = $props();
  let el: HTMLElement;
  const headingId = $props.id();

  onMount(() => {
    const prev = document.activeElement as HTMLElement | null;
    if (!prev?.closest('.panel')) returnTo = prev;
    el.focus({ preventScroll: true });
    return () => {
      if (ui.panel !== null) return;
      // Only take focus back if it was still in the panel; a click on the cosmos keeps it there.
      const now = document.activeElement;
      if ((!now || now === document.body || el.contains(now)) && returnTo?.isConnected) returnTo.focus({ preventScroll: true });
      returnTo = null;
    };
  });
</script>

<div class="panel" class:wide transition:fly={{ x: still() ? 0 : 24, duration: 260 }} role="dialog" aria-labelledby={headingId} tabindex="-1" bind:this={el}>
  <header>
    <h2 id={headingId}>{title}</h2>
    <button class="close" onclick={() => (ui.panel = null)} aria-keyshortcuts="Escape">Close <kbd aria-hidden="true">Esc</kbd></button>
  </header>
  <div class="body">
    {@render children()}
  </div>
</div>

