<!--
  The frame's left margin, set flush right against the field: energy and its rate, the goal with
  its progress rule, then the counts of what this era is making. Hover or focus reveals more.
-->
<script lang="ts">
  import type { StepGoal } from '../../core/era';
  import { count, energy, toText } from '../../core/format';
  import { energyComparison } from '../../content/comparisons';
  import Num from '../common/Num.svelte';
  import { game, track } from '../store.svelte';
  import { energyUnit, formatStock } from '../view';
  import { lowerFirst } from './words';

  const g = game();
  const id = $props.id();

  const v = $derived.by(() => {
    track();
    const run = g.state.run;
    const unit = energyUnit(g);
    const notation = g.state.settings.notation;
    const next = g.inFinale ? null : g.nextStep;
    // The next step's own goal; failing one, the step itself and what it needs.
    let goal: StepGoal | null = null;
    if (next) {
      const blocker = g.stepBlocker();
      goal = g.stepGoal() ?? {
        text: next.label,
        detail: blocker ?? `needs ${toText(energy(next.cost, unit, notation))}`,
        progress: next.cost > 0 ? Math.min(1, run.energy / next.cost) : 1,
      };
    }
    const scale = g.era?.dotScale?.() ?? null;
    return {
      e: energy(run.energy, unit, notation),
      rate: energy(g.energyMeter.rate, unit, notation),
      hasRate: g.energyMeter.rate > 0,
      compare: energyComparison(run.energy),
      total: energy(run.energyTotal, unit, notation),
      goal,
      stocks: (g.era?.stocks() ?? []).map((s) => ({
        ...s,
        shown: formatStock(g, s, s.value),
        rateShown: s.rate !== undefined && s.rate > 0 ? formatStock(g, s, s.rate) : null,
        oursShown: s.ours !== undefined ? formatStock(g, s, s.ours) : null,
      })),
      scale: scale && { unit: scale.unit, shown: count(scale.value, notation) },
    };
  });
</script>

<section class="ledger" aria-label="Energy and goal">
  <div class="cap" id="{id}-energy">Energy</div>
  <!-- svelte-ignore a11y_no_noninteractive_tabindex (focusable so keyboard players can read the comparison) -->
  <div class="reveal-host" tabindex="0" aria-labelledby="{id}-energy {id}-value" aria-describedby="{id}-energy-more">
    <div class="big" id="{id}-value"><Num parts={v.e} /></div>
    <div class="rate dim" class:none={!v.hasRate}><Num parts={v.rate} sign="+" /> a second</div>
    <div class="reveal" id="{id}-energy-more">
      <div>
        {#if v.compare}<p class="faint small">{v.compare}</p>{/if}
        <p class="faint small">Total this universe: <Num parts={v.total} /></p>
      </div>
    </div>
  </div>

  {#if v.goal}
    <div class="block goal">
      <div class="cap">Goal</div>
      <div class="line">{v.goal.text}</div>
      <div
        class="progress"
        role="progressbar"
        aria-label="Progress toward the goal"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(v.goal.progress * 100)}
      >
        <i style="width: {v.goal.progress * 100}%"></i>
      </div>
      {#if v.goal.detail}<div class="small dim">{v.goal.detail}</div>{/if}
    </div>
  {/if}

  {#if v.stocks.length > 0}
    <div class="block counts">
      {#each v.stocks as s (s.id)}
        <!-- svelte-ignore a11y_no_noninteractive_tabindex (focusable so keyboard players can read what it counts) -->
        <div class="count reveal-host" tabindex="0" aria-describedby="{s.oursShown ? `${id}-${s.id}-ours ` : ''}{id}-{s.id}">
          <span class="row"><b><Num parts={s.shown} /></b><span class="dim">{lowerFirst(s.label)}</span></span>
          <!-- Our universe's figure stays in view: it is what this count is measured against. -->
          {#if s.oursShown}<p class="ours dim small" id="{id}-{s.id}-ours">in our universe, <Num parts={s.oursShown} /></p>{/if}
          <div class="reveal" id="{id}-{s.id}">
            <div>
              {#if s.rateShown}<p class="faint small"><Num parts={s.rateShown} sign="+" /> a second</p>{/if}
              {#if s.hint}<p class="faint small">{s.hint}</p>{/if}
            </div>
          </div>
        </div>
      {/each}
      {#if v.scale}<p class="faint small dots">1 dot = <Num parts={v.scale.shown} /> {v.scale.unit}</p>{/if}
    </div>
  {/if}
</section>

<style>
  .ledger {
    text-align: right;
  }
  .reveal-host {
    pointer-events: auto;
    display: block;
    cursor: default;
  }
  .big {
    font-weight: 300;
    font-size: 3.05rem;
    line-height: 1;
    letter-spacing: -0.02em;
    color: #fff;
  }
  .big :global(.u) {
    font-size: 1.33rem;
    letter-spacing: 0;
    opacity: 1;
    color: rgb(255 255 255 / 0.7);
  }
  .rate {
    font-size: 0.87rem;
    margin-top: 0.55rem;
    transition: opacity var(--med) var(--ease);
  }
  .rate.none {
    opacity: 0;
  }
  .goal .line {
    font-size: 1.13rem;
    line-height: 1.3;
    text-wrap: balance;
  }
  .progress i {
    right: 0;
  }
  .count {
    font-size: 1rem;
    line-height: 1.9;
  }
  .count b {
    font-weight: 300;
    font-size: 1.27rem;
    margin-right: 0.4rem;
    color: #fff;
  }
  .count .reveal p {
    line-height: 1.45;
    margin-bottom: 0.35rem;
  }
  /* Qualified, to outweigh the frame's reset of paragraph margins. */
  .count .ours {
    line-height: 1.2;
    margin: -0.25rem 0 0.45rem;
  }
  .counts .dots {
    margin-top: 1rem;
  }
</style>
