/**
 * Pieces of the v2 looks shared by the Soup and Era II.
 *
 * - Best: the strongest of the lights (fronts, pushes, tubes) offered in a frame, for a layer that has
 *   only a few slots. It keeps them without sorting or allocating, and a keyed light that held a slot
 *   last frame competes with a bonus, so near-equals don't trade places every frame and a light doesn't
 *   pop on and off as flashes come and go.
 * - Packets: photons drawn as wave packets, the Feynman diagram's photon made of light. A short
 *   sinusoidal thread under a Gaussian envelope, inside a faint straight glow, racing along.
 */
import type { Filaments } from '../../render/filaments';

type RGB = readonly [number, number, number];

/** How much more a keyed light that held a slot last frame weighs when it competes again. */
const STAY = 1.5;

export class Best<T> {
  /** This frame's winners (refilled by `list`). */
  private readonly out: T[] = [];
  private readonly slots: T[];
  private readonly w: Float32Array;
  private readonly keys: Float64Array;
  private readonly held: Float64Array;
  private heldCount = 0;
  private count = 0;

  constructor(
    readonly size: number,
    make: () => T,
  ) {
    this.slots = Array.from({ length: size }, make);
    this.w = new Float32Array(size);
    this.keys = new Float64Array(size);
    this.held = new Float64Array(size);
  }

  /** Starts a frame. */
  reset(): void {
    this.count = 0;
  }

  /**
   * A slot for an item of `weight` (and stable `key`, 0 for none) to be written into, or null if it
   * doesn't make the cut. What a slot held before is overwritten.
   */
  take(weight: number, key = 0): T | null {
    let w = weight;
    if (key !== 0) {
      for (let k = 0; k < this.heldCount; k++) {
        if (this.held[k] === key) {
          w *= STAY;
          break;
        }
      }
    }
    let i = this.count;
    if (i < this.size) this.count++;
    else {
      i = 0;
      for (let k = 1; k < this.size; k++) if (this.w[k] < this.w[i]) i = k;
      if (w <= this.w[i]) return null;
    }
    this.w[i] = w;
    this.keys[i] = key;
    return this.slots[i];
  }

  /** Ends the frame: the winners, in no particular order (the same array every frame). */
  list(): T[] {
    this.out.length = 0;
    this.heldCount = 0;
    for (let k = 0; k < this.count; k++) {
      this.out.push(this.slots[k]);
      if (this.keys[k] !== 0) this.held[this.heldCount++] = this.keys[k];
    }
    return this.out;
  }
}

/** Points in one packet's thread at High detail (callers' filaments thin them at lower levels). */
const PACKET_PTS = 56;

/** Scratch for drawing packets (one set, reused: the filaments copy what they are given). */
const pts = new Float32Array(PACKET_PTS * 2);
const core = new Float32Array(PACKET_PTS);
const sheath = new Float32Array(PACKET_PTS);
const axis = new Float32Array(10);
const axisCore = new Float32Array(5);
const axisSheath = new Float32Array(5);
const tint: [number, number, number] = [0, 0, 0];

/**
 * A photon at (x, y) moving along (vx, vy): `k` its brightness, `c` its tint (any brightness: only
 * the hue is used), `sigma` the envelope's width and `lambda` the wavelength (world units), `t` the
 * time (the wave crawls forward inside its envelope).
 */
export function packet(fil: Filaments, x: number, y: number, vx: number, vy: number, k: number, c: RGB, sigma: number, lambda: number, t: number): void {
  if (k <= 0.004) return;
  const sp = Math.hypot(vx, vy) || 1;
  const ux = vx / sp;
  const uy = vy / sp;
  const peak = Math.max(c[0], c[1], c[2], 1e-3);
  // A paler version of its hue: light, not paint.
  for (let m = 0; m < 3; m++) tint[m] = 0.2 + 0.8 * (c[m] / peak);
  const n = fil.segments(PACKET_PTS - 1, 24) + 1;
  const reach = 2.3 * sigma;
  const amp = 0.17 * lambda;
  const crawl = t * 9;
  for (let i = 0; i < n; i++) {
    const s = -reach + (2 * reach * i) / (n - 1);
    const env = Math.exp(-(s * s) / (sigma * sigma));
    const off = amp * env * Math.sin((Math.PI * 2 * s) / lambda - crawl);
    pts[i * 2] = x + ux * s - uy * off;
    pts[i * 2 + 1] = y + uy * s + ux * off;
    core[i] = k * env;
    sheath[i] = 0.05 * k * env;
  }
  fil.push(pts, tint, tint, 1.7, core, sheath, false, n);
  // The envelope's own glow: a faint straight streak of the same light along the axis.
  for (let i = 0; i < 5; i++) {
    const s = -reach + (2 * reach * i) / 4;
    const env = Math.exp(-(s * s) / (sigma * sigma));
    axis[i * 2] = x + ux * s;
    axis[i * 2 + 1] = y + uy * s;
    axisCore[i] = 0;
    axisSheath[i] = 0.12 * k * env;
  }
  fil.push(axis, tint, tint, 2.2 + 0.18 * sigma, axisCore, axisSheath, false, 5);
}
