/**
 * Codex: what the player has discovered, organised by each era's iconic chart. Discoveries persist
 * across universes (the player remembers what a universe forgets) and some carry a small, named,
 * permanent bonus tied to what the thing really does.
 */
import type { EraId } from './state';
import type { Modifier } from './stats';

export type ChartId =
  | 'standard-model'
  | 'nuclides'
  | 'atoms'
  | 'first-stars'
  | 'elements'
  | 'galaxies'
  | 'ages'
  | 'constants'
  | 'notes';

export interface CodexEntry {
  id: string;
  title: string;
  /** Short symbol for chart tiles ("u", "γ", "⁴He", "Fe"). */
  symbol?: string;
  chart: ChartId;
  era: EraId;
  /** 2–4 sentences, plain and exact. */
  text: string;
  /** Optional permanent bonus. `text` is shown on the entry. */
  bonus?: { text: string; mods: Modifier[] };
  /** Chart-specific layout data (grid position, group). */
  layout?: { col: number; row: number; group?: string };
}

export const CHART_TITLES: Record<ChartId, string> = {
  'standard-model': 'The Standard Model',
  nuclides: 'Light Nuclei',
  atoms: 'Atoms & First Molecules',
  'first-stars': 'The First Stars',
  elements: 'The Periodic Table',
  galaxies: 'Galaxies',
  ages: 'The Five Ages',
  constants: 'Six Numbers',
  notes: 'Notes',
};
