/**
 * Number and unit formatting.
 *
 * Every figure is produced as structured parts so the UI can typeset real superscripts
 * ("4.21 × 10⁴⁵ J") while plain-text contexts get Unicode superscripts from the same source.
 */

export interface NumParts {
  /** Mantissa or plain number. Empty when a bare power of ten reads better ("10⁻¹¹ s"). */
  m: string;
  /** Power of ten in scientific form, otherwise null. */
  e: number | null;
  /** Unit including any SI prefix ("GeV", "kJ", "µs"). May be empty. */
  u: string;
}

export type Notation = 'scientific' | 'engineering';

export const EV_PER_JOULE = 6.241509074e18;
export const SECONDS_PER_YEAR = 3.15576e7; // Julian year, the astronomer's year

const SUP: Record<string, string> = {
  '0': '⁰', '1': '¹', '2': '²', '3': '³', '4': '⁴',
  '5': '⁵', '6': '⁶', '7': '⁷', '8': '⁸', '9': '⁹', '-': '⁻',
};

/** "−11" → "⁻¹¹" */
export function superscript(n: number): string {
  return String(n)
    .split('')
    .map((ch) => SUP[ch] ?? ch)
    .join('');
}

/** Narrow no-break space: SI digit grouping ("123 456") that never wraps. */
const GROUP = ' ';
const MINUS = '−';

function group(intText: string): string {
  return intText.replace(/\B(?=(\d{3})+(?!\d))/g, GROUP);
}

/** Splits |n| into a mantissa in [1, 10) (or [1, 1000) for engineering) and an exponent, after rounding. */
function split(n: number, sig: number, notation: Notation): { mant: number; exp: number } {
  const a = Math.abs(n);
  let exp = Math.floor(Math.log10(a));
  if (notation === 'engineering') exp = Math.floor(exp / 3) * 3;
  let mant = a / 10 ** exp;
  // Round to the requested significant figures and renormalise if rounding carried (9.996 → 10.0).
  const digitsBefore = Math.floor(Math.log10(mant)) + 1;
  const decimals = Math.max(0, sig - digitsBefore);
  const f = 10 ** decimals;
  mant = Math.round(mant * f) / f;
  const limit = notation === 'engineering' ? 1000 : 10;
  if (mant >= limit) {
    mant /= notation === 'engineering' ? 1000 : 10;
    exp += notation === 'engineering' ? 3 : 1;
  }
  return { mant, exp };
}

/** Fixed significant figures ("4.20", "42.0", "420"), or trimmed ("4.2") when `trim` is set. */
function sigText(x: number, sig: number, trim: boolean): string {
  if (x === 0) return '0';
  const digitsBefore = Math.floor(Math.log10(Math.abs(x))) + 1;
  const decimals = Math.max(0, sig - digitsBefore);
  let s = x.toFixed(decimals);
  if (trim && s.includes('.')) s = s.replace(/\.?0+$/, '');
  return s;
}

function signed(text: string, n: number): string {
  return n < 0 ? MINUS + text : text;
}

export interface SciOptions {
  sig?: number;
  trim?: boolean;
  notation?: Notation;
  /** Omit a mantissa of exactly 1 ("10⁻¹¹" instead of "1 × 10⁻¹¹"). */
  bareOnes?: boolean;
}

/** Scientific parts for any finite number. */
export function sci(n: number, unit = '', opts: SciOptions = {}): NumParts {
  const { sig = 3, trim = false, notation = 'scientific', bareOnes = false } = opts;
  if (Number.isNaN(n)) return { m: '–', e: null, u: unit };
  if (!Number.isFinite(n)) return { m: n > 0 ? '∞' : '−∞', e: null, u: unit };
  if (n === 0) return { m: '0', e: null, u: unit };
  const { mant, exp } = split(n, sig, notation);
  if (exp === 0) return { m: signed(sigText(mant, sig, trim), n), e: null, u: unit };
  if (bareOnes && mant === 1) return { m: n < 0 ? MINUS : '', e: exp, u: unit };
  return { m: signed(sigText(mant, sig, trim), n), e: exp, u: unit };
}

/** Counts: grouped digits below a million, scientific above. */
export function count(n: number, notation: Notation = 'scientific'): NumParts {
  const a = Math.abs(n);
  if (a < 1e6) return { m: signed(group(String(Math.floor(a))), n), e: null, u: '' };
  return sci(n, '', { notation });
}

/**
 * Significant figures, with as many more (up to three) as it takes to keep a value just short of
 * `whole` from reading as `whole` (0.9997 of the hydrogen captured is not all of it).
 */
function shortOf(x: number, whole: number, sig: number, trim: boolean): string {
  let text = sigText(x, sig, trim);
  for (let extra = 1; extra <= 3 && x < whole && Number(text) >= whole; extra++) text = sigText(x, sig + extra, trim);
  return text;
}

/** A plain decimal with a few significant figures (multipliers, ratios). */
export function decimal(n: number, sig = 3, trim = true): NumParts {
  const a = Math.abs(n);
  if (Number.isNaN(n)) return sci(n);
  if (a !== 0 && (a < 1e-3 || a >= 1e6)) return sci(n, '', { sig, trim });
  return { m: signed(shortOf(a, 1, sig, trim), n), e: null, u: '' };
}

const EV_PREFIXES = ['', 'k', 'M', 'G', 'T', 'P', 'E'];
const J_PREFIXES = ['', 'k', 'M', 'G', 'T'];
const SUB_J_PREFIXES: [number, string][] = [
  [1e-3, 'm'],
  [1e-6, 'µ'],
  [1e-9, 'n'],
];

export type EnergyUnit = 'eV' | 'J';

/**
 * Energy is stored in electronvolts. It is displayed in eV with SI prefixes until the universe
 * has crossed one joule; from then on (a one-way switch held in run state) it is shown in joules.
 */
export function energy(eV: number, unit: EnergyUnit, notation: Notation = 'scientific'): NumParts {
  if (eV === 0) return { m: '0', e: null, u: unit };
  if (!Number.isFinite(eV)) return sci(eV, unit);
  if (unit === 'eV') {
    if (Math.abs(eV) < 1) return sci(eV, 'eV', { notation });
    return prefixed(eV, EV_PREFIXES, 'eV') ?? sci(eV, 'eV', { notation });
  }
  const j = eV / EV_PER_JOULE;
  const a = Math.abs(j);
  if (a < 1) {
    for (const [scale, prefix] of SUB_J_PREFIXES) {
      if (a >= scale) return prefixed(j / scale, [prefix], 'J') ?? sci(j, 'J', { notation });
    }
    return sci(j, 'J', { notation });
  }
  return prefixed(j, J_PREFIXES, 'J') ?? sci(j, 'J', { notation });
}

/**
 * Three significant figures with an SI prefix. Rounds first, then picks the prefix, so 999.7 GeV
 * reads "1.00 TeV" rather than "1000 GeV". Returns null when the value is beyond the prefix list.
 */
function prefixed(value: number, prefixes: readonly string[], base: string): NumParts | null {
  const { mant, exp } = split(value, 3, 'scientific');
  const tier = Math.floor(exp / 3);
  if (tier < 0 || tier >= prefixes.length) return null;
  const scaled = mant * 10 ** (exp - tier * 3);
  return { m: signed(sigText(scaled, 3, false), value), e: null, u: prefixes[tier] + base };
}

/** Power output in watts (eV/s in, displayed in the same unit family as energy). */
export function power(eVPerSecond: number, unit: EnergyUnit, notation: Notation = 'scientific'): NumParts {
  const p = energy(eVPerSecond, unit, notation);
  if (unit === 'J') return { ...p, u: p.u.replace(/J$/, 'W') };
  return { ...p, u: p.u + '/s' };
}

const SUB_SECOND: [number, string][] = [
  [1e-3, 'ms'],
  [1e-6, 'µs'],
  [1e-9, 'ns'],
];

/**
 * Cosmic time, from 10⁻³⁶ s to 10¹⁰⁰ years. Trimmed figures: these are milestones, not counters.
 * Each unit is picked after rounding, so 59.99 s reads "1 min", not "60 s".
 */
export function cosmicTime(seconds: number): NumParts {
  const s = seconds;
  if (Number.isNaN(s)) return sci(s, 's');
  if (s <= 0) return { m: '0', e: null, u: 's' };
  if (s < 1e-9) return sci(s, 's', { sig: 2, trim: true, bareOnes: true });
  // The value in a unit, if it still rounds to less than the next unit up.
  const within = (v: number, next: number, u: string): NumParts | null => {
    const m = sigText(v, 3, true);
    return Number(m) < next ? { m, e: null, u: m === '1' && u === 'days' ? 'day' : u } : null;
  };
  if (s < 1) {
    for (const [scale, unit] of SUB_SECOND) {
      if (s >= scale) {
        const p = within(s / scale, 1000, unit);
        if (p) return p;
      }
    }
  }
  const yr = s / SECONDS_PER_YEAR;
  return (
    (s < 60 ? within(s, 60, 's') : null) ??
    (s < 3600 ? within(s / 60, 60, 'min') : null) ??
    (s < 86400 ? within(s / 3600, 24, 'hr') : null) ??
    (yr < 1 ? within(s / 86400, SECONDS_PER_YEAR / 86400, 'days') : null) ??
    (yr < 1e3 ? within(yr, 1e3, 'yr') : null) ??
    (yr < 1e6 ? within(yr / 1e3, 1e3, 'kyr') : null) ??
    (yr < 1e9 ? within(yr / 1e6, 1e3, 'Myr') : null) ??
    (yr < 1e12 ? within(yr / 1e9, 1e3, 'Gyr') : null) ??
    sci(yr, 'yr', { sig: 2, trim: true, bareOnes: true })
  );
}

/** Temperature in kelvin: scientific when huge, grouped digits when human-scale. */
export function temperature(kelvin: number): NumParts {
  if (kelvin >= 1e5) return sci(kelvin, 'K', { sig: 2, trim: true, bareOnes: true });
  if (kelvin > 0 && kelvin < 1e-3) return sci(kelvin, 'K', { sig: 2, trim: true, bareOnes: true });
  if (kelvin >= 10) return { m: group(String(Math.round(kelvin))), e: null, u: 'K' };
  return { m: signed(sigText(Math.abs(kelvin), 2, true), kelvin), e: null, u: 'K' };
}

export function percent(fraction: number, sig = 3): NumParts {
  const v = fraction * 100;
  if (Number.isNaN(v)) return sci(v, '%');
  if (v !== 0 && Math.abs(v) < 0.01) return sci(v, '%', { sig: 2, trim: true });
  return { m: signed(shortOf(Math.abs(v), 100, sig, true), v), e: null, u: '%' };
}

/** Plain text with Unicode superscripts, for titles, toasts and canvas labels. */
export function toText(p: NumParts): string {
  let body = p.m;
  if (p.e !== null) body = (p.m && p.m !== MINUS ? p.m + ' × ' : p.m) + '10' + superscript(p.e);
  return p.u ? `${body} ${p.u}` : body;
}

/** Duration for humans (offline summaries, timers): "3 h 12 min", "45 s". */
export function duration(seconds: number): string {
  const s = Math.max(0, Math.round(seconds));
  if (s < 60) return `${s} s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m} min`;
  const h = Math.floor(m / 60);
  const rm = m % 60;
  if (h < 24) return rm ? `${h} h ${rm} min` : `${h} h`;
  const d = Math.floor(h / 24);
  const rh = h % 24;
  return rh ? `${d} d ${rh} h` : `${d} d`;
}
