/**
 * Boot: fonts and styles, the game, the audio director, the UI, and the glue between them.
 */
import '@fontsource-variable/newsreader';
import '@fontsource-variable/newsreader/wght-italic.css';
import '@fontsource/ibm-plex-mono/400.css';
import '@fontsource/ibm-plex-mono/500.css';
import '@fontsource/ibm-plex-sans/300.css';
import '@fontsource/ibm-plex-sans/400.css';
import '@fontsource/ibm-plex-sans/500.css';
import './ui/global.css';

import { mount } from 'svelte';
import App from './ui/App.svelte';
import { AudioDirector } from './audio/director';
import { Game } from './core/game';
import { cosmicTime } from './core/format';
import { exportString, LocalStorageAdapter } from './core/save';
import { watchAchievements } from './platform/achievements';
import { native, NativeStorageAdapter } from './platform/native';
import type { EraId, Quality } from './core/state';
import { ERAS as SHIPPED, WIP_ERAS } from './eras';
import { toCss, type RGB } from './render/color';
import { QUALITY, type QualityLevel, type Renderer } from './render/renderer';
import { frameEra } from './ui/frame/eras';
import { markStep } from './ui/frame/readings';
import { pushToast, setGame, still, ui } from './ui/store.svelte';

// ?wip (dev builds only) adds the eras still being built.
const ERAS = import.meta.env.DEV && new URLSearchParams(location.search).has('wip') ? WIP_ERAS : SHIPPED;
// In the desktop shell, saves are files (Steam Cloud syncs them); in a browser, localStorage.
const bridge = native();
const game = new Game({ storage: bridge ? new NativeStorageAdapter(bridge) : new LocalStorageAdapter(), eras: ERAS });
if (bridge?.steam.available()) watchAchievements(game, (id) => bridge.steam.achievement(id));
const director = new AudioDirector(game, (id) => ERAS[id]?.audio);
setGame(game, director);

// ── Game → UI glue
const accent: RGB = [0.74, 0.82, 1];
game.bus.on('ui', () => {
  ui.tick++;
  const target = game.era?.accent();
  if (target) {
    for (let i = 0; i < 3; i++) accent[i] += (target[i] - accent[i]) * 0.06;
    document.documentElement.style.setProperty('--accent', toCss(accent));
  }
});
game.bus.on('toast', (e) => pushToast(e.text, e.tone));
game.bus.on('ending', (e) => {
  ui.ending = e.phase;
  if (e.phase === 'done') setTimeout(() => (ui.ending = null), 2400);
});
game.bus.on('discover', (e) => pushToast(e.entry.title, 'discovery', e.entry.id));
/** Runs `fn` `ms` after the pull-back between eras now playing (if any) has settled. */
function afterPassing(fn: () => void, ms: number): void {
  if (!game.passing) {
    setTimeout(fn, ms);
    return;
  }
  const off = game.bus.on('ui', () => {
    if (game.passing) return;
    off();
    setTimeout(fn, ms);
  });
}
// The era's name when it begins. The frame shows it in its time caption as it powers on, and also on
// returning to the era (it shows no title otherwise); the v1 HUD shows a card over the scene, for a
// fresh start only, once the opening flash has passed. An era arriving through a pull-back is named
// once it has settled, not while the camera still moves and the readings still count.
game.bus.on('eraStart', (e) => {
  if (e.era === 'prologue') return;
  const def = ERAS[e.era];
  const framed = frameEra(e.era) !== null;
  if (!def || (!e.fresh && !framed)) return;
  const card = { key: Date.now(), title: def.title, epoch: def.epoch, time: cosmicTime(def.steps[0].t) };
  // Only if the universe is still in that era by then (a reset can cut a pull-back short).
  const name = () => {
    if (game.state.run.era === e.era && !game.state.meta.atMultiverse) ui.eraCard = card;
  };
  afterPassing(name, !framed ? 1300 : game.passing ? 400 : 0);
});
// A step is time passing: the frame's clock and thermometer run to the new date.
game.bus.on('step', (e) => {
  const prev = game.steps()[e.index - 1];
  if (prev) markStep(prev, e.step, still());
});
game.bus.on('offline', (e) => {
  if (e.seconds >= 60) ui.offline = { seconds: e.seconds, energy: e.energy, lines: e.report.lines };
});

// ── Settings that live outside the game model
let renderer: Renderer | null = null;
let lastQuality: Quality | null = null;

/**
 * What this device knows about itself: the level Auto has settled on, and whether the player has been
 * told its graphics show a simplified look. Kept in the device's own storage (localStorage; in the
 * desktop shell that is the app's data folder, which Steam Cloud does not sync), never in the save,
 * which Steam Cloud carries to the player's other machines: a laptop's Low must not follow them to a
 * desktop. Tied to the GPU it was learned on, so on another one (a new card, a laptop's other GPU)
 * Auto starts over from High.
 */
interface DeviceRecord {
  gpu: string;
  auto: QualityLevel;
  toldSimplified: boolean;
}
const DEVICE_KEY = 'ylem.device';
let device: DeviceRecord = { gpu: '', auto: 'high', toldSimplified: false };

function loadDevice(gpu: string): DeviceRecord {
  try {
    const d = JSON.parse(localStorage.getItem(DEVICE_KEY) ?? 'null') as Partial<DeviceRecord> | null;
    if (d && d.gpu === gpu) return { gpu, auto: d.auto && d.auto in QUALITY ? d.auto : 'high', toldSimplified: d.toldSimplified === true };
  } catch {
    /* storage blocked or unreadable: this device starts over */
  }
  return { gpu, auto: 'high', toldSimplified: false };
}

function saveDevice(): void {
  try {
    localStorage.setItem(DEVICE_KEY, JSON.stringify(device));
  } catch {
    /* storage blocked: kept for this session only */
  }
}

function setAuto(level: QualityLevel): void {
  device.auto = level;
  saveDevice();
}

function applySettings(): void {
  const s = game.state.settings;
  document.documentElement.style.setProperty('--ui-scale', String(s.uiScale));
  // Switching to Auto starts it over from High.
  if (s.quality === 'auto' && lastQuality !== null && lastQuality !== 'auto') {
    setAuto('high');
    resetGovernor(160);
  }
  lastQuality = s.quality;
  if (!renderer) return;
  renderer.reduceFlashes = s.reduceFlashes;
  const level = s.quality === 'auto' ? device.auto : s.quality;
  renderer.setQuality(level in QUALITY ? level : 'high');
}
game.bus.on('settings', applySettings);

// Auto quality: when frames run well over budget through a few seconds of ordinary play, step down one
// level and say so. It never steps back up on its own (no see-sawing), never changes a level the player
// picked, and stops once a step brings no real gain (the frame rate is capped, or the time goes elsewhere).
// What it settles on is this device's (see DeviceRecord).
const SLOW_MS = 26;
const SLOW_TICKS = 100;
const NAMES: Record<QualityLevel, string> = { high: 'High', medium: 'Medium', low: 'Low' };
let settle = 0;
let slowTicks = 0;
let stepFrom = 0;
let stuck = false;
function resetGovernor(ticks: number): void {
  settle = Math.max(settle, ticks);
  slowTicks = 0;
  stepFrom = 0;
  stuck = false;
}
// UI ticks come 20 times a second: hold off for 8 s after boot and 5 s into each era, past loading
// and shader compiles.
resetGovernor(160);
game.bus.on('eraStart', () => resetGovernor(100));
game.bus.on('ui', () => {
  const s = game.state.settings;
  if (!renderer || s.quality !== 'auto' || device.auto === 'low' || stuck) return;
  if (game.inFinale || game.state.meta.atMultiverse) {
    slowTicks = 0;
    return;
  }
  if (settle > 0) {
    settle--;
    return;
  }
  const ms = game.frameMs;
  if (stepFrom > 0) {
    // The first look after a step: if it barely helped, a lower level won't either.
    if (ms > stepFrom * 0.85) {
      stuck = true;
      return;
    }
    stepFrom = 0;
  }
  if (ms > SLOW_MS) slowTicks++;
  else if (ms < 20) slowTicks = 0;
  if (slowTicks < SLOW_TICKS) return;
  const next = device.auto === 'high' ? 'medium' : 'low';
  setAuto(next);
  stepFrom = ms;
  slowTicks = 0;
  settle = 80;
  applySettings();
  pushToast(`Quality lowered to ${NAMES[next]} for a smoother frame rate`, 'quiet');
});

const target = document.getElementById('app');
if (!target) throw new Error('Missing #app');
mount(App, {
  target,
  props: {
    onReady: (r: Renderer) => {
      renderer = r;
      device = loadDevice(r.caps.renderer);
      // Saves from before Auto's level was kept per device carried it in their settings: let it go.
      delete (game.state.settings as unknown as Record<string, unknown>).autoQuality;
      game.attachRenderer(r);
      applySettings();
      if (import.meta.env.DEV) {
        // ?era=soup jumps straight into an era (dev and visual QA only). With &fresh the era starts
        // over: only its own progress is cleared (the codex, history and earlier eras stay), and the
        // universe as it was is kept in storage first, under ylem.before-restart.
        const params = new URLSearchParams(location.search);
        const era = params.get('era') as EraId | null;
        const fresh = params.has('fresh');
        const run = game.state.run;
        if (era && ERAS[era] && (run.era !== era || fresh)) {
          if (fresh) {
            try {
              localStorage.setItem('ylem.before-restart', exportString(game.state));
            } catch {
              /* storage blocked: the restart goes ahead without the copy */
            }
            delete run.eras[era];
            for (const id of Object.keys(run.phenomena)) if (id.startsWith(`${era}.`)) delete run.phenomena[id];
            for (const id of Object.keys(run.flags)) if (id.startsWith(`${era}.`)) delete run.flags[id];
            run.energy = 0;
            // A later reload continues the universe instead of restarting it again.
            history.replaceState(null, '', location.pathname + (params.has('wip') ? '?wip' : ''));
          }
          run.era = era;
          run.step = 0;
          run.time = ERAS[era]!.steps[0].t;
        }
      }
      game.boot();
      game.start();
      // Without float render targets the frame is drawn in a simplified, 8-bit form: say so, once.
      if (r.simplified && !device.toldSimplified) {
        device.toldSimplified = true;
        saveDevice();
        pushToast("This device's graphics can't render the full lighting, so the game shows a simplified look.", 'quiet');
      }
    },
  },
});

if (import.meta.env.DEV) {
  (window as unknown as { __ylem: unknown }).__ylem = {
    game,
    director,
    give: (eV: number) => game.gain(eV),
    advance: () => game.advance(),
    speed: (x: number) => (game.loop.timeScale = x),
    // Records the live mix for audio QA (tools/scenarios/opening-mix.ts); loaded only when asked for.
    capture: () => import('./audio/capture').then((m) => m.startCapture(director.engine)),
  };
}
