<!--
  Floating yields where energy is released. A fixed pool of DOM nodes animated imperatively, so a
  storm of events costs nothing; bursts are aggregated so the numbers stay readable. In the eras seen
  through the frame they are set in the frame's type.
-->
<script lang="ts">
  import { onMount } from 'svelte';
  import { energy, type NumParts } from '../../core/format';
  import { usesFrameType } from '../frame/eras';
  import { game, still, track } from '../store.svelte';

  const g = game();
  let host: HTMLDivElement;
  const framed = $derived.by(() => {
    track();
    return usesFrameType(g.state.run.era);
  });

  onMount(() => {
    const POOL = 24;
    const nodes: HTMLDivElement[] = [];
    for (let i = 0; i < POOL; i++) {
      const d = document.createElement('div');
      d.className = 'floater num';
      host.appendChild(d);
      nodes.push(d);
    }
    let next = 0;
    let last = 0;
    let pending = 0;
    let px = 0;
    let py = 0;
    let flushTimer: ReturnType<typeof setTimeout> | null = null;

    const html = (p: NumParts) => {
      const exp = p.e === null ? '' : `${p.m && p.m !== '−' ? p.m + ' × ' : p.m}10<sup>${p.e < 0 ? '−' + Math.abs(p.e) : p.e}</sup>`;
      return `+${exp || p.m}${p.u ? ` <span class="u">${p.u}</span>` : ''}`;
    };
    const show = () => {
      flushTimer = null;
      const r = g.renderer;
      if (!r || pending <= 0) return;
      const [sx, sy] = r.camera.worldToScreen(px, py, r.cssW, r.cssH);
      const d = nodes[next++ % POOL];
      d.innerHTML = html(energy(pending, g.state.run.joules ? 'J' : 'eV', g.state.settings.notation));
      d.style.transform = `translate(${Math.round(sx)}px, ${Math.round(sy - 14)}px)`;
      d.animate(
        [
          { opacity: 0, translate: `-50% ${still() ? 0 : 4}px` },
          { opacity: 1, translate: '-50% 0px', offset: 0.14 },
          { opacity: 0, translate: `-50% ${still() ? 0 : -34}px` },
        ],
        { duration: 1150, easing: 'cubic-bezier(0.2, 0.7, 0.2, 1)', fill: 'forwards' },
      );
      pending = 0;
      last = performance.now();
    };

    const off = g.bus.on('gain', (e) => {
      if (!g.state.settings.floatingNumbers) return;
      pending += e.amount;
      px = e.x;
      py = e.y;
      const since = performance.now() - last;
      if (since >= 110) show();
      else if (!flushTimer) flushTimer = setTimeout(show, 110 - since);
    });
    return () => {
      off();
      if (flushTimer) clearTimeout(flushTimer);
    };
  });
</script>

<div class="floaters" class:framed bind:this={host} aria-hidden="true"></div>

<style>
  .floaters {
    position: fixed;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
  }
  .floaters :global(.floater) {
    position: absolute;
    left: 0;
    top: 0;
    font-size: max(0.78rem, var(--min-text));
    color: var(--ink-2);
    white-space: nowrap;
    opacity: 0;
    text-shadow: 0 0 10px rgb(0 0 0 / 0.9);
    will-change: transform, opacity;
  }
  /* The frame's figures: IBM Plex Sans with tabular digits, white, the unit a step quieter. */
  .floaters.framed :global(.floater) {
    font-family: var(--sans);
    font-feature-settings: 'tnum' 1;
    font-size: 0.87rem;
    color: rgb(255 255 255 / 0.82);
    text-shadow:
      0 0 10px rgb(0 0 0 / 0.85),
      0 1px 2px rgb(0 0 0 / 0.7);
  }
  .floaters.framed :global(.floater .u) {
    color: rgb(255 255 255 / 0.6);
  }
</style>
