/**
 * Synth patches. Each schedules a short-lived node graph at `time` and frees it when done.
 * Envelopes are exponential (how real sounds decay) with a few milliseconds of attack so nothing clicks.
 */
import type { AudioEngine, BusName } from './engine';

interface Common {
  time?: number;
  gain?: number;
  /** Stereo position, −1 … 1. */
  pan?: number;
  bus?: BusName;
}

function out(a: AudioEngine, pan: number, bus: BusName): { input: GainNode; end: (t: number) => void } {
  const ctx = a.ctx as AudioContext;
  const g = ctx.createGain();
  const p = ctx.createStereoPanner();
  p.pan.value = Math.max(-1, Math.min(1, pan));
  g.connect(p).connect(a.bus(bus));
  return {
    input: g,
    end: (t) => {
      a.claimVoice(t);
      a.after(Math.max(0, t - a.now) + 0.12, () => {
        g.disconnect();
        p.disconnect();
      });
    },
  };
}

/**
 * Percussive envelope. The attack is linear: an exponential rise from silence crams nearly all of its
 * amplitude into the last fraction of a millisecond, which on low tones is an audible click. The
 * decay is exponential, then a short linear fade lands on true zero before the source stops.
 */
function env(param: AudioParam, t: number, peak: number, attack: number, decay: number): number {
  const p = Math.max(peak, 0.0002);
  param.setValueAtTime(0, t);
  param.linearRampToValueAtTime(p, t + attack);
  param.exponentialRampToValueAtTime(Math.min(0.0001, p * 0.01), t + attack + decay);
  param.linearRampToValueAtTime(0, t + attack + decay + 0.02);
  return t + attack + decay + 0.02;
}

/** FM bell. `ratio` 3.5 = metallic, 2 = warm, 1.41 = glassy. `bright` scales the modulation index. */
export function bell(
  a: AudioEngine,
  freq: number,
  o: Common & { decay?: number; ratio?: number; bright?: number } = {},
): void {
  const ctx = a.ctx;
  if (!ctx) return;
  const t = o.time ?? a.now;
  const decay = o.decay ?? 1.6;
  const { input, end } = out(a, o.pan ?? 0, o.bus ?? 'sfx');
  const car = ctx.createOscillator();
  const mod = ctx.createOscillator();
  const modGain = ctx.createGain();
  car.frequency.value = freq;
  mod.frequency.value = freq * (o.ratio ?? 3.5);
  const index = freq * (o.bright ?? 1.2);
  modGain.gain.setValueAtTime(index, t);
  modGain.gain.exponentialRampToValueAtTime(Math.max(1, index * 0.02), t + decay * 0.45);
  mod.connect(modGain).connect(car.frequency);
  car.connect(input);
  const stop = env(input.gain, t, o.gain ?? 0.2, 0.004, decay);
  car.start(t);
  mod.start(t);
  car.stop(stop + 0.05);
  mod.stop(stop + 0.05);
  end(stop + 0.05);
}

/** Soft pluck: triangle through a closing lowpass. */
export function pluck(a: AudioEngine, freq: number, o: Common & { decay?: number; tone?: number } = {}): void {
  const ctx = a.ctx;
  if (!ctx) return;
  const t = o.time ?? a.now;
  const decay = o.decay ?? 0.6;
  const { input, end } = out(a, o.pan ?? 0, o.bus ?? 'sfx');
  const osc = ctx.createOscillator();
  osc.type = 'triangle';
  osc.frequency.value = freq;
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.Q.value = 0.7;
  const top = Math.min(16000, freq * (o.tone ?? 7));
  lp.frequency.setValueAtTime(top, t);
  lp.frequency.exponentialRampToValueAtTime(Math.max(80, freq * 0.9), t + decay * 0.8);
  osc.connect(lp).connect(input);
  const stop = env(input.gain, t, o.gain ?? 0.2, 0.003, decay);
  osc.start(t);
  osc.stop(stop + 0.05);
  end(stop + 0.05);
}

/** A pitched blip that glides down `drop` semitones: pops, condensations. */
export function blip(a: AudioEngine, freq: number, o: Common & { dur?: number; drop?: number } = {}): void {
  const ctx = a.ctx;
  if (!ctx) return;
  const t = o.time ?? a.now;
  const dur = o.dur ?? 0.12;
  const { input, end } = out(a, o.pan ?? 0, o.bus ?? 'sfx');
  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(freq, t);
  osc.frequency.exponentialRampToValueAtTime(freq * 2 ** (-(o.drop ?? 7) / 12), t + dur);
  osc.connect(input);
  const stop = env(input.gain, t, o.gain ?? 0.15, 0.002, dur);
  osc.start(t);
  osc.stop(stop + 0.03);
  end(stop + 0.03);
}

/** Filtered noise burst with an optional frequency sweep: sizzle, whoosh, breath. */
export function noise(
  a: AudioEngine,
  o: Common & { dur?: number; freq?: number; to?: number; q?: number; attack?: number } = {},
): void {
  const ctx = a.ctx;
  if (!ctx) return;
  const t = o.time ?? a.now;
  const dur = o.dur ?? 0.3;
  const { input, end } = out(a, o.pan ?? 0, o.bus ?? 'sfx');
  const src = ctx.createBufferSource();
  src.buffer = a.noise();
  src.loop = true;
  const bp = ctx.createBiquadFilter();
  bp.type = 'bandpass';
  bp.Q.value = o.q ?? 1.2;
  bp.frequency.setValueAtTime(o.freq ?? 2000, t);
  if (o.to) bp.frequency.exponentialRampToValueAtTime(o.to, t + dur);
  src.connect(bp).connect(input);
  const stop = env(input.gain, t, o.gain ?? 0.1, o.attack ?? 0.01, dur);
  src.start(t, Math.random() * 1.5);
  src.stop(stop + 0.05);
  end(stop + 0.05);
}

/** Low impact: a sine that drops fast in pitch, like a soft kick. */
export function thump(a: AudioEngine, freq: number, o: Common & { dur?: number } = {}): void {
  const ctx = a.ctx;
  if (!ctx) return;
  const t = o.time ?? a.now;
  const dur = o.dur ?? 0.5;
  const { input, end } = out(a, o.pan ?? 0, o.bus ?? 'sfx');
  const osc = ctx.createOscillator();
  osc.frequency.setValueAtTime(freq * 3, t);
  osc.frequency.exponentialRampToValueAtTime(freq, t + 0.07);
  osc.connect(input);
  const stop = env(input.gain, t, o.gain ?? 0.4, 0.004, dur);
  osc.start(t);
  osc.stop(stop + 0.05);
  end(stop + 0.05);
}

/** Pad swell: detuned saws per note through a lowpass, slow attack and release. */
export function swell(
  a: AudioEngine,
  freqs: readonly number[],
  o: Common & { attack?: number; hold?: number; release?: number; cutoff?: number } = {},
): void {
  const ctx = a.ctx;
  if (!ctx) return;
  const t = o.time ?? a.now;
  const attack = o.attack ?? 1.2;
  const hold = o.hold ?? 0.8;
  const release = o.release ?? 3;
  const { input, end } = out(a, o.pan ?? 0, o.bus ?? 'music');
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.Q.value = 0.5;
  const cutoff = o.cutoff ?? 2400;
  lp.frequency.setValueAtTime(cutoff * 0.35, t);
  lp.frequency.exponentialRampToValueAtTime(cutoff, t + attack);
  lp.frequency.exponentialRampToValueAtTime(cutoff * 0.3, t + attack + hold + release);
  lp.connect(input);
  const peak = (o.gain ?? 0.18) / Math.sqrt(freqs.length);
  input.gain.setValueAtTime(0.0001, t);
  input.gain.exponentialRampToValueAtTime(peak, t + attack);
  input.gain.setValueAtTime(peak, t + attack + hold);
  input.gain.exponentialRampToValueAtTime(0.0001, t + attack + hold + release);
  const stop = t + attack + hold + release + 0.05;
  for (const f of freqs) {
    for (const det of [-7, 7]) {
      const osc = ctx.createOscillator();
      osc.type = 'sawtooth';
      osc.frequency.value = f;
      osc.detune.value = det;
      osc.connect(lp);
      osc.start(t);
      osc.stop(stop);
    }
  }
  end(stop);
}

/**
 * A rising tone that feels endless (Shepard-like): octave-spaced partials glide up together while a
 * bell-shaped spectral window keeps the overall pitch from running away. Returns a stop function.
 */
export function riser(a: AudioEngine, o: Common & { base?: number; seconds?: number } = {}): (fade?: number) => void {
  const ctx = a.ctx;
  if (!ctx) return () => {};
  const t = o.time ?? a.now;
  const seconds = o.seconds ?? 6;
  const base = o.base ?? 55;
  const master = ctx.createGain();
  master.gain.setValueAtTime(0.0001, t);
  master.gain.exponentialRampToValueAtTime(o.gain ?? 0.22, t + 0.6);
  master.connect(a.bus(o.bus ?? 'music'));
  const oscs: OscillatorNode[] = [];
  const octaves = 6;
  for (let i = 0; i < octaves; i++) {
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = i < 2 ? 'sine' : 'triangle';
    const f0 = base * 2 ** i;
    osc.frequency.setValueAtTime(f0, t);
    osc.frequency.exponentialRampToValueAtTime(f0 * 2, t + seconds);
    // Spectral window: middle partials loud, extremes quiet, so the rise never "arrives".
    const centre = (octaves - 1) / 2;
    const w = Math.exp(-(((i - centre) / 1.6) ** 2));
    g.gain.value = w * 0.35;
    osc.connect(g).connect(master);
    osc.start(t);
    oscs.push(osc);
  }
  let stopped = false;
  return (fade = 0.4) => {
    if (stopped) return;
    stopped = true;
    const n = a.now;
    master.gain.cancelScheduledValues(n);
    master.gain.setValueAtTime(Math.max(0.0001, master.gain.value), n);
    master.gain.exponentialRampToValueAtTime(0.0001, n + fade);
    for (const osc of oscs) osc.stop(n + fade + 0.05);
    a.after(fade + 0.2, () => master.disconnect());
  };
}
