/**
 * The Afterglow sounds like the inside of a bell: a low dorian drone with a hissing plasma roar
 * beneath it, deep strikes for each pulse, and small chimes where crests cross. First Light resolves
 * the long suspension into an open major chord.
 */
import type { EraAudio } from '../../audio/director';
import { bell, noise, pluck, swell, thump } from '../../audio/patches';
import { SCALES, mtof, note, type Key } from '../../audio/scales';

const KEY: Key = { root: 45, scale: SCALES.dorian };

export const AFTERGLOW_AUDIO: EraAudio = {
  key: KEY,
  bed: {
    id: 'afterglow',
    chords: [
      [33, 45, 52, 57, 60, 64],
      [31, 43, 50, 55, 59, 62],
      [29, 41, 48, 53, 57, 64],
      [31, 43, 50, 57, 62, 66],
    ],
    chordSeconds: 26,
    pad: { gain: 0.1, type: 'sine', cutoff: 1100, detune: 5, lfo: 0.03 },
    drone: { note: 33, gain: 0.045 },
    air: { freq: 320, q: 0.5, gain: 0.03, drift: 0.02 },
    shimmer: { gain: 0.006, rate: 0.09 },
    level: 0.62,
  },
  cues: {
    'afterglow.pulse': (a, p, c) => {
      const g = a.admit('afterglow.pulse', 0.08);
      if (!g) return;
      const deg = [0, 2, 4, 7][Math.floor(Math.random() * 4)];
      const t = a.now;
      bell(a, mtof(note(c.key, deg + 7)), { time: t, gain: 0.08 * g, decay: 3.2, ratio: 2, bright: 0.35, pan: c.pan(p.x) });
      thump(a, mtof(note(c.key, deg) - 12), { time: t, gain: 0.12 * g, dur: 1.2, pan: c.pan(p.x) });
    },
    'afterglow.cross': (a, p, c) => {
      const g = a.admit('afterglow.cross', 0.16);
      if (!g) return;
      const deg = 14 + Math.floor(Math.random() * 5);
      bell(a, mtof(note(c.key, deg)), { time: a.quantize(0.25, 0.1), gain: 0.022 * g * (p.intensity ?? 1), decay: 1.4, ratio: 1.41, bright: 0.4, pan: c.pan(p.x) });
    },
    'afterglow.capture': (a, p, c) => {
      const g = a.admit('afterglow.capture', 0.05);
      if (!g) return;
      const deg = p.pitch === 1 ? 9 : 11 + Math.floor(Math.random() * 3);
      pluck(a, mtof(note(c.key, deg + 7)), { time: a.quantize(0.125, 0.06), gain: 0.04 * g, decay: 0.7, tone: 5, pan: c.pan(p.x) });
    },
    'afterglow.ionize': (a, p, c) => {
      const g = a.admit('afterglow.ionize', 0.09);
      if (g) noise(a, { dur: 0.07, freq: 3000, q: 2.5, gain: 0.035 * g, pan: c.pan(p.x) });
    },
    'afterglow.node': (a, p, c) => {
      if (!a.admit('afterglow.node', 0.25)) return;
      [0, 4, 7].forEach((d, i) => bell(a, mtof(note(c.key, d + 14)), { time: a.now + i * 0.06, gain: 0.035, decay: 2, ratio: 2, bright: 0.5, pan: c.pan(p.x) }));
    },
    'afterglow.node.catch': (a, p, c) => {
      if (!a.admit('afterglow.node.catch', 0.4)) return;
      const t = a.now;
      thump(a, 49, { time: t, gain: 0.25, dur: 0.8 });
      [0, 2, 4, 7, 9].forEach((d, i) => bell(a, mtof(note(c.key, d + 14)), { time: t + i * 0.05, gain: 0.045, decay: 2.4, ratio: 2, bright: 0.6, pan: c.pan(p.x) }));
    },
    'afterglow.milestone': (a, _p, c) => {
      const t = a.now;
      swell(a, [45, 52, 57, 60, 67].map(mtof), { bus: 'music', time: t, attack: 1.6, hold: 1, release: 5, gain: 0.15, cutoff: 1800 });
      bell(a, mtof(note(c.key, 7)), { bus: 'music', time: t + 0.4, gain: 0.05, decay: 3.5, ratio: 2, bright: 0.4 });
    },
    'afterglow.firstlight': (a) => {
      const t = a.now;
      thump(a, 36, { time: t, gain: 0.3, dur: 2.4 });
      noise(a, { time: t, dur: 4.5, freq: 400, to: 7000, q: 0.4, gain: 0.07, attack: 1.5, bus: 'ambience' });
      swell(a, [45, 52, 57, 61, 64, 69, 76].map(mtof), { time: t + 0.4, attack: 2.4, hold: 2.5, release: 8, gain: 0.24, cutoff: 3600 });
    },
  },
};
