/**
 * Tangible comparisons for big numbers. Each entry is a real, checkable quantity.
 * `describe(x)` picks the largest entry not exceeding x and phrases the ratio.
 */
import { EV_PER_JOULE, superscript } from '../core/format';

interface Ref {
  /** Energy in joules. */
  j: number;
  what: string;
}

const EV = 1 / EV_PER_JOULE;

const ENERGY: Ref[] = [
  { j: 1.8 * EV, what: 'one photon of red light' },
  { j: 2.2e6 * EV, what: 'the energy that holds a deuteron together' },
  { j: 0.938e9 * EV, what: 'the mass-energy of a proton' },
  { j: 1.6e-7, what: 'the kinetic energy of a flying mosquito' },
  { j: 13.6e12 * EV, what: 'one collision at the Large Hadron Collider' },
  { j: 51, what: 'the most energetic cosmic ray ever recorded (1991)' },
  { j: 1, what: 'lifting an apple one meter' },
  { j: 4184, what: 'one food calorie' },
  { j: 5.8e5, what: 'a car at highway speed' },
  { j: 1e9, what: 'a lightning bolt' },
  { j: 6.3e13, what: 'the Hiroshima bomb' },
  { j: 2e18, what: 'a magnitude 9 earthquake' },
  { j: 6.2e20, what: "humanity's energy use for a year" },
  { j: 3.8e26, what: 'the Sun shining for one second' },
  { j: 1.2e34, what: 'the Sun shining for a year' },
  { j: 1e44, what: 'a supernova (one "foe")' },
  { j: 1.2e44, what: "the Sun's ten billion years of burning hydrogen" },
  { j: 5.4e47, what: 'the first black-hole merger detected in gravitational waves' },
  { j: 3e55, what: 'a bright quasar shining for a hundred million years' },
  { j: 2.7e59, what: 'the mass-energy of the Milky Way' },
  { j: 1.4e70, what: 'the mass-energy of all ordinary matter in the observable universe' },
].sort((a, b) => a.j - b.j);

/** "≈ 3.2 × the kinetic energy of a flying mosquito" (input in eV). */
export function energyComparison(eV: number): string | null {
  const j = eV / EV_PER_JOULE;
  if (!(j > 0)) return null;
  let best: Ref | null = null;
  for (const r of ENERGY) if (r.j <= j * 1.0001) best = r;
  if (!best) return null;
  const ratio = j / best.j;
  if (ratio < 1.15) return `About ${best.what}.`;
  if (ratio < 1000) return `About ${ratio < 10 ? ratio.toFixed(1) : Math.round(ratio)} × ${best.what}.`;
  const exp = Math.floor(Math.log10(ratio));
  return `About 10${superscript(exp)} × ${best.what}.`;
}
