<!--
  The frame, after the Eameses' Powers of Ten: a square field of view on the universe marked only by
  its corners, the world outside it dimmed; the time above; the field's true size on a scale bar
  beneath; the economy in the left margin and the next step and the phenomena in the right, like
  captions beside a figure. One typeface; hierarchy by size, weight, position and space. No boxes.
  Through a pull-back between eras the readings run with the camera, and the old era's field stays
  marked by its corners as it shrinks into the new view, so the move outward reads at a glance; then
  the time caption names the era for a few seconds before handing back to the clock.
-->
<script lang="ts">
  import { cosmicTime, sci, temperature } from '../../core/format';
  import Num from '../common/Num.svelte';
  import Hint from '../hud/Hint.svelte';
  import Toasts from '../hud/Toasts.svelte';
  import { game, track, ui } from '../store.svelte';
  import Actions from './Actions.svelte';
  import Ledger from './Ledger.svelte';
  import Links from './Links.svelte';
  import { frameReadings } from './readings';
  import { inWords } from './words';

  let { hidden }: { hidden: boolean } = $props();
  const g = game();

  const v = $derived.by(() => {
    track();
    const r = frameReadings(g);
    const def = g.eraDef;
    return {
      title: def.title,
      epoch: def.epoch,
      t: inWords(cosmicTime(r.t)),
      T: inWords(temperature(r.T)),
      scale: r.meters !== null ? sci(r.meters, 'm', { sig: 2, trim: true, bareOnes: true }) : null,
      compare: r.compare,
      finale: g.inFinale,
      passing: g.passing,
      // The era's announcement (main.ts times it) is shown here, in the time caption, not as a card.
      named: ui.eraCard !== null && ui.eraCard.title === def.title,
      // The old field's corners, while the camera draws back from it: they fade as it becomes a speck.
      old: r.old,
      oldSeen: r.old > 0 && r.old < 0.995 ? Math.min(1, Math.max(0, (r.old - 0.004) / 0.026)) : 0,
    };
  });
</script>

<div class="frame" class:hidden class:panel-open={ui.panel !== null} class:finale={v.finale} class:passing={v.passing}>
  <div class="field" aria-hidden="true"><i class="corner tl"></i><i class="corner tr"></i><i class="corner bl"></i><i class="corner br"></i></div>
  {#if v.oldSeen > 0}
    <div class="field old" aria-hidden="true" style="--k: {v.old}; opacity: {v.oldSeen}">
      <i class="corner tl"></i><i class="corner tr"></i><i class="corner bl"></i><i class="corner br"></i>
    </div>
  {/if}

  <header class="time">
    <h1 class="sr-only">{v.title}, {v.epoch}</h1>
    <p class="sr-only" aria-live="polite">{v.named ? `${v.title}, ${v.epoch}` : ''}</p>
    <div class="caption" class:out={v.named}>
      <div class="t"><span class="sr-only">Cosmic time: </span><Num parts={v.t} /></div>
      <div class="sub dim">after the beginning, at <Num parts={v.T} /></div>
    </div>
    <div class="caption name" class:out={!v.named} aria-hidden="true">
      <div class="t">{v.title}</div>
      <div class="sub dim">{v.epoch}</div>
    </div>
  </header>

  {#if v.scale}
    <div class="scale">
      <div class="bar" aria-hidden="true"></div>
      <div class="m"><span class="sr-only">Scale bar: </span><Num parts={v.scale} /></div>
      <div class="what faint">{v.compare}</div>
    </div>
  {/if}

  <div class="left">
    <Ledger />
  </div>

  <div class="right">
    <Actions />
  </div>

  <!-- Last in reading and Tab order: the step and the phenomena come before the menu. -->
  <div class="menu">
    <Links />
  </div>

  <div class="captions">
    <Toasts />
    <Hint />
  </div>
</div>

<style>
  .frame {
    --S: min(76vh, 54vw);
    --gap: 3.5rem;
    /* What each margin has between the field and the screen's edge. */
    --side: calc((100vw - var(--S)) / 2 - var(--gap) - var(--gutter));
    position: fixed;
    inset: 0;
    pointer-events: none;
    font-family: var(--sans);
    font-weight: 400;
    color: #fff;
    font-feature-settings: 'tnum' 1;
    transition:
      opacity 1.4s var(--ease),
      visibility 1.4s;
    /* The instrument powers on: at a load, and as the first framed era opens out of the Prologue. */
    animation: power-on 1.4s var(--ease);
  }
  @keyframes power-on {
    from {
      opacity: 0;
    }
  }
  /* Hidden also takes the controls out of the Tab order, so focus never lands on something invisible. */
  .frame.hidden {
    opacity: 0;
    visibility: hidden;
  }
  .frame.hidden :global(*) {
    pointer-events: none !important;
  }

  .field {
    position: absolute;
    left: 50%;
    top: 50%;
    width: var(--S);
    height: var(--S);
    transform: translate(-50%, -50%);
  }
  /*
   * The world goes on past the field: the margins are part of it, veiled only enough for the text over
   * them to read (a layer of its own, so lifting it costs only opacity).
   */
  .field::before {
    content: '';
    position: absolute;
    inset: 0;
    box-shadow: 0 0 0 100vmax rgb(0 0 0 / 0.42);
    transition: opacity 1.4s var(--ease);
  }
  .corner {
    position: absolute;
    width: var(--corner, 22px);
    height: var(--corner, 22px);
    border: 0 solid rgb(255 255 255 / 0.6);
  }
  /* The old era's field, marked only by its corners, shrinking into the new view. */
  .field.old {
    width: calc(var(--S) * var(--k));
    height: calc(var(--S) * var(--k));
    --corner: min(22px, calc(var(--S) * var(--k) / 4));
  }
  .field.old::before {
    content: none;
  }
  .tl {
    left: -1px;
    top: -1px;
    border-left-width: 1px;
    border-top-width: 1px;
  }
  .tr {
    right: -1px;
    top: -1px;
    border-right-width: 1px;
    border-top-width: 1px;
  }
  .bl {
    left: -1px;
    bottom: -1px;
    border-left-width: 1px;
    border-bottom-width: 1px;
  }
  .br {
    right: -1px;
    bottom: -1px;
    border-right-width: 1px;
    border-bottom-width: 1px;
  }

  .time {
    position: absolute;
    left: 50%;
    bottom: calc(50% + var(--S) / 2 + 1.3rem);
    transform: translateX(-50%);
    text-align: center;
    white-space: nowrap;
    display: grid;
    justify-items: center;
  }
  /* The clock and the era's name share one place and cross-fade (opacity only, so also when still). */
  .caption {
    grid-area: 1 / 1;
    align-self: end;
    transition: opacity 0.9s var(--ease);
  }
  .caption.out {
    opacity: 0;
  }
  .time .t {
    font-weight: 300;
    font-size: 2rem;
    line-height: 1.2;
    letter-spacing: -0.01em;
  }
  .time .t :global(.u) {
    opacity: 1;
  }
  .time .sub {
    font-size: 0.87rem;
    margin-top: 0.15rem;
  }

  .scale {
    position: absolute;
    left: 50%;
    top: calc(50% + var(--S) / 2 + 1.45rem);
    transform: translateX(-50%);
    text-align: center;
    white-space: nowrap;
  }
  .scale .bar {
    width: calc(var(--S) / 4);
    height: 7px;
    margin: 0 auto 0.5rem;
    border: 1px solid rgb(255 255 255 / 0.7);
    border-top: 0;
  }
  .scale .m {
    font-size: 0.93rem;
  }
  .scale .what {
    font-size: 0.8rem;
    margin-top: 0.1rem;
  }

  .left {
    position: absolute;
    right: calc(50% + var(--S) / 2 + var(--gap));
    top: calc(50% - var(--S) / 2);
    bottom: calc(50% - var(--S) / 2 + 3rem);
    width: min(18rem, var(--side));
  }
  .menu {
    position: absolute;
    right: calc(50% + var(--S) / 2 + var(--gap));
    bottom: calc(50% - var(--S) / 2);
    width: min(18rem, var(--side));
  }
  .right {
    position: absolute;
    left: calc(50% + var(--S) / 2 + var(--gap));
    top: calc(50% - var(--S) / 2);
    bottom: var(--gutter);
    width: min(20rem, var(--side));
    display: flex;
    flex-direction: column;
    transition:
      opacity 240ms var(--ease),
      visibility 240ms;
  }
  /* Panels open over the right margin. */
  .panel-open .right {
    opacity: 0;
    visibility: hidden;
  }
  /*
   * While the camera draws back between eras the margins dim and wait (nothing can be bought until it
   * settles), leaving the readings that count with the move: the time above, the scale bar below.
   */
  .left > :global(*),
  .right > :global(*),
  .menu > :global(*) {
    transition: opacity 1.2s var(--ease);
  }
  .passing .left > :global(*),
  .passing .right > :global(*),
  .passing .menu > :global(*) {
    opacity: 0.14;
    transition-duration: 0.7s;
  }
  .passing .left :global(*),
  .passing .right :global(*),
  .passing .menu :global(*) {
    pointer-events: none !important;
  }

  /* Messages and the one contextual instruction read as captions along the field's lower edge. */
  .captions {
    position: absolute;
    left: 50%;
    bottom: calc(50% - var(--S) / 2 + 1.6rem);
    transform: translateX(-50%);
    width: calc(var(--S) - 3rem);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.9rem;
  }
  .captions :global(.milestone),
  .captions :global(.quiet),
  .captions :global(.hint),
  .captions :global(.discovery .what) {
    font-family: var(--sans);
