  }

  /* The frame's shared type: captions, readings, rules and reveals. */
  .frame :global(p) {
    margin: 0;
  }
  .frame :global(.num) {
    font-family: inherit;
  }
  .frame :global(.cap) {
    font-size: 0.8rem;
    color: rgb(255 255 255 / 0.46);
    margin-bottom: 0.4rem;
  }
  .frame :global(.dim) {
    color: rgb(255 255 255 / 0.52);
