  .frame :global(.progress i) {
    position: absolute;
    top: -0.5px;
    height: 2px;
    background: #fff;
  }
  /* Hover or keyboard focus opens a reveal; the text stays readable to screen readers while closed. */
  .frame :global(.reveal) {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows 160ms var(--ease);
  }
  .frame :global(.reveal > div) {
    min-height: 0;
    overflow: hidden;
  }
  .frame :global(.reveal-host:hover .reveal),
  .frame :global(.reveal-host:focus-visible .reveal) {
    grid-template-rows: 1fr;
  }
</style>
