/**
 * Uniform spatial hash for neighbour queries, rebuilt each step by counting sort (O(n + cells),
 * no allocations after warm-up). Over a periodic box (physics/torus.ts) its queries reach across the
 * edges; the caller measures distances through the wrap.
 */
import type { Particles } from './particles';

export class Grid {
  private cols = 1;
  private rows = 1;
  private minX = 0;
  private minY = 0;
  private cellW: number;
  private cellH: number;
  private wrap = false;
  private counts = new Int32Array(1);
  private starts = new Int32Array(2);
  private items: Int32Array;
  private cellOf: Int32Array;

  constructor(
    readonly cell: number,
    capacity: number,
  ) {
    this.items = new Int32Array(capacity);
    this.cellOf = new Int32Array(capacity);
    this.cellW = this.cellH = cell;
  }

  /** The area covered; `wrap` makes it a periodic box (its cells then tile it exactly). */
  setBounds(minX: number, minY: number, maxX: number, maxY: number, wrap = false): void {
    this.minX = minX;
    this.minY = minY;
    const cols = Math.max(1, (wrap ? Math.floor : Math.ceil)((maxX - minX) / this.cell));
    const rows = Math.max(1, (wrap ? Math.floor : Math.ceil)((maxY - minY) / this.cell));
    if (cols * rows !== this.cols * this.rows) {
      this.counts = new Int32Array(cols * rows);
      this.starts = new Int32Array(cols * rows + 1);
    }
    this.cols = cols;
    this.rows = rows;
    this.wrap = wrap;
    this.cellW = wrap ? (maxX - minX) / cols : this.cell;
    this.cellH = wrap ? (maxY - minY) / rows : this.cell;
  }

  private cellIndex(x: number, y: number): number {
    let cx = Math.floor((x - this.minX) / this.cellW);
    let cy = Math.floor((y - this.minY) / this.cellH);
    if (cx < 0) cx = 0;
    else if (cx >= this.cols) cx = this.cols - 1;
    if (cy < 0) cy = 0;
    else if (cy >= this.rows) cy = this.rows - 1;
    return cy * this.cols + cx;
  }

  build(p: Particles): void {
    const n = p.n;
    if (this.items.length < n) {
      this.items = new Int32Array(p.cap);
      this.cellOf = new Int32Array(p.cap);
    }
    this.counts.fill(0);
    for (let i = 0; i < n; i++) {
      const c = this.cellIndex(p.x[i], p.y[i]);
      this.cellOf[i] = c;
      this.counts[c]++;
    }
    let acc = 0;
    for (let c = 0; c < this.counts.length; c++) {
      this.starts[c] = acc;
      acc += this.counts[c];
    }
    this.starts[this.counts.length] = acc;
    this.counts.fill(0);
    for (let i = 0; i < n; i++) {
      const c = this.cellOf[i];
      this.items[this.starts[c] + this.counts[c]++] = i;
    }
  }

  /** Calls `fn(j)` for every particle in cells overlapping the circle (caller filters by distance). */
  near(x: number, y: number, radius: number, fn: (j: number) => void): void {
    let c0x = Math.floor((x - radius - this.minX) / this.cellW);
    let c1x = Math.floor((x + radius - this.minX) / this.cellW);
    let c0y = Math.floor((y - radius - this.minY) / this.cellH);
    let c1y = Math.floor((y + radius - this.minY) / this.cellH);
    if (this.wrap) {
      // Across the edges, but never a cell twice when the circle is wider than the box.
      c1x = Math.min(c1x, c0x + this.cols - 1);
      c1y = Math.min(c1y, c0y + this.rows - 1);
    } else {
      c0x = Math.max(0, c0x);
      c1x = Math.min(this.cols - 1, c1x);
      c0y = Math.max(0, c0y);
      c1y = Math.min(this.rows - 1, c1y);
    }
    for (let gy = c0y; gy <= c1y; gy++) {
      const cy = this.wrap ? ((gy % this.rows) + this.rows) % this.rows : gy;
      for (let gx = c0x; gx <= c1x; gx++) {
        const cx = this.wrap ? ((gx % this.cols) + this.cols) % this.cols : gx;
        const c = cy * this.cols + cx;
        const end = this.starts[c + 1];
        for (let k = this.starts[c]; k < end; k++) fn(this.items[k]);
      }
    }
  }
}
