/**
 * Achievements, as Steam sees them. Each is unlocked from what the game already records (era ends,
 * fates, the codex, a few moments of skill), so nothing in the eras needs to know about Steam. The ids
 * are the API names to create in Steamworks.
 */
import type { ChartId } from '../core/codex';
import type { Game } from '../core/game';
import { diesYoung, fateOf, type Fate } from '../core/multiverse';
import { ERA_ORDER, type EraId } from '../core/state';

export interface AchievementDef {
  id: string;
  name: string;
  description: string;
}

