/**
 * Luminous filaments: smooth curves drawn as one continuous strip each, so joints never double up
 * into beads, and shaded across their width the way a plasma arc glows: a thin white-hot core inside
 * a coloured sheath. The colour shades along the curve from one end's to the other's, and brightness
 * can vary along it (energy travelling down the string). Gluon strings now; jets and loops later.
 * Drawn additively over the scene, after the media and matter.
 */
import { tryProgram, type Program } from './gl';
import { HEADER } from './glsl';
import type { LayerFrame, RenderLayer } from './renderer';

type RGB = readonly [number, number, number];

/**
 * Floats per vertex: x, y, signed distance across (world units: ± the half-width at the strip's
 * edges), r, g, b, core gain, sheath gain, half-width (world units). Interpolating the distance
 * itself, not a fraction of the width, keeps the centreline exact where the width changes along the
 * strip (a fraction would zigzag across each segment's diagonal).
 */
const F = 9;

const VS = HEADER + /* glsl */ `
layout(location = 0) in vec2 aPos;
layout(location = 1) in float aAcross;
layout(location = 2) in vec3 aColor;
layout(location = 3) in vec3 aShape;   // core gain, sheath gain, half-width
uniform vec4 uView;
out float vAcross;
out vec3 vColor;
out vec3 vShape;
void main() {
  vec2 p = (aPos - uView.xy) / uView.zw;
  gl_Position = vec4(p.x, -p.y, 0.0, 1.0);
  vAcross = aAcross;
  vColor = aColor;
  vShape = aShape;
}`;

const FS = HEADER + /* glsl */ `
in float vAcross;
in vec3 vColor;
in vec3 vShape;
uniform float uPxPerUnit;
uniform float uCorePx;
uniform float uGain;
uniform float uRibbon;
out vec4 outColor;
void main() {
  float a = min(1.0, abs(vAcross) / max(vShape.z, 1e-4));
  // The core is a fixed width in pixels (a filament of light stays sharp at any zoom).
  float px = abs(vAcross) * uPxPerUnit;
  float core = exp(-px * px / (2.0 * uCorePx * uCorePx));
  vec3 c;
  if (uRibbon > 0.5) {
    // A discharge streamer's cross-section: a white-hot thread, a paler tint glowing close around it,
    // and a translucent sheath of the colour itself whose fringe deepens (more saturated) as it fades
    // to nothing at the strip's edge.
    float a2 = a * a;
    float peak = max(max(vColor.r, vColor.g), vColor.b);
    vec3 deep = vColor * vColor / max(peak, 1e-3);
    float edge = (1.0 - a2) * (1.0 - a2);
    float inner = exp(-a2 * 16.0);
    float body = exp(-a2 * 3.2) * edge;
    vec3 thread = mix(vColor, vec3(1.0), 0.62);
    vec3 sheath = mix(vColor, vec3(1.0), 0.3) * inner * 0.7 + mix(deep, vColor, exp(-a2 * 7.0)) * body * 0.8;
    c = thread * core * vShape.x + sheath * vShape.y;
  } else {
    // The sheath fills the strip: a gaussian across it, nearly nothing at its edges.
    float sheath = exp(-a * a * 5.0);
    vec3 hot = mix(vColor, vec3(1.0), 0.4);
    c = hot * core * vShape.x + vColor * sheath * vShape.y;
  }
  outColor = vec4(c * uGain, 0.0);
}`;

export class Filaments implements RenderLayer {
  readonly stage = 'atmosphere' as const;
  /** Core width in pixels (gaussian sigma). */
  corePx = 0.8;
  /**
   * Shade each strip as a discharge streamer (white thread, pale inner glow, a sheath whose fringe
   * deepens) instead of a plain core and sheath.
   */
  ribbon = false;
  /**
   * Shade the colour along each strip around the hue circle (the shorter way) instead of straight
   * through RGB, so complementary ends pass through saturated hues rather than grey.
   */
  arc = false;
  /** Segments per length relative to High, from the quality level of the last frame drawn. */
  detail = 1;
  private gl: WebGL2RenderingContext | null = null;
  private prog: Program | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private vbo: WebGLBuffer | null = null;
  private data = new Float32Array(F * 4096);
  private n = 0;
  private capacity = 0;

  init(gl: WebGL2RenderingContext): void {
    this.gl = gl;
    // A program the driver rejects leaves the era without filaments, not without its look.
    this.prog = tryProgram(gl, VS, FS, 'filaments');
    this.vao = gl.createVertexArray();
    this.vbo = gl.createBuffer();
    gl.bindVertexArray(this.vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.vbo);
    const stride = F * 4;
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, stride, 0);
    gl.enableVertexAttribArray(1);
    gl.vertexAttribPointer(1, 1, gl.FLOAT, false, stride, 8);
    gl.enableVertexAttribArray(2);
    gl.vertexAttribPointer(2, 3, gl.FLOAT, false, stride, 12);
    gl.enableVertexAttribArray(3);
    gl.vertexAttribPointer(3, 3, gl.FLOAT, false, stride, 24);
    gl.bindVertexArray(null);
    this.capacity = 0;
  }

  /**
   * How many segments a curve that would take `full` of them at High is drawn with now (never fewer
   * than `min`): callers sample their curves this finely.
   */
  segments(full: number, min = 8): number {
    return Math.max(Math.min(min, full), Math.round(full * this.detail));
  }

  private vertex(x: number, y: number, across: number, r: number, g: number, b: number, core: number, sheath: number, half: number): void {
    if ((this.n + 1) * F > this.data.length) {
      const grown = new Float32Array(this.data.length * 2);
      grown.set(this.data);
      this.data = grown;
    }
    const d = this.data;
    const o = this.n * F;
    d[o] = x;
    d[o + 1] = y;
    d[o + 2] = across;
    d[o + 3] = r;
    d[o + 4] = g;
    d[o + 5] = b;
    d[o + 6] = core;
    d[o + 7] = sheath;
    d[o + 8] = half;
    this.n++;
  }

  /**
   * Adds a filament through the first `count` points of `pts` (x, y pairs, world units; all of them
   * by default): colour from `a` to `b` along it, `half` the sheath's half-width (world units, one for
   * the whole strip or one per point), and per-point gains for the core and sheath. Its ends fade out
   * unless `fadeEnds` is false (a spark's streak keeps its bright head).
   */
  push(
    pts: ArrayLike<number>,
    a: RGB,
    b: RGB,
    half: ArrayLike<number> | number,
    core: ArrayLike<number> | number,
    sheath: ArrayLike<number> | number,
    fadeEnds = true,
    count = pts.length / 2,
  ): void {
    const m = count;
    if (m < 2) return;
    // The ends' colours as brightness, chroma and hue in the hexagonal hue plane (for `arc`).
    const ia = (a[0] + a[1] + a[2]) / 3;
    const ib = (b[0] + b[1] + b[2]) / 3;
    const ua = a[0] - (a[1] + a[2]) / 2;
    const va = (a[1] - a[2]) * 0.8660254;
    const ub = b[0] - (b[1] + b[2]) / 2;
    const vb = (b[1] - b[2]) * 0.8660254;
    const ka = Math.hypot(ua, va);
    const kb = Math.hypot(ub, vb);
    let ha = Math.atan2(va, ua);
    let hb = Math.atan2(vb, ub);
    if (ka < 1e-4) ha = hb;
    if (kb < 1e-4) hb = ha;
    let dh = hb - ha;
    if (dh > Math.PI) dh -= Math.PI * 2;
    else if (dh < -Math.PI) dh += Math.PI * 2;
    const arc = this.arc;
    for (let i = 0; i < m; i++) {
      const i0 = Math.max(0, i - 1);
      const i1 = Math.min(m - 1, i + 1);
      let tx = pts[i1 * 2] - pts[i0 * 2];
      let ty = pts[i1 * 2 + 1] - pts[i0 * 2 + 1];
      const len = Math.hypot(tx, ty) || 1;
      tx /= len;
      ty /= len;
      // The ends fade rather than narrow (a strip narrower than the core would pinch it).
      const s = i / (m - 1);
      const fade = fadeEnds ? Math.min(1, Math.sin(Math.PI * s) * 4) : 1;
      const w = typeof half === 'number' ? half : half[i];
      const x = pts[i * 2];
      const y = pts[i * 2 + 1];
      let cr: number;
      let cg: number;
      let cb: number;
      if (arc) {
        const lum = ia + (ib - ia) * s;
        const k = ka + (kb - ka) * s;
        const h = ha + dh * s;
        const u = k * Math.cos(h);
        const v = k * Math.sin(h);
        cr = Math.max(0, lum + 0.6666667 * u);
        cg = Math.max(0, lum - u / 3 + v * 0.5773503);
        cb = Math.max(0, lum - u / 3 - v * 0.5773503);
      } else {
        cr = a[0] + (b[0] - a[0]) * s;
        cg = a[1] + (b[1] - a[1]) * s;
        cb = a[2] + (b[2] - a[2]) * s;
      }
      const gc = (typeof core === 'number' ? core : core[i]) * fade;
      const gs = (typeof sheath === 'number' ? sheath : sheath[i]) * fade;
      // A degenerate pair joins this filament to the previous one in the same strip.
      if (i === 0 && this.n > 0) {
        this.vertex(this.data[(this.n - 1) * F], this.data[(this.n - 1) * F + 1], 0, cr, cg, cb, 0, 0, 0);
        this.vertex(x - ty * w, y + tx * w, -w, cr, cg, cb, 0, 0, w);
      }
      this.vertex(x - ty * w, y + tx * w, -w, cr, cg, cb, gc, gs, w);
      this.vertex(x + ty * w, y - tx * w, w, cr, cg, cb, gc, gs, w);
    }
  }

  draw(frame: LayerFrame): void {
    const gl = this.gl;
    this.detail = frame.quality.detail;
    if (!gl || !this.prog || !this.vao || !this.vbo || this.n < 3) {
      this.n = 0;
      return;
    }
    gl.bindBuffer(gl.ARRAY_BUFFER, this.vbo);
    const bytes = this.n * F * 4;
    if (bytes > this.capacity) {
      this.capacity = Math.max(bytes, this.capacity * 2);
      gl.bufferData(gl.ARRAY_BUFFER, this.capacity, gl.DYNAMIC_DRAW);
    }
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.data, 0, this.n * F);
    frame.scene.bind();
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE);
    this.prog.use().f1('uPxPerUnit', frame.pxPerUnit).f1('uCorePx', this.corePx).f1('uGain', frame.gain ?? 1).f1('uRibbon', this.ribbon ? 1 : 0);
    gl.uniform4fv(this.prog.loc('uView'), frame.view);
    gl.bindVertexArray(this.vao);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, this.n);
    gl.bindVertexArray(null);
    this.n = 0;
  }

  dispose(): void {
    const gl = this.gl;
    if (!gl) return;
    this.prog?.dispose();
    if (this.vbo) gl.deleteBuffer(this.vbo);
    if (this.vao) gl.deleteVertexArray(this.vao);
    this.prog = null;
    this.vbo = null;
    this.vao = null;
  }
}
