/**
 * How the Dark Ages and Cosmic Dawn look (version 2). The simulation says what is where; this draws it.
 *
 * - The afterglow: the sky itself glows with this universe's own microwave pattern, orange, then deep
 *   red, then gone as it redshifts out of the visible.
 * - Neutral gas: a dim, cold medium (GasMedium) shaped by the simulation's parcels, so it is seen by how
 *   it moves: sliding into the halos, streaming toward the hand. A sparse storm of specks rides the
 *   same flow, barely lit until something shines.
 * - Dark matter: invisible, betrayed only by lensing (GravLens): the specks and mist behind a halo are
 *   bent around it, a slow shimmer that drifts as the halos fall together. The hand is a mass too.
 * - Clumps: knots in the medium that glow from inside as they are compressed and heated, and dim as
 *   they cool. The Jeans mass is a delicate spherical front tightening round the clump as it cools, gold
 *   when it is about to go.
 * - Collapse and ignition: streamers spiral in to a core heating from red to white while the world
 *   holds still; then a point of light of real dynamic range, with lens glare, lighting the gas around
 *   it. The first one in the universe gets the whole sky.
 * - Stars: crisp blue-white points that light their bubbles. Bubbles are spheres carved out of the gas,
 *   their bodies glowing faintly, their fronts limb-bright.
 * - Supernovae: light fronts racing through the gas, pushing the specks; fresh metals glint as they slow.
 * - Black holes: an absence, ringed by the light it bends.
 * - Effects (the era's FxPool, restyled): flashes light the medium, rings are fronts and pushes, sparks
 *   are faint glints.
 */
import { Filaments } from '../../render/filaments';
import type { FxLook } from '../../render/fx';
import type { PostParams } from '../../render/post';
import type { Renderer } from '../../render/renderer';
import { Shape } from '../../render/sprites';
import { Storm, type StormKick, type StormLight } from '../../render/storm';
import type { VolumeFront, VolumeLight } from '../../render/volume';
import { dawnBackground, type DawnBgParams } from './background';
import { GravLens, type Lens } from './lens';
import { FIELD_H, FIELD_W, FLOW_H, FLOW_W, GasMedium, ION_H, ION_W } from './medium';

type RGB = readonly [number, number, number];

/** What the simulation tells the look at the start of a frame. */
export interface DawnFrame {
  /** Era seconds. */
  t: number;
  /** The background's state (afterglow, visibility, a step's pulse, the finale's clearing). */
  bg: DawnBgParams;
  /** Depth of the dark matter (the pull stat). */
  pull: number;
  /** The coldest the gas can get now (sim kelvin). */
  floor: number;
  /** 0 → 1 while the very first protostar collapses: the held breath before the first light. */
  breath: number;
  /** The play area's half extents (world units). */
  halfW: number;
  halfH: number;
}

export interface Halo {
  x: number;
  y: number;
  s: number;
}

export interface Bubble {
  x: number;
  y: number;
  r: number;
  n: number;
}

/** The post settings this look is graded for. */
const POST: Partial<PostParams> = { bloom: 0.2, bloomThreshold: 1.3, glare: 0.55, glareThreshold: 2.5, saturation: 1.2, punch: 1.15, vignette: 0.42, grain: 0.011 };

const COLD: [number, number, number] = [0.55, 0.65, 0.88];
const PALE: [number, number, number] = [0.82, 0.86, 1.0];
const WARM: [number, number, number] = [1.0, 0.78, 0.55];

/** How far outside a bubble its signed distance is kept (world units): enough for the front's glow. */
const ION_FAR = 60;
/** Gaussian radius a gas parcel is spread over in the gas field (world units). */
const PARCEL_SIGMA = 40;

const lum = (c: RGB) => 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
const smooth = (a: number, b: number, x: number) => {
  const u = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return u * u * (3 - 2 * u);
};

interface Ranked<T> {
  weight: number;
  item: T;
}

/** The afterglow's colour times brightness for `g` (1 at 3,000 K → 0 redshifted into the infrared). */
export function afterglowLight(g: number): [number, number, number] {
  const k = Math.max(0, g);
  const deep: RGB = [0.5, 0.03, 0.01];
  const red: RGB = [1.0, 0.15, 0.03];
  const orange: RGB = [1.0, 0.46, 0.17];
  const a = smooth(0.05, 0.4, k);
  const b = smooth(0.35, 1.0, k);
  const c = [0, 1, 2].map((i) => {
    const lo = deep[i] + (red[i] - deep[i]) * a;
    return lo + (orange[i] - lo) * b;
  });
  // Brightness falls steeply as the peak slides out of the visible.
  const e = k * k * 0.9 + k * 0.1;
  return [c[0] * e, c[1] * e, c[2] * e];
}

export class DawnLook implements FxLook {
  readonly medium = new GasMedium();
  readonly storm = new Storm({
    count: 11000,
    depth: 650,
    focal: 1600,
    lifeMin: 5,
    lifeMax: 12,
    swirl: 3,
    swirlScale: 700,
    drag: 1.1,
    flowGain: 1,
    jitter: 0.5,
    spread: 0,
    faintest: 0.0025,
    peak: 0.8,
    magnitudePower: 1.15,
    halo: 0,
    twinkle: 0.07,
    streak: 0.06,
    streakFrom: 0.6,
    light: 12,
    ambient: 1,
    palette: [COLD, PALE, WARM, COLD, COLD, COLD, COLD, COLD],
    weights: [3, 1.1, 0.12, 0, 0, 0, 0, 0],
  });
  readonly lens = new GravLens();
  readonly filaments = new Filaments();
  private r: Renderer | null = null;
  private saved: Partial<PostParams> = {};
  private savedZoom = 1;
  private readonly bgParams: DawnBgParams = { glow: 1, web: 0.25, pulse: 0, finale: 0, rect: new Float32Array(4) };
  /** The play area's half extents (the microwave pattern spans it). */
  private readonly play = new Float32Array([889, 500]);
  /** The microwave pattern the afterglow glows with (0–1, 0.5 the mean), recorded or made up. */
  private readonly cmb = new Float32Array(48 * 27).fill(0.5);
  private cmbVersion = 0;
  private cmbKnown = false;
  private readonly dm = new Float32Array(128 * 72);
  private dmVersion = 0;
  private dmKey = '';
  private dmT = -1;
  private ionT = -1;
  private frame: DawnFrame | null = null;
  private lights: Ranked<VolumeLight>[] = [];
  private fronts: Ranked<VolumeFront>[] = [];
  private kicks: Ranked<StormKick>[] = [];
  private speckLights: Ranked<StormLight>[] = [];
  private lensList: Ranked<Lens>[] = [];
  /** This frame's halos, hand and light sources, for the flow the storm rides. */
  private halosNow: Halo[] = [];
  private hand: { x: number; y: number; reach: number; k: number } | null = null;
  private handK = 0;
  private sources: { x: number; y: number; l: number; r: number }[] = [];
  private seg = new Float32Array(64);

  /** The background this look draws behind the medium. */
  private readonly background = dawnBackground(
    this.bgParams,
    {
      cmb: { width: 48, height: 27, data: () => this.cmb, version: () => this.cmbVersion },
      dm: { width: 128, height: 72, data: () => this.dm, version: () => this.dmVersion },
    },
    this.play,
  );

  /**
   * Takes over the renderer: the background, the layers, the grade, and a camera drawn back so the
   * whole height of the play fits the frame's square field. `cmb` is the microwave map the Afterglow
   * recorded ("48x27:" + base64 bytes), the pattern the afterglow glows with.
   */
  attach(r: Renderer, cmb?: string): void {
    this.r = r;
    this.decodeCmb(cmb);
    r.setBackground(this.background);
    r.setLayers([this.medium, this.storm, this.lens, this.filaments]);
    this.storm.flow = this.medium;
    const post = r.post as unknown as Record<string, unknown>;
    for (const [k, v] of Object.entries(POST)) {
      (this.saved as Record<string, unknown>)[k] = post[k];
      post[k] = v;
    }
    this.savedZoom = r.camera.zoom;
    r.camera.zoom = this.fit(r);
  }

  detach(r: Renderer): void {
    r.setLayers([]);
    this.storm.flow = null;
    Object.assign(r.post, this.saved);
    r.camera.zoom = this.savedZoom;
    this.r = null;
  }

  /** The zoom at which the play's full height fills the frame's square (min(76vh, 54vw)). */
  private fit(r: Renderer): number {
    return Math.min(0.76, (0.54 * r.cssW) / Math.max(1, r.cssH));
  }

  private decodeCmb(code: string | undefined): void {
    const m = code ? /^48x27:(.+)$/.exec(code) : null;
    if (!m) return;
    try {
      const bin = atob(m[1]);
      if (bin.length !== 48 * 27) return;
      for (let i = 0; i < bin.length; i++) this.cmb[i] = bin.charCodeAt(i) / 255;
      this.cmbVersion++;
      this.cmbKnown = true;
    } catch {
      /* a damaged record: the flat pattern stays */
    }
  }

  // ─── the frame

  /** Starts a frame: the effect lists and the gas field refill every frame. */
  begin(r: Renderer, f: DawnFrame): void {
    this.r = r;
    this.frame = f;
    r.camera.zoom = this.fit(r);
    const bg = this.bgParams;
    bg.glow = f.bg.glow;
    bg.web = f.bg.web;
    bg.pulse = f.bg.pulse;
    bg.finale = f.bg.finale;
    bg.rect.set(f.bg.rect);
    this.play[0] = f.halfW;
    this.play[1] = f.halfH;
    this.lights.length = 0;
    this.fronts.length = 0;
    this.kicks.length = 0;
    this.speckLights.length = 0;
    this.lensList.length = 0;
    this.sources.length = 0;
    this.hand = null;
    // The fields cover what the camera sees at rest, with a margin.
    const cam = r.camera;
    const hh = cam.viewHeight / cam.zoom / 2 + 60;
    const hw = (cam.viewHeight / cam.zoom / 2) * cam.aspect + 60;
    const rc = this.medium.rect;
    if (rc[0] !== -hw || rc[1] !== -hh) {
      rc.set([-hw, -hh, hw, hh]);
      this.ionT = -1;
    }
    this.medium.field.fill(0);
    this.grade(f);
  }

  /** The medium's and the storm's grade for this moment of the era. */
  private grade(f: DawnFrame): void {
    const bg = f.bg;
    const calm = 1 - 0.55 * f.breath;
    // The gas as a 21-centimeter receiver sees it, a faint cold grey: against the afterglow it shows dark
    // (colder than the afterglow, it absorbs: the real 21-cm signal of the Dark Ages); once the afterglow
    // has gone, it shows faintly on its own. The 21-centimeter line sees it better.
    const vis = 0.02 * (1 + 1.6 * Math.max(0, bg.web - 0.25)) * calm * (1 + 0.5 * bg.pulse) * (1 - 0.8 * bg.finale) * (1 - 0.85 * Math.min(1, bg.glow * 1.5));
    const L = this.medium.light;
    L.ambient = [0.42 * vis, 0.5 * vis, 0.68 * vis];
    const g = afterglowLight(bg.glow);
    const gk = 0.004 * calm;
    L.glow = [g[0] * gk, g[1] * gk, g[2] * gk];
    L.heat = 0.15 * calm;
    L.ion = 0.06 * (1 - 0.65 * bg.finale);
    L.clear = bg.finale;
    const s = this.storm.config;
    s.swirl = 3 * calm;
    s.jitter = 0.5 * calm;
    // Nothing shines in the Dark Ages: the specks are all but invisible until something lights them.
    s.faintest = 0.0025 * calm * (1 + 0.8 * Math.max(0, bg.web - 0.25));
  }

  /** A light inside the medium (it lights the gas around it). */
  light(x: number, y: number, radius: number, c: RGB): void {
    this.lights.push({ weight: lum(c) * radius, item: { x, y, z: 0, radius, color: [c[0], c[1], c[2]] } });
  }

  /** A spherical light front in the medium (it lights the gas it passes through). */
  front(x: number, y: number, radius: number, width: number, c: RGB, weight: number): void {
    if (radius <= 0) return;
    this.fronts.push({ weight, item: { x, y, radius, width, color: [c[0], c[1], c[2]] } });
  }

  /** Splats mass into the gas field: density, heat glow, glow × temperature, enriched density. */
  private splat(x: number, y: number, sigma: number, mass: number, glow: number, temp: number, metal: number): void {
    const rc = this.medium.rect;
    const cw = (rc[2] - rc[0]) / FIELD_W;
    const ch = (rc[3] - rc[1]) / FIELD_H;
    const cx = (x - rc[0]) / cw - 0.5;
    const cy = (y - rc[1]) / ch - 0.5;
    const sx = Math.max(0.6, sigma / cw);
    const sy = Math.max(0.6, sigma / ch);
    const x0 = Math.max(0, Math.floor(cx - 3 * sx));
    const x1 = Math.min(FIELD_W - 1, Math.ceil(cx + 3 * sx));
    const y0 = Math.max(0, Math.floor(cy - 3 * sy));
    const y1 = Math.min(FIELD_H - 1, Math.ceil(cy + 3 * sy));
    if (x1 < x0 || y1 < y0) return;
    const wx = this.seg;
    const n = Math.min(wx.length, x1 - x0 + 1);
    for (let i = 0; i < n; i++) {
      const d = x0 + i - cx;
      wx[i] = Math.exp((-d * d) / (2 * sx * sx));
    }
    const norm = 1 / (2 * Math.PI * sx * sy);
    const d = this.medium.field;
    for (let j = y0; j <= y1; j++) {
      const dy = j - cy;
      const wy = Math.exp((-dy * dy) / (2 * sy * sy)) * norm;
      let o = (j * FIELD_W + x0) * 4;
      for (let i = 0; i < n; i++, o += 4) {
        const w = wx[i] * wy;
        d[o] += mass * w;
        d[o + 1] += glow * w;
        d[o + 2] += glow * temp * w;
        d[o + 3] += metal * w;
      }
    }
  }

  // ─── the dark matter

  /**
   * The halos: their dark matter for the web the background draws in the finale, their lensing, and
   * their pull on the gas the storm's specks show. `drift` is the pair falling together, if any.
   */
  halos(ws: readonly Halo[], pull: number, web: number, t: number, drift: readonly Halo[] | null): void {
    this.halosNow = ws as Halo[];
    if (!this.cmbKnown) this.inventCmb(ws);
    // Stronger with the 21-centimeter line and with deeper dark matter, always subtle.
    const gain = (0.85 + 0.55 * Math.max(0, web - 0.25)) * Math.sqrt(Math.min(2.5, pull));
    ws.forEach((w, i) => {
      const e = 30 * Math.sqrt(w.s) * gain;
      // A halo is lumpy (smaller halos orbit inside it), so its lens is never quite still: its centre
      // of mass wanders a little, slowly; a pair falling together wanders more as they tug at each other.
      const tug = drift && (drift[0] === w || drift[1] === w) ? 2.2 : 1;
      const a = t * (0.31 + 0.07 * i) + i * 2.4;
      const off = 0.14 * e * tug;
      const x = w.x + Math.cos(a) * off + Math.cos(a * 2.3 + 1) * off * 0.4;
      const y = w.y + Math.sin(a * 1.2) * off;
      this.lensList.push({ weight: w.s, item: { x, y, einstein: e, core: e * 1.05, reach: e * 6, shadow: 0 } });
      // Gas squeezed into the well glints faintly.
      this.sources.push({ x: w.x, y: w.y, l: 0.05 * w.s, r: 90 });
    });
    this.buildDm(ws, pull, t);
  }

  /**
   * A universe with no recorded map (an old save, a test) still had its ripples: one is made up from
   * where its halos are (they sit at the peaks), with smaller ripples between.
   */
  private inventCmb(ws: readonly Halo[]): void {
    this.cmbKnown = true;
    const hw = this.play[0];
    const hh = this.play[1];
    for (let j = 0; j < 27; j++) {
      const y = (((j + 0.5) / 27) * 2 - 1) * hh;
      for (let i = 0; i < 48; i++) {
        const x = (((i + 0.5) / 48) * 2 - 1) * hw;
        let v = 0.44 + 0.07 * Math.sin(i * 1.37 + j * 0.41) * Math.cos(j * 1.13 - i * 0.57) + 0.04 * Math.sin(i * 3.1 - j * 2.3);
        for (const w of ws) v += 0.3 * w.s * Math.exp(-((x - w.x) ** 2 + (y - w.y) ** 2) / (2 * 120 * 120));
        this.cmb[j * 48 + i] = Math.min(1, Math.max(0, v));
      }
    }
    this.cmbVersion++;
  }

  /** Dark-matter density: a halo at each well, filaments to its nearest neighbours and on past the edge. */
  private buildDm(ws: readonly Halo[], pull: number, t: number): void {
    // Halos move while they fall together or are held: a few rebuilds a second are plenty.
    if (this.dmKey !== '' && t - this.dmT < 0.12 && t >= this.dmT) return;
    const depth = 0.7 + 0.3 * Math.min(2, pull);
    const key = ws.map((w) => `${w.x.toFixed(0)},${w.y.toFixed(0)},${w.s.toFixed(2)}`).join(';') + depth.toFixed(2);
    this.dmT = t;
    if (key === this.dmKey) return;
    this.dmKey = key;
    const rc = this.bgParams.rect;
    const halfW = this.play[0];
    const halfH = this.play[1];
    const segs: number[] = [];
    const seen = new Set<string>();
    ws.forEach((a, i) => {
      const order = ws
        .map((b, j) => ({ j, d: (a.x - b.x) ** 2 + (a.y - b.y) ** 2 }))
        .filter((o) => o.j !== i)
        .sort((u, v) => u.d - v.d)
        .slice(0, 2);
      for (const o of order) {
        const k = i < o.j ? `${i}-${o.j}` : `${o.j}-${i}`;
        if (seen.has(k)) continue;
        seen.add(k);
        const b = ws[o.j];
        segs.push(a.x, a.y, b.x, b.y, 0.5 * Math.min(a.s, b.s) * depth);
      }
      const ex = a.x / halfW;
      const ey = a.y / halfH;
      const out = Math.hypot(ex, ey);
      if (out > 0.45) {
        const L = 1.6 * Math.max(halfW, halfH);
        segs.push(a.x, a.y, a.x + (ex / out) * L, a.y + (ey / out) * L * 0.8, 0.3 * a.s * depth);
      }
    });
    const cw = (rc[2] - rc[0]) / 128;
    const ch = (rc[3] - rc[1]) / 72;
    const d = this.dm;
    const halo = 1 / (2 * 140 * 140);
    const fil = 1 / (2 * 34 * 34);
    for (let cy = 0; cy < 72; cy++) {
      const y = rc[1] + (cy + 0.5) * ch;
      for (let cx = 0; cx < 128; cx++) {
        const x = rc[0] + (cx + 0.5) * cw;
        let v = 0;
        for (const w of ws) v += 1.05 * w.s * depth * Math.exp(-((x - w.x) ** 2 + (y - w.y) ** 2) * halo);
        for (let k = 0; k < segs.length; k += 5) {
          const ax = segs[k];
          const ay = segs[k + 1];
          const bx = segs[k + 2] - ax;
          const by = segs[k + 3] - ay;
          const u = Math.max(0, Math.min(1, ((x - ax) * bx + (y - ay) * by) / (bx * bx + by * by || 1)));
          const qx = x - ax - bx * u;
          const qy = y - ay - by * u;
          const pinch = 1 + 1.6 * Math.min(u, 1 - u);
          v += segs[k + 4] * Math.exp(-(qx * qx + qy * qy) * fil * pinch);
        }
        d[cy * 128 + cx] = v;
      }
    }
    this.dmVersion++;
  }

  /**
   * The latest halo merger, `age` seconds ago: the gas round the deeper well flares warm as the
   * virial shock heats it, then cools.
   */
  merger(x: number, y: number, age: number, mu: number): void {
    if (age < 0 || age > 9) return;
    const rise = Math.min(1, age / 0.35);
    const fall = Math.exp(-age / 2.6);
    const k = rise * fall * Math.min(1.6, 0.4 + mu);
    if (k <= 0.004) return;
    // Hot first (orange), cooling to a dull red as it fades.
    const hot = Math.exp(-age / 1.4);
    const c: RGB = [1.0 * k, (0.16 + 0.32 * hot) * k, (0.04 + 0.1 * hot) * k];
    this.light(x, y, 150 + 60 * Math.min(1, age), [c[0] * 0.09, c[1] * 0.09, c[2] * 0.09]);
    this.speckLights.push({ weight: k, item: { x, y, intensity: 0.6 * k, radius: 220, width: 0 } });
  }

  /** Ionized bubbles: spheres in the medium, rebuilt a few times a second (often while they merge). */
  bubbles(list: readonly Bubble[], t: number): void {
    const fast = (this.frame?.bg.finale ?? 0) > 0;
    if (this.ionT >= 0 && t - this.ionT < (fast ? 0.05 : 0.1) && t >= this.ionT) return;
    this.ionT = t;
    const d = this.medium.ion;
    for (let i = 0; i < ION_W * ION_H; i++) {
      d[i * 4] = -ION_FAR;
      d[i * 4 + 1] = 0;
      d[i * 4 + 2] = 0;
      d[i * 4 + 3] = 0;
    }
    const rc = this.medium.rect;
    const cw = (rc[2] - rc[0]) / ION_W;
    const ch = (rc[3] - rc[1]) / ION_H;
    for (const b of list) {
      if (b.r < 3) continue;
      const reach = b.r + ION_FAR;
      // A bubble its stars still feed burns bright; one left to recombine deepens to red and dims.
      const flux = Math.min(1.25, Math.sqrt(Math.max(0, b.n)));
      const cx0 = Math.max(0, Math.floor((b.x - reach - rc[0]) / cw));
      const cx1 = Math.min(ION_W - 1, Math.ceil((b.x + reach - rc[0]) / cw));
      const cy0 = Math.max(0, Math.floor((b.y - reach - rc[1]) / ch));
      const cy1 = Math.min(ION_H - 1, Math.ceil((b.y + reach - rc[1]) / ch));
      for (let cy = cy0; cy <= cy1; cy++) {
        const dy = rc[1] + (cy + 0.5) * ch - b.y;
        for (let cx = cx0; cx <= cx1; cx++) {
          const dx = rc[0] + (cx + 0.5) * cw - b.x;
          const v = b.r - Math.sqrt(dx * dx + dy * dy);
          const o = (cy * ION_W + cx) * 4;
          if (v > d[o]) {
            d[o] = v;
            d[o + 1] = b.r;
            d[o + 2] = flux;
          }
        }
      }
    }
    this.medium.ionVersion++;
  }

  // ─── matter

  /** A parcel of neutral hydrogen: mass in the gas field, nothing drawn on its own. */
  gas(x: number, y: number, k: number, hot: number, enriched: boolean): void {
    if (k <= 0.01) return;
    // Hot gas (blown out of a newborn star's halo) glows faintly as it flies.
    this.splat(x, y, PARCEL_SIGMA, k, hot * 1.2 * k, 0.7, enriched ? k : 0);
  }

  /**
   * A clump: a dense knot in the gas that glows from inside with the heat it is shining away (`glow`,
   * at temperature `temp` 0–1), with its Jeans mass as a front at `jeans` (world units) when it can
   * collapse. `ratio` is mass over Jeans mass: past 0.75 the front turns gold and quickens.
   */
  clump(x: number, y: number, m: number, rad: number, glow: number, temp: number, enriched: boolean, jeans: number, ratio: number, t: number, id: number): void {
    // Never a disc: a dense core and a few lumps turning round it, faster and tighter as collapse nears.
    const near = Math.min(1, ratio);
    const metal = enriched ? m : 0;
    this.splat(x, y, rad * 0.4, m * 0.4, glow * 0.5, temp, metal * 0.4);
    const spin = (0.25 + 1.6 * near * near) * (id % 2 ? 1 : -1);
    for (let l = 0; l < 4; l++) {
      const a = id * 2.1 + (l * Math.PI) / 2 + l * 0.7 + t * spin * (1 + 0.2 * l);
      const off = rad * (0.45 + 0.2 * Math.sin(id + l * 1.9)) * (1 - 0.4 * near);
      this.splat(x + Math.cos(a) * off, y + Math.sin(a) * off, rad * (0.28 + 0.06 * l), m * 0.15, glow * 0.125, temp, metal * 0.15);
    }
    // Its heat glints on the specks inside it.
    if (glow > 0.2) this.sources.push({ x, y, l: Math.min(0.6, glow * 0.12), r: rad * 1.4 });
    if (jeans <= 0) return;
    if (ratio > 0.75) {
      const urgency = Math.min(1, (ratio - 0.75) / 0.25);
      const beat = 0.7 + 0.3 * Math.sin(t * (5 + 7 * urgency) + id);
      const f = (0.35 + 0.65 * urgency) * beat;
      this.front(x, y, jeans, 5, [0.11 * f, 0.07 * f, 0.025 * f], 2 + ratio);
      this.speckLights.push({ weight: 1 + ratio, item: { x, y, intensity: 1.2 * f, radius: jeans, width: 7 } });
      // Ripples falling inward: it is about to go.
      const ph = (t * (0.8 + 0.7 * urgency) + id * 0.37) % 1;
      const rr = jeans - (jeans - rad * 0.6) * ph;
      const g = Math.sin(ph * Math.PI) * (0.3 + 0.7 * urgency);
      this.front(x, y, rr, 4, [0.08 * g, 0.05 * g, 0.018 * g], 1 + ratio);
    } else {
      const f = 0.25 + 0.75 * (ratio / 0.75) ** 2;
      this.front(x, y, jeans, 4, [0.022 * f, 0.03 * f, 0.05 * f], ratio);
      this.speckLights.push({ weight: ratio, item: { x, y, intensity: 0.55 * f, radius: jeans, width: 6 } });
    }
  }

  /**
   * A protostar, `k` 0 → 1 through its collapse: streamers spiral into a core heating from red to
   * white; the very first holds the whole universe still around it.
   */
  protostar(x: number, y: number, k: number, t: number, id: number, first: boolean): void {
    const r = this.r;
    if (!r) return;
    const k2 = k * k;
    // The envelope falling in: mass still in the field, drawn tighter as it goes.
    this.splat(x, y, 34 - 24 * k, 26, 6 * k2, 0.3 + 0.7 * k, 0);
    // The core: deep red → orange → white, its light climbing steeply.
    const cr = 1.0;
    const cg = 0.25 + 0.7 * k2;
    const cb = 0.08 + 0.9 * k2 * k;
    const e = (0.6 + 9 * k2 * k2) * (0.92 + 0.08 * Math.sin(t * 37 + id));
    r.top.push(x, y, 1.7 + 0.6 * k, cr * e * 1.6, cg * e * 1.6, cb * e * 1.6, 1, Shape.Glow);
    r.top.push(x, y, 9, cr * e * 0.12, cg * e * 0.12, cb * e * 0.12, 1, Shape.Glow);
    this.light(x, y, 40 + 70 * k, [0.02 * e, 0.02 * e * cg, 0.02 * e * cb]);
    this.sources.push({ x, y, l: 0.5 * e, r: 60 });
    // Streamers: gas spiralling in along a few ribbons, each a thin bright core in a soft sheath that
    // widens and brightens into a glowing foot at the core.
    const arms = 3;
    const spin = (1.6 + 5 * k) * (id % 2 ? 1 : -1);
    const reach = 70 * (1 - 0.55 * k);
    const segs = this.filaments.segments(18, 10);
    for (let a = 0; a < arms; a++) {
      const a0 = (id * 1.7 + (a * Math.PI * 2) / arms + t * spin * 0.25) % (Math.PI * 2);
      const pts = new Float32Array((segs + 1) * 2);
      const core = new Float32Array(segs + 1);
      const sheath = new Float32Array(segs + 1);
      for (let j = 0; j <= segs; j++) {
        const s = j / segs;
        const rr = 3 + reach * (1 - s) ** 1.3;
        const ang = a0 + (1 - s) * (1.1 + 0.5 * Math.sin(a * 2.1 + id)) * (id % 2 ? 1 : -1);
        pts[j * 2] = x + Math.cos(ang) * rr;
        pts[j * 2 + 1] = y + Math.sin(ang) * rr;
        const g = (0.15 + 0.85 * s * s) * (0.3 + 1.4 * k);
        core[j] = 0.22 * g;
        sheath[j] = 0.05 * g * (0.4 + 0.6 * s);
      }
      this.filaments.push(pts, [0.6, 0.12, 0.05], [cr, cg, cb], 6 + 6 * k, core, sheath);
    }
    if (first) this.speckLights.push({ weight: 4, item: { x, y, intensity: 0.4 * k, radius: 90, width: 0 } });
  }

  /**
   * A first star: a crisp blue-white point of real dynamic range that lights its bubble. At birth a
   * flare that lights the gas far around it (the first in the universe brightest of all); late in its
   * short life it swells and reddens. `front` is its own ionization front racing out to `frontMax`.
   */
  star(x: number, y: number, m: number, life: number, age: number, pop2: boolean, front: number, frontMax: number, t: number, id: number, first: boolean): void {
    const r = this.r;
    if (!r) return;
    const late = life < 3 ? 1 - life / 3 : 0;
    const mass = Math.pow(m / 50, 0.35);
    const flick = late > 0 ? 1 - 0.25 * late * (0.5 + 0.5 * Math.sin(t * 23 + id)) : 1;
    // Birth: a flash of light, then a settling over a second or two.
    const birth = age < 2 ? Math.exp(-age / (first ? 0.55 : 0.3)) * (first ? 1 : 0.35) : 0;
    const c: RGB = pop2 ? [1.0, 0.9, 0.78] : [0.7 + 0.32 * late, 0.82 - 0.1 * late, 1.0 - 0.35 * late];
    const k = (pop2 ? 6 : 10) * mass * flick;
    const core = k * (1 + 40 * birth);
    r.top.push(x, y, 1.9 + 0.7 * late + 1.2 * birth, core * 1.25, core * 1.22, core * 1.18, 1, Shape.Glow);
    r.top.push(x, y, 6.5 * (1 + 0.4 * late), c[0] * k * 0.55, c[1] * k * 0.55, c[2] * k * 0.55, 1, Shape.Glow);
    r.top.push(x, y, 22 * (1 + 0.5 * late + 2 * birth), c[0] * k * 0.04 * (1 + 6 * birth), c[1] * k * 0.04 * (1 + 6 * birth), c[2] * k * 0.04 * (1 + 6 * birth), 1, Shape.Glow);
    // Its light in the gas: far at birth, then the steady glow of its bubble.
    const reach = 120 * mass + (first ? 900 : 380) * birth;
    const li = 0.06 * mass * flick + (first ? 2.0 : 0.4) * birth;
    this.light(x, y, reach, [c[0] * li, c[1] * li, c[2] * li]);
    this.speckLights.push({ weight: li * 10, item: { x, y, intensity: 0.9 * mass + 4 * birth, radius: 70 * mass + 300 * birth, width: 0 } });
    this.sources.push({ x, y, l: mass * flick * (1 + 6 * birth), r: 110 * mass });
    if (first && birth > 0.02) this.kicks.push({ weight: 10, item: { x, y, radius: 40 + age * 260, push: 500 * birth } });
    // Its own ionization front racing outward, fading as it settles into the bubble.
    const grow = 1 - Math.min(1, front / Math.max(1, frontMax));
    if (grow > 0.02) {
      const g = grow * grow;
      this.front(x, y, Math.max(8, front), 4 + front * 0.05, [0.12 * g, 0.03 * g, 0.06 * g], 0.5 + grow);
    }
  }

  /** A black hole: an absence ringed by the light it bends, in a faint warm thread of infalling gas. */
  blackHole(x: number, y: number, rad: number, t: number, id: number): void {
    const shadow = rad * 1.15;
    this.lensList.push({ weight: 100, item: { x, y, einstein: shadow * 2.1, core: shadow * 0.35, reach: shadow * 7, shadow } });
    // Gas spiralling in, lit by its own friction: one side brighter, where it comes toward us.
    const segs = this.filaments.segments(28, 12);
    const pts = new Float32Array((segs + 1) * 2);
    const core = new Float32Array(segs + 1);
    const sheath = new Float32Array(segs + 1);
    const tilt = 0.38;
    const turn = t * 0.9 + id;
    for (let j = 0; j <= segs; j++) {
      const a = (j / segs) * Math.PI * 2 * 0.86 + turn;
      const rr = shadow * 1.55;
      pts[j * 2] = x + Math.cos(a) * rr;
      pts[j * 2 + 1] = y + Math.sin(a) * rr * tilt;
      const doppler = 0.55 + 0.45 * Math.cos(a - 0.4);
      core[j] = 0.35 * doppler * doppler;
      sheath[j] = 0.05 * doppler;
    }
    this.filaments.push(pts, [1.0, 0.6, 0.32], [1.0, 0.82, 0.6], 3.5, core, sheath);
  }

  /** Fresh carbon, oxygen and iron: small glints, gold or teal, that slow and fade. */
  metal(x: number, y: number, vx: number, vy: number, fade: number, teal: boolean, t: number, id: number): void {
    const r = this.r;
    if (!r || fade <= 0.01) return;
    const sp = Math.hypot(vx, vy);
    const c = fade * (0.35 + 0.65 * Math.min(1, sp / 80)) * (0.85 + 0.15 * Math.sin(t * 9 + id));
    const col: RGB = teal ? [0.45, 1.0, 0.9] : [1.0, 0.72, 0.3];
    r.glow.push(x, y, 1.1, col[0] * 2.4 * c, col[1] * 2.4 * c, col[2] * 2.4 * c, 1, Shape.Glow, 0, 0, vx * 0.03, vy * 0.03);
  }

  /** The hand while it holds: a mass that bends what lies behind it and draws the gas in. */
  handAt(x: number, y: number, reach: number, held: boolean, dt: number): void {
    this.handK += ((held ? 1 : 0) - this.handK) * (1 - Math.exp(-dt * (held ? 5 : 3)));
    if (this.handK < 0.01) return;
    const e = 24 * this.handK;
    this.lensList.push({ weight: 50, item: { x, y, einstein: e, core: e * 1.1, reach: e * 6, shadow: 0 } });
    this.hand = { x, y, reach, k: held ? this.handK : 0 };
    // Gas drawn together warms as it is squeezed: the specks glint as they near the hand.
    this.sources.push({ x, y, l: 0.3 * this.handK, r: reach * 0.3 });
  }

  /** A cosmetic shell (a supernova's ejecta, an ionization front): a light front racing through the gas. */
  shell(x: number, y: number, radius: number, c: RGB, f: number, speed: number): void {
    const l = lum(c) * f;
    if (l <= 0.004) return;
    this.front(x, y, radius, 5 + radius * 0.035, [c[0] * 0.15 * f, c[1] * 0.15 * f, c[2] * 0.15 * f], 3 + l);
    // Only fast shells throw the specks.
    if (speed > 400) this.kicks.push({ weight: l, item: { x, y, radius, push: 1.1 * speed * Math.min(1.5, l) * f } });
    this.speckLights.push({ weight: l, item: { x, y, intensity: (2.2 * l) / (1 + radius / 700), radius, width: 18 + radius * 0.05 } });
  }

  // ─── FxLook: the era's effects, restyled

  flash(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * (1 - t);
    const rr = this.r;
    if (!rr || f <= 0.003) return;
    rr.top.push(x, y, Math.min(3.2, 1.4 + size * 0.012), r * f * 2.2, g * f * 2.2, b * f * 2.2, 1, Shape.Glow);
    rr.top.push(x, y, size * 0.22, r * f * 0.16, g * f * 0.16, b * f * 0.16, 1, Shape.Glow);
    const c: RGB = [r * f * 0.035, g * f * 0.035, b * f * 0.035];
    this.light(x, y, size * 2.2, c);
    const l = lum([r, g, b]) * f;
    this.speckLights.push({ weight: l * size * 0.02, item: { x, y, intensity: 1.6 * l, radius: size * 1.4, width: 0 } });
  }

  ring(x: number, y: number, radius: number, r: number, g: number, b: number, t: number): void {
    const f = Math.pow(1 - t, 1.6);
    if (f <= 0.01) return;
    const l = lum([r, g, b]);
    this.front(x, y, radius, 6 + radius * 0.05, [r * 0.06 * f, g * 0.06 * f, b * 0.06 * f], 2 + l * f);
    this.kicks.push({ weight: l * f, item: { x, y, radius, push: 260 * Math.min(2, l) * f } });
    this.speckLights.push({ weight: l * f, item: { x, y, intensity: (2.4 * l * f) / (1 + radius / 700), radius, width: 16 + radius * 0.06 } });
  }

  spark(x: number, y: number, vx: number, vy: number, size: number, r: number, g: number, b: number, t: number): void {
    // Debris and starlight: faint glints, never a spray of streaks.
    const f = (1 - t) * (1 - t);
    const k = Math.min(1, size * 0.2) * f;
    if (k <= 0.02) return;
    const l = Math.max(1, lum([r, g, b]));
    const c: RGB = [r / l, g / l, b / l];
    const tx = x - vx * 0.02;
    const ty = y - vy * 0.02;
    this.filaments.push([tx, ty, (tx + x) / 2, (ty + y) / 2, x, y], c, [1, 1, 1], 2, [0, 0.12 * k, 0.45 * k], [0, 0.01 * k, 0.02 * k], false);
  }

  puff(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * Math.min(1, t * 6);
    if (f > 0.01) this.light(x, y, size, [r * 0.05 * f, g * 0.05 * f, b * 0.05 * f]);
  }

  /** Ends the frame: the strongest lights, fronts, pushes and lenses go to the layers; the flow is built. */
  end(): void {
    const top = <T>(list: Ranked<T>[], n: number): T[] => list.sort((a, b) => b.weight - a.weight).slice(0, n).map((x) => x.item);
    this.medium.lights = top(this.lights, 8);
    this.medium.fronts = top(this.fronts, 8);
    this.storm.kicks = top(this.kicks, 4);
    this.storm.lights = top(this.speckLights, 8);
    this.lens.lenses = top(this.lensList, 8);
    this.medium.fieldVersion++;
    this.buildFlow();
  }

  /**
   * The flow the storm's specks ride, over the current view: toward the halos (gently), toward the
   * hand (hard, while it holds); and the light they glint in (stars, protostars, bubbles' bodies).
   */
  private buildFlow(): void {
    const r = this.r;
    if (!r) return;
    const cam = r.camera;
    const hw = cam.halfW;
    const hh = cam.halfH;
    const cx = cam.x;
    const cy = cam.y;
    const vel = this.medium.flowVelocity;
    const light = this.medium.flowLight;
    const sx = FLOW_W / (2 * hw);
    const sy = FLOW_H / (2 * hh);
    const pull = Math.sqrt(Math.min(2.5, this.frame?.pull ?? 1));
    const hand = this.hand;
    const rc = this.medium.rect;
    const icw = ION_W / (rc[2] - rc[0]);
    const ich = ION_H / (rc[3] - rc[1]);
    const ion = this.medium.ion;
    const srcs = this.sources;
    for (let j = 0; j < FLOW_H; j++) {
      // Row j is v = (j + 0.5) / FLOW_H, and v runs bottom to top (world y is down).
      const y = cy + hh * (1 - (2 * (j + 0.5)) / FLOW_H);
      for (let i = 0; i < FLOW_W; i++) {
        const x = cx + hw * ((2 * (i + 0.5)) / FLOW_W - 1);
        let vx = 0;
        let vy = 0;
        // Inside a core the pull gives way to a slow swirl, so the specks gather round a centre as a
        // loose crowd instead of piling into a point.
        for (const w of this.halosNow) {
          const dx = w.x - x;
          const dy = w.y - y;
          const d = Math.hypot(dx, dy) + 1;
          const f = ((w.s * pull * 1000) / (d + 140) / (1 + d / 600)) * smooth(30, 110, d);
          const s = (w.s * 5) / (1 + d / 120);
          vx += (dx / d) * f - (dy / d) * s;
          vy += (dy / d) * f + (dx / d) * s;
        }
        if (hand && hand.k > 0) {
          const dx = hand.x - x;
          const dy = hand.y - y;
          const d = Math.hypot(dx, dy) + 1;
          const R = hand.reach * 1.2;
          if (d < R) {
            const f = ((hand.k * 190 * (1 - d / R)) / (1 + d / 160)) * smooth(hand.reach * 0.1, hand.reach * 0.32, d);
            const s = hand.k * 12 * (1 - d / R);
            vx += (dx / d) * f - (dy / d) * s;
            vy += (dy / d) * f + (dx / d) * s;
          }
        }
        const o = j * FLOW_W + i;
        vel[o * 2] = vx * sx;
        vel[o * 2 + 1] = -vy * sy;
        let l = 0;
        for (const s of srcs) {
          const dx = s.x - x;
          const dy = s.y - y;
          l += s.l / (1 + (dx * dx + dy * dy) / (s.r * s.r));
        }
        // Inside a bubble, its glow.
        const ix = Math.floor((x - rc[0]) * icw);
        const iy = Math.floor((y - rc[1]) * ich);
        if (ix >= 0 && iy >= 0 && ix < ION_W && iy < ION_H) {
          const q = (iy * ION_W + ix) * 4;
          if (ion[q] > 0) l += 0.12 * ion[q + 2];
        }
        light[o * 4] = l;
        light[o * 4 + 1] = l;
        light[o * 4 + 2] = l;
        light[o * 4 + 3] = 1;
      }
    }
    this.medium.flowVersion++;
  }
}
