/** Keys 1–9 buy the visible, unmaxed phenomena in panel order (shared by the panel and the key handler). */
import type { Game } from '../core/game';

export function hotkeyTargets(g: Game): string[] {
  return g
    .visiblePhenomena(g.state.run.era)
    .filter((p) => !g.isMaxed(p.id))
    .slice(0, 9)
    .map((p) => p.id);
}
