<!--
  The cosmic timeline: one segment per era. Eras not yet reached are unnamed ticks.
-->
<script lang="ts">
  import { ERA_ORDER } from '../../core/state';
  import { game, track } from '../store.svelte';

  const g = game();
  const v = $derived.by(() => {
    track();
    const run = g.state.run;
    const idx = ERA_ORDER.indexOf(run.era);
    const steps = g.steps().length;
    const within = steps > 1 ? run.step / (steps - 1) : 0;
    const n = ERA_ORDER.length;
    return { idx, pos: (idx + within) / n, n };
  });
</script>

<div class="timeline" role="img" aria-label="Cosmic timeline: era {v.idx + 1} of {v.n}">
  <div class="track"></div>
  <div class="fill" style="width: {v.pos * 100}%"></div>
  {#each ERA_ORDER as id, i (id)}
    <div class="tick" class:past={i <= v.idx} style="left: {(i / v.n) * 100}%" title={i <= v.idx ? (g.eraDefOf(id)?.title ?? '') : ''}></div>
  {/each}
  <div class="now" style="left: {v.pos * 100}%"></div>
</div>

<style>
  .timeline {
    position: relative;
    width: min(30vw, 30rem);
    height: 12px;
  }
  .track,
  .fill {
    position: absolute;
    top: 50%;
    left: 0;
    height: 1px;
  }
  .track {
    right: 0;
    background: var(--line);
  }
  .fill {
    background: linear-gradient(90deg, var(--line-2), var(--accent-soft));
    transition: width 1.2s var(--ease);
  }
  .tick {
    position: absolute;
    top: 50%;
    width: 1px;
    height: 5px;
    translate: 0 -50%;
    background: var(--ink-4);
  }
  .tick.past {
    background: var(--ink-3);
    height: 7px;
  }
  .now {
    position: absolute;
    top: 50%;
    width: 5px;
    height: 5px;
    translate: -50% -50%;
    border-radius: 50%;
    background: var(--accent);
    box-shadow: 0 0 10px var(--accent);
    transition: left 1.2s var(--ease);
  }
</style>
