/**
 * The desktop shell's bridge (electron/preload.cjs), when the game runs inside it. In a browser all of
 * this is absent and the game uses its web fallbacks.
 */
import type { StorageAdapter } from '../core/save';

export interface NativeBridge {
  storage: {
    read(key: string): string | null;
    write(key: string, value: string): boolean;
    remove(key: string): boolean;
  };
  steam: {
    available(): boolean;
    achievement(id: string): void;
  };
  quit(): void;
  setFullscreen(on: boolean): void;
  isFullscreen(): boolean;
}

export function native(): NativeBridge | null {
  return (globalThis as unknown as { ylemNative?: NativeBridge }).ylemNative ?? null;
}

/** Saves as plain files in the user's data folder (Steam Auto-Cloud can sync them). */
export class NativeStorageAdapter implements StorageAdapter {
  constructor(private readonly bridge: NativeBridge) {}
  read(key: string): string | null {
    return this.bridge.storage.read(key);
  }
  write(key: string, value: string): void {
    if (!this.bridge.storage.write(key, value)) throw new Error('The save file could not be written.');
  }
  remove(key: string): void {
    this.bridge.storage.remove(key);
  }
}
