<!--
  Between universes: how the last one ended and what it taught, the seeds its black holes offer, what
  the player remembers (Knowledge, bought with Insight), and every universe so far. The first visit
  opens with the pull-back into the foam.
-->
<script lang="ts">
  import { count, duration } from '../../core/format';
  import { KNOWLEDGE, type KnowledgeDef } from '../../core/knowledge';
  import { INFLATION_AFTER, INFLATION_MILESTONES, inflationTower } from '../../core/multiverse';
  import Num from '../common/Num.svelte';
  import { audio, game, track } from '../store.svelte';
  import Foam from './Foam.svelte';
  import SeedCard from './SeedCard.svelte';

  const g = game();
  const NAMES = ['A', 'B', 'C', 'D', 'E', 'F'];

  const v = $derived.by(() => {
    track();
    const meta = g.state.meta;
    return {
      at: meta.atMultiverse,
      last: meta.last,
      seeds: [...meta.seeds],
      parent: g.seedParent(),
      seedFrom: meta.seedFrom,
      insight: meta.insight,
      knowledge: { ...meta.knowledge },
      lineage: [...meta.lineage].reverse(),
      revealSeen: meta.revealSeen,
      inflation: meta.lineage.length >= INFLATION_AFTER ? inflationTower(meta.inflationT) : null,
      nextMilestone: INFLATION_MILESTONES[meta.inflationMilestones] ?? null,
    };
  });

  const REVEAL = [
    'Nothing is left to happen here.',
    'Pull back far enough, and this whole universe is a single bubble.',
    'There are others.',
    "Some physicists think every black hole holds a new universe, with laws slightly changed. Nobody knows. Let's assume they're right.",
  ];
  let shown = $state(0);
  let revealing = $state(false);
  let hovered = $state(-1);
  let showLineage = $state(false);

  // Primitives, so the reveal starts once (v itself is a fresh object every UI tick).
  const at = $derived(v.at);
  const revealSeen = $derived(v.revealSeen);

  $effect(() => {
    if (!at || revealSeen) return;
    revealing = true;
    shown = 0;
    const timers = REVEAL.map((_, i) => setTimeout(() => (shown = i + 1), 1400 + i * 3600));
    return () => timers.forEach(clearTimeout);
  });

  function endReveal(): void {
    g.state.meta.revealSeen = true;
    revealing = false;
    g.persist();
  }

  function pick(k: number): void {
    audio().cue('ui.buy', {});
    g.inflate(k);
  }

  function learn(k: KnowledgeDef): void {
    if (g.buyKnowledge(k.id)) audio().cue('ui.buy', {});
    else audio().cue('ui.deny', {});
  }

  const buds = $derived(Math.max(v.seeds.length + 3, Math.min(48, Math.round(Math.log10(Math.max(10, v.last?.blackHoles ?? 10)) * 3))));
</script>

{#if v.at && v.last}
  <div class="mv" role="dialog" aria-label="The multiverse">
    <Foam {buds} highlight={hovered} seeds={v.seeds.length} pull={revealing && !g.state.settings.reduceMotion} />

    {#if revealing}
      <button class="reveal" onclick={() => (shown >= REVEAL.length ? endReveal() : (shown = REVEAL.length))}>
        {#each REVEAL.slice(0, shown) as line, i (i)}
          <p class:last={i === REVEAL.length - 1}>{line}</p>
        {/each}
        {#if shown >= REVEAL.length}<span class="cont label">Continue</span>{/if}
      </button>
    {:else}
      <div class="grid">
        <div class="top">
          <section class="end">
            <div class="label">Universe {v.last.index}</div>
            <h1>{v.last.title}</h1>
            <p class="text">{v.last.text}</p>
            <dl class="facts">
              <dt class="label">Lasted, for you</dt>
              <dd>{duration(v.last.playTime)}</dd>
              <dt class="label">Black holes it made</dt>
              <dd><Num parts={count(v.last.blackHoles, g.state.settings.notation)} /></dd>
              <dt class="label">First discoveries</dt>
              <dd>{v.last.finds}</dd>
            </dl>
          </section>
          <section class="taught">
            <div class="label">What it taught</div>
            {#each v.last.insight.lines as line (line.label)}
              <div class="row"><span>{line.label}</span><span class="num">+{line.value}</span></div>
            {/each}
            <div class="row total"><span>Insight</span><span class="num">+{v.last.insight.total}</span></div>
          </section>
          {#if v.inflation}
            {@const n = v.inflation}
            <section class="foam-count">
              <div class="label">Eternal inflation</div>
              <div class="big">
                {#if n.outer}10<sup>10<sup>{n.inner}</sup></sup>{:else}10<sup>{n.inner}</sup>{/if}
                <span class="unit">universes, budding on their own</span>
              </div>
              {#if v.nextMilestone}
                <div class="next">Next: {v.nextMilestone.name} · +{v.nextMilestone.insight} Insight</div>
              {:else}
                <div class="next">On toward ten to the ten to the ten million: by one estimate, how many different universes inflation could make.</div>
              {/if}
            </section>
          {/if}
        </div>

        <aside class="know">
          <div class="head">
            <span class="label">Knowledge</span>
            <span class="ins"><span class="num">{Math.floor(v.insight)}</span> Insight</span>
          </div>
          <p class="sub">What you remember that no universe does.</p>
          <ul>
            {#each KNOWLEDGE as k (k.id)}
              {@const lvl = v.knowledge[k.id] ?? 0}
              {@const maxed = lvl >= k.costs.length}
              {@const cost = maxed ? 0 : k.costs[lvl]}
              <li class:owned={lvl > 0} class:maxed>
                <div class="kh">
                  <span class="kn">{k.name}</span>
                  {#if k.costs.length > 1}
                    <span class="dots">{#each k.costs as _, i (i)}<i class:on={i < lvl}></i>{/each}</span>
                  {/if}
                </div>
                <p>{k.text}</p>
                {#if !maxed}
                  <button class="buy" class:can={v.insight >= cost} onclick={() => learn(k)}>{cost} Insight</button>
                {:else}
                  <span class="have label">Known</span>
                {/if}
              </li>
            {/each}
          </ul>
        </aside>

        <section class="seeds">
          <div class="label">
            {#if v.seedFrom === v.last.index}
              Its black holes hold {v.seeds.length} seeds. Choose the next universe.
            {:else}
              It made no black holes, so it left no seeds. The black holes of Universe {v.seedFrom} still hold {v.seeds.length}. Choose the next universe.
            {/if}
          </div>
          <div class="row-cards">
            {#each v.seeds as c, k (k)}
              <SeedCard {c} parent={v.parent} name={NAMES[k]} sight={(v.knowledge.sight ?? 0) > 0} onpick={() => pick(k)} onhover={(on) => (hovered = on ? k : -1)} />
            {/each}
          </div>
        </section>


        <section class="lineage">
          <button class="label tog" onclick={() => (showLineage = !showLineage)}>Lineage · {v.lineage.length} universe{v.lineage.length === 1 ? '' : 's'} {showLineage ? '▾' : '▸'}</button>
          {#if showLineage}
            <ol>
              {#each v.lineage as u (u.index)}
                <li>
                  <span class="ix">{u.index}</span>
                  <span class="from">{u.parent ? `from ${u.parent}` : 'ours'}</span>
                  <span class="fate">{u.fate}</span>
                  <span class="dur">{duration(u.playTime)}</span>
                  <span class="num">+{u.insight}</span>
                </li>
              {/each}
            </ol>
          {/if}
        </section>
      </div>
    {/if}
  </div>
{/if}

