<!--
  One quiet contextual instruction at a time, only when it helps.
-->
<script lang="ts">
  import { fade } from 'svelte/transition';
  import { game, track } from '../store.svelte';

  const g = game();
  const hint = $derived.by(() => {
    track();
    return g.era?.hint() ?? null;
  });
</script>

<div class="hint-wrap" aria-live="polite">
  {#key hint}
    {#if hint}
      <p class="hint" in:fade={{ duration: 600, delay: 150 }} out:fade={{ duration: 300 }}>{hint}</p>
    {/if}
  {/key}
</div>

