/**
 * Era II — The First Three Minutes (Big Bang nucleosynthesis, 1 s → 20 min).
 *
 * Nuclei repel each other electrically; only collisions fast enough to beat that Coulomb barrier
 * fuse (with a small quantum-tunnelling chance below it). The player flings nuclei into each other.
 * Until about three minutes the light is hot enough to split deuterium as soon as it forms (the
 * deuterium bottleneck), and free neutrons decay, so the race is to lock neutrons into helium-4.
 * Result carried forward: Yₚ, the helium mass fraction (ours: 0.245), plus trace D and Li.
 */
import type { EraDef, StepGoal } from '../../core/era';
import type { Game } from '../../core/game';
import { decimal, percent, type NumParts } from '../../core/format';
import { fixed, geometric, type PhenomenonDef } from '../../core/phenomena';
import { NUCLEO_AUDIO, NUCLEO_SOUND } from './audio';
import { NUCLEO_CODEX } from './codex';
import { NucleoEra } from './sim';

const fNum = (v: number): NumParts => decimal(v, 3);
const fMult = (v: number): NumParts => {
  const d = decimal(v, 3);
  return { ...d, m: '×' + d.m };
};
const fPct = (v: number): NumParts => percent(v, 3);

const J = 6.241509074e18;
/** Overall price level of the era relative to its yields; tuned with tools/balance. */
const PRICE = 1;

/** Energy in hand toward the next step's price (a goal is read while its step is the next one). */
const toward = (g: Game): number => g.energy / Math.max(1, g.nextStep?.cost ?? Infinity);
/** Helium's share of all ordinary matter by mass so far (Yₚ). */
const heliumByMass = (g: Game): number => (g.state.run.eras.nucleo as { yp?: number } | undefined)?.yp ?? 0;
/** Helium by mass that freeze-out asks for (its gate, below). */
const HELIUM_NEEDED = 0.12;

/**
 * A goal past the first step: until the Reaction Network is open no helium can form, so until then
 * the goal is the network.
 */
const afterNetwork =
  (goal: (g: Game) => StepGoal) =>
  (g: Game): StepGoal =>
    g.level('nucleo.network') > 0
      ? goal(g)
      : {
          text: 'Open the Reaction Network',
          detail: 'Then deuterium can fuse on toward helium, the safest place a neutron can be.',
          progress: g.energy / Math.max(1, g.phenomenonCost('nucleo.network')),
        };

