/**
 * The Soup simulation.
 *
 * Every condensation makes a quark and its antiquark flying apart with equal and opposite momentum.
 * The pair attracts and comes back together to annihilate into light (energy). Once baryogenesis is
 * active, some antiquarks decay before the reunion, orphaning their quark: that quark is matter that
 * survives (the Free quarks stock). Free quarks drift and, with Color Charge, cluster into
 * red-green-blue triplets, which pays off when confinement locks them into protons and neutrons.
 */
import type { EraModule, OfflineReport, PointerInfo, StockView, WorldLabel } from '../../core/era';
import { fieldHalf } from '../../core/field';
import type { Game } from '../../core/game';
import { count, decimal, toText } from '../../core/format';
import { RateMeter } from '../../core/meter';
import type { RGB } from '../../render/color';
import { Fx, FxPool } from '../../render/fx';
import type { Renderer } from '../../render/renderer';
import { Shape } from '../../render/sprites';
import { Grid } from '../../physics/grid';
import { Particles } from '../../physics/particles';
import { Torus } from '../../physics/torus';
import { DENS_H, DENS_W, HEAT_MAX, type SoupBgParams } from './background';
import { Hadrons } from './hadrons';
import { SoupLook } from './look';

/** Seconds the Soup takes to open out of reheating's light. */
const INTRO = 1.4;
/** How far past an edge of the view something can still show (its glow, a string): drawn on both sides. */
const EDGE = 90;

/**
 * The finale's timeline (seconds from its start), on the beats of its music (tools/sound/cues/finale.ts,
 * which plays from the same moment): the triplets start to bind, the strings snap on the crack, the last
 * antimatter goes on the boom, the survivors are counted, and the camera starts drawing back under the
 * held D (the pull-back's own timing brings Era II in as the harmony settles into B♭).
 */
const F_BUILD = 2;
const F_SNAP = 11.2;
const F_BOOM = 15;
const F_SURVIVORS = 16;
const F_DONE = 21;

// Particle kinds
const QUARK = 0;
const ANTI = 1;
const FREE = 2;
const LEPTON = 3;
const BARYON = 4;

// Flags
const F_MANUAL = 1;
const F_FADE = 2;

/** Energy released by one light quark–antiquark annihilation at weight 1 (eV). */
const E0 = 1e9;
/** Heavy flavors (index 1 strange, 2 charm, 3 bottom): energy multipliers and relative odds. */
const HEAVY_FACTOR = [1, 4, 12, 30];
const HEAVY_ODDS = [0, 0.62, 0.3, 0.08];
const HEAVY_CODEX = ['', 'strange', 'charm', 'bottom'];

/** Quark colours (linear RGB) and the anticolours of their antiquarks. */
const QC: RGB[] = [
  [1.0, 0.17, 0.11],
  [0.2, 1.0, 0.34],
  [0.22, 0.44, 1.0],
];
const AC: RGB[] = [
  [0.16, 0.92, 1.0],
  [1.0, 0.22, 0.92],
  [1.0, 0.84, 0.14],
];

const LEPTON_CODEX = ['electron', 'muon', 'tau'];

/** The top quark's wake, from its fading tail to its head. */
const TOP_TAIL: RGB = [1.0, 0.62, 0.26];
const TOP_HEAD: RGB = [1.0, 0.9, 0.7];

const FREE_CAP = 230;
/** The view FREE_CAP was set for (16:9, in world units): the field keeps the density it gave. */
const CAP_AREA = 1778 * 1000;
/** Seconds a lepton lives: in a periodic box nothing leaves, so it fades instead. */
const LEPTON_LIFE = 2.2;
const PAIR_RADIUS = 11;

/** Confinement strings: launch speed of each end, constant tension (px/s²) and the length that breaks one. */
const TUBE_V = 210;
const TENSION = 240;
const SNAP_LEN = 128;

/**
 * Chains. The first of a click's pairs to annihilate is a link, and links each within CHAIN_WINDOW
 * seconds of the last make a chain: a click is one link however many pairs it made, so the chain
 * keeps time with the clicking. Each link past the first adds CHAIN_STEP to the energy of every
 * annihilation in the chain (the rest of its clicks' pairs too), up to CHAIN_CAP links. Spontaneous
 * and held pairs neither extend a chain nor break it.
 */
const CHAIN_WINDOW = 0.6;
const CHAIN_STEP = 0.02;
const CHAIN_CAP = 8;
/** Recent clicks, remembered by number (a pair lives about a second: this is many clicks' worth). */
const BEATS = 64;

export interface SoupState {
  quarks: number;
  photons: number;
  annihilations: number;
  pairs: number;
  baryogenesis: boolean;
  hotClock: number;
  topClock: number;
  quarkRate: number;
  photonRate: number;
  everHeld: boolean;
  everHot: boolean;
}

function defaults(): SoupState {
  return {
    quarks: 0,
    photons: 0,
    annihilations: 0,
    pairs: 0,
    baryogenesis: false,
    hotClock: 20,
    topClock: 25,
    quarkRate: 0,
    photonRate: 0,
    everHeld: false,
    everHot: false,
  };
}

interface HotSpot {
  x: number;
  y: number;
  age: number;
  life: number;
}

/** Confinement, cosmetic: a lone quark and an antiquark from the sea, tied by a string that stretches until it breaks. */
interface Tube {
  qx: number;
  qy: number;
  qvx: number;
  qvy: number;
  ax: number;
  ay: number;
  avx: number;
  avy: number;
  c: number;
  age: number;
  /** Stretched to the edge of breaking before the crack: held there until it comes. */
  taut?: boolean;
}

/** A quark and its antiquark closing into a short-lived meson (cosmetic). The quark sits at `spin`. */
interface Meson {
  x: number;
  y: number;
  vx: number;
  vy: number;
  c: number;
  sep: number;
  spin: number;
  age: number;
  life: number;
}

/** A nucleon and an antinucleon from the hadronizing sea, bound to find each other and annihilate (cosmetic). */
interface SeaPair {
  x: number;
  y: number;
  vx: number;
  vy: number;
  ax: number;
  ay: number;
  avx: number;
  avy: number;
  proton: boolean;
  rot: number;
  born: number;
  meet: number;
}

interface TopQuark {
  x: number;
  y: number;
  vx: number;
  vy: number;
  age: number;
  life: number;
}

export class SoupEra implements EraModule {
  private readonly p = new Particles(1600);
  private readonly grid = new Grid(64, 1600);
  /** The frame's field, a periodic box: what leaves one side comes back through the other. */
  private readonly box = new Torus();
  private readonly images: number[] = [];
  private readonly trailCopy = new Float32Array(40);
  private readonly fx = new FxPool(900);
  private readonly s: SoupState;
  private readonly bgParams: SoupBgParams = {
    cool: 0,
    pulse: 0,
    confine: 0,
    hotX: 0,
    hotY: 0,
    hot: 0,
    dens: new Float32Array(DENS_W * DENS_H),
    densW: 889,
    densH: 500,
    heat: new Float32Array(HEAT_MAX * 4),
  };
  /** Visual only: the plasma's heat events (x, y, time, strength) as a ring, and per-cell matter counts. */
  private readonly heatEv = new Float32Array(HEAT_MAX * 4);
  private heatNext = 0;
  /** How it all looks (version 2): the plasma, the storm of specks, the filaments, the effects. */
  private readonly look = new SoupLook();
  /** Protons, neutrons, their antiparticles and mesons, drawn in that look. */
  private readonly hadrons = new Hadrons(this.look);
  private halfW = 889;
  private halfH = 500;
  private t = 0;
  private idle = 0;
  private clicks = 0;

  private pairsPerClick = 1;
  private thermalRate = 0;
  private annMult = 1;
  private asym = 0;
  private heavyChance = 0;
  private heavyMult = 1;
  private hotRate = 0;
  private color = 0;
  private stream = 0;
  private topMult = 1;

  private thermalAcc = 0;
  private streamAcc = 0;
  private pDown = false;
  private pX = 0;
  private pY = 0;
  private freeCheck = 0;
  private readonly quarkMeter = new RateMeter(20);
  private readonly photonMeter = new RateMeter(20);
  private hot: HotSpot | null = null;
  private top: TopQuark | null = null;
  private bonds: number[] = [];
  private unsub: (() => void)[] = [];
  /** Chains (see CHAIN_WINDOW). Clicks are numbered, and each pair carries its click's number in `b`. */
  private beat = 0;
  private readonly beatChain = new Uint32Array(BEATS);
  private chainId = 0;
  private chain = 0;
  private chainT = -Infinity;
  private chainX = 0;
  private chainY = 0;
  /** Visual only: where the chain's label sits, easing toward its latest link. */
  private labelX = 0;
  private labelY = 0;

  private intro = 0;
  /** Visual only: the top quark's recent path (x, y pairs, newest last) and ambient glint timer. */
  private topTrail: number[] = [];
  private readonly trailCore = new Float32Array(18);
  private readonly trailSheath = new Float32Array(18);
  private finaleT = -1;
  private finaleDone: (() => void) | null = null;
  private snapped = false;
  private tallied = false;
  /** Confinement: red-green-blue triplets (stable ids) and when each starts pulling together. */
  private triplets: { ids: [number, number, number]; start: number }[] = [];
  private tripletsBuilt = false;
  /** Confinement, cosmetic: lone quarks waiting for their string, strings, mesons, and the nucleon–antinucleon sea. */
  private loners: { id: number; start: number }[] = [];
  private tubes: Tube[] = [];
  private mesons: Meson[] = [];
  private sea: SeaPair[] = [];

  constructor(private readonly g: Game) {
    const run = g.state.run;
    this.s = (run.eras.soup as SoupState | undefined) ?? defaults();
    run.eras.soup = this.s;
  }

  // ───────────────────────────────────────── lifecycle

  enter(fresh: boolean): void {
    const g = this.g;
    if (g.renderer) this.look.attach(g.renderer);
    this.refreshStats();
    this.unsub.push(g.stats.onChange(() => this.refreshStats()));
    this.unsub.push(g.bus.on('buy', () => this.checkBaryogenesis()));
    this.quarkMeter.reset(this.s.quarkRate);
    this.photonMeter.reset(this.s.photonRate);
    this.syncStepFlags();
    this.bgParams.cool = g.state.run.step / 6;
    this.look.cooling = this.bgParams.cool;
    // Resuming: re-sample the visible matter from the stock.
    if (!fresh) this.sampleFree();
    if (fresh) {
      this.intro = INTRO;
      this.bgParams.pulse = 1;
      g.renderer?.shock(0, 0, 0.5, 0.8, 1.6);
    }
  }

  exit(): void {
    if (this.g.renderer) this.look.detach(this.g.renderer);
    for (const u of this.unsub) u();
    this.unsub = [];
  }

  resize(halfW: number, halfH: number): void {
    this.halfW = halfW;
    this.halfH = halfH;
    // The era plays in the frame's field, a periodic box: what leaves one side comes back in through the
    // other, the way a simulation stands a finite box in for endless, uniform space.
    this.box.set(halfW, halfH);
    this.grid.setBounds(-halfW, -halfH, halfW, halfH, true);
    const p = this.p;
    for (let i = 0; i < p.n; i++) {
      p.x[i] = this.box.wrapX(p.x[i]);
      p.y[i] = this.box.wrapY(p.y[i]);
    }
  }

  /** How many free quarks are shown: as dense in the field as FREE_CAP was over the whole view. */
  /**
   * The free quarks the stock stands for, drawn into the field up to what it shows (at a resume, and when
   * the development skip sets the stock a finale needs).
   */
  sampleFree(): void {
    if (this.s.quarks <= 0) return;
    const p = this.p;
    let have = 0;
    for (let i = 0; i < p.n; i++) if (p.kind[i] === FREE && !p.isDead(i)) have++;
    const n = Math.min(this.freeCap, Math.floor(40 + Math.log10(1 + this.s.quarks) * 18)) - have;
    const rng = this.g.sim;
    for (let k = 0; k < n; k++) {
      const i = p.spawn(FREE, rng.range(-this.box.hx, this.box.hx), rng.range(-this.box.hy, this.box.hy), 0, 0, PAIR_RADIUS, 1, rng.int(3));
      if (i >= 0) p.b[i] = 1;
    }
  }

  private get freeCap(): number {
    return Math.max(40, Math.round((FREE_CAP * this.box.area) / CAP_AREA));
  }

  private refreshStats(): void {
    const st = this.g.stats;
    this.pairsPerClick = st.get('soup.pairsPerClick');
    this.thermalRate = st.get('soup.thermalRate');
    this.annMult = st.get('soup.annihilationMult');
    this.asym = st.get('soup.asymmetry');
    this.heavyChance = st.get('soup.heavyChance');
    this.heavyMult = st.get('soup.heavyMult');
    this.hotRate = st.get('soup.hotspotRate');
    this.color = st.get('soup.color');
    this.stream = st.get('soup.stream');
    this.topMult = st.get('soup.topMult');
  }

  private get weight(): number {
    return 10 ** this.g.state.run.step;
  }

  private syncStepFlags(): void {
    const step = this.g.state.run.step;
    for (let i = 1; i <= 6; i++) this.g.setFlag(`soup.step${i}`, step >= i);
  }

  private checkBaryogenesis(): void {
    const g = this.g;
    if (this.s.baryogenesis) return;
    if (g.level('soup.sphalerons') > 0 && g.level('soup.cp') > 0 && g.state.run.step >= 2) {
      this.s.baryogenesis = true;
      g.setFlag('soup.baryogenesis');
      g.sfx('soup.baryogenesis');
      g.renderer?.addFlash(0.35);
      g.renderer?.shock(0, 0, 0.5, 0.6, 2);
      this.bgParams.pulse = 0.6;
      const oneIn = Math.round(1 / Math.max(this.asym, 1e-6));
      g.toast(
        `Baryogenesis. For every ${oneIn} antiquarks, ${oneIn + 1} quarks. The leftovers are all the ordinary matter there will ever be.`,
        'milestone',
      );
    }
  }

  // ───────────────────────────────────────── actions

  /**
   * Condense `n` pairs at (x, y). Visible pairs are capped; the rest ride on their weight. `beat` is
   * the number of the click that made them (0 for any other pairs), for chains.
   */
  private condense(x: number, y: number, n: number, manual: boolean, burst = false, beat = 0): void {
    const g = this.g;
    const rng = g.sim;
    const room = Math.floor((this.p.cap - 260 - this.p.n) / 2);
    if (room <= 0 || n <= 0) {
      // Saturated screen: the event still happens, just off-screen.
      this.offscreenPairs(n);
      return;
    }
    const maxVisible = burst ? 40 : manual ? 10 : 5;
    const visible = Math.max(1, Math.min(Math.ceil(n), room, maxVisible));
    const wEach = (this.weight * n) / visible;
    for (let k = 0; k < visible; k++) {
      const color = rng.int(3);
      let heavy = 0;
      if (this.heavyChance > 0 && rng.chance(this.heavyChance)) {
        const r = rng.next();
        heavy = r < HEAVY_ODDS[1] ? 1 : r < HEAVY_ODDS[1] + HEAVY_ODDS[2] ? 2 : 3;
      }
      const ang = rng.angle();
      const speed = (burst ? 260 : 170) + rng.range(0, 120);
      const cx = Math.cos(ang) * speed;
      const cy = Math.sin(ang) * speed;
      const ox = x + rng.range(-4, 4);
      const oy = y + rng.range(-4, 4);
      const r = heavy ? PAIR_RADIUS + 2 : PAIR_RADIUS;
      const qi = this.p.spawn(QUARK, ox, oy, cx, cy, r, wEach, color);
      const ai = this.p.spawn(ANTI, ox, oy, -cx, -cy, r, wEach, color);
      if (qi < 0 || ai < 0) break;
      this.p.link[qi] = this.p.id[ai];
      this.p.link[ai] = this.p.id[qi];
      this.p.a[qi] = heavy;
      this.p.a[ai] = heavy;
      this.p.b[qi] = beat;
      this.p.b[ai] = beat;
      if (manual) {
        this.p.flags[qi] |= F_MANUAL;
        this.p.flags[ai] |= F_MANUAL;
      }
      if (this.s.baryogenesis && rng.chance(this.asym)) this.p.life[ai] = rng.range(0.22, 0.5);
    }
    this.s.pairs += n * this.weight;
    this.maybeLeptons(x, y);
    if (manual || burst) {
      // Energy gathers to a point and condenses: a ring that closes in, a hard white spark, a soft burst.
      this.fx.spawn(Fx.Ring, x, y, 0.16, burst ? 120 : 64, 1.1, 1.3, 2.0, burst ? -700 : -380);
      this.fx.spawn(Fx.Flash, x, y, 0.14, 9, 5, 5.4, 6.4, 40);
      this.fx.spawn(Fx.Ring, x, y, 0.3, 6, 0.8, 0.95, 1.5, burst ? 420 : 220);
      g.sfx('soup.condense', x, burst ? 1.4 : 1);
    }
    if (!g.isDiscovered('up')) {
      g.discover('up');
      g.discover('down');
    }
  }

  /** Pairs that happen while the screen is saturated: credited by expectation. */
  private offscreenPairs(n: number): void {
    const w = this.weight * n;
    const e = E0 * w * this.annMult * (1 + this.heavyChance * 4 * this.heavyMult);
    this.g.gain(e);
    this.s.annihilations += w;
    this.s.photons += 2 * w;
    this.photonMeter.add(2 * w);
    if (this.s.baryogenesis) {
      const q = w * this.asym;
      this.s.quarks += q;
      this.quarkMeter.add(q);
    }
    this.s.pairs += w;
  }

  /** Lepton pairs ride along with some condensations. Their discoveries are state, so the draws are too. */
  private maybeLeptons(x: number, y: number): void {
    const g = this.g;
    const rng = g.sim;
    const step = g.state.run.step;
    let species = -1;
    const r = rng.next();
    if (step >= 2 && g.level('soup.flavours') > 0 && r < 0.0016) species = 2;
    else if (step >= 1 && r < 0.009) species = 1;
    else if (r < 0.045) species = 0;
    if (species < 0) return;
    const ang = rng.angle();
    for (const sign of [1, -1]) {
      const i = this.p.spawn(LEPTON, x, y, Math.cos(ang) * 620 * sign, Math.sin(ang) * 620 * sign, 4, 0, species * 2 + (sign > 0 ? 0 : 1));
      if (i < 0) return;
      this.p.b[i] = rng.range(-1.6, 1.6);
    }
    if (g.discover(LEPTON_CODEX[species])) g.sfx('soup.lepton', x);
  }

  private annihilate(qi: number, ai: number): void {
    const p = this.p;
    const g = this.g;
    const w = p.w[qi];
    const heavy = p.a[qi] | 0;
    const factor = heavy ? HEAVY_FACTOR[heavy] * this.heavyMult : 1;
    const x = (p.x[qi] + p.x[ai]) * 0.5;
    const y = (p.y[qi] + p.y[ai]) * 0.5;
    const links = Math.max(0, Math.min(this.chainLink(p.b[qi], x, y) - 1, CHAIN_CAP));
    const e = E0 * w * this.annMult * factor * (1 + CHAIN_STEP * links);
    if (p.flags[qi] & F_MANUAL) g.gain(e, x, y);
    else g.gain(e);
    this.s.annihilations += w;
    this.s.photons += 2 * w;
    this.photonMeter.add(2 * w);
    const c = QC[p.sub[qi]];
    p.kill(qi);
    p.kill(ai);
    // Two photons, back to back.
    const ang = g.fx.angle();
    const sp = 1300;
    const k = heavy ? 1.7 : 1;
    // Two photons, back to back: wave packets racing apart.
    this.fx.spawn(Fx.Photon, x, y, 0.26, 5 * k, 4, 4.4, 5.2, 0, Math.cos(ang) * sp, Math.sin(ang) * sp);
    this.fx.spawn(Fx.Photon, x, y, 0.26, 5 * k, 4, 4.4, 5.2, 0, -Math.cos(ang) * sp, -Math.sin(ang) * sp);
    // A crisp white-hot point, a short colored bloom, a fast thin ring, and light left in the bath
    // (the plasma itself warms there). A chain makes each one a little brighter and wider.
    const ch = links / CHAIN_CAP;
    const kb = k * (1 + 0.5 * ch);
    const kr = k * (1 + 0.7 * ch);
    this.fx.spawn(Fx.Flash, x, y, 0.12, 12 * k * (1 + 0.25 * ch), 9 * kb, 9.4 * kb, 10 * kb, 30);
    this.fx.spawn(Fx.Flash, x, y, 0.3, 22 * k * (1 + 0.4 * ch), (0.6 + 2.4 * c[0]) * kb, (0.6 + 2.4 * c[1]) * kb, (0.8 + 2.4 * c[2]) * kb, 90);
    this.fx.spawn(Fx.Ring, x, y, 0.24 * (1 + 0.3 * ch), 8, 0.8 * kr, 0.95 * kr, 1.3 * kr, 280 * k * (1 + 0.3 * ch));
    this.addHeat(x, y, 0.8 * kb);
    if (heavy) {
      g.sfx('soup.heavy', x, 1, p.sub[qi]);
      g.discover(HEAVY_CODEX[heavy]);
    } else g.sfx('soup.annihilate', x, 1, p.sub[qi]);
    g.discover('photon');
  }

  /**
   * An annihilation at (x, y) of a pair from click number `beat` (0: not a clicked pair, which leaves
   * any chain alone). Returns the chain's length, counting this one.
   */
  private chainLink(beat: number, x: number, y: number): number {
    if (!beat) return 0;
    const slot = beat % BEATS;
    const live = this.t - this.chainT <= CHAIN_WINDOW;
    if (this.beatChain[slot] === 0) {
      // The first of this click's pairs home: the next link if it came in time, else a new chain.
      if (!live) {
        this.chain = 0;
        this.chainId++;
        this.labelX = x;
        this.labelY = y;
      }
      this.beatChain[slot] = this.chainId;
      this.chain++;
      this.chainT = this.t;
      this.chainX = x;
      this.chainY = y;
      if (this.chain >= 2) this.g.sfx('soup.combo', x, this.chain);
      return this.chain;
    }
    // The rest of a linked click's pairs share in its chain while the chain lives.
    return live && this.beatChain[slot] === this.chainId ? this.chain : 0;
  }

  /** Numbers a new click (its slot is cleared: it has joined no chain yet). */
  private nextBeat(): number {
    this.beat++;
    this.beatChain[this.beat % BEATS] = 0;
    return this.beat;
  }

  /** Charge-parity violation, in miniature: the antiquark is lost before reunion, leaving its quark as surviving matter. */
  private decayAnti(ai: number): void {
    const p = this.p;
    const g = this.g;
    const qi = p.find(p.link[ai]);
    const w = p.w[ai];
    const x = p.x[ai];
    const y = p.y[ai];
    const c = AC[p.sub[ai]];
    p.kill(ai);
    g.gain(E0 * 0.3 * w * this.annMult);
    this.fx.spawn(Fx.Ring, x, y, 0.3, 4, c[0], c[1], c[2], 60);
    for (let k = 0; k < 3; k++) {
      const a = g.fx.angle();
      this.fx.spawn(Fx.Spark, x, y, 0.25, 2.5, c[0] * 1.5, c[1] * 1.5, c[2] * 1.5, 0, Math.cos(a) * 300, Math.sin(a) * 300);
    }
    if (qi >= 0) {
      p.kind[qi] = FREE;
      p.link[qi] = 0;
      p.flags[qi] &= ~F_MANUAL;
      p.b[qi] = 0;
      this.s.quarks += w;
      this.quarkMeter.add(w);
      this.fx.spawn(Fx.Flash, p.x[qi], p.y[qi], 0.4, 14, QC[p.sub[qi]][0] * 2, QC[p.sub[qi]][1] * 2, QC[p.sub[qi]][2] * 2, 10);
    }
    g.sfx('soup.decay', x);
  }

  /** Leave a bloom of heat in the plasma (visual only). */
  private addHeat(x: number, y: number, strength: number): void {
    const o = this.heatNext * 4;
    this.heatEv[o] = x;
    this.heatEv[o + 1] = y;
    this.heatEv[o + 2] = this.t;
    this.heatEv[o + 3] = strength;
    this.heatNext = (this.heatNext + 1) % HEAT_MAX;
  }

  // ───────────────────────────────────────── events

  private updateEvents(dt: number): void {
    const g = this.g;
    const rng = g.sim;
    if (this.hotRate > 0 && !this.hot && this.finaleT < 0) {
      this.s.hotClock -= dt;
      if (this.s.hotClock <= 0) {
        this.s.hotClock = Math.max(6, rng.exp(60 / this.hotRate));
        // Inside the field, clear of the margins' text: it asks to be clicked.
        const F = fieldHalf(this.halfW, this.halfH);
        this.hot = {
          x: rng.range(-F + 90, F - 90),
          y: rng.range(-F + 90, F - 90),
          age: 0,
          life: 9,
        };
        g.sfx('soup.hotspot', this.hot.x);
      }
    }
    if (this.hot) {
      this.hot.age += dt;
      if (this.hot.age >= this.hot.life) this.hot = null;
    }
    if (g.level('soup.flavours') >= 2 && !this.top && this.finaleT < 0) {
      this.s.topClock -= dt;
      if (this.s.topClock <= 0) {
        this.s.topClock = Math.max(20, rng.exp(75));
        const fromLeft = rng.chance(0.5);
        // In at the view's edge and across the field, where it can be seen and caught.
        const F = fieldHalf(this.halfW, this.halfH);
        const y = rng.range(-F * 0.6, F * 0.6);
        this.top = {
          x: fromLeft ? -this.box.hx : this.box.hx,
          y,
          vx: (fromLeft ? 1 : -1) * rng.range(150, 210),
          vy: rng.range(-40, 40),
          age: 0,
          life: 8,
        };
        g.sfx('soup.top', this.top.x);
      }
    }
    if (this.top) {
      const tq = this.top;
      tq.age += dt;
      const wx = this.box.wrapX(tq.x + tq.vx * dt);
      const wy = this.box.wrapY(tq.y + tq.vy * dt);
      // Through an edge and in at the other: its wake starts again there.
      if (Math.abs(wx - tq.x) > this.box.hx || Math.abs(wy - tq.y) > this.box.hy) this.topTrail.length = 0;
      tq.x = wx;
      tq.y = wy;
      if (g.fx.chance(dt * 30)) {
        const a = g.fx.angle();
        this.fx.spawn(Fx.Spark, tq.x, tq.y, 0.4, 2.5, 2.5, 2.0, 1.2, 0, Math.cos(a) * 80 - tq.vx * 0.3, Math.sin(a) * 80 - tq.vy * 0.3, 2);
      }
      if (tq.age >= tq.life) {
        this.fx.spawn(Fx.Flash, tq.x, tq.y, 0.4, 30, 2.5, 2, 1.2, 40);
        this.fx.spawn(Fx.Ring, tq.x, tq.y, 0.4, 10, 1.2, 0.95, 0.55, 260);
        this.top = null;
        this.topTrail.length = 0;
      }
    }
  }

  private burstHotSpot(h: HotSpot): void {
    const g = this.g;
    this.hot = null;
    this.s.everHot = true;
    this.condense(h.x, h.y, 15 * this.pairsPerClick, true, true, this.nextBeat());
    g.gain(E0 * this.weight * this.annMult * 10 * this.pairsPerClick, h.x, h.y);
    g.renderer?.addFlash(0.25);
    g.renderer?.shock(h.x, h.y, 0.55, 0.8, 1.1);
    g.renderer?.camera.addTrauma(0.18);
    this.bgParams.pulse = Math.min(1, this.bgParams.pulse + 0.4);
    this.fx.spawn(Fx.Flash, h.x, h.y, 0.5, 60, 6, 6.4, 7.5, 160);
    this.addHeat(h.x, h.y, 2.5);
    this.fx.spawn(Fx.Ring, h.x, h.y, 0.6, 30, 1.6, 1.8, 2.4, 700);
    for (let k = 0; k < 18; k++) {
      const a = g.fx.angle();
      const s = g.fx.range(300, 900);
      const c = QC[k % 3];
      this.fx.spawn(Fx.Spark, h.x, h.y, 0.5, 4, 1 + c[0] * 3, 1 + c[1] * 3, 1 + c[2] * 3, 0, Math.cos(a) * s, Math.sin(a) * s, 3);
    }
    g.sfx('soup.burst', h.x);
  }

  private catchTop(tq: TopQuark): void {
    const g = this.g;
    this.top = null;
    const e = E0 * this.weight * this.annMult * 60 * this.topMult * Math.max(1, this.pairsPerClick);
    g.gain(e, tq.x, tq.y);
    g.discover('top');
    g.renderer?.addFlash(0.3);
    g.renderer?.shock(tq.x, tq.y, 0.7, 0.9, 1.2);
    g.renderer?.addAberration(0.004);
    g.renderer?.camera.addTrauma(0.22);
    for (let k = 0; k < 14; k++) {
      const a = g.fx.angle();
      const s = g.fx.range(200, 700);
      this.fx.spawn(Fx.Spark, tq.x, tq.y, 0.6, 3, 2.6, 2.1, 1.3, 0, Math.cos(a) * s, Math.sin(a) * s, 2.5);
    }
    this.fx.spawn(Fx.Flash, tq.x, tq.y, 0.5, 50, 4, 3.4, 2.2, 80);
    this.addHeat(tq.x, tq.y, 2.5);
    this.fx.spawn(Fx.Flash, tq.x, tq.y, 0.15, 16, 12, 11, 9, 60);
    this.fx.spawn(Fx.Ring, tq.x, tq.y, 0.55, 20, 2.4, 1.9, 1.1, 600);
    this.topTrail.length = 0;
    g.sfx('soup.top.catch', tq.x);
  }

  // ───────────────────────────────────────── simulation

  update(dt: number): void {
    const g = this.g;
    this.t += dt;
    this.idle += dt;
    const p = this.p;
    const inFinale = this.finaleT >= 0;
    // Once confinement starts the era's numbers are settled, so the jitter draws on the cosmetic stream.
    const rng = inFinale ? g.fx : g.sim;

    if (!inFinale) {
      this.thermalAcc += this.thermalRate * dt;
      if (this.thermalAcc >= 1) {
        const n = Math.floor(this.thermalAcc);
        this.thermalAcc -= n;
        // Spread spontaneous pairs over a few random spots.
        const spots = Math.min(n, 3);
        for (let k = 0; k < spots; k++) {
          this.condense(rng.range(-this.box.hx, this.box.hx), rng.range(-this.box.hy, this.box.hy), n / spots, false);
        }
      }
      if (this.pDown && this.stream > 0) {
        this.streamAcc += this.stream * dt;
        if (this.streamAcc >= 1) {
          const n = Math.floor(this.streamAcc);
          this.streamAcc -= n;
          this.condense(this.pX, this.pY, n * this.pairsPerClick, true);
          this.s.everHeld = true;
        }
      }
      this.updateEvents(dt);
    } else {
      this.updateFinale(dt);
    }

    // Forces and integration.
    const sq = Math.sqrt(dt);
    const box = this.box;
    const colorForce = inFinale ? 0 : this.color;
    if (colorForce > 0) this.grid.build(p);
    this.bonds.length = 0;

    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const kind = p.kind[i];
      p.age[i] += dt;
      if (kind === LEPTON) {
        // Fast and nearly free; curl gently like tracks in a bubble chamber.
        const curl = p.b[i] * dt;
        const vx = p.vx[i];
        p.vx[i] = vx * Math.cos(curl) - p.vy[i] * Math.sin(curl);
        p.vy[i] = vx * Math.sin(curl) + p.vy[i] * Math.cos(curl);
        p.x[i] = box.wrapX(p.x[i] + p.vx[i] * dt);
        p.y[i] = box.wrapY(p.y[i] + p.vy[i] * dt);
        if (p.age[i] > LEPTON_LIFE) p.kill(i);
        continue;
      }
      if (kind === BARYON) {
        p.vx[i] *= Math.exp(-2 * dt);
        p.vy[i] *= Math.exp(-2 * dt);
        p.x[i] = box.wrapX(p.x[i] + p.vx[i] * dt);
        p.y[i] = box.wrapY(p.y[i] + p.vy[i] * dt);
        continue;
      }
      if (p.flags[i] & F_FADE) {
        p.life[i] -= dt;
        if (p.life[i] <= 0) {
          p.kill(i);
          continue;
        }
      }
      const isFree = kind === FREE;
      if (isFree && p.b[i] < 1) p.b[i] = Math.min(1, p.b[i] + dt * 1.4);
      const sigma = isFree ? 42 : 95;
      let ax = rng.gauss() * sigma / sq;
      let ay = rng.gauss() * sigma / sq;
      // Pair partners attract after a moment of free flight.
      if (!isFree && p.link[i]) {
        const j = p.find(p.link[i]);
        if (j >= 0) {
          if (p.age[i] > 0.12) {
            const k = inFinale ? 40 : 7;
            ax += box.dx(p.x[j] - p.x[i]) * k;
            ay += box.dy(p.y[j] - p.y[i]) * k;
          }
        } else if (kind === QUARK) {
          // Partner vanished without decaying (shouldn't happen): treat as freed.
          p.link[i] = 0;
        }
      }
      if (isFree && colorForce > 0) {
        const xi = p.x[i];
        const yi = p.y[i];
        const ci = p.sub[i];
        this.grid.near(xi, yi, 80, (j) => {
          if (j <= i || p.kind[j] !== FREE || p.isDead(j)) return;
          const dx = box.dx(p.x[j] - xi);
          const dy = box.dy(p.y[j] - yi);
          const d2 = dx * dx + dy * dy;
          if (d2 > 6400 || d2 < 1e-4) return;
          const d = Math.sqrt(d2);
          const same = p.sub[j] === ci;
          let f = same ? -colorForce * 14 * (1 - d / 80) : colorForce * 28 * (1 - d / 80);
          if (d < 16) f -= 90 * (1 - d / 16);
          const fx = (dx / d) * f;
          const fy = (dy / d) * f;
          p.vx[i] += fx * dt;
          p.vy[i] += fy * dt;
          p.vx[j] -= fx * dt;
          p.vy[j] -= fy * dt;
          if (!same && d < 62 && this.bonds.length < 480) this.bonds.push(p.id[i], p.id[j]);
        });
      }
      const drag = Math.exp(-(isFree ? 2.4 : 1.15) * dt);
      p.vx[i] = (p.vx[i] + ax * dt) * drag;
      p.vy[i] = (p.vy[i] + ay * dt) * drag;
      p.x[i] = box.wrapX(p.x[i] + p.vx[i] * dt);
      p.y[i] = box.wrapY(p.y[i] + p.vy[i] * dt);
    }

    // Collisions, decays.
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const kind = p.kind[i];
      if (kind === ANTI && p.life[i] !== Infinity) {
        p.life[i] -= dt;
        if (p.life[i] <= 0) {
          this.decayAnti(i);
          continue;
        }
      }
      if (kind === QUARK && p.link[i]) {
        const j = p.find(p.link[i]);
        if (j < 0) continue;
        const dx = box.dx(p.x[j] - p.x[i]);
        const dy = box.dy(p.y[j] - p.y[i]);
        const rr = (p.r[i] + p.r[j]) * 0.8;
        if (p.age[i] > 0.08 && dx * dx + dy * dy < rr * rr) this.annihilate(i, j);
      }
    }

    // Keep the visible sample of free matter bounded (the stock itself is never touched).
    this.freeCheck -= dt;
    if (this.freeCheck <= 0) {
      this.freeCheck = 0.4;
      let free = 0;
      for (let i = 0; i < p.n; i++) if (p.kind[i] === FREE && !(p.flags[i] & F_FADE) && !p.isDead(i)) free++;
      let excess = free - this.freeCap;
      for (let i = 0; i < p.n && excess > 0; i++) {
        if (p.kind[i] === FREE && !(p.flags[i] & F_FADE) && !p.isDead(i)) {
          p.flags[i] |= F_FADE;
          p.life[i] = 1.2;
          excess--;
        }
      }
      if (this.color > 0 && free > 6 && !g.isDiscovered('gluon')) g.discover('gluon');
    }

    if (this.intro > 0) this.intro = Math.max(0, this.intro - dt);
    const ease = 1 - Math.exp(-dt * 10);
    this.labelX += (this.chainX - this.labelX) * ease;
    this.labelY += (this.chainY - this.labelY) * ease;
    p.compact();
    this.fx.update(dt);
    this.quarkMeter.tick(dt);
    this.photonMeter.tick(dt);
    this.s.quarkRate = this.quarkMeter.rate;
    this.s.photonRate = this.photonMeter.rate;
    this.bgParams.pulse *= Math.exp(-dt * 2.5);
  }

  // ───────────────────────────────────────── steps

  onStep(index: number): void {
    const g = this.g;
    const r = g.renderer;
    this.syncStepFlags();
    this.bgParams.cool = index / 6;
    this.look.cooling = this.bgParams.cool;
    this.bgParams.pulse = Math.min(1, this.bgParams.pulse + 0.5);
    r?.camera.breathe(0.05, 1.5);
    // Space expands: everything is carried outward a little.
    const p = this.p;
    for (let i = 0; i < p.n; i++) {
      p.vx[i] += p.x[i] * 0.55;
      p.vy[i] += p.y[i] * 0.55;
    }
    if (index === 2) {
      // The Higgs field settles: particles gain mass and visibly slow down.
      for (let i = 0; i < p.n; i++) {
        p.vx[i] *= 0.3;
        p.vy[i] *= 0.3;
      }
      g.discover('higgs');
      g.discover('w-boson');
      g.discover('z-boson');
      g.sfx('soup.higgs');
      r?.shock(0, 0, 0.9, 0.55, 2.4);
      r?.addFlash(0.2);
    }
    this.checkBaryogenesis();
  }

  // ───────────────────────────────────────── finale: confinement

  finale(): Promise<void> {
    const g = this.g;
    const s = this.s;
    const run = g.state.run;
    const eff = g.stats.get('soup.tripletEfficiency');
    const baryons = (s.quarks * eff) / 3;
    const pFrac = 0.5 + (g.sim.next() - 0.5) * 0.04;
    run.legacy.baryons = baryons;
    run.legacy.protons = baryons * pFrac;
    run.legacy.neutrons = baryons * (1 - pFrac);
    run.legacy.eta = baryons / Math.max(1, s.photons);
    run.legacy.tripletEfficiency = eff;
    this.finaleT = 0;
    this.hot = null;
    this.top = null;
    g.sfx('soup.cooling');
    return new Promise((resolve) => {
      this.finaleDone = resolve;
    });
  }

  private updateFinale(dt: number): void {
    const g = this.g;
    const p = this.p;
    this.finaleT += dt;
    const t = this.finaleT;
    // A crossover, not a sudden change of phase: the whole plasma cools and thins together, through the
    // music's whole climb.
    const k = 1 - Math.min(1, t / (F_SNAP - 1.2));
    this.bgParams.confine = 1 - k * k;
    if (t > F_BUILD && !this.tripletsBuilt) this.buildTriplets();
    if (t > F_BUILD && t < F_SNAP) this.pullTriplets(dt, t);
    this.breakStrings(dt, t);
    this.updateMesons(dt);
    this.updateSea(dt, t);
    if (t >= F_SNAP && !this.snapped) {
      this.snapped = true;
      // Any color charge still alone now (a straggler) closes into a meson on the spot.
      let left = 0;
      for (let i = 0; i < p.n; i++) {
        if (p.isDead(i) || (p.kind[i] !== FREE && p.kind[i] !== QUARK && p.kind[i] !== ANTI)) continue;
        this.mesons.push({ x: p.x[i], y: p.y[i], vx: p.vx[i] * 0.3, vy: p.vy[i] * 0.3, c: p.sub[i], sep: 22, spin: g.fx.angle(), age: 0, life: g.fx.range(0.4, 0.8) });
        p.kill(i);
        left++;
      }
      if (left > 0) g.sfx('soup.snap');
      g.discover('nu-e');
      g.discover('nu-mu');
      if (g.isDiscovered('tau')) g.discover('nu-tau');
      g.discover('confinement');
    }
    if (t >= F_SURVIVORS && !this.tallied) {
      this.tallied = true;
      const run = g.state.run;
      g.sfx('soup.confined');
      // The moment lands: the whole frame lifts (the flash budget and Reduce flashes hold it in check).
      g.renderer?.addFlash(0.6);
      g.renderer?.shock(0, 0, 0.8, 0.7, 2.2);
      // The survivors: every nucleon still standing once the antimatter is gone (each flares white-hot
      // where it is drawn, not through the plasma: thirty flashes' light there would fog it).
      for (let i = 0; i < p.n; i++) {
        if (p.kind[i] !== BARYON || p.isDead(i)) continue;
        this.fx.spawn(Fx.Ring, p.x[i], p.y[i], 0.8, 15, 0.6, 0.57, 0.5, 60);
        this.fx.spawn(Fx.Flash, p.x[i], p.y[i], 0.5, 18, 1.6, 1.5, 1.35, 20);
      }
      g.toast(
        `Confinement. ${toText(count(run.legacy.baryons))} protons and neutrons. Matter per photon: ${toText(decimal(run.legacy.eta, 2))}.`,
        'milestone',
      );
    }
    if (this.tallied) {
      // Space keeps expanding: the survivors drift slowly apart.
      for (let i = 0; i < p.n; i++) {
        if (p.kind[i] !== BARYON) continue;
        p.vx[i] += p.x[i] * 0.12 * dt;
        p.vy[i] += p.y[i] * 0.12 * dt;
      }
    }
    if (t >= F_DONE && this.finaleDone) {
      const done = this.finaleDone;
      this.finaleDone = null;
      done();
    }
  }

  /**
   * Greedy matching: for each quark of the rarest colour, its nearest partners of the other two. The
   * quarks left over wait for their strings to break, and the cooling plasma makes nucleon–antinucleon
   * pairs (fewer than the survivors here, so the screen stays readable; really a billion for each).
   */
  private buildTriplets(): void {
    const p = this.p;
    const fxr = this.g.fx;
    this.tripletsBuilt = true;
    const byColor: number[][] = [[], [], []];
    for (let i = 0; i < p.n; i++) {
      if (p.kind[i] === FREE && !p.isDead(i) && !(p.flags[i] & F_FADE)) byColor[p.sub[i]].push(i);
    }
    const order = [0, 1, 2].sort((a, b) => byColor[a].length - byColor[b].length);
    const used = new Set<number>();
    const d2 = (a: number, b: number) => (p.x[a] - p.x[b]) ** 2 + (p.y[a] - p.y[b]) ** 2;
    // Partners farther than this are too far to bind: those quarks are left to break their strings.
    const reach = 210 * 210;
    for (const i of byColor[order[0]]) {
      let j = -1;
      let best = Infinity;
      for (const c of byColor[order[1]]) {
        if (used.has(c)) continue;
        const d = d2(i, c);
        if (d < best && d < reach) {
          best = d;
          j = c;
        }
      }
      if (j < 0) continue;
      let k = -1;
      best = Infinity;
      for (const c of byColor[order[2]]) {
        if (used.has(c)) continue;
        const d = d2(i, c) + d2(j, c);
        if (d < best && d < 2 * reach) {
          best = d;
          k = c;
        }
      }
      if (k < 0) continue;
      used.add(i);
      used.add(j);
      used.add(k);
      // Spread over the climb, crowding toward its top: more and more lock in as the strings rise.
      this.triplets.push({ ids: [p.id[i], p.id[j], p.id[k]], start: F_BUILD + 0.5 + (F_SNAP - F_BUILD - 2.5) * Math.sqrt(fxr.next()) });
    }
    for (const list of byColor) {
      for (const i of list) if (!used.has(i)) this.loners.push({ id: p.id[i], start: F_BUILD + 1 + fxr.range(0, F_SNAP - F_BUILD - 3) });
    }
    const pairs = Math.max(8, Math.min(20, Math.round(this.triplets.length * 0.7)));
    for (let n = 0; n < pairs; n++) {
      const x = fxr.range(-this.box.hx, this.box.hx) * 0.86;
      const y = fxr.range(-this.box.hy, this.box.hy) * 0.86;
      const a = fxr.angle();
      const d = fxr.range(30, 55);
      const drift = fxr.angle();
      const sp = fxr.range(8, 22);
      this.sea.push({
        x: x + Math.cos(a) * d,
        y: y + Math.sin(a) * d,
        vx: Math.cos(drift) * sp,
        vy: Math.sin(drift) * sp,
        ax: x - Math.cos(a) * d,
        ay: y - Math.sin(a) * d,
        avx: -Math.cos(drift) * sp,
        avy: -Math.sin(drift) * sp,
        proton: fxr.chance(0.5),
        rot: fxr.angle(),
        // The last antimatter: drawn out as the strings snap, meeting its matter on the boom.
        born: F_SNAP - 1 + fxr.range(0, 1.8),
        meet: F_BOOM - 0.45 + fxr.range(0, 0.8),
      });
    }
  }

  /** Each triplet's quarks are drawn to their common centre and lock into a nucleon. */
  private pullTriplets(dt: number, t: number): void {
    const p = this.p;
    const g = this.g;
    for (let n = this.triplets.length - 1; n >= 0; n--) {
      const tr = this.triplets[n];
      if (t < tr.start) continue;
      const a = p.find(tr.ids[0]);
      const b = p.find(tr.ids[1]);
      const c = p.find(tr.ids[2]);
      if (a < 0 || b < 0 || c < 0) {
        this.triplets.splice(n, 1);
        continue;
      }
      // Their common centre, through the wrap (they may lie across an edge of the field).
      const box = this.box;
      const cx = box.wrapX(p.x[a] + (box.dx(p.x[b] - p.x[a]) + box.dx(p.x[c] - p.x[a])) / 3);
      const cy = box.wrapY(p.y[a] + (box.dy(p.y[b] - p.y[a]) + box.dy(p.y[c] - p.y[a])) / 3);
      const k = 6 + 30 * Math.min(1, (t - tr.start) / 1.5);
      let far = 0;
      for (const i of [a, b, c]) {
        const dx = box.dx(cx - p.x[i]);
        const dy = box.dy(cy - p.y[i]);
        far = Math.max(far, dx * dx + dy * dy);
        p.vx[i] = (p.vx[i] + dx * k * dt) * Math.exp(-3 * dt);
        p.vy[i] = (p.vy[i] + dy * k * dt) * Math.exp(-3 * dt);
      }
      if (far < 81) {
        const color = p.sub[a];
        p.kill(a);
        p.kill(b);
        p.kill(c);
        const nb = p.spawn(BARYON, cx, cy, 0, 0, 13, 1, g.fx.chance(0.5) ? 0 : 1);
        if (nb >= 0) p.a[nb] = g.fx.angle();
        this.fx.spawn(Fx.Ring, cx, cy, 0.5, 8, 1.6, 1.55, 1.5, 130);
        this.fx.spawn(Fx.Flash, cx, cy, 0.12, 14, 8, 7.8, 7.6, 30);
        this.fx.spawn(Fx.Flash, cx, cy, 0.35, 30, 2.4, 2.3, 2.2, 30);
        g.sfx('soup.baryon', cx, 1, color);
        this.triplets.splice(n, 1);
      }
    }
  }

  /**
   * String breaking. A lone quark pulls an antiquark out of the sea and the two fly apart; the string
   * between them pulls back with a constant force (it never weakens with distance) and stretches until
   * it holds enough energy to make a new quark–antiquark pair. It breaks there, and each piece closes
   * into a colorless meson.
   */
  private breakStrings(dt: number, t: number): void {
    const p = this.p;
    const g = this.g;
    for (let n = this.loners.length - 1; n >= 0; n--) {
      const l = this.loners[n];
      if (t < l.start) continue;
      this.loners.splice(n, 1);
      const i = p.find(l.id);
      if (i < 0) continue;
      const a = g.fx.angle();
      const ux = Math.cos(a);
      const uy = Math.sin(a);
      const x = p.x[i];
      const y = p.y[i];
      const c = AC[p.sub[i]];
      this.tubes.push({
        qx: x,
        qy: y,
        qvx: ux * TUBE_V,
        qvy: uy * TUBE_V,
        ax: x - ux * 10,
        ay: y - uy * 10,
        avx: -ux * TUBE_V,
        avy: -uy * TUBE_V,
        c: p.sub[i],
        age: 0,
      });
      this.fx.spawn(Fx.Flash, x - ux * 10, y - uy * 10, 0.2, 10, c[0] * 2, c[1] * 2, c[2] * 2, 20);
      p.kill(i);
    }
    for (let n = this.tubes.length - 1; n >= 0; n--) {
      const tb = this.tubes[n];
      tb.age += dt;
      const box = this.box;
      const dx = box.dx(tb.ax - tb.qx);
      const dy = box.dy(tb.ay - tb.qy);
      const d = Math.hypot(dx, dy) || 1;
      // Taut at the edge of breaking, a string is held there trembling until the crack, when every one
      // goes at once; one stretched to its length after that breaks as it gets there.
      if (tb.taut && this.finaleT < F_SNAP) continue;
      const fx = (dx / d) * TENSION * dt;
      const fy = (dy / d) * TENSION * dt;
      tb.qvx += fx;
      tb.qvy += fy;
      tb.avx -= fx;
      tb.avy -= fy;
      tb.qx = box.wrapX(tb.qx + tb.qvx * dt);
      tb.qy = box.wrapY(tb.qy + tb.qvy * dt);
      tb.ax = box.wrapX(tb.ax + tb.avx * dt);
      tb.ay = box.wrapY(tb.ay + tb.avy * dt);
      if (d < SNAP_LEN * 0.94 && !tb.taut) continue;
      if (this.finaleT < F_SNAP) {
        tb.taut = true;
        tb.qvx = tb.qvy = tb.avx = tb.avy = 0;
        continue;
      }
      const f = 0.5 + g.fx.range(-0.12, 0.12);
      const bx = tb.qx + dx * f;
      const by = tb.qy + dy * f;
      const c = QC[tb.c];
      this.mesons.push(this.meson(tb.qx, tb.qy, bx - dx * 0.04, by - dy * 0.04, tb.qvx * 0.45, tb.qvy * 0.45, tb.c));
      this.mesons.push(this.meson(bx + dx * 0.04, by + dy * 0.04, tb.qx + dx, tb.qy + dy, tb.avx * 0.45, tb.avy * 0.45, tb.c));
      // The break: a hot white point where the new pair appears, kicked apart across the string.
      this.fx.spawn(Fx.Flash, bx, by, 0.14, 9, 6, 6, 6.2, 30);
      this.fx.spawn(Fx.Flash, bx, by, 0.3, 16, 0.6 + c[0] * 1.6, 0.6 + c[1] * 1.6, 0.6 + c[2] * 1.6, 30);
      this.fx.spawn(Fx.Ring, bx, by, 0.28, 4, 1.2, 1.2, 1.25, 120);
      g.sfx('soup.snap', bx, 1, tb.c);
      this.tubes.splice(n, 1);
    }
  }

  /**
   * A meson from a quark at (qx, qy) and an antiquark at (ax, ay), which then pull together; they decay
   * over the few seconds after the snap, as the music's falling whistlers do.
   */
  private meson(qx: number, qy: number, ax: number, ay: number, vx: number, vy: number, c: number): Meson {
    const x = (qx + ax) / 2;
    const y = (qy + ay) / 2;
    const spin = Math.atan2(qy - y, qx - x);
    return { x: this.box.wrapX(x), y: this.box.wrapY(y), vx, vy, c, sep: Math.hypot(qx - ax, qy - ay), spin, age: 0, life: this.g.fx.range(0.6, 2.6) };
  }

  /** Mesons spin down tight, then decay: a neutral pion into two photons, a charged one into a muon and a neutrino. */
  private updateMesons(dt: number): void {
    const g = this.g;
    for (let n = this.mesons.length - 1; n >= 0; n--) {
      const m = this.mesons[n];
      m.age += dt;
      m.sep = 7 + (m.sep - 7) * Math.exp(-9 * dt);
      m.spin += dt * (4 + 40 / m.sep);
      const drag = Math.exp(-1.6 * dt);
      m.vx *= drag;
      m.vy *= drag;
      m.x = this.box.wrapX(m.x + m.vx * dt);
      m.y = this.box.wrapY(m.y + m.vy * dt);
      if (m.age < m.life) continue;
      const a = g.fx.angle();
      if (g.fx.chance(1 / 3)) {
        this.fx.spawn(Fx.Photon, m.x, m.y, 0.24, 3.4, 3, 3.3, 4, 0, Math.cos(a) * 1000, Math.sin(a) * 1000);
        this.fx.spawn(Fx.Photon, m.x, m.y, 0.24, 3.4, 3, 3.3, 4, 0, -Math.cos(a) * 1000, -Math.sin(a) * 1000);
        this.fx.spawn(Fx.Flash, m.x, m.y, 0.12, 10, 4, 4.3, 5, 20);
      } else {
        this.fx.spawn(Fx.Spark, m.x, m.y, 0.55, 2.4, 2.2, 2.3, 2.6, 0, Math.cos(a) * 420, Math.sin(a) * 420, 1.2);
        this.fx.spawn(Fx.Spark, m.x, m.y, 0.3, 1.5, 0.5, 0.55, 0.65, 0, -Math.cos(a) * 1200, -Math.sin(a) * 1200);
        this.fx.spawn(Fx.Flash, m.x, m.y, 0.1, 7, 2.2, 2.3, 2.6, 15);
      }
      g.sfx('soup.meson', m.x, 1, m.c);
      this.mesons.splice(n, 1);
    }
  }

  /** The nucleon–antinucleon sea: each pair drifts, finds itself again and annihilates. */
  private updateSea(dt: number, t: number): void {
    const g = this.g;
    for (let n = this.sea.length - 1; n >= 0; n--) {
      const s = this.sea[n];
      if (t < s.born) continue;
      s.rot += dt * 2.4;
      const box = this.box;
      const dx = box.dx(s.ax - s.x);
      const dy = box.dy(s.ay - s.y);
      const d = Math.hypot(dx, dy) || 1;
      const pull = t > s.meet ? 520 * Math.min(1, (t - s.meet) / 0.7) * dt : 0;
      const drag = Math.exp(-(pull > 0 ? 0.6 : 1.2) * dt);
      s.vx = (s.vx + (dx / d) * pull) * drag;
      s.vy = (s.vy + (dy / d) * pull) * drag;
      s.avx = (s.avx - (dx / d) * pull) * drag;
      s.avy = (s.avy - (dy / d) * pull) * drag;
      s.x = box.wrapX(s.x + s.vx * dt);
      s.y = box.wrapY(s.y + s.vy * dt);
      s.ax = box.wrapX(s.ax + s.avx * dt);
      s.ay = box.wrapY(s.ay + s.avy * dt);
      if (pull <= 0 || d > 18) continue;
      const x = box.wrapX(s.x + dx / 2);
      const y = box.wrapY(s.y + dy / 2);
      // Nearly 2 GeV of rest mass back into light: a hard white point and a spray of photons.
      this.fx.spawn(Fx.Flash, x, y, 0.13, 14, 8, 8, 8.4, 30);
      this.fx.spawn(Fx.Flash, x, y, 0.4, 28, 1.3, 1.3, 1.5, 60);
      this.fx.spawn(Fx.Ring, x, y, 0.32, 8, 0.9, 0.95, 1.15, 260);
      const a0 = g.fx.angle();
      for (let k = 0; k < 4; k++) {
        const a = a0 + (k * Math.PI) / 2 + g.fx.range(-0.4, 0.4);
        this.fx.spawn(Fx.Photon, x, y, 0.24, 3.2, 3, 3.3, 4, 0, Math.cos(a) * 1150, Math.sin(a) * 1150);
      }
      g.sfx('soup.antinucleon', x);
      this.sea.splice(n, 1);
    }
  }

  // ───────────────────────────────────────── rendering

  render(r: Renderer, _dt: number): void {
    const look = this.look;
    const inFinale = this.finaleT >= 0;
    look.begin(r, this.t);
    // Confinement cools and thins the plasma; an event's pulse lifts it for a moment.
    look.cooling = Math.min(1, this.bgParams.cool + 0.7 * this.bgParams.confine);
    look.confinement = this.bgParams.confine;
    look.plasma.config.brightness *= (1 + 0.35 * this.bgParams.pulse) * (1 - 0.6 * this.bgParams.confine);
    // Heat left by recent events glows in the plasma where they happened, spreading as it fades.
    for (let k = 0; k < HEAT_MAX; k++) {
      const o = k * 4;
      const age = (this.t - this.heatEv[o + 2]) / 1.5;
      if (age < 0 || age >= 1 || this.heatEv[o + 3] <= 0) continue;
      const f = (1 - age) * (1 - age) * this.heatEv[o + 3] * 0.6;
      look.glow(this.heatEv[o], this.heatEv[o + 1], 90 + 140 * age, 1.0 * f, 0.45 * f, 0.16 * f);
    }

    // The view is a periodic box: what straddles an edge is drawn on both sides of it (its copies across
    // the edges, matter only), so nothing pops as it wraps. The box itself lights the medium.
    const ims = this.box.images(this.halfW + EDGE, this.halfH + EDGE, this.images);
    for (let n = 0; n < ims.length; n += 2) {
      look.ghost = n > 0;
      this.renderMatter(r, ims[n], ims[n + 1], inFinale);
    }
    look.ghost = false;

    this.fx.render(r, look);
    if (this.intro > 0) {
      // Reheating's light, carried over from the Prologue, condenses into the plasma: blinding for a
      // moment, then quickly the matter it became.
      const a = Math.pow(this.intro / INTRO, 3.6);
      const peak = r.reduceFlashes ? 1.4 : 7;
      // White at first, warming toward the plasma's own heat as it fades (never a neutral grey).
      r.over.push(0, 0, Math.max(this.halfW, this.halfH) * 5, peak * a, peak * a * (0.62 + 0.36 * a), peak * a * (0.35 + 0.65 * a), 1, Shape.Puff);
    }
    look.end();
  }

  /**
   * Everything material in the field, drawn shifted by (ox, oy): the field itself, or one of the copies
   * the periodic box shows around it. Strings run to the nearest copy of the other end, so one that
   * crosses an edge of the field is completed by the copy beside it; a copy's matter is drawn only
   * where the view can show it.
   */
  private renderMatter(r: Renderer, ox: number, oy: number, inFinale: boolean): void {
    const p = this.p;
    const look = this.look;
    const box = this.box;
    const fade = (i: number) => (p.flags[i] & F_FADE ? Math.max(0, p.life[i] / 1.2) : 1);
    const mx = this.halfW + 90;
    const my = this.halfH + 90;
    const seen = (x: number, y: number) => Math.abs(x) < mx && Math.abs(y) < my;
    // Gluon strings: every pair is tied to its partner, and you can see the pull.
    for (let i = 0; i < p.n; i++) {
      if (p.kind[i] !== QUARK || !p.link[i] || p.isDead(i)) continue;
      const j = p.find(p.link[i]);
      if (j < 0) continue;
      const x0 = p.x[i] + ox;
      const y0 = p.y[i] + oy;
      const x1 = x0 + box.dx(p.x[j] - p.x[i]);
      const y1 = y0 + box.dy(p.y[j] - p.y[i]);
      if (!seen(x0, y0) && !seen(x1, y1)) continue;
      look.string(x0, y0, x1, y1, QC[p.sub[i]], AC[p.sub[j]], Math.min(1, Math.hypot(x1 - x0, y1 - y0) / 170), this.t, 0.8, p.id[i] * 1.7);
    }
    // Color bonds between nearby free quarks of different colors (stored by id: compact() shifts indices).
    for (let k = 0; k < this.bonds.length; k += 2) {
      const i = p.find(this.bonds[k]);
      const j = p.find(this.bonds[k + 1]);
      if (i < 0 || j < 0) continue;
      const x0 = p.x[i] + ox;
      const y0 = p.y[i] + oy;
      const x1 = x0 + box.dx(p.x[j] - p.x[i]);
      const y1 = y0 + box.dy(p.y[j] - p.y[i]);
      if (!seen(x0, y0) && !seen(x1, y1)) continue;
      const s = Math.max(0, 1 - Math.hypot(x1 - x0, y1 - y0) / 62) * (this.finaleT > 0 ? 1 : 0.6);
      look.string(x0, y0, x1, y1, QC[p.sub[i]], QC[p.sub[j]], 0.1, this.t, 0.45 * s, this.bonds[k]);
    }
    // Confinement strings: taut, bright, humming as they pull each triplet together.
    for (const tr of this.triplets) {
      if (this.finaleT < tr.start) continue;
      const idx = [p.find(tr.ids[0]), p.find(tr.ids[1]), p.find(tr.ids[2])];
      if (idx.some((i) => i < 0)) continue;
      const s = Math.min(1, (this.finaleT - tr.start) / 0.6);
      for (let m = 0; m < 3; m++) {
        const i = idx[m];
        const j = idx[(m + 1) % 3];
        const x0 = p.x[i] + ox;
        const y0 = p.y[i] + oy;
        const x1 = x0 + box.dx(p.x[j] - p.x[i]);
        const y1 = y0 + box.dy(p.y[j] - p.y[i]);
        if (!seen(x0, y0) && !seen(x1, y1)) continue;
        look.string(x0, y0, x1, y1, QC[p.sub[i]], QC[p.sub[j]], 0.75, this.t, s, tr.ids[0] + m);
      }
    }

    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const x = p.x[i] + ox;
      const y = p.y[i] + oy;
      if (!seen(x, y)) continue;
      switch (p.kind[i]) {
        case QUARK:
          look.quark(x, y, QC[p.sub[i]], 1, false, p.a[i] > 0, this.t, p.id[i]);
          break;
        case ANTI: {
          let a = 1;
          if (p.life[i] !== Infinity && p.life[i] < 0.2) a = 0.35 + 0.65 * (Math.sin(p.life[i] * 90) * 0.5 + 0.5);
          look.quark(x, y, AC[p.sub[i]], a, true, p.a[i] > 0);
          break;
        }
        case FREE: {
          const f = fade(i) * p.b[i];
          const pulse = 0.88 + 0.12 * Math.sin(this.t * 2.2 + p.id[i]);
          look.quark(x, y, QC[p.sub[i]], 0.7 * pulse * f, false, false, this.t, p.id[i]);
          break;
        }
        case LEPTON: {
          // Leptons: small, pale and quick (an antilepton wears a ring); nothing leaves the field, so
          // each fades out at the end of its short flight.
          const lf = Math.min(1, (LEPTON_LIFE - p.age[i]) / 0.5);
          if (p.sub[i] & 1) r.top.push(x, y, 5, 1.6 * lf, 1.7 * lf, 2 * lf, 1, Shape.Ring, 0.12);
          r.top.push(x, y, 1.6, 4 * lf, 4.2 * lf, 4.6 * lf, 1, Shape.Glow);
          break;
        }
        case BARYON: {
          // Color fully confined. The three quarks lock where they met, and the nucleon rings once as
          // the binding energy comes out as light; after the tally the charges inside wash out to white
          // and the survivors shine on as the plasma goes dark around them.
          const age = p.age[i];
          const since = this.finaleT - F_SURVIVORS;
          const hue = this.tallied ? 1 - 0.7 * Math.min(1, since / 1.6) : 1;
          const ring = 1 + 0.2 * Math.exp(-age * 4.5) * Math.cos(age * 24);
          let glow = 1.4 * Math.exp(-age * 5);
          if (this.tallied) glow += (r.reduceFlashes ? 0.8 : 3.4) * Math.exp(-since * 2.2) + 0.8 * Math.min(1, since / 1.4);
          this.hadrons.nucleon(r, x, y, ring, 1, p.a[i] + age * 0.9, this.t, p.id[i] * 2.3, QC, p.sub[i] === 0, false, hue, glow);
          break;
        }
      }
    }
    if (inFinale) this.renderConfinement(r, ox, oy);

    if (this.hot && seen(this.hot.x + ox, this.hot.y + oy)) {
      const h = { ...this.hot, x: this.hot.x + ox, y: this.hot.y + oy };
      const a = Math.min(1, h.age / 0.8) * Math.min(1, (h.life - h.age) / 1.2);
      const beat = 0.75 + 0.25 * Math.sin(h.age * 5.5);
      // A knot of hotter plasma: it glows white-gold through the medium, color charges circle it,
      // and a slow heartbeat of light pulses out of it to the edge of the clickable area.
      look.glow(h.x, h.y, 240, 1.4 * a * beat, 0.95 * a * beat, 0.5 * a * beat, 1);
      r.top.push(h.x, h.y, 3, 10 * a * beat, 9.6 * a * beat, 9 * a * beat, 1, Shape.Glow);
      r.top.push(h.x, h.y, 40, 1.2 * a, 1.1 * a, 0.95 * a, 1, Shape.Glow);
      for (let k = 0; k < 9; k++) {
        const ang = h.age * (1.6 + (k % 3) * 0.35) * (k < 6 ? 1 : -1.3) + (k * Math.PI) / 4.5;
        const rad = (k < 6 ? 34 : 56) + 10 * Math.sin(h.age * 2 + k);
        look.quark(h.x + Math.cos(ang) * rad, h.y + Math.sin(ang) * rad, QC[k % 3], 0.55 * a, false);
      }
      const ring = (h.age * 0.8) % 1;
      look.ring(h.x, h.y, 40 + 60 * ring, 1.4 * a, 1.3 * a, 1.1 * a, ring);
    }
    if (this.top && seen(this.top.x + ox, this.top.y + oy)) {
      const tq = { ...this.top, x: this.top.x + ox, y: this.top.y + oy };
      const trail = this.topTrail;
      if (ox === 0 && oy === 0) {
        trail.push(this.top.x, this.top.y);
        if (trail.length > 36) trail.splice(0, 2);
      }
      const tr = this.trailCopy.subarray(0, trail.length);
      for (let m = 0; m < trail.length; m += 2) {
        tr[m] = trail[m] + ox;
        tr[m + 1] = trail[m + 1] + oy;
      }
      // The wake: a heavy particle tearing through the plasma leaves a streak of light, brightest at its head.
      const n = tr.length / 2;
      if (n >= 3) {
        const { trailCore: core, trailSheath: sheath } = this;
        for (let m = 0; m < n; m++) {
          const f = (m + 1) / n;
          core[m] = 2.2 * f * f;
          sheath[m] = 0.35 * f;
        }
        look.filaments.push(tr, TOP_TAIL, TOP_HEAD, 9, core, sheath, false);
      }
      const flick = 0.85 + 0.15 * Math.sin(tq.age * 40);
      look.quark(tq.x, tq.y, [1.0, 0.75, 0.35], 1.3 * flick, false, true, this.t, 7);
      const ping = (tq.age * 1.4) % 1;
      look.ring(tq.x, tq.y, 20 + 80 * ping, 1.6, 1.25, 0.6, ping);
    }

  }

  /**
   * Confinement: the plasma drains of heat and the specks still; strings stretch, tremble and snap
   * into mesons; the nucleon–antinucleon sea finds itself and burns back into light; and at the tally
   * one front of light sweeps out across the cold, dark universe while every survivor flares.
   */
  private renderConfinement(r: Renderer, ox: number, oy: number): void {
    const t = this.finaleT;
    const look = this.look;
    const hadrons = this.hadrons;
    const box = this.box;
    // Light that floods the plasma is held down with Reduce flashes on.
    const calm = r.reduceFlashes ? 0.4 : 1;
    for (const tb of this.tubes) {
      // The string thins and brightens as it stores energy and trembles harder the closer it is to
      // breaking; the energy gathering in its middle (the pair it is about to become) glows in the plasma.
      const qx = tb.qx + ox;
      const qy = tb.qy + oy;
      const ax = qx + box.dx(tb.ax - tb.qx);
      const ay = qy + box.dy(tb.ay - tb.qy);
      const strain = Math.min(1, Math.hypot(ax - qx, ay - qy) / SNAP_LEN);
      look.string(qx, qy, ax, ay, QC[tb.c], AC[tb.c], strain, this.t, 1, tb.c * 3.1);
      // Tinted, not white (white light over a cooling plasma reads as grey haze).
      const e = strain * strain * strain * calm;
      const c = QC[tb.c];
      look.glow((qx + ax) / 2, (qy + ay) / 2, 40 + 60 * strain, (0.5 + 0.5 * c[0]) * e, (0.35 + 0.4 * c[1]) * e, (0.3 + 0.5 * c[2]) * e);
      look.quark(qx, qy, QC[tb.c], 1, false, false, this.t, tb.c);
      look.quark(ax, ay, AC[tb.c], Math.min(1, tb.age * 6), true);
    }
    for (const m of this.mesons) {
      // Quark and antiquark in a tight spin on what is left of the string: the colors cancel, so the pair glows white.
      const ux = Math.cos(m.spin) * m.sep * 0.5;
      const uy = Math.sin(m.spin) * m.sep * 0.5;
      const bound = Math.min(1, 9 / m.sep);
      const fade = Math.min(1, (m.life - m.age) * 8);
      hadrons.meson(r, m.x + ox, m.y + oy, ux, uy, QC[m.c], AC[m.c], fade, bound, this.t, m.c * 2.7 + m.life * 13);
    }
    for (const s of this.sea) {
      if (t < s.born) continue;
      // Each pair condenses out of the cooling plasma and drifts, then is drawn back together: both burn
      // hotter as they close and the light between them builds until they annihilate.
      const a = Math.min(1, (t - s.born) / 0.45);
      const size = 0.85 * (0.6 + 0.4 * a);
      const x0 = s.x + ox;
      const y0 = s.y + oy;
      const x1 = x0 + box.dx(s.ax - s.x);
      const y1 = y0 + box.dy(s.ay - s.y);
      const close = t > s.meet ? (1 - Math.min(1, Math.hypot(x1 - x0, y1 - y0) / 110)) ** 2 : 0;
      const glow = 2.2 * close * calm;
      const seed = s.born * 17;
      hadrons.nucleon(r, x0, y0, size, a, s.rot, this.t, seed, QC, s.proton, false, 1, glow);
      hadrons.nucleon(r, x1, y1, size, a, -s.rot, this.t, seed + 5, AC, s.proton, true, 1, glow);
      if (close > 0) {
        // The energy building between them: a hot, tight glow (a broad white one greyed the plasma).
        const f = close * calm;
        look.glow((x0 + x1) / 2, (y0 + y1) / 2, 36 + 44 * close, 1.3 * f, 0.72 * f, 0.42 * f, seed);
      }
    }
    if (this.tallied) {
      // The tally: one front of light sweeps out from the centre through the cold plasma and the specks.
      const u = (t - F_SURVIVORS) / 2.4;
      if (u < 1) look.ring(0, 0, 40 + 1100 * (1 - (1 - u) * (1 - u)), 1.5 * calm, 0.8 * calm, 0.36 * calm, u);
    }
  }

  // ───────────────────────────────────────── input

  pointer(e: PointerInfo): void {
    if (!e.primary) return;
    // A press on a copy of the field acts on the field itself: it is the same space.
    const box = this.box;
    const x = box.wrapX(e.x);
    const y = box.wrapY(e.y);
    const near = (h: { x: number; y: number }, r: number) => Math.hypot(box.dx(x - h.x), box.dy(y - h.y)) < r;
    if (e.type === 'down') {
      this.idle = 0;
      this.pDown = true;
      this.pX = x;
      this.pY = y;
      if (this.finaleT >= 0) return;
      if (this.hot && near(this.hot, 80)) {
        this.burstHotSpot(this.hot);
        return;
      }
      if (this.top && near(this.top, 50)) {
        this.catchTop(this.top);
        return;
      }
      this.clicks++;
      this.condense(x, y, this.pairsPerClick, true, false, this.nextBeat());
      this.streamAcc = 0;
    } else if (e.type === 'move') {
      this.pX = x;
      this.pY = y;
    } else {
      this.pDown = false;
    }
  }

  // ───────────────────────────────────────── HUD

  stocks(): StockView[] {
    const s = this.s;
    const out: StockView[] = [
      {
        id: 'photons',
        label: 'Photons',
        value: s.photons,
        format: 'count',
        rate: this.photonMeter.rate,
        hint: 'Every annihilation turns a particle and its antiparticle into light.',
      },
    ];
    if (s.baryogenesis || s.quarks > 0) {
      out.push({
        id: 'quarks',
        label: 'Free quarks',
        value: s.quarks,
        format: 'count',
        rate: this.quarkMeter.rate,
        hint: 'Quarks left without a partner by the slight preference for matter. This is the matter that survives.',
      });
      out.push({
        id: 'eta',
        label: 'Matter per photon',
        value: s.quarks / 3 / Math.max(1, s.photons),
        format: 'decimal',
        ours: 6.1e-10,
        hint: 'η, nucleons per photon. It decides how the first nuclei will form.',
      });
    }
    return out;
  }

  dotScale(): { value: number; unit: string } | null {
    const w = this.weight;
    return w > 1 ? { value: w, unit: 'particles' } : null;
  }

  labels(): WorldLabel[] {
    if (this.chain < 2 || this.finaleT >= 0) return [];
    // Held over the latest link while the chain lives; once it breaks, it rises and fades.
    const after = Math.max(0, this.t - this.chainT - CHAIN_WINDOW) / 0.7;
    if (after >= 1) return [];
    return [{ id: 'chain', x: this.labelX, y: this.labelY - 34 - 22 * after, text: `chain ×${this.chain}`, tone: 'value', opacity: 1 - after }];
  }

  offline(seconds: number): OfflineReport {
    const s = this.s;
    const q = this.quarkMeter.rate * seconds;
    const ph = this.photonMeter.rate * seconds;
    s.quarks += q;
    s.photons += ph;
    const lines = [{ label: 'Photons', value: toText(count(ph)) }];
    if (q > 0) lines.push({ label: 'Free quarks', value: toText(count(q)) });
    return { lines };
  }

  accent(): RGB {
    const c = this.bgParams.cool;
    return [0.72 + 0.2 * c, 0.82 + 0.1 * c, 1.0 - 0.05 * c];
  }

  /** The instrument powers on once the light has become a plasma to look at. */
  hudHidden(): boolean {
    return this.intro > INTRO - 0.8;
  }

  hint(): string | null {
    if (this.finaleT >= 0) return null;
    if (this.clicks === 0 && this.idle > 1.5) return 'Click to turn energy into matter.';
    if (this.hot && !this.s.everHot && this.hot.age > 1.2) return 'A hot spot. Click it.';
    if (this.top && !this.g.isDiscovered('top')) return 'A top quark. Catch it before it decays.';
    if (this.stream > 0 && !this.s.everHeld) return 'Hold to keep making matter.';
    return null;
  }
}
