export const ELEMENTS: readonly ElementInfo[] = TABLE.map(([symbol, name, origin, abundance], i) => ({
  z: i + 1,
  symbol,
  name,
  origin,
  abundance,
  note: NOTES[i + 1],
}));

/** Elements a star (or the Big Bang) can leave behind: everything except the dark ones. */
export const MAKEABLE: readonly ElementInfo[] = ELEMENTS.filter((e) => e.origin !== 'unstable');

export function element(z: number): ElementInfo {
  return ELEMENTS[z - 1];
}

/** Position in the standard 18-column layout (lanthanides and actinides in rows 8 and 9). */
export function tablePosition(z: number): { col: number; row: number } {
  if (z === 1) return { col: 0, row: 0 };
  if (z === 2) return { col: 17, row: 0 };
  if (z <= 10) return { col: z <= 4 ? z - 3 : z - 5 + 12, row: 1 };
  if (z <= 18) return { col: z <= 12 ? z - 11 : z - 13 + 12, row: 2 };
  if (z <= 36) return { col: z - 19, row: 3 };
  if (z <= 54) return { col: z - 37, row: 4 };
  if (z <= 86) {
    if (z <= 56) return { col: z - 55, row: 5 };
    if (z <= 71) return { col: z - 57 + 3, row: 8 };
    return { col: z - 72 + 3, row: 5 };
  }
  if (z <= 88) return { col: z - 87, row: 6 };
  if (z <= 103) return { col: z - 89 + 3, row: 9 };
  return { col: z - 104 + 3, row: 6 };
}

export function elementCodexId(z: number): string {
  return `el-${z}`;
}
