/**
 * Gravitational lensing, the one way dark matter shows itself: what lies behind a mass is seen bent
 * around it. Drawn over the finished scene (before the brightest light on top): each lens's
 * neighbourhood is copied, then drawn back through the lens equation, β = θ − α(θ), with the
 * deflections of every lens added (thin lenses in one plane superpose), so two halos falling together
 * bend the background as one. A halo is a soft, spread-out mass (it magnifies and drags the specks and
 * mist drifting behind it into a slow shimmer); a black hole is a point mass with a shadow, an absence
 * ringed by the light it bends. The deflection tapers to nothing at each lens's reach, so the copy and
 * the scene meet without a seam.
 */
import { FULLSCREEN_VS, Program, Target, drawFullscreen, type GLCaps } from '../../render/gl';
import { HEADER } from '../../render/glsl';
import type { LayerFrame, RenderLayer } from '../../render/renderer';

export interface Lens {
  x: number;
  y: number;
  /** Einstein radius and core radius (world units): a soft core keeps a diffuse mass from mirroring. */
  einstein: number;
  core: number;
  /** Where the deflection has tapered to nothing (world units). */
  reach: number;
  /** Radius of the shadow (world units; 0 for anything but a black hole). */
  shadow: number;
}

const MAX = 8;

const LENS_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uSrc;
uniform vec4 uView;
uniform vec4 uLens[${MAX}];   // x, y, einstein², core²
uniform vec2 uLensB[${MAX}];  // reach, shadow
uniform int uCount;
out vec4 outColor;
void main() {
  vec2 ndc = vUv * 2.0 - 1.0;
  vec2 w = uView.xy + vec2(ndc.x, -ndc.y) * uView.zw;
  vec2 src = w;
  float shade = 1.0;
  for (int k = 0; k < ${MAX}; k++) {
    if (k >= uCount) break;
    vec2 d = w - uLens[k].xy;
    float r2 = dot(d, d);
    float r = sqrt(r2);
    float taper = 1.0 - smoothstep(0.45 * uLensB[k].x, uLensB[k].x, r);
    src -= d * uLens[k].z / (r2 + uLens[k].w) * taper;
    float sh = uLensB[k].y;
    if (sh > 0.0) shade *= smoothstep(sh * 0.86, sh * 1.04, r);
  }
  vec2 s = (src - uView.xy) / uView.zw;
  outColor = vec4(texture(uSrc, vec2(s.x, -s.y) * 0.5 + 0.5).rgb * shade, 1.0);
}`;

export class GravLens implements RenderLayer {
  readonly stage = 'atmosphere' as const;
  /** Refilled by the look every frame (the strongest eight are drawn). */
  lenses: Lens[] = [];
  private gl: WebGL2RenderingContext | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private prog: Program | null = null;
  private copy: Target | null = null;
  private a = new Float32Array(MAX * 4);
  private b = new Float32Array(MAX * 2);
  private rects: number[] = [];

  init(gl: WebGL2RenderingContext, caps: GLCaps, emptyVao: WebGLVertexArrayObject): void {
    this.gl = gl;
    this.vao = emptyVao;
    this.prog = null;
    try {
      this.prog = new Program(gl, FULLSCREEN_VS, LENS_FS, 'dawn-lens');
    } catch (e) {
      console.error(e);
      return;
    }
    this.copy = new Target(gl, 1, 1, caps.hdr);
  }

  draw(frame: LayerFrame): void {
    const gl = this.gl;
    const prog = this.prog;
    const copy = this.copy;
    const n = Math.min(MAX, this.lenses.length);
    if (!gl || !prog || !copy || n === 0) return;
    const scene = frame.scene;
    // The copy must match the scene's format for a blit; a scene without HDR has no lens.
    if (copy.hdr !== scene.hdr) return;
    copy.resize(scene.width, scene.height);
    const v = frame.view;
    const W = scene.width;
    const H = scene.height;
    this.rects.length = 0;
    for (let i = 0; i < n; i++) {
      const L = this.lenses[i];
      this.a.set([L.x, L.y, L.einstein * L.einstein, L.core * L.core], i * 4);
      this.b.set([L.reach, L.shadow], i * 2);
      // Scene pixels the lens can touch, with room for what it pulls in from just outside.
      const cx = ((L.x - v[0]) / v[2] * 0.5 + 0.5) * W;
      const cy = (0.5 - (L.y - v[1]) / v[3] * 0.5) * H;
      const rad = (L.reach * 1.1 + L.einstein) * (H / (2 * v[3])) + 2;
      const x0 = Math.max(0, Math.floor(cx - rad));
      const y0 = Math.max(0, Math.floor(cy - rad));
      const x1 = Math.min(W, Math.ceil(cx + rad));
      const y1 = Math.min(H, Math.ceil(cy + rad));
      if (x1 > x0 && y1 > y0) this.rects.push(x0, y0, x1, y1);
    }
    if (this.rects.length === 0) return;
    gl.disable(gl.SCISSOR_TEST);
    gl.bindFramebuffer(gl.READ_FRAMEBUFFER, scene.fbo);
    gl.bindFramebuffer(gl.DRAW_FRAMEBUFFER, copy.fbo);
    const r = this.rects;
    for (let k = 0; k < r.length; k += 4) gl.blitFramebuffer(r[k], r[k + 1], r[k + 2], r[k + 3], r[k], r[k + 1], r[k + 2], r[k + 3], gl.COLOR_BUFFER_BIT, gl.NEAREST);
    gl.bindFramebuffer(gl.READ_FRAMEBUFFER, null);
    gl.bindFramebuffer(gl.DRAW_FRAMEBUFFER, null);
    scene.bind();
    gl.disable(gl.BLEND);
    prog.use().i1('uSrc', 0);
    gl.uniform4fv(prog.loc('uView'), v);
    gl.uniform4fv(prog.loc('uLens'), this.a);
    gl.uniform2fv(prog.loc('uLensB'), this.b);
    gl.uniform1i(prog.loc('uCount'), n);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, copy.tex);
    gl.enable(gl.SCISSOR_TEST);
    for (let k = 0; k < r.length; k += 4) {
      gl.scissor(r[k], r[k + 1], r[k + 2] - r[k], r[k + 3] - r[k + 1]);
      drawFullscreen(gl, this.vao!);
    }
    gl.disable(gl.SCISSOR_TEST);
    gl.bindTexture(gl.TEXTURE_2D, null);
  }

  dispose(): void {
    this.prog?.dispose();
    this.copy?.dispose();
    this.prog = null;
    this.copy = null;
  }
}
