/**
 * How the Forge looks (version 2). The simulation says what is where; this draws it.
 *
 * - The disk: a raymarched slab (render/disk.ts) of unresolved starlight with dust lanes inside it that
 *   dim and redden what lies behind them, brightening toward the galactic centre off the lower left,
 *   ageing from young blue-white to old gold. Molecular clouds are dark, dusty knots in it; around the
 *   hottest stars they light up as H II regions (hydrogen-alpha red, oxygen teal close in) with crisp,
 *   limb-bright ionization fronts. The same world holds the whole galaxy for the finale.
 * - Resolved stars of the disk: a GPU storm of crisp pinpoints in depth, in the colours of a stellar
 *   population, bluer while the galaxy is young. Dust motes: a second, all but invisible storm that
 *   glints where starlight or a light front passes and is thrown outward by blast waves.
 * - Stars: crisp point lights in their true blackbody colours with a real range of brightness; the
 *   brightest flare in the lens and light the dust around them.
 * - Remnants: a white dwarf a faint blue-white point, a pulsar's beams thin filaments of light, a black
 *   hole an absence ringed by a thin, bent ring of light.
 * - Deaths: shells in the disk (a supernova remnant's broken filaments, a planetary nebula's slow
 *   limb-bright bubble), light fronts through the dust, blast waves through the motes.
 * - Feeding: the stream is a luminous ribbon of twisting strands, a thin bright core in a soft sheath
 *   widening into a glowing foot in the cloud, heating from hydrogen pink to white as it falls.
 * - Effects (the era's FxPool, restyled): flashes are point spreads that light the dust; rings are light
 *   fronts and blast waves rather than drawn circles; sparks are streaks.
 */
import { Disk, type DiskCloud, type DiskHot, type DiskShell } from '../../render/disk';
import { Filaments } from '../../render/filaments';
import type { FxLook } from '../../render/fx';
import type { BackgroundDef, Renderer } from '../../render/renderer';
import type { PostParams } from '../../render/post';
import { Shape } from '../../render/sprites';
import { Storm, type StormKick, type StormLight } from '../../render/storm';
import type { VolumeFront, VolumeLight } from '../../render/volume';

type Col = readonly [number, number, number];

const BLACK: BackgroundDef = {
  id: 'forge-v2',
  fragment: /* glsl */ `
void main() {
  outColor = vec4(0.0, 0.0, 0.0, 1.0);
}`,
};

/** The post settings this look is graded for: crisp light, only the brightest blooming, glare for the biggest stars. */
const POST: Partial<PostParams> = { bloom: 0.2, bloomThreshold: 1.6, glare: 0.32, glareThreshold: 1.5, glareAngle: 0.52, saturation: 1.18, punch: 1.18, vignette: 0.4, grain: 0.01 };

/**
 * Where the galaxy is around the patch (world units; the field is about 1,800 light-years across, so
 * one unit is about 2.3 light-years): its centre 8 kpc off the lower left, a 2.6 kpc scale length, and
 * a stellar disk about 15 kpc in radius.
 */
export const GALAXY_CENTRE: [number, number] = [-9300, 6600];
export const GALAXY_SCALE = 3600;
export const GALAXY_RADIUS = 21000;

/** Speck colours of a stellar population: hot blue, white, yellow, orange, red dwarfs, red giants, gold. */
const POP: [number, number, number][] = [
  [0.6, 0.72, 1.0],
  [0.84, 0.9, 1.0],
  [1.0, 0.93, 0.82],
  [1.0, 0.74, 0.48],
  [1.0, 0.55, 0.34],
  [1.0, 0.62, 0.38],
  [1.0, 0.82, 0.58],
  [1.0, 1.0, 1.0],
];
const POP_YOUNG = [2.4, 2.0, 2.0, 1.4, 0.9, 0.35, 0.5, 0];
const POP_OLD = [0.35, 0.8, 1.8, 2.2, 1.6, 1.0, 1.2, 0];

const H_PINK: Col = [1.0, 0.3, 0.42];
const HOT_WHITE: Col = [0.86, 0.92, 1.0];

const lum = (c: Col) => 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];

interface Ranked<T> {
  weight: number;
  item: T;
}

export class ForgeLook implements FxLook {
  readonly disk = new Disk({ centre: GALAXY_CENTRE, scaleLength: GALAXY_SCALE, radius: GALAXY_RADIUS });
  readonly stars = new Storm({
    count: 14000,
    depth: 260,
    focal: 1600,
    lifeMin: 30,
    lifeMax: 70,
    swirl: 0,
    swirlScale: 600,
    drag: 1,
    jitter: 0,
    spread: 0,
    faintest: 0.03,
    peak: 2.2,
    magnitudePower: 0.85,
    halo: 0,
    twinkle: 0.05,
    palette: POP,
    weights: [...POP_YOUNG],
  });
  readonly motes = new Storm({
    count: 7000,
    depth: 220,
    focal: 1600,
    lifeMin: 5,
    lifeMax: 12,
    swirl: 4,
    swirlScale: 700,
    drag: 1.4,
    jitter: 0.8,
    spread: 0,
    faintest: 0.004,
    peak: 0.2,
    magnitudePower: 1,
    halo: 0,
    twinkle: 0.25,
    palette: [
      [1.0, 0.78, 0.6],
      [1.0, 0.42, 0.5],
      [0.5, 0.95, 0.88],
      [0.9, 0.94, 1.0],
    ],
    weights: [3, 1.4, 0.4, 0.6],
  });
  readonly filaments = new Filaments();
  /** The resolved stars' settings at rest (the finale fades them as the view draws back). */
  private readonly rest = { faintest: this.stars.config.faintest, peak: this.stars.config.peak };
  private r: Renderer | null = null;
  private saved: Partial<PostParams> = {};
  private lights: Ranked<VolumeLight>[] = [];
  private fronts: Ranked<VolumeFront>[] = [];
  private kicks: Ranked<StormKick>[] = [];
  private speckLights: Ranked<StormLight>[] = [];
  private clouds: DiskCloud[] = [];
  private hots: DiskHot[] = [];
  private shells: Ranked<DiskShell>[] = [];
  private loop = new Float32Array(2 * 49);

  attach(r: Renderer): void {
    this.r = r;
    r.setBackground(BLACK);
    r.setLayers([this.disk, this.motes, this.stars, this.filaments]);
    const post = r.post as unknown as Record<string, unknown>;
    for (const [k, v] of Object.entries(POST)) {
      (this.saved as Record<string, unknown>)[k] = post[k];
      post[k] = v;
    }
  }

  detach(r: Renderer): void {
    r.setLayers([]);
    Object.assign(r.post, this.saved);
    this.r = null;
  }

  /**
   * The state of the disk: unresolved starlight (`glow`), its age (0 young … 1 old), gas richness, the
   * patch's arm (x at y = 0 and strength), an epoch step's lift, and how far back the view has drawn
   * (0 the patch … 1 the whole galaxy).
   */
  medium(glow: number, age: number, gas: number, armX: number, armK: number, pulse: number, far: number): void {
    const d = this.disk.config;
    d.glow = glow;
    d.age = age;
    d.dust = gas;
    d.armX = armX;
    d.armK = armK;
    d.pulse = pulse;
    const s = this.stars.config;
    for (let k = 0; k < 8; k++) s.weights[k] = POP_YOUNG[k] + (POP_OLD[k] - POP_YOUNG[k]) * age;
    // Seen from far, single stars are no longer resolved: the galaxy's light is theirs.
    const near = Math.max(0, 1 - far * 1.6);
    s.faintest = this.rest.faintest * (0.8 + 0.5 * Math.min(1.5, glow)) * near;
    s.peak = this.rest.peak * near;
    this.motes.config.peak = 0.2 * near;
  }

  /** Turns the galaxy's arms so the given point (world) lies on one: the Sun on its arm, in the finale. */
  armThrough(x: number, y: number): void {
    const dx = x - GALAXY_CENTRE[0];
    const dy = y - GALAXY_CENTRE[1];
    const r = Math.hypot(dx, dy);
    // Arm phase is th - ln(r / R) / 0.23 + phase; on an arm its cosine is 1.
    this.disk.config.armPhase = -(Math.atan2(dy, dx) - Math.log(r / GALAXY_SCALE) / 0.23);
  }

  /** Starts a frame (the per-frame lists refill). */
  begin(r: Renderer): void {
    this.r = r;
    this.lights.length = 0;
    this.fronts.length = 0;
    this.kicks.length = 0;
    this.speckLights.length = 0;
    this.clouds.length = 0;
    this.hots.length = 0;
    this.shells.length = 0;
  }

  /** A molecular cloud in the disk. */
  cloud(x: number, y: number, radius: number, heat: number, gas: number, seed: number): void {
    this.clouds.push({ x, y, radius, heat, gas, seed });
  }

  /** A hot star's ionized bubble (its Strömgren radius) in the clouds around it. */
  bubble(x: number, y: number, radius: number, strength: number): void {
    this.hots.push({ x, y, radius, strength });
  }

  /** A light inside the disk: the dust around it scatters it (a reflection nebula), and motes near it glint. */
  light(x: number, y: number, radius: number, c: Col, glint = 0): void {
    const color: [number, number, number] = [c[0], c[1], c[2]];
    this.lights.push({ weight: lum(c) * radius, item: { x, y, z: 0, radius, color } });
    if (glint > 0) this.speckLights.push({ weight: glint * radius * 0.01, item: { x, y, intensity: glint, radius: radius * 0.8, width: 0 } });
  }

  /** A shell in the disk (see DiskShell); `weight` ranks it when there are more than the disk draws. */
  shell(s: DiskShell, weight: number): void {
    this.shells.push({ weight, item: s });
  }

  /**
   * A star as a crisp point light: a white-hot pinpoint tinted by its colour, a tight halo, and for the
   * luminous ones a wide faint glow; brightness spans the stars' real range, compressed (∝ L^0.2), so a
   * blue giant outshines a red dwarf by far and the brightest flare in the lens. `embed` (0–1) is how
   * deep in its birth cloud it still is: dimmed and reddened.
   */
  star(x: number, y: number, c: Col, L: number, k: number, embed = 0, swell = 1): number {
    const r = this.r;
    if (!r || k <= 0.003) return 0;
    const b = (0.5 + 0.85 * L ** 0.2) * k * (1 - 0.75 * embed);
    const red = embed * 0.7;
    const cr = c[0];
    const cg = c[1] * (1 - 0.45 * red);
    const cb = c[2] * (1 - 0.75 * red);
    const s = Math.min(1.6, 0.85 + 0.12 * Math.log10(1 + L)) * swell;
    // The core: white where it is brightest, keeping a trace of the star's colour.
    r.top.push(x, y, 1.9 * s, (cr * 0.45 + 0.55) * b * 4.2, (cg * 0.45 + 0.55) * b * 4.2, (cb * 0.45 + 0.55) * b * 4.2, 1, Shape.Glow);
    r.top.push(x, y, 6 * s, cr * b * 0.9, cg * b * 0.9, cb * b * 0.9, 1, Shape.Glow);
    if (L > 30) {
      const w = Math.min(1, Math.log10(L / 30) / 4);
      r.top.push(x, y, (10 + 16 * w) * s, cr * b * 0.05 * w, cg * b * 0.05 * w, cb * b * 0.05 * w, 1, Shape.Glow);
    }
    return b;
  }

  /** A white dwarf: a tiny, hot, faint point, cooling over time (`k`). */
  whiteDwarf(x: number, y: number, k: number): void {
    const r = this.r;
    if (!r || k <= 0.003) return;
    r.top.push(x, y, 1.5, 2.2 * k, 2.4 * k, 2.9 * k, 1, Shape.Glow);
    r.top.push(x, y, 4.5, 0.25 * k, 0.3 * k, 0.42 * k, 1, Shape.Glow);
  }

  /**
   * A pulsar: a blue-white point that flashes twice a turn as its beams sweep past us (`a` their angle),
   * the way pulsars are seen: as pulses, not as beams.
   */
  pulsar(x: number, y: number, a: number, k: number): void {
    const r = this.r;
    if (!r || k <= 0.003) return;
    const pulse = Math.max(0, Math.cos(a)) ** 24 + Math.max(0, -Math.cos(a)) ** 24;
    const e = k * (0.45 + 2.2 * pulse);
    r.top.push(x, y, 1.6, 3.2 * e, 3.5 * e, 4.2 * e, 1, Shape.Glow);
    r.top.push(x, y, 5, 0.35 * e, 0.45 * e, 0.7 * e, 1, Shape.Glow);
    if (pulse > 0.05) this.light(x, y, 50, [0.05 * pulse * k, 0.06 * pulse * k, 0.1 * pulse * k], 0.8 * pulse * k);
  }
  /**
   * A black hole: an absence. A disc of nothing over the disk's light, ringed by a thin ring of light
   * bent around it (the photon ring), and a faint lensed glow just outside.
   */
  blackHole(x: number, y: number, R: number, k: number): void {
    const r = this.r;
    if (!r || k <= 0.003) return;
    r.solid.push(x, y, R * 0.6, 0, 0, 0, 0.92 * k, Shape.Disc);
    this.circle(x, y, R * 0.68, [1.0, 0.88, 0.74], 0.3 * k, 0.02 * k, 1.2);
  }

  /**
   * Corner marks around something (the frame's own way of pointing): four short, faint angles at
   * radius `R`, for the star under the hand, the one being fed, a remnant picked up.
   */
  reticle(x: number, y: number, R: number, c: Col, k: number): void {
    if (k <= 0.01) return;
    const a = R * 0.38;
    for (const sx of [-1, 1]) {
      for (const sy of [-1, 1]) {
        const cx = x + sx * R;
        const cy = y + sy * R;
        this.filaments.push([cx - sx * a, cy, cx, cy, cx, cy - sy * a], c, c, 1.6, 0.55 * k, 0.05 * k, false);
      }
    }
  }

  /** A thin ring of light (a filament closing on itself): the photon ring, a countdown. */
  circle(x: number, y: number, R: number, c: Col, core: number, sheath: number, half = 2): void {
    const n = Math.max(16, Math.min(48, Math.round(R * 0.8)));
    const pts = this.loop.subarray(0, (n + 1) * 2);
    for (let j = 0; j <= n; j++) {
      const a = (j / n) * Math.PI * 2;
      pts[j * 2] = x + Math.cos(a) * R;
      pts[j * 2 + 1] = y + Math.sin(a) * R;
    }
    this.filaments.push(pts, c, c, half, core, sheath, false);
  }

  /**
   * The feeding stream from a cloud (x0, y0) to a star (x1, y1): a luminous ribbon along a gentle arc,
   * three strands twisting about each other inside a soft sheath that widens into a glowing foot in
   * the cloud, heating from hydrogen pink to white-hot as it falls, energy crawling along it.
   */
  stream(x0: number, y0: number, x1: number, y1: number, t: number, k: number): void {
    const dx = x1 - x0;
    const dy = y1 - y0;
    const L = Math.hypot(dx, dy);
    if (L < 8 || k <= 0.01) return;
    const nx = -dy / L;
    const ny = dx / L;
    const bend = Math.min(60, L * 0.28);
    const n = this.filaments.segments(Math.max(16, Math.min(56, Math.round(L / 5))));
    const pts = new Float32Array((n + 1) * 2);
    const core = new Float32Array(n + 1);
    const sheath = new Float32Array(n + 1);
    const path = (u: number, off: number, j: number) => {
      const b = 4 * u * (1 - u) * bend;
      pts[j * 2] = x0 + dx * u + nx * (b + off);
      pts[j * 2 + 1] = y0 + dy * u + ny * (b + off);
    };
    // The sheath: widest and brightest at the foot, thinning toward the star.
    for (let j = 0; j <= n; j++) {
      const u = j / n;
      path(u, 0, j);
      core[j] = 0;
      sheath[j] = (0.5 * (1 - u) ** 1.5 + 0.08) * k;
    }
    this.filaments.push(pts, H_PINK, [0.9, 0.55, 0.7], 14, 0, sheath, true);
    // The strands: thin cores twisting about the arc, brightening as the gas falls and heats.
    for (let s = 0; s < 3; s++) {
      const ph = s * 2.094 + t * 2.2;
      for (let j = 0; j <= n; j++) {
        const u = j / n;
        const amp = 5.5 * (1 - u) * (0.4 + u) * 1.6;
        path(u, amp * Math.sin(ph + u * 9), j);
        const crawl = 0.75 + 0.5 * Math.max(0, Math.sin(u * 22 - t * 9 + s * 1.7));
        core[j] = (0.25 + 1.5 * u * u) * crawl * k;
        sheath[j] = (0.1 + 0.25 * u) * k;
      }
      this.filaments.push(pts, H_PINK, HOT_WHITE, 3.2, core, sheath, true);
    }
    // The foot lights the cloud it is drawn from; where it lands, the star's surroundings glow hot.
    this.light(x0, y0, 60, [0.1 * k, 0.025 * k, 0.035 * k], 0.6 * k);
    this.light(x1, y1, 40, [0.05 * k, 0.045 * k, 0.06 * k], 0.8 * k);
  }

  /** Gas thrown off by a dying star: a short streak of its colour along its motion, fading as it slows. */
  debris(x: number, y: number, vx: number, vy: number, c: Col, k: number): void {
    if (k <= 0.01) return;
    const tx = x - vx * 0.06;
    const ty = y - vy * 0.06;
    const l = Math.max(1, lum(c));
    const cc: Col = [c[0] / l, c[1] / l, c[2] / l];
    this.filaments.push([tx, ty, (tx + x) / 2, (ty + y) / 2, x, y], cc, cc, 3, [0, 0.15 * k, 0.45 * k], [0, 0.08 * k, 0.14 * k], false);
  }

  /** A gamma-ray burst: two beams of light straight out across the disk, a white-hot core in a violet sheath. */
  beam(x: number, y: number, a: number, k: number): void {
    if (k <= 0.01) return;
    const L = 2400;
    for (const s of [1, -1]) {
      const ex = x + Math.cos(a) * L * s;
      const ey = y + Math.sin(a) * L * s;
      this.filaments.push([x, y, x + (ex - x) * 0.1, y + (ey - y) * 0.1, x + (ex - x) * 0.4, y + (ey - y) * 0.4, ex, ey], [0.9, 0.85, 1.0], [0.55, 0.5, 1.0], 9, [2.6 * k, 1.8 * k, 0.8 * k, 0], [0.3 * k, 0.2 * k, 0.08 * k, 0], false);
    }
    this.light(x, y, 260, [0.12 * k, 0.11 * k, 0.16 * k], 1.5 * k);
  }

  /** The Sun seen from far: a warm point of light, its size fixed on screen (`px` world units per pixel), and a thin ring. */
  marker(x: number, y: number, px: number, k: number): void {
    const r = this.r;
    if (!r || k <= 0.01) return;
    r.top.push(x, y, 2.2 * px, 2.6 * k, 2.25 * k, 1.5 * k, 1, Shape.Glow);
    this.circle(x, y, 15 * px, [1.0, 0.86, 0.62], 0.45 * k, 0.04 * k, 1.5 * px);
  }

  /**
   * A dead star feeding on its companion: gas drawn off the donor in a thin stream that swings round the
   * accretor into a small hot disk, which glows and lights the dust (an X-ray binary, a black hole's
   * hotter than a white dwarf's).
   */
  accretion(dx: number, dy: number, ax: number, ay: number, bh: boolean, k: number, t: number): void {
    if (k <= 0.01) return;
    const n = 12;
    const pts = new Float32Array((n + 1) * 2);
    const core = new Float32Array(n + 1);
    const vx = ax - dx;
    const vy = ay - dy;
    for (let j = 0; j <= n; j++) {
      const u = j / n;
      // Bends sideways as it falls (the orbit carries it), ending tangent to the disk.
      const side = Math.sin(u * Math.PI) * 0.25;
      pts[j * 2] = dx + vx * u - vy * side;
      pts[j * 2 + 1] = dy + vy * u + vx * side;
      core[j] = (0.15 + 0.9 * u * u) * (0.8 + 0.25 * Math.sin(u * 14 - t * 10)) * k;
    }
    const hot: Col = bh ? [0.75, 0.85, 1.0] : [0.9, 0.92, 1.0];
    this.filaments.push(pts, [1.0, 0.45, 0.4], hot, 2.4, core, 0.08 * k, true);
    this.circle(ax, ay, bh ? 6.5 : 5, hot, (bh ? 1.3 : 0.9) * k, 0.18 * k, 1.8);
    this.light(ax, ay, 40, [0.12 * k, 0.12 * k, 0.16 * k], 0.6 * k);
  }

  /** How full a white dwarf is toward the Chandrasekhar limit: a thin arc that closes as it nears 1.4 Suns. */
  gauge(x: number, y: number, R: number, fill: number, k: number): void {
    if (fill <= 0.01 || k <= 0.01) return;
    const n = Math.max(4, Math.round(40 * fill));
    const pts = this.loop.subarray(0, (n + 1) * 2);
    for (let j = 0; j <= n; j++) {
      const a = -Math.PI / 2 + (j / n) * Math.PI * 2 * fill;
      pts[j * 2] = x + Math.cos(a) * R;
      pts[j * 2 + 1] = y + Math.sin(a) * R;
    }
    this.filaments.push(pts, [0.85, 0.88, 1.0], [0.85, 0.88, 1.0], 1.6, 0.55 * fill * k, 0.04 * k, false);
  }

  // ─── FxLook: the era's effects, restyled

  flash(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * (1 - t);
    const rr = this.r;
    if (!rr || f <= 0.003) return;
    rr.top.push(x, y, Math.min(4.5, 1.6 + size * 0.03), r * f * 1.6, g * f * 1.6, b * f * 1.6, 1, Shape.Glow);
    rr.top.push(x, y, Math.min(60, size * 0.35), r * f * 0.18, g * f * 0.18, b * f * 0.18, 1, Shape.Glow);
    this.light(x, y, size * 1.8, [r * f * 0.05, g * f * 0.05, b * f * 0.05]);
    const l = lum([r, g, b]) * f;
    this.speckLights.push({ weight: l * size * 0.02, item: { x, y, intensity: 1.2 * l, radius: size * 1.4, width: 0 } });
  }

  ring(x: number, y: number, radius: number, r: number, g: number, b: number, t: number): void {
    const f = Math.pow(1 - t, 1.6);
    if (f <= 0.01) return;
    const l = lum([r, g, b]);
    if (radius < 0) return;
    // A light front through the dust (a light echo), and the blast wave throwing the motes outward.
    this.fronts.push({ weight: l * f, item: { x, y, radius, width: 16 + radius * 0.08, color: [r * 0.05 * f, g * 0.05 * f, b * 0.05 * f] } });
    this.kicks.push({ weight: l * f, item: { x, y, radius: radius * 0.8, push: 900 * Math.min(2, l) * f } });
    this.speckLights.push({ weight: l * f, item: { x, y, intensity: (3 * l * f) / (1 + radius / 600), radius, width: 26 + radius * 0.1 } });
  }

  spark(x: number, y: number, vx: number, vy: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = 1 - t;
    const k = Math.min(2, size * 0.3) * f * f;
    if (k <= 0.01) return;
    const tx = x - vx * 0.03;
    const ty = y - vy * 0.03;
    const l = Math.max(1, lum([r, g, b]));
    const c: Col = [r / l, g / l, b / l];
    this.filaments.push([tx, ty, (tx + x) / 2, (ty + y) / 2, x, y], c, [1, 1, 1], 3, [0, 0.4 * k, 1.2 * k], [0, 0.04 * k, 0.08 * k], false);
  }

  puff(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * Math.min(1, t * 6);
    if (f > 0.01) this.light(x, y, size, [r * 0.1 * f, g * 0.1 * f, b * 0.1 * f]);
  }

  /** Ends the frame: the strongest lights, fronts, pushes and shells go to the layers (each has a few slots). */
  end(): void {
    const top = <T>(list: Ranked<T>[], n: number): T[] => list.sort((a, b) => b.weight - a.weight).slice(0, n).map((x) => x.item);
    const d = this.disk;
    d.lights = top(this.lights, 8);
    d.fronts = top(this.fronts, 4);
    d.clouds = this.clouds.slice(0, 12);
    d.hot = this.hots.slice(0, 8);
    d.shells = top(this.shells, 6);
    this.motes.kicks = top(this.kicks, 4);
    this.motes.lights = top(this.speckLights, 8);
  }
}
