<!--
  What this era is making, with rates, our universe's value for comparison, and the dot scale.
-->
<script lang="ts">
  import { count, type NumParts } from '../../core/format';
  import type { StockView } from '../../core/era';
  import Num from '../common/Num.svelte';
  import Tip from '../common/Tip.svelte';
  import { game, track } from '../store.svelte';
  import { formatStock } from '../view';

  const g = game();

  const fmt = (s: StockView, value: number): NumParts => formatStock(g, s, value);

  const v = $derived.by(() => {
    track();
    const era = g.era;
    return { stocks: era?.stocks() ?? [], scale: era?.dotScale?.() ?? null };
  });
</script>

{#if v.stocks.length > 0}
  <section class="stocks">
    {#each v.stocks as s (s.id)}
      <Tip side="above" width="19rem">
        <div class="row">
          <span class="label name">{s.label}</span>
          <!-- svelte-ignore a11y_no_noninteractive_tabindex (the row has no box of its own; the value takes focus for the tooltip) -->
          <span class="val" tabindex="0"><Num parts={fmt(s, s.value)} /></span>
          {#if s.rate !== undefined && s.rate > 0}
            <span class="rate"><Num parts={fmt(s, s.rate)} sign="+" />/s</span>
          {:else if s.ours !== undefined}
            <span class="rate ours">ours <Num parts={fmt(s, s.ours)} /></span>
          {:else}
            <span class="rate"></span>
          {/if}
        </div>
        {#snippet tip()}
          {s.hint ?? ''}
          {#if s.ours !== undefined}<p class="ours-line">In our universe: <Num parts={fmt(s, s.ours)} /></p>{/if}
        {/snippet}
      </Tip>
    {/each}
    {#if v.scale}
      <div class="scale">1 dot = <Num parts={count(v.scale.value, g.state.settings.notation)} /> {v.scale.unit}</div>
    {/if}
  </section>
{/if}

