/**
 * Persistence: versioned, compressed, with rotating backups.
 *
 * Storage sits behind an adapter: the web build uses localStorage; the Steam build will provide a
 * file-backed adapter (synced by Steam Cloud) without touching anything here.
 */
import LZ from 'lz-string';
import { SAVE_VERSION, defaultState, type GameState } from './state';

export interface StorageAdapter {
  read(key: string): string | null;
  write(key: string, value: string): void;
  remove(key: string): void;
}

export class LocalStorageAdapter implements StorageAdapter {
  read(key: string): string | null {
    try {
      return localStorage.getItem(key);
    } catch {
      return null;
    }
  }
  write(key: string, value: string): void {
    localStorage.setItem(key, value);
  }
  remove(key: string): void {
    try {
      localStorage.removeItem(key);
    } catch {
      /* storage unavailable: nothing to remove */
    }
  }
}

export class MemoryStorageAdapter implements StorageAdapter {
  readonly data = new Map<string, string>();
  read(key: string): string | null {
    return this.data.get(key) ?? null;
  }
  write(key: string, value: string): void {
    this.data.set(key, value);
  }
  remove(key: string): void {
    this.data.delete(key);
  }
}

const EXPORT_PREFIX = 'YLEM1:';
const BACKUP_COUNT = 3;
const BACKUP_INTERVAL_MS = 5 * 60 * 1000;

/** Schema migrations, keyed by the version they upgrade *from*. */
const MIGRATIONS: Record<number, (s: Record<string, unknown>) => Record<string, unknown>> = {
  // v1 → v2: our vacuum's lifetime was 10¹⁶¹ years; Andreassen, Frost & Schwartz (2018) give 10¹³⁹.
  // Every stored universe moves with it, so its distance from ours stays what it was.
  1: (s) => {
    const shift = (c: unknown) => {
      const k = c as { logVacuum?: unknown } | null | undefined;
      if (k && typeof k.logVacuum === 'number') k.logVacuum -= 22;
    };
    shift((s.run as { constants?: unknown } | undefined)?.constants);
    const meta = s.meta as { lineage?: { constants?: unknown }[]; seeds?: unknown[] } | undefined;
    for (const e of meta?.lineage ?? []) shift(e.constants);
    for (const c of meta?.seeds ?? []) shift(c);
    return s;
  },
};

/**
 * Fills in any fields missing from a loaded save with defaults, recursively, so additions to the
 * schema never break old saves. Arrays and records of user data are taken as-is.
 */
function mergeDefaults<T>(defaults: T, loaded: unknown): T {
  if (loaded === undefined || loaded === null) return defaults;
  // A null default (the first universe's parent, the last universe's ending) says nothing about the
  // shape of what is stored there: take what was saved.
  if (defaults === null) return loaded as T;
  if (typeof defaults !== 'object' || Array.isArray(defaults)) {
    return (typeof loaded === typeof defaults ? loaded : defaults) as T;
  }
  if (typeof loaded !== 'object' || Array.isArray(loaded)) return defaults;
  const out: Record<string, unknown> = { ...(loaded as Record<string, unknown>) };
  for (const [k, dv] of Object.entries(defaults as Record<string, unknown>)) {
    const lv = (loaded as Record<string, unknown>)[k];
    // Open-ended maps (phenomena levels, flags, era blobs) have empty defaults: keep loaded content.
    const isOpenMap =
      typeof dv === 'object' && dv !== null && !Array.isArray(dv) && Object.keys(dv).length === 0;
    out[k] = isOpenMap ? (lv ?? dv) : mergeDefaults(dv, lv);
  }
  return out as T;
}

/** Replaces non-finite numbers (a corrupted or overflowed save) with zero, recursively. */
function sanitize(value: unknown): unknown {
  if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
  if (Array.isArray(value)) return value.map(sanitize);
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) out[k] = sanitize(v);
    return out;
  }
  return value;
}

export function migrate(raw: Record<string, unknown>, now: number): GameState {
  let data = raw;
  let v = typeof data.v === 'number' ? data.v : 0;
  if (v > SAVE_VERSION) throw new Error(`Save is from a newer version of the game (v${v}).`);
  while (v < SAVE_VERSION) {
    const step = MIGRATIONS[v];
    if (step) data = step(data);
    v++;
  }
  const seed = typeof (data.run as { seed?: unknown } | undefined)?.seed === 'number'
    ? (data.run as { seed: number }).seed
    : 1;
  const merged = mergeDefaults(defaultState(seed, now), sanitize(data));
  merged.v = SAVE_VERSION;
  return merged;
}

export function serialize(state: GameState): string {
  return LZ.compressToUTF16(JSON.stringify(state));
}

export function deserialize(text: string, now: number): GameState {
  const json = LZ.decompressFromUTF16(text);
  if (!json) throw new Error('Save data could not be decompressed.');
  return migrate(JSON.parse(json) as Record<string, unknown>, now);
}

export function exportString(state: GameState): string {
  return EXPORT_PREFIX + LZ.compressToBase64(JSON.stringify(state));
}

export function importString(text: string, now: number): GameState {
  const trimmed = text.trim();
  if (!trimmed.startsWith(EXPORT_PREFIX)) throw new Error('That does not look like a Ylem save.');
  const json = LZ.decompressFromBase64(trimmed.slice(EXPORT_PREFIX.length));
  if (!json) throw new Error('That save is damaged or incomplete.');
  return migrate(JSON.parse(json) as Record<string, unknown>, now);
}

export class SaveManager {
  private lastBackup = 0;

  constructor(
    private readonly storage: StorageAdapter,
    private readonly key = 'ylem.save',
  ) {}

  load(now: number): GameState | null {
    const primary = this.storage.read(this.key);
    if (primary) {
      try {
        return deserialize(primary, now);
      } catch (err) {
        console.warn('Primary save unreadable, trying backups.', err);
      }
    }
    for (let i = 0; i < BACKUP_COUNT; i++) {
      const b = this.storage.read(`${this.key}.bak${i}`);
      if (!b) continue;
      try {
        return deserialize(b, now);
      } catch {
        /* try the next backup */
      }
    }
    return null;
  }

  save(state: GameState, now: number): void {
    state.saved = now;
    const text = serialize(state);
    this.storage.write(this.key, text);
    if (now - this.lastBackup >= BACKUP_INTERVAL_MS) {
      for (let i = BACKUP_COUNT - 1; i > 0; i--) {
        const prev = this.storage.read(`${this.key}.bak${i - 1}`);
        if (prev) this.storage.write(`${this.key}.bak${i}`, prev);
      }
      this.storage.write(`${this.key}.bak0`, text);
      this.lastBackup = now;
    }
  }

  wipe(): void {
    this.storage.remove(this.key);
    for (let i = 0; i < BACKUP_COUNT; i++) this.storage.remove(`${this.key}.bak${i}`);
  }
}
