<!--
  The Clock: the spine of the game. Era, cosmic time, temperature, and the next epoch step with its
  goal (what to do to get there), whose progress runs along the card's foot.
-->
<script lang="ts">
  import { cosmicTime, energy, temperature } from '../../core/format';
  import Num from '../common/Num.svelte';
  import Tip from '../common/Tip.svelte';
  import { game, track } from '../store.svelte';
  import { advance as advanceStep } from '../view';

  const g = game();

  const v = $derived.by(() => {
    track();
    const run = g.state.run;
    const def = g.eraDef;
    const step = g.currentStep;
    const next = g.nextStep;
    const goal = g.stepGoal();
    return {
      title: def.title,
      epoch: def.epoch,
      t: run.time,
      T: step.T,
      next,
      can: g.canAdvance(),
      blocker: g.stepBlocker(),
      goal,
      progress: goal ? goal.progress : next ? Math.min(1, run.energy / Math.max(1, next.cost)) : 0,
      unit: (run.joules ? 'J' : 'eV') as 'J' | 'eV',
      finale: g.inFinale,
      notation: g.state.settings.notation,
      last: g.state.run.step === g.steps().length - 2,
    };
  });

  const advance = () => advanceStep(g);
</script>

<section class="clock">
  <h1 class="era">{v.title}</h1>
  <div class="label epoch">{v.epoch}</div>
  <div class="readings">
    <Tip side="below">
      <!-- svelte-ignore a11y_no_noninteractive_tabindex (focusable so keyboard players get the tooltip) -->
      <span class="reading" tabindex="0"><span class="k" aria-hidden="true">t</span><span class="sr-only">Cosmic time</span><Num parts={cosmicTime(v.t)} /></span>
      {#snippet tip()}
        Time since the beginning. Each epoch step moves it forward to the next milestone of cosmic history.
      {/snippet}
    </Tip>
    <Tip side="below">
      <!-- svelte-ignore a11y_no_noninteractive_tabindex (focusable so keyboard players get the tooltip) -->
      <span class="reading" tabindex="0"><span class="k" aria-hidden="true">T</span><span class="sr-only">Temperature</span><Num parts={temperature(v.T)} /></span>
      {#snippet tip()}
        Temperature of the universe. It falls as space expands, and what can exist depends on it.
      {/snippet}
    </Tip>
  </div>

  {#if v.next && !v.finale}
    <div class="next" class:ready={v.can} class:final={v.last}>
      <button class="advance" onclick={advance} aria-keyshortcuts="T" aria-describedby={v.goal ? 'step-goal' : undefined}>
        <span class="arrow" aria-hidden="true">→</span>
        <span class="sr-only">Advance to</span>
        <span class="what">
          <span class="when"><Num parts={cosmicTime(v.next.t)} /></span>
          <span class="name">{v.next.label}</span>
        </span>
        <span class="side">
          <span class="sr-only">, costs</span>
          <span class="cost"><Num parts={energy(v.next.cost, v.unit, v.notation)} /></span>
          <kbd aria-hidden="true">T</kbd>
        </span>
      </button>
      {#if v.goal}
        <p class="goal" id="step-goal">
          <span class="aim">{v.goal.text}</span>
          {#if v.goal.detail}<span class="why">{v.goal.detail}</span>{/if}
        </p>
      {/if}
      <span class="track" aria-hidden="true"><span class="bar" style="--p:{v.progress}"></span></span>
    </div>
    {#if !v.goal && v.blocker && v.blocker !== 'In progress'}
      <div class="blocker">{v.blocker}</div>
    {/if}
  {/if}
</section>

