<!--
  Text anchored in the scene (counters, markers, element tiles), positioned from world coordinates.
  In the eras seen through the frame it is set in the frame's type, as captions of the same instrument.
-->
<script lang="ts">
  import { usesFrameType } from '../frame/eras';
  import { game, track } from '../store.svelte';

  const g = game();
  const v = $derived.by(() => {
    track();
    const era = g.era;
    const r = g.renderer;
    const framed = usesFrameType(g.state.run.era);
    if (!era?.labels || !r) return { framed, labels: [] };
    const labels = era.labels().map((l) => {
      const [sx, sy] = r.camera.worldToScreen(l.x, l.y, r.cssW, r.cssH);
      return { ...l, sx, sy };
    });
    return { framed, labels };
  });
</script>

<div class="labels" class:framed={v.framed}>
  {#each v.labels as l (l.id)}
    {#if l.tone === 'tile'}
      <div class="wl tile" style="transform: translate({l.sx}px, {l.sy}px); opacity: {l.opacity ?? 1}; --c: {l.color ?? 'var(--ink-2)'}">
        {#if l.sub}<span class="z">{l.sub}</span>{/if}
        <span class="sym">{l.text}</span>
      </div>
    {:else}
      <div class="wl {l.tone ?? 'quiet'}" style="transform: translate({l.sx}px, {l.sy}px); opacity: {l.opacity ?? 1}">
        {l.text}
      </div>
    {/if}
  {/each}
</div>

