/**
 * The Galaxies: deep intergalactic space seen from far above the group. Distant galaxies are tiny
 * smudges that redden and fade as dark energy carries them off; faint filaments of the cosmic web
 * feed the group while it still has fresh gas arriving; a dim glow of stripped stars hangs over the
 * bound group. In the finale, everything beyond the group is gone.
 */
import type { BackgroundDef } from '../../render/renderer';

export interface GalaxiesBgParams {
  /** 0 → 1: how far the distant universe has slipped away (reddening, then gone). */
  redshift: number;
  /** Strength of the cosmic-web filaments feeding the group (declines with the steps). */
  inflow: number;
  /** World position of the group's centre and its bound radius. */
  cx: number;
  cy: number;
  bound: number;
  /** Intragroup light from tidal debris. */
  haze: number;
  pulse: number;
}

export function galaxiesBackground(params: GalaxiesBgParams): BackgroundDef {
  return {
    id: 'galaxies',
    fragment: /* glsl */ `
uniform float uRedshift;
uniform float uInflow;
uniform vec3 uGroup;
uniform float uHaze;
uniform float uPulse;

// A sparse field of distant galaxies: one small, tilted, elongated smudge in a few cells.
float smudges(vec2 w, float cell, float density, out float hue) {
  vec2 c = floor(w / cell);
  hue = hash12(c + 7.1);
  if (hash12(c) < 1.0 - density) return 0.0;
  vec2 o = hash22(c + 2.3) * 0.6 + 0.2;
  vec2 f = fract(w / cell) - o;
  float a = hash12(c + 5.9) * 6.2832;
  vec2 q = mat2(cos(a), -sin(a), sin(a), cos(a)) * f;
  q.y *= 1.6 + 2.4 * hash12(c + 9.4);
  return exp(-dot(q, q) * (240.0 + 300.0 * hash12(c + 1.7))) * (0.25 + 0.75 * hash12(c + 3.3));
}

void main() {
  vec2 world = uView.xy + (vUv * 2.0 - 1.0) * uView.zw * vec2(1.0, -1.0);
  vec2 p = world / 1000.0;
  float t = uTime * 0.002;
  vec3 col = vec3(0.0025, 0.0025, 0.005);

  // The cosmic web: thin filaments converging on the group, fading as the gas supply is cut off.
  float n = fbm(vec3(p * 1.1, t), 4);
  float ridge = pow(max(0.0, 1.0 - abs(n) * 2.3), 6.0);
  float toward = smoothstep(2.2, 0.3, length(world - uGroup.xy) / max(uGroup.z, 1.0));
  col += vec3(0.012, 0.016, 0.03) * ridge * uInflow * (0.4 + 0.6 * toward);

  // Distant galaxies, white-gold today, reddening and thinning as the expansion carries them away.
  float h1;
  float h2;
  float g = smudges(world, 70.0, 0.11, h1) * 0.45 + smudges(world + 333.0, 31.0, 0.06, h2) * 0.25;
  vec3 near = mix(vec3(1.0, 0.9, 0.75), vec3(0.75, 0.82, 1.0), h1);
  vec3 far = vec3(1.0, 0.32, 0.12);
  float fade = clamp(1.0 - uRedshift * 1.1, 0.0, 1.0);
  col += mix(near, far, smoothstep(0.0, 0.8, uRedshift)) * g * fade;

  // Stars stripped in collisions still shine faintly across the group.
  float d = length(world - uGroup.xy) / max(uGroup.z, 1.0);
  col += vec3(0.02, 0.016, 0.014) * uHaze * exp(-d * d * 2.2) * (0.7 + 0.3 * fbm(vec3(p * 2.5, t), 2));

  outColor = vec4(col * (1.0 + uPulse), 1.0);
}`,
    uniforms: (p) => {
      p.f1('uRedshift', params.redshift).f1('uInflow', params.inflow).f1('uHaze', params.haze).f1('uPulse', params.pulse);
      p.f3('uGroup', params.cx, params.cy, params.bound);
    },
  };
}
