/**
 * The Long Night simulation: the home galaxy from 10¹¹ years to the evaporation of its last black hole.
 *
 * The galaxy is a swarm of star particles on randomly tilted orbits (an elliptical galaxy seen from far
 * away), each an equal share of Era VI's final stellar mass; what each particle is (an old star, a red
 * or blue dwarf, a white, black or brown dwarf, a neutron star) follows the steps. Black holes (the
 * central one and eight left by massive stars) feed while the player holds on them: stars in reach
 * spiral into an accretion disk that shines with the efficiency of the hole's spin (Novikov & Thorne)
 * and spins it up. Letting go spills the disk through the ergosphere, a burst paid for by the hole's
 * spin (the Penrose process, dramatized). Feed too much at once and the disk passes the Eddington limit
 * and blows away. Later the galaxy evaporates, dead stars dissolve (if protons decay), and the black
 * holes evaporate by Hawking radiation, each in a final flash.
 */
import type { EraModule, OfflineReport, PointerInfo, StockView, WorldLabel } from '../../core/era';
import type { Game } from '../../core/game';
import { count, toText } from '../../core/format';
import { Rng } from '../../core/rng';
import type { RGB } from '../../render/color';
import { Fx, FxPool } from '../../render/fx';
import { LineStyle } from '../../render/lines';
import type { BackgroundDef, Renderer } from '../../render/renderer';
import { Shape } from '../../render/sprites';
import { nightBackground, type NightBgParams } from './background';
import { fateOf, type Fate } from '../../core/multiverse';
import { accretionEfficiency, hawkingYears, Kind, kindAt, shines, SPIN_MAX, spinEnergyShare } from './model';

/** eV per light unit per second, before the step weight. */
const E_UNIT = 1.5e51;
const N_STARS = 3200;
/** Scale radius of the galaxy's star profile and its outer edge, in world units. */
const SCALE = 70;
const EDGE = 470;
/** The galaxy is an E2: flattened a little on the sky. */
const FLAT = 0.84;
/** Orbital speed scale (world units per second) of the stars. */
const V_ORBIT = 22;
/** Light units of starlight per particle of each kind (Star, Red, Blue, White, Neutron, Brown, Black). */
const LUM = [0.06, 0.03, 0.05, 0.0012, 0.0006, 0, 0];
/** Particles a hole draws in per second while held (central, stellar), and the central one on its own. */
const FEED_CENTRAL = 5;
const FEED_STELLAR = 3;
/**
 * Stars the central hole draws in on its own per second, by step: later steps span far more time, so
 * more stars wander into it per second of play.
 */
const PASSIVE_FEED = [0.5, 0.7, 1, 8, 9, 9, 0, 0, 0];
/** Share of eaten stars replaced from the galaxy's vast outskirts (the visible core is a small part). */
const RESPAWN = 0.85;
/** Reach of a hole in world units (central, stellar), before upgrades. */
const REACH_CENTRAL = 120;
const REACH_STELLAR = 55;
/** Matter a disk holds before it reaches the Eddington limit, in particle shares (central, stellar). */
const CAP_CENTRAL = 40;
const CAP_STELLAR = 14;
/** Seconds for a disk to drain into its hole, and light units per share drained (× efficiency). */
const DISK_TAU = 12;
const ACC_LIGHT = 30;
/** Light-unit-seconds of a spill per share at full spin, and the share of spin a full spill takes. */
const SPILL_UNITS = 65;
const SPILL_SPIN = 0.25;
/** Spin gained per full disk fed (before Frame Dragging), and how hard the central hole is to spin. */
const SPINUP = 0.16;
const INERTIA_CENTRAL = 4;
/** Flare of a star torn apart as it is drawn in, in light-unit-seconds. */
const TDE_UNITS = 2;
/** Stars drifting inward toward the centre per second (the loss cone refilling), before upgrades. */
const REFILL = 2.5;
/** New stars from brown-dwarf collisions per second, before upgrades (steps 3–5). */
const BROWN_RATE = 0.08;
/** Light of a newly lit star while it lasts, and how long it lasts. */
const NEW_STAR_LIGHT = 0.4;
const NEW_STAR_LIFE = 40;
/** Glow of a dead star kept warm by captured dark matter, per level of the upgrade. */
const WIMP_LIGHT = 0.004;
/** Gravitational-wave burst of a stellar hole merging into the central one, per 20 Suns. */
const GW_UNITS = 12000;
/** Hawking glow of a 20-Sun hole in the Black Hole Era, in light units (∝ 1/√M here, capped). */
const HAWK_LIGHT = 30;
/** Final flash of an evaporating stellar hole, per 20 Suns. */
const FLASH_UNITS = 1500;
/** How close to the flash a press still catches it (seconds before it). */
const CATCH_WINDOW = 0.45;
const MERGE_TIME = 3;

const enum St {
  Free,
  Falling,
  Ejected,
  Dissolving,
  Gone,
}

interface Hole {
  central: boolean;
  /** Mass in Suns. */
  m: number;
  spin: number;
  /** Matter in the disk, in particle shares. */
  disk: number;
  /** Orbit in the galaxy (stellar holes): radius, phase, angular speed, tilt and node. */
  or: number;
  th: number;
  om: number;
  ci: number;
  cn: number;
  sn: number;
  x: number;
  y: number;
  /** Direction of the disk's long axis on screen. */
  tilt: number;
  /** Seconds since the last spill and its size (jets). */
  jetT: number;
  jetK: number;
  /** Seconds to the final flash while evaporating, else −1. */
  evap: number;
  evapTotal: number;
  /** Pressed just before its flash. */
  caught: boolean;
  /** Seconds into a merger with the central hole, else −1. */
  merge: number;
  mx: number;
  my: number;
  alive: boolean;
  /** Seconds since matter last arrived (draws the stream). */
  fedT: number;
  /** Stars owed to the disk (fractional, from the feeding rate). */
  feedAcc: number;
}

interface SavedHole {
  central: boolean;
  m: number;
  spin: number;
  disk: number;
  or: number;
  th: number;
  om: number;
  ci: number;
  cn: number;
  sn: number;
  tilt: number;
  alive: boolean;
  /** Seconds left before its final flash, once it has begun to evaporate (older saves lack it). */
  evap?: number;
  evapTotal?: number;
}

export interface NightState {
  holes: SavedHole[];
  /** Seed of the galaxy's star particles, and how many are still in it. */
  seed: number;
  left: number;
  spills: number;
  fulls: number;
  blowouts: number;
  tdes: number;
  newStars: number;
  mergers: number;
  flashes: number;
  caught: number;
  everHeld: boolean;
  everSpilled: boolean;
  evaporated: boolean;
  dissolved: boolean;
  /** Light units harvested from black holes (spills, mergers, flashes). */
  harvest: number;
}

function defaults(): NightState {
  return {
    holes: [],
    seed: 0,
    left: N_STARS,
    spills: 0,
    fulls: 0,
    blowouts: 0,
    tdes: 0,
    newStars: 0,
    mergers: 0,
    flashes: 0,
    caught: 0,
    everHeld: false,
    everSpilled: false,
    evaporated: false,
    dissolved: false,
    harvest: 0,
  };
}

/** Shadow radius on screen (not to scale: a real one would be a speck). */
function shadowRadius(h: Hole): number {
  return h.central ? 18 + 3 * Math.log10(Math.max(1, h.m / 1e8)) : 4 + 1.4 * Math.log2(h.m / 5 + 1);
}

export class NightEra implements EraModule {
  private readonly s: NightState;
  private readonly fx = new FxPool(500);
  private readonly bgParams: NightBgParams;
  private readonly bg: BackgroundDef;
  private holes: Hole[] = [];

  // Star particles.
  private readonly pr = new Float32Array(N_STARS);
  private readonly pth = new Float32Array(N_STARS);
  private readonly pom = new Float32Array(N_STARS);
  private readonly pci = new Float32Array(N_STARS);
  private readonly pcn = new Float32Array(N_STARS);
  private readonly psn = new Float32Array(N_STARS);
  private readonly pu = new Float32Array(N_STARS);
  private readonly pst = new Uint8Array(N_STARS);
  private readonly ptgt = new Int16Array(N_STARS);
  private readonly pt = new Float32Array(N_STARS);
  private readonly pdur = new Float32Array(N_STARS);
  private readonly pfx = new Float32Array(N_STARS);
  private readonly pfy = new Float32Array(N_STARS);
  private readonly pvx = new Float32Array(N_STARS);
  private readonly pvy = new Float32Array(N_STARS);
  /** Seconds left of a star newly lit by a brown-dwarf collision. */
  private readonly pborn = new Float32Array(N_STARS);
  private readonly px = new Float32Array(N_STARS);
  private readonly py = new Float32Array(N_STARS);

  private t = 0;
  private idle = 0;
  /** Mass in Suns of the stars one particle stands for. */
  private shareSuns = 1.25e8;
  private refillAcc = 0;
  private brownAcc = 0;
  private holding = -1;
  private hover = -1;
  private flashGlow = 0;

  private disks = 1;
  private old = 1;
  private ergo = 1;
  private drag = 1;
  private edd = 1;
  private reach = 1;
  private tde = 1;
  private window = 0.12;
  private refill = 1;
  private brown = 1;
  private wimp = 0;
  private gw = 1;
  private hawking = 1;
  private unsub: (() => void)[] = [];

  private finaleT = -1;
  private finaleDone: (() => void) | null = null;
  private finaleFlashed = false;
  /** How this universe ends (it sets the steps, the late behaviour and the finale). */
  private fate: Fate = 'heat-death';
  /** Where a vacuum bubble appears, and its radius. */
  private bubbleX = 0;
  private bubbleY = 0;
  private bubbleR = 0;

  constructor(private readonly g: Game) {
    const run = g.state.run;
    this.s = (run.eras.night as NightState | undefined) ?? defaults();
    run.eras.night = this.s;
    this.bgParams = { glow: 1, tint: [1, 0.78, 0.52], dark: 0, pulse: 0 };
    this.bg = nightBackground(this.bgParams);
  }

  // ───────────────────────────────────────── lifecycle

  enter(fresh: boolean): void {
    const g = this.g;
    g.renderer?.setBackground(this.bg);
    this.refreshStats();
    this.unsub.push(g.stats.onChange(() => this.refreshStats()));
    this.syncStepFlags();
    const legacy = g.state.run.legacy;
    const stars = (legacy.finalStars || 40) * 1e10;
    this.shareSuns = stars / N_STARS;
    if (fresh || !this.s.holes.length) this.createHoles((legacy.finalBH || 4e8) as number);
    else for (const sh of this.s.holes) this.holes.push(this.restoreHole(sh));
    if (!this.s.seed) this.s.seed = (g.sim.next() * 2 ** 31) >>> 0;
    this.fate = fateOf(g.state.run.constants);
    // A save from before evaporation timers were kept, made after they began: start them again.
    const evaporating = (this.fate === 'heat-death' || this.fate === 'vacuum') && this.step >= 7 && g.steps().length - 1 > 7;
    if (!fresh && evaporating && !this.holes.some((h) => h.evap >= 0)) this.beginEvaporations();
    this.populate(this.step >= 5 && this.s.evaporated ? 0 : this.s.left);
    g.discover('age-primordial');
    g.discover('age-stelliferous');
    this.syncLook(true);
  }

  exit(): void {
    for (const u of this.unsub) u();
    this.unsub = [];
    const cam = this.g.renderer?.camera;
    if (cam) {
      cam.zoom = 1;
      cam.x = 0;
      cam.y = 0;
    }
  }

  private refreshStats(): void {
    const st = this.g.stats;
    this.disks = st.get('night.disks');
    this.old = st.get('night.old');
    this.ergo = st.get('night.ergo');
    this.drag = st.get('night.drag');
    this.edd = st.get('night.edd');
    this.reach = st.get('night.reach');
    this.tde = st.get('night.tde');
    this.window = st.get('night.window');
    this.refill = st.get('night.refill');
    this.brown = st.get('night.brown');
    this.wimp = st.get('night.wimp');
    this.gw = st.get('night.gw');
    this.hawking = st.get('night.hawking');
  }

  private get step(): number {
    return this.g.state.run.step;
  }

  private get weight(): number {
    return 10 ** this.step;
  }

  private gain(units: number, x?: number, y?: number): void {
    this.g.gain(units * E_UNIT * this.weight, x, y);
  }

  /** Gains that come from black holes count toward the harvest (legacy). */
  private harvest(units: number, x?: number, y?: number): void {
    this.s.harvest += units;
    this.gain(units, x, y);
  }

  private syncStepFlags(): void {
    for (let i = 1; i <= this.step; i++) this.g.setFlag(`night.step${i}`);
  }

  // ───────────────────────────────────────── setup

  private createHoles(centralMass: number): void {
    const rng = this.g.sim;
    this.holes.push(this.makeHole({ central: true, m: Math.max(1e7, centralMass), spin: 0.6, disk: 0, or: 0, th: 0, om: 0, ci: 1, cn: 1, sn: 0, tilt: rng.range(-0.5, 0.5), alive: true }));
    for (let k = 0; k < 8; k++) {
      const or = rng.range(120, 420);
      const node = rng.angle();
      const inc = Math.acos(rng.range(-1, 1));
      this.holes.push(
        this.makeHole({
          central: false,
          m: 5 + 35 * rng.next() ** 2,
          spin: rng.range(0.2, 0.9),
          disk: 0,
          or,
          th: rng.angle(),
          om: (rng.chance(0.5) ? 1 : -1) * this.orbitSpeed(or),
          ci: Math.cos(inc),
          cn: Math.cos(node),
          sn: Math.sin(node),
          tilt: rng.angle(),
          alive: true,
        }),
      );
    }
  }

  private makeHole(sh: SavedHole): Hole {
    const h: Hole = { ...sh, x: 0, y: 0, jetT: 99, jetK: 0, evap: sh.evap ?? -1, evapTotal: sh.evapTotal ?? 1, caught: false, merge: -1, mx: 0, my: 0, fedT: 99, feedAcc: 0 };
    this.placeHole(h);
    return h;
  }

  private restoreHole(sh: SavedHole): Hole {
    return this.makeHole(sh);
  }

  private orbitSpeed(r: number): number {
    return (V_ORBIT * Math.sqrt(r / (r + SCALE))) / Math.max(r, 8);
  }

  /** `n` star particles from the galaxy's seed (a cuspy profile, randomly tilted orbits). */
  private populate(n: number): void {
    const rng = new Rng(this.s.seed);
    for (let i = 0; i < N_STARS; i++) {
      // Hernquist profile: M(<r) ∝ r²/(r + a)².
      const q = Math.sqrt(rng.range(0.0004, 0.9));
      const r = Math.min(EDGE, (SCALE * q) / (1 - q));
      const inc = Math.acos(rng.range(-1, 1));
      const node = rng.angle();
      this.pr[i] = r;
      this.pth[i] = rng.angle();
      this.pom[i] = (rng.chance(0.55) ? 1 : -1) * this.orbitSpeed(r);
      this.pci[i] = Math.cos(inc);
      this.pcn[i] = Math.cos(node);
      this.psn[i] = Math.sin(node);
      this.pu[i] = rng.next();
      this.pst[i] = i < n ? St.Free : St.Gone;
      this.pborn[i] = 0;
    }
    this.positions();
  }

  // ───────────────────────────────────────── simulation

  update(dt: number): void {
    const g = this.g;
    const s = this.s;
    this.t += dt;
    this.idle += dt;
    const inFinale = this.finaleT >= 0;
    if (inFinale) this.updateFinale(dt);
    const step = Math.min(8, this.step);

    // Orbits.
    for (let i = 0; i < N_STARS; i++) if (this.pst[i] === St.Free) this.pth[i] += this.pom[i] * dt;
    // A collapsing universe draws its galaxy in; a tearing one pulls it apart.
    if (!inFinale && this.fate === 'crunch' && step >= 1) this.scaleGalaxy(Math.exp(-dt * 0.004 * step));
    if (!inFinale && this.fate === 'rip' && step >= 2) this.scaleGalaxy(Math.exp(dt * 0.0035 * (step - 1)));
    for (const h of this.holes) {
      if (!h.alive) continue;
      if (h.merge >= 0) continue;
      h.th += h.om * dt;
      if (!h.central) h.om = Math.sign(h.om || 1) * this.orbitSpeed(h.or);
      this.placeHole(h);
    }
    this.positions();

    // The loss cone refills: close passes nudge stars onto orbits that dive into the centre.
    if (step < 5 && !inFinale) {
      this.refillAcc += REFILL * this.refill * dt;
      while (this.refillAcc >= 1) {
        this.refillAcc -= 1;
        const i = g.sim.int(N_STARS);
        if (this.pst[i] === St.Free && this.pr[i] > 40) {
          this.pr[i] *= g.sim.range(0.35, 0.7);
          this.pom[i] = Math.sign(this.pom[i] || 1) * this.orbitSpeed(this.pr[i]);
        }
      }
    }

    // Feeding: the held hole draws in the stars around it; the central one also feeds a little on its
    // own, on stars that wander into it.
    const held = this.holding >= 0 ? this.holes[this.holding] : undefined;
    if (held && held.alive && held.evap < 0 && held.merge < 0 && !inFinale) {
      s.everHeld = true;
      this.idle = 0;
    }
    for (let k = 0; k < this.holes.length && !inFinale; k++) {
      const h = this.holes[k];
      if (!h.alive || h.evap >= 0 || h.merge >= 0) continue;
      const rate = k === this.holding ? (h.central ? FEED_CENTRAL : FEED_STELLAR) : h.central ? PASSIVE_FEED[step] : 0;
      h.feedAcc += rate * dt;
      while (h.feedAcc >= 1) {
        h.feedAcc -= 1;
        if (!this.drawIn(k)) {
          h.feedAcc = 0;
          break;
        }
      }
    }

    // Matter on its way in.
    let light = 0;
    for (let i = 0; i < N_STARS; i++) {
      const st = this.pst[i];
      if (st === St.Falling) {
        this.pt[i] += dt;
        if (this.pt[i] >= this.pdur[i]) this.arrive(i);
      } else if (st === St.Ejected) {
        this.pt[i] += dt;
        if (this.pt[i] > 7) this.pst[i] = St.Gone;
      } else if (st === St.Dissolving) {
        this.pt[i] += dt;
        if (this.pt[i] > this.pdur[i]) {
          this.pst[i] = St.Gone;
          light += 0.02 / dt;
        }
      }
    }

    // Disks: they drain into their holes and shine; overfed, they blow away.
    let fedLight = 0;
    for (let k = 0; k < this.holes.length; k++) {
      const h = this.holes[k];
      if (!h.alive) continue;
      h.jetT += dt;
      h.fedT += dt;
      if (h.disk > 0) {
        const drained = Math.min(h.disk, (h.disk * dt) / DISK_TAU);
        h.disk -= drained;
        if (h.disk < 0.02) h.disk = 0;
        h.m += drained * (h.central ? this.shareSuns * 0.05 : 0.6);
        fedLight += ((ACC_LIGHT * drained) / dt) * accretionEfficiency(h.spin) * this.disks;
      }
      if (h.disk >= this.capOf(h)) this.blowout(h);
    }
    light += fedLight;

    // Black holes merging into the central one, and evaporating ones.
    const central = this.holes[0];
    for (const h of this.holes) {
      if (!h.alive || h.central) continue;
      if (h.merge >= 0) {
        h.merge += dt;
        const k = Math.min(1, h.merge / MERGE_TIME);
        const a = k * k * 9;
        const r = (1 - k) ** 1.5;
        h.x = central.x + (h.mx * Math.cos(a) - h.my * Math.sin(a)) * r;
        h.y = central.y + (h.mx * Math.sin(a) + h.my * Math.cos(a)) * r;
        if (h.merge >= MERGE_TIME) this.mergeHole(h);
      } else if (h.evap >= 0) {
        h.evap -= dt;
        if (h.evap <= 0) this.flash(h);
      }
    }

    // Starlight from what still shines; dead stars kept warm (if dark matter does that).
    if (!inFinale) {
      let star = 0;
      let dead = 0;
      for (let i = 0; i < N_STARS; i++) {
        if (this.pst[i] !== St.Free) continue;
        if (this.pborn[i] > 0) {
          this.pborn[i] -= dt;
          star += NEW_STAR_LIGHT * LUM[Kind.Red] * 20;
          continue;
        }
        const kind = kindAt(step, this.pu[i]);
        star += LUM[kind];
        if (kind === Kind.White || kind === Kind.Black || kind === Kind.Neutron) dead++;
      }
      light += star * this.old + dead * WIMP_LIGHT * this.wimp;

      // Once the galaxy is gone the only light is the holes' own faint Hawking glow, hotter the smaller
      // they are, and brightest in the last moments before a hole's flash.
      if (step >= 5) {
        for (const h of this.holes) {
          if (!h.alive || h.merge >= 0) continue;
          const ramp = h.evap >= 0 ? 1 + 6 * (1 - h.evap / h.evapTotal) ** 4 : 1;
          // (The central hole is far the coldest; it keeps a floor here so a universe that merged every
          // stellar hole into it can still reach its end.)
          const glow = h.central ? 0.6 : Math.min(4, Math.sqrt(20 / h.m));
          light += HAWK_LIGHT * this.hawking * glow * ramp;
        }
      }

      // Brown dwarfs collide now and then and light a new star.
      if (step >= 3 && step <= 5) {
        this.brownAcc += BROWN_RATE * this.brown * dt;
        while (this.brownAcc >= 1) {
          this.brownAcc -= 1;
          this.lightNewStar();
        }
      }
    }

    if (light > 0) g.gain(light * E_UNIT * this.weight * dt);
    this.flashGlow = Math.max(0, this.flashGlow - dt * 0.8);
    this.fx.update(dt);
    this.syncLook(false);
  }

  /** Positions of the star particles still in orbit. */
  private positions(): void {
    for (let i = 0; i < N_STARS; i++) {
      if (this.pst[i] !== St.Free) continue;
      const r = this.pr[i];
      const c = Math.cos(this.pth[i]);
      const sn = Math.sin(this.pth[i]);
      this.px[i] = r * (c * this.pcn[i] - sn * this.pci[i] * this.psn[i]);
      this.py[i] = r * (c * this.psn[i] + sn * this.pci[i] * this.pcn[i]) * FLAT;
    }
  }

  private placeHole(h: Hole): void {
    if (h.central) {
      h.x = 0;
      h.y = 0;
      return;
    }
    const c = Math.cos(h.th);
    const sn = Math.sin(h.th);
    h.x = h.or * (c * h.cn - sn * h.ci * h.sn);
    h.y = h.or * (c * h.sn + sn * h.ci * h.cn) * FLAT;
  }

  private reachOf(h: Hole): number {
    return (h.central ? REACH_CENTRAL : REACH_STELLAR) * this.reach;
  }

  private capOf(h: Hole): number {
    return (h.central ? CAP_CENTRAL : CAP_STELLAR) * this.edd;
  }

  /** Starts the nearest star in reach falling into hole `k`; false if there is none. */
  private drawIn(k: number): boolean {
    const h = this.holes[k];
    const reach = this.reachOf(h);
    let best = -1;
    let bd = reach * reach;
    for (let i = 0; i < N_STARS; i++) {
      if (this.pst[i] !== St.Free) continue;
      const dx = this.px[i] - h.x;
      const dy = this.py[i] - h.y;
      const d2 = dx * dx + dy * dy;
      // Not always the nearest: a little randomness makes the stream look like a stream. Which star
      // falls in changes the game, so the draw comes from the simulation's stream (a star too far
      // away to win whatever it draws is skipped).
      if (d2 * 0.7 >= bd) continue;
      const w = d2 * (0.7 + 0.6 * this.g.sim.next());
      if (w < bd) {
        bd = w;
        best = i;
      }
    }
    if (best < 0) return false;
    this.pst[best] = St.Falling;
    this.ptgt[best] = k;
    this.pt[best] = 0;
    this.pfx[best] = this.px[best] - h.x;
    this.pfy[best] = this.py[best] - h.y;
    this.pdur[best] = 0.9 + 0.6 * this.g.sim.next();
    this.s.left = Math.max(0, this.s.left - 1);
    return true;
  }

  /** A falling star reaches the disk (a living star is torn apart first). */
  private arrive(i: number): void {
    const g = this.g;
    const h = this.holes[this.ptgt[i]];
    this.pst[i] = St.Gone;
    if (!h || !h.alive) return;
    h.disk += 1;
    h.fedT = 0;
    // Matter arriving from the disk's orbit spins the hole up, toward Thorne's limit.
    h.spin = Math.min(SPIN_MAX, h.spin + (SPINUP * this.drag) / (this.capOf(h) * (h.central ? INERTIA_CENTRAL : 1)));
    if (h.spin > 0.99) g.discover('thorne-limit');
    const living = this.pborn[i] > 0 || shines(kindAt(this.step, this.pu[i]));
    // The galaxy is far bigger than its bright core: most eaten stars are made up from its outskirts.
    if (this.step < 5 && g.sim.chance(RESPAWN)) this.respawn(i);
    if (living) {
      this.s.tdes++;
      g.setFlag('night.tde');
      g.discover('night-tde');
      this.harvest(TDE_UNITS * this.tde);
      // Now and then the flare of a torn star shows (they come too often to draw every one).
      if (g.fx.chance(0.2)) {
        const R = shadowRadius(h);
        const a = g.fx.angle();
        this.fx.spawn(Fx.Flash, h.x + Math.cos(a) * R * 1.6, h.y + Math.sin(a) * R * 1.6, 0.45, R * 1.4, 1.1, 0.7, 0.45, R * 0.5);
        g.sfx('night.tde', h.x);
      }
    } else if (g.fx.chance(0.3)) {
      g.sfx('night.feed', h.x, 1, Math.min(1.5, h.disk / this.capOf(h)));
    }
    if (h.disk >= this.capOf(h) * (1 - this.window)) g.discover('night-eddington');
  }

  /** Overfed: radiation pressure blows the disk away. */
  private blowout(h: Hole): void {
    const g = this.g;
    this.s.blowouts++;
    const R = shadowRadius(h);
    this.harvest(0.1 * SPILL_UNITS * h.disk * (spinEnergyShare(h.spin) / 0.29), h.x, h.y);
    for (let k = 0; k < 18; k++) {
      const a = g.fx.angle();
      const v = 60 + 80 * g.fx.next();
      this.fx.spawn(Fx.Spark, h.x + Math.cos(a) * R * 2, h.y + Math.sin(a) * R * 2, 1.2, 2.2, 1.2, 0.7, 0.45, 0, Math.cos(a) * v, Math.sin(a) * v, 1.5);
    }
    this.fx.spawn(Fx.Ring, h.x, h.y, 1.1, R * 2.5, 0.9, 0.55, 0.35, R * 14);
    h.disk = 0;
    this.holding = -1;
    g.sfx('night.blowout', h.x);
    g.discover('night-eddington');
  }

  /** Let go: the disk plunges through the ergosphere and the spin pays out. */
  private spill(h: Hole): void {
    const g = this.g;
    const s = this.s;
    const cap = this.capOf(h);
    const heat = h.disk / cap;
    const full = heat >= 1 - this.window;
    const units = SPILL_UNITS * h.disk * (spinEnergyShare(h.spin) / 0.29) * this.ergo * (full ? 2 : 1);
    this.harvest(units, h.x, h.y);
    h.spin *= Math.max(0, 1 - (SPILL_SPIN * Math.min(1, heat)) / (h.central ? INERTIA_CENTRAL : 1));
    h.jetT = 0;
    h.jetK = Math.min(1.5, 0.35 + heat * (full ? 1.1 : 0.7));
    h.disk = 0;
    s.spills++;
    s.everSpilled = true;
    g.setFlag('night.spilled');
    g.discover('night-penrose');
    const R = shadowRadius(h);
    this.fx.spawn(Fx.Flash, h.x, h.y, full ? 1.2 : 0.8, R * (full ? 5 : 3), 1.1, 1.2, 1.8, R * 2);
    g.renderer?.addFlash(full ? 0.12 : 0.04);
    if (full) {
      s.fulls++;
      g.setFlag('night.full');
      g.discover('blandford-znajek');
      g.renderer?.shock(h.x, h.y, 0.5, 0.6, 1);
      g.sfx('night.full', h.x);
    } else {
      g.sfx('night.spill', h.x, Math.min(1.2, 0.4 + heat));
    }
  }

  private startMerge(h: Hole): void {
    const c = this.holes[0];
    h.merge = 0;
    h.mx = h.x - c.x;
    h.my = h.y - c.y;
    this.g.sfx('night.chirp', h.x);
  }

  /** A stellar hole spirals into the central one: a burst of gravitational waves. */
  private mergeHole(h: Hole): void {
    const g = this.g;
    const c = this.holes[0];
    h.alive = false;
    h.merge = -1;
    c.m += h.m * 0.95;
    this.s.mergers++;
    this.harvest(GW_UNITS * (h.m / 20) * this.gw, c.x, c.y);
    const R = shadowRadius(c);
    for (let k = 0; k < 3; k++) this.fx.spawn(Fx.Ring, c.x, c.y, 1.6 + k * 0.4, R * 2, 0.55, 0.6, 0.9, 260 + k * 90);
    g.renderer?.shock(c.x, c.y, 0.7, 0.8, 1.3);
    g.sfx('night.merge', c.x);
  }

  /** An evaporating hole's final flash (caught if pressed just before it). */
  private flash(h: Hole): void {
    const g = this.g;
    const s = this.s;
    h.alive = false;
    h.evap = -1;
    s.flashes++;
    if (h.caught) s.caught++;
    g.discover('night-flash');
    this.harvest(FLASH_UNITS * (h.m / 20) * this.hawking * (h.caught ? 2.5 : 1), h.x, h.y);
    this.fx.spawn(Fx.Flash, h.x, h.y, 1.6, 90, 2.6, 2.7, 3.2, 40);
    for (let k = 0; k < 3; k++) this.fx.spawn(Fx.Ring, h.x, h.y, 1.4 + k * 0.5, 8, 0.75, 0.85, 1.1, 300 + k * 120);
    g.renderer?.addFlash(h.caught ? 0.35 : 0.2);
    g.renderer?.shock(h.x, h.y, 0.8, 0.8, 1.2);
    this.flashGlow = 1;
    g.sfx(h.caught ? 'night.catch' : 'night.flash', h.x);
  }

  /** A star from the outskirts takes the place of one eaten (on an outer orbit, a fresh draw of kind). */
  private respawn(i: number): void {
    const rng = this.g.sim;
    const r = rng.range(0.55, 1) * EDGE;
    const inc = Math.acos(rng.range(-1, 1));
    const node = rng.angle();
    this.pr[i] = r;
    this.pth[i] = rng.angle();
    this.pom[i] = (rng.chance(0.55) ? 1 : -1) * this.orbitSpeed(r);
    this.pci[i] = Math.cos(inc);
    this.pcn[i] = Math.cos(node);
    this.psn[i] = Math.sin(node);
    this.pu[i] = rng.next();
    this.pborn[i] = 0;
    this.pst[i] = St.Free;
    this.s.left = Math.min(N_STARS, this.s.left + 1);
  }

  /** Two brown dwarfs collide and light a small new star. */
  private lightNewStar(): void {
    const g = this.g;
    for (let tries = 0; tries < 30; tries++) {
      const i = g.sim.int(N_STARS);
      if (this.pst[i] !== St.Free || this.pborn[i] > 0) continue;
      if (kindAt(this.step, this.pu[i]) !== Kind.Brown) continue;
      this.pborn[i] = NEW_STAR_LIFE;
      this.s.newStars++;
      this.fx.spawn(Fx.Flash, this.px[i], this.py[i], 1.4, 26, 1.6, 0.7, 0.4, 8);
      this.fx.spawn(Fx.Ring, this.px[i], this.py[i], 1.2, 6, 1.2, 0.6, 0.35, 90);
      g.sfx('night.newstar', this.px[i]);
      return;
    }
  }

  // ───────────────────────────────────────── steps

  onStep(index: number): void {
    const g = this.g;
    this.syncStepFlags();
    this.bgParams.pulse = Math.min(1, this.bgParams.pulse + 0.35);
    g.renderer?.camera.breathe(0.04, 1.5);
    const last = index === g.steps().length - 1;
    if (index >= 1 && !last) g.sfx('night.milestone');
    if (this.fate === 'crunch' || this.fate === 'rip') {
      this.lateStep(index);
      return;
    }
    // A vacuum's last step is its bubble: the finale takes it from here.
    if (this.fate === 'vacuum' && last) return;
    if (index === 2) {
      g.discover('night-blue-dwarf');
      g.discover('horizon-temperature');
    }
    if (index === 3) {
      g.discover('age-degenerate');
      g.discover('last-star');
      g.toast('The last star has faded. From now on, nearly all the light comes from black holes.', 'quiet');
    }
    if (index === 4) g.discover('night-black-dwarf');
    if (index === 5) this.evaporate();
    if (index === 6) this.dissolve();
    if (index === 7) this.beginEvaporations();
  }

  /** The steps of a universe that falls back together, or is torn apart. */
  private lateStep(index: number): void {
    const g = this.g;
    if (this.fate === 'crunch') {
      if (index === 1) g.toast('The expansion has stopped. From here on, everything falls back together.', 'quiet');
      if (index === 3) {
        g.discover('age-degenerate');
        g.toast('The sky is as hot as a star. Stars come apart; the black holes still feed.', 'quiet');
      }
    } else {
      if (index === 1) for (const h of this.holes) if (!h.central) h.or *= 1.25;
      if (index === 2) g.toast('Dark energy is pulling the galaxy apart. Feed the holes while there is still something near them.', 'quiet');
    }
  }

  /** Every star's orbit (and the stellar holes') grows or shrinks by `k`. */
  private scaleGalaxy(k: number): void {
    for (let i = 0; i < N_STARS; i++) {
      if (this.pst[i] !== St.Free) continue;
      this.pr[i] = Math.min(EDGE * 3, Math.max(6, this.pr[i] * k));
      this.pom[i] = Math.sign(this.pom[i] || 1) * this.orbitSpeed(this.pr[i]);
    }
    for (const h of this.holes) if (!h.central && h.alive && h.merge < 0) h.or = Math.min(EDGE * 3, Math.max(40, h.or * k));
  }

  /** 10²⁰ years: close passes fling most dead stars out; the rest sink into the central hole. */
  private evaporate(): void {
    const g = this.g;
    const c = this.holes[0];
    this.s.evaporated = true;
    g.discover('galactic-evaporation');
    let delay = 0;
    for (let i = 0; i < N_STARS; i++) {
      if (this.pst[i] !== St.Free) continue;
      if (g.sim.chance(0.94)) {
        const r = Math.hypot(this.px[i], this.py[i]) || 1;
        const v = 50 + 110 * g.fx.next();
        this.pst[i] = St.Ejected;
        this.pt[i] = 0;
        this.pvx[i] = (this.px[i] / r) * v;
        this.pvy[i] = (this.py[i] / r) * v;
      } else {
        this.pst[i] = St.Falling;
        this.ptgt[i] = 0;
        this.pt[i] = -delay;
        this.pfx[i] = this.px[i] - c.x;
        this.pfy[i] = this.py[i] - c.y;
        this.pdur[i] = 1.2 + 0.8 * g.sim.next();
        delay += 0.07;
      }
    }
    this.s.left = 0;
    // Stellar holes sink toward the middle as the galaxy boils away around them.
    for (const h of this.holes) if (!h.central) h.or *= 0.7;
    g.toast('The galaxy is boiling away. What stays falls into the central black hole: hold it, and spill what you can.', 'quiet');
  }

  /** 10⁴⁰ years: if protons decay, the last dead stars turn into radiation. */
  private dissolve(): void {
    const g = this.g;
    this.s.dissolved = true;
    g.discover('age-blackhole');
    g.discover('proton-decay');
    for (let i = 0; i < N_STARS; i++) {
      if (this.pst[i] !== St.Free && this.pst[i] !== St.Falling) continue;
      this.pst[i] = St.Dissolving;
      this.pt[i] = 0;
      this.pdur[i] = 2 + 4 * g.sim.next();
    }
    for (const h of this.holes) h.disk = 0;
    if (this.holes.some((h) => !h.central && h.alive)) g.toast('Only black holes are left, glowing faintly. Hold one to drop it into the central hole, or keep it for its last flash.', 'quiet');
  }

  /** 10⁷⁰ years: the black holes left by stars evaporate, lightest first. */
  private beginEvaporations(): void {
    const g = this.g;
    g.discover('night-hawking');
    const left = this.holes.filter((h) => !h.central && h.alive && h.merge < 0).sort((a, b) => a.m - b.m);
    let t = 6;
    for (const h of left) {
      h.evap = t;
      h.evapTotal = t;
      t += 7 + 3 * g.sim.next();
    }
  }

  // ───────────────────────────────────────── input

  pointer(e: PointerInfo): void {
    if (!e.primary) return;
    if (e.type === 'move') {
      if (this.holding < 0) this.hover = this.holeAt(e.x, e.y);
      return;
    }
    if (e.type === 'up' || e.type === 'cancel') {
      const h = this.holding >= 0 ? this.holes[this.holding] : undefined;
      this.holding = -1;
      if (h && h.alive && h.disk > 0.5 && e.type === 'up') this.spill(h);
      return;
    }
    this.idle = 0;
    if (this.finaleT >= 0) return;
    const k = this.holeAt(e.x, e.y);
    if (k < 0) return;
    const h = this.holes[k];
    // An evaporating hole: a press just before its flash catches it.
    if (h.evap >= 0) {
      if (h.evap <= CATCH_WINDOW) {
        h.caught = true;
        this.flash(h);
      } else {
        this.g.sfx('night.early', h.x);
      }
      return;
    }
    if (h.merge >= 0) return;
    // In the Black Hole Era there is nothing left to feed on: a held stellar hole is dropped into the
    // central one instead (a burst of gravitational waves now, instead of its glow and its flash later).
    if (this.step >= 6) {
      if (!h.central) this.startMerge(h);
      return;
    }
    this.holding = k;
    h.feedAcc = Math.max(h.feedAcc, 0.6);
    this.g.sfx('night.press', h.x);
  }

  private holeAt(x: number, y: number): number {
    let best = -1;
    let bd = Infinity;
    for (let k = 0; k < this.holes.length; k++) {
      const h = this.holes[k];
      if (!h.alive) continue;
      const d = Math.hypot(h.x - x, h.y - y);
      const r = Math.max(22, shadowRadius(h) * 2.6);
      if (d < r && d < bd) {
        bd = d;
        best = k;
      }
    }
    return best;
  }

  // ───────────────────────────────────────── finale: heat death

  finale(): Promise<void> {
    const g = this.g;
    const run = g.state.run;
    const c = this.holes[0];
    run.legacy.finalHole = c.m;
    run.legacy.lastFlashYears = hawkingYears(c.m);
    run.legacy.flashesCaught = this.s.caught;
    run.legacy.harvest = this.s.harvest;
    this.holding = -1;
    this.finaleT = 0;
    this.finaleFlashed = false;
    g.sfx('night.complete');
    return new Promise((resolve) => {
      this.finaleDone = resolve;
    });
  }

  private updateFinale(dt: number): void {
    const g = this.g;
    this.finaleT += dt;
    const t = this.finaleT;
    const c = this.holes[0];
    if (this.fate !== 'heat-death') {
      this.otherFinale(dt);
      return;
    }
    if (t >= 9 && !this.finaleFlashed) {
      this.finaleFlashed = true;
      c.alive = false;
      this.fx.spawn(Fx.Flash, c.x, c.y, 3, 260, 3, 3, 3.4, 80);
      for (let k = 0; k < 5; k++) this.fx.spawn(Fx.Ring, c.x, c.y, 2 + k * 0.6, 10, 0.8, 0.9, 1.2, 420 + k * 160);
      g.renderer?.addFlash(1);
      g.renderer?.shock(c.x, c.y, 1, 1, 1.6);
      g.sfx('night.flash', c.x);
      g.discover('night-flash');
    }
    if (t >= 11.5 && t - dt < 11.5) {
      g.discover('age-dark');
      g.discover('fate-heat-death');
      const yrs = toText(count(hawkingYears(c.m)));
      g.toast(`The last black hole is gone, ${yrs} years after the Big Bang. The universe is as even as it will ever be. Nothing is left to happen.`, 'milestone');
    }
    if (t >= 18 && this.finaleDone) {
      const done = this.finaleDone;
      this.finaleDone = null;
      done();
    }
  }

  /** The ends of universes not headed for heat death. */
  private otherFinale(dt: number): void {
    const g = this.g;
    const t = this.finaleT;
    const c = this.holes[0];
    if (this.fate === 'crunch') {
      // Everything falls together, faster and hotter, into one point.
      this.scaleGalaxy(Math.exp(-dt * (0.15 + t * 0.12)));
      if (t >= 8 && !this.finaleFlashed) {
        this.finaleFlashed = true;
        for (const h of this.holes) h.alive = false;
        for (let i = 0; i < N_STARS; i++) if (this.pst[i] === St.Free) this.pst[i] = St.Gone;
        this.fx.spawn(Fx.Flash, 0, 0, 3, 420, 3.4, 3, 2.6, 120);
        g.renderer?.addFlash(1.4);
        g.renderer?.shock(0, 0, 1, 1, 1.8);
        g.sfx('night.flash', 0);
        g.discover('fate-crunch');
      }
      if (t >= 10.5 && t - dt < 10.5) g.toast('Everything has fallen back together into one point. Some think a universe could bounce back from this; nobody knows.', 'milestone');
    } else if (this.fate === 'rip') {
      // Torn apart: everything flies outward and fades.
      this.scaleGalaxy(Math.exp(dt * (0.2 + t * 0.35)));
      if (t >= 7 && !this.finaleFlashed) {
        this.finaleFlashed = true;
        for (let i = 0; i < N_STARS; i++) if (this.pst[i] === St.Free) this.pst[i] = St.Gone;
        for (const h of this.holes) h.alive = false;
        for (let k = 0; k < 60; k++) {
          const a = g.fx.angle();
          const v = 200 + 300 * g.fx.next();
          this.fx.spawn(Fx.Spark, c.x, c.y, 1.6, 2.4, 1.2, 1.1, 1.3, 0, Math.cos(a) * v, Math.sin(a) * v, 0);
        }
        g.sfx('night.blowout', 0);
        g.discover('fate-rip');
      }
      if (t >= 9 && t - dt < 9) g.toast('Dark energy has torn everything apart, down to the atoms. Nothing bound is left anywhere.', 'milestone');
    } else {
      // A bubble of true vacuum: it grows at nearly light speed and nothing survives it.
      if (t < dt * 1.5) {
        const a = g.fx.angle();
        this.bubbleX = Math.cos(a) * 300;
        this.bubbleY = Math.sin(a) * 180;
      }
      this.bubbleR = 16 * t * t;
      for (let i = 0; i < N_STARS; i++) {
        if (this.pst[i] !== St.Free) continue;
        if (Math.hypot(this.px[i] - this.bubbleX, this.py[i] - this.bubbleY) < this.bubbleR) this.pst[i] = St.Gone;
      }
      for (const h of this.holes) if (h.alive && Math.hypot(h.x - this.bubbleX, h.y - this.bubbleY) < this.bubbleR) h.alive = false;
      if (t >= 9 && !this.finaleFlashed) {
        this.finaleFlashed = true;
        g.discover('fate-vacuum');
      }
      if (t >= 10 && t - dt < 10) g.toast('A bubble of true vacuum swept through. Whatever this universe was, it is not anymore.', 'milestone');
    }
    if (t >= 17 && this.finaleDone) {
      const done = this.finaleDone;
      this.finaleDone = null;
      done();
    }
  }

  /** The last step needs the black holes left by stars gone (merged or evaporated). */
  static lastBlocker(g: Game): string | null {
    if (fateOf(g.state.run.constants) !== 'heat-death') return null;
    const s = g.state.run.eras.night as NightState | undefined;
    const era = g.era as unknown as { stellarLeft?: () => number } | null;
    const left = era?.stellarLeft?.() ?? (s ? s.holes.filter((h) => !h.central && h.alive).length : 0);
    return left > 0 ? `Needs ${left} more black hole${left === 1 ? '' : 's'} gone` : null;
  }

  stellarLeft(): number {
    return this.holes.filter((h) => !h.central && h.alive).length;
  }

  // ───────────────────────────────────────── look

  /** Background and saved state follow the simulation. */
  private syncLook(force: boolean): void {
    const step = this.step;
    const bp = this.bgParams;
    let shining = 0;
    let total = 0;
    for (let i = 0; i < N_STARS; i++) {
      if (this.pst[i] !== St.Free) continue;
      total++;
      if (shines(kindAt(step, this.pu[i]))) shining++;
    }
    let target = total === 0 ? 0 : (shining / N_STARS) * 1.1 + (total / N_STARS) * 0.12;
    if (this.fate === 'crunch' && step >= 2) target += step === 2 ? 0.8 : 2 + (this.finaleT >= 0 ? this.finaleT * 0.6 : 0);
    bp.glow += (target - bp.glow) * (force ? 1 : 0.05);
    let tint: RGB = step <= 0 ? [1, 0.78, 0.52] : step === 1 ? [1, 0.55, 0.32] : step === 2 ? [0.6, 0.75, 1.1] : [0.55, 0.55, 0.62];
    // A collapsing sky heats from red to white; a tearing one only darkens.
    if (this.fate === 'crunch' && step >= 2) tint = step === 2 ? [1.6, 0.5, 0.25] : [2.2, 1.6, 1.1];
    for (let k = 0; k < 3; k++) bp.tint[k] += (tint[k] - bp.tint[k]) * (force ? 1 : 0.03);
    const endsAt = this.fate === 'crunch' ? 8.5 : this.fate === 'rip' ? 7 : 9;
    const dark = this.finaleT >= endsAt ? Math.min(1, (this.finaleT - endsAt) / 3) : step >= 6 ? 0.6 : 0;
    bp.dark += (dark - bp.dark) * (force ? 1 : 0.05);
    bp.pulse = Math.max(0, bp.pulse - 0.01) + this.flashGlow * 0.02;
    // Saved holes follow the live ones.
    this.s.holes = this.holes.map((h) => ({
      central: h.central,
      m: h.m,
      spin: h.spin,
      disk: h.disk,
      or: h.or,
      th: h.th,
      om: h.om,
      ci: h.ci,
      cn: h.cn,
      sn: h.sn,
      tilt: h.tilt,
      alive: h.alive,
      ...(h.evap >= 0 ? { evap: h.evap, evapTotal: h.evapTotal } : {}),
    }));
  }

  render(r: Renderer): void {
    const step = this.step;
    const t = this.t;
    // Stars.
    for (let i = 0; i < N_STARS; i++) {
      const st = this.pst[i];
      if (st === St.Gone) continue;
      let x = this.px[i];
      let y = this.py[i];
      let c: RGB;
      let size: number;
      let a = 1;
      const kind = this.pborn[i] > 0 ? Kind.Star : kindAt(step, this.pu[i]);
      switch (kind) {
        case Kind.Star:
          c = [1.25, 1.0, 0.72];
          size = 1.7;
          break;
        case Kind.Red:
          c = [1.15, 0.5, 0.3];
          size = 1.45;
          break;
        case Kind.Blue:
          c = [0.6, 0.82, 1.6];
          size = 1.7;
          break;
        case Kind.White:
          c = [0.7, 0.8, 1.05];
          size = 1.15;
          break;
        case Kind.Neutron:
          c = [0.5, 0.85, 1.3];
          size = 1.1;
          a = 0.6 + 0.4 * Math.sin(t * (4 + this.pu[i] * 20));
          break;
        case Kind.Brown:
          c = [0.42, 0.16, 0.09];
          size = 1.05;
          break;
        default:
          c = [0.08, 0.08, 0.1];
          size = 1;
      }
      if (this.pborn[i] > 0) {
        const k = Math.min(1, this.pborn[i] / 4);
        c = [1.6, 0.75, 0.42];
        size = 2.2;
        a = k;
      }
      if (st === St.Falling) {
        const h = this.holes[this.ptgt[i]];
        if (!h) continue;
        const p = Math.max(0, this.pt[i]) / this.pdur[i];
        if (this.pt[i] < 0) {
          // Waiting its turn to fall (the evaporation frenzy): still where it was.
          x = h.x + this.pfx[i];
          y = h.y + this.pfy[i];
        } else {
          const ang = p * p * 7 * (h.spin >= 0 ? 1 : -1);
          const shrink = (1 - p) ** 1.6;
          x = h.x + (this.pfx[i] * Math.cos(ang) - this.pfy[i] * Math.sin(ang)) * shrink;
          y = h.y + (this.pfx[i] * Math.sin(ang) + this.pfy[i] * Math.cos(ang)) * shrink;
          // Heated on the way in.
          c = [c[0] + p * 1.4, c[1] + p * 1.1, c[2] + p * 0.9];
          size += p;
        }
      } else if (st === St.Ejected) {
        x = this.px[i] + this.pvx[i] * this.pt[i];
        y = this.py[i] + this.pvy[i] * this.pt[i];
        a = Math.max(0, 1 - this.pt[i] / 7);
      } else if (st === St.Dissolving) {
        const p = Math.min(1, this.pt[i] / this.pdur[i]);
        a = 1 - p;
        c = [c[0] + 0.6 * p, c[1] + 0.6 * p, c[2] + 0.8 * p];
      }
      if (a <= 0.01) continue;
      // Stars right in front of a shadow are hidden by it.
      if (this.hidden(x, y)) continue;
      if (this.bubbleR > 0 && Math.hypot(x - this.bubbleX, y - this.bubbleY) < this.bubbleR) continue;
      r.glow.push(x, y, size, c[0] * a, c[1] * a, c[2] * a, 1, Shape.Glow);
    }
    // Black holes.
    for (let k = 0; k < this.holes.length; k++) {
      const h = this.holes[k];
      const lingering = h.central && this.fate === 'heat-death' && this.finaleT >= 0 && this.finaleT < 9;
      if (!h.alive && !lingering) continue;
      this.renderHole(r, h, k);
    }
    // The bubble's wall: a thin bright shell racing outward, nothing behind it.
    if (this.bubbleR > 0) {
      r.under.push(this.bubbleX, this.bubbleY, this.bubbleR, 0.03, 0.02, 0.06, 1, Shape.Puff);
      r.over.push(this.bubbleX, this.bubbleY, this.bubbleR, 0.9, 0.8, 1.4, 1, Shape.Shock, 0.006);
    }
    this.fx.render(r);
  }

  private hidden(x: number, y: number): boolean {
    for (const h of this.holes) {
      if (!h.alive) continue;
      const R = shadowRadius(h);
      const dx = x - h.x;
      const dy = y - h.y;
      if (dx * dx + dy * dy < R * R) return true;
    }
    return false;
  }

  private renderHole(r: Renderer, h: Hole, k: number): void {
    const t = this.t;
    let R = shadowRadius(h);
    let hot = 0;
    if (h.evap >= 0) {
      // Evaporating: it shrinks and heats as its flash nears.
      const p = 1 - h.evap / h.evapTotal;
      R *= Math.max(0.25, 1 - 0.75 * p ** 3);
      hot = p ** 4;
    }
    if (h.central && this.finaleT >= 0) {
      const p = Math.min(1, this.finaleT / 9);
      R *= Math.max(0.05, 1 - p ** 2.5);
      hot = p ** 3;
    }
    const cap = this.capOf(h);
    const heat = Math.min(1.2, h.disk / cap);
    // The accretion disk: a tilted ring of hot plasma, brighter on the side swinging toward us.
    if (heat > 0.01 || h.fedT < 1) {
      const n = h.central ? 56 : 30;
      const ra = R * 2.5;
      const rb = ra * 0.34;
      const ct = Math.cos(h.tilt);
      const st = Math.sin(h.tilt);
      const near = heat >= 1 - this.window && k === this.holding;
      const throb = near ? 1 + 0.6 * Math.sin(t * 18) : 1;
      const lvl = Math.max(0.15, heat) * throb;
      const col: RGB = [1.4 + 0.6 * heat, 0.7 + 0.8 * heat, 0.35 + 1.1 * heat];
      for (let j = 0; j < n; j++) {
        const a = (j / n) * Math.PI * 2 + t * (0.8 + 2.2 * h.spin);
        const ex = Math.cos(a) * ra;
        const ey = Math.sin(a) * rb;
        const x = h.x + ex * ct - ey * st;
        const y = h.y + ex * st + ey * ct;
        // The far half passes behind the shadow.
        if (Math.sin(a) < 0 && Math.hypot(x - h.x, y - h.y) < R * 1.05) continue;
        const beam = 1 + 0.7 * Math.cos(a);
        const f = 0.5 * lvl * beam;
        r.glow.push(x, y, 2.2 + heat * 1.6, col[0] * f, col[1] * f, col[2] * f, 1, Shape.Glow);
      }
      r.under.push(h.x, h.y, R * 3.4, 0.14 * lvl, 0.08 * lvl, 0.05 * lvl, 1, Shape.Puff);
    }
    // Light bent around the hole, the shadow, and the thin ring of light orbiting just outside it.
    r.under.push(h.x, h.y, R * 2.2, 0.05, 0.04, 0.035, 1, Shape.Puff);
    r.solid.push(h.x, h.y, R, 0, 0, 0, 1, Shape.Disc);
    const ring = (h.central ? 0.85 : 0.55) + 0.6 * heat + 2 * hot;
    // The Ring sprite draws at half its size: the photon ring sits on the shadow's edge.
    r.glow.push(h.x, h.y, R * 2.06, 1.1 * ring, (0.8 + 0.4 * hot) * ring, (0.55 + 0.9 * hot) * ring, 0.85, Shape.Ring, h.central ? 0.032 : 0.058);
    // Once the galaxy is gone, the holes' own faint glow is the only light left.
    if (this.step >= 5 && !h.central && h.evap < 0) {
      const g = Math.min(1, Math.sqrt(20 / h.m)) * 0.5;
      r.glow.push(h.x, h.y, R * 2.6, 0.1 * g, 0.14 * g, 0.24 * g, 1, Shape.Glow);
    }
    // Hawking glow: hotter as it shrinks.
    if (hot > 0.01) r.glow.push(h.x, h.y, R * (2 + 6 * hot), 0.9 * hot, 1.1 * hot, 1.6 * hot, 1, Shape.Glow);
    // A ring closes on an evaporating hole: press as it arrives.
    if (h.evap >= 0 && h.evap < 2.2) {
      const p = h.evap / 2.2;
      r.over.push(h.x, h.y, R * (1.3 + 9 * p), 0.6, 0.75, 1.1, 0.8, Shape.Shock, 0.03);
    }
    // Jets after a spill.
    if (h.jetT < 1.8) {
      const f = 1 - h.jetT / 1.8;
      const q = h.jetK * f;
      const ang = h.tilt + Math.PI / 2;
      for (const sgn of [1, -1]) {
        const L = R * (5 + 9 * h.jetK) * (0.3 + 0.7 * Math.min(1, h.jetT * 4));
        const ex = h.x + Math.cos(ang) * L * sgn;
        const ey = h.y + Math.sin(ang) * L * sgn;
        r.lines.push(h.x, h.y, ex, ey, 2 + 4 * q, 0.6, LineStyle.Glow, 0.6 * q, 0.8 * q, 1.6 * q, 0.9, 0.3 * q, 0.45 * q, 1 * q, 0);
        r.under.push(ex, ey, R * (1 + 1.2 * h.jetK), 0.08 * q, 0.11 * q, 0.24 * q, 1, Shape.Puff);
      }
    }
    // Reach, while hovered or held.
    if ((k === this.hover || k === this.holding) && h.evap < 0 && this.finaleT < 0) {
      const reach = this.reachOf(h);
      const segs = 48;
      const al = k === this.holding ? 0.28 : 0.16;
      for (let j = 0; j < segs; j += 2) {
        const a0 = (j / segs) * Math.PI * 2 - t * 0.2;
        const a1 = ((j + 1) / segs) * Math.PI * 2 - t * 0.2;
        r.lines.push(h.x + Math.cos(a0) * reach, h.y + Math.sin(a0) * reach, h.x + Math.cos(a1) * reach, h.y + Math.sin(a1) * reach, 1.2, 1.2, LineStyle.Crisp, 0.5, 0.48, 0.55, al);
      }
    }
  }

  // ───────────────────────────────────────── HUD

  labels(): WorldLabel[] {
    const out: WorldLabel[] = [];
    const k = this.holding >= 0 ? this.holding : this.hover;
    const h = k >= 0 ? this.holes[k] : undefined;
    if (h && h.alive && this.finaleT < 0) {
      const R = shadowRadius(h);
      const heat = Math.round((100 * h.disk) / this.capOf(h));
      const what = `${h.central ? 'Central black hole' : 'Black hole'} · ${toText(count(h.m))} Suns · spin ${h.spin.toFixed(2)}${h.disk > 0 ? ` · disk ${heat} %` : ''}`;
      out.push({ id: 'hole', x: h.x, y: h.y - R * 2.8 - 12, text: what, tone: 'value', opacity: 0.9 });
    }
    return out;
  }

  stocks(): StockView[] {
    const c = this.holes[0];
    const shining = this.countFree((kind) => shines(kind));
    const out: StockView[] = [
      { id: 'central', label: 'Central black hole', value: c?.m ?? 0, format: 'count', hint: 'Its mass in Suns. Everything it swallows makes it heavier, and the heavier it is, the longer it will last.' },
      { id: 'spin', label: 'Its spin', value: c?.spin ?? 0, format: 'decimal', hint: "From 0 (still) to 0.998, the most a disk can spin a hole up (Thorne's limit). Spills spend it; feeding restores it." },
    ];
    if (this.step <= 2) out.push({ id: 'shining', label: 'Stars still shining', value: shining * this.shareSuns * 5, format: 'count', hint: 'Red dwarfs, mostly: the smallest stars live longest.' });
    else if (this.step <= 5) out.push({ id: 'dead', label: 'Dead stars', value: this.countFree(() => true) * this.shareSuns * 2, format: 'count', hint: 'White, black and brown dwarfs and neutron stars.' });
    const stellar = this.stellarLeft();
    out.push({ id: 'holes', label: 'Black holes left by stars', value: stellar, format: 'count', hint: 'Hold one to feed it. In the Black Hole Era they evaporate one by one, smallest first.' });
    return out;
  }

  private countFree(test: (k: Kind) => boolean): number {
    let n = 0;
    for (let i = 0; i < N_STARS; i++) if (this.pst[i] === St.Free && test(kindAt(this.step, this.pu[i]))) n++;
    return n;
  }

  dotScale(): { value: number; unit: string } | null {
    return this.step <= 4 ? { value: this.shareSuns * 2, unit: 'stars' } : null;
  }

  offline(seconds: number): OfflineReport {
    void seconds;
    return { lines: [] };
  }

  accent(): RGB {
    const step = this.step;
    if (step <= 1) return [1, 0.7, 0.5];
    if (step === 2) return [0.7, 0.82, 1];
    return [0.78, 0.8, 0.9];
  }

  hint(): string | null {
    if (this.finaleT >= 0) return null;
    const s = this.s;
    if (this.step === 7 && this.holes.some((h) => h.evap >= 0 && h.alive) && s.caught === 0 && this.idle > 3) return 'Press a black hole the moment its ring closes, to catch its last flash.';
    if (!s.everHeld && this.idle > 4) return 'Press and hold on a black hole to feed it the stars around it.';
    if (s.everHeld && !s.everSpilled && this.idle > 5) return 'Let go to spill the disk through the black hole\'s spin.';
    if (s.blowouts > 0 && s.fulls === 0 && this.idle > 6) return 'Let go just before the disk reaches its limit: it throbs when it is close.';
    const c = this.holes[0];
    if (c && c.spin < 0.2 && this.step < 6 && this.idle > 8) return 'A hole that has lost its spin pays little. Feed it longer to spin it back up.';
    return null;
  }
}
