/**
 * Post-processing: physically based bloom, lens glare and the final composite.
 *
 * Bloom follows the progressive downsample/upsample method (Jimenez, "Next Generation Post
 * Processing in Call of Duty: Advanced Warfare", 2014): a 13-tap filter going down (with a Karis
 * average on the first pass to stop single bright pixels from flickering), a 3×3 tent going up,
 * each level added onto the next larger one. With a threshold, only light above it blooms and the
 * glow is added on top, so faint detail stays crisp; without one, the bloom is mixed in. Glare streaks the brightest light along a few fixed
 * directions, the way a lens's aperture blades and diffraction do, so a point of light reads as
 * light seen through optics rather than as a blob.
 *
 * Without float targets the scene and the bloom levels are 8-bit (see LDR_RANGE): light is read back
 * up to its real level where it is thresholded and tonemapped, so the grade means the same thing, and
 * the glare threshold comes down to make up for the brightest points clipping at the range.
 * Every program is optional: one the driver rejects leaves its effect out (with no composite at all,
 * the scene is copied to the screen as it is).
 */
import { AGX, HASH, HEADER } from './glsl';
import { FULLSCREEN_VS, Target, drawFullscreen, lightGain, tryProgram, type Program, type TargetFormat } from './gl';

/**
 * Without float targets the brightest points clip at the range (LDR_RANGE). Bloom's threshold sits well
 * inside it and keeps its grade; glare reads a blurred bloom level, where a clipped core averages out
 * below its threshold, so glare starts lower there to find the same points.
 */
const LDR_GLARE_THRESHOLD = 0.6;

const DOWN_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uSrc;
uniform vec2 uTexel;
uniform int uKaris;
uniform float uThreshold;
// Light as stored → real light (the first pass, from an 8-bit scene), and back for the level.
uniform float uDecode;
uniform float uEncode;
out vec4 outColor;
vec3 S(float x, float y) { return texture(uSrc, vUv + vec2(x, y) * uTexel).rgb * uDecode; }
float karis(vec3 c) { return 1.0 / (1.0 + dot(c, vec3(0.2126, 0.7152, 0.0722))); }
void main() {
  vec3 a = S(-2.0, 2.0), b = S(0.0, 2.0), c = S(2.0, 2.0);
  vec3 d = S(-2.0, 0.0), e = S(0.0, 0.0), f = S(2.0, 0.0);
  vec3 g = S(-2.0, -2.0), h = S(0.0, -2.0), i = S(2.0, -2.0);
  vec3 j = S(-1.0, 1.0), k = S(1.0, 1.0), l = S(-1.0, -1.0), m = S(1.0, -1.0);
  vec3 o;
  if (uKaris == 1) {
    vec3 g0 = (a + b + d + e) * 0.25;
    vec3 g1 = (b + c + e + f) * 0.25;
    vec3 g2 = (d + e + g + h) * 0.25;
    vec3 g3 = (e + f + h + i) * 0.25;
    vec3 g4 = (j + k + l + m) * 0.25;
    float w0 = karis(g0) * 0.125, w1 = karis(g1) * 0.125, w2 = karis(g2) * 0.125;
    float w3 = karis(g3) * 0.125, w4 = karis(g4) * 0.5;
    o = (g0 * w0 + g1 * w1 + g2 * w2 + g3 * w3 + g4 * w4) / (w0 + w1 + w2 + w3 + w4);
    // Only the light above the threshold blooms (soft knee, keeping its colour).
    float l = dot(o, vec3(0.2126, 0.7152, 0.0722));
    o *= max(l - uThreshold, 0.0) / max(l, 1e-4);
  } else {
    o = e * 0.125 + (a + c + g + i) * 0.03125 + (b + d + f + h) * 0.0625 + (j + k + l + m) * 0.125;
  }
  outColor = vec4(max(o, vec3(0.0)) * uEncode, 1.0);
}`;

const UP_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uSrc;
uniform vec2 uTexel;
uniform float uRadius;
out vec4 outColor;
vec3 S(float x, float y) { return texture(uSrc, vUv + vec2(x, y) * uTexel * uRadius).rgb; }
void main() {
  vec3 o = S(0.0, 0.0) * 4.0
    + (S(0.0, 1.0) + S(-1.0, 0.0) + S(1.0, 0.0) + S(0.0, -1.0)) * 2.0
    + (S(-1.0, 1.0) + S(1.0, 1.0) + S(-1.0, -1.0) + S(1.0, -1.0));
  outColor = vec4(o / 16.0, 1.0);
}`;

const GLARE_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uSrc;
uniform vec2 uTexel;
uniform float uThreshold;
uniform float uAngle;
out vec4 outColor;
vec3 bright(vec2 uv) { return max(texture(uSrc, uv).rgb - uThreshold, vec3(0.0)); }
void main() {
  vec3 sum = vec3(0.0);
  for (int a = 0; a < 3; a++) {
    float ang = uAngle + float(a) * 1.0471976;
    vec2 dir = vec2(cos(ang), sin(ang)) * uTexel;
    for (int i = 1; i <= 14; i++) {
      float w = exp(-float(i) * 0.28);
      sum += (bright(vUv + dir * float(i) * 1.6) + bright(vUv - dir * float(i) * 1.6)) * w;
    }
  }
  outColor = vec4(sum * 0.09, 1.0);
}`;

const BLIT_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uSrc;
uniform float uGain;
out vec4 outColor;
void main() { outColor = vec4(texture(uSrc, vUv).rgb * uGain, 1.0); }`;

const COMPOSITE_FS = HEADER + HASH + AGX + /* glsl */ `
in vec2 vUv;
uniform sampler2D uScene;
uniform sampler2D uBloomTex;
uniform sampler2D uGlareTex;
uniform float uBloom;
uniform float uBloomAdd;
uniform float uGlare;
uniform float uDecode;
uniform float uExposure;
uniform float uSaturation;
uniform float uPunch;
uniform float uVignette;
uniform float uGrain;
uniform float uTime;
uniform float uAberration;
uniform float uFlash;
uniform float uAspect;
uniform vec4 uShock[4];   // centre uv, radius (in screen heights), strength
uniform vec3 uTint;       // final colour balance (1,1,1 = neutral)
out vec4 outColor;

void main() {
  vec2 uv = vUv;
  vec2 offset = vec2(0.0);
  for (int i = 0; i < 4; i++) {
    vec4 s = uShock[i];
    if (s.w <= 0.0) continue;
    vec2 d = (uv - s.xy) * vec2(uAspect, 1.0);
    float dist = length(d);
    float x = (dist - s.z) / 0.035;
    float wave = x * exp(-x * x);
    offset += (d / max(dist, 1e-4)) * wave * s.w * 0.02 / vec2(uAspect, 1.0);
  }
  uv += offset;

  vec2 dc = uv - 0.5;
  vec3 col;
  if (uAberration > 0.0) {
    vec2 ab = dc * uAberration;
    col = vec3(texture(uScene, uv - ab).r, texture(uScene, uv).g, texture(uScene, uv + ab).b);
  } else {
    col = texture(uScene, uv).rgb;
  }
  vec3 bloom = texture(uBloomTex, uv).rgb;
  col = uBloomAdd > 0.5 ? col + bloom * uBloom : mix(col, bloom, uBloom);
  if (uGlare > 0.0) col += texture(uGlareTex, uv).rgb * uGlare;
  // Light as stored → real light (an 8-bit scene keeps it scaled down).
  col *= uDecode * uExposure * (1.0 + uFlash);
  col *= uTint;
  col = agxTonemap(col, uSaturation, uPunch);

  vec2 vd = dc * vec2(uAspect, 1.0);
  float vig = smoothstep(0.35, 1.05, length(vd) / max(uAspect, 1.0) * 1.6);
  col *= 1.0 - uVignette * vig;

  float n = hash12(gl_FragCoord.xy + fract(uTime * 7.31) * 811.0) - 0.5;
  col += n * uGrain * (0.6 + 0.4 * (1.0 - dot(col, vec3(0.333))));
  col += (hash12(gl_FragCoord.xy * 1.37 + 17.0) - 0.5) / 255.0;
  outColor = vec4(col, 1.0);
}`;

export interface PostParams {
  bloom: number;
  /** Light above this blooms, added on top (0: all of it blooms, mixed in). */
  bloomThreshold: number;
  /** Lens glare strength (0: none), the brightness it starts from, and the streaks' angle (radians). */
  glare: number;
  glareThreshold: number;
  glareAngle: number;
  exposure: number;
  saturation: number;
  punch: number;
  vignette: number;
  grain: number;
  aberration: number;
  flash: number;
  tint: [number, number, number];
}

export function defaultPost(): PostParams {
  return {
    bloom: 0.085,
    bloomThreshold: 0,
    glare: 0,
    glareThreshold: 1.5,
    glareAngle: 0.35,
    exposure: 1,
    saturation: 1.32,
    punch: 1.3,
    vignette: 0.38,
    grain: 0.032,
    aberration: 0,
    flash: 0,
    tint: [1, 1, 1],
  };
}

export class Post {
  private down: Program | null;
  private up: Program | null;
  private blit: Program | null;
  private glare: Program | null;
  private composite: Program | null;
  private mips: Target[] = [];
  private glareTarget: Target | null = null;
  private shockData = new Float32Array(16);
  /** How the scene and the bloom levels store light, and the gain light takes going into them. */
  private readonly format: TargetFormat;
  private readonly gain: number;

  constructor(
    private readonly gl: WebGL2RenderingContext,
    format: TargetFormat | boolean,
    private readonly emptyVao: WebGLVertexArrayObject,
  ) {
    this.format = format === true ? 'half' : format === false ? 'rgba8' : format;
    this.gain = lightGain(this.format);
    this.down = tryProgram(gl, FULLSCREEN_VS, DOWN_FS, 'bloom-down');
    this.up = tryProgram(gl, FULLSCREEN_VS, UP_FS, 'bloom-up');
    this.blit = tryProgram(gl, FULLSCREEN_VS, BLIT_FS, 'blit');
    this.glare = tryProgram(gl, FULLSCREEN_VS, GLARE_FS, 'glare');
    this.composite = tryProgram(gl, FULLSCREEN_VS, COMPOSITE_FS, 'composite');
  }

  resize(width: number, height: number): void {
    let w = Math.floor(width / 2);
    let h = Math.floor(height / 2);
    let level = 0;
    while (level < 7 && w >= 4 && h >= 4) {
      if (this.mips[level]) this.mips[level].resize(w, h);
      else this.mips[level] = new Target(this.gl, w, h, this.format);
      w = Math.floor(w / 2);
      h = Math.floor(h / 2);
      level++;
    }
    while (this.mips.length > level) this.mips.pop()?.dispose();
    const g = this.mips[1] ?? this.mips[0];
    if (g) {
      if (this.glareTarget) this.glareTarget.resize(g.width, g.height);
      else this.glareTarget = new Target(this.gl, g.width, g.height, this.format);
    }
  }

  /** Streaks the brightest light from a bloom level into the glare target. */
  private streak(p: PostParams): Target | null {
    const src = this.mips[1] ?? this.mips[0];
    const dst = this.glareTarget;
    if (!src || !dst || p.glare <= 0 || !this.glare || !this.down || !this.up) return null;
    const gl = this.gl;
    gl.disable(gl.BLEND);
    dst.bind();
    // The level holds light as stored, so the threshold is taken to the same scale.
    const threshold = p.glareThreshold * (this.gain === 1 ? 1 : LDR_GLARE_THRESHOLD) * this.gain;
    this.glare.use().i1('uSrc', 0).f2('uTexel', 1 / src.width, 1 / src.height).f1('uThreshold', threshold).f1('uAngle', p.glareAngle);
    src.sample(0);
    drawFullscreen(gl, this.emptyVao);
    return dst;
  }

  /**
   * Draws `src` stretched over the currently bound target (blending state untouched), its light
   * multiplied by `gain` (a background going into an 8-bit scene is scaled down to its range).
   */
  blitTo(src: Target, gain = 1): void {
    if (!this.blit) return;
    this.blit.use().i1('uSrc', 0).f1('uGain', gain);
    src.sample(0);
    drawFullscreen(this.gl, this.emptyVao);
  }

  private bloom(scene: Target, threshold: number): Target | null {
    const gl = this.gl;
    if (this.mips.length === 0 || !this.down || !this.up) return null;
    gl.disable(gl.BLEND);
    let src = scene;
    this.down.use().i1('uSrc', 0).f1('uThreshold', threshold);
    for (let i = 0; i < this.mips.length; i++) {
      const dst = this.mips[i];
      dst.bind();
      // The first pass reads the scene's light at its real level (to threshold it) and stores it
      // scaled like the scene; the rest only filter, so scale doesn't matter to them.
      const first = i === 0;
      this.down.f2('uTexel', 1 / src.width, 1 / src.height).i1('uKaris', first ? 1 : 0);
      this.down.f1('uDecode', first ? 1 / this.gain : 1).f1('uEncode', first ? this.gain : 1);
      src.sample(0);
      drawFullscreen(gl, this.emptyVao);
      src = dst;
    }
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE);
    this.up.use().i1('uSrc', 0).f1('uRadius', 1);
    for (let i = this.mips.length - 1; i > 0; i--) {
      const s = this.mips[i];
      const dst = this.mips[i - 1];
      dst.bind();
      this.up.f2('uTexel', 1 / s.width, 1 / s.height);
      s.sample(0);
      drawFullscreen(gl, this.emptyVao);
    }
    gl.disable(gl.BLEND);
    return this.mips[0];
  }

  /** Bloom + composite to the default framebuffer. */
  present(
    scene: Target,
    canvasW: number,
    canvasH: number,
    p: PostParams,
    time: number,
    shocks: readonly { x: number; y: number; radius: number; strength: number }[],
  ): void {
    const gl = this.gl;
    const bloom = this.composite ? this.bloom(scene, p.bloomThreshold) : null;
    const glare = bloom ? this.streak(p) : null;
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, canvasW, canvasH);
    gl.disable(gl.BLEND);
    if (!this.composite) {
      // No composite on this device: the scene as it is, rather than nothing.
      this.blitTo(scene, 1 / this.gain);
      return;
    }
    this.shockData.fill(0);
    for (let i = 0; i < Math.min(4, shocks.length); i++) {
      const s = shocks[i];
      this.shockData.set([s.x, s.y, s.radius, s.strength], i * 4);
    }
    const c = this.composite.use();
    c.i1('uScene', 0).i1('uBloomTex', 1).i1('uGlareTex', 2).f1('uGlare', glare ? p.glare : 0);
    c.f1('uBloomAdd', p.bloomThreshold > 0 ? 1 : 0).f1('uDecode', 1 / this.gain);
    c.f1('uBloom', bloom ? p.bloom : 0).f1('uExposure', p.exposure).f1('uSaturation', p.saturation).f1('uPunch', p.punch);
    c.f1('uVignette', p.vignette).f1('uGrain', p.grain).f1('uTime', time).f1('uAberration', p.aberration);
    c.f1('uFlash', p.flash).f1('uAspect', canvasW / canvasH);
    c.f3('uTint', p.tint[0], p.tint[1], p.tint[2]);
    c.f4v('uShock', this.shockData);
    scene.sample(0);
    (bloom ?? scene).sample(1);
    (glare ?? bloom ?? scene).sample(2);
    drawFullscreen(gl, this.emptyVao);
  }

  dispose(): void {
    for (const m of this.mips) m.dispose();
    this.glareTarget?.dispose();
    this.glare?.dispose();
    this.down?.dispose();
    this.up?.dispose();
    this.blit?.dispose();
    this.composite?.dispose();
  }
}
