<!--
  Messages from the universe: milestones (serif, centred) and discoveries (small, clickable).
-->
<script lang="ts">
  import { fade, fly } from 'svelte/transition';
  import { dismissToast, still, track, ui } from '../store.svelte';

  const LIFE: Record<string, number> = { milestone: 9000, discovery: 5000, quiet: 6000 };

  $effect(() => {
    track();
    const now = performance.now();
    // A discovery being read (hovered or focused) waits until it is let go.
    const held = document.querySelector<HTMLElement>('.toast.discovery:hover, .toast.discovery:focus')?.dataset.id;
    for (const t of ui.toasts) if (now - t.born > LIFE[t.tone] && String(t.id) !== held) dismissToast(t.id);
  });

  function open(id: number, codex?: string) {
    if (codex) {
      ui.codexFocus = codex;
      ui.panel = 'codex';
    }
    dismissToast(id);
  }
</script>

<div class="toasts" aria-live="polite">
  {#each ui.toasts as t (t.id)}
    {#if t.tone === 'discovery'}
      <button class="toast discovery" data-id={t.id} onclick={() => open(t.id, t.codex)} in:fly={{ y: still() ? 0 : 6, duration: 240 }} out:fade={{ duration: 320 }}>
        <span class="label">Discovered</span>
        <span class="what">{t.text}</span>
      </button>
    {:else}
      <p class="toast {t.tone}" in:fly={{ y: still() ? 0 : 10, duration: 700 }} out:fade={{ duration: 900 }}>{t.text}</p>
    {/if}
  {/each}
</div>

