/**
 * Knowledge: what the player remembers that no universe does. Bought with Insight between universes;
 * it never resets.
 */
import type { EraDef } from './era';
import type { EraId } from './state';

export interface KnowledgeDef {
  id: string;
  name: string;
  /** What remembering it does, in one or two plain sentences. */
  text: string;
  /** Insight cost of each level, in order (the number of levels is its length). */
  costs: readonly number[];
  /** The era it belongs to, for the "by heart" entries. */
  era?: EraId;
}

const heart = (era: EraId, name: string, text: string): KnowledgeDef => ({ id: `heart.${era}`, name, text, costs: [15], era });

export const KNOWLEDGE: readonly KnowledgeDef[] = [
  heart('soup', 'The Soup by heart', 'You know how baryogenesis goes: the Sakharov conditions start met, the Soup yields twice the energy, and its steps cost a quarter less.'),
  heart('nucleo', 'The first minutes by heart', 'Nucleosynthesis starts with its first two phenomena understood, yields twice the energy, and its steps cost a quarter less.'),
  heart('afterglow', 'Recombination by heart', 'The Afterglow starts with its first two phenomena understood, yields twice the energy, and its steps cost a quarter less.'),
  heart('dawn', 'The first stars by heart', 'Cosmic Dawn starts with its first two phenomena understood, yields twice the energy, and its steps cost a quarter less.'),
  heart('forge', 'The Forge by heart', 'The Forge starts with its first two phenomena understood, yields twice the energy, and its steps cost a quarter less.'),
  heart('galaxies', 'The Galaxies by heart', 'The Galaxies start with their first two phenomena understood, yield twice the energy, and their steps cost a quarter less.'),
  heart('night', 'The Long Night by heart', 'The Long Night starts with its first two phenomena understood, yields twice the energy, and its steps cost a quarter less.'),
  { id: 'seeds', name: 'More seeds', text: "Look closer at a dying universe's black holes: one more seed to choose from.", costs: [10, 25, 60] },
  { id: 'steady', name: 'Steady hand', text: "Seeds drift only half as far from their parent's numbers.", costs: [20, 50] },
  { id: 'sight', name: 'Second sight', text: 'Seeds show how their universe would end, and whether it would die young.', costs: [40] },
  { id: 'memory', name: 'Long memory', text: 'Every universe teaches half again as much Insight.', costs: [30, 80] },
  { id: 'patience', name: 'Patience', text: 'Time away counts for up to a day instead of half a day.', costs: [25] },
  {
    id: 'observer',
    name: 'The observer',
    text: 'You know what to look for. In a universe with friendly numbers, close enough to ours, you will notice when something looks back.',
    costs: [400],
  },
];

export function knowledgeDef(id: string): KnowledgeDef | undefined {
  return KNOWLEDGE.find((k) => k.id === id);
}

/** Phenomena an era starts with when known by heart: its first two, plus the Soup's Sakharov conditions. */
export function heartGrants(def: EraDef): string[] {
  const out = def.phenomena.slice(0, 2).map((p) => p.id);
  for (const p of def.phenomena) if (p.group === 'sakharov' && !out.includes(p.id)) out.push(p.id);
  return out;
}
