/**
 * Visual matter: a storm of particles that live entirely on the graphics card (transform feedback).
 * Near the game plane the fluid carries them; in depth, curl noise does; a thermal jitter keeps them
 * restless. They are drawn as light, the way stars are: a one-pixel core (the lens pass gives the
 * brightest their glare; nothing here draws a blob), brightness spread over orders of magnitude (most
 * barely there, a rare few blazing), twinkling, a streak behind the bright ones if asked, in
 * perspective so the field reads as a volume. Flashes and light fronts passing through light the
 * specks up. They are not game objects: they make the medium visible.
 */
import { bindTexture, tryProgram, type GLCaps, type Program } from './gl';
import { HEADER, SIMPLEX } from './glsl';
import type { LayerFrame, RenderLayer } from './renderer';

export interface StormConfig {
  count: number;
  /** Half-depth of the volume, and the camera's distance from the game plane (world units). */
  depth: number;
  focal: number;
  /** Lifetime range (seconds). */
  lifeMin: number;
  lifeMax: number;
  /** Curl-noise speed (world units per second) and feature size (world units). */
  swirl: number;
  swirlScale: number;
  /** How quickly specks take up the flow around them (per second), and how much the fluid counts. */
  drag: number;
  flowGain: number;
  /** Random kicks (world units per second, per √second): the restlessness of a hot medium. */
  jitter: number;
  /** Expansion: the rate everything recedes from the view's centre (per second). */
  spread: number;
  /**
   * Brightness (linear HDR, at the core) follows a long tail like the stars': the faintest speck's,
   * and above it each tenfold brighter is tenfold rarer when `magnitudePower` is 1 (higher: a longer
   * tail), up to `peak`.
   */
  faintest: number;
  peak: number;
  magnitudePower: number;
  /** A faint halo around the brightest only (0: pure pinpoints, the lens does the rest). */
  halo: number;
  /** How much each speck's brightness flickers (0–1): the medium seething. */
  twinkle: number;
  /** Seconds of motion drawn behind a speck as a streak (0: none), full above `streakFrom` brightness. */
  streak: number;
  streakFrom: number;
  /**
   * How much the medium lights the specks: near the plane they shine with the fluid's light where it
   * is (`light` times its brightness) and fade to `ambient` where it isn't.
   */
  light: number;
  ambient: number;
  /** Up to eight kinds of speck: linear colours, and how often each is born (weights). */
  palette: [number, number, number][];
  weights: number[];
  /**
   * Where the storm's randomness starts. Births and lives follow from it and from time alone, so with
   * the same steps the same frames come out (screenshots can be compared pixel for pixel).
   */
  seed: number;
}

export function defaultStorm(): StormConfig {
  return {
    count: 30000,
    depth: 700,
    focal: 1400,
    lifeMin: 3,
    lifeMax: 9,
    swirl: 60,
    swirlScale: 420,
    drag: 1.5,
    flowGain: 1,
    jitter: 0,
    spread: 0,
    faintest: 0.02,
    peak: 40,
    magnitudePower: 1,
    halo: 0,
    twinkle: 0,
    streak: 0,
    streakFrom: 1,
    light: 0,
    ambient: 1,
    palette: [[1, 1, 1]],
    weights: [1],
    seed: 1,
  };
}

/** Mulberry32: a small seeded generator, uniform in [0, 1). */
function seeded(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Light passing through the medium: a flash (point) or a light front racing outward (ring). */
/** A ring of push racing outward from a point (a shock through the specks). */
export interface StormKick {
  x: number;
  y: number;
  /** The ring's radius now (world units). */
  radius: number;
  /** How hard it throws specks outward (world units per second, per second). */
  push: number;
}

export interface StormLight {
  x: number;
  y: number;
  /** Brightness added to a speck at the light (linear HDR). */
  intensity: number;
  /** A point light's reach, or a front's current radius (world units). */
  radius: number;
  /** A front's thickness (world units); 0 for a point light. */
  width: number;
}

/** The field a storm can ride: velocity in cells per second with its grid size, and its light. */
export interface FlowSource {
  readonly velocityTexture: WebGLTexture | null;
  readonly dyeTexture: WebGLTexture | null;
  simSize(): [number, number];
}

const UPDATE_VS = HEADER + SIMPLEX + /* glsl */ `
layout(location = 0) in vec4 aPos;   // x, y, z, life left
layout(location = 1) in vec4 aVel;   // vx, vy, vz, kind + share of life at birth
out vec4 vPos;
out vec4 vVel;
uniform float uDt;
uniform float uTime;
uniform vec4 uView;
uniform sampler2D uFlow;
uniform float uFlowOn;
uniform vec2 uFlowScale;
uniform float uFlowGain;
uniform float uDepth;
uniform float uFocal;
uniform float uSwirl;
uniform float uSwirlScale;
uniform float uDrag;
uniform float uJitter;
uniform float uSpread;
uniform vec2 uLife;
uniform float uWeights[8];
uniform vec4 uKick[4];   // x, y, ring radius, push (world units per second, per second)
uniform int uKickCount;
uniform float uSeed;

float rand(float n) { return fract(sin(n * 12.9898 + 78.233) * 43758.5453); }

vec2 curl2(vec3 p) {
  const float e = 0.02;
  float n1 = snoise(p + vec3(0.0, e, 0.0));
  float n2 = snoise(p - vec3(0.0, e, 0.0));
  float n3 = snoise(p + vec3(e, 0.0, 0.0));
  float n4 = snoise(p - vec3(e, 0.0, 0.0));
  return vec2(n1 - n2, n4 - n3) / (2.0 * e);
}

void main() {
  vec3 p = aPos.xyz;
  vec3 v = aVel.xyz;
  float life = aPos.w - uDt;
  float tag = aVel.w;
  // Seen in perspective, the volume's far reaches cover more world than the near ones.
  float reach = (uFocal + p.z) / uFocal;
  vec2 rel = (p.xy - uView.xy) / (uView.zw * reach);
  bool gone = life <= 0.0 || abs(rel.x) > 1.25 || abs(rel.y) > 1.25;
  float s = float(gl_VertexID) * 1.618 + uTime * 7.31 + uSeed;
  if (gone) {
    // Most specks near the plane in focus, a few far in front or behind.
    float zr = rand(s + 3.1) * 2.0 - 1.0;
    float z = max(sign(zr) * zr * zr * uDepth, -0.7 * uFocal);
    float rz = (uFocal + z) / uFocal;
    p = vec3(uView.xy + (vec2(rand(s), rand(s + 1.7)) * 2.0 - 1.0) * uView.zw * rz * 1.15, z);
    v = vec3(0.0);
    float pick = rand(s + 5.3);
    float kind = 0.0;
    float acc = 0.0;
    for (int k = 0; k < 8; k++) {
      acc += uWeights[k];
      if (pick > acc) kind = float(k + 1);
    }
    float total = mix(uLife.x, uLife.y, rand(s + 9.9));
    life = total;
    tag = min(kind, 7.0) + min(0.999, total / uLife.y);
  }
  vec3 q = vec3(p.xy / uSwirlScale, p.z / uSwirlScale + uTime * 0.05);
  vec3 want = vec3(curl2(q) * uSwirl, snoise(q.yzx + 11.0) * uSwirl * 0.35);
  if (uFlowOn > 0.5) {
    vec2 uv = vec2((p.x - uView.x) / (2.0 * uView.z) + 0.5, 0.5 - (p.y - uView.y) / (2.0 * uView.w));
    vec2 flow = texture(uFlow, uv).xy * uFlowScale;
    // The fluid moves the plane; specks far in front or behind feel less of it.
    want.xy += flow * uFlowGain * exp(-abs(p.z) / (0.5 * uDepth));
  }
  want.xy += (p.xy - uView.xy) * uSpread;
  // Rings of push racing outward (a shock): specks at a ring are thrown outward, then drag settles them.
  for (int i = 0; i < 4; i++) {
    if (i >= uKickCount) break;
    vec2 d = p.xy - uKick[i].xy;
    float dist = length(d);
    float x = (dist - uKick[i].z) / 70.0;
    v.xy += (d / max(dist, 1.0)) * uKick[i].w * exp(-x * x) * uDt;
  }
  v += (want - v) * (1.0 - exp(-uDt * uDrag));
  vec3 kick = vec3(rand(s + 21.0), rand(s + 22.0), rand(s + 23.0)) * 2.0 - 1.0;
  v += kick * uJitter * sqrt(uDt);
  p += v * uDt;
  vPos = vec4(p, life);
  vVel = vec4(v, tag);
}`;

const UPDATE_FS = HEADER + /* glsl */ `
out vec4 outColor;
void main() { outColor = vec4(0.0); }`;

/** Shared by the point and streak passes: where a speck is on screen and how bright it shines. */
const SPECK = /* glsl */ `
layout(location = 0) in vec4 aPos;
layout(location = 1) in vec4 aVel;
uniform vec4 uView;
uniform float uFocal;
uniform float uFaint;
uniform float uPeak;
uniform float uPower;
uniform float uLifeMax;
uniform float uTime;
uniform float uTwinkle;
uniform vec3 uPalette[8];
uniform sampler2D uDye;
uniform float uDyeOn;
uniform float uLight;
uniform float uAmbient;
uniform float uDepth;
uniform vec4 uLights[8];
uniform float uLightWidth[8];
uniform int uLightCount;

float hash(float n) { return fract(sin(n * 91.3458) * 47453.5453); }

vec2 project(vec3 p) {
  float k = uFocal / (uFocal + p.z);
  vec2 sp = (p.xy - uView.xy) * k;
  return vec2(sp.x / uView.z, -sp.y / uView.w);
}

/** This speck's colour, and its brightness now (linear HDR, at the core). */
vec4 shine(int id) {
  float b = min(uPeak, uFaint * pow(max(hash(float(id) + 0.5), 1e-5), -uPower));
  float rate = 3.0 + 9.0 * hash(float(id) + 7.7);
  b *= 1.0 + uTwinkle * sin(uTime * rate + hash(float(id) + 3.3) * 6.2832);
  float kind = floor(aVel.w);
  float total = fract(aVel.w) * uLifeMax;
  float age = total - aPos.w;
  float fade = smoothstep(0.0, 0.8, age) * smoothstep(0.0, 1.2, aPos.w);
  float near = exp(-abs(aPos.z) / (0.35 * uDepth));
  float lit = uAmbient;
  if (uDyeOn > 0.5) {
    vec2 uv = vec2((aPos.x - uView.x) / (2.0 * uView.z) + 0.5, 0.5 - (aPos.y - uView.y) / (2.0 * uView.w));
    float l = dot(texture(uDye, uv).rgb, vec3(0.3333));
    lit = mix(uAmbient, uAmbient + uLight * l, near);
  }
  // Light passing through: flashes nearby, and fronts as they sweep past.
  float extra = 0.0;
  for (int i = 0; i < 8; i++) {
    if (i >= uLightCount) break;
    vec4 L = uLights[i];
    float d = length(aPos.xy - L.xy);
    float w = uLightWidth[i];
    extra += w > 0.0 ? L.z * exp(-pow((d - L.w) / w, 2.0)) : L.z / (1.0 + d * d / (L.w * L.w));
  }
  // Farther specks are dimmer (inverse square), nearer ones a little brighter.
  float k = min(uFocal / (uFocal + aPos.z), 1.5);
  return vec4(uPalette[int(kind)], (b * lit + extra * near) * fade * k * k);
}
`;

const POINT_VS = HEADER + SPECK + /* glsl */ `
uniform float uHalo;
uniform float uMaxPoint;
out vec3 vColor;
out float vBright;
out float vSize;
void main() {
  vec4 s = shine(gl_VertexID);
  gl_Position = vec4(project(aPos.xyz), 0.0, 1.0);
  // A pixel for the faint, two or three for the bright (room for a halo only if one is asked for).
  float size = clamp(1.0 + min(2.0, sqrt(s.a)) + uHalo * max(0.0, sqrt(s.a) - 1.0) * 8.0, 1.0, uMaxPoint);
  gl_PointSize = size;
  vColor = s.rgb;
  vBright = s.a;
  vSize = size;
}`;

const POINT_FS = HEADER + /* glsl */ `
in vec3 vColor;
in float vBright;
in float vSize;
uniform float uGain;
out vec4 outColor;
void main() {
  vec2 d = gl_PointCoord * 2.0 - 1.0;
  float rn = length(d);
  if (rn > 1.0) discard;
  float r = rn * vSize * 0.5;
  // A pinpoint: one pixel of light, white-hot when bright. A faint halo only on the brightest.
  float core = exp(-r * r / 0.18);
  float halo = vSize > 3.5 ? pow(1.0 + r * r / 2.0, -2.0) * (1.0 - smoothstep(0.5, 1.0, rn)) * 0.12 : 0.0;
  vec3 col = mix(vColor, vec3(1.0), clamp(vBright * 0.15, 0.2, 0.85)) * core + vColor * halo;
  outColor = vec4(col * vBright * uGain, 0.0);
}`;

const STREAK_VS = HEADER + SPECK + /* glsl */ `
uniform float uStreak;
uniform float uStreakFrom;
out vec3 vColor;
void main() {
  vec4 s = shine(gl_InstanceID);
  // Vertex 1 is the speck itself; vertex 0 is where it was uStreak seconds ago.
  float head = float(gl_VertexID);
  vec3 p = aPos.xyz - aVel.xyz * uStreak * (1.0 - head);
  gl_Position = vec4(project(p), 0.0, 1.0);
  // Only the bright specks draw their motion.
  float show = smoothstep(0.3 * uStreakFrom, uStreakFrom, s.a);
  vColor = mix(s.rgb, vec3(1.0), 0.5) * s.a * head * show * 0.18;
}`;

const STREAK_FS = HEADER + /* glsl */ `
in vec3 vColor;
uniform float uGain;
out vec4 outColor;
void main() { outColor = vec4(vColor * uGain, 0.0); }`;

export class Storm implements RenderLayer {
  readonly stage = 'matter' as const;
  config: StormConfig;
  /** The fluid (or other field) the specks ride, if any. */
  flow: FlowSource | null = null;
  /** Lights passing through this frame (up to eight; the caller refills it every frame). */
  lights: StormLight[] = [];
  /** Rings of push this frame (up to four; refilled by the caller every frame). */
  kicks: StormKick[] = [];
  private kickData = new Float32Array(16);
  private gl: WebGL2RenderingContext | null = null;
  private update: Program | null = null;
  private points: Program | null = null;
  private streaks: Program | null = null;
  private buffers: WebGLBuffer[] = [];
  /** Per buffer: a VAO reading one speck per vertex (update, points) and one per instance (streaks). */
  private vaos: WebGLVertexArrayObject[] = [];
  private instanced: WebGLVertexArrayObject[] = [];
  private tf: WebGLTransformFeedback | null = null;
  /**
   * What the flow and dye samplers read when there is no field: a sampler a program declares is live
   * even when a branch skips it, so left to whatever is bound it could point at the scene being drawn
   * into (a feedback loop WebGL refuses: nothing would draw).
   */
  private blank: WebGLTexture | null = null;
  private cur = 0;
  private count = 0;
  private maxPoint = 64;
  private time = 0;
  private weights = new Float32Array(8);
  private palette = new Float32Array(24);
  private lightData = new Float32Array(32);
  private lightWidth = new Float32Array(8);

  constructor(config: Partial<StormConfig> = {}) {
    this.config = { ...defaultStorm(), ...config };
  }

  init(gl: WebGL2RenderingContext, _caps: GLCaps): void {
    this.gl = gl;
    this.update = tryProgram(gl, UPDATE_VS, UPDATE_FS, 'storm:update', ['vPos', 'vVel']);
    this.points = tryProgram(gl, POINT_VS, POINT_FS, 'storm:points');
    this.streaks = tryProgram(gl, STREAK_VS, STREAK_FS, 'storm:streaks');
    if (!this.update || !this.points || !this.streaks) {
      this.update = this.points = this.streaks = null;
      return;
    }
    const range = gl.getParameter(gl.ALIASED_POINT_SIZE_RANGE) as Float32Array;
    this.maxPoint = range ? range[1] : 64;
    this.tf = gl.createTransformFeedback();
    this.blank = gl.createTexture();
    bindTexture(gl, 0, this.blank);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array(4));
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    bindTexture(gl, 0, null);
    this.allocate(this.config.count);
  }

  /** (Re)builds the particle buffers: every speck starts at the end of its life, so it is born fresh. */
  private allocate(count: number): void {
    const gl = this.gl!;
    for (const b of this.buffers) gl.deleteBuffer(b);
    for (const v of [...this.vaos, ...this.instanced]) gl.deleteVertexArray(v);
    this.buffers = [];
    this.vaos = [];
    this.instanced = [];
    this.count = count;
    const data = new Float32Array(count * 8);
    // Staggered deaths, so the first births are spread over the first seconds (the same every run).
    const rand = seeded(this.config.seed);
    for (let i = 0; i < count; i++) data[i * 8 + 3] = rand() * this.config.lifeMin - 0.5;
    for (let k = 0; k < 2; k++) {
      const buf = gl.createBuffer()!;
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, data, gl.DYNAMIC_COPY);
      for (const divisor of [0, 1]) {
        const vao = gl.createVertexArray()!;
        gl.bindVertexArray(vao);
        for (const [loc, offset] of [[0, 0], [1, 16]]) {
          gl.enableVertexAttribArray(loc);
          gl.vertexAttribPointer(loc, 4, gl.FLOAT, false, 32, offset);
          gl.vertexAttribDivisor(loc, divisor);
        }
        (divisor ? this.instanced : this.vaos).push(vao);
      }
      this.buffers.push(buf);
    }
    gl.bindVertexArray(null);
    gl.bindBuffer(gl.ARRAY_BUFFER, null);
    this.cur = 0;
  }

  draw(frame: LayerFrame): void {
    const gl = this.gl;
    const up = this.update;
    if (!gl || !up || !this.points || !this.streaks || !this.tf || this.vaos.length < 2) return;
    const c = this.config;
    if (c.count !== this.count) this.allocate(c.count);
    const dt = Math.min(frame.dt, 1 / 20);
    this.time += dt;
    const v = frame.view;
    // Lower quality moves and draws only the first share of the specks (the buffers keep them all, so
    // a change of level is instant), each a little brighter so the field doesn't look emptied (only a
    // little: the smaller scene of a lower level already spreads each speck over more pixels).
    const q = frame.quality;
    const share = Math.min(1, Math.max(0.05, q.particles));
    const live = Math.max(1, Math.round(this.count * share));
    const gain = Math.cbrt(1 / share);

    this.weights.fill(0);
    const sum = c.weights.reduce((t, w) => t + w, 0) || 1;
    c.weights.slice(0, 8).forEach((w, k) => (this.weights[k] = w / sum));
    this.palette.fill(0);
    c.palette.slice(0, 8).forEach((col, k) => this.palette.set(col, k * 3));

    // 1. Move every speck on the GPU.
    up.use().f1('uDt', dt).f1('uTime', this.time).f1('uDepth', c.depth).f1('uFocal', c.focal).f1('uSeed', (c.seed % 997) * 3.7);
    up.f1('uSwirl', c.swirl).f1('uSwirlScale', c.swirlScale).f1('uDrag', c.drag).f1('uJitter', c.jitter).f1('uSpread', c.spread);
    up.f2('uLife', c.lifeMin, c.lifeMax).f1('uFlowGain', c.flowGain);
    gl.uniform4fv(up.loc('uView'), v);
    gl.uniform1fv(up.loc('uWeights'), this.weights);
    const nk = Math.min(4, this.kicks.length);
    for (let i = 0; i < nk; i++) {
      const k = this.kicks[i];
      this.kickData.set([k.x, k.y, k.radius, k.push], i * 4);
    }
    gl.uniform4fv(up.loc('uKick'), this.kickData);
    gl.uniform1i(up.loc('uKickCount'), nk);
    const flowTex = this.flow?.velocityTexture ?? null;
    up.f1('uFlowOn', flowTex ? 1 : 0);
    if (flowTex && this.flow) {
      const [sw, sh] = this.flow.simSize();
      up.f2('uFlowScale', (2 * v[2]) / sw, (-2 * v[3]) / sh);
    }
    bindTexture(gl, 0, flowTex ?? this.blank);
    up.i1('uFlow', 0);
    gl.bindVertexArray(this.vaos[this.cur]);
    gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, this.tf);
    gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 0, this.buffers[1 - this.cur]);
    gl.enable(gl.RASTERIZER_DISCARD);
    gl.beginTransformFeedback(gl.POINTS);
    gl.drawArrays(gl.POINTS, 0, live);
    gl.endTransformFeedback();
    gl.disable(gl.RASTERIZER_DISCARD);
    gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 0, null);
    gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, null);
    this.cur = 1 - this.cur;

    // 2. Draw them into the scene, light adding up: streaks first, then the crisp cores.
    frame.scene.bind();
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE);
    const dyeTex = this.flow?.dyeTexture ?? null;
    const n = Math.min(8, this.lights.length);
    this.lightData.fill(0);
    this.lightWidth.fill(0);
    for (let i = 0; i < n; i++) {
      const L = this.lights[i];
      this.lightData.set([L.x, L.y, L.intensity * gain, Math.max(1, L.radius)], i * 4);
      this.lightWidth[i] = L.width;
    }
    const shared = (prog: Program) => {
      prog.use().f1('uFocal', c.focal).f1('uGain', frame.gain ?? 1);
      prog.f1('uFaint', c.faintest * gain).f1('uPeak', c.peak).f1('uPower', c.magnitudePower).f1('uLifeMax', c.lifeMax);
      prog.f1('uTime', this.time).f1('uTwinkle', c.twinkle);
      prog.f1('uLight', c.light).f1('uAmbient', c.ambient).f1('uDepth', c.depth);
      gl.uniform4fv(prog.loc('uView'), v);
      gl.uniform3fv(prog.loc('uPalette'), this.palette);
      gl.uniform4fv(prog.loc('uLights'), this.lightData);
      gl.uniform1fv(prog.loc('uLightWidth'), this.lightWidth);
      gl.uniform1i(prog.loc('uLightCount'), n);
      prog.f1('uDyeOn', dyeTex && c.light > 0 ? 1 : 0);
      bindTexture(gl, 0, dyeTex ?? this.blank);
      prog.i1('uDye', 0);
    };
    if (c.streak > 0) {
      shared(this.streaks);
      this.streaks.f1('uStreak', c.streak).f1('uStreakFrom', c.streakFrom);
      gl.bindVertexArray(this.instanced[this.cur]);
      gl.drawArraysInstanced(gl.LINES, 0, 2, live);
    }
    shared(this.points);
    this.points.f1('uHalo', c.halo).f1('uMaxPoint', Math.min(64, this.maxPoint));
    gl.bindVertexArray(this.vaos[this.cur]);
    gl.drawArrays(gl.POINTS, 0, live);
    gl.bindVertexArray(null);
  }

  dispose(): void {
    const gl = this.gl;
    if (!gl) return;
    for (const b of this.buffers) gl.deleteBuffer(b);
    for (const v of [...this.vaos, ...this.instanced]) gl.deleteVertexArray(v);
    if (this.tf) gl.deleteTransformFeedback(this.tf);
    if (this.blank) gl.deleteTexture(this.blank);
    this.blank = null;
    this.update?.dispose();
    this.points?.dispose();
    this.streaks?.dispose();
    this.buffers = [];
    this.vaos = [];
    this.instanced = [];
    this.tf = null;
    this.update = this.points = this.streaks = null;
  }
}
