<!--
  The periodic table by cosmic origin. Every element keeps its place: found ones in the colour of
  what made them, missing ones dashed, and the 35 with nothing left from any star dark.
-->
<script lang="ts">
  import { ELEMENTS, ORIGIN_COLOR, ORIGIN_LABEL, ORIGIN_TEXT, elementCodexId, tablePosition, type ElementInfo, type Origin } from '../../content/elements';
  import { untrack } from 'svelte';
  import type { Game } from '../../core/game';
  import { track } from '../store.svelte';

  let { g, focus = null }: { g: Game; focus?: number | null } = $props();

  const ORDER: Origin[] = ['bigbang', 'cosmic', 'lowmass', 'massive', 'whitedwarf', 'merger', 'unstable'];

  // The element the Codex was opened on (a discovery toast), chosen once.
  let selected = $state<number | null>(untrack(() => focus));

  const view = $derived.by(() => {
    track();
    const made = new Set((g.state.run.eras.forge as { made?: number[] } | undefined)?.made ?? []);
    const tiles = ELEMENTS.map((e) => ({ e, pos: tablePosition(e.z), found: e.origin !== 'unstable' && g.isDiscovered(elementCodexId(e.z)), here: made.has(e.z) }));
    const legend = ORDER.filter((o) => o !== 'unstable').map((o) => {
      const all = tiles.filter((t) => t.e.origin === o);
      return { o, found: all.filter((t) => t.found).length, total: all.length };
    });
    return { tiles, legend, here: made.size };
  });

  // A later jump (a discovery clicked with the Codex open) selects the new element.
  $effect(() => {
    if (focus === null) return;
    selected = focus;
    cursor = focus;
  });

  const current = $derived(selected ? ELEMENTS[selected - 1] : null);
  const entry = $derived(current ? g.codexEntry(elementCodexId(current.z)) : undefined);
  const currentFound = $derived(current ? view.tiles[current.z - 1].found : false);

  // Hovering, focusing or pressing a legend entry picks out its elements, so origins never rest on color alone.
  let only = $state<Origin | null>(null);
  let peek = $state<Origin | null>(null);
  const lit = $derived(peek ?? only);

  function pick(e: ElementInfo) {
    selected = selected === e.z ? null : e.z;
  }

  // The table is one Tab stop; arrow keys walk it like the chart it is (Home and End jump to H and Og).
  let tableEl: HTMLElement;
  let cursor = $state(untrack(() => focus) ?? 1);
  const AT = new Map(ELEMENTS.map((e) => [`${tablePosition(e.z).col},${tablePosition(e.z).row}`, e.z]));
  const STEP: Record<string, [number, number]> = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] };

  function walk(e: KeyboardEvent) {
    let to: number | undefined;
    if (e.key === 'Home') to = 1;
    else if (e.key === 'End') to = ELEMENTS.length;
    else if (STEP[e.key]) {
      const [dc, dr] = STEP[e.key];
      let { col, row } = tablePosition(cursor);
      for (let i = 0; i < 18 && to === undefined; i++) {
        col += dc;
        row += dr;
        to = AT.get(`${col},${row}`);
      }
    } else return;
    e.preventDefault();
    if (to === undefined) return;
    cursor = to;
    tableEl.querySelector<HTMLElement>(`[data-z="${to}"]`)?.focus();
  }
</script>

<!-- svelte-ignore a11y_no_noninteractive_element_interactions (arrow keys from the element buttons inside) -->
<div class="table" role="group" aria-label="Periodic table by origin. Arrow keys move between elements." bind:this={tableEl} onkeydown={walk}>
  {#each view.tiles as t (t.e.z)}
    <button
      class="el"
      class:found={t.found}
      class:dark={t.e.origin === 'unstable'}
      class:here={t.here}
      class:sel={selected === t.e.z}
      class:faded={lit !== null && t.e.origin !== lit}
      style="grid-column:{t.pos.col + 1}; grid-row:{t.pos.row + 1}; --c:{ORIGIN_COLOR[t.e.origin]}"
      onclick={() => pick(t.e)}
      onfocus={() => (cursor = t.e.z)}
      tabindex={t.e.z === cursor ? 0 : -1}
      data-z={t.e.z}
      aria-pressed={selected === t.e.z}
      aria-label={`${t.e.name}, ${t.e.origin === 'unstable' ? 'does not last' : `${ORIGIN_LABEL[t.e.origin]}${t.found ? '' : ', not found yet'}`}`}
    >
      <span class="z">{t.e.z}</span>
      <span class="sym">{t.e.symbol}</span>
    </button>
  {/each}
  <span class="gap" style="grid-column:3; grid-row:6">57–71</span>
  <span class="gap" style="grid-column:3; grid-row:7">89–103</span>
</div>

<div class="legend" role="group" aria-label="Show elements by origin">
  {#each [...view.legend, { o: 'unstable' as Origin, found: 0, total: 0 }] as l (l.o)}
    <button
      class="chip"
      class:dark={l.o === 'unstable'}
      class:on={only === l.o}
      style="--c:{ORIGIN_COLOR[l.o]}"
      aria-pressed={only === l.o}
      onclick={() => (only = only === l.o ? null : l.o)}
      onpointerenter={() => (peek = l.o)}
      onpointerleave={() => (peek = null)}
      onfocus={() => (peek = l.o)}
      onblur={() => (peek = null)}
    >
      <i></i>{ORIGIN_LABEL[l.o]}{#if l.total}&nbsp;<b>{l.found}/{l.total}</b>{/if}
    </button>
  {/each}
</div>

{#if current}
  <article class="detail">
    <h3>
      {current.name}<span class="dsym">{current.symbol}</span><span class="dz">{current.z}</span>
    </h3>
    <p class="origin" style="--c:{ORIGIN_COLOR[current.origin]}"><i></i>{ORIGIN_LABEL[current.origin]}</p>
    {#if current.origin === 'unstable'}
      <p>{ORIGIN_TEXT.unstable}</p>
      {#if current.note}<p>{current.note}</p>{/if}
    {:else if currentFound && entry}
      <p>{entry.text}</p>
      {#if entry.text !== ORIGIN_TEXT[current.origin]}<p class="quiet">{ORIGIN_TEXT[current.origin]}</p>{/if}
      {#if entry.bonus}<p class="bonus"><span class="label">Bonus</span> {entry.bonus.text}</p>{/if}
    {:else}
      <p class="quiet">Not found yet. {ORIGIN_TEXT[current.origin]}</p>
    {/if}
  </article>
{:else}
  <p class="pick">
    {view.here > 0 ? `${view.here} elements made in this universe. ` : ''}Select an element to read about it.
  </p>
{/if}
<p class="credit">Origins after Jennifer Johnson's chart (2019). Each element is credited to what made most of it.</p>

