/**
 * The Forge's codex: the periodic table by origin (one entry per element a star can leave behind)
 * and notes on how stars live and die. Facts are sourced in src/content/elements.ts and in the
 * comments below.
 */
import type { CodexEntry } from '../../core/codex';
import type { Modifier } from '../../core/stats';
import { MAKEABLE, ORIGIN_TEXT, elementCodexId, tablePosition, type ElementInfo } from '../../content/elements';

const era = 'forge' as const;

function mod(stat: string, value: number, source: string): Modifier {
  return { stat, kind: 'mul', value, source };
}

/** Elements with a bonus tied to what they really do; the rest get their origin's small bonus. */
const SPECIAL: Record<number, (name: string) => { text: string; mods: Modifier[] }> = {
  6: (n) => ({ text: 'Carbon is the catalyst of the CNO cycle: stars above 1.3 Suns shine 8 % brighter.', mods: [mod('forge.cno', 1.08, n)] }),
  8: (n) => ({ text: 'Oxygen is the main coolant of enriched gas: star formation +6 %.', mods: [mod('forge.sfr', 1.06, n)] }),
  14: (n) => ({ text: 'Silicate dust shields molecular clouds: star formation +4 %.', mods: [mod('forge.sfr', 1.04, n)] }),
  26: (n) => ({ text: 'An iron core is what collapses: supernovae give 10 % more energy.', mods: [mod('forge.snEnergy', 1.1, n)] }),
  28: (n) => ({ text: 'Nickel-56 decay keeps exploded stars glowing: Type Ia supernovae give 12 % more energy.', mods: [mod('forge.iaEnergy', 1.12, n)] }),
  79: (n) => ({ text: 'Kilonovae give 10 % more energy.', mods: [mod('forge.knEnergy', 1.1, n)] }),
};

function bonusFor(e: ElementInfo): CodexEntry['bonus'] {
  const special = SPECIAL[e.z];
  if (special) return special(e.name);
  switch (e.origin) {
    case 'lowmass':
      return { text: 'Red giants and planetary nebulae give 4 % more energy.', mods: [mod('forge.giant', 1.04, e.name)] };
    case 'massive':
      return { text: 'Supernovae give 4 % more energy.', mods: [mod('forge.snEnergy', 1.04, e.name)] };
    case 'whitedwarf':
      return { text: 'Type Ia supernovae give 6 % more energy.', mods: [mod('forge.iaEnergy', 1.06, e.name)] };
    case 'merger':
      return { text: 'Kilonovae give 5 % more energy.', mods: [mod('forge.knEnergy', 1.05, e.name)] };
    default:
      return undefined;
  }
}

const ELEMENT_ENTRIES: CodexEntry[] = MAKEABLE.map((e) => ({
  id: elementCodexId(e.z),
  title: e.name,
  symbol: e.symbol,
  chart: 'elements',
  era,
  text: e.note ?? ORIGIN_TEXT[e.origin],
  bonus: bonusFor(e),
  layout: tablePosition(e.z),
}));

