<!--
  The frame's right margin: the next epoch step (click or T takes it) and the phenomena, a typeset
  list (keys 1–9 buy them in order, as in the list).
-->
<script lang="ts">
  import { cosmicTime, energy } from '../../core/format';
  import Num from '../common/Num.svelte';
  import { game, track, ui } from '../store.svelte';
  import { advance, BUY_MODES, energyUnit, phenomenaItems } from '../view';
  import Row from './Row.svelte';

  const g = game();
  const id = $props.id();

  const v = $derived.by(() => {
    track();
    const next = g.inFinale ? null : g.nextStep;
    const blocker = g.stepBlocker();
    return {
      next,
      when: next ? cosmicTime(next.t) : null,
      cost: next ? energy(next.cost, energyUnit(g), g.state.settings.notation) : null,
      can: g.canAdvance(),
      blocker: blocker && blocker !== 'In progress' ? blocker : null,
      progress: next ? Math.min(1, g.state.run.energy / Math.max(1, next.cost)) : 0,
      list: g.inFinale ? null : phenomenaItems(g),
    };
  });

  const MODE_NAMES: Record<string, string> = { '×1': 'One at a time', '×10': 'Ten at a time', Max: 'As many as you can afford' };

  /** Arrow keys move the buy amount along, as in any radio group, and focus follows it. */
  function modeKey(e: KeyboardEvent): void {
    const step = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0;
    if (!step) return;
    e.preventDefault();
    const i = BUY_MODES.findIndex((m) => m.m === ui.buyMode);
    const next = (Math.max(0, i) + step + BUY_MODES.length) % BUY_MODES.length;
    ui.buyMode = BUY_MODES[next].m;
    const group = e.currentTarget as HTMLElement;
    queueMicrotask(() => group.querySelectorAll<HTMLElement>('[role="radio"]')[next]?.focus());
  }
</script>

<section class="actions">
  {#if v.next && v.when && v.cost}
    <div class="cap" id="{id}-next">Next</div>
    <button
      class="next"
      class:ready={v.can}
      onclick={() => advance(g)}
      aria-labelledby="{id}-next {id}-label"
      aria-describedby="{id}-detail"
      aria-keyshortcuts="T"
    >
      <span class="line" id="{id}-label">{v.next.label}</span>
      <span class="progress" aria-hidden="true"><i style="width: {v.progress * 100}%"></i></span>
      <span class="small detail" id="{id}-detail">
        <span class="dim"><Num parts={v.when} />, for <Num parts={v.cost} /></span>
        {#if v.blocker}<span class="faint blocker">{v.blocker}</span>{/if}
      </span>
      <kbd aria-hidden="true">T</kbd>
    </button>
  {/if}

  {#if v.list?.any}
    <div class="block">
      <div class="head">
        <span class="cap">Phenomena</span>
        {#if v.list.levelled}
          <!-- A radio group: one Tab stop (the amount chosen), arrow keys to change it. -->
          <div class="modes" role="radiogroup" aria-label="Buy amount" tabindex="-1" onkeydown={modeKey}>
            {#each BUY_MODES as mode (mode.label)}
              <button
                class="mode"
                class:on={ui.buyMode === mode.m}
                role="radio"
                aria-checked={ui.buyMode === mode.m}
                aria-label={MODE_NAMES[mode.label]}
                tabindex={ui.buyMode === mode.m ? 0 : -1}
                onclick={() => (ui.buyMode = mode.m)}>{mode.label}</button
              >
            {/each}
          </div>
        {/if}
      </div>
      <div class="list">
        {#each v.list.items as item (item.kind === 'card' ? item.def.id : 'g:' + item.id)}
          {#if item.kind === 'group'}
            <div class="group small dim">
              <span>{item.title}</span>
              {#if item.progress}<span>{item.progress[0]} of {item.progress[1]}</span>{/if}
            </div>
          {:else}
            <Row def={item.def} hotkey={item.key} />
          {/if}
        {/each}
      </div>
    </div>
  {/if}
</section>

<style>
  .actions {
    display: flex;
    flex-direction: column;
    max-height: 100%;
    min-height: 0;
  }
  .next {
    pointer-events: auto;
    position: relative;
    display: block;
    width: 100%;
    padding-right: 1.6rem;
    color: rgb(255 255 255 / 0.72);
    transition: color var(--med) var(--ease);
  }
  .next .line {
    display: block;
    font-size: 1.13rem;
    line-height: 1.3;
    text-wrap: balance;
  }
  .next:hover .line,
  .next:focus-visible .line {
    text-decoration: underline;
    text-underline-offset: 4px;
    text-decoration-thickness: 1px;
  }
  .next.ready {
    color: #fff;
  }
  .next .progress {
    display: block;
  }
  .next .progress i {
    left: 0;
    background: rgb(255 255 255 / 0.62);
    transition: width 300ms linear;
  }
  .next.ready .progress i {
    background: #fff;
  }
  .detail {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
  }
  .next kbd {
    position: absolute;
    right: 0;
    top: 0.2rem;
    font-family: var(--sans);
    color: rgb(255 255 255 / 0.36);
    border-color: rgb(255 255 255 / 0.18);
  }
  .next.ready kbd {
    color: #fff;
    border-color: rgb(255 255 255 / 0.6);
  }
  .head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
  }
  /*
   * The buy amount: read at a glance across a desk (the size of the list's own figures, the amounts
   * not chosen still well above the faint captions), each a full-size target, with no box around it.
   */
  .modes {
    pointer-events: auto;
    display: flex;
    gap: 0.2rem;
    margin-right: -0.45rem;
  }
  .mode {
    font-size: 0.93rem;
    line-height: 1;
    min-width: 1.5rem;
    padding: 0.4rem 0.45rem 0.35rem;
    text-align: center;
    color: rgb(255 255 255 / 0.6);
    transition: color var(--fast) var(--ease);
  }
  /* The rule sits under the text, inside the padding, so the target can be larger than what is drawn. */
  .mode::after {
    content: '';
    display: block;
    height: 1px;
    margin-top: 0.3rem;
    background: transparent;
    transition: background-color var(--fast) var(--ease);
  }
  .mode:hover {
    color: #fff;
  }
  .mode.on {
    color: #fff;
  }
  .mode.on::after {
    background: rgb(255 255 255 / 0.7);
  }
  .list {
    margin-top: 0.15rem;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    /* Room on the left for the hanging keys and the focus ring. */
    padding: 0.3rem 0.3rem 1.5rem 1.4rem;
    margin-left: -1.4rem;
    margin-right: -0.3rem;
    scrollbar-width: thin;
    scrollbar-color: rgb(255 255 255 / 0.2) transparent;
  }
  .group {
    display: flex;
    justify-content: space-between;
    margin: 0.9rem 0 0.2rem;
  }
  .group:first-child {
    margin-top: 0;
  }
</style>
