/**
 * The Galaxies simulation: the home galaxy's group from 13.8 to 100 billion years.
 *
 * Galaxy centres move as a small N-body set (softened point masses with dark halos); where halos
 * overlap, dynamical friction drags galaxies together until they merge. Each galaxy's stars are
 * particles that follow a rigid density-wave pattern while undisturbed (so arms never wind up) and
 * are integrated in the moving halo potentials during encounters, which is what raises tidal tails
 * and bridges (restricted N-body, as in Toomre & Toomre 1972). Major mergers turn disks into
 * ellipticals, start a starburst, and leave a pair of black holes that sinks, merges and flares as a
 * quasar. Galaxies outside the group's bound radius are carried away by dark energy, redden, and are
 * lost beyond the horizon unless flung back in.
 */
import type { EraModule, OfflineReport, PointerInfo, StockView, WorldLabel } from '../../core/era';
import type { Game } from '../../core/game';
import { count, toText } from '../../core/format';
import type { RGB } from '../../render/color';
import { Fx, FxPool } from '../../render/fx';
import { LineStyle } from '../../render/lines';
import type { BackgroundDef, Renderer } from '../../render/renderer';
import { Shape } from '../../render/sprites';
import { galaxiesBackground, type GalaxiesBgParams } from './background';
import { hubbleTile, hubbleType, isDisk, mergeOutcome, oldLight, type GalaxyProps, type Morph } from './model';

/** Gravitational constant in world units³ per second² per mass unit (10¹⁰ Suns). */
const G = 120;
/** eV per light unit per second, before the step weight. */
const E_UNIT = 1.9e44;
/** Light units per unit of star formation (young stars are bright). */
const YOUNG_LIGHT = 60;
/** Burst energy per 10¹⁰ Suns of stars when galaxies merge, in light-unit-seconds. */
const MERGE_UNITS = 80;
/** Quasar luminosity per 10⁸ Suns of black hole, in light units, and its decay time. */
const QUASAR_UNITS = 120;
const QUASAR_LIFE = 24;
/** Gravitational-wave burst when two black holes merge, per 10⁸ Suns. */
const GW_UNITS = 400;
/** Steady light of an active nucleus per 10⁸ Suns of black hole (to the 0.8 power). */
const AGN_UNITS = 12;
/** Star formation per unit gas per second, and cosmic gas inflow per disk galaxy per second. */
const SFE = 0.01;
const INFLOW = 0.004;
/** Seconds a black-hole pair takes to sink and merge after its galaxies have. */
const BH_SINK = 7;
/** Dynamical friction from the outer dark halos, per second, on a 10¹² Sun galaxy at one disk-sum apart. */
const HALO_FRICTION = 0.03;
/** Later steps cover far more time each, so slow friction gets further per second of play. */
const STEP_AGE = [1, 1.5, 2, 3, 5, 8, 12];
/** The least drag between home and its big neighbor, per second, wherever they are. */
const CORE_FRICTION = 0.008;
/**
 * "The great collision": until the clock reaches it, home and its big neighbor only draw closer,
 * without drag and without meeting (the real pair first meets ~4.5 billion years from now and is one
 * galaxy by ~20 billion years), so the step never narrates a collision already watched.
 */
const COLLISION_STEP = 2;
const MERGE_TIME = 7;
const RESHAPE_TIME = 4;
const SETTLE_TIME = 14;
const MAX_PARTICLES = 7000;
/** Most galaxies on screen at once (new arrivals and tidal dwarfs wait below it). */
const MAX_GALAXIES = 16;
/**
 * Dark energy (a cosmological constant): the push per unit of distance from the group's centre, in
 * world units/s². It never changes; bound members stay bound, and what is not bound accelerates away.
 */
const DARK_ENERGY = 8e-5;
/** Seconds between small galaxies falling in along the cosmic web, per step (none once it is cut off). */
const ARRIVAL_EVERY = [24, 30, 40, 55, 0, 0, 0];
/** Cosmic gas inflow left at each step (the web is cut off). */
const INFLOW_LEFT = [1, 0.75, 0.5, 0.32, 0.12, 0.04, 0];

const enum Pop {
  Bulge,
  Disk,
  Young,
  Knot,
  Dust,
}

interface Galaxy extends GalaxyProps {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  spin: 1 | -1;
  /** Pattern rotation angle. */
  angle: number;
  /** Orientation of an elliptical's long axis or a bar. */
  tilt: number;
  arms: number;
  /** Seconds left in free (integrated) mode; 0 = following the pattern. */
  disturbed: number;
  /** Starburst strength (decays). */
  burst: number;
  /** Quasar luminosity in light units (decays). */
  quasar: number;
  home: boolean;
  neighbor: boolean;
  bound: boolean;
  /** 0..1 reddening of a receding galaxy. */
  redshift: number;
  lostT: number;
  mergingInto: number;
  mergeT: number;
  bhPair: number;
  ring: number;
  reshape: number;
  shells: number;
  label: string;
  /** Recent encounter partners (id → seconds of cooldown), so a pass counts once. */
  met: Map<number, number>;
}

type NewGalaxy = Partial<SavedGalaxy> & { morph: Morph; stars: number; x: number; y: number };

interface SavedGalaxy extends GalaxyProps {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  spin: 1 | -1;
  tilt: number;
  arms: number;
  home: boolean;
  neighbor: boolean;
  label: string;
  /** Mid-merger when saved: the galaxy it is sinking into, and how far along (older saves lack both). */
  mergingInto?: number;
  mergeT?: number;
}

export interface GalaxiesState {
  galaxies: SavedGalaxy[];
  nextId: number;
  mergers: number;
  majors: number;
  flybys: number;
  quasars: number;
  lost: number;
  /** Light units of stars stripped into the space between galaxies. */
  debris: number;
  everFlung: boolean;
  flungOut: boolean;
  /** Galaxies that fell in along the cosmic web (older saves lack it). */
  arrivals?: number;
}

function defaults(): GalaxiesState {
  return { galaxies: [], nextId: 1, mergers: 0, majors: 0, flybys: 0, quasars: 0, lost: 0, debris: 0, everFlung: false, flungOut: false };
}

/** Disk radius from stellar mass (10¹⁰ Suns). */
function radiusFor(stars: number): number {
  return Math.max(10, 52 * stars ** 0.35);
}

/** Stable random in [0, 1), for cosmetic layout that must not flicker from frame to frame. */
function hash(id: number, k: number): number {
  const s = Math.sin(id * 12.9898 + k * 78.233) * 43758.5453;
  return s - Math.floor(s);
}

export class GalaxiesEra implements EraModule {
  private readonly s: GalaxiesState;
  private readonly fx = new FxPool(700);
  private readonly bgParams: GalaxiesBgParams;
  private readonly bg: BackgroundDef;
  private gal: Galaxy[] = [];

  // Star particles.
  private readonly px = new Float32Array(MAX_PARTICLES);
  private readonly py = new Float32Array(MAX_PARTICLES);
  /**
   * A free star's velocity: relative to its galaxy while it has one (so whatever moves the galaxy, a
   * fling or the drag of another's halo, carries its stars along), absolute once it is debris.
   */
  private readonly pvx = new Float32Array(MAX_PARTICLES);
  private readonly pvy = new Float32Array(MAX_PARTICLES);
  private readonly sx = new Float32Array(MAX_PARTICLES);
  private readonly sy = new Float32Array(MAX_PARTICLES);
  private readonly r0 = new Float32Array(MAX_PARTICLES);
  private readonly th0 = new Float32Array(MAX_PARTICLES);
  private readonly owner = new Int32Array(MAX_PARTICLES);
  private readonly free = new Uint8Array(MAX_PARTICLES);
  private readonly pop = new Uint8Array(MAX_PARTICLES);
  private readonly life = new Float32Array(MAX_PARTICLES);
  private np = 0;

  private halfW = 889;
  private halfH = 500;
  private t = 0;
  private idle = 0;
  private cx = 0;
  private cy = 0;
  private boundR = 500;
  /** Mass of the group (its core and everything bound to it). */
  private groupM = 270;
  /** The uniform pull of our viewing frame, which follows the group. */
  private frameAx = 0;
  private frameAy = 0;
  /** Seconds until the next galaxy falls in. */
  private arrivalT = 20;
  private redshift = 0;

  private sf = 1;
  private inflowMult = 1;
  private burstMult = 1;
  private barChance = 0.3;
  private quasarMult = 1;
  private friction = 1;
  private tidal = 0;
  private cannibal = 0;
  private gw = 1;
  private halo = 1;
  private ihl = 0;
  private oldMult = 1;

  private grabId = 0;
  private pX = 0;
  private pY = 0;
  private hoverId = 0;
  private path: number[] = [];
  private pathClock = 0;
  private unsub: (() => void)[] = [];
  private intro = 0;

  private finaleT = -1;
  private finaleDone: (() => void) | null = null;
  private tallied = false;

  constructor(private readonly g: Game) {
    const run = g.state.run;
    this.s = (run.eras.galaxies as GalaxiesState | undefined) ?? defaults();
    run.eras.galaxies = this.s;
    this.bgParams = { redshift: 0, inflow: 1, cx: 0, cy: 0, bound: 500, haze: 0, pulse: 0 };
    this.bg = galaxiesBackground(this.bgParams);
  }

  // ───────────────────────────────────────── lifecycle

  enter(fresh: boolean): void {
    const g = this.g;
    g.renderer?.setBackground(this.bg);
    this.refreshStats();
    this.unsub.push(g.stats.onChange(() => this.refreshStats()));
    this.syncStepFlags();
    if (fresh || !this.s.galaxies.length) this.createRoster();
    else this.restore(this.s.galaxies);
    for (const gx of this.gal) this.discoverType(gx);
    g.discover('local-group');
    this.redshift = Math.min(1, this.step / 6);
    if (fresh) this.intro = 1.6;
  }

  exit(): void {
    for (const u of this.unsub) u();
    this.unsub = [];
    const cam = this.g.renderer?.camera;
    if (cam) {
      cam.zoom = 1;
      cam.x = 0;
      cam.y = 0;
    }
  }

  resize(halfW: number, halfH: number): void {
    const sx = halfW / this.halfW;
    this.halfW = halfW;
    this.halfH = halfH;
    for (const gx of this.gal) gx.x *= sx;
    for (let i = 0; i < this.np; i++) this.px[i] *= sx;
  }

  private refreshStats(): void {
    const st = this.g.stats;
    this.sf = st.get('galaxies.sf');
    this.inflowMult = st.get('galaxies.inflow');
    this.burstMult = st.get('galaxies.burst');
    this.barChance = st.get('galaxies.bar');
    this.quasarMult = st.get('galaxies.quasar');
    this.friction = st.get('galaxies.friction');
    this.tidal = st.get('galaxies.tidal');
    this.cannibal = st.get('galaxies.cannibal');
    this.gw = st.get('galaxies.gw');
    this.halo = st.get('galaxies.halo');
    this.ihl = st.get('galaxies.ihl');
    this.oldMult = st.get('galaxies.old');
  }

  private get step(): number {
    return this.g.state.run.step;
  }

  private get weight(): number {
    return 10 ** this.step;
  }

  private syncStepFlags(): void {
    for (let i = 1; i <= 6; i++) this.g.setFlag(`galaxies.step${i}`, this.step >= i);
  }

  // ───────────────────────────────────────── galaxies

  /** The group as it is today, seeded from what this universe's home galaxy became in Era V. */
  private createRoster(): void {
    const rng = this.g.sim;
    const legacy = this.g.state.run.legacy;
    const bhSeed = 4e6 * Math.min(2, Math.max(0.5, ((legacy.blackHoles ?? 1e10) / 1e10) ** 0.15));
    const homeStars = Math.min(9, Math.max(4, 6 * ((legacy.galaxyStars ?? 3e11) / 3e11) ** 0.2));
    const W = this.halfW;
    const H = this.halfH;
    const add = (o: NewGalaxy) => this.spawn(o);
    const hx = -0.32 * W;
    const hy = 0.12 * H;
    // Home and its big neighbour on a wide, bound orbit: a first pass, then (most likely) a merger.
    const nx = 0.44 * W;
    const ny = -0.1 * H;
    const sep = Math.hypot(nx - hx, ny - hy);
    const ux = (nx - hx) / sep;
    const uy = (ny - hy) / sep;
    const relX = -1.5 * ux - 3 * uy;
    const relY = -1.5 * uy + 3 * ux;
    const hvx = -relX * 0.6;
    const hvy = -relY * 0.6;
    add({ morph: 'barred', stars: homeStars, gas: homeStars * 0.12, mass: 100, bh: bhSeed, bulge: 0.22, x: hx, y: hy, vx: hvx, vy: hvy, spin: 1, home: true, label: 'Home' });
    add({ morph: 'spiral', stars: 10, gas: 1.2, mass: 150, bh: 1.4e8, bulge: 0.24, x: nx, y: ny, vx: relX * 0.4, vy: relY * 0.4, spin: -1, neighbor: true });
    // Satellites on orbits: the large cloud plunging (it falls in first), the others nearly circular.
    const orbit = (host: { x: number; y: number; vx: number; vy: number; m: number }, ox: number, oy: number, frac: number): [number, number] => {
      const d = Math.hypot(ox, oy);
      const v = Math.sqrt((G * host.m) / d) * frac;
      return [host.vx + (-oy / d) * v, host.vy + (ox / d) * v];
    };
    const homeHost = { x: hx, y: hy, vx: hvx, vy: hvy, m: 100 };
    const nbHost = { x: nx, y: ny, vx: relX * 0.4, vy: relY * 0.4, m: 150 };
    const [m33vx, m33vy] = orbit(nbHost, 0.66 * W - nx, 0.4 * H - ny, 0.9);
    add({ morph: 'spiral', stars: 0.5, gas: 0.35, mass: 6, bh: 1e5, bulge: 0.08, x: 0.66 * W, y: 0.4 * H, vx: m33vx, vy: m33vy });
    const [lvx, lvy] = orbit(homeHost, 150, -36, 0.6);
    add({ morph: 'irregular', stars: 0.3, gas: 0.12, mass: 10, bh: 0, x: hx + 150, y: hy - 36, vx: lvx, vy: lvy });
    const [svx, svy] = orbit(homeHost, 112, 92, 0.9);
    add({ morph: 'irregular', stars: 0.05, gas: 0.04, mass: 1.5, bh: 0, x: hx + 112, y: hy + 92, vx: svx, vy: svy });
    for (let k = 0; k < 6; k++) {
      const host = k < 3 ? homeHost : nbHost;
      const a = rng.angle();
      const d = rng.range(240, 400);
      const [dvx, dvy] = orbit(host, Math.cos(a) * d, Math.sin(a) * d, 1);
      add({ morph: 'dwarf', stars: rng.range(0.001, 0.01), gas: 0, mass: rng.range(0.3, 1.2), bh: 0, x: host.x + Math.cos(a) * d, y: host.y + Math.sin(a) * d, vx: dvx, vy: dvy });
    }
    // Other groups at the edges: unbound, already receding.
    const outer: [Morph, number, number, number][] = [
      ['spiral', 4, -0.92, -0.8],
      ['elliptical', 7, 0.95, 0.8],
      ['spiral', 3, -0.95, 0.8],
      ['barred', 5, 0.95, -0.85],
      ['irregular', 0.6, 0.98, 0.05],
      ['spiral', 2.5, -0.95, -0.15],
    ];
    // They move off with the Hubble flow, faster the farther they are.
    for (const [morph, stars, fx, fy] of outer) {
      const x = fx * W;
      const y = fy * H;
      const ox = x - 0.1 * W;
      const oy = y;
      const od = Math.hypot(ox, oy);
      const v = 1.5 + 0.002 * od;
      add({ morph, stars, x, y, flat: morph === 'elliptical' ? 0.3 : 0, bulge: morph === 'elliptical' ? 1 : 0.15 + rng.range(0, 0.15), vx: (ox / od) * v, vy: (oy / od) * v });
    }
    // Satellites that start close to their hosts are already in orbit, not arriving.
    for (const a of this.gal)
      for (const b of this.gal) {
        if (a !== b && Math.hypot(a.x - b.x, a.y - b.y) < (a.radius + b.radius) * 1.6) a.met.set(b.id, 40);
      }
  }

  /**
   * Brings back a saved group, centred on screen around home. Saves from earlier versions could have
   * drifted far off screen, lost home in the middle of the great merger (the galaxy it was sinking
   * into carries on as home), or lost the big neighbor (which made "One galaxy" impossible): the role
   * passes to the biggest galaxy left, or the step's need is met if none is.
   */
  private restore(saved: SavedGalaxy[]): void {
    const core = saved.filter((sg) => sg.home || sg.neighbor);
    const anchor = core.length ? core : saved.slice(0, 1);
    const m = anchor.reduce((t, sg) => t + sg.mass, 0) || 1;
    const ox = anchor.reduce((t, sg) => t + sg.x * sg.mass, 0) / m;
    const oy = anchor.reduce((t, sg) => t + sg.y * sg.mass, 0) / m;
    for (const sg of saved) this.addGalaxy({ ...sg, x: sg.x - ox, y: sg.y - oy });
    for (const a of this.gal) {
      if (a.mergingInto && !this.byId(a.mergingInto)) {
        a.mergingInto = 0;
        a.mergeT = 0;
      }
    }
    if (!this.gal.some((a) => a.home)) {
      const heir = this.gal.find((a) => a.neighbor) ?? [...this.gal].sort((a, b) => b.mass - a.mass)[0];
      if (heir) {
        if (heir.neighbor) {
          this.g.setFlag('galaxies.greatMerger');
          this.g.discover('milkomeda');
        }
        heir.home = true;
        heir.neighbor = false;
        heir.label = 'Home';
      }
    }
    if (!this.g.flag('galaxies.greatMerger') && !this.gal.some((a) => a.neighbor)) {
      const big = this.gal.filter((a) => !a.home).sort((a, b) => b.mass - a.mass)[0];
      if (big) big.neighbor = true;
      else this.g.setFlag('galaxies.greatMerger');
    }
  }

  /** A new galaxy, with the usual proportions for whatever is not given. */
  private spawn(o: NewGalaxy): Galaxy {
    const rng = this.g.sim;
    const stars = o.stars;
    return this.addGalaxy({
      id: this.s.nextId++,
      morph: o.morph,
      stars,
      gas: o.gas ?? stars * 0.15,
      mass: o.mass ?? stars * 16,
      bh: o.bh ?? 1e6 * stars ** 1.2,
      bulge: o.bulge ?? 0.2,
      flat: o.flat ?? 0,
      x: o.x,
      y: o.y,
      vx: o.vx ?? 0,
      vy: o.vy ?? 0,
      radius: o.radius ?? radiusFor(stars),
      spin: o.spin ?? (rng.chance(0.5) ? 1 : -1),
      tilt: o.tilt ?? rng.angle(),
      arms: o.arms ?? 2,
      home: o.home ?? false,
      neighbor: o.neighbor ?? false,
      label: o.label ?? '',
    });
  }

  /**
   * A small galaxy falls into the group along a filament of the cosmic web: in from just past the
   * screen's edge (still inside the bound region), onto a roomy orbit as a new satellite.
   */
  private arrive(): void {
    if (this.gal.filter((a) => a.lostT < 0).length >= MAX_GALAXIES || this.np > MAX_PARTICLES - 400) return;
    const rng = this.g.sim;
    // Well inside the bound region, so a nudge in the crowd does not tip it out again.
    const room = this.boundR * 0.8;
    let x = 0;
    let y = 0;
    let found = false;
    for (let k = 0; k < 12 && !found; k++) {
      // A point on the screen's border, pushed just out of sight.
      const u = rng.range(-1, 1);
      if (rng.chance(0.5)) {
        x = u * this.halfW;
        y = (rng.chance(0.5) ? 1 : -1) * (this.halfH + 40);
      } else {
        x = (rng.chance(0.5) ? 1 : -1) * (this.halfW + 40);
        y = u * this.halfH;
      }
      found = Math.hypot(x - this.cx, y - this.cy) < room;
    }
    // The bound region no longer reaches past the edges: nothing more falls in.
    if (!found) return;
    const ox = x - this.cx;
    const oy = y - this.cy;
    const r = Math.hypot(ox, oy);
    const vc = Math.sqrt((G * this.groupM) / r);
    const turn = rng.chance(0.5) ? 1 : -1;
    const vt = vc * rng.range(0.72, 0.95) * turn;
    const vx = (-oy / r) * vt - (ox / r) * 1.5;
    const vy = (ox / r) * vt - (oy / r) * 1.5;
    const kind = rng.next();
    if (kind < 0.55) {
      const stars = rng.range(0.04, 0.25);
      this.spawn({ morph: 'irregular', stars, gas: stars * rng.range(1, 2), bh: 0, x, y, vx, vy });
    } else if (kind < 0.85) {
      const stars = rng.range(0.3, 1.5);
      this.spawn({ morph: rng.chance(this.barChance) ? 'barred' : 'spiral', stars, gas: stars * 0.4, bulge: rng.range(0.05, 0.2), x, y, vx, vy });
    } else {
      this.spawn({ morph: 'dwarf', stars: rng.range(0.002, 0.01), gas: 0, mass: rng.range(0.3, 1.2), bh: 0, x, y, vx, vy });
    }
    this.s.arrivals = (this.s.arrivals ?? 0) + 1;
    if (this.s.arrivals === 1) this.g.toast('A small galaxy is falling into the group along the cosmic web.', 'quiet');
    this.g.discover('infall');
  }

  private addGalaxy(sg: SavedGalaxy): Galaxy {
    const gx: Galaxy = {
      ...sg,
      angle: this.g.fx.angle(),
      disturbed: 0,
      burst: 0,
      quasar: 0,
      bound: true,
      redshift: 0,
      lostT: -1,
      mergingInto: sg.mergingInto ?? 0,
      mergeT: sg.mergeT ?? 0,
      bhPair: 0,
      ring: 0,
      reshape: 0,
      shells: 0,
      met: new Map(),
    };
    this.gal.push(gx);
    this.populate(gx);
    return gx;
  }

  private byId(id: number): Galaxy | undefined {
    return this.gal.find((gx) => gx.id === id);
  }

  /** Star particles for a galaxy, laid out in its pattern (polar coordinates about its centre). */
  private populate(gx: Galaxy): void {
    const rng = this.g.fx;
    const n = Math.round(Math.min(700, Math.max(30, 260 * gx.stars ** 0.32)));
    const R = gx.radius;
    for (let k = 0; k < n && this.np < MAX_PARTICLES; k++) {
      const i = this.np++;
      let r: number;
      let th: number;
      let pop = Pop.Disk;
      const u = rng.next();
      if (gx.morph === 'elliptical' || gx.morph === 'dwarf') {
        r = R * (gx.morph === 'dwarf' ? 0.55 : 0.6) * (-Math.log(1 - 0.98 * rng.next())) ** 1.1 * 0.6;
        th = rng.angle();
        pop = Pop.Bulge;
      } else if (gx.morph === 'irregular') {
        const clump = Math.floor(u * 4);
        const ca = clump * 1.9 + gx.tilt;
        const cr = R * 0.35 * (clump === 0 ? 0 : 1);
        const ox = Math.cos(ca) * cr + rng.gauss() * R * 0.28;
        const oy = Math.sin(ca) * cr + rng.gauss() * R * 0.28;
        r = Math.hypot(ox, oy);
        th = Math.atan2(oy, ox);
        pop = rng.chance(0.25) ? Pop.Young : rng.chance(0.08) ? Pop.Knot : Pop.Disk;
      } else if (u < gx.bulge * 0.9) {
        r = R * 0.16 * Math.sqrt(-Math.log(1 - 0.97 * rng.next()));
        th = rng.angle();
        pop = Pop.Bulge;
        if (gx.morph === 'barred' && rng.chance(0.6)) {
          // The bar: a long box of old stars through the centre.
          const bx = (rng.next() * 2 - 1) * R * 0.42;
          const by = rng.gauss() * R * 0.05;
          r = Math.hypot(bx, by);
          th = Math.atan2(by, bx);
        }
      } else if (gx.morph === 'lenticular') {
        r = R * 0.85 * Math.sqrt(rng.next());
        th = rng.angle();
        pop = Pop.Bulge;
      } else {
        // Arms: logarithmic spirals with scatter; young stars and nebulae crowd the arm crests.
        r = R * (0.18 + 0.82 * rng.next() ** 0.85);
        const arm = Math.floor(rng.next() * gx.arms);
        const crest = rng.gauss() * (0.22 + 0.12 * (r / R));
        th = (arm * Math.PI * 2) / gx.arms + Math.log(r / (R * 0.18)) / 0.38 + crest;
        const near = Math.abs(crest) < 0.12;
        pop = rng.chance(0.08) ? Pop.Dust : near ? (rng.chance(0.12) ? Pop.Knot : Pop.Young) : Pop.Disk;
        if (pop === Pop.Dust) th -= 0.18 * gx.spin;
        if (rng.chance(0.12)) th = rng.angle();
      }
      this.r0[i] = r;
      this.th0[i] = th;
      this.pop[i] = pop;
      this.owner[i] = gx.id;
      this.free[i] = 0;
      this.life[i] = 1;
      const [x, y] = this.patternPos(gx, r, th);
      this.px[i] = x;
      this.py[i] = y;
    }
  }

  private patternPos(gx: Galaxy, r: number, th: number): [number, number] {
    const a = th * gx.spin + gx.angle;
    let x = Math.cos(a) * r;
    let y = Math.sin(a) * r;
    if (gx.morph === 'elliptical' || gx.morph === 'dwarf') {
      // An elliptical: squashed along its own axis, turning very slowly.
      const c = Math.cos(gx.tilt);
      const s = Math.sin(gx.tilt);
      const u = Math.cos(th) * r;
      const v = Math.sin(th) * r * (1 - gx.flat);
      x = c * u - s * v;
      y = s * u + c * v;
    }
    return [gx.x + x, gx.y + y];
  }

  /** Squared circular velocity of a galaxy's halo (a flat rotation curve out to ~3 radii). */
  private vc2(gx: Galaxy): number {
    return (G * gx.mass) / (3 * gx.radius);
  }

  /** Puts a galaxy's stars into free flight, with the velocities their orbits had (relative to it). */
  private disturb(gx: Galaxy, seconds: number): void {
    if (gx.disturbed <= 0) {
      const vc = Math.sqrt(this.vc2(gx));
      const core = gx.radius * 0.15;
      for (let i = 0; i < this.np; i++) {
        if (this.owner[i] !== gx.id || this.free[i]) continue;
        const dx = this.px[i] - gx.x;
        const dy = this.py[i] - gx.y;
        const r = Math.hypot(dx, dy) || 1;
        const v = (vc * r) / Math.sqrt(r * r + core * core) * (gx.morph === 'elliptical' || gx.morph === 'dwarf' ? 0.35 : 1);
        this.pvx[i] = (-dy / r) * v * gx.spin;
        this.pvy[i] = (dx / r) * v * gx.spin;
        this.free[i] = 1;
      }
    }
    gx.disturbed = Math.max(gx.disturbed, seconds);
  }

  /** Back to the pattern: stars keep their places; those flung far out become intragroup debris. */
  private settle(gx: Galaxy): void {
    // Each star particle stands for an equal share of its galaxy's stars.
    let n = 0;
    for (let i = 0; i < this.np; i++) if (this.owner[i] === gx.id) n++;
    const share = gx.stars / Math.max(1, n);
    for (let i = 0; i < this.np; i++) {
      if (this.owner[i] !== gx.id || !this.free[i]) continue;
      const dx = this.px[i] - gx.x;
      const dy = this.py[i] - gx.y;
      const r = Math.hypot(dx, dy);
      if (r > gx.radius * 1.9) {
        this.owner[i] = -1;
        this.life[i] = 40;
        this.pvx[i] += gx.vx;
        this.pvy[i] += gx.vy;
        this.s.debris += share;
        continue;
      }
      this.r0[i] = r;
      const a = Math.atan2(dy, dx);
      this.th0[i] = (a - gx.angle) * gx.spin;
      this.free[i] = 0;
    }
  }

  private discoverType(gx: Galaxy): void {
    this.g.discover(hubbleTile(hubbleType(gx)));
  }

  // ───────────────────────────────────────── events

  private gain(units: number, x?: number, y?: number): void {
    this.g.gain(units * E_UNIT * this.weight, x, y);
  }

  /** Two galaxies pass close: tides raise tails, gas is squeezed into a starburst, a bar may form. */
  private flyby(a: Galaxy, b: Galaxy, closeness: number): void {
    const g = this.g;
    this.s.flybys++;
    for (const [me, other] of [
      [a, b],
      [b, a],
    ] as const) {
      this.disturb(me, SETTLE_TIME);
      const ratio = other.mass / me.mass;
      me.burst = Math.min(3, me.burst + closeness * Math.min(1.5, ratio) * this.burstMult);
      if (me.morph === 'spiral' && g.sim.chance(this.barChance * closeness)) {
        me.morph = 'barred';
        this.discoverType(me);
      } else if (isDisk(me.morph) && ratio > 2 && me.mass < 15) {
        me.morph = 'irregular';
        this.discoverType(me);
      }
    }
    // A small galaxy fired through a disk's centre sends a ring rolling outward.
    const big = a.mass >= b.mass ? a : b;
    const small = big === a ? b : a;
    const d = Math.hypot(a.x - b.x, a.y - b.y);
    const vrel = Math.hypot(a.vx - b.vx, a.vy - b.vy);
    if (isDisk(big.morph) && small.mass < 0.35 * big.mass && d < big.radius * 0.3 && vrel > 22 && big.ring <= 0) {
      big.ring = 8;
      big.burst = Math.min(3, big.burst + 1);
      this.ringWave(big);
      g.discover('gal-ring');
      g.sfx('galaxies.ring', big.x);
    }
    if (a.burst > 0.6 || b.burst > 0.6) g.discover('gal-starburst');
    g.discover('gal-tails');
    g.sfx('galaxies.flyby', (a.x + b.x) / 2);
    // Tidal dwarfs: gas-rich clumps in the long tails a big disk throws out under a strong pull
    // collapse into small galaxies of their own (made of the host's gas and stars).
    const host = big;
    const strong = small.mass > 0.1 * host.mass;
    const live = this.gal.filter((x) => x.lostT < 0).length;
    if (this.tidal > 0 && strong && isDisk(host.morph) && host.stars > 2 && host.gas > 0.25 && live < MAX_GALAXIES && g.sim.chance(this.tidal * closeness)) {
      const ang = Math.atan2(host.y - small.y, host.x - small.x) + Math.PI + g.sim.range(-0.6, 0.6);
      const r = host.radius * 2.2;
      host.gas -= 0.03;
      host.stars -= 0.02;
      const td = this.addGalaxy({
        id: this.s.nextId++,
        morph: 'irregular',
        stars: 0.02,
        gas: 0.03,
        mass: 0.05,
        bh: 0,
        bulge: 0,
        flat: 0,
        x: host.x + Math.cos(ang) * r,
        y: host.y + Math.sin(ang) * r,
        vx: host.vx + Math.cos(ang) * 12,
        vy: host.vy + Math.sin(ang) * 12,
        radius: 12,
        spin: 1,
        tilt: 0,
        arms: 2,
        home: false,
        neighbor: false,
        label: '',
      });
      this.fx.spawn(Fx.Ring, td.x, td.y, 1.2, 8, 0.6, 0.7, 1.1, 40);
      g.discover('gal-tidal-dwarf');
    }
  }

  private ringWave(gx: Galaxy): void {
    this.disturb(gx, SETTLE_TIME);
    for (let i = 0; i < this.np; i++) {
      if (this.owner[i] !== gx.id) continue;
      const dx = this.px[i] - gx.x;
      const dy = this.py[i] - gx.y;
      const r = Math.hypot(dx, dy) || 1;
      const k = 26 * Math.exp(-r / gx.radius);
      this.pvx[i] += (dx / r) * k;
      this.pvy[i] += (dy / r) * k;
    }
  }

  private startMerge(big: Galaxy, small: Galaxy): void {
    small.mergingInto = big.id;
    small.mergeT = 0;
    this.disturb(big, MERGE_TIME + SETTLE_TIME);
    this.disturb(small, MERGE_TIME + SETTLE_TIME);
  }

  private finishMerge(small: Galaxy): void {
    const g = this.g;
    const big = this.byId(small.mergingInto);
    if (!big) return;
    const s = this.s;
    const r = mergeOutcome(big, small, g.sim.next());
    const wasHome = big.home || small.home;
    const greatMerger = (big.home && small.neighbor) || (big.neighbor && small.home);
    // The energy a merger sets loose grows with both masses (their reduced mass): two equals
    // pay the most, a dwarf next to nothing.
    const pair = (4 * big.stars * small.stars) / Math.max(1e-6, big.stars + small.stars);
    Object.assign(big, r.remnant);
    big.home = wasHome;
    // The big neighbor stays itself after swallowing others, until it meets home.
    big.neighbor = (big.neighbor || small.neighbor) && !wasHome;
    big.label = wasHome ? 'Home' : big.label;
    const bvx = big.vx;
    const bvy = big.vy;
    big.vx = (big.vx * big.mass + small.vx * small.mass) / (big.mass + small.mass);
    big.vy = (big.vy * big.mass + small.vy * small.mass) / (big.mass + small.mass);
    // The stars keep moving as they were; only the galaxy they are measured against changes.
    for (let i = 0; i < this.np; i++) {
      if (this.owner[i] === small.id) {
        this.owner[i] = big.id;
        this.pvx[i] += small.vx - big.vx;
        this.pvy[i] += small.vy - big.vy;
      } else if (this.owner[i] === big.id) {
        this.pvx[i] += bvx - big.vx;
        this.pvy[i] += bvy - big.vy;
      }
    }
    this.gal = this.gal.filter((x) => x !== small);
    s.mergers++;
    g.setFlag('galaxies.firstMerger');
    this.gain(MERGE_UNITS * pair * this.burstMult, big.x, big.y);
    big.burst = Math.min(3, big.burst + (r.major ? 2 : 0.6) * this.burstMult);
    this.fx.spawn(Fx.Flash, big.x, big.y, 1.4, big.radius * 1.4, 2.4, 2, 1.6, big.radius);
    g.renderer?.addFlash(r.major ? 0.25 : 0.08);
    g.renderer?.camera.addTrauma(r.major ? 0.25 : 0.06);
    g.sfx('galaxies.merge', big.x);
    if (r.major) {
      s.majors++;
      big.radius = Math.max(big.radius, radiusFor(big.stars) * 0.95);
      this.reshapeElliptical(big);
      if (small.bh > 0 && big.bh > small.bh) big.bhPair = BH_SINK / this.gw;
      else this.quasarFlare(big);
    } else {
      big.radius = radiusFor(big.stars);
      // Gas a small galaxy brings into a gas-poor giant sinks to the middle and feeds its black hole.
      if (small.gas > 0.02 && !isDisk(big.morph) && big.bh > 1e7) {
        const q = QUASAR_UNITS * (big.bh / 1e8) ** 0.7 * this.quasarMult * 0.6 * Math.min(1, small.gas / 0.4);
        if (q > big.quasar) {
          this.quasarFlare(big);
          big.quasar = q;
          g.discover('centaurus-a');
        }
      }
    }
    if (r.shells) {
      big.shells = 20;
      g.discover('gal-shells');
    }
    this.discoverType(big);
    g.discover('dynamical-friction');
    if (small.morph !== 'dwarf' && (small.label || small.neighbor || small.stars > 0.2)) g.discover('satellite');
    if (greatMerger) {
      g.setFlag('galaxies.greatMerger');
      g.discover('milkomeda');
      g.toast('The two great galaxies are one. Their spiral arms are gone.', 'milestone');
    }
  }

  /** A major merger's remnant settles into a smooth elliptical. */
  private reshapeElliptical(gx: Galaxy): void {
    const rng = this.g.fx;
    gx.reshape = RESHAPE_TIME;
    gx.tilt = rng.angle();
    for (let i = 0; i < this.np; i++) {
      if (this.owner[i] !== gx.id) continue;
      this.sx[i] = this.px[i];
      this.sy[i] = this.py[i];
      this.r0[i] = gx.radius * 0.36 * (-Math.log(1 - 0.98 * rng.next())) ** 1.1;
      this.th0[i] = rng.angle();
      if (this.pop[i] === Pop.Dust || this.pop[i] === Pop.Knot) this.pop[i] = Pop.Bulge;
      else if (this.pop[i] === Pop.Young && rng.chance(0.7)) this.pop[i] = Pop.Bulge;
    }
  }

  private quasarFlare(gx: Galaxy): void {
    const g = this.g;
    gx.quasar = QUASAR_UNITS * (gx.bh / 1e8) ** 0.7 * this.quasarMult;
    this.s.quasars++;
    g.sfx('galaxies.quasar', gx.x);
    g.renderer?.addFlash(0.15);
    g.discover('gal-quasar');
    g.discover('quenching');
  }

  // ───────────────────────────────────────── simulation

  update(dt: number): void {
    const g = this.g;
    const s = this.s;
    this.t += dt;
    this.idle += dt;
    if (this.intro > 0) this.intro = Math.max(0, this.intro - dt);
    const inFinale = this.finaleT >= 0;
    if (inFinale) this.updateFinale(dt);
    const step = Math.min(6, this.step);

    const de = DARK_ENERGY;

    // The group: its core (home and the big neighbor) and every galaxy inside the zero-gravity
    // radius, where the pull of the mass within still beats the accelerating expansion. Grown
    // outward from the core until it settles.
    let r0 = this.boundR;
    let cvx = 0;
    let cvy = 0;
    for (let pass = 0; pass < 4; pass++) {
      let m = 0;
      let mx = 0;
      let my = 0;
      let mvx = 0;
      let mvy = 0;
      for (const gx of this.gal) {
        if (gx.lostT >= 0) continue;
        if (!gx.home && !gx.neighbor && (pass === 0 || Math.hypot(gx.x - this.cx, gx.y - this.cy) >= r0)) continue;
        m += gx.mass;
        mx += gx.x * gx.mass;
        my += gx.y * gx.mass;
        mvx += gx.vx * gx.mass;
        mvy += gx.vy * gx.mass;
      }
      if (m <= 0) break;
      this.cx = mx / m;
      this.cy = my / m;
      cvx = mvx / m;
      cvy = mvy / m;
      this.groupM = m;
      r0 = Math.cbrt((G * m) / de) * this.halo;
    }
    this.boundR = r0;

    // We watch from the group's own frame: a gentle pull, the same on every galaxy and star (so
    // none can feel it against another), keeps the group's centre on screen however hard things
    // are thrown.
    this.frameAx = -0.01 * this.cx - 0.2 * cvx;
    this.frameAy = -0.01 * this.cy - 0.2 * cvy;

    // Small galaxies keep falling in along the cosmic web, ever more rarely, until it is cut off.
    const every = ARRIVAL_EVERY[step];
    if (!inFinale && every > 0 && this.intro <= 0) {
      this.arrivalT -= dt;
      if (this.arrivalT <= 0) {
        this.arrivalT = every * this.g.sim.range(0.75, 1.25);
        this.arrive();
      }
    }

    // Gravity, friction and dark energy on galaxy centres.
    const n = this.gal.length;
    for (let i = 0; i < n; i++) {
      const a = this.gal[i];
      if (a.lostT >= 0) continue;
      let ax = 0;
      let ay = 0;
      for (let j = 0; j < n; j++) {
        if (i === j) continue;
        const b = this.gal[j];
        if (b.lostT >= 0) continue;
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const soft = (a.radius + b.radius) * 0.6;
        const d2 = dx * dx + dy * dy + soft * soft;
        const f = (G * b.mass) / (d2 * Math.sqrt(d2));
        ax += dx * f;
        ay += dy * f;
        const pair = (a.home && b.neighbor) || (a.neighbor && b.home);
        if (pair && step < COLLISION_STEP) {
          // Until the collision step the two great galaxies only draw closer: they don't meet yet.
          const hold = (a.radius + b.radius) * 1.6;
          const dd = Math.sqrt(dx * dx + dy * dy) || 1;
          if (dd < hold) {
            const closing = ((a.vx - b.vx) * dx + (a.vy - b.vy) * dy) / dd;
            const push = 0.012 * (hold - dd) + (closing > 0 ? 1.5 * closing : 0);
            ax -= (dx / dd) * push;
            ay -= (dy / dd) * push;
          }
        }
        // Dynamical friction. A galaxy moving through another's dark halo raises a wake that drags
        // on it, stronger the heavier it is (Chandrasekhar): big partners spiral together within a
        // few passes, dwarfs can orbit for ages (unless Cannibalism lets giants swallow them).
        // Where the galaxies overlap deeply it grips hard.
        const d = Math.sqrt(dx * dx + dy * dy);
        const sum = a.radius + b.radius;
        const dwarf = b.mass > 20 * a.mass;
        const reach = sum * (0.6 + 0.2 * this.cannibal * (dwarf ? 1 : 0));
        const halo = sum * 4;
        if (d < halo && a.mergingInto === 0 && !(pair && step < COLLISION_STEP)) {
          const wake = Math.min(1, Math.max(a.mass / 100, dwarf ? 0.04 * this.cannibal : 0));
          let grip = HALO_FRICTION * STEP_AGE[step] * wake * Math.min(1, (sum / Math.max(1, d)) ** 2) * (1 - d / halo);
          // The two great galaxies share one sprawling halo, so they always drag on each other.
          if (pair) grip = Math.max(grip, CORE_FRICTION);
          // The Dynamical Friction upgrade helps the catch when galaxies plunge through each other.
          if (d < reach) grip += 0.35 * (1 - d / reach) * this.friction;
          const k = grip * Math.min(1, b.mass / a.mass);
          ax -= (a.vx - b.vx) * k;
          ay -= (a.vy - b.vy) * k;
        }
      }
      // Outside the bound radius the accelerating expansion wins. The two great galaxies anchor
      // the group inside one shared halo: thrown far out, they slow and fall back.
      const ox = a.x - this.cx;
      const oy = a.y - this.cy;
      const od = Math.hypot(ox, oy) || 1;
      const core = a.home || a.neighbor;
      a.bound = core || od < this.boundR;
      if (!inFinale) {
        if (!a.bound) {
          ax += ox * de;
          ay += oy * de;
        } else if (core && od > this.boundR * 0.8) {
          const out = (a.vx * ox + a.vy * oy) / od;
          const pull = 0.004 * (od - this.boundR * 0.8) + (out > 0 ? 0.25 * out : 0);
          ax -= (ox / od) * pull;
          ay -= (oy / od) * pull;
        }
      }
      if (a.mergingInto) {
        const into = this.byId(a.mergingInto);
        if (into) {
          ax += (into.x - a.x) * 1.6 - (a.vx - into.vx) * 2.2;
          ay += (into.y - a.y) * 1.6 - (a.vy - into.vy) * 2.2;
        }
      }
      if (a.id === this.grabId) {
        a.vx *= Math.exp(-6 * dt);
        a.vy *= Math.exp(-6 * dt);
      } else {
        a.vx += (ax + this.frameAx) * dt;
        a.vy += (ay + this.frameAy) * dt;
      }
    }
    for (const a of this.gal) {
      a.x += a.vx * dt;
      a.y += a.vy * dt;
      a.angle += ((Math.sqrt(this.vc2(a)) * 0.55) / a.radius) * dt * (a.morph === 'elliptical' || a.morph === 'dwarf' ? 0.15 : 1);
      for (const [id, cd] of a.met) {
        if (cd - dt <= 0) a.met.delete(id);
        else a.met.set(id, cd - dt);
      }
    }

    // Encounters: flybys and the start of mergers.
    if (!inFinale) this.encounters();

    // Mergers in progress, black-hole pairs, quasars, stars and gas.
    // Stars torn loose shine like any old stars, more so once intragroup light is understood.
    let light = s.debris * this.ihl * this.oldMult;
    const inflow = INFLOW * INFLOW_LEFT[step] * this.inflowMult;
    for (const a of [...this.gal]) {
      if (a.mergingInto) {
        a.mergeT += dt;
        if (a.mergeT >= MERGE_TIME) this.finishMerge(a);
        continue;
      }
      if (a.bhPair > 0) {
        a.bhPair -= dt;
        if (a.bhPair <= 1.8 && a.bhPair + dt > 1.8) g.sfx('galaxies.chirp', a.x);
        if (a.bhPair <= 0) {
          a.bhPair = 0;
          this.gain(GW_UNITS * (a.bh / 1e8) * this.gw, a.x, a.y);
          for (let k = 0; k < 4; k++) this.fx.spawn(Fx.Ring, a.x, a.y, 1.8 + k * 0.4, 10, 0.45, 0.5, 0.75, 240 + k * 70);
          g.renderer?.shock(a.x, a.y, 0.9, 0.9, 1.4);
          g.sfx('galaxies.bhmerge', a.x);
          g.discover('gal-bh-merger');
          this.quasarFlare(a);
        }
      }
      if (a.lostT >= 0) {
        a.lostT += dt;
        continue;
      }
      // Gas: fresh inflow onto disks while the cosmic web still delivers it; stars form from it.
      if (isDisk(a.morph) || a.morph === 'irregular') a.gas += inflow * (a.mass / 100) ** 0.6 * dt;
      const bar = a.morph === 'barred' ? 1.3 : 1;
      const sfr = a.gas * SFE * this.sf * bar * (1 + 9 * a.burst);
      const formed = Math.min(a.gas, sfr * dt * 0.02);
      a.gas -= formed;
      a.stars += formed;
      a.burst = Math.max(0, a.burst - dt * 0.05 / Math.max(0.5, this.burstMult));
      // A quasar burns, and its feedback blows the remaining gas away: red and dead.
      if (a.quasar > 0) {
        a.quasar *= Math.exp(-dt / QUASAR_LIFE);
        // Feedback blows the gas out; a little of it feeds the black hole, which grows.
        const blown = a.gas * (1 - Math.exp(-dt * 0.12));
        a.gas -= blown;
        a.bh += blown * 6e7;
        if (a.quasar < 1) a.quasar = 0;
      }
      // A disk that runs out of gas fades into a lenticular.
      if (isDisk(a.morph) && a.gas < 0.004 * a.stars && step >= 4) {
        a.morph = 'lenticular';
        this.discoverType(a);
      }
      if (a.disturbed > 0 && a.mergingInto === 0) {
        a.disturbed -= dt;
        if (a.disturbed <= 0) {
          a.disturbed = 0;
          this.settle(a);
        }
      }
      if (a.reshape > 0) a.reshape = Math.max(0, a.reshape - dt);
      if (a.ring > 0) a.ring = Math.max(0, a.ring - dt);
      if (a.shells > 0) a.shells = Math.max(0, a.shells - dt);
      const agn = AGN_UNITS * (a.bh / 1e8) ** 0.8 * this.quasarMult;
      light += oldLight(a) * this.oldMult + sfr * YOUNG_LIGHT + a.quasar + agn;
      // Receding galaxies redden; past the edge they are beyond the horizon.
      const od = Math.hypot(a.x - this.cx, a.y - this.cy);
      a.redshift = a.bound ? Math.max(0, a.redshift - dt * 0.5) : Math.min(1, (od - this.boundR) / (this.halfW * 0.9));
      if (od > Math.max(this.halfW, this.halfH) * 1.45 && !a.home && !a.neighbor) this.loseGalaxy(a);
    }
    this.gal = this.gal.filter((a) => a.lostT < 2.5);
    if (light > 0) g.gain(light * E_UNIT * this.weight * dt);

    this.updateParticles(dt);
    this.fx.update(dt);
    if (this.grabId) {
      this.pathClock -= dt;
      if (this.pathClock <= 0) {
        this.pathClock = 0.08;
        this.predictPath();
      }
    }
    this.save();
    this.redshift += (Math.min(1, step / 6) - this.redshift) * (1 - Math.exp(-dt * 0.4));
    const bp = this.bgParams;
    bp.redshift = inFinale ? Math.min(1, this.redshift + this.finaleT / 6) : this.redshift;
    bp.inflow = INFLOW_LEFT[step] * Math.min(1.5, this.inflowMult);
    bp.cx = this.cx;
    bp.cy = this.cy;
    bp.bound = this.boundR;
    bp.haze = Math.min(1.2, 0.15 + s.debris * 2);
    bp.pulse *= Math.exp(-dt * 2);
  }

  private encounters(): void {
    const n = this.gal.length;
    for (let i = 0; i < n; i++) {
      const a = this.gal[i];
      if (a.mergingInto || a.lostT >= 0) continue;
      for (let j = i + 1; j < n; j++) {
        const b = this.gal[j];
        if (b.mergingInto || b.lostT >= 0) continue;
        const d = Math.hypot(a.x - b.x, a.y - b.y);
        const sum = a.radius + b.radius;
        const vrel = Math.hypot(a.vx - b.vx, a.vy - b.vy);
        const early = ((a.home && b.neighbor) || (a.neighbor && b.home)) && this.step < COLLISION_STEP;
        if (d < sum * 0.42 && vrel < 34 * this.friction ** 0.5 && !early) {
          const big = a.mass >= b.mass ? a : b;
          this.startMerge(big, big === a ? b : a);
          continue;
        }
        if (d < sum * 1.5 && !a.met.has(b.id)) {
          a.met.set(b.id, 9);
          b.met.set(a.id, 9);
          this.flyby(a, b, Math.min(1, 1.5 - d / sum));
        }
      }
    }
  }

  private loseGalaxy(a: Galaxy): void {
    if (a.lostT >= 0) return;
    a.lostT = 0;
    this.s.lost++;
    this.g.sfx('galaxies.lost', a.x);
    this.g.discover('event-horizon');
    if (this.s.lost === 1) this.g.toast('A galaxy has slipped beyond the horizon. Its light will only grow redder and fainter.', 'quiet');
  }

  private updateParticles(dt: number): void {
    const gal = new Map<number, Galaxy>();
    for (const gx of this.gal) gal.set(gx.id, gx);
    // The halos stars move in: each pulls like a flat rotation curve out to a few radii. A galaxy beyond
    // the horizon pulls only its own stars.
    const pots = this.gal.map((gx) => ({ gx, x: gx.x, y: gx.y, v2: this.vc2(gx), c2: (gx.radius * 0.15) ** 2, reach2: (gx.radius * 6) ** 2, live: gx.lostT < 0 }));
    // A galaxy's stars fall with it under every outside pull, so what moves them against it is only how
    // that pull differs across the galaxy: the tide. Here, the outside pull at each galaxy's centre.
    const ext = new Map<number, [number, number]>();
    for (const gx of this.gal) {
      let ax = 0;
      let ay = 0;
      for (const p of pots) {
        if (p.gx === gx || !p.live) continue;
        const dx = p.x - gx.x;
        const dy = p.y - gx.y;
        const f = p.v2 / (dx * dx + dy * dy + p.c2);
        ax += dx * f;
        ay += dy * f;
      }
      ext.set(gx.id, [ax, ay]);
    }
    let w = 0;
    for (let i = 0; i < this.np; i++) {
      const id = this.owner[i];
      const gx = id >= 0 ? gal.get(id) : undefined;
      if (id >= 0 && !gx) {
        // The galaxy was lost beyond the horizon: its stars go with it.
        continue;
      }
      if (id < 0) {
        this.life[i] -= dt;
        if (this.life[i] <= 0) continue;
      }
      if (gx && gx.reshape > 0) {
        const k = 1 - gx.reshape / RESHAPE_TIME;
        const e = k * k * (3 - 2 * k);
        const [tx, ty] = this.patternPos(gx, this.r0[i], this.th0[i]);
        this.px[i] = this.sx[i] + (tx - this.sx[i]) * e;
        this.py[i] = this.sy[i] + (ty - this.sy[i]) * e;
        this.free[i] = 0;
      } else if (gx && this.free[i]) {
        // In its galaxy's frame: its own halo's pull and the others' tide (without the reach cut, so
        // the tide fades smoothly with distance instead of switching on).
        const x = this.px[i];
        const y = this.py[i];
        const [ex, ey] = ext.get(gx.id) ?? [0, 0];
        let ax = -ex;
        let ay = -ey;
        for (const p of pots) {
          if (p.gx !== gx && !p.live) continue;
          const dx = p.x - x;
          const dy = p.y - y;
          const f = p.v2 / (dx * dx + dy * dy + p.c2);
          ax += dx * f;
          ay += dy * f;
        }
        this.pvx[i] += ax * dt;
        this.pvy[i] += ay * dt;
        this.px[i] = x + (gx.vx + this.pvx[i]) * dt;
        this.py[i] = y + (gx.vy + this.pvy[i]) * dt;
      } else if (!gx) {
        // Debris between the galaxies: every halo within reach, and the pull of our viewing frame.
        let ax = this.frameAx;
        let ay = this.frameAy;
        for (const p of pots) {
          if (!p.live) continue;
          const dx = p.x - this.px[i];
          const dy = p.y - this.py[i];
          const d2 = dx * dx + dy * dy;
          if (d2 > p.reach2) continue;
          const f = p.v2 / (d2 + p.c2);
          ax += dx * f;
          ay += dy * f;
        }
        this.pvx[i] += ax * dt;
        this.pvy[i] += ay * dt;
        this.px[i] += this.pvx[i] * dt;
        this.py[i] += this.pvy[i] * dt;
      } else {
        const [x, y] = this.patternPos(gx, this.r0[i], this.th0[i]);
        this.px[i] = x;
        this.py[i] = y;
      }
      // Compact: keep live stars contiguous.
      if (w !== i) this.copyParticle(i, w);
      w++;
    }
    this.np = w;
  }

  private copyParticle(from: number, to: number): void {
    this.px[to] = this.px[from];
    this.py[to] = this.py[from];
    this.pvx[to] = this.pvx[from];
    this.pvy[to] = this.pvy[from];
    this.sx[to] = this.sx[from];
    this.sy[to] = this.sy[from];
    this.r0[to] = this.r0[from];
    this.th0[to] = this.th0[from];
    this.owner[to] = this.owner[from];
    this.free[to] = this.free[from];
    this.pop[to] = this.pop[from];
    this.life[to] = this.life[from];
  }

  private save(): void {
    // A galaxy in the middle of a merger is kept with it, so the merger finishes after a reload.
    this.s.galaxies = this.gal
      .filter((a) => a.lostT < 0)
      .map((a) => ({
        id: a.id,
        morph: a.morph,
        stars: a.stars,
        gas: a.gas,
        mass: a.mass,
        bh: a.bh,
        bulge: a.bulge,
        flat: a.flat,
        x: a.x,
        y: a.y,
        vx: a.vx,
        vy: a.vy,
        radius: a.radius,
        spin: a.spin,
        tilt: a.tilt,
        arms: a.arms,
        home: a.home,
        neighbor: a.neighbor,
        label: a.label,
        ...(a.mergingInto ? { mergingInto: a.mergingInto, mergeT: a.mergeT } : {}),
      }));
  }

  // ───────────────────────────────────────── steps

  onStep(index: number): void {
    const g = this.g;
    this.syncStepFlags();
    this.bgParams.pulse = Math.min(1, this.bgParams.pulse + 0.3);
    g.renderer?.camera.breathe(0.05, 1.5);
    // Billions of years pass: unbound galaxies are carried further out.
    for (const a of this.gal) {
      if (a.bound || a.home) continue;
      a.x = this.cx + (a.x - this.cx) * 1.12;
      a.y = this.cy + (a.y - this.cy) * 1.12;
    }
    if (index >= 1 && index < 6) g.sfx('galaxies.milestone');
    if (index === 1) g.discover('satellite');
    if (index === 2) g.discover('andromeda');
    if (index === 5) g.discover('event-horizon');
    if (index === 4) g.toast('The cosmic web no longer feeds the group. Nothing new will fall in, and what gas is left is all there will be.', 'quiet');
  }

  static oneGalaxyBlocker(g: Game): string | null {
    return g.flag('galaxies.greatMerger') ? null : 'Needs your galaxy and its big neighbor merged';
  }

  static aloneBlocker(g: Game): string | null {
    const s = g.state.run.eras.galaxies as GalaxiesState | undefined;
    const era = g.era as unknown as { boundOthers?: () => number } | null;
    const left = era?.boundOthers?.() ?? (s ? Math.max(0, s.galaxies.length - 1) : 0);
    return left > 0 ? `Needs ${left} more galax${left === 1 ? 'y' : 'ies'} merged into yours` : null;
  }

  /** Galaxies still bound to the group but not yet part of home. */
  boundOthers(): number {
    return this.gal.filter((a) => a.bound && !a.home && a.lostT < 0).length;
  }

  // ───────────────────────────────────────── finale: alone

  finale(): Promise<void> {
    const g = this.g;
    const run = g.state.run;
    const home = this.gal.find((a) => a.home);
    run.legacy.finalStars = home?.stars ?? 0;
    run.legacy.finalBH = home?.bh ?? 0;
    run.legacy.mergers = this.s.mergers;
    run.legacy.lostGalaxies = this.s.lost;
    g.tally('blackHoles', 'galaxies', (home?.bh ?? 0) / 1e3);
    this.grabId = 0;
    this.finaleT = 0;
    g.sfx('galaxies.complete');
    return new Promise((resolve) => {
      this.finaleDone = resolve;
    });
  }

  private updateFinale(dt: number): void {
    const g = this.g;
    this.finaleT += dt;
    const t = this.finaleT;
    const home = this.gal.find((a) => a.home);
    // Everything not part of home slips away.
    for (const a of this.gal) {
      if (a.home || a.lostT >= 0) continue;
      const ox = a.x - this.cx;
      const oy = a.y - this.cy;
      a.vx += ox * 0.05 * dt;
      a.vy += oy * 0.05 * dt;
    }
    const cam = g.renderer?.camera;
    if (cam && home) {
      const k = Math.min(1, t / 9);
      const e = k * k * (3 - 2 * k);
      cam.x = home.x * e;
      cam.y = home.y * e;
      cam.zoom = 1 + (g.state.settings.reduceMotion ? 0.3 : 0.6) * e;
    }
    if (t >= 6 && !this.tallied) {
      this.tallied = true;
      g.toast('Alone. Astronomers born here would see no other galaxies, and could never learn that the universe is expanding.', 'milestone');
    }
    if (t >= 13 && this.finaleDone) {
      const done = this.finaleDone;
      this.finaleDone = null;
      done();
    }
  }

  // ───────────────────────────────────────── rendering

  render(r: Renderer): void {
    const t = this.t;
    // The bound region: a faint dashed circle.
    if (this.finaleT < 0) {
      const R = this.boundR;
      const segs = 72;
      for (let k = 0; k < segs; k += 2) {
        const a0 = (k / segs) * Math.PI * 2 + t * 0.01;
        const a1 = ((k + 1) / segs) * Math.PI * 2 + t * 0.01;
        r.lines.push(this.cx + Math.cos(a0) * R, this.cy + Math.sin(a0) * R, this.cx + Math.cos(a1) * R, this.cy + Math.sin(a1) * R, 1.4, 1.4, LineStyle.Crisp, 0.35, 0.38, 0.5, 0.22);
      }
    }
    const fade = new Map<number, number>();
    for (const a of this.gal) {
      const lost = a.lostT >= 0 ? Math.max(0, 1 - a.lostT / 2.5) : 1;
      const f = lost * (1 - 0.75 * a.redshift);
      fade.set(a.id, f);
      this.renderBody(r, a, f);
    }
    // Stars.
    for (let i = 0; i < this.np; i++) {
      const id = this.owner[i];
      const f = id < 0 ? Math.min(1, this.life[i] / 10) * 0.6 : (fade.get(id) ?? 0);
      if (f <= 0.01) continue;
      const gx = id >= 0 ? this.byId(id) : undefined;
      const red = gx ? gx.redshift : 0;
      const pop = this.pop[i];
      const x = this.px[i];
      const y = this.py[i];
      if (pop === Pop.Dust) {
        r.solid.push(x, y, 7, 0.02, 0.012, 0.008, 0.32 * f, Shape.Puff);
        continue;
      }
      let c: RGB;
      let size: number;
      switch (pop) {
        case Pop.Bulge:
          c = [1.3, 1.05, 0.7];
          size = 1.9;
          break;
        case Pop.Young:
          c = [0.8, 1.0, 1.7];
          size = 1.9;
          break;
        case Pop.Knot:
          c = [1.8, 0.5, 0.8];
          size = 2.4;
          break;
        default:
          c = [0.95, 0.95, 1.15];
          size = 1.6;
      }
      if (red > 0) c = [c[0] * (1 - 0.3 * red) + 0.6 * red, c[1] * (1 - 0.7 * red), c[2] * (1 - 0.85 * red)];
      const burst = gx && pop !== Pop.Bulge ? 1 + 0.5 * Math.min(2, gx.burst) : 1;
      r.glow.push(x, y, size, c[0] * f * burst, c[1] * f * burst, c[2] * f * burst, 1, Shape.Glow);
    }
    this.renderFling(r);
    this.fx.render(r);
    if (this.intro > 0) {
      const a = Math.pow(this.intro / 1.6, 2);
      r.over.push(0, 0, Math.max(this.halfW, this.halfH) * 2.6, 0.9 * a, 0.85 * a, 1.0 * a, 1, Shape.Puff);
    }
  }

  private renderBody(r: Renderer, a: Galaxy, f: number): void {
    const R = a.radius;
    const ell = a.morph === 'elliptical' || a.morph === 'dwarf';
    const lum = Math.min(1.4, 0.35 + 0.25 * Math.log10(1 + a.stars * 10));
    const k = f * lum;
    if (ell) {
      r.under.push(a.x, a.y, R * 1.5, 0.22 * k, 0.17 * k, 0.11 * k, 1, Shape.Puff);
      r.under.push(a.x, a.y, R * 0.6, 0.35 * k, 0.27 * k, 0.17 * k, 1, Shape.Puff);
    } else {
      r.under.push(a.x, a.y, R * 1.6, 0.15 * k, 0.16 * k, 0.23 * k, 1, Shape.Puff);
      r.under.push(a.x, a.y, R * 0.45 * (0.7 + a.bulge), 0.4 * k, 0.32 * k, 0.2 * k, 1, Shape.Puff);
    }
    // The nucleus, and a quasar's glare and jets.
    r.glow.push(a.x, a.y, 3 + R * 0.04, 2.2 * k, 1.9 * k, 1.5 * k, 1, Shape.Glow);
    if (a.quasar > 0) {
      const q = Math.min(1.5, a.quasar / 400);
      r.glow.push(a.x, a.y, 30 + 30 * q, 2.6 * q, 2.8 * q, 3.6 * q, 1, Shape.Star, 1);
      const ang = a.tilt + Math.PI / 2;
      for (const s of [1, -1]) {
        const ex = a.x + Math.cos(ang) * R * 2.2 * s;
        const ey = a.y + Math.sin(ang) * R * 2.2 * s;
        r.lines.push(a.x, a.y, ex, ey, 4 * q + 1, 0.5, LineStyle.Glow, 0.7 * q, 0.85 * q, 1.6 * q, 0.9, 0.3, 0.4, 0.9, 0);
        // Where the jet rams the thin gas around the galaxy it balloons into a radio lobe.
        r.under.push(ex, ey, R * (0.3 + 0.25 * q), 0.07 * q, 0.09 * q, 0.22 * q, 1, Shape.Puff);
      }
    }
    if (a.burst > 0.2) {
      const b = Math.min(1.5, a.burst) * f;
      r.under.push(a.x, a.y, R * 0.95, 0.11 * b, 0.05 * b, 0.12 * b, 1, Shape.Puff);
    }
    if (a.ring > 0) r.over.push(a.x, a.y, R * (1.6 - a.ring / 8), 1.1 * f * (a.ring / 8), 0.5 * f * (a.ring / 8), 0.8 * f * (a.ring / 8), 1, Shape.Shock, 0.02);
    if (a.shells > 0) {
      // Shells: the stars of a swallowed dwarf pile up where their orbits turn around, so each shell is
      // a faint arc with a sharp outer edge. They sit on alternating sides, each further out, and drift
      // outward as they fade.
      const life = a.shells / 20;
      const grow = 1 + 0.25 * (1 - life);
      for (let n = 1; n <= 4; n++) {
        const rad = R * (0.45 + 0.28 * n) * grow;
        const mid = a.tilt + (n % 2 ? 0 : Math.PI);
        const span = 0.9 - 0.08 * n;
        const dim = life * f * (1.1 - 0.15 * n);
        const segs = 14;
        for (let j = 0; j < segs; j++) {
          const a0 = mid - span + (2 * span * j) / segs;
          const a1 = a0 + (2 * span) / segs;
          // The edge: brightest at the middle of the arc, gone at its ends.
          const e = Math.sin(((j + 0.5) / segs) * Math.PI) * dim;
          r.lines.push(a.x + Math.cos(a0) * rad, a.y + Math.sin(a0) * rad, a.x + Math.cos(a1) * rad, a.y + Math.sin(a1) * rad, 1.6, 1.6, LineStyle.Glow, 0.22 * e, 0.18 * e, 0.14 * e, 0.6);
        }
        for (let j = 0; j < 36; j++) {
          // Its stars, crowding toward the edge.
          const u = hash(a.id * 8 + n, j);
          const v = hash(a.id * 8 + n, j + 40);
          const th = mid + span * (2 * u - 1);
          const rr = rad * (1 - 0.16 * v * v);
          const e = Math.sin(u * Math.PI) * dim;
          r.glow.push(a.x + Math.cos(th) * rr, a.y + Math.sin(th) * rr, 1.5, 0.75 * e, 0.62 * e, 0.45 * e, 1, Shape.Glow);
        }
      }
    }
    if (a.bhPair > 0) {
      const sep = 4 + a.bhPair * 2.5;
      const ph = this.t * (2 + 10 / (a.bhPair + 0.3));
      for (const s of [1, -1]) r.glow.push(a.x + Math.cos(ph) * sep * s, a.y + Math.sin(ph) * sep * s, 3, 1.6, 1.4, 1.2, 1, Shape.Glow);
    }
    if (a.id === this.hoverId || a.id === this.grabId) {
      r.over.push(a.x, a.y, R * 1.3, 0.45, 0.5, 0.65, 0.7, Shape.Shock, 0.015);
    }
  }

  private renderFling(r: Renderer): void {
    const a = this.grabId ? this.byId(this.grabId) : undefined;
    if (!a) return;
    const dx = a.x - this.pX;
    const dy = a.y - this.pY;
    const pull = Math.hypot(dx, dy);
    r.lines.push(a.x, a.y, this.pX, this.pY, 2.4, 1, LineStyle.Glow, 0.7, 0.75, 0.9, 0.5, 0.5, 0.5, 0.6, 0.25);
    r.over.push(a.x, a.y, a.radius * (1.1 + Math.min(1, pull / 400)), 0.8, 0.85, 1.1, 0.6, Shape.Shock, 0.015);
    // The predicted path, dashed.
    const p = this.path;
    for (let k = 0; k + 3 < p.length; k += 4) {
      const fade = 1 - k / p.length;
      r.lines.push(p[k], p[k + 1], p[k + 2], p[k + 3], 1.6, 1.6, LineStyle.Crisp, 0.8 * fade, 0.85 * fade, 1.1 * fade, 0.7);
    }
  }

  // ───────────────────────────────────────── input

  private flingVelocity(a: Galaxy): [number, number] {
    const dx = a.x - this.pX;
    const dy = a.y - this.pY;
    const d = Math.hypot(dx, dy);
    const v = Math.min(55, d * 0.11);
    return d > 1 ? [(dx / d) * v, (dy / d) * v] : [0, 0];
  }

  /** Where the grabbed galaxy would go if released now (gravity from the others, frozen). */
  private predictPath(): void {
    const a = this.grabId ? this.byId(this.grabId) : undefined;
    this.path = [];
    if (!a) return;
    const [fvx, fvy] = this.flingVelocity(a);
    let x = a.x;
    let y = a.y;
    let vx = a.vx + fvx;
    let vy = a.vy + fvy;
    const h = 0.16;
    for (let k = 0; k < 90; k++) {
      let ax = 0;
      let ay = 0;
      for (const b of this.gal) {
        if (b === a || b.lostT >= 0) continue;
        const dx = b.x - x;
        const dy = b.y - y;
        const soft = (a.radius + b.radius) * 0.6;
        const d2 = dx * dx + dy * dy + soft * soft;
        const f = (G * b.mass) / (d2 * Math.sqrt(d2));
        ax += dx * f;
        ay += dy * f;
      }
      vx += ax * h;
      vy += ay * h;
      const nx = x + vx * h;
      const ny = y + vy * h;
      if (k % 2 === 0) this.path.push(x, y, nx, ny);
      x = nx;
      y = ny;
    }
  }

  pointer(e: PointerInfo): void {
    if (!e.primary) return;
    this.pX = e.x;
    this.pY = e.y;
    if (e.type === 'move') {
      if (!this.grabId) {
        let best = 0;
        let bd = Infinity;
        for (const a of this.gal) {
          if (a.lostT >= 0) continue;
          const d = Math.hypot(a.x - e.x, a.y - e.y);
          if (d < Math.max(18, a.radius * 0.8) && d < bd) {
            bd = d;
            best = a.id;
          }
        }
        this.hoverId = best;
      }
      return;
    }
    if (e.type === 'up' || e.type === 'cancel') {
      const a = this.grabId ? this.byId(this.grabId) : undefined;
      if (a && e.type === 'up') {
        const [vx, vy] = this.flingVelocity(a);
        a.vx += vx;
        a.vy += vy;
        if (Math.hypot(vx, vy) > 5) {
          this.s.everFlung = true;
          this.g.sfx('galaxies.fling', a.x, Math.min(1.5, Math.hypot(vx, vy) / 80));
        }
      }
      this.grabId = 0;
      this.path = [];
      return;
    }
    this.idle = 0;
    if (this.finaleT >= 0) return;
    let best: Galaxy | undefined;
    let bd = Infinity;
    for (const a of this.gal) {
      if (a.lostT >= 0 || a.mergingInto) continue;
      const d = Math.hypot(a.x - e.x, a.y - e.y);
      if (d < Math.max(20, a.radius * 0.85) && d < bd) {
        bd = d;
        best = a;
      }
    }
    if (best) {
      this.grabId = best.id;
      this.pathClock = 0;
      this.g.sfx('galaxies.grab', best.x);
    }
  }

  // ───────────────────────────────────────── HUD

  labels(): WorldLabel[] {
    const out: WorldLabel[] = [];
    for (const a of this.gal) {
      if (a.lostT >= 0) continue;
      if (a.home) out.push({ id: `home-${a.id}`, x: a.x, y: a.y + a.radius * 1.25 + 14, text: 'Home', tone: 'quiet', opacity: this.finaleT >= 0 ? 0.4 : 0.8 });
    }
    const h = this.hoverId ? this.byId(this.hoverId) : undefined;
    if (h && this.finaleT < 0) {
      const what = `${hubbleType(h)} · ${toText(count(h.stars * 1e10))} stars${h.bound ? '' : ' · receding'}`;
      out.push({ id: 'hover', x: h.x, y: h.y - h.radius * 1.3 - 12, text: what, tone: 'value', opacity: 0.9 });
    }
    return out;
  }

  stocks(): StockView[] {
    const s = this.s;
    const home = this.gal.find((a) => a.home);
    const bound = this.gal.filter((a) => a.bound && a.lostT < 0).length;
    const out: StockView[] = [
      { id: 'bound', label: 'Galaxies in reach', value: bound, format: 'count', hint: 'Galaxies held by the group\'s gravity. Anything outside the dashed circle is being carried away.' },
      { id: 'stars', label: 'Stars at home', value: (home?.stars ?? 0) * 1e10, format: 'count', hint: 'Stars in your galaxy, the Sun among them.' },
      { id: 'bh', label: 'Central black hole', value: home?.bh ?? 0, format: 'count', hint: 'Mass of the black hole at the heart of your galaxy, in Suns.' },
    ];
    if (s.lost > 0) out.push({ id: 'lost', label: 'Beyond the horizon', value: s.lost, format: 'count', hint: 'Galaxies carried out of reach for good by the accelerating expansion.' });
    return out;
  }

  dotScale(): { value: number; unit: string } | null {
    return null;
  }

  offline(seconds: number): OfflineReport {
    void seconds;
    return { lines: [] };
  }

  accent(): RGB {
    const r = this.redshift;
    return [0.85 + 0.15 * r, 0.82 - 0.12 * r, 0.7 - 0.2 * r];
  }

  hint(): string | null {
    if (this.finaleT >= 0) return null;
    const s = this.s;
    if (!s.everFlung && this.idle > 4) return 'Drag a galaxy back and let go to fling it.';
    if (s.everFlung && s.mergers === 0 && this.idle > 12) return 'Galaxies that meet slowly merge. Fast ones only pass, raising tidal tails.';
    const receding = this.gal.some((a) => !a.bound && a.lostT < 0 && a.redshift > 0.4);
    if (receding && s.lost === 0 && this.idle > 8) return 'Fling the reddening galaxies back inside the circle before they are gone.';
    return null;
  }
}
