<!--
  One phenomenon: real name, one line of physics, the exact effect (now → next), cost.
-->
<script lang="ts">
  import { energy } from '../../core/format';
  import { roman, type PhenomenonDef } from '../../core/phenomena';
  import Num from '../common/Num.svelte';
  import { game, track, ui } from '../store.svelte';
  import { buyAmount, buyByClick, energyUnit, planBuy } from '../view';

  let { def, hotkey }: { def: PhenomenonDef; hotkey: number | null } = $props();
  const g = game();
  const born = performance.now();
  const id = $props.id();

  const v = $derived.by(() => {
    track();
    const lvl = g.level(def.id);
    const maxed = g.isMaxed(def.id);
    const p = planBuy(g, def, buyAmount(def, ui.ctrl, ui.shift));
    const unit = energyUnit(g);
    const text = def.effectText?.(lvl) ?? '';
    const preview = def.shows && !text ? g.preview(def.id) : null;
    return {
      lvl,
      maxed,
      n: p.n,
      cost: energy(p.cost, unit, g.state.settings.notation),
      can: !maxed && !g.inFinale && p.cost <= g.energy,
      text,
      preview,
      fresh: performance.now() - born < 1800,
    };
  });

  const buy = (e: MouseEvent) => buyByClick(g, def, e);
</script>

{#if v.maxed}
  <div class="done-row" title={def.physics}>
    <span class="name">{def.name}</span>
    <span class="lvl">{def.max === 1 ? '✓' : `${roman(v.lvl)} · max`}</span>
  </div>
{:else}
<button
  class="card"
  class:can={v.can}
  class:maxed={v.maxed}
  class:fresh={v.fresh}
  onclick={buy}
  disabled={v.maxed}
  aria-label={`${def.name}${v.lvl ? `, level ${v.lvl}` : ''}`}
  aria-describedby="{id}-physics {id}-foot"
  aria-keyshortcuts={hotkey !== null ? String(hotkey) : undefined}
>
  <div class="head">
    <span class="name">{def.name}</span>
    <span class="lvl">
      {#if def.max !== 1 && v.lvl > 0}<span class="rn">{roman(v.lvl)}</span>{/if}
      {#if def.max === 1 && v.lvl > 0}<span class="rn">✓</span>{/if}
      {#if hotkey !== null}<kbd>{hotkey}</kbd>{/if}
    </span>
  </div>
  <p class="physics" id="{id}-physics">{def.physics}</p>
  <div class="foot" id="{id}-foot">
    <span class="effect">
      {#if v.text}
        <span class="txt">{v.text}</span>
      {:else if v.preview && def.shows}
        <span class="now"><Num parts={def.shows.format(v.preview.now)} /></span>
        {#if !v.maxed}<span class="to" aria-hidden="true">→</span><span class="sr-only">becomes</span><span class="next"><Num parts={def.shows.format(v.preview.next)} /></span>{/if}
        <span class="unit">{def.shows.label}</span>
      {/if}
    </span>
    {#if !v.maxed}
      <span class="cost">
        <span class="sr-only">{v.can ? 'Costs' : 'Needs'}</span>
        {#if v.n > 1}<span class="times">×{v.n}</span>{/if}
        <Num parts={v.cost} />
      </span>
    {/if}
  </div>
</button>
{/if}

