/**
 * A galaxy's disk seen face-on, as a medium the rays march through (at reduced resolution, averaged
 * over frames like the plasma). The disk is a slab around the game plane, layered the way real disks
 * are (the "sandwich"): unresolved starlight in a thick layer, dust in a thinner, patchy one inside
 * it. Dust dims blue light more than red (interstellar reddening), so a lane in front of starlight
 * turns it brown and red rather than black, while the starlight in front of the lane stays as it is:
 * depth reads from the light itself.
 *
 * Molecular clouds are dense, dusty knots in the slab. Around each hot star the gas is ionized out to
 * its Strömgren radius: inside, it glows hydrogen-alpha red (the teal of doubly ionized oxygen nearest
 * the hottest stars) and its dust is cleared; at the boundary, where the ionization front meets dense
 * gas, a thin bright rim; beyond it the neutral gas stands dark. Rims and shells (supernova remnants,
 * planetary nebulae) are thin spherical shells integrated exactly along each ray, so they stay crisp
 * at the march's resolution and their limbs outshine their faces, as real ones do. Point lights
 * scatter off the dust (reflection nebulae) and light fronts sweep through it (light echoes).
 *
 * The same world holds the whole galaxy: an exponential disk with a bulge and two logarithmic spiral
 * arms around a centre far off the patch. Up close its gradient is the patch's light growing toward
 * the centre; drawn back, the patch's own detail fades and the galaxy is what is left. The virtual
 * camera backs away as the view widens, so the slab keeps its proportions at every scale.
 */
import { FULLSCREEN_VS, Program, Target, drawFullscreen, type GLCaps } from './gl';
import { HEADER } from './glsl';
import { NOISE_SIZE, noiseVolume } from './noise3d';
import type { LayerFrame, RenderLayer } from './renderer';
import type { VolumeFront, VolumeLight } from './volume';

export const DISK_CLOUDS = 12;
export const DISK_HOT = 8;
export const DISK_SHELLS = 6;

export interface DiskConfig {
  /** Resolution relative to the scene, and steps per ray (at High). */
  scale: number;
  steps: number;
  /** Half-thickness of the slab, and the camera's distance from the plane at a 500-unit half-height. */
  half: number;
  focal: number;
  /** Unresolved starlight at the patch (0 … ~1.5), and its age: 0 young and blue-white, 1 old and golden. */
  glow: number;
  age: number;
  /** Dust richness (0 … 1): the lanes' depth. */
  dust: number;
  /** World units per noise tile of the patch's lanes. */
  laneScale: number;
  /** The galaxy: its centre (world), disk scale length, outer radius, and the arms' rotation (radians). */
  centre: [number, number];
  scaleLength: number;
  radius: number;
  armPhase: number;
  /** The patch's own arm, a band sweeping through: its x at y = 0 and strength (0: none). */
  armX: number;
  armK: number;
  /** A brief lift of the whole disk (an epoch step). */
  pulse: number;
}

export function defaultDisk(): DiskConfig {
  return {
    scale: 0.5,
    steps: 26,
    half: 220,
    focal: 1600,
    glow: 0.4,
    age: 0,
    dust: 1,
    laneScale: 1500,
    centre: [-9000, 6500],
    scaleLength: 3600,
    radius: 21000,
    armPhase: 0,
    armX: -1e5,
    armK: 0,
    pulse: 0,
  };
}

/** A molecular cloud: where it is, its radius, how brightly nearby hot stars light it (0 … 2), its gas (0 … ~1.5), a seed. */
export interface DiskCloud {
  x: number;
  y: number;
  radius: number;
  heat: number;
  gas: number;
  seed: number;
}

/** A hot star's ionized bubble: its radius (the Strömgren radius) and strength (0 … 1). */
export interface DiskHot {
  x: number;
  y: number;
  radius: number;
  strength: number;
}

/**
 * A thin glowing shell: radius and half-thickness (world units), the rim's colour seen face-on and the
 * fill inside it (times intensity), how broken into filaments it is (0 … 1), and a seed.
 */
export interface DiskShell {
  x: number;
  y: number;
  radius: number;
  width: number;
  rim: [number, number, number];
  inner: [number, number, number];
  broken: number;
  seed: number;
}

const MARCH_FS = HEADER + /* glsl */ `
precision highp sampler3D;
in vec2 vUv;
out vec4 outColor;
uniform sampler3D uNoise;
uniform vec4 uView;
uniform float uFocal;
uniform float uHalf;
uniform float uTime;
uniform int uSteps;
uniform float uFrame;
uniform float uGlow;
uniform float uAge;
uniform float uDust;
uniform float uLane;
uniform vec4 uGal;        // centre x, y, scale length, outer radius
uniform float uGalNorm;   // the inverse of the disk's light at the patch
uniform float uArmPhase;
uniform vec2 uArm;        // the patch's arm: x at y = 0, strength
uniform float uPatch;     // 1: the patch's own detail; 0: only the galaxy (seen from far)
uniform float uPulse;
uniform vec4 uCloud[${DISK_CLOUDS}];   // x, y, radius, heat
uniform vec4 uCloudB[${DISK_CLOUDS}];  // gas, seed, -, -
uniform int uCloudCount;
uniform vec4 uHot[${DISK_HOT}];        // x, y, radius, strength
uniform int uHotCount;
uniform vec4 uLight[8];
uniform vec3 uLightCol[8];
uniform int uLightCount;
uniform vec4 uFront[4];
uniform vec3 uFrontCol[4];
uniform int uFrontCount;
uniform vec4 uShell[${DISK_SHELLS}];   // x, y, radius, half-thickness
uniform vec4 uShellA[${DISK_SHELLS}];  // rim colour, broken
uniform vec4 uShellB[${DISK_SHELLS}];  // fill colour, seed
uniform int uShellCount;

float N(vec3 p) { return texture(uNoise, p).r; }

const vec3 H_ALPHA = vec3(1.0, 0.16, 0.27);
const vec3 O_III = vec3(0.16, 0.95, 0.78);
// Extinction per channel relative to green (R_V about 3.1): blue is dimmed most, red least.
const vec3 REDDEN = vec3(0.72, 1.0, 1.36);
const vec3 DUST_GLOW = vec3(0.55, 0.34, 0.2);
const vec3 OLD = vec3(1.0, 0.76, 0.5);
const vec3 YOUNG = vec3(0.55, 0.68, 1.0);

/** Interleaved gradient noise (Jimenez 2014): a spatially even jitter that converges fast over frames. */
float ign(vec2 p) { return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715)))); }

/**
 * Length of a ray's path through a spherical shell from r - w to r + w, at distance b from its centre
 * (the ray taken as straight down through the plane): twice the thickness where it crosses squarely,
 * several times more where it grazes the limb.
 */
float chord(float b, float r, float w) {
  float o = r + w;
  float i = max(0.0, r - w);
  return 2.0 * (sqrt(max(0.0, o * o - b * b)) - sqrt(max(0.0, i * i - b * b)));
}

/**
 * The galaxy at a point of the plane: the colour of its unresolved starlight (times brightness, 1 at
 * the patch), the dust its arms put there, and its knots of star formation. An exponential disk and a
 * golden bulge; seen from far, two logarithmic arms of young blue light with dust along their inner
 * edges and pink knots along them.
 */
void galaxy(vec2 w, out vec3 star, out float lane, out float knots) {
  vec2 d = w - uGal.xy;
  float r = length(d);
  float R = uGal.z;
  float disk = exp(-r / R) * (1.0 - smoothstep(uGal.w * 0.7, uGal.w * 1.05, r)) * uGalNorm;
  float bulge = exp(-pow(r / (0.2 * R), 2.0)) * uGalNorm;
  float far = 1.0 - uPatch;
  // Between the arms only the old population: dimmer and golden.
  star = mix(YOUNG, OLD, 0.3 + 0.7 * uAge) * disk * (1.0 - 0.45 * far) + OLD * bulge * 1.6;
  lane = 0.0;
  knots = 0.0;
  if (far > 0.0) {
    float th = atan(d.y, d.x);
    float big = N(vec3(w / (1.6 * R), 0.37));
    // Sampled rotated and offset, so the noise's tiling never lines up into a lattice.
    vec2 wr = mat2(0.8, -0.6, 0.6, 0.8) * w;
    float fine = N(vec3(wr / (0.9 * R) + 0.31, 0.83));
    // The arms wander a little and break into clumps, with feathery spurs between them.
    float ph = th - log(max(r, 1.0) / R) / 0.23 + uArmPhase + (big - 0.5) * 0.9;
    float c = 0.5 + 0.5 * cos(2.0 * ph);
    float ring = smoothstep(0.25 * R, 0.9 * R, r);
    float arm = pow(c, 6.0) * ring * (0.35 + 1.5 * fine * fine);
    float spur = pow(0.5 + 0.5 * cos(4.0 * ph + 2.4 + fine * 4.0), 10.0) * ring * 0.35 * fine;
    float inner = pow(0.5 + 0.5 * cos(2.0 * ph + 0.62), 14.0) * smoothstep(0.15 * R, 0.7 * R, r);
    star += YOUNG * (arm + spur) * disk * 2.6 * far;
    lane = inner * smoothstep(0.3, 0.65, fine) * 1.8 * min(disk, 2.5) * far;
    knots = pow(max(0.0, fine - 0.58) * 3.5, 2.0) * smoothstep(0.45, 0.65, big) * pow(c, 3.0) * ring * min(disk, 3.0) * far;
  }
}
void main() {
  vec2 ndc = vUv * 2.0 - 1.0;
  vec3 onPlane = vec3(uView.x + ndc.x * uView.z, uView.y - ndc.y * uView.w, 0.0);
  vec3 cam = vec3(uView.xy, -uFocal);
  vec3 dir = normalize(onPlane - cam);
  float t0 = (-uHalf - cam.z) / dir.z;
  float t1 = (uHalf - cam.z) / dir.z;
  float stepLen = (t1 - t0) / float(uSteps);
  // How far the ray wanders sideways crossing the slab (for culling what it can reach).
  float drift = length(dir.xy / dir.z) * uHalf;

  // The galaxy's light here, once per pixel: it changes over thousands of units, the slab over hundreds.
  vec3 gStar;
  float gLane;
  float gKnots;
  galaxy(onPlane.xy, gStar, gLane, gKnots);
  vec3 starAt = gStar * uGlow * (1.0 + uPulse);
  float h2 = uHalf * uHalf;

  // The patch's arm: a broad band of young light, dust along its leading edge.
  float ad = (onPlane.x - uArm.x - onPlane.y * 0.35) / 260.0;
  float armBand = exp(-ad * ad) * uArm.y * uPatch;
  float armDust = exp(-(ad + 0.9) * (ad + 0.9) * 3.0) * uArm.y * uPatch;
  starAt += YOUNG * armBand * (0.25 + 0.5 * uGlow);
  // Lanes on a larger scale, carrying the dust's structure while the view draws back from the patch.
  float mn = N(vec3(onPlane.xy / (uLane * 5.0), 0.61));
  float midLane = pow(max(0.0, 1.0 - abs(mn - 0.5) * 5.0), 4.0) * (0.1 + 1.6 * uPatch * (1.0 - uPatch)) * (0.4 + 0.6 * uDust);

  // What this ray can reach: the clouds and bubbles near its path.
  int cl[${DISK_CLOUDS}];
  int nc = 0;
  for (int i = 0; i < ${DISK_CLOUDS}; i++) {
    if (i >= uCloudCount) break;
    vec4 c = uCloud[i];
    if (length(onPlane.xy - c.xy) < c.z * 1.25 + drift) cl[nc++] = i;
  }
  int hs[${DISK_HOT}];
  int nh = 0;
  for (int i = 0; i < ${DISK_HOT}; i++) {
    if (i >= uHotCount) break;
    vec4 h = uHot[i];
    if (length(onPlane.xy - h.xy) < h.z * 1.3 + drift) hs[nh++] = i;
  }
  bool cloudsNear = nc > 0 && uPatch > 0.01;

  float t = t0 + stepLen * fract(ign(gl_FragCoord.xy) + uFrame * 0.6180339887);
  vec3 L = vec3(0.0);
  vec3 T = vec3(1.0);
  float tb = uTime * 0.004;
  for (int i = 0; i < 64; i++) {
    if (i >= uSteps) break;
    vec3 p = cam + dir * t;
    float z2 = p.z * p.z;
    // Starlight: a thick layer. Dust: a thinner one, gathered into feathered, branching lanes.
    float vStar = exp(-z2 / (0.42 * h2));
    float vDust = exp(-z2 / (0.12 * h2));
    vec3 q = p / uLane;
    vec3 wq = vec3(N(q * 0.5 + vec3(0.13, 0.71, tb)), N(q * 0.5 + vec3(0.59, tb, 0.91)), 0.5) - 0.5;
    float dn = N(q + wq * 0.45 + vec3(0.0, 0.0, tb * 0.5));
    // Broad lanes, and a network of thin filaments along the ridges of the same field (feathered spurs).
    float ridge = 1.0 - abs(dn - 0.5) * 6.0;
    float lanes = smoothstep(0.56, 0.68, dn) * 0.9 + pow(max(ridge, 0.0), 4.0) * 1.1;
    float dust = (lanes * (0.35 + 0.65 * uDust) * uPatch + armDust * 0.9 + gLane + midLane) * vDust;
    // Unresolved stars clump a little (star clouds).
    float clump = mix(1.0, 0.55 + 0.9 * smoothstep(0.3, 0.75, N(q * 0.7 + vec3(0.41, 0.23, 0.0))), uPatch);
    vec3 emit = starAt * vStar * clump * 0.0011;
    emit += vec3(1.0, 0.3, 0.42) * gKnots * uGlow * vDust * 0.03;

    // Molecular clouds: dense dusty knots, lit by the hot stars inside and near them.
    float gas = 0.0;
    float heat = 0.0;
    if (cloudsNear) {
      float s = N(q * 2.6 + vec3(0.31, 0.17, tb * 2.0) + wq * 0.6) * 0.55 + N(q * 7.0 + vec3(0.77, 0.21, tb * 3.0)) * 0.18;
      for (int k = 0; k < ${DISK_CLOUDS}; k++) {
        if (k >= nc) break;
        vec4 c = uCloud[cl[k]];
        vec4 cb = uCloudB[cl[k]];
        vec3 d = vec3(p.xy - c.xy, p.z * 1.8) / c.z;
        float r2 = dot(d, d);
        if (r2 > 1.6) continue;
        // Each cloud takes its own part of the shared structure, so no two share a silhouette.
        float own = N(vec3(d.xy * 0.45 + cb.y * 0.173, cb.y * 0.071 + tb));
        float body = exp(-r2 * 2.2 * (1.0 - 0.6 * (own - 0.5)));
        // Only the denser part of the structure is gas: clumps, filaments and globules, not a fog.
        gas += body * smoothstep(0.55, 0.7, s + own * 0.45) * (1.0 + 0.8 * cb.x) * uPatch;
        heat += c.w * body;
      }
    }

    // Ionized bubbles: inside, the gas glows and its dust is gone.
    float ion = 0.0;
    float oiii = 0.0;
    float rim = 0.0;
    for (int k = 0; k < ${DISK_HOT}; k++) {
      if (k >= nh) break;
      vec4 h = uHot[hs[k]];
      float d = length(vec3(p.xy - h.xy, p.z * 1.4));
      float w = 0.07 * h.z + 2.0;
      ion = max(ion, h.w * smoothstep(h.z + w, h.z - w, d));
      oiii += h.w * smoothstep(0.7 * h.z, 0.1 * h.z, d);
      rim += h.w * exp(-pow((d - h.z) / (1.5 * w), 2.0));
    }
    ion = min(ion, 1.0);
    // Radiation and winds have swept most of the gas out of a bubble into its walls.
    float n2 = gas * gas * (1.0 - 0.85 * ion);
    // The ionization front: where the bubble's edge meets dense gas it burns brightest (the rims of
    // pillars and globules), so it follows the gas, broken and bright where the gas is thick.
    emit += H_ALPHA * (n2 * ion * 0.35 + gas * (0.012 + heat * 0.1) + gas * gas * gas * rim * 1.8) * 0.012;
    emit += vec3(1.0, 0.5, 0.58) * gas * gas * gas * gas * rim * 0.003;
    emit += O_III * n2 * min(oiii, 1.2) * 0.008;
    // Cold gas still scatters a little of the disk's light: dark clouds read as gas, not holes.
    float dustAll = dust + gas * (1.0 - 0.9 * ion) * 2.2;
    float ambient = dot(starAt, vec3(0.33)) * 0.00016 + 0.00002;
    emit += DUST_GLOW * dustAll * ambient;

    // Light from stars and flashes scattered by the dust (reflection nebulae), and fronts sweeping through it.
    vec3 lit = vec3(0.0);
    for (int k = 0; k < 8; k++) {
      if (k >= uLightCount) break;
      vec3 dl = p - uLight[k].xyz;
      float r = uLight[k].w;
      float f = 1.0 + dot(dl, dl) / (r * r);
      lit += uLightCol[k] / (f * sqrt(f));
    }
    for (int k = 0; k < 4; k++) {
      if (k >= uFrontCount) break;
      float x = (length(p - vec3(uFront[k].xy, 0.0)) - uFront[k].z) / uFront[k].w;
      lit += uFrontCol[k] * exp(-x * x);
    }
    emit += lit * (dustAll * 0.02 + gas * 0.012 + 0.0008 * vStar) * vec3(0.8, 0.9, 1.0);

    L += T * emit * stepLen;
    T *= exp(-dustAll * 0.016 * stepLen * REDDEN);
    t += stepLen;
  }

  // Shells: thin, so integrated exactly along the ray (crisp at any resolution), and seen through the
  // dust in front of the plane.
  vec3 V = sqrt(T);
  for (int k = 0; k < ${DISK_SHELLS}; k++) {
    if (k >= uShellCount) break;
    vec4 s = uShell[k];
    vec2 d = onPlane.xy - s.xy;
    float b = length(d);
    if (b > s.z + 2.0 * s.w) continue;
    vec4 a = uShellA[k];
    vec4 fillCol = uShellB[k];
    // Mostly the limb: a thin shell is faint where it is seen face-on, bright where the ray grazes it.
    float limb = max(0.0, chord(b, s.z, s.w) / (4.0 * s.w) - 0.7);
    // Broken into strands: ridges of 3D noise over the shell's surface, where this ray crosses it.
    vec3 sp = vec3(d, sqrt(max(0.0, s.z * s.z - b * b))) / max(s.z, 1.0);
    float n = N(sp * 0.42 + fillCol.w * 0.137);
    float strands = pow(max(0.0, 1.0 - abs(n - 0.5) * 3.5), 3.0);
    float brk = mix(1.0, strands * 2.4, a.w);
    float fill = sqrt(max(0.0, 1.0 - b * b / (s.z * s.z)));
    L += V * (a.rgb * limb * brk + fillCol.rgb * fill * (1.0 - 0.6 * a.w * (1.0 - strands)));
  }
  outColor = vec4(L, 1.0);
}`;

/**
 * Folds this frame's march into the running average, reprojected so a pan or zoom moves the history
 * with the disk (the plane is where its light comes from); the history is kept inside the range of this
 * frame's neighbourhood, and where last frame saw nothing this frame stands alone.
 */
const ACCUM_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uCur;
uniform sampler2D uPrev;
uniform vec4 uView;
uniform vec4 uPrevView;
uniform float uBlend;
uniform vec2 uTexel;
out vec4 outColor;
void main() {
  vec4 cur = texture(uCur, vUv);
  vec2 ndc = vUv * 2.0 - 1.0;
  vec2 w = uView.xy + vec2(ndc.x, -ndc.y) * uView.zw;
  vec2 pn = (w - uPrevView.xy) / uPrevView.zw;
  vec2 puv = vec2(pn.x, -pn.y) * 0.5 + 0.5;
  if (uBlend >= 1.0 || any(lessThan(puv, vec2(0.0))) || any(greaterThan(puv, vec2(1.0)))) {
    outColor = cur;
    return;
  }
  vec4 lo = cur;
  vec4 hi = cur;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec4 n = texture(uCur, vUv + vec2(float(x), float(y)) * uTexel);
      lo = min(lo, n);
      hi = max(hi, n);
    }
  }
  vec4 prev = clamp(texture(uPrev, puv), lo, hi);
  outColor = mix(prev, cur, uBlend);
}`;

const COMPOSITE_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uSrc;
out vec4 outColor;
void main() { outColor = vec4(texture(uSrc, vUv).rgb, 1.0); }`;

export class Disk implements RenderLayer {
  readonly stage = 'media' as const;
  config: DiskConfig;
  /** Refilled by the caller every frame. */
  clouds: DiskCloud[] = [];
  hot: DiskHot[] = [];
  shells: DiskShell[] = [];
  lights: VolumeLight[] = [];
  fronts: VolumeFront[] = [];
  private gl: WebGL2RenderingContext | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private march: Program | null = null;
  private accum: Program | null = null;
  private comp: Program | null = null;
  private noise: WebGLTexture | null = null;
  private target: Target | null = null;
  /** The march averaged over recent frames (its per-pixel jitter becomes smooth): last frame's and this one's. */
  private history: [Target, Target] | null = null;
  private fresh = true;
  /** The view the history was rendered in. */
  private prevView = new Float32Array(4);
  private frameNo = 0;
  private time = 0;
  private cloudA = new Float32Array(DISK_CLOUDS * 4);
  private cloudB = new Float32Array(DISK_CLOUDS * 4);
  private hotA = new Float32Array(DISK_HOT * 4);
  private shellA = new Float32Array(DISK_SHELLS * 4);
  private shellB = new Float32Array(DISK_SHELLS * 4);
  private shellC = new Float32Array(DISK_SHELLS * 4);
  private lightA = new Float32Array(32);
  private lightC = new Float32Array(24);
  private frontA = new Float32Array(16);
  private frontC = new Float32Array(12);

  constructor(config: Partial<DiskConfig> = {}) {
    this.config = { ...defaultDisk(), ...config };
  }

  /** How much of the patch's own detail shows at a view this many world units tall (1 up close, 0 seen from far). */
  static patchShown(halfH: number): number {
    return 1 - smooth(900, 3200, halfH);
  }

  init(gl: WebGL2RenderingContext, caps: GLCaps, emptyVao: WebGLVertexArrayObject): void {
    this.gl = gl;
    this.vao = emptyVao;
    this.march = this.accum = this.comp = null;
    if (!caps.hdr) return;
    try {
      this.march = new Program(gl, FULLSCREEN_VS, MARCH_FS, 'disk:march');
      this.accum = new Program(gl, FULLSCREEN_VS, ACCUM_FS, 'disk:accumulate');
      this.comp = new Program(gl, FULLSCREEN_VS, COMPOSITE_FS, 'disk:composite');
    } catch (e) {
      console.error(e);
      this.march = this.accum = this.comp = null;
      return;
    }
    const tex = gl.createTexture();
    if (!tex) return;
    gl.bindTexture(gl.TEXTURE_3D, tex);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    gl.texImage3D(gl.TEXTURE_3D, 0, gl.R8, NOISE_SIZE, NOISE_SIZE, NOISE_SIZE, 0, gl.RED, gl.UNSIGNED_BYTE, noiseVolume());
    gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    for (const w of [gl.TEXTURE_WRAP_S, gl.TEXTURE_WRAP_T, gl.TEXTURE_WRAP_R]) gl.texParameteri(gl.TEXTURE_3D, w, gl.REPEAT);
    gl.bindTexture(gl.TEXTURE_3D, null);
    this.noise = tex;
    this.target = new Target(gl, 1, 1, true);
    this.history = [new Target(gl, 1, 1, true), new Target(gl, 1, 1, true)];
    this.fresh = true;
  }

  draw(frame: LayerFrame): void {
    const gl = this.gl;
    const m = this.march;
    const acc = this.accum;
    if (!gl || !m || !acc || !this.comp || !this.noise || !this.target || !this.history) return;
    const c = this.config;
    const q = frame.quality;
    this.time += frame.dt;
    const t = this.target;
    const [prev, next] = this.history;
    // Lower quality: fewer steps at a lower resolution, more frames averaged to make up for them.
    const scale = c.scale * q.volume;
    const steps = Math.max(6, Math.min(64, Math.round(c.steps * q.steps)));
    const blend = Math.min(1, 0.14 * (steps / Math.max(6, c.steps)));
    const w0 = t.width;
    const h0 = t.height;
    t.resize(frame.scene.width * scale, frame.scene.height * scale);
    prev.resize(t.width, t.height);
    next.resize(t.width, t.height);
    // A new size (a resized window, another quality level) leaves nothing to average with.
    if (t.width !== w0 || t.height !== h0) this.fresh = true;

    const halfH = frame.view[3];
    const r0 = Math.hypot(c.centre[0], c.centre[1]);

    const nc = Math.min(DISK_CLOUDS, this.clouds.length);
    for (let i = 0; i < nc; i++) {
      const k = this.clouds[i];
      this.cloudA.set([k.x, k.y, Math.max(1, k.radius), k.heat], i * 4);
      this.cloudB.set([k.gas, k.seed, 0, 0], i * 4);
    }
    const nh = Math.min(DISK_HOT, this.hot.length);
    for (let i = 0; i < nh; i++) {
      const h = this.hot[i];
      this.hotA.set([h.x, h.y, Math.max(1, h.radius), h.strength], i * 4);
    }
    const ns = Math.min(DISK_SHELLS, this.shells.length);
    for (let i = 0; i < ns; i++) {
      const s = this.shells[i];
      this.shellA.set([s.x, s.y, Math.max(1, s.radius), Math.max(0.5, s.width)], i * 4);
      this.shellB.set([s.rim[0], s.rim[1], s.rim[2], s.broken], i * 4);
      this.shellC.set([s.inner[0], s.inner[1], s.inner[2], s.seed], i * 4);
    }
    const nl = Math.min(8, this.lights.length);
    for (let i = 0; i < nl; i++) {
      const L = this.lights[i];
      this.lightA.set([L.x, L.y, L.z, Math.max(1, L.radius)], i * 4);
      this.lightC.set(L.color, i * 3);
    }
    const nf = Math.min(4, this.fronts.length);
    for (let i = 0; i < nf; i++) {
      const f = this.fronts[i];
      this.frontA.set([f.x, f.y, f.radius, Math.max(1, f.width)], i * 4);
      this.frontC.set(f.color, i * 3);
    }

    gl.disable(gl.BLEND);
    t.bind();
    // The camera backs away as the view widens (a dolly, not a zoom), so the slab keeps its proportions.
    m.use().f1('uFocal', c.focal * Math.max(1, halfH / 500)).f1('uHalf', c.half).f1('uTime', this.time);
    m.f1('uFrame', (this.frameNo = (this.frameNo + 1) % 1024));
    m.f1('uGlow', c.glow).f1('uAge', c.age).f1('uDust', c.dust).f1('uLane', c.laneScale).f1('uPulse', c.pulse);
    m.f4('uGal', c.centre[0], c.centre[1], c.scaleLength, c.radius).f1('uGalNorm', Math.exp(r0 / c.scaleLength)).f1('uArmPhase', c.armPhase);
    m.f2('uArm', c.armX, c.armK).f1('uPatch', Disk.patchShown(halfH));
    gl.uniform1i(m.loc('uSteps'), steps);
    gl.uniform4fv(m.loc('uView'), frame.view);
    gl.uniform4fv(m.loc('uCloud'), this.cloudA);
    gl.uniform4fv(m.loc('uCloudB'), this.cloudB);
    gl.uniform1i(m.loc('uCloudCount'), nc);
    gl.uniform4fv(m.loc('uHot'), this.hotA);
    gl.uniform1i(m.loc('uHotCount'), nh);
    gl.uniform4fv(m.loc('uShell'), this.shellA);
    gl.uniform4fv(m.loc('uShellA'), this.shellB);
    gl.uniform4fv(m.loc('uShellB'), this.shellC);
    gl.uniform1i(m.loc('uShellCount'), ns);
    gl.uniform4fv(m.loc('uLight'), this.lightA);
    gl.uniform3fv(m.loc('uLightCol'), this.lightC);
    gl.uniform1i(m.loc('uLightCount'), nl);
    gl.uniform4fv(m.loc('uFront'), this.frontA);
    gl.uniform3fv(m.loc('uFrontCol'), this.frontC);
    gl.uniform1i(m.loc('uFrontCount'), nf);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_3D, this.noise);
    m.i1('uNoise', 0);
    drawFullscreen(gl, this.vao!);
    gl.bindTexture(gl.TEXTURE_3D, null);

    // Fold this frame's march into the running average (the disk changes slowly; the jitter doesn't).
    next.bind();
    acc.use().i1('uCur', 0).i1('uPrev', 1).f1('uBlend', this.fresh ? 1 : blend).f2('uTexel', 1 / t.width, 1 / t.height);
    gl.uniform4fv(acc.loc('uView'), frame.view);
    gl.uniform4fv(acc.loc('uPrevView'), this.fresh ? frame.view : this.prevView);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, prev.tex);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, t.tex);
    drawFullscreen(gl, this.vao!);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.activeTexture(gl.TEXTURE0);
    this.history = [next, prev];
    this.prevView.set(frame.view);
    this.fresh = false;

    // The disk is the deepest thing there is: it replaces whatever lies behind it.
    frame.scene.bind();
    gl.disable(gl.BLEND);
    this.comp.use().i1('uSrc', 0);
    gl.bindTexture(gl.TEXTURE_2D, next.tex);
    drawFullscreen(gl, this.vao!);
  }

  dispose(): void {
    const gl = this.gl;
    if (!gl) return;
    this.march?.dispose();
    this.accum?.dispose();
    this.comp?.dispose();
    if (this.noise) gl.deleteTexture(this.noise);
    this.target?.dispose();
    for (const h of this.history ?? []) h.dispose();
    this.march = this.accum = this.comp = null;
    this.noise = null;
    this.target = this.history = null;
  }
}

function smooth(a: number, b: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}
