/**
 * The orchestrator. Owns the state and wires the systems together: stats, phenomena, epoch steps,
 * eras, energy, codex, saving, offline credit and input. Rendering and audio are optional so the
 * same game runs headless in tests and in the balance simulator.
 */
import { Bus } from './bus';
import type { CodexEntry } from './codex';
import type { EraDef, EraModule, EpochStep, OfflineReport, PointerInfo, StepGoal } from './era';
import { EV_PER_JOULE } from './format';
import { Loop } from './loop';
import { RateMeter } from './meter';
import type { PhenomenonDef, PhenomenonHost } from './phenomena';
import { Rng, freshSeed } from './rng';
import { SaveManager, type StorageAdapter } from './save';
import { heartGrants, knowledgeDef } from './knowledge';
import { blackHoleFactor, constantsModifiers, diesYoung, FATE_NAME, FATE_TEXT, fateOf, INFLATION_AFTER, INFLATION_MILESTONES, inflationLog, insightFor, mutate, type Barren, type Fate } from './multiverse';
import { ERA_ORDER, defaultState, newRun, type Constants, type EraId, type GameState } from './state';
import { Stats, type Modifier } from './stats';
import type { Renderer } from '../render/renderer';

export const OFFLINE_CAP_SECONDS = 12 * 3600;
const AUTOSAVE_SECONDS = 15;
const UI_TICK_SECONDS = 0.05;

export interface GameEvents extends Record<string, unknown> {
  /** Energy gained at a world position (floating numbers, audio). */
  gain: { amount: number; x: number; y: number };
  buy: { id: string; level: number };
  step: { era: EraId; index: number; step: EpochStep };
  eraStart: { era: EraId; fresh: boolean };
  eraEnd: { era: EraId };
  finaleStart: { era: EraId };
  discover: { entry: CodexEntry };
  toast: { text: string; tone: 'quiet' | 'milestone' };
  joules: Record<string, never>;
  /** A named sound cue from the simulation; the audio engine decides what it sounds like. */
  sfx: { id: string; x?: number; intensity?: number; pitch?: number };
  offline: { seconds: number; energy: number; report: OfflineReport };
  ui: Record<string, never>;
  saved: Record<string, never>;
  settings: Record<string, never>;
  /** A universe ended (its fate, or it died young): the multiverse screen opens. */
  universeEnd: Record<string, never>;
  /** A new universe was inflated from a seed. */
  universeStart: Record<string, never>;
  /** The ending's movements: words over the scene, a point of light, the title, then back to play. */
  ending: { phase: 'words' | 'light' | 'title' | 'done' };
}

/** Codex entries that belong to the multiverse rather than an era. */
const META_CODEX: CodexEntry[] = [
  {
    // Guth, Linde, Vilenkin (1980s): eternal inflation; still untested.
    id: 'eternal-inflation',
    title: 'Eternal inflation',
    chart: 'notes',
    era: 'night',
    text: 'In many versions of inflation, space keeps inflating forever in most places, and pockets where it stops become universes, without end. It is a hypothesis; nobody yet knows how to test it.',
  },
];

export interface GameOptions {
  storage: StorageAdapter;
  eras: Partial<Record<EraId, EraDef>>;
  /** Extra codex entries not owned by an era. */
  codex?: readonly CodexEntry[];
  now?: () => number;
  seed?: number;
}

export class Game implements PhenomenonHost {
  state: GameState;
  readonly stats = new Stats();
  readonly bus = new Bus<GameEvents>();
  readonly sim: Rng;
  readonly fx: Rng;
  readonly save: SaveManager;
  readonly loop: Loop;
  readonly energyMeter = new RateMeter(20);
  renderer: Renderer | null = null;
  era: EraModule | null = null;
  /** True while an era finale plays (purchases and steps are locked). */
  inFinale = false;
  /** Smoothed real frame time in milliseconds (for the quality governor and perf readout). */
  frameMs = 16.7;

  private readonly eras: Partial<Record<EraId, EraDef>>;
  private readonly phenomena = new Map<string, PhenomenonDef>();
  private readonly codex = new Map<string, CodexEntry>();
  private readonly now: () => number;
  private autosaveClock = 0;
  private uiClock = 0;
  private hiddenAt: number | null = null;
  /** A save was adopted (imported) and the page is about to reload into it: never write over it. */
  private adopted = false;

  constructor(opts: GameOptions) {
    this.now = opts.now ?? (() => Date.now());
    this.eras = opts.eras;
    this.save = new SaveManager(opts.storage);
    const t = this.now();
    this.state = this.save.load(t) ?? defaultState(opts.seed ?? freshSeed(), t);

    for (const id of ERA_ORDER) {
      const def = this.eras[id];
      if (!def) continue;
      this.stats.define(def.stats);
      for (const p of def.phenomena) this.phenomena.set(p.id, p);
      for (const c of def.codex) this.codex.set(c.id, c);
    }
    for (const c of opts.codex ?? []) this.codex.set(c.id, c);
    for (const c of META_CODEX) this.codex.set(c.id, c);

    this.stats.addProvider(() => this.phenomenaModifiers());
    this.stats.addProvider(() => this.codexModifiers());
    this.stats.addProvider(() => constantsModifiers(this.state.run.constants));

    this.sim = new Rng(this.state.run.seed);
    if (this.state.run.rng.some((v) => v !== 0)) this.sim.restore(this.state.run.rng);
    this.fx = new Rng(freshSeed());
    this.energyMeter.reset(this.state.run.meters.energy ?? 0);

    this.loop = new Loop(
      (dt) => this.update(dt),
      (alpha, frameDt) => this.render(alpha, frameDt),
    );
  }

  // ───────────────────────────────────────── lifecycle

  /** Enter the saved era and credit any time away. Call once after construction (and attach). */
  boot(): void {
    const run = this.state.run;
    // A save from a build with more eras (a dev build) opened in one with fewer: rest at the end of
    // the latest era this build has instead of failing to start.
    if (!this.eras[run.era]) {
      const at = ERA_ORDER.indexOf(run.era);
      const known = ERA_ORDER.filter((id, i) => this.eras[id] && i < at);
      const back = known[known.length - 1] ?? ERA_ORDER.find((id) => this.eras[id])!;
      run.era = back;
      run.step = this.eras[back]!.steps.length - 1;
      this.setFlag(`${back}.complete`);
    }
    // A save from a build whose step list was longer: rest on this build's last step, not past it.
    run.step = Math.max(0, Math.min(Math.floor(run.step) || 0, this.steps(run.era).length - 1));
    this.enterEra(run.era, run.step === 0 && run.playTime === 0);
    const last = this.steps().length - 1;
    if (last > 0 && run.step === last && !this.state.meta.atMultiverse) {
      // Closed or reloaded while a finale was playing: play it again so the universe moves on.
      if (!this.flag(`${run.era}.complete`)) void this.runFinale();
      // Finished back when this was the last era there was: the next one exists now.
      else if (this.nextEraId()) this.advanceEra();
    }
    const away = (this.now() - this.state.saved) / 1000;
    if (away > 60 && run.playTime > 0) this.applyOffline(away);
  }

  attachRenderer(r: Renderer): void {
    this.renderer = r;
    r.reduceFlashes = this.state.settings.reduceFlashes;
  }

  start(): void {
    this.loop.start();
  }

  /** Visibility changes: save on hide, credit the gap on return. */
  setHidden(hidden: boolean): void {
    if (hidden) {
      this.hiddenAt = this.now();
      this.persist();
    } else if (this.hiddenAt !== null) {
      const gap = (this.now() - this.hiddenAt) / 1000;
      this.hiddenAt = null;
      if (gap > 2) this.applyOffline(gap, gap > 60);
      this.loop.resync();
    }
  }

  // ───────────────────────────────────────── frame

  update(dt: number): void {
    const run = this.state.run;
    this.inflate$(dt);
    if (this.state.meta.atMultiverse) {
      // Between universes nothing happens in the last one.
      this.state.lifetime.playTime += dt;
      return;
    }
    run.playTime += dt;
    this.state.lifetime.playTime += dt;
    this.era?.update(dt);
    this.energyMeter.tick(dt);
    this.autosaveClock += dt;
    if (this.autosaveClock >= AUTOSAVE_SECONDS) {
      this.autosaveClock = 0;
      this.persist();
    }
  }

  render(_alpha: number, frameDt: number): void {
    this.frameMs += (frameDt * 1000 - this.frameMs) * 0.05;
    const r = this.renderer;
    // Between universes the last one is a still behind the foam: its last frame stays on the canvas.
    if (r && !this.state.meta.atMultiverse) {
      r.pullBack.update(frameDt);
      r.camera.update(frameDt, this.state.settings.reduceMotion);
      this.era?.render(r, frameDt);
      r.render(frameDt);
    }
    this.uiClock += frameDt;
    if (this.uiClock >= UI_TICK_SECONDS) {
      this.uiClock = 0;
      this.bus.emit('ui', {});
    }
  }

  // ───────────────────────────────────────── energy

  get energy(): number {
    return this.state.run.energy;
  }

  /** Credit energy (eV). Pass a world position to show it where it happened. */
  gain(eV: number, x?: number, y?: number): void {
    // An era known by heart yields twice as much: the player knows where the energy is.
    this.credit(this.knowledge(`heart.${this.state.run.era}`) > 0 ? eV * 2 : eV, x, y);
  }

  /** Energy already counted as earned (offline credit comes from the measured rate). */
  private credit(eV: number, x?: number, y?: number): void {
    if (!(eV > 0)) return;
    const run = this.state.run;
    run.energy += eV;
    run.energyTotal += eV;
    this.state.lifetime.energyTotal += eV;
    this.energyMeter.add(eV);
    if (!run.joules && run.energyTotal >= EV_PER_JOULE) {
      run.joules = true;
      this.bus.emit('joules', {});
      this.toast('1 joule: about what it takes to lift an apple one meter.', 'milestone');
    }
    if (x !== undefined && y !== undefined) this.bus.emit('gain', { amount: eV, x, y });
  }

  spend(eV: number): boolean {
    const run = this.state.run;
    if (eV > run.energy * (1 + 1e-12)) return false;
    run.energy = Math.max(0, run.energy - eV);
    return true;
  }

  // ───────────────────────────────────────── phenomena

  level(id: string): number {
    return this.state.run.phenomena[id] ?? 0;
  }

  flag(name: string): boolean {
    return !!this.state.run.flags[name];
  }

  setFlag(name: string, value = true): void {
    this.state.run.flags[name] = value;
  }

  phenomenon(id: string): PhenomenonDef {
    const p = this.phenomena.get(id);
    if (!p) throw new Error(`Unknown phenomenon "${id}"`);
    return p;
  }

  phenomenonCost(id: string): number {
    return this.phenomenon(id).cost(this.level(id));
  }

  isMaxed(id: string): boolean {
    const p = this.phenomenon(id);
    return p.max !== undefined && this.level(id) >= p.max;
  }

  private requirementsMet(p: PhenomenonDef): boolean {
    return !p.requires || p.requires.every((r) => this.level(r) > 0);
  }

  /** Phenomena of an era that are visible now. Revealing is permanent within a universe. */
  visiblePhenomena(era: EraId): PhenomenonDef[] {
    const run = this.state.run;
    const out: PhenomenonDef[] = [];
    for (const p of this.eras[era]?.phenomena ?? []) {
      if (run.revealed[p.id]) {
        out.push(p);
        continue;
      }
      if (!this.requirementsMet(p)) continue;
      const shown = p.reveal ? p.reveal(this) : run.energy >= 0.25 * p.cost(this.level(p.id));
      if (shown) {
        run.revealed[p.id] = true;
        out.push(p);
      }
    }
    return out;
  }

  /** Buy up to `count` levels (Infinity = as many as affordable). Returns levels bought. */
  buy(id: string, count = 1): number {
    if (this.inFinale || this.passing || this.state.meta.atMultiverse) return 0;
    const p = this.phenomenon(id);
    if (!this.requirementsMet(p)) return 0;
    let bought = 0;
    while (bought < count && !this.isMaxed(id)) {
      const cost = p.cost(this.level(id));
      if (!this.spend(cost)) break;
      this.state.run.phenomena[id] = this.level(id) + 1;
      bought++;
      p.onBuy?.(this.level(id));
    }
    if (bought > 0) {
      this.state.run.revealed[id] = true;
      this.stats.invalidate();
      if (p.codex) this.discover(p.codex);
      this.bus.emit('buy', { id, level: this.level(id) });
    }
    return bought;
  }

  /** Current and next value of the stat a phenomenon previews. */
  preview(id: string): { now: number; next: number } | null {
    const p = this.phenomenon(id);
    if (!p.shows) return null;
    const lvl = this.level(id);
    const nextMods = (p.effects?.(lvl + 1) ?? []).map((m) => ({ ...m, sid: id }));
    return { now: this.stats.get(p.shows.stat), next: this.stats.preview(p.shows.stat, id, nextMods) };
  }

  private *phenomenaModifiers(): Iterable<Modifier> {
    for (const [id, lvl] of Object.entries(this.state.run.phenomena)) {
      if (lvl <= 0) continue;
      const p = this.phenomena.get(id);
      if (!p?.effects) continue;
      for (const m of p.effects(lvl)) yield { ...m, sid: id };
    }
  }

  // ───────────────────────────────────────── codex

  codexEntry(id: string): CodexEntry | undefined {
    return this.codex.get(id);
  }

  allCodex(): CodexEntry[] {
    return [...this.codex.values()];
  }

  isDiscovered(id: string): boolean {
    return this.state.codex.discovered[id] !== undefined;
  }

  /** Record a discovery. Returns true the first time. */
  discover(id: string): boolean {
    const entry = this.codex.get(id);
    if (!entry || this.isDiscovered(id)) return false;
    this.state.codex.discovered[id] = this.now();
    this.state.run.finds = (this.state.run.finds ?? 0) + 1;
    if (entry.bonus) this.stats.invalidate();
    this.bus.emit('discover', { entry });
    return true;
  }

  private *codexModifiers(): Iterable<Modifier> {
    for (const id of Object.keys(this.state.codex.discovered)) {
      const e = this.codex.get(id);
      if (!e?.bonus) continue;
      for (const m of e.bonus.mods) yield { ...m, sid: `codex:${id}` };
    }
  }

  // ───────────────────────────────────────── epochs and eras

  /** Definition of any era (undefined if that era isn't part of this build). */
  eraDefOf(id: EraId): EraDef | undefined {
    return this.eras[id];
  }

  get eraDef(): EraDef {
    const def = this.eras[this.state.run.era];
    if (!def) throw new Error(`Era "${this.state.run.era}" is not available`);
    return def;
  }

  /** The current era's steps in this universe (an era may change them with its fate). */
  steps(id: EraId = this.state.run.era): readonly EpochStep[] {
    const def = this.eras[id];
    if (!def) throw new Error(`Era "${id}" is not available`);
    return def.stepsFor?.(this) ?? def.steps;
  }

  get currentStep(): EpochStep {
    return this.steps()[this.state.run.step];
  }

  get nextStep(): EpochStep | null {
    const step = this.steps()[this.state.run.step + 1];
    if (!step) return null;
    // An era known by heart: its steps cost a quarter less.
    return this.knowledge(`heart.${this.state.run.era}`) > 0 ? { ...step, cost: step.cost * 0.75 } : step;
  }

  /** Why the next step can't be taken right now (besides energy), or null. */
  stepBlocker(): string | null {
    if (this.inFinale || this.passing) return 'In progress';
    const next = this.nextStep;
    if (!next) return 'End of era';
    return next.gate?.(this) ?? null;
  }

  /** The next step's goal, with its progress kept within 0–1, or null (no next step, or no goal written). */
  stepGoal(): StepGoal | null {
    const goal = this.nextStep?.goal?.(this);
    if (!goal) return null;
    const p = goal.progress;
    return { ...goal, progress: Number.isFinite(p) ? Math.min(1, Math.max(0, p)) : 0 };
  }

  canAdvance(): boolean {
    const next = this.nextStep;
    return !!next && this.stepBlocker() === null && this.energy >= next.cost;
  }

  /** Buy the next epoch step. The era's last step starts its finale. */
  advance(): boolean {
    if (!this.canAdvance()) return false;
    this.takeStep(this.nextStep as EpochStep);
    return true;
  }

  /**
   * Development and QA: take the next step now, whatever it needs: its energy is given and its gate
   * passed over (an era whose steps are not bought reaches it its own way). The era's last step
   * starts its finale as usual. False while a finale or a pull-back plays, or at the end.
   */
  skipStep(): boolean {
    if (this.inFinale || this.passing || this.state.meta.atMultiverse || !this.era) return false;
    if (this.era.skip?.()) return true;
    const next = this.nextStep;
    if (!next) return false;
    this.state.run.energy = Math.max(this.state.run.energy, next.cost);
    this.takeStep(next);
    return true;
  }

  private takeStep(next: EpochStep): void {
    this.spend(next.cost);
    const run = this.state.run;
    run.step++;
    run.time = next.t;
    run.history.push({ t: next.t, era: run.era, text: next.history, at: run.playTime });
    this.stats.invalidate();
    this.era?.onStep(run.step);
    this.bus.emit('step', { era: run.era, index: run.step, step: next });
    this.persist();
    if (run.step === this.steps().length - 1) void this.runFinale();
  }

  private async runFinale(): Promise<void> {
    const era = this.state.run.era;
    this.inFinale = true;
    this.bus.emit('finaleStart', { era });
    try {
      await this.era?.finale();
      // Powers of Ten: the era ends by drawing back from it, and the next arrives around what it made.
      const def = this.eras[era];
      const distance = def?.pullBack;
      if (distance && this.renderer && this.handsOver()) await this.renderer.pullBack.recede(distance, this.state.settings.reduceMotion, def?.pullBackTiming);
    } finally {
      this.inFinale = false;
    }
    this.completeEra();
  }

  /** A pull-back between eras is playing (the next era's input waits for it). */
  get passing(): boolean {
    return !!this.renderer?.pullBack.active;
  }

  /** Finishing the era now playing leads into another era (not to the universe's end, nor a rest). */
  private handsOver(): boolean {
    const from = this.state.run.era;
    return !diesYoung(this.state.run.constants, from) && from !== ERA_ORDER[ERA_ORDER.length - 1] && this.nextEraId() !== null;
  }

  nextEraId(): EraId | null {
    const i = ERA_ORDER.indexOf(this.state.run.era);
    for (let j = i + 1; j < ERA_ORDER.length; j++) if (this.eras[ERA_ORDER[j]]) return ERA_ORDER[j];
    return null;
  }

  private completeEra(): void {
    const run = this.state.run;
    const from = run.era;
    this.setFlag(`${from}.complete`);
    this.bus.emit('eraEnd', { era: from });
    // Some universes can go no further than this.
    const barren = diesYoung(run.constants, from);
    if (barren) {
      this.endUniverse(barren);
      return;
    }
    // The last era of all: the universe has reached its fate.
    if (from === ERA_ORDER[ERA_ORDER.length - 1]) {
      this.endUniverse(null);
      return;
    }
    if (!this.nextEraId()) {
      // Last implemented era: the universe rests at its final step.
      this.persist();
      return;
    }
    this.advanceEra();
  }

  /** Leaves the finished era for the next one. */
  private advanceEra(): void {
    const run = this.state.run;
    const next = this.nextEraId()!;
    this.era?.exit();
    this.era = null;
    run.era = next;
    run.step = 0;
    const first = this.eras[next]!.steps[0];
    run.time = first.t;
    run.history.push({ t: first.t, era: next, text: first.history, at: run.playTime });
    // What the last era earned (its finale's payout most of all) is not what this one will earn while
    // you are away.
    this.energyMeter.reset();
    this.enterEra(next, true);
    this.renderer?.pullBack.arrive();
    this.persist();
  }

  private enterEra(id: EraId, fresh: boolean): void {
    const def = this.eras[id];
    if (!def) throw new Error(`Era "${id}" is not available`);
    // An era known by heart starts with its first phenomena understood.
    if (fresh && this.knowledge(`heart.${id}`) > 0) for (const pid of heartGrants(def)) this.grant(pid);
    this.era = def.create(this);
    this.stats.invalidate();
    const [hw, hh] = this.viewportHalf();
    this.era.resize?.(hw, hh);
    this.era.enter(fresh);
    this.bus.emit('eraStart', { era: id, fresh });
  }

  /** Half extents of the visible world at rest (no zoom, shake or breath). */
  viewportHalf(): [number, number] {
    const cam = this.renderer?.camera;
    const hh = (cam?.viewHeight ?? 1000) / 2;
    return [hh * (cam?.aspect ?? 16 / 9), hh];
  }

  // ───────────────────────────────────────── input

  pointer(e: PointerInfo): void {
    // Mid pull-back nothing new starts under the cursor (a press that began before it still ends).
    if (e.type === 'down' && this.passing) return;
    if (e.type === 'down') this.state.lifetime.clicks++;
    this.era?.pointer(e);
  }

  // ───────────────────────────────────────── messages

  toast(text: string, tone: 'quiet' | 'milestone' = 'quiet'): void {
    this.bus.emit('toast', { text, tone });
  }

  sfx(id: string, x?: number, intensity?: number, pitch?: number): void {
    this.bus.emit('sfx', { id, x, intensity, pitch });
  }

  // ───────────────────────────────────────── persistence

  persist(): void {
    if (this.adopted) return;
    const run = this.state.run;
    run.rng = this.sim.snapshot();
    run.meters.energy = this.energyMeter.rate;
    try {
      this.save.save(this.state, this.now());
      this.bus.emit('saved', {});
    } catch (err) {
      console.error('Save failed', err);
    }
  }

  applyOffline(seconds: number, announce = true): void {
    const s = Math.min(seconds, OFFLINE_CAP_SECONDS * (this.knowledge('patience') > 0 ? 2 : 1));
    if (s <= 0) return;
    // The foam goes on budding while you are away; a universe that has ended stays as it was.
    this.inflate$(s);
    if (this.state.meta.atMultiverse || !this.era || this.inFinale) return;
    const energy = this.energyMeter.rate * s;
    const report = this.era.offline(s);
    if (energy > 0) this.credit(energy);
    if (announce) this.bus.emit('offline', { seconds: s, energy, report });
  }

  // ───────────────────────────────────────── the multiverse

  /** Level of a piece of Knowledge (0 if not known). */
  knowledge(id: string): number {
    return this.state.meta.knowledge[id] ?? 0;
  }

  /** A phenomenon's first level, given rather than bought (Knowledge). */
  private grant(id: string): void {
    const p = this.phenomena.get(id);
    if (!p || this.level(id) > 0) return;
    this.state.run.phenomena[id] = 1;
    this.state.run.revealed[id] = true;
    p.onBuy?.(1);
    if (p.codex) this.discover(p.codex);
    this.stats.invalidate();
  }

  /** The universe is over (its fate, or it died young): record it, learn from it, offer seeds. */
  endUniverse(barren: Barren | null): void {
    const run = this.state.run;
    const meta = this.state.meta;
    if (meta.atMultiverse) return;
    const fate = barren ? 'barren' : fateOf(run.constants);
    const blackHoles = barren?.starless ? 0 : (run.legacy.blackHoles ?? 0) * blackHoleFactor(run.constants);
    const insight = insightFor({ constants: run.constants, newDiscoveries: run.finds ?? 0, blackHoles, fate, mult: 1.5 ** this.knowledge('memory') });
    const label = barren ? barren.label : FATE_NAME[fate as Fate];
    meta.insight += insight.total;
    meta.universesCompleted++;
    meta.unlocked = true;
    meta.lineage.push({ index: run.index, parent: run.parent ?? null, constants: { ...run.constants }, fate: label, blackHoles, playTime: run.playTime, legacy: { ...run.legacy }, insight: insight.total });
    meta.last = { index: run.index, fate, title: barren ? barren.title : label, text: barren ? barren.text : FATE_TEXT[fate as Fate], insight, blackHoles, playTime: run.playTime, finds: run.finds ?? 0 };
    meta.seeds = this.makeSeeds();
    meta.atMultiverse = true;
    this.persist();
    this.bus.emit('universeEnd', {});
  }

  /**
   * Candidate seeds: drifted copies of the numbers of the universe whose black holes hold them. A
   * universe that made no black holes leaves no seeds (offspring come from black holes), so the
   * choice goes back to the nearest ancestor that made some.
   */
  private makeSeeds(): Constants[] {
    const run = this.state.run;
    const meta = this.state.meta;
    let from = meta.lineage[meta.lineage.length - 1];
    while (from && from.blackHoles < 1 && from.parent !== null) {
      const up = meta.lineage.find((u) => u.index === from!.parent);
      if (!up) break;
      from = up;
    }
    meta.seedFrom = from?.index ?? run.index;
    const parent = from?.constants ?? run.constants;
    const rng = new Rng((run.seed ^ Math.imul(run.index, 0x9e3779b9)) >>> 0);
    const n = 3 + this.knowledge('seeds');
    const scale = 0.5 ** this.knowledge('steady');
    return Array.from({ length: n }, () => mutate(parent, rng, { scale }));
  }

  /** The numbers of the universe the offered seeds come from. */
  seedParent(): Constants {
    const meta = this.state.meta;
    return meta.lineage.find((u) => u.index === meta.seedFrom)?.constants ?? this.state.run.constants;
  }

  /** Inflate seed `k`: a new universe with its numbers starts at the very beginning. */
  inflate(k: number): boolean {
    const meta = this.state.meta;
    const c = meta.seeds[k];
    if (!meta.atMultiverse || !c) return false;
    const prev = this.state.run;
    this.era?.exit();
    this.era = null;
    this.state.run = newRun(prev.index + 1, (Math.imul(prev.seed, 1664525) + 1013904223) >>> 0, c, this.now(), meta.seedFrom || prev.index);
    meta.atMultiverse = false;
    meta.seeds = [];
    this.renderer?.pullBack.stop();
    this.sim.restore(new Rng(this.state.run.seed).snapshot());
    this.energyMeter.reset();
    this.stats.invalidate();
    this.enterEra(this.state.run.era, true);
    this.persist();
    this.bus.emit('universeStart', {});
    return true;
  }

  /** Eternal inflation: once enough universes exist, the foam buds on its own, paying at milestones. */
  private inflate$(dt: number): void {
    const meta = this.state.meta;
    if (meta.lineage.length < INFLATION_AFTER) return;
    if (meta.inflationT === 0) this.discover('eternal-inflation');
    meta.inflationT += dt;
    const next = INFLATION_MILESTONES[meta.inflationMilestones];
    if (next && inflationLog(meta.inflationT) >= next.at) {
      meta.inflationMilestones++;
      meta.insight += next.insight;
      this.toast(next.text, 'milestone');
      // Between universes nothing else saves, and Insight should never be lost.
      this.persist();
    }
  }

  /** Spend Insight on the next level of a piece of Knowledge. */
  buyKnowledge(id: string): boolean {
    const def = knowledgeDef(id);
    const meta = this.state.meta;
    const level = this.knowledge(id);
    if (!def || level >= def.costs.length) return false;
    const cost = def.costs[level];
    if (meta.insight < cost) return false;
    meta.insight -= cost;
    meta.knowledge[id] = level + 1;
    this.stats.invalidate();
    this.persist();
    return true;
  }

  /**
   * Make `state` the save (an import) and stop saving this session, so the reload that follows starts
   * from it: the page's own last-moment saves would otherwise write the old universe back over it.
   */
  adopt(state: GameState): void {
    this.save.save(state, this.now());
    this.adopted = true;
  }

  /**
   * Add an era's share to a legacy total once. A finale replayed after a reload replaces its share
   * instead of adding it a second time.
   */
  tally(key: string, era: EraId, value: number): void {
    const legacy = this.state.run.legacy;
    const part = `${key}.${era}`;
    legacy[key] = (legacy[key] ?? 0) - (legacy[part] ?? 0) + value;
    legacy[part] = value;
  }

  /** Start over from the very beginning (keeps settings). */
  hardReset(): void {
    const settings = this.state.settings;
    this.era?.exit();
    this.era = null;
    this.save.wipe();
    // Whatever finale or pull-back was playing belonged to the universe being wiped.
    this.inFinale = false;
    this.renderer?.pullBack.stop();
    this.state = defaultState(freshSeed(), this.now());
    this.state.settings = settings;
    this.sim.restore(new Rng(this.state.run.seed).snapshot());
    this.energyMeter.reset();
    this.stats.invalidate();
    this.enterEra(this.state.run.era, true);
    this.persist();
  }
}
