/**
 * World ↔ screen mapping plus the camera's physical "acting": trauma-based shake for violent events
 * and a breath (a brief zoom out and back) when cosmic time advances.
 *
 * World space is y-down to match the DOM, centred on (0, 0), with `viewHeight` world units visible
 * vertically at zoom 1. Input mapping ignores shake so the cursor never jitters.
 */
export class Camera {
  x = 0;
  y = 0;
  viewHeight = 1000;
  zoom = 1;
  aspect = 16 / 9;
  /** How far the camera has drawn back for a pull-back between eras (×, 1 at rest); see PullBack. */
  distance = 1;

  shakeX = 0;
  shakeY = 0;
  private trauma = 0;
  private breathT = 1;
  private breathAmp = 0;
  private breathDur = 1.4;
  /** Reduce motion: a breath is a quarter as deep, so a step forward reads without the swoop. */
  private breathScale = 1;
  private t = 0;

  addTrauma(amount: number): void {
    this.trauma = Math.min(1, this.trauma + amount);
  }

  /** A short zoom-out-and-return. Amplitude is a fraction of the view (0.06 = 6 %). */
  breathe(amplitude = 0.06, duration = 1.4): void {
    this.breathT = 0;
    this.breathAmp = amplitude;
    this.breathDur = duration;
  }

  update(dt: number, reduceMotion: boolean): void {
    this.t += dt;
    this.trauma = Math.max(0, this.trauma - dt * 1.5);
    this.breathScale = reduceMotion ? 0.25 : 1;
    const s = reduceMotion ? 0 : this.trauma * this.trauma;
    const amp = s * this.viewHeight * 0.012;
    const t = this.t;
    this.shakeX = amp * (Math.sin(t * 37.1) * 0.55 + Math.sin(t * 23.3 + 1.7) * 0.45);
    this.shakeY = amp * (Math.sin(t * 31.7 + 0.6) * 0.55 + Math.sin(t * 19.1 + 2.9) * 0.45);
    if (this.breathT < 1) this.breathT = Math.min(1, this.breathT + dt / this.breathDur);
  }

  /** Extra zoom-out from an active breath: rises fast, settles slowly. */
  get breath(): number {
    const t = this.breathT;
    if (t >= 1) return 0;
    const rise = 1 - Math.exp(-t * 9);
    const fall = 1 - t * t * (3 - 2 * t);
    return this.breathAmp * this.breathScale * rise * fall;
  }

  get halfH(): number {
    return (this.viewHeight / this.zoom) * this.distance * (1 + this.breath) * 0.5;
  }

  get halfW(): number {
    return this.halfH * this.aspect;
  }

  /** Fills `out` with [centreX, centreY, halfW, halfH] including shake (for drawing). */
  view(out: Float32Array): void {
    out[0] = this.x + this.shakeX;
    out[1] = this.y + this.shakeY;
    out[2] = this.halfW;
    out[3] = this.halfH;
  }

  screenToWorld(px: number, py: number, cssW: number, cssH: number): [number, number] {
    return [this.x + ((px / cssW) * 2 - 1) * this.halfW, this.y + ((py / cssH) * 2 - 1) * this.halfH];
  }

  worldToScreen(x: number, y: number, cssW: number, cssH: number): [number, number] {
    return [
      (((x - this.x) / this.halfW + 1) / 2) * cssW,
      (((y - this.y) / this.halfH + 1) / 2) * cssH,
    ];
  }
}
