/**
 * The modifier registry.
 *
 * Every tunable number in the game is a named stat: `value = (base + Σ add) × Π mul`.
 * Modifiers come from providers (phenomena, discoveries, legacy, constants, knowledge), so any
 * value on screen can explain itself as a breakdown in its tooltip.
 */

export interface StatDef {
  id: string;
  base: number;
  min?: number;
  max?: number;
}

export type ModKind = 'add' | 'mul';

export interface Modifier {
  stat: string;
  kind: ModKind;
  value: number;
  /** Human-readable origin shown in breakdowns ("Charge-Parity Violation III", "Carbon"). */
  source: string;
  /** Stable id of the provider entry (e.g. a phenomenon id), used for what-if previews. */
  sid?: string;
}

export type ModProvider = () => Iterable<Modifier>;

export interface Breakdown {
  base: number;
  adds: { source: string; value: number }[];
  muls: { source: string; value: number }[];
  value: number;
  clamped: boolean;
}

export class Stats {
  private defs = new Map<string, StatDef>();
  private providers: ModProvider[] = [];
  private byStat = new Map<string, Modifier[]>();
  private cache = new Map<string, number>();
  private listeners = new Set<() => void>();
  private dirty = true;

  define(defs: readonly StatDef[]): void {
    for (const d of defs) this.defs.set(d.id, d);
    this.dirty = true;
  }

  addProvider(p: ModProvider): () => void {
    this.providers.push(p);
    this.dirty = true;
    return () => {
      this.providers = this.providers.filter((q) => q !== p);
      this.dirty = true;
    };
  }

  /** Call after anything that can change a modifier (purchase, discovery, era change). */
  invalidate(): void {
    this.dirty = true;
    for (const fn of this.listeners) fn();
  }

  /** Subscribe to invalidation, e.g. so a simulation can refresh its cached stat values. */
  onChange(fn: () => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  has(id: string): boolean {
    return this.defs.has(id);
  }

  get(id: string): number {
    if (this.dirty) this.rebuild();
    const cached = this.cache.get(id);
    if (cached !== undefined) return cached;
    const v = this.compute(id).value;
    this.cache.set(id, v);
    return v;
  }

  breakdown(id: string): Breakdown {
    if (this.dirty) this.rebuild();
    return this.compute(id);
  }

  private rebuild(): void {
    this.byStat.clear();
    this.cache.clear();
    for (const p of this.providers) {
      for (const m of p()) {
        let list = this.byStat.get(m.stat);
        if (!list) {
          list = [];
          this.byStat.set(m.stat, list);
        }
        list.push(m);
      }
    }
    this.dirty = false;
  }

  /**
   * What would `id` be if the modifiers from `sid` were replaced by `mods`?
   * Pure: does not touch the cache or notify listeners.
   */
  preview(id: string, sid: string, mods: readonly Modifier[]): number {
    if (this.dirty) this.rebuild();
    const kept = (this.byStat.get(id) ?? []).filter((m) => m.sid !== sid);
    return this.compute(id, kept.concat(mods.filter((m) => m.stat === id))).value;
  }

  private compute(id: string, override?: readonly Modifier[]): Breakdown {
    const def = this.defs.get(id);
    if (!def) throw new Error(`Unknown stat "${id}"`);
    const mods = override ?? this.byStat.get(id) ?? [];
    let add = 0;
    let mul = 1;
    const adds: Breakdown['adds'] = [];
    const muls: Breakdown['muls'] = [];
    for (const m of mods) {
      if (m.kind === 'add') {
        add += m.value;
        adds.push({ source: m.source, value: m.value });
      } else {
        mul *= m.value;
        muls.push({ source: m.source, value: m.value });
      }
    }
    let value = (def.base + add) * mul;
    let clamped = false;
    if (def.min !== undefined && value < def.min) {
      value = def.min;
      clamped = true;
    }
    if (def.max !== undefined && value > def.max) {
      value = def.max;
      clamped = true;
    }
    return { base: def.base, adds, muls, value, clamped };
  }
}
