/**
 * The plasma of the Soup: a medium that shines by its own heat. Rays march through a slab around the
 * game plane (at reduced resolution). Its structure is convection: cellular noise gives cells with
 * bright interiors and dark lanes where they meet, warped by gradient noise, with smaller cells and
 * fine turbulence inside, all boiling in place (the early universe had no winds). Every point glows
 * at a temperature on a blackbody ramp (rose, amber, gold, white), hotter in the cell cores, cooler
 * in the lanes, and the whole medium cools as the era goes on (`heat`). A faint field of colour charge
 * tints it. Light sources inside (quarks, flashes) brighten and tint it around them, light fronts
 * sweep through it, flux tubes glow in it, and it absorbs, so depth reads: near cells sharp and
 * bright, far ones veiled.
 *
 * What the march spends is kept where it shows: steps crowd toward the front of the slab (the hot,
 * detailed matter) and lengthen behind it (cool, dim, seen through the front), each ray only evaluates
 * the lights and fronts that pass near it, and the charge tint's three values come from one lookup.
 * Without float targets it runs on 8-bit sRGB targets with its light scaled to the scene's range (see
 * LDR_RANGE), its running average rounded at random so it still converges.
 */
import { FULLSCREEN_VS, Target, bindTexture, drawFullscreen, lightFormat, lightGain, tryProgram, type GLCaps, type Program, type TargetFormat } from './gl';
import { HEADER } from './glsl';
import { NOISE_SIZE, cellVolume, chargeVolume, noiseVolume } from './noise3d';
import type { LayerFrame, RenderLayer } from './renderer';
import type { VolumeFront, VolumeLight, VolumeTube } from './volume';

export interface PlasmaConfig {
  /** Resolution relative to the scene, and steps per ray. */
  scale: number;
  steps: number;
  /** Half-depth of the slab, how far in front of the plane it starts, and the camera distance. */
  depth: number;
  near: number;
  focal: number;
  /** World units per cell tile (five cells across), tiles per second of boiling, warp amount. */
  cellSize: number;
  boil: number;
  warp: number;
  /** 1 is white-hot, 0 is cooled to the edge of confinement. */
  heat: number;
  /** Emission scale, absorption per unit, how dark the lanes go (0–1). */
  brightness: number;
  absorb: number;
  lanes: number;
  /** Strength of the colour-charge tint. */
  charge: number;
  /** Depth (world units behind the slab's front) over which the matter cools and dims. */
  fade: number;
  /** The colour the coolest matter keeps (linear, before brightness). */
  cool: [number, number, number];
  /**
   * How long dim matter keeps to red before its colour climbs the ramp (0: the plain ramp). Embers
   * glow red until they are bright; orange that is still dim reads as brown, not as heat.
   */
  ember: number;
}

export function defaultPlasma(): PlasmaConfig {
  return { scale: 0.5, steps: 48, depth: 900, near: 500, focal: 1600, cellSize: 1400, boil: 0.012, warp: 0.55, heat: 1, brightness: 1, absorb: 0.004, lanes: 0.85, charge: 0.12, fade: 400, cool: [0.06, 0.07, 0.16], ember: 0 };
}

/**
 * Steps actually marched per `steps` asked for. The steps are spread as t(u) = (u + u²) / 2 along the
 * slab, so at this share the front third is sampled as densely as `steps` evenly spaced steps would,
 * and the cool, dim depths behind it more sparsely.
 */
const STEP_SHARE = 0.75;

const MARCH_FS = HEADER + /* glsl */ `
precision highp sampler3D;
in vec2 vUv;
out vec4 outColor;
uniform sampler3D uCells;
uniform sampler3D uNoise;
uniform sampler3D uChargeTex;
uniform vec4 uView;
uniform float uFocal;
uniform float uDepth;
uniform float uNear;
uniform int uSteps;
uniform float uCellSize;
uniform float uWarp;
uniform float uHeat;
uniform float uBright;
uniform float uAbsorb;
uniform float uLanes;
uniform float uCharge;
uniform float uFade;
uniform float uFrame;
uniform float uGain;
uniform float uEmber;
uniform vec3 uCool;
// Where boiling has carried each lookup (it depends on time alone): the three warp components, the
// big and small cells, the fine turbulence, the charge field.
uniform vec3 uOffWarpX;
uniform vec3 uOffWarpY;
uniform vec3 uOffWarpZ;
uniform vec3 uOffBig;
uniform vec3 uOffSmall;
uniform vec3 uOffFine;
uniform vec3 uOffCharge;
uniform vec4 uLight[8];
uniform vec3 uLightCol[8];
uniform int uLightCount;
uniform vec4 uTubeA[6];
uniform vec3 uTubeB[6];
uniform vec3 uTubeCol[6];
uniform int uTubeCount;
uniform vec4 uFront[4];
uniform vec3 uFrontCol[4];
uniform int uFrontCount;

float N(vec3 p) { return texture(uNoise, p).r; }

/** Blackbody-like ramp for temperature t (0 cool … 1 hottest): colour times radiance. */
vec3 blackbody(float t) {
  t = clamp(t, 0.0, 1.25);
  float h = min(1.25, pow(t, 1.0 + uEmber));
  vec3 c = mix(vec3(0.42, 0.0, 0.14), vec3(1.0, 0.1, 0.06), smoothstep(0.0, 0.3, h));
  c = mix(c, vec3(1.0, 0.36, 0.04), smoothstep(0.25, 0.55, h));
  c = mix(c, vec3(1.0, 0.62, 0.16), smoothstep(0.5, 0.85, h));
  c = mix(c, vec3(1.0, 0.92, 0.78), smoothstep(0.9, 1.25, h));
  // Radiance climbs steeply with temperature (Stefan–Boltzmann, softened).
  return c * (0.02 + 2.4 * t * t * t * t);
}

/** Density of glowing matter at p, and its temperature. */
float field(vec3 p, out float temp, out vec3 tint) {
  vec3 q = p / uCellSize;
  vec3 qw = q * 0.37;
  vec3 w = vec3(N(qw + uOffWarpX), N(qw + uOffWarpY), N(qw + uOffWarpZ)) - 0.5;
  q += w * uWarp;
  vec2 big = texture(uCells, q + uOffBig).rg;
  vec2 small = texture(uCells, q * 2.6 + uOffSmall).rg;
  float fine = N(q * 3.1 + uOffFine);
  // Interiors dense, lanes thin (so a ray down a lane reaches deeper); smaller cells break the
  // interiors up; fine turbulence on top.
  float interior = smoothstep(0.015, 0.14, big.g);
  float sub = mix(1.0 - uLanes * 0.5, 1.0, smoothstep(0.01, 0.12, small.g));
  float d = mix(1.0 - uLanes, 1.0, interior) * sub * (0.85 + 0.3 * fine);
  // Hottest at a cell's centre (small F1), cooler toward its lanes, and cooler with depth: the lanes
  // are depressions where the eye sees deeper, cooler matter (as in the Sun's granulation).
  float sink = exp(-max(0.0, p.z + uNear) / uFade);
  temp = uHeat * mix(0.22, 1.0, interior * interior) * (1.3 - 0.75 * big.r) * (0.88 + 0.24 * fine) * mix(0.3, 1.0, sink);
  // The charge field: the noise at three offsets in one lookup (the texture holds it shifted by 0.375
  // and 0.703 of a tile, within a hundredth of a tile of the 0.37 and 0.71 three lookups would add).
  tint = vec3(1.0);
  if (uCharge > 0.0) tint += uCharge * (texture(uChargeTex, q * 0.21 + uOffCharge).rgb - 0.5) * 2.0;
  return d;
}

float rayTube(vec3 o, vec3 d, vec3 a, vec3 b) {
  vec3 ab = b - a;
  vec3 ao = o - a;
  float abab = dot(ab, ab);
  float abd = dot(ab, d);
  float aod = dot(ao, d);
  float aoab = dot(ao, ab);
  float den = abab - abd * abd;
  float s = den > 1e-6 ? clamp((aoab - aod * abd) / den, 0.0, 1.0) : 0.0;
  vec3 c = a + ab * s;
  float t = max(dot(c - o, d), 0.0);
  return length(o + d * t - c);
}

/** Interleaved gradient noise (Jimenez 2014): a spatially even jitter that converges fast over frames. */
float ign(vec2 p) { return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715)))); }

/** Index of the lowest set bit of a non-zero mask (a power of two's log is exact in a float). */
int lowBit(int m) { return int(log2(float(m & -m)) + 0.5); }

void main() {
  vec2 ndc = vUv * 2.0 - 1.0;
  vec3 onPlane = vec3(uView.x + ndc.x * uView.z, uView.y - ndc.y * uView.w, 0.0);
  vec3 cam = vec3(uView.xy, -uFocal);
  vec3 dir = normalize(onPlane - cam);
  float t0 = (-uNear - cam.z) / dir.z;
  float t1 = (uDepth - cam.z) / dir.z;
  float len = t1 - t0;
  // The lights this ray passes close enough to matter: a light falls off as q^-1.5 with q = 1 + d²/r²,
  // so beyond twelve radii it adds under a two-thousandth of its colour, and is left out of every step.
  int lights = 0;
  for (int k = 0; k < 8; k++) {
    if (k >= uLightCount) break;
    vec3 c = uLight[k].xyz;
    float reach = 12.0 * uLight[k].w;
    vec3 off = cam + dir * clamp(dot(c - cam, dir), t0, t1) - c;
    if (dot(off, off) < reach * reach) lights |= 1 << k;
  }
  // Likewise the fronts whose shell (within 3.5 widths, where the gaussian has all but vanished) the
  // ray actually crosses.
  int fronts = 0;
  vec3 pa = cam + dir * t0;
  vec3 pb = cam + dir * t1;
  for (int k = 0; k < 4; k++) {
    if (k >= uFrontCount) break;
    vec3 c = vec3(uFront[k].xy, 0.0);
    float nearest = length(cam + dir * clamp(dot(c - cam, dir), t0, t1) - c);
    float farthest = max(length(pa - c), length(pb - c));
    float band = 3.5 * uFront[k].w;
    if (uFront[k].z + band > nearest && uFront[k].z - band < farthest) fronts |= 1 << k;
  }
  // Steps crowd toward the front of the slab, where the matter is hottest and the detail is, and
  // lengthen behind it: at u along the march the ray is at t0 + len·(u + u²)/2, so a step is half the
  // even length at the front and one and a half times it at the back (each weighted by its length).
  // Each frame starts its steps at a different stratum (golden-ratio sequence), so the average converges.
  float du = 1.0 / float(uSteps);
  float jitter = fract(ign(gl_FragCoord.xy) + uFrame * 0.6180339887);
  vec3 L = vec3(0.0);
  float T = 1.0;
  for (int i = 0; i < 128; i++) {
    if (i >= uSteps || T < 0.015) break;
    float u = (float(i) + jitter) * du;
    float t = t0 + len * 0.5 * u * (1.0 + u);
    float stepLen = len * (0.5 + u) * du;
    vec3 p = cam + dir * t;
    float temp;
    vec3 tint;
    float d = field(p, temp, tint);
    vec3 lit = vec3(0.0);
    int ml = lights;
    while (ml != 0) {
      int k = lowBit(ml);
      ml &= ml - 1;
      vec3 dl = p - uLight[k].xyz;
      float r = uLight[k].w;
      float q = 1.0 + dot(dl, dl) / (r * r);
      lit += uLightCol[k] / (q * sqrt(q));
    }
    int mf = fronts;
    while (mf != 0) {
      int k = lowBit(mf);
      mf &= mf - 1;
      float x = (length(p - vec3(uFront[k].xy, 0.0)) - uFront[k].z) / uFront[k].w;
      lit += uFrontCol[k] * exp(-x * x);
    }
    // The source function: the radiance the medium shows where it is thick (a glowing surface),
    // reached gradually where it is thin. Emission and absorption are integrated together per step.
    // Warm where hot, and a cool violet fill where it is coolest: the shadows keep a colour of their
    // own instead of sinking to brown (the warm/cool split of a lit film frame).
    vec3 cool = uCool * (1.0 - smoothstep(0.15, 0.55, temp / max(uHeat, 1e-3)));
    vec3 S = (blackbody(temp) * tint + cool) * uBright + lit;
    float a = d * uAbsorb * stepLen;
    float e = exp(-a);
    L += T * S * (1.0 - e);
    T *= e;
  }
  for (int k = 0; k < 6; k++) {
    if (k >= uTubeCount) break;
    float r = uTubeA[k].w;
    float m = rayTube(cam, dir, uTubeA[k].xyz, uTubeB[k]);
    L += uTubeCol[k] * (1.7725 * r) * exp(-(m * m) / (r * r));
  }
  // Stored in the scene's range (scaled down when the targets are 8-bit).
  outColor = vec4(L * uGain, 1.0 - T);
}`;

/**
 * Folds this frame's march into the running average. The history is reprojected: each pixel looks up
 * where the matter it shows (at the depth most of the light comes from) was in last frame's view, so a
 * pan, zoom or shake moves the history with the medium instead of smearing it. What the reprojection
 * cannot follow (parallax at other depths, light that came or went) is caught by keeping the history
 * inside the range of this frame's neighbourhood; where last frame saw nothing, this frame stands alone.
 * An 8-bit history would lose the small steps an average takes to rounding (it would stall short of
 * the value it is converging on), so there it is rounded at random, up as often as the remainder says.
 */
const ACCUM_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uCur;
uniform sampler2D uPrev;
uniform vec4 uView;
uniform vec4 uPrevView;
uniform float uSpread;
uniform float uBlend;
uniform vec2 uTexel;
// The history's 8-bit step (0 for float targets), whether it is sRGB-encoded, and the frame number.
uniform float uQuantum;
uniform float uSrgb;
uniform float uFrame;
out vec4 outColor;
vec3 toSrgb(vec3 c) { c = max(c, vec3(0.0)); return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c)); }
vec3 fromSrgb(vec3 e) { e = max(e, vec3(0.0)); return mix(e / 12.92, pow((e + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), e)); }
vec4 store(vec4 o) {
  if (uQuantum <= 0.0) return o;
  float n = fract(52.9829189 * fract(dot(gl_FragCoord.xy + uFrame * vec2(5.588238, 3.317), vec2(0.06711056, 0.00583715)))) - 0.5;
  o.rgb = uSrgb > 0.5 ? fromSrgb(toSrgb(o.rgb) + n * uQuantum) : o.rgb + n * uQuantum;
  o.a += n * uQuantum;
  return o;
}
void main() {
  vec4 cur = texture(uCur, vUv);
  vec2 ndc = vUv * 2.0 - 1.0;
  vec2 w = uView.xy + vec2(ndc.x, -ndc.y) * uView.zw * uSpread;
  vec2 pn = (w - uPrevView.xy) / (uPrevView.zw * uSpread);
  vec2 puv = vec2(pn.x, -pn.y) * 0.5 + 0.5;
  if (uBlend >= 1.0 || any(lessThan(puv, vec2(0.0))) || any(greaterThan(puv, vec2(1.0)))) {
    outColor = cur;
    return;
  }
  vec4 lo = cur;
  vec4 hi = cur;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec4 n = texture(uCur, vUv + vec2(float(x), float(y)) * uTexel);
      lo = min(lo, n);
      hi = max(hi, n);
    }
  }
  vec4 prev = clamp(texture(uPrev, puv), lo, hi);
  outColor = store(mix(prev, cur, uBlend));
}`;

const COMPOSITE_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uSrc;
out vec4 outColor;
void main() { outColor = texture(uSrc, vUv); }`;

export class Plasma implements RenderLayer {
  readonly stage = 'media' as const;
  config: PlasmaConfig;
  /** Refilled by the caller every frame. */
  lights: VolumeLight[] = [];
  tubes: VolumeTube[] = [];
  fronts: VolumeFront[] = [];
  private gl: WebGL2RenderingContext | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private march: Program | null = null;
  private accum: Program | null = null;
  private comp: Program | null = null;
  private cells: WebGLTexture | null = null;
  private noise: WebGLTexture | null = null;
  private charge: WebGLTexture | null = null;
  private target: Target | null = null;
  /** The march averaged over recent frames (its per-pixel jitter becomes smooth): last frame's and this one's. */
  private history: [Target, Target] | null = null;
  /** How the targets store light (half floats, or 8-bit sRGB without float targets). */
  private format: TargetFormat = 'half';
  private fresh = true;
  /** The view the history was rendered in. */
  private prevView = new Float32Array(4);
  private frameNo = 0;
  private time = 0;
  private lightA = new Float32Array(32);
  private lightC = new Float32Array(24);
  private tubeA = new Float32Array(24);
  private tubeB = new Float32Array(18);
  private tubeC = new Float32Array(18);
  private frontA = new Float32Array(16);
  private frontC = new Float32Array(12);

  constructor(config: Partial<PlasmaConfig> = {}) {
    this.config = { ...defaultPlasma(), ...config };
  }

  init(gl: WebGL2RenderingContext, caps: GLCaps, emptyVao: WebGLVertexArrayObject): void {
    this.gl = gl;
    this.vao = emptyVao;
    this.march = tryProgram(gl, FULLSCREEN_VS, MARCH_FS, 'plasma:march');
    this.accum = tryProgram(gl, FULLSCREEN_VS, ACCUM_FS, 'plasma:accumulate');
    this.comp = tryProgram(gl, FULLSCREEN_VS, COMPOSITE_FS, 'plasma:composite');
    if (!this.march || !this.accum || !this.comp) {
      this.march = this.accum = this.comp = null;
      return;
    }
    this.cells = texture3d(gl, gl.RG8, gl.RG, cellVolume());
    this.noise = texture3d(gl, gl.R8, gl.RED, noiseVolume());
    this.charge = texture3d(gl, gl.RGBA8, gl.RGBA, chargeVolume());
    this.format = lightFormat(caps);
    this.target = new Target(gl, 1, 1, this.format);
    this.history = [new Target(gl, 1, 1, this.format), new Target(gl, 1, 1, this.format)];
    this.fresh = true;
  }

  draw(frame: LayerFrame): void {
    const gl = this.gl;
    const m = this.march;
    const acc = this.accum;
    if (!gl || !m || !acc || !this.comp || !this.cells || !this.noise || !this.charge || !this.target || !this.history) return;
    const c = this.config;
    const q = frame.quality;
    this.time += frame.dt;
    const t = this.target;
    const [prev, next] = this.history;
    // Lower quality: fewer steps at a lower resolution, and more frames averaged to make up for them
    // (the march's jitter moves every frame, so steps times frames is what smooths it).
    const scale = c.scale * q.volume;
    const asked = Math.max(4, Math.min(128, Math.round(c.steps * q.steps)));
    const steps = Math.max(4, Math.round(asked * STEP_SHARE));
    const blend = Math.min(1, 0.12 * (asked / Math.max(4, c.steps)));
    const w0 = t.width;
    const h0 = t.height;
    t.resize(frame.scene.width * scale, frame.scene.height * scale);
    prev.resize(t.width, t.height);
    next.resize(t.width, t.height);
    // A new size (a resized window, another quality level) leaves nothing to average with.
    if (t.width !== w0 || t.height !== h0) this.fresh = true;

    const nl = Math.min(8, this.lights.length);
    for (let i = 0; i < nl; i++) {
      const L = this.lights[i];
      this.lightA.set([L.x, L.y, L.z, Math.max(1, L.radius)], i * 4);
      this.lightC.set(L.color, i * 3);
    }
    const nt = Math.min(6, this.tubes.length);
    for (let i = 0; i < nt; i++) {
      const b = this.tubes[i];
      this.tubeA.set([b.ax, b.ay, b.az, Math.max(0.5, b.radius)], i * 4);
      this.tubeB.set([b.bx, b.by, b.bz], i * 3);
      this.tubeC.set(b.color, i * 3);
    }
    const nf = Math.min(4, this.fronts.length);
    for (let i = 0; i < nf; i++) {
      const f = this.fronts[i];
      this.frontA.set([f.x, f.y, f.radius, Math.max(1, f.width)], i * 4);
      this.frontC.set(f.color, i * 3);
    }

    gl.disable(gl.BLEND);
    t.bind();
    m.use().f1('uFocal', c.focal).f1('uDepth', c.depth).f1('uNear', c.near);
    m.f1('uCellSize', c.cellSize).f1('uWarp', c.warp).f1('uHeat', c.heat);
    // How far boiling has carried each lookup through its texture, wrapped to one tile here in double
    // precision (the textures repeat every tile, so the march sees the same thing, and long sessions
    // lose nothing to large coordinates).
    const tb = this.time * c.boil;
    const wrap = (x: number) => x - Math.floor(x);
    m.f3('uOffWarpX', 0.13, 0.71, wrap(tb * 0.6)).f3('uOffWarpY', 0.59, wrap(tb * 0.6), 0.91).f3('uOffWarpZ', wrap(tb * 0.6), 0.87, 0.17);
    m.f3('uOffBig', 0, 0, wrap(tb)).f3('uOffSmall', 0.31, 0.17, wrap(tb * 1.9)).f3('uOffFine', 0.2, 0.45, wrap(tb * 2.7)).f3('uOffCharge', 0, 0, wrap(tb * 0.3));
    m.f1('uBright', c.brightness).f1('uAbsorb', c.absorb).f1('uLanes', c.lanes).f1('uCharge', c.charge).f1('uFade', c.fade);
    m.f1('uFrame', (this.frameNo = (this.frameNo + 1) % 1024)).f1('uGain', lightGain(this.format)).f1('uEmber', c.ember);
    m.f3('uCool', ...c.cool);
    gl.uniform1i(m.loc('uSteps'), steps);
    gl.uniform4fv(m.loc('uView'), frame.view);
    gl.uniform4fv(m.loc('uLight'), this.lightA);
    gl.uniform3fv(m.loc('uLightCol'), this.lightC);
    gl.uniform1i(m.loc('uLightCount'), nl);
    gl.uniform4fv(m.loc('uTubeA'), this.tubeA);
    gl.uniform3fv(m.loc('uTubeB'), this.tubeB);
    gl.uniform3fv(m.loc('uTubeCol'), this.tubeC);
    gl.uniform1i(m.loc('uTubeCount'), nt);
    gl.uniform4fv(m.loc('uFront'), this.frontA);
    gl.uniform3fv(m.loc('uFrontCol'), this.frontC);
    gl.uniform1i(m.loc('uFrontCount'), nf);
    bindTexture(gl, 0, this.cells, gl.TEXTURE_3D);
    m.i1('uCells', 0);
    bindTexture(gl, 1, this.noise, gl.TEXTURE_3D);
    m.i1('uNoise', 1);
    bindTexture(gl, 2, this.charge, gl.TEXTURE_3D);
    m.i1('uChargeTex', 2);
    drawFullscreen(gl, this.vao!);
    for (const unit of [2, 1, 0]) bindTexture(gl, unit, null, gl.TEXTURE_3D);

    // Fold this frame's march into the running average (the medium changes slowly; the jitter doesn't).
    next.bind();
    acc.use().i1('uCur', 0).i1('uPrev', 1).f1('uBlend', this.fresh ? 1 : blend).f1('uFrame', this.frameNo);
    acc.f1('uQuantum', this.format === 'half' ? 0 : 1 / 255).f1('uSrgb', this.format === 'srgb' ? 1 : 0);
    // Reprojected at the depth most of the light comes from: half an absorption length into the slab.
    const z = Math.min(c.depth, -c.near + 0.5 / Math.max(1e-5, c.absorb));
    acc.f1('uSpread', (c.focal + z) / c.focal).f2('uTexel', 1 / t.width, 1 / t.height);
    gl.uniform4fv(acc.loc('uView'), frame.view);
    gl.uniform4fv(acc.loc('uPrevView'), this.fresh ? frame.view : this.prevView);
    prev.sample(1);
    t.sample(0);
    drawFullscreen(gl, this.vao!);
    this.history = [next, prev];
    this.prevView.set(frame.view);
    this.fresh = false;

    frame.scene.bind();
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    this.comp.use().i1('uSrc', 0);
    next.sample(0);
    drawFullscreen(gl, this.vao!);
  }

  dispose(): void {
    const gl = this.gl;
    if (!gl) return;
    this.march?.dispose();
    this.accum?.dispose();
    this.comp?.dispose();
    for (const tex of [this.cells, this.noise, this.charge]) if (tex) gl.deleteTexture(tex);
    this.target?.dispose();
    for (const h of this.history ?? []) h.dispose();
    this.march = this.accum = this.comp = null;
    this.cells = this.noise = this.charge = null;
    this.target = this.history = null;
  }
}

function texture3d(gl: WebGL2RenderingContext, internal: number, format: number, data: Uint8Array): WebGLTexture | null {
  const tex = gl.createTexture();
  if (!tex) return null;
  bindTexture(gl, 0, tex, gl.TEXTURE_3D);
  gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
  gl.texImage3D(gl.TEXTURE_3D, 0, internal, NOISE_SIZE, NOISE_SIZE, NOISE_SIZE, 0, format, gl.UNSIGNED_BYTE, data);
  gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  for (const w of [gl.TEXTURE_WRAP_S, gl.TEXTURE_WRAP_T, gl.TEXTURE_WRAP_R]) gl.texParameteri(gl.TEXTURE_3D, w, gl.REPEAT);
  bindTexture(gl, 0, null, gl.TEXTURE_3D);
  return tex;
}
