<!--
  "While you were away": one card, one click.
-->
<script lang="ts">
  import { duration, energy } from '../../core/format';
  import Num from '../common/Num.svelte';
  import { game, ui } from '../store.svelte';

  const g = game();

  /** The card is modal: its one button takes focus, and Tab stays on it (Enter, Space or Esc continue). */
  function hold(node: HTMLButtonElement) {
    const prev = document.activeElement as HTMLElement | null;
    node.focus({ preventScroll: true });
    return () => {
      if (prev?.isConnected && prev !== document.body) prev.focus({ preventScroll: true });
    };
  }
</script>

{#if ui.offline}
  <div class="scrim">
    <div
      class="card"
      role="dialog"
      aria-modal="true"
      aria-label="While you were away"
      tabindex="-1"
      onkeydown={(e) => e.key === 'Tab' && e.preventDefault()}
    >
      <div class="label">While you were away</div>
      <div class="dur">{duration(ui.offline.seconds)}</div>
      <dl>
        {#if ui.offline.energy > 0}
          <dt>Energy</dt>
          <dd class="e"><Num parts={energy(ui.offline.energy, g.state.run.joules ? 'J' : 'eV', g.state.settings.notation)} sign="+" /></dd>
        {/if}
        {#each ui.offline.lines as line (line.label)}
          <dt>{line.label}</dt>
          <dd class="num">+{line.value}</dd>
        {/each}
      </dl>
      <button class="go" onclick={() => (ui.offline = null)} {@attach hold}>Continue</button>
    </div>
  </div>
{/if}

