/**
 * The Long Night's physics, kept pure for tests: how much light a disk around a spinning black hole
 * gives, how much of a hole's mass is spin that can be taken back, how long holes take to evaporate,
 * and which of Adams & Laughlin's five ages a time belongs to.
 */

/** Thorne's limit: a disk spins its hole up no further than this (Thorne 1974). */
export const SPIN_MAX = 0.998;

/**
 * Radius of the innermost stable circular orbit, in units of GM/c², for a prograde orbit around a
 * hole of spin a (Bardeen, Press & Teukolsky 1972): 6 for no spin, 1 for the maximum.
 */
export function iscoRadius(a: number): number {
  const s = Math.min(1, Math.max(0, a));
  const z1 = 1 + Math.cbrt(1 - s * s) * (Math.cbrt(1 + s) + Math.cbrt(1 - s));
  const z2 = Math.sqrt(3 * s * s + z1 * z1);
  return 3 + z2 - Math.sqrt(Math.max(0, (3 - z1) * (3 + z1 + 2 * z2)));
}

/**
 * Share of the rest energy of matter that a thin disk turns into light before the matter falls in:
 * the binding energy at the innermost stable orbit (Novikov & Thorne 1973). 5.7 % with no spin, about
 * 32 % at Thorne's limit, 42 % in principle at full spin.
 */
export function accretionEfficiency(a: number): number {
  return 1 - Math.sqrt(1 - 2 / (3 * iscoRadius(a)));
}

/**
 * Share of a hole's mass-energy held in its spin, which could in principle be taken back out
 * (Christodoulou 1970): 1 − M_irr/M. Up to 29 % at full spin.
 */
export function spinEnergyShare(a: number): number {
  const s = Math.min(1, Math.max(0, a));
  return 1 - Math.sqrt((1 + Math.sqrt(1 - s * s)) / 2);
}

/**
 * Hawking evaporation time in years for a hole of `suns` solar masses: ∝ M³, about 10⁶⁷ years for
 * one Sun (published estimates range from 10⁶⁶ to 10⁶⁷).
 */
export function hawkingYears(suns: number): number {
  return 1e67 * suns ** 3;
}

/** The cosmological decade of a time in years: η = log₁₀(t / 1 yr) (Adams & Laughlin 1997). */
export function decade(years: number): number {
  return Math.log10(years);
}

export type Age = 'primordial' | 'stelliferous' | 'degenerate' | 'blackhole' | 'dark';

/** Adams & Laughlin's five ages by cosmological decade. */
export function ageOf(eta: number): Age {
  if (eta < 6) return 'primordial';
  if (eta < 15) return 'stelliferous';
  if (eta < 40) return 'degenerate';
  if (eta < 100) return 'blackhole';
  return 'dark';
}

/** What a star particle is at a given step of the era (index into NightEra's steps). */
export const enum Kind {
  /** An ordinary old star (Sun-like or smaller). */
  Star,
  /** A red dwarf: the longest-lived stars. */
  Red,
  /** A red dwarf near its end, heated into a blue dwarf (predicted, never observed). */
  Blue,
  /** A white dwarf, still warm. */
  White,
  /** A neutron star. */
  Neutron,
  /** A brown dwarf: too small ever to have fused hydrogen. */
  Brown,
  /** A white dwarf cooled to the background: a black dwarf. */
  Black,
}

/** Whether a kind still makes its own light by fusion (it is torn apart if a hole draws it in). */
export function shines(k: Kind): boolean {
  return k === Kind.Star || k === Kind.Red || k === Kind.Blue;
}

/**
 * What a star particle with a fixed random draw `u` (0..1) has become by `step`. The mix follows the
 * steps: old stars → red dwarfs (10¹² yr) → blue dwarfs (10¹³) → dead stars (10¹⁴): white dwarfs,
 * neutron stars and brown dwarfs → white dwarfs cooled to black dwarfs (10¹⁵).
 */
export function kindAt(step: number, u: number): Kind {
  if (step <= 0) return u < 0.3 ? Kind.Star : u < 0.92 ? Kind.Red : u < 0.96 ? Kind.White : Kind.Brown;
  if (step === 1) return u < 0.88 ? Kind.Red : u < 0.95 ? Kind.White : u < 0.97 ? Kind.Neutron : Kind.Brown;
  if (step === 2) return u < 0.6 ? Kind.Blue : u < 0.88 ? Kind.Red : u < 0.95 ? Kind.White : u < 0.97 ? Kind.Neutron : Kind.Brown;
  if (step === 3) return u < 0.82 ? Kind.White : u < 0.86 ? Kind.Neutron : Kind.Brown;
  return u < 0.82 ? Kind.Black : u < 0.86 ? Kind.Neutron : Kind.Brown;
}

/** Mass in Suns of one real object of a kind (for the scale of what a particle stands for). */
export function typicalMass(k: Kind): number {
  switch (k) {
    case Kind.Star:
      return 0.7;
    case Kind.Red:
    case Kind.Blue:
      return 0.15;
    case Kind.White:
    case Kind.Black:
      return 0.6;
    case Kind.Neutron:
      return 1.4;
    default:
      return 0.05;
  }
}
