/**
 * Dark Ages → Cosmic Dawn simulation.
 *
 * Gas parcels drift and fall into dark-matter wells (placed at the peaks of this universe's
 * microwave background) and toward the cursor while the player holds. Parcels merge into clumps;
 * merging compresses and heats a clump (the faster they meet, the hotter), and cooling (molecular
 * hydrogen, later metals) lets it radiate that heat away: the Dark Ages' only light. Radiation can't
 * cool gas below the afterglow's temperature, so the floor falls step by step. Until cosmic dawn no
 * halo is massive enough to make the H₂ a collapse needs; from then on a clump whose mass exceeds its
 * Jeans mass (∝ T^1.5) collapses into a protostar and ignites. First stars are huge, blue-white and
 * short-lived; their ultraviolet grows ionized bubbles, which recombine once their stars are gone
 * (fast early on, when the gas is dense, slowly later), and their Lyman-Werner light breaks up the
 * H₂ in clouds nearby. Their deaths leave black holes (or nothing, in the pair-instability window)
 * that sink into the halos and merge, and scatter metals that make later clumps cool faster and form
 * smaller stars.
 */
import type { EraModule, OfflineReport, PointerInfo, StockView } from '../../core/era';
import type { Game } from '../../core/game';
import { count, toText } from '../../core/format';
import { RateMeter } from '../../core/meter';
import type { RGB } from '../../render/color';
import { Fx, FxPool } from '../../render/fx';
import type { Renderer } from '../../render/renderer';
import { Grid } from '../../physics/grid';
import { Particles } from '../../physics/particles';
import type { DawnBgParams } from './background';
import { DawnLook } from './look';

const GAS = 0;
const CLUMP = 1;
const PROTO = 2;
const STAR = 3;
const BH = 4;
const METAL = 5;

const F_HOT_WARNED = 1;

/** Jeans mass in parcel units: M_J = K_JEANS · T^1.5. */
const K_JEANS = 0.135;
const T_GAS = 40;
/**
 * The coldest gas can get at each epoch step: radiation can't cool it below the afterglow, which
 * fades from 3000 K to under 20 K across the era (sim kelvin, compressed). A colder floor means a
 * smaller Jeans mass.
 */
const T_MIN = [26, 15, 11, 8, 7.5, 7, 6.5];
/** The step from which halos are massive enough to make the H₂ a collapse needs: cosmic dawn. */
const DAWN_STEP = 3;
/** Heating per merger from the clouds' relative speed: kinetic energy turns into heat (K per (unit/s)²). */
const K_SHOCK = 1.1e-3;
/** Inside an ionized bubble, Lyman-Werner light breaks up H₂: primordial gas cools this much slower. */
const LW_COOL = 0.35;
/**
 * At most this much of a collapsing cloud (in parcels) ends up in its star. The newborn star's light
 * blows the rest out of its small halo: the first stars formed from a sliver of their clouds.
 */
const CORE_UNITS = 26;
/** Photoheated gas blown out of a halo by a newborn star (sim kelvin). */
const T_BLOWN = 70;
/**
 * How long an ionized bubble lasts once its stars are gone, per epoch step (seconds): the gas is
 * dense early on and recombines fast; the universe thins out and later bubbles persist.
 */
const T_REC = [8, 8, 8, 14, 30, 60, 240];
/** Radius of the ionized bubble one star keeps lit (world units). */
const R_ION = 44;
/**
 * Halo mergers. The nearest two halos start to fall together on their own every HALO_GAP seconds on
 * average (at least HALO_GAP_MIN; both ÷ Hierarchical Merging). HALO_FALL is their pull on each other
 * and HALO_HAND the hand's pull on a halo (world units/s²). Halos closer than MERGE_D merge; clumps
 * within MERGE_R are shock-heated by up to MERGE_HEAT kelvin for two halos of unit depth.
 */
const HALO_GAP = 60;
const HALO_GAP_MIN = 30;
const HALO_FALL = 45;
const HALO_HAND = 260;
const MERGE_D = 46;
const MERGE_R = 300;
const MERGE_HEAT = 10;
/** Helium mass fraction of our universe, the reference for first-star fuel. */
const YP_OURS = 0.245;
/** Energy radiated per parcel·kelvin of cooling, and starlight per second for a 50-Sun star (eV, weight 1). */
const E_COOL = 1.6e5;
const L0 = 3e7;

/** How far past the play area the look's field textures reach (world units). */
const FIELD_MARGIN = 80;

/** Stable per-particle random in [0, 1), for visual variety that survives compaction. */
function hash(id: number, k: number): number {
  const s = Math.sin(id * 12.9898 + k * 78.233) * 43758.5453;
  return s - Math.floor(s);
}

export interface DawnState {
  stars: number;
  blackHoles: number;
  metals: number;
  reion: number;
  firstStar: number;
  /** Ionized regions: `n` counts the stars that have lit each one (its volume grows with their light). */
  bubbles: { id: number; x: number; y: number; r: number; n: number }[];
  nextBubble: number;
  everGathered: boolean;
  everIgnited: boolean;
  starRate: number;
  haloClock: number;
  /** Halo mergers so far. */
  mergers: number;
}

function defaults(): DawnState {
  return {
    stars: 0,
    blackHoles: 0,
    metals: 0,
    reion: 0,
    firstStar: 0,
    bubbles: [],
    nextBubble: 1,
    everGathered: false,
    everIgnited: false,
    starRate: 0,
    haloClock: 30,
    mergers: 0,
  };
}

interface Well {
  x: number;
  y: number;
  s: number;
  vx: number;
  vy: number;
}

export class DawnEra implements EraModule {
  private readonly p = new Particles(900);
  private readonly grid = new Grid(40, 900);
  private readonly fx = new FxPool(800);
  private readonly s: DawnState;
  private readonly bgParams: DawnBgParams;
  /** How it all looks (version 2): the gas medium, the lensing of dark matter, the stars, the effects. */
  private readonly look = new DawnLook();
  /** Cosmetic expanding shells (supernova ejecta, ionization fronts): thin rings that decelerate. */
  private shells: { x: number; y: number; v: number; age: number; life: number; c: RGB; th: number }[] = [];
  private wells: Well[] = [];
  private halfW = 889;
  private halfH = 500;
  private t = 0;
  private idle = 0;

  private pull = 1;
  private cool = 0.05;
  private inflow = 1.2;
  private jeansMult = 1;
  private lumMult = 1;
  private bubble = 1;
  private fragment = 0;
  private yields = 1;
  private trigger = 0;
  private metalCool = 3;
  private web = 0.25;
  private gather = 1;
  private direct = 0;
  private mergeRate = 1;
  /**
   * For renderers: the two halos falling together on their own (null when none), and the latest
   * halo merger (where, when in era seconds `t`, and how strong: `mu` is 1 for two unit halos).
   * The halos themselves are `wells`, which now move (vx, vy) while they fall or are held.
   */
  drift: [Well, Well] | null = null;
  lastMerger: { x: number; y: number; t: number; mu: number } | null = null;
  /** First-star fuel from this universe's helium fraction: brightness and lifetime factors. */
  private fuelLum = 1;
  private fuelLife = 1;
  /** No collapse may start before this time: the first star gets its moment, then the rest follow. */
  private nextCollapse = 0;

  private inflowAcc = 0;
  private pDown = false;
  private pX = 0;
  private pY = 0;
  private gatherSound = 0;
  private reionClock = 0;
  private readonly starMeter = new RateMeter(30);
  private intro = 0;
  private unsub: (() => void)[] = [];

  private finaleT = -1;
  private finaleDone: (() => void) | null = null;
  private tallied = false;

  constructor(private readonly g: Game) {
    const run = g.state.run;
    this.s = (run.eras.dawn as DawnState | undefined) ?? defaults();
    // Saves from before halo mergers were counted.
    this.s.mergers ??= 0;
    run.eras.dawn = this.s;
    this.bgParams = { glow: 1, web: 0.25, pulse: 0, finale: 0, rect: new Float32Array(4) };
    this.setFieldRect();
    this.setFuel(run.legacy.yp);
  }

  /**
   * Helium raises the mean mass per particle, μ = 1 / (2X + 3Y/4) for ionized gas, and a star's
   * luminosity goes roughly as μ⁴; its hydrogen fuel goes as X. More helium: brighter, shorter-lived stars.
   */
  private setFuel(yp: number | undefined): void {
    const Y = Math.min(0.6, Math.max(0, yp ?? YP_OURS));
    const mu = (y: number) => 1 / (2 * (1 - y) + 0.75 * y);
    this.fuelLum = (mu(Y) / mu(YP_OURS)) ** 4;
    this.fuelLife = (1 - Y) / (1 - YP_OURS) / this.fuelLum;
  }

  // ───────────────────────────────────────── lifecycle

  enter(fresh: boolean): void {
    const g = this.g;
    if (g.renderer) this.look.attach(g.renderer, g.state.run.artifacts.cmb);
    this.refreshStats();
    this.unsub.push(g.stats.onChange(() => this.refreshStats()));
    this.starMeter.reset(this.s.starRate);
    this.syncStepFlags();
    this.buildWells();
    this.bgParams.glow = Math.max(0, 1 - g.state.run.step / 2);
    const n = fresh ? 240 : 200;
    for (let k = 0; k < n; k++) this.spawnGas(true);
    if (fresh) this.intro = 1.6;
  }

  exit(): void {
    if (this.g.renderer) this.look.detach(this.g.renderer);
    for (const u of this.unsub) u();
    this.unsub = [];
  }

  resize(halfW: number, halfH: number): void {
    const sx = halfW / this.halfW;
    this.halfW = halfW;
    this.halfH = halfH;
    this.grid.setBounds(-halfW - 120, -halfH - 120, halfW + 120, halfH + 120);
    for (const w of this.wells) w.x *= sx;
    this.setFieldRect();
  }

  /** The world rectangle the background's field textures cover (the play area plus a margin). */
  private setFieldRect(): void {
    const rc = this.bgParams.rect;
    rc[0] = -this.halfW - FIELD_MARGIN;
    rc[1] = -this.halfH - FIELD_MARGIN;
    rc[2] = this.halfW + FIELD_MARGIN;
    rc[3] = this.halfH + FIELD_MARGIN;
  }

  private refreshStats(): void {
    const st = this.g.stats;
    this.pull = st.get('dawn.pull');
    this.cool = st.get('dawn.cool');
    this.inflow = st.get('dawn.inflow');
    this.jeansMult = st.get('dawn.jeansMult');
    this.lumMult = st.get('dawn.lumMult');
    this.bubble = st.get('dawn.bubble');
    this.fragment = st.get('dawn.fragment');
    this.yields = st.get('dawn.yields');
    this.trigger = st.get('dawn.trigger');
    this.metalCool = st.get('dawn.metalCool');
    this.web = st.get('dawn.web');
    this.gather = st.get('dawn.gather');
    this.direct = st.get('dawn.direct');
    this.mergeRate = st.get('dawn.mergeRate');
    this.bgParams.web = this.web;
  }

  private get step(): number {
    return this.g.state.run.step;
  }

  private get weight(): number {
    return 1e25 * 10 ** this.step;
  }

  /** How many real stars (or remnants) one simulated star stands for. */
  private get starWeight(): number {
    return 1e3 * 10 ** this.step;
  }

  private syncStepFlags(): void {
    for (let i = 1; i <= 6; i++) this.g.setFlag(`dawn.step${i}`, this.step >= i);
  }

  /** Dark-matter wells at the peaks of this universe's microwave background. */
  private buildWells(): void {
    const peaks = this.g.state.run.artifacts.peaks;
    this.wells = [];
    if (peaks) {
      for (const part of peaks.split(';').slice(0, 10)) {
        const [x, y, s] = part.split(',').map(Number);
        if ([x, y, s].every(Number.isFinite)) this.wells.push({ x: x * this.halfW * 0.92, y: y * this.halfH * 0.92, s: 0.4 + 0.6 * s, vx: 0, vy: 0 });
      }
    }
    // Without a recorded map (a fresh test, an old save), the ripples are still there, just unknown.
    const rng = this.g.sim;
    while (this.wells.length < 6) {
      this.wells.push({ x: rng.range(-this.halfW, this.halfW) * 0.8, y: rng.range(-this.halfH, this.halfH) * 0.8, s: rng.range(0.4, 1), vx: 0, vy: 0 });
    }
  }

  private spawnGas(anywhere: boolean): number {
    const rng = this.g.sim;
    let x: number;
    let y: number;
    let vx = rng.range(-12, 12);
    let vy = rng.range(-12, 12);
    if (anywhere) {
      x = rng.range(-this.halfW, this.halfW);
      y = rng.range(-this.halfH, this.halfH);
    } else {
      // Along a filament from the edge toward a well.
      const w = this.wells[rng.int(this.wells.length)];
      const side = rng.int(4);
      x = side < 2 ? rng.range(-this.halfW, this.halfW) : side === 2 ? -this.halfW - 20 : this.halfW + 20;
      y = side < 2 ? (side === 0 ? -this.halfH - 20 : this.halfH + 20) : rng.range(-this.halfH, this.halfH);
      const d = Math.hypot(w.x - x, w.y - y) || 1;
      vx = ((w.x - x) / d) * 50;
      vy = ((w.y - y) / d) * 50;
    }
    const i = this.p.spawn(GAS, x, y, vx, vy, 5, 1);
    if (i >= 0) this.p.a[i] = T_GAS;
    return i;
  }

  // ───────────────────────────────────────── clumps and stars

  private clumpRadius(m: number): number {
    return 9 + 5.5 * Math.cbrt(m);
  }

  private jeansMass(T: number): number {
    return K_JEANS * this.jeansMult * T ** 1.5;
  }

  private get tMin(): number {
    return T_MIN[Math.min(T_MIN.length - 1, this.step)];
  }

  private inBubble(x: number, y: number): boolean {
    for (const b of this.s.bubbles) if ((x - b.x) ** 2 + (y - b.y) ** 2 < b.r * b.r) return true;
    return false;
  }

  /**
   * Merge `j` (gas or clump) into clump `i`: mass adds, compression heats, and so does the collision
   * itself (the kinetic energy of their relative motion, ½μv², spread over the merged mass).
   */
  private absorb(i: number, j: number): void {
    const p = this.p;
    const mi = p.w[i];
    const mj = p.w[j];
    const m = mi + mj;
    const v2 = (p.vx[i] - p.vx[j]) ** 2 + (p.vy[i] - p.vy[j]) ** 2;
    const shock = Math.min(80, (K_SHOCK * v2 * mi * mj) / (m * m));
    const heat = (34 * mj) / Math.max(1, m) + (p.kind[j] === CLUMP ? 6 : 0) + shock;
    p.a[i] = (p.a[i] * mi + p.a[j] * mj) / m + heat;
    p.vx[i] = (p.vx[i] * mi + p.vx[j] * mj) / m;
    p.vy[i] = (p.vy[i] * mi + p.vy[j] * mj) / m;
    p.x[i] = (p.x[i] * mi + p.x[j] * mj) / m;
    p.y[i] = (p.y[i] * mi + p.y[j] * mj) / m;
    p.w[i] = m;
    p.r[i] = this.clumpRadius(m);
    if (p.sub[j]) p.sub[i] = 1;
    p.kill(j);
    if (p.kind[j] === CLUMP || mj > 2) this.g.sfx('dawn.merge', p.x[i]);
  }

  private collapse(i: number): void {
    const p = this.p;
    p.kind[i] = PROTO;
    p.life[i] = 1.4;
    // The very first collapse gets the sky to itself; after that, stars can follow each other quickly.
    this.nextCollapse = this.t + (this.s.everIgnited ? 0.2 : 3.2);
    p.flags[i] &= ~F_HOT_WARNED;
    this.fx.spawn(Fx.Ring, p.x[i], p.y[i], 1.3, p.r[i] * 2.2, 0.5, 0.6, 0.9, -p.r[i] * 1.4);
    this.fx.spawn(Fx.Ring, p.x[i], p.y[i], 1.0, p.r[i] * 3.2, 1.1, 0.8, 0.35, -p.r[i] * 2.6);
  }

  private ignite(i: number): void {
    const p = this.p;
    const g = this.g;
    const rng = g.sim;
    const enriched = p.sub[i] === 1;
    const units = Math.min(p.w[i], CORE_UNITS);
    const rest = p.w[i] - units;
    const base = units * 4 * rng.range(0.6, 1.8) * (enriched ? 0.25 : 1);
    let stars = 0;
    for (let k = 0; k < p.n; k++) if (p.kind[k] === STAR && !p.isDead(k)) stars++;
    const extra = stars > 140 ? 0 : Math.floor(this.fragment) + (rng.chance(this.fragment % 1) ? 1 : 0);
    const x = p.x[i];
    const y = p.y[i];
    p.kill(i);
    if (rest >= 1) this.blowOut(x, y, rest);
    for (let k = 0; k <= extra; k++) {
      const m = k === 0 ? base : base * rng.range(0.4, 0.8);
      const a = rng.angle();
      const off = k === 0 ? 0 : 18 + rng.range(0, 14);
      const s = p.spawn(STAR, x + Math.cos(a) * off, y + Math.sin(a) * off, 0, 0, 8, m, enriched ? 1 : 0);
      if (s < 0) break;
      p.life[s] = Math.max(8, 38 * Math.pow(50 / Math.max(5, m), 0.45) * this.fuelLife);
      p.b[s] = 6;
      p.a[s] = this.bubbleFor(p.x[s], p.y[s]);
      this.s.stars += this.starWeight;
      this.starMeter.add(this.starWeight);
    }
    const r = g.renderer;
    r?.addFlash(this.s.everIgnited ? 0.12 : 0.45);
    r?.shock(x, y, this.s.everIgnited ? 0.35 : 0.9, 0.8, 1.4);
    r?.camera.addTrauma(this.s.everIgnited ? 0.05 : 0.25);
    this.igniteFx(x, y, !this.s.everIgnited);
    g.sfx('dawn.ignite', x);
    if (!this.s.everIgnited) {
      this.s.everIgnited = true;
      this.s.firstStar = g.state.run.time;
      g.setFlag('dawn.firstStar');
      g.discover('pop3');
      g.toast('The first star. For the first time in a hundred million years, something shines.', 'milestone');
    }
  }

  /** What a newborn star's light pushes out of its cloud: a few hot wisps fly off, the rest leaves the halo for good. */
  private blowOut(x: number, y: number, mass: number): void {
    const p = this.p;
    const rng = this.g.sim;
    const n = Math.min(14, Math.floor(mass));
    for (let k = 0; k < n; k++) {
      const a = rng.angle();
      const v = rng.range(200, 380);
      const gi = p.spawn(GAS, x + Math.cos(a) * 14, y + Math.sin(a) * 14, Math.cos(a) * v, Math.sin(a) * v, 5, 1);
      if (gi >= 0) p.a[gi] = T_BLOWN;
    }
    this.fx.spawn(Fx.Puff, x, y, 2.2, 90, 0.3, 0.1, 0.18, 120);
  }

  /** First light: a white-hot flash, starlight rays, and the pink ionization front setting out. */
  private igniteFx(x: number, y: number, first: boolean): void {
    const fx = this.fx;
    const rng = this.g.fx;
    const s = first ? 1.6 : 1;
    fx.spawn(Fx.Flash, x, y, 0.8 * s, 70 * s, 4, 4.2, 5, 120 * s);
    if (first) fx.spawn(Fx.Flash, x, y, 2.4, 40, 2.2, 2.3, 3, 40);
    if (first) fx.spawn(Fx.Ring, x, y, 0.7, 16, 1.6, 1.8, 2.4, 340);
    else this.shell(x, y, 300, 0.45, [1.2, 1.3, 1.6], 0.012);
    this.shell(x, y, first ? 150 : 80, first ? 2.6 : 1.4, first ? [1.5, 0.42, 0.78] : [0.8, 0.22, 0.42], 0.018);
    const rays = first ? 36 : 12;
    for (let k = 0; k < rays; k++) {
      const a = rng.angle();
      const v = rng.range(220, 560) * s;
      fx.spawn(Fx.Spark, x, y, rng.range(0.35, 0.8) * s, 2.6, 1.8, 2, 2.6, 0, Math.cos(a) * v, Math.sin(a) * v, 2.2);
    }
    fx.spawn(Fx.Puff, x, y, 2.5 * s, 50 * s, 0.22, 0.12, 0.2, 40 * s);
  }

  private shell(x: number, y: number, v: number, life: number, c: RGB, th: number): void {
    if (this.shells.length >= 48) this.shells.shift();
    this.shells.push({ x, y, v, age: 0, life, c, th });
  }

  /** A supernova: blinding core, a fast white shell, a slower shell of fresh metals, and the glowing remnant. */
  private supernovaFx(x: number, y: number, pis: boolean): void {
    const fx = this.fx;
    const rng = this.g.fx;
    const s = pis ? 1.35 : 1;
    fx.spawn(Fx.Flash, x, y, 0.9 * s, 110 * s, 5, 4.4, 3.6, 220 * s);
    fx.spawn(Fx.Flash, x, y, 0.35, 30, 6, 6, 6, 60);
    this.shell(x, y, 520 * s, 0.6, [1.8, 1.65, 1.5], 0.01);
    this.shell(x, y, 190 * s, 1.3 * s, [0.75, 0.48, 0.17], 0.014);
    this.shell(x, y, 120 * s, 2 * s, [0.2, 0.5, 0.45], 0.018);
    for (let k = 0; k < 26; k++) {
      const a = rng.angle();
      const v = rng.range(160, 480) * s;
      const teal = rng.chance(0.4);
      fx.spawn(Fx.Spark, x, y, rng.range(0.5, 1.1), 3, teal ? 0.6 : 2, teal ? 1.6 : 1.3, teal ? 1.4 : 0.5, 0, Math.cos(a) * v, Math.sin(a) * v, 1.6);
    }
    fx.spawn(Fx.Puff, x, y, 3, 60, 0.5, 0.35, 0.25, 70);
    fx.spawn(Fx.Puff, x, y, 6 * s, 70, 0.16, 0.07, 0.12, 26);
  }

  /**
   * The bubble a newborn star lights: the one whose middle it was born in (stars in one halo feed one
   * bubble), otherwise a new one of its own. Overlapping bubbles together make one ionized region.
   * Returns the bubble's stable id.
   */
  private bubbleFor(x: number, y: number): number {
    const bs = this.s.bubbles;
    let best: (typeof bs)[number] | null = null;
    let bd = Infinity;
    for (const b of bs) {
      const d = Math.hypot(x - b.x, y - b.y);
      if (d < Math.max(40, 0.35 * b.r) && d < bd) {
        best = b;
        bd = d;
      }
    }
    if (best) {
      best.n++;
      return best.id;
    }
    const id = this.s.nextBubble++;
    bs.push({ id, x, y, r: 6, n: 1 });
    if (bs.length > 120) {
      let small = 0;
      bs.forEach((b, k) => {
        if (b.r < bs[small].r) small = k;
      });
      bs.splice(small, 1);
    }
    return id;
  }

  private die(i: number): void {
    const p = this.p;
    const g = this.g;
    const rng = g.sim;
    const m = p.w[i];
    const x = p.x[i];
    const y = p.y[i];
    p.kill(i);
    const pis = m >= 140 && m <= 260;
    const metals = (pis ? 2.5 : 1) * this.yields;
    const burst = L0 * Math.pow(m / 50, 1.4) * 12 * this.yields * this.weight * this.lumMult * this.fuelLum;
    g.gain(burst, x, y);
    this.s.metals += metals * this.weight;
    let debris = 0;
    for (let k = 0; k < p.n; k++) if (p.kind[k] === METAL && !p.isDead(k)) debris++;
    const shards = debris > 260 ? 2 : Math.round(10 * Math.min(2.5, metals));
    for (let k = 0; k < shards; k++) {
      const a = rng.angle();
      const s = rng.range(90, 260);
      const mi = p.spawn(METAL, x, y, Math.cos(a) * s, Math.sin(a) * s, 4, 1);
      if (mi >= 0) p.life[mi] = rng.range(10, 18);
    }
    this.supernovaFx(x, y, pis);
    const r = g.renderer;
    r?.shock(x, y, 0.8, 1, 1.4);
    r?.addFlash(0.18);
    r?.addAberration(0.003);
    r?.camera.addTrauma(0.2);
    g.sfx('dawn.sn', x);
    g.setFlag('dawn.firstDeath');
    g.discover('first-metals');
    // The shock pushes gas away and, with Triggered Collapse, squeezes nearby clumps.
    for (let j = 0; j < p.n; j++) {
      if (p.isDead(j)) continue;
      const dx = p.x[j] - x;
      const dy = p.y[j] - y;
      const d = Math.hypot(dx, dy) || 1;
      if (d > 320) continue;
      const k = (1 - d / 320) * 220;
      if (p.kind[j] === GAS || p.kind[j] === METAL) {
        p.vx[j] += (dx / d) * k;
        p.vy[j] += (dy / d) * k;
      } else if (p.kind[j] === CLUMP && this.trigger > 0) {
        p.a[j] = Math.max(this.tMin, p.a[j] * (1 - this.trigger * (1 - d / 320)));
      }
    }
    if (pis) {
      g.discover('pair-instability');
    } else if (m >= 25) {
      const b = p.spawn(BH, x, y, 0, 0, 6, m);
      if (b >= 0) p.life[b] = Infinity;
      this.s.blackHoles += this.starWeight;
      if (g.discover('first-bh')) g.toast('A black hole: what is left of the first giant stars.', 'quiet');
      g.sfx('dawn.bh', x);
    }
  }

  private updateReion(): void {
    const W = 48;
    const H = 27;
    let covered = 0;
    const bs = this.s.bubbles;
    for (let cy = 0; cy < H; cy++) {
      const y = -this.halfH + ((cy + 0.5) / H) * 2 * this.halfH;
      for (let cx = 0; cx < W; cx++) {
        const x = -this.halfW + ((cx + 0.5) / W) * 2 * this.halfW;
        for (const b of bs) {
          if ((x - b.x) ** 2 + (y - b.y) ** 2 < b.r * b.r) {
            covered++;
            break;
          }
        }
      }
    }
    const before = this.s.reion;
    this.s.reion = covered / (W * H);
    // Bubbles come and go, so the halfway mark is announced once.
    if (before < 0.5 && this.s.reion >= 0.5 && !this.g.flag('dawn.half')) {
      this.g.setFlag('dawn.half');
      this.g.sfx('dawn.milestone');
      this.g.toast('Half the universe is ionized again.', 'quiet');
    }
  }

  // ───────────────────────────────────────── simulation

  update(dt: number): void {
    const g = this.g;
    const p = this.p;
    const rng = g.sim;
    this.t += dt;
    this.idle += dt;
    if (this.intro > 0) this.intro = Math.max(0, this.intro - dt);
    const inFinale = this.finaleT >= 0;
    if (inFinale) this.updateFinale(dt);

    if (!inFinale) {
      this.inflowAcc += this.inflow * dt;
      while (this.inflowAcc >= 1) {
        this.inflowAcc -= 1;
        if (p.n < p.cap - 80) this.spawnGas(false);
      }
      this.updateHalos(dt);
    }
    // The afterglow redshifts out of the visible within the first minute or two.
    if (this.bgParams.glow > 0.12) this.bgParams.glow = Math.max(0.12, this.bgParams.glow - dt * 0.009);

    this.grid.build(p);
    const reach = 320 * this.gather;
    let cooling = 0;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const kind = p.kind[i];
      p.age[i] += dt;
      if (kind === STAR) continue;
      if (kind === BH) {
        // Heavy and dragged by dynamical friction, a black hole sinks to the bottom of its halo.
        let ax = 0;
        let ay = 0;
        for (const w of this.wells) {
          const dx = w.x - p.x[i];
          const dy = w.y - p.y[i];
          const d = Math.hypot(dx, dy) + 1;
          const f = (w.s * 9000) / (d + 90);
          ax += (dx / d) * f;
          ay += (dy / d) * f;
        }
        p.vx[i] = (p.vx[i] + ax * dt) * Math.exp(-2.5 * dt);
        p.vy[i] = (p.vy[i] + ay * dt) * Math.exp(-2.5 * dt);
        p.x[i] += p.vx[i] * dt;
        p.y[i] += p.vy[i] * dt;
        continue;
      }
      let ax = 0;
      let ay = 0;
      // Wells pull gas, clumps and metals in.
      for (const w of this.wells) {
        const dx = w.x - p.x[i];
        const dy = w.y - p.y[i];
        const d = Math.hypot(dx, dy) + 1;
        const f = (w.s * this.pull * 1300) / (d + 90);
        ax += (dx / d) * f;
        ay += (dy / d) * f;
      }
      // The cursor is a mass concentration while held.
      if (this.pDown && !inFinale && (kind === GAS || kind === CLUMP || kind === METAL)) {
        const dx = this.pX - p.x[i];
        const dy = this.pY - p.y[i];
        const d = Math.hypot(dx, dy) + 1;
        if (d < reach) {
          const f = ((kind === CLUMP ? 1400 : 2600) * (1 - d / reach)) / (1 + d / 120);
          ax += (dx / d) * f;
          ay += (dy / d) * f;
        }
      }
      const drag = kind === CLUMP ? 1.4 : 0.9;
      p.vx[i] = (p.vx[i] + ax * dt) * Math.exp(-drag * dt);
      p.vy[i] = (p.vy[i] + ay * dt) * Math.exp(-drag * dt);
      p.x[i] += p.vx[i] * dt;
      p.y[i] += p.vy[i] * dt;
      if (kind === METAL) {
        p.life[i] -= dt;
        if (p.life[i] <= 0) p.kill(i);
      }
    }

    // Merging and enrichment.
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const kind = p.kind[i];
      if (kind === BH) {
        // Two black holes at the bottom of one halo spiral together and merge.
        this.grid.near(p.x[i], p.y[i], 16, (j) => {
          if (j <= i || p.isDead(i) || p.isDead(j) || p.kind[j] !== BH) return;
          if ((p.x[j] - p.x[i]) ** 2 + (p.y[j] - p.y[i]) ** 2 > 196) return;
          const m = p.w[i] + p.w[j];
          p.x[i] = (p.x[i] * p.w[i] + p.x[j] * p.w[j]) / m;
          p.y[i] = (p.y[i] * p.w[i] + p.y[j] * p.w[j]) / m;
          p.w[i] = m;
          p.r[i] = Math.min(14, Math.max(p.r[i], p.r[j]) + 1);
          p.kill(j);
          this.fx.spawn(Fx.Ring, p.x[i], p.y[i], 0.9, 40, 0.5, 0.35, 0.8, -36);
        });
        continue;
      }
      if (kind !== GAS && kind !== CLUMP && kind !== METAL) continue;
      const ri = kind === CLUMP ? p.r[i] : 6;
      this.grid.near(p.x[i], p.y[i], Math.max(ri, 10) + 12, (j) => {
        if (j === i || p.isDead(i) || p.isDead(j)) return;
        const kj = p.kind[j];
        const d2 = (p.x[j] - p.x[i]) ** 2 + (p.y[j] - p.y[i]) ** 2;
        if (kind === METAL) {
          if ((kj === GAS || kj === CLUMP) && d2 < 400 && !p.sub[j]) {
            p.sub[j] = 1;
            p.life[i] -= 4;
            g.sfx('dawn.metal', p.x[j]);
          }
          return;
        }
        if (kj !== GAS && kj !== CLUMP) return;
        if (kind === GAS && kj === GAS) {
          if (j > i && d2 < 100) {
            p.kind[i] = CLUMP;
            p.r[i] = this.clumpRadius(1);
            this.absorb(i, j);
          }
          return;
        }
        if (kind === CLUMP) {
          const rj = kj === CLUMP ? p.r[j] : 5;
          const rr = (ri + rj) * (kj === CLUMP ? 0.7 : 0.9);
          if (d2 < rr * rr && (kj === GAS || p.w[i] >= p.w[j])) this.absorb(i, j);
        }
      });
    }

    // Clump thermodynamics: cool, radiate (that radiation is the Dark Ages' only income), collapse.
    const floor = this.tMin;
    const dawn = this.step >= DAWN_STEP && !inFinale;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const kind = p.kind[i];
      if (kind === CLUMP) {
        const h2 = p.sub[i] ? this.metalCool : this.inBubble(p.x[i], p.y[i]) ? LW_COOL : 1;
        const rate = this.cool * h2 * (1 + 0.02 * p.w[i]);
        const dT = (p.a[i] - floor) * (1 - Math.exp(-rate * dt));
        p.a[i] -= dT;
        cooling += dT * p.w[i];
        if (!dawn) continue;
        if (this.t >= this.nextCollapse && p.w[i] >= this.jeansMass(p.a[i]) && p.w[i] >= 4) {
          this.collapse(i);
          continue;
        }
        if (this.direct > 0 && p.w[i] > 40 && p.a[i] > 60 && rng.chance(0.15 * dt)) {
          this.directCollapse(i);
          continue;
        }
        if (!(p.flags[i] & F_HOT_WARNED) && p.w[i] > 0.75 * this.jeansMass(p.a[i]) && p.w[i] >= 4) {
          p.flags[i] |= F_HOT_WARNED;
          g.sfx('dawn.critical', p.x[i]);
        }
      } else if (kind === PROTO) {
        p.life[i] -= dt;
        if (p.life[i] <= 0) this.ignite(i);
      } else if (kind === STAR) {
        const m = p.w[i];
        const L = L0 * Math.pow(m / 50, 1.4) * this.lumMult * this.fuelLum * this.weight;
        g.gain(L * dt);
        // Its own ionization front, for the eye; the region it feeds grows below.
        p.b[i] = Math.min(46 * Math.pow(m / 50, 0.4), p.b[i] + 18 * dt);
        p.life[i] -= dt;
        if (p.life[i] <= 0 && !inFinale) this.die(i);
      }
    }
    if (cooling > 0) g.gain(cooling * E_COOL * this.weight);

    // Ionized regions: a Strömgren volume holds as many atoms as its light can keep ionized against
    // recombination, so radius ∝ n^(1/3), where n counts the stars lighting it over one recombination
    // time. That time is short early on, when the gas is dense, and grows as the universe thins out.
    const bs = this.s.bubbles;
    const fade = Math.exp(-dt / T_REC[Math.min(T_REC.length - 1, this.step)]);
    for (let k = bs.length - 1; k >= 0 && !inFinale; k--) {
      const b = bs[k];
      b.n *= fade;
      const target = R_ION * this.bubble * Math.cbrt(b.n);
      b.r += (target - b.r) * (1 - Math.exp(-(b.r < target ? 0.12 : 0.05) * dt));
      if (b.n < 0.05 && b.r < 4) bs.splice(k, 1);
    }

    this.reionClock -= dt;
    if (this.reionClock <= 0) {
      this.reionClock = 0.3;
      this.updateReion();
    }
    if (this.pDown && !inFinale) {
      this.gatherSound -= dt;
      if (this.gatherSound <= 0) {
        this.gatherSound = 0.5;
        g.sfx('dawn.gather', this.pX);
      }
    }

    p.compact();
    this.fx.update(dt);
    for (let k = this.shells.length - 1; k >= 0; k--) {
      const sh = this.shells[k];
      sh.age += dt;
      if (sh.age >= sh.life) this.shells.splice(k, 1);
    }
    this.starMeter.tick(dt);
    this.s.starRate = this.starMeter.rate;
    this.bgParams.pulse *= Math.exp(-dt * 2);
  }

  private directCollapse(i: number): void {
    const p = this.p;
    const g = this.g;
    const x = p.x[i];
    const y = p.y[i];
    const m = p.w[i] * 1500;
    p.kind[i] = BH;
    p.w[i] = m;
    p.r[i] = 9;
    p.life[i] = Infinity;
    this.s.blackHoles += this.starWeight * 3;
    this.fx.spawn(Fx.Ring, x, y, 1.2, 80, 0.6, 0.5, 1, -60);
    g.renderer?.shock(x, y, 0.6, -0.6, 1.2);
    g.sfx('dawn.bh', x);
    g.discover('direct-collapse');
  }

  /**
   * Halos grow by merging, small ones first (structure forms from the bottom up). Now and then the
   * nearest two fall together on their own; a hold tugs every halo in reach toward the cursor, so a
   * hold between two halos pulls them into one. Halos that meet merge (see mergeHalos).
   */
  private updateHalos(dt: number): void {
    const s = this.s;
    const ws = this.wells;
    s.haloClock -= dt;
    if (s.haloClock <= 0 && !this.drift && ws.length >= 3) {
      s.haloClock = Math.max(HALO_GAP_MIN, this.g.sim.exp(HALO_GAP)) / this.mergeRate;
      let best = Infinity;
      for (let i = 0; i < ws.length; i++)
        for (let j = i + 1; j < ws.length; j++) {
          const d = Math.hypot(ws[i].x - ws[j].x, ws[i].y - ws[j].y);
          if (d < best) {
            best = d;
            this.drift = [ws[i], ws[j]];
          }
        }
    }
    if (this.drift && !(ws.includes(this.drift[0]) && ws.includes(this.drift[1]))) this.drift = null;
    const reach = 320 * this.gather;
    for (const w of ws) {
      let ax = 0;
      let ay = 0;
      if (this.drift && (w === this.drift[0] || w === this.drift[1])) {
        const o = w === this.drift[0] ? this.drift[1] : this.drift[0];
        const dx = o.x - w.x;
        const dy = o.y - w.y;
        const d = Math.hypot(dx, dy) || 1;
        ax += (dx / d) * HALO_FALL * (0.5 + o.s);
        ay += (dy / d) * HALO_FALL * (0.5 + o.s);
      }
      if (this.pDown) {
        // Dark matter is far heavier than the gas: the hand moves a halo slowly.
        const dx = this.pX - w.x;
        const dy = this.pY - w.y;
        const d = Math.hypot(dx, dy) || 1;
        if (d < reach && d > 6) {
          const f = (HALO_HAND * (1 - d / reach)) / (1 + d / 200);
          ax += (dx / d) * f;
          ay += (dy / d) * f;
        }
      }
      w.vx = (w.vx + ax * dt) * Math.exp(-1.6 * dt);
      w.vy = (w.vy + ay * dt) * Math.exp(-1.6 * dt);
      w.x = Math.max(-this.halfW * 0.95, Math.min(this.halfW * 0.95, w.x + w.vx * dt));
      w.y = Math.max(-this.halfH * 0.95, Math.min(this.halfH * 0.95, w.y + w.vy * dt));
    }
    for (let i = 0; i < ws.length; i++)
      for (let j = i + 1; j < ws.length; j++)
        if ((ws[i].x - ws[j].x) ** 2 + (ws[i].y - ws[j].y) ** 2 < MERGE_D * MERGE_D) {
          this.mergeHalos(i, j);
          return;
        }
  }

  /**
   * Two halos become one deeper halo. The gas around it falls in faster and is shock-heated on the
   * way (virial shocks), so every clump nearby glows hot and shines the heat away as it cools; fresh
   * gas floods in along the web.
   */
  private mergeHalos(a: number, b: number): void {
    const g = this.g;
    const p = this.p;
    const A = this.wells[a];
    const B = this.wells[b];
    const m = A.s + B.s;
    // Like any merger, two equals release the most (the reduced mass); a small halo falling into a
    // deep one, much less.
    const mu = (2 * A.s * B.s) / m;
    const x = (A.x * A.s + B.x * B.s) / m;
    const y = (A.y * A.s + B.y * B.s) / m;
    A.vx = (A.vx * A.s + B.vx * B.s) / m;
    A.vy = (A.vy * A.s + B.vy * B.s) / m;
    A.x = x;
    A.y = y;
    A.s = Math.min(1.8, A.s + B.s * 0.8);
    this.wells.splice(b, 1);
    this.drift = null;
    this.s.mergers++;
    // Deeper dark matter (Cold Dark Matter) makes for harder shocks.
    const heat = MERGE_HEAT * mu * Math.sqrt(this.pull);
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i) || p.kind[i] !== CLUMP) continue;
      const d = Math.hypot(p.x[i] - x, p.y[i] - y);
      if (d < MERGE_R) p.a[i] += heat * (1 - d / MERGE_R);
    }
    const rng = g.sim;
    for (let k = 0; k < 12; k++) {
      const ang = rng.angle();
      const r = rng.range(60, 240);
      const gi = p.spawn(GAS, x + Math.cos(ang) * r, y + Math.sin(ang) * r, -Math.sin(ang) * 40, Math.cos(ang) * 40, 5, 1);
      if (gi >= 0) p.a[gi] = T_GAS;
    }
    this.fx.spawn(Fx.Ring, x, y, 2, 30, 0.4, 0.3, 0.7, 200);
    this.fx.spawn(Fx.Flash, x, y, 1.4, 160, 0.5, 0.42, 0.8, 120);
    this.shell(x, y, 260, 1.6, [0.55, 0.62, 1], 0.014);
    g.renderer?.shock(x, y, 0.35, 0.7, 1.2);
    g.renderer?.camera.addTrauma(0.06);
    g.sfx('dawn.halo', x);
    this.lastMerger = { x, y, t: this.t, mu };
    if (this.s.mergers === 1) g.toast('Two halos merged. Gas falling into the deeper well heats up, and the heat shines.', 'quiet');
    // Keep at least a handful of wells: the cosmic web keeps delivering new ones.
    if (this.wells.length < 5) {
      this.wells.push({ x: rng.range(-this.halfW, this.halfW) * 0.85, y: rng.range(-this.halfH, this.halfH) * 0.85, s: rng.range(0.4, 0.9), vx: 0, vy: 0 });
    }
  }

  // ───────────────────────────────────────── steps

  onStep(index: number): void {
    const g = this.g;
    this.s.stars *= 10;
    this.s.blackHoles *= 10;
    this.s.metals *= 10;
    this.syncStepFlags();
    this.bgParams.pulse = Math.min(1, this.bgParams.pulse + 0.3);
    g.renderer?.camera.breathe(0.05, 1.5);
    if (index === 1) this.bgParams.glow = Math.min(this.bgParams.glow, 0.35);
    if (index === 2) this.bgParams.glow = 0;
    if (index >= 3) g.sfx('dawn.milestone');
    if (index === 1) g.discover('dark-ages');
  }

  // ───────────────────────────────────────── finale: reionization complete

  finale(): Promise<void> {
    const g = this.g;
    const run = g.state.run;
    run.legacy.firstStar = this.s.firstStar;
    run.legacy.popIII = this.s.stars;
    g.tally('blackHoles', 'dawn', this.s.blackHoles);
    run.legacy.metals = this.s.metals;
    run.legacy.reion = this.s.reion;
    this.finaleT = 0;
    g.renderer?.camera.breathe(0.1, 7);
    g.sfx('dawn.complete');
    return new Promise((resolve) => {
      this.finaleDone = resolve;
    });
  }

  private updateFinale(dt: number): void {
    const g = this.g;
    this.finaleT += dt;
    const t = this.finaleT;
    // The last neutral gaps close.
    for (const b of this.s.bubbles) b.r += dt * 60;
    if (t >= 3.5 && !this.tallied) {
      this.tallied = true;
      g.renderer?.addFlash(0.2);
      g.toast(
        `Reionization complete. ${toText(count(this.s.stars))} first stars, ${toText(count(this.s.blackHoles))} black holes, and the first metals.`,
        'milestone',
      );
    }
    if (t >= 8 && this.finaleDone) {
      const done = this.finaleDone;
      this.finaleDone = null;
      done();
    }
  }

  // ───────────────────────────────────────── rendering

  /** The id of the very first star (it gets the whole sky to itself), and whether one had lit last frame. */
  private firstLight = -1;
  private litBefore = false;

  render(r: Renderer, dt: number): void {
    const p = this.p;
    const t = this.t;
    const look = this.look;
    const inFinale = this.finaleT >= 0;
    const bg = this.bgParams;
    bg.finale = inFinale ? Math.min(1, Math.max(0, (this.finaleT - 0.6) / 4.5)) ** 1.5 : 0;
    const floor = this.tMin;
    const dawn = this.step >= DAWN_STEP && !inFinale;
    // The universe holds still while its very first cloud collapses.
    let breath = 0;
    if (!this.s.everIgnited) for (let i = 0; i < p.n; i++) if (p.kind[i] === PROTO && !p.isDead(i)) breath = Math.max(breath, 1 - p.life[i] / 1.4);
    look.begin(r, { t, bg, pull: this.pull, floor, breath, halfW: this.halfW, halfH: this.halfH });
    look.halos(this.wells, this.pull, this.web, t, this.drift);
    if (this.lastMerger) look.merger(this.lastMerger.x, this.lastMerger.y, t - this.lastMerger.t, this.lastMerger.mu);
    look.bubbles(this.s.bubbles, t);

    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const x = p.x[i];
      const y = p.y[i];
      const id = p.id[i];
      switch (p.kind[i]) {
        case GAS:
          // Blown out of a newborn star's halo, gas flies hot.
          look.gas(x, y, Math.min(1, p.age[i] * 2) * (1 - bg.finale), Math.max(0, (p.a[i] - T_GAS) / (T_BLOWN - T_GAS)), p.sub[i] === 1);
          break;
        case CLUMP: {
          const m = p.w[i];
          const T = p.a[i];
          // What it shines away as it cools (the Dark Ages' only light), and how hot it runs.
          const glow = (m * Math.max(0, T - floor) * (1 + 0.02 * m)) / 900;
          const jeans = this.jeansMass(T);
          const rj = m >= 3 && dawn ? this.clumpRadius(Math.min(400, jeans)) * 1.25 : 0;
          look.clump(x, y, m, p.r[i], glow, Math.min(0.6, Math.max(0, (T - floor) / 70)), p.sub[i] === 1, rj, m / Math.max(1, jeans), t, id);
          break;
        }
        case PROTO:
          look.protostar(x, y, 1 - p.life[i] / 1.4, t, id, !this.s.everIgnited);
          break;
        case STAR: {
          const m = p.w[i];
          if (!this.litBefore && this.firstLight < 0) this.firstLight = id;
          look.star(x, y, m, p.life[i], p.age[i], p.sub[i] === 1, p.b[i], 46 * Math.pow(m / 50, 0.4), t, id, id === this.firstLight);
          break;
        }
        case BH:
          look.blackHole(x, y, p.r[i], t, id);
          break;
        case METAL:
          look.metal(x, y, p.vx[i], p.vy[i], Math.min(1, p.life[i] / 3), hash(id, 50) < 0.4, t, id);
          break;
      }
    }
    this.litBefore = this.s.everIgnited;
    look.handAt(this.pX, this.pY, 320 * this.gather, this.pDown && !inFinale, dt);
    for (const sh of this.shells) {
      const u = sh.age / sh.life;
      const rad = 8 + sh.v * sh.age * (1 - 0.4 * u);
      look.shell(sh.x, sh.y, rad, sh.c, Math.pow(1 - u, 1.5) * Math.min(1, sh.age * 20), sh.v * (1 - 0.8 * u));
    }
    this.fx.render(r, look);
    look.end();
  }

  // ───────────────────────────────────────── input

  pointer(e: PointerInfo): void {
    if (!e.primary) return;
    this.pX = e.x;
    this.pY = e.y;
    if (e.type === 'down') {
      this.idle = 0;
      this.pDown = true;
      this.s.everGathered = true;
    } else if (e.type === 'up' || e.type === 'cancel') {
      this.pDown = false;
    }
  }

  // ───────────────────────────────────────── HUD

  stocks(): StockView[] {
    const s = this.s;
    const out: StockView[] = [];
    if (s.everIgnited) {
      out.push({ id: 'stars', label: 'First stars', value: s.stars, format: 'count', rate: this.starMeter.rate, hint: 'Population III: huge, hot and short-lived.' });
    }
    if (s.blackHoles > 0) {
      out.push({ id: 'bh', label: 'Black holes', value: s.blackHoles, format: 'count', hint: 'What the giants leave behind. Remember them.' });
    }
    out.push({ id: 'reion', label: 'Reionized', value: s.reion, format: 'percent', hint: 'How much of the universe the first starlight has ionized again.' });
    return out;
  }

  dotScale(): { value: number; unit: string } | null {
    return { value: this.weight / 2e24, unit: 'Suns of gas' };
  }

  offline(seconds: number): OfflineReport {
    const s = this.s;
    const stars = this.starMeter.rate * seconds;
    s.stars += stars;
    return { lines: stars > 0 ? [{ label: 'First stars', value: toText(count(stars)) }] : [] };
  }

  accent(): RGB {
    if (this.s.everIgnited) return [0.86, 0.72, 1];
    const g = this.bgParams.glow;
    return [0.6 + 0.4 * g, 0.55 + 0.1 * g, 0.75 - 0.3 * g];
  }

  hint(): string | null {
    if (this.finaleT >= 0) return null;
    if (!this.s.everGathered && this.idle > 2.5) return 'Hold and drag to gather the gas.';
    if (this.s.everGathered && this.step < DAWN_STEP && this.idle > 8)
      return this.s.mergers < 2
        ? 'Hold between two halos, the dark warped spots, to pull them into one. Merging heats their gas, and hot gas glows: that glow is your energy.'
        : 'Crash gas clouds into each other. The harder they hit, the brighter they glow, and the glow is your energy. Stars come later, at cosmic dawn.';
    if (this.s.everGathered && !this.s.everIgnited && this.idle > 8) return 'Pile gas into one clump and let it cool. The light around it tightens and turns gold as it gets close, then it collapses into a star.';
    return null;
  }
}
