/**
 * Readings in words for the frame: "10⁻¹² seconds after the beginning, at 5.6 × 10¹⁶ kelvin".
 * The figures come from the same formatters as everywhere else; only the unit is spelled out.
 */
import type { NumParts } from '../../core/format';

const UNITS: Record<string, [one: string, many: string]> = {
  s: ['second', 'seconds'],
  ms: ['millisecond', 'milliseconds'],
  'µs': ['microsecond', 'microseconds'],
  ns: ['nanosecond', 'nanoseconds'],
  min: ['minute', 'minutes'],
  hr: ['hour', 'hours'],
  day: ['day', 'days'],
  days: ['day', 'days'],
  yr: ['year', 'years'],
  kyr: ['thousand years', 'thousand years'],
  Myr: ['million years', 'million years'],
  Gyr: ['billion years', 'billion years'],
  K: ['kelvin', 'kelvin'],
};

/** The same figure with its unit spelled out ("1 nanosecond", "10⁻¹² seconds"). */
export function inWords(p: NumParts): NumParts {
  const names = UNITS[p.u];
  if (!names) return p;
  return { ...p, u: p.e === null && p.m === '1' ? names[0] : names[1] };
}

/** "Free quarks" → "free quarks", for a count that reads as a phrase; leaves "CMB" alone. */
export function lowerFirst(s: string): string {
  return s.length > 1 && s[1] === s[1].toLowerCase() ? s[0].toLowerCase() + s.slice(1) : s;
}
