/**
 * The frame: era background (at reduced resolution) → HDR scene with sprite and line layers →
 * bloom → composite (distortion, tonemapping, grain) to the screen.
 *
 * Eras queue sprites and lines every frame in immediate mode, and can add GPU layers (fluids,
 * particle storms) that keep their own state; the renderer owns the frame and survives context loss
 * by rebuilding everything from scratch, layers included.
 *
 * Nothing a driver rejects stops the game: a program that fails to build leaves its pass out, and a
 * layer that throws (building or drawing) is set aside while the rest of the frame goes on. Without
 * float render targets the frame is kept in 8-bit sRGB targets with its light scaled into their range
 * (see LDR_RANGE): a simplified look, but the same scene, which `simplified` reports.
 */
import { BLACKBODY, HASH, HEADER, SIMPLEX } from './glsl';
import { FULLSCREEN_VS, Target, bindTexture, detectCaps, drawFullscreen, lightFormat, lightGain, tryProgram, unbindTextures, type GLCaps, type Program, type TargetFormat } from './gl';
import { Camera } from './camera';
import { LineBatch, createLineProgram } from './lines';
import { Post, defaultPost, type PostParams } from './post';
import { PullBack } from './pullback';
import { SpriteBatch, createSpriteProgram } from './sprites';

export interface FrameInfo {
  time: number;
  /** Render-target size in pixels. */
  width: number;
  height: number;
  view: Float32Array;
}

/**
 * An era's full-screen background. `fragment` is GLSL appended after the shared header, hash,
 * simplex noise and blackbody chunks; it receives `vUv`, and the uniforms `uTime`, `uRes` and
 * `uView` (world centre and half extents), and must write `outColor`.
 */
export interface BackgroundDef {
  id: string;
  fragment: string;
  uniforms?: (p: Program, frame: FrameInfo) => void;
  /**
   * Single-channel float data textures the shader samples (declared in `fragment` as
   * `uniform sampler2D <name>;`). Re-uploaded whenever `version()` changes.
   */
  textures?: BgTexture[];
}

/**
 * A GPU pass an era adds to the frame. Media (fluids) draw right after the background, matter (GPU
 * particles) after the under-glow sprites, and atmosphere (volumes the light scatters through) over
 * everything, before the lens. A layer owns its GL resources: `init` builds them (again after a lost
 * context) and `draw` may use its own targets, but must leave the scene target bound when it returns.
 * Textures are bound through `bindTexture` / `Target.sample` (so a target never stays bound for
 * sampling while drawn into), and light written into the scene is multiplied by `LayerFrame.gain`.
 */
export interface RenderLayer {
  readonly stage: 'media' | 'matter' | 'atmosphere';
  init(gl: WebGL2RenderingContext, caps: GLCaps, emptyVao: WebGLVertexArrayObject): void;
  draw(frame: LayerFrame): void;
  dispose(): void;
}

export interface LayerFrame {
  dt: number;
  time: number;
  /** World centre and half extents. */
  view: Float32Array;
  /** Scene target, already bound. */
  scene: Target;
  pxPerUnit: number;
  /** What the current quality level renders: layers scale their own work by it. */
  quality: QualitySpec;
  /**
   * What light written into the scene is multiplied by: 1 with HDR, 1 / LDR_RANGE when the scene is
   * 8-bit (the composite scales it back up).
   */
  gain: number;
}

export interface BgTexture {
  name: string;
  width: number;
  height: number;
  data: () => Float32Array;
  version: () => number;
}

interface Shock {
  x: number;
  y: number;
  /** Radius in screen heights. */
  radius: number;
  speed: number;
  strength: number;
  life: number;
  age: number;
}

/**
 * What each quality level renders. High is the reference look. Medium renders the scene a little
 * smaller and leaves the finest noise octave out of the background; Low goes further, and also runs
 * the final pass at the scene's size, leaving the stretch to the screen to the browser. The GPU layers
 * scale with it too (each relative to what its era asks for): raymarched volumes take fewer steps at a
 * lower resolution and average more frames to make up for it, particle storms draw fewer specks (each a
 * little brighter, so the field keeps its light), and curves are drawn with fewer segments.
 */
export type QualityLevel = 'low' | 'medium' | 'high';
export interface QualitySpec {
  /** Fraction of device pixels the scene renders at. */
  scale: number;
  /** Background resolution relative to the scene. */
  bg: number;
  /** Finest fbm octaves the backgrounds leave out. */
  octaveDrop: number;
  /** Composite at the screen's own resolution (sharper grain and dithering) or at the scene's. */
  nativePost: boolean;
  /** Share of a raymarched volume's steps per ray. */
  steps: number;
  /** A volume's resolution relative to the one its layer asks for (on top of the scene's `scale`). */
  volume: number;
  /** Share of a particle storm's specks drawn. */
  particles: number;
  /** Segments per length of drawn curves (filaments), relative to High. */
  detail: number;
}
export const QUALITY: Record<QualityLevel, QualitySpec> = {
  high: { scale: 1, bg: 0.5, octaveDrop: 0, nativePost: true, steps: 1, volume: 1, particles: 1, detail: 1 },
  medium: { scale: 0.8, bg: 0.5, octaveDrop: 1, nativePost: true, steps: 0.7, volume: 0.85, particles: 0.6, detail: 0.65 },
  low: { scale: 0.6, bg: 0.4, octaveDrop: 2, nativePost: false, steps: 0.5, volume: 0.75, particles: 0.35, detail: 0.45 },
};

/**
 * The pull-back between eras, over the finished scene before the lens (so it blooms as the scene
 * does): the live scene through a soft window (out = still + scene × alpha, blended ONE, SRC_ALPHA),
 * and the old era's last frame, kept as a still, shrinking into the centre. Four taps a texel apart
 * at the still's own scale keep its points from shimmering as they shrink.
 */
const PASSAGE_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uGhost;
uniform vec2 uTexel;
uniform float uGhostGain;
uniform float uGhostScale;
uniform float uLive;
uniform float uWindow;
out vec4 outColor;
void main() {
  vec2 p = vUv * 2.0 - 1.0;
  float live = uLive;
  if (uWindow > 0.0) {
    vec2 q = abs(p) / uWindow;
    float r = pow(pow(q.x, 3.0) + pow(q.y, 3.0), 1.0 / 3.0);
    live *= 1.0 - smoothstep(0.5, 1.0, r);
  }
  vec3 ghost = vec3(0.0);
  vec2 g = p * uGhostScale;
  if (uGhostGain > 0.0 && abs(g.x) < 1.0 && abs(g.y) < 1.0) {
    vec2 uv = g * 0.5 + 0.5;
    vec2 o = uTexel * 0.35 * uGhostScale;
    ghost = (texture(uGhost, uv + vec2(o.x, o.y)).rgb + texture(uGhost, uv + vec2(-o.x, o.y)).rgb
      + texture(uGhost, uv + vec2(o.x, -o.y)).rgb + texture(uGhost, uv + vec2(-o.x, -o.y)).rgb) * 0.25 * uGhostGain;
  }
  outColor = vec4(ghost, live);
}`;

/**
 * Full-screen flashes draw on a budget of exposure lift that refills over time, so a run of events
 * can't strobe the screen (WCAG 2.3.1: no more than three flashes a second). The bank holds one
 * flash at the cap; refilled, it allows about three small flashes a second, fewer with Reduce flashes.
 */
const FLASH_CAP = 1.2;
const FLASH_REFILL = 0.45;
const FLASH_CAP_REDUCED = 0.18;
const FLASH_REFILL_REDUCED = 0.06;

export interface RenderStats {
  sprites: number;
  lines: number;
  cpuMs: number;
}

export class Renderer {
  readonly gl: WebGL2RenderingContext;
  caps!: GLCaps;
  readonly camera = new Camera();
  /** The pull-back between eras (it moves the camera and veils the scene). */
  readonly pullBack = new PullBack(this.camera);

  under!: SpriteBatch;
  solid!: SpriteBatch;
  glow!: SpriteBatch;
  over!: SpriteBatch;
  /** Drawn over the atmosphere too: the brightest light (flashes, sources) seen through any medium. */
  top!: SpriteBatch;
  lines!: LineBatch;

  post: PostParams = defaultPost();
  quality: QualitySpec = QUALITY.high;
  reduceFlashes = false;
  stats: RenderStats = { sprites: 0, lines: 0, cpuMs: 0 };
  lost = false;

  cssW = 1;
  cssH = 1;
  private dpr = 1;
  private scene!: Target;
  private bg!: Target;
  private fx!: Post;
  private emptyVao!: WebGLVertexArrayObject;
  private passage: Program | null = null;
  /** How the scene stores light, and what light going into it is multiplied by (see LDR_RANGE). */
  private format: TargetFormat = 'half';
  private gain = 1;
  /** The old era's last frame during a pull-back (allocated on the first one). */
  private ghost: Target | null = null;
  private bgDef: BackgroundDef | null = null;
  /** Background programs by era and octave drop (null: it failed to build, so the era goes without). */
  private bgPrograms = new Map<string, Program | null>();
  private bgTextures = new Map<string, { tex: WebGLTexture; version: number }>();
  private layers: RenderLayer[] = [];
  /** Layers that threw while building or drawing: set aside (disposed) so the frame goes on without them. */
  private broken = new Set<RenderLayer>();
  private layerFrame: LayerFrame | null = null;
  private shocks: Shock[] = [];
  private flash = 0;
  private flashBank = FLASH_CAP;
  private aberration = 0;
  private time = 0;
  private viewArr = new Float32Array(4);
  private frameInfo: FrameInfo = { time: 0, width: 1, height: 1, view: this.viewArr };

  constructor(private readonly canvas: HTMLCanvasElement) {
    const gl = canvas.getContext('webgl2', {
      alpha: false,
      antialias: false,
      depth: false,
      stencil: false,
      premultipliedAlpha: false,
      preserveDrawingBuffer: false,
      powerPreference: 'high-performance',
    });
    if (!gl) throw new Error('WebGL2 is not available');
    this.gl = gl;
    canvas.addEventListener('webglcontextlost', (e) => {
      e.preventDefault();
      this.lost = true;
    });
    canvas.addEventListener('webglcontextrestored', () => {
      // Rebuilt from scratch; should even that fail, the canvas stays dark rather than half-built.
      try {
        this.init();
        this.lost = false;
      } catch (e) {
        console.error(e);
      }
    });
    this.init();
  }

  private init(): void {
    const gl = this.gl;
    this.caps = detectCaps(gl);
    // ?ldr (dev builds only): render as a device without float targets would, to check the fallback.
    if (import.meta.env?.DEV && typeof location !== 'undefined' && new URLSearchParams(location.search).has('ldr')) this.caps.hdr = false;
    this.format = lightFormat(this.caps);
    this.gain = lightGain(this.format);
    const vao = gl.createVertexArray();
    if (!vao) throw new Error('Could not create VAO');
    this.emptyVao = vao;
    const sp = createSpriteProgram(gl);
    this.under = new SpriteBatch(gl, sp, 'add');
    this.solid = new SpriteBatch(gl, sp, 'alpha');
    this.glow = new SpriteBatch(gl, sp, 'add');
    this.over = new SpriteBatch(gl, sp, 'add');
    this.top = new SpriteBatch(gl, sp, 'add');
    this.lines = new LineBatch(gl, createLineProgram(gl));
    this.scene = new Target(gl, 1, 1, this.format);
    // The background is drawn by era code that knows nothing of the scene's range, so without HDR it
    // keeps 0–1 in sRGB (precise in the dark, where backgrounds live) and is scaled on its way in.
    this.bg = new Target(gl, 1, 1, this.format);
    this.fx = new Post(gl, this.format, this.emptyVao);
    this.passage = tryProgram(gl, FULLSCREEN_VS, PASSAGE_FS, 'passage');
    this.ghost = null;
    this.bgPrograms.clear();
    this.bgTextures.clear();
    this.broken.clear();
    for (const l of this.layers) this.initLayer(l);
    this.applySize();
  }

  /** True when this device can't render float targets and the frame is shown in its simplified, 8-bit form. */
  get simplified(): boolean {
    return this.format !== 'half';
  }

  /** Replaces the era's GPU layers (the old ones are disposed). */
  setLayers(layers: RenderLayer[]): void {
    for (const l of this.layers) {
      if (layers.includes(l)) continue;
      this.disposeLayer(l);
      this.broken.delete(l);
    }
    for (const l of layers) if (!this.layers.includes(l)) this.initLayer(l);
    this.layers = layers;
  }

  /** Builds a layer; one that throws is set aside, and the era's look attaches without it. */
  private initLayer(l: RenderLayer): void {
    try {
      l.init(this.gl, this.caps, this.emptyVao);
    } catch (e) {
      console.error(e);
      this.setAside(l);
    }
  }

  private setAside(l: RenderLayer): void {
    this.broken.add(l);
    this.disposeLayer(l);
  }

  private disposeLayer(l: RenderLayer): void {
    try {
      l.dispose();
    } catch (e) {
      console.error(e);
    }
  }

  resize(cssW: number, cssH: number, dpr: number): void {
    this.cssW = Math.max(1, cssW);
    this.cssH = Math.max(1, cssH);
    this.dpr = dpr;
    this.applySize();
  }

  private applySize(): void {
    const q = this.quality;
    const device = Math.min(this.dpr, 2);
    const w = Math.max(1, Math.round(this.cssW * device * q.scale));
    const h = Math.max(1, Math.round(this.cssH * device * q.scale));
    this.canvas.width = q.nativePost ? Math.max(1, Math.round(this.cssW * device)) : w;
    this.canvas.height = q.nativePost ? Math.max(1, Math.round(this.cssH * device)) : h;
    this.camera.aspect = this.cssW / this.cssH;
    if (!this.scene) return;
    this.scene.resize(w, h);
    this.bg.resize(w * q.bg, h * q.bg);
    this.fx.resize(w, h);
    this.ghost?.resize(w, h);
  }

  /** Fraction of device pixels the scene renders at. */
  get renderScale(): number {
    return this.quality.scale;
  }

  setQuality(level: QualityLevel): void {
    this.quality = QUALITY[level];
    this.applySize();
    if (this.bgDef) this.bgProgram(this.bgDef);
  }

  setBackground(def: BackgroundDef | null): void {
    this.bgDef = def;
    if (def) this.bgProgram(def);
  }

  /**
   * The background's program at the current level, compiled the first time it is needed (again after
   * a lost context). A shader the driver rejects leaves a plain dark background, not a dead game.
   */
  private bgProgram(def: BackgroundDef): Program | null {
    const drop = this.quality.octaveDrop;
    const key = `${def.id}:${drop}`;
    let prog = this.bgPrograms.get(key);
    if (prog === undefined) {
      const fs = HEADER + `#define FBM_DROP ${drop}\n` + HASH + SIMPLEX + BLACKBODY + /* glsl */ `
in vec2 vUv;
uniform float uTime;
uniform vec2 uRes;
uniform vec4 uView;
out vec4 outColor;
` + def.fragment;
      prog = tryProgram(this.gl, FULLSCREEN_VS, fs, `bg:${def.id}`);
      this.bgPrograms.set(key, prog);
    }
    return prog;
  }

  /** A refractive shockwave ring at a world position. Strength ~0.2 subtle … 1.5 violent. */
  shock(x: number, y: number, strength: number, speed = 0.9, life = 1.1): void {
    if (this.shocks.length >= 8) this.shocks.shift();
    this.shocks.push({ x, y, radius: 0, speed, strength, life, age: 0 });
  }

  /** Brief exposure lift (0.2 = noticeable, 1 = blinding). Capped hard when flashes are reduced. */
  addFlash(amount: number): void {
    const reduced = this.reduceFlashes;
    const room = (reduced ? FLASH_CAP_REDUCED : FLASH_CAP) - this.flash;
    const lift = Math.min(room, this.flashBank, reduced ? amount * 0.25 : amount);
    if (lift <= 0) return;
    this.flash += lift;
    this.flashBank -= lift;
  }

  addAberration(amount: number): void {
    if (this.reduceFlashes) return;
    this.aberration = Math.min(0.012, this.aberration + amount);
  }

  /** Pixels of the scene target per world unit. */
  get pxPerUnit(): number {
    return this.scene.height / (2 * this.camera.halfH);
  }

  render(dt: number): void {
    const t0 = performance.now();
    const gl = this.gl;
    if (this.lost || gl.isContextLost()) {
      this.clearBatches();
      return;
    }
    this.time += dt;
    this.camera.view(this.viewArr);
    this.frameInfo.time = this.time;

    gl.disable(gl.DEPTH_TEST);
    gl.disable(gl.CULL_FACE);
    // Every frame starts with no texture bound anywhere: whatever the last one left can't be sampled
    // by a pass that forgot to bind its own (a feedback loop with the scene, and that pass draws nothing).
    unbindTextures(gl);

    // 1. Background at reduced resolution.
    const bgProg = this.bgDef ? this.bgProgram(this.bgDef) : null;
    if (bgProg && this.bgDef) {
      this.bg.bind();
      gl.disable(gl.BLEND);
      this.frameInfo.width = this.bg.width;
      this.frameInfo.height = this.bg.height;
      bgProg.use().f1('uTime', this.time).f2('uRes', this.bg.width, this.bg.height);
      gl.uniform4fv(bgProg.loc('uView'), this.viewArr);
      this.bgDef.uniforms?.(bgProg, this.frameInfo);
      this.bindBgTextures(bgProg, this.bgDef);
      drawFullscreen(gl, this.emptyVao);
    }

    // 2. Scene: background upsampled, then particle layers.
    this.scene.bind();
    gl.disable(gl.BLEND);
    if (bgProg) this.fx.blitTo(this.bg, this.gain);
    else {
      gl.clearColor(0, 0, 0, 1);
      gl.clear(gl.COLOR_BUFFER_BIT);
    }
    gl.enable(gl.BLEND);
    const ppu = this.pxPerUnit;
    const minPx = 1.35 * (this.scene.height / this.cssH);
    const g = this.gain;
    const lf = (this.layerFrame ??= { dt, time: this.time, view: this.viewArr, scene: this.scene, pxPerUnit: ppu, quality: this.quality, gain: g });
    lf.dt = dt;
    lf.time = this.time;
    lf.scene = this.scene;
    lf.pxPerUnit = ppu;
    lf.quality = this.quality;
    lf.gain = g;
    this.drawLayers('media', lf);
    this.under.draw(this.viewArr, ppu, minPx, g);
    this.drawLayers('matter', lf);
    this.lines.draw(this.viewArr, ppu, minPx * 0.7, g);
    this.solid.draw(this.viewArr, ppu, minPx, g);
    this.glow.draw(this.viewArr, ppu, minPx, g);
    this.over.draw(this.viewArr, ppu, minPx, g);
    this.drawLayers('atmosphere', lf);
    this.top.draw(this.viewArr, ppu, minPx, g);
    gl.disable(gl.BLEND);
    if (this.pullBack.active) this.drawPassage();

    // 3. Transient effects.
    const shocks = [];
    for (let i = this.shocks.length - 1; i >= 0; i--) {
      const s = this.shocks[i];
      s.age += dt;
      s.radius += s.speed * dt * (1 - 0.5 * (s.age / s.life));
      if (s.age >= s.life) {
        this.shocks.splice(i, 1);
        continue;
      }
      const fade = 1 - s.age / s.life;
      shocks.push({
        x: (s.x - this.viewArr[0]) / (2 * this.viewArr[2]) + 0.5,
        y: 0.5 - (s.y - this.viewArr[1]) / (2 * this.viewArr[3]),
        radius: s.radius,
        strength: s.strength * fade * fade * (this.reduceFlashes ? 0.4 : 1),
      });
    }
    const flash = this.flash;
    this.flash *= Math.exp(-dt * 5.5);
    if (this.flash < 1e-3) this.flash = 0;
    const reduced = this.reduceFlashes;
    const bank = reduced ? FLASH_CAP_REDUCED : FLASH_CAP;
    this.flashBank = Math.min(bank, this.flashBank + dt * (reduced ? FLASH_REFILL_REDUCED : FLASH_REFILL));
    const aberration = this.aberration;
    this.aberration *= Math.exp(-dt * 4);
    if (this.aberration < 1e-5) this.aberration = 0;

    // 4. Bloom + composite.
    const p = this.post;
    const saved = { flash: p.flash, aberration: p.aberration };
    p.flash = saved.flash + flash;
    p.aberration = saved.aberration + aberration;
    this.fx.present(this.scene, this.canvas.width, this.canvas.height, p, this.time, shocks);
    p.flash = saved.flash;
    p.aberration = saved.aberration;

    this.stats.sprites = this.under.size + this.solid.size + this.glow.size + this.over.size + this.top.size;
    this.stats.lines = this.lines.size;
    this.clearBatches();
    this.stats.cpuMs = performance.now() - t0;
  }

  /** The pull-back's veil and still over the finished scene (the scene target is bound). */
  private drawPassage(): void {
    const gl = this.gl;
    const pb = this.pullBack;
    const scene = this.scene;
    // The still holds the scene as stored (in its range), so it goes back in with no gain.
    const ghost = (this.ghost ??= new Target(gl, scene.width, scene.height, this.format));
    if (this.passage) {
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.SRC_ALPHA);
      this.passage.use().i1('uGhost', 0).f2('uTexel', 1 / ghost.width, 1 / ghost.height).f1('uGhostGain', pb.ghost).f1('uGhostScale', pb.ghostScale);
      this.passage.f1('uLive', pb.live).f1('uWindow', pb.window);
      ghost.sample(0);
      drawFullscreen(gl, this.emptyVao);
      gl.disable(gl.BLEND);
    }
    if (pb.capture) {
      // The receded frame becomes the still the next era arrives around.
      ghost.bind();
      this.fx.blitTo(scene);
      scene.bind();
    }
  }

  private drawLayers(stage: RenderLayer['stage'], frame: LayerFrame): void {
    const gl = this.gl;
    for (const l of this.layers) {
      if (l.stage !== stage || this.broken.has(l)) continue;
      try {
        l.draw(frame);
      } catch (e) {
        // A layer that throws mid-frame is set aside; the state it may have left is put back.
        console.error(e);
        if (gl.getParameter(gl.TRANSFORM_FEEDBACK_ACTIVE)) gl.endTransformFeedback();
        gl.disable(gl.RASTERIZER_DISCARD);
        gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, null);
        this.setAside(l);
      }
      this.scene.bind();
      gl.bindVertexArray(null);
      gl.enable(gl.BLEND);
    }
  }

  private bindBgTextures(prog: Program, def: BackgroundDef): void {
    const gl = this.gl;
    (def.textures ?? []).forEach((t, k) => {
      const key = `${def.id}:${t.name}`;
      let entry = this.bgTextures.get(key);
      if (!entry) {
        const tex = gl.createTexture();
        if (!tex) return;
        entry = { tex, version: -1 };
        this.bgTextures.set(key, entry);
        bindTexture(gl, 1 + k, tex);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      }
      bindTexture(gl, 1 + k, entry.tex);
      const v = t.version();
      if (v !== entry.version) {
        entry.version = v;
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.R16F, t.width, t.height, 0, gl.RED, gl.FLOAT, t.data());
      }
      prog.i1(t.name, 1 + k);
    });
  }

  private clearBatches(): void {
    this.under.clear();
    this.solid.clear();
    this.glow.clear();
    this.over.clear();
    this.top.clear();
    this.lines.clear();
  }
}
