import { SOUP_CODEX } from './codex';
import { SoupEra } from './sim';

const fNum = (v: number): NumParts => decimal(v, 3);
const fMult = (v: number): NumParts => {
  const d = decimal(v, 3);
  return { ...d, m: '×' + d.m };
};
const fPct = (v: number): NumParts => percent(v, 3);

const GEV = 1e9;
const TEV = 1e12;
const PEV = 1e15;
/**
 * Prices are quoted relative to the per-event yields (an annihilation gives ~1 GeV at the start).
 * This one factor sets the era's overall length; tuned with tools/balance.
 */
const PRICE = 2.25;

/** Free quarks confinement needs before it can make anything. */
const QUARKS_NEEDED = 1e6;

/** Free quarks so far: matter left over once baryogenesis is on. */
const freeQuarks = (g: Game): number => (g.state.run.eras.soup as { quarks?: number } | undefined)?.quarks ?? 0;

/** Sakharov's conditions met: quark number can change, matter is favored, the soup falls out of balance. */
const sakharov = (g: Game): [done: number, total: number] => [
  (g.level('soup.sphalerons') > 0 ? 1 : 0) + (g.level('soup.cp') > 0 ? 1 : 0) + (g.state.run.step >= 2 ? 1 : 0),
  3,
];

/** Energy in hand toward the next step's price (a goal is read while its step is the next one). */
const toward = (g: Game): number => g.energy / Math.max(1, g.nextStep?.cost ?? Infinity);

/** Until baryogenesis, the goal that matters most: the next of Sakharov's conditions. */
function matterGoal(g: Game): StepGoal {
  const [done, total] = sakharov(g);
  // A non-breaking hyphen (U+2011) keeps the phenomenon's name whole when the line wraps.
  const next =
    g.level('soup.sphalerons') === 0 ? 'Baryon Number Violation' : g.level('soup.cp') === 0 ? 'Charge‑Parity Violation' : 'the electroweak transition';
  return {
    text: 'Leave more matter than antimatter',
    detail: `One extra quark per billion pairs will do. Next: ${next}.`,
    progress: done / total,
  };
}

/** A step that needs only energy, once baryogenesis is on (until then, matter comes first). */
const cooling =
  (text: string, detail: string) =>
  (g: Game): StepGoal =>
    g.flag('soup.baryogenesis') ? { text, detail, progress: toward(g) } : matterGoal(g);

