/**
 * Rate meters: turn bursty simulation events into smooth per-second rates.
 * Used for "+x/s" readouts and for offline credit (you earn what you were earning).
 */
export class RateMeter {
  /** Smoothed rate per second. */
  rate = 0;
  private bucket = 0;
  private elapsed = 0;
  private warm = 0;

  /**
   * @param window   Smoothing time constant in seconds.
   * @param interval How often the bucket is folded into the average.
   */
  constructor(
    private readonly window = 20,
    private readonly interval = 0.5,
  ) {}

  add(amount: number): void {
    this.bucket += amount;
  }

  tick(dt: number): void {
    this.elapsed += dt;
    if (this.elapsed < this.interval) return;
    const instant = this.bucket / this.elapsed;
    // Converge fast at first so a fresh meter is useful within seconds, then smooth.
    this.warm = Math.min(this.window, this.warm + this.elapsed);
    const k = 1 - Math.exp(-this.elapsed / Math.max(this.interval, Math.min(this.window, this.warm)));
    this.rate += (instant - this.rate) * k;
    this.bucket = 0;
    this.elapsed = 0;
  }

  reset(rate = 0): void {
    this.rate = rate;
    this.bucket = 0;
    this.elapsed = 0;
    this.warm = 0;
  }
}
