/**
 * Phenomena: the game's upgrades. Each is a real physical process with its true name, one line of
 * physics, and an exact effect expressed as stat modifiers, so its card can preview "now → next".
 */
import type { NumParts } from './format';
import type { EraId } from './state';
import type { Modifier } from './stats';

export interface PhenomenonHost {
  readonly energy: number;
  level(id: string): number;
  flag(name: string): boolean;
}

export interface PhenomenonDef {
  id: string;
  era: EraId;
  name: string;
  /** One line of real physics (≤ 90 characters). */
  physics: string;
  /** Maximum level; 1 makes it a one-shot. Omitted = unlimited. */
  max?: number;
  /** Cost in eV of going from `level` to `level + 1`. */
  cost: (level: number) => number;
  /** Modifiers granted at `level` (never called with 0). */
  effects?: (level: number) => Modifier[];
  /** The stat whose value the card previews, with its formatter and an optional unit label. */
  shows?: { stat: string; format: (v: number) => NumParts; label: string };
  /** Effect text for one-shots or effects that aren't a single stat. */
  effectText?: (level: number) => string;
  /** Phenomena that must be owned before this one can appear. */
  requires?: readonly string[];
  /** Extra reveal condition; by default a phenomenon appears once energy reaches 25 % of its cost. */
  reveal?: (h: PhenomenonHost) => boolean;
  /** Cards sharing a group render together (e.g. the Sakharov conditions). */
  group?: string;
  /** Codex entry discovered when first bought. */
  codex?: string;
  /** Side effects of buying (events, discoveries). */
  onBuy?: (level: number) => void;
}

/** Cost curve: base × growth^level. */
export function geometric(base: number, growth: number): (level: number) => number {
  return (level) => base * growth ** level;
}

/** Fixed cost (one-shots). */
export function fixed(cost: number): (level: number) => number {
  return () => cost;
}

/** Roman numerals for level badges (I … XX, then digits). */
export function roman(n: number): string {
  if (n <= 0) return '';
  if (n > 39) return String(n);
  const tens = ['', 'X', 'XX', 'XXX'];
  const ones = ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX'];
  return tens[Math.floor(n / 10)] + ones[n % 10];
}
