<!--
  The Universe card: this universe's results next to ours, and its history so far.
-->
<script lang="ts">
  import Panel from './Panel.svelte';
  import { cosmicTime, count, decimal, duration, percent, energy, type NumParts } from '../../core/format';
  import type { StockFormat } from '../../core/era';
  import { LEGACY } from '../../content/legacy';
  import Num from '../common/Num.svelte';
  import Strip from '../multiverse/Strip.svelte';
  import { OUR_CONSTANTS } from '../../core/state';
  import { game, track } from '../store.svelte';

  const g = game();

  function fmt(f: StockFormat, v: number): NumParts {
    if (f === 'decimal') return decimal(v, 3);
    if (f === 'percent') return percent(v, 3);
    if (f === 'energy') return energy(v, g.state.run.joules ? 'J' : 'eV');
    return count(v, g.state.settings.notation);
  }

  const v = $derived.by(() => {
    track();
    const run = g.state.run;
    return {
      index: run.index,
      played: run.playTime,
      legacy: LEGACY.filter((l) => run.legacy[l.key] !== undefined).map((l) => ({ ...l, value: run.legacy[l.key] * (l.scale ?? 1) })),
      constants: run.constants,
      parent: run.parent,
      history: [...run.history],
    };
  });
</script>

<Panel title="Universe {v.index}">
  <p class="sub">{duration(v.played)} since the beginning, for you.</p>

  {#if v.index > 1}
    <h3 class="label">Its numbers, against ours</h3>
    <Strip c={v.constants} parent={OUR_CONSTANTS} />
  {/if}

  {#if v.legacy.length}
    <h3 class="label">Results</h3>
    <table>
      <thead>
        <tr><th></th><th class="label">Yours</th><th class="label">Ours</th></tr>
      </thead>
      <tbody>
        {#each v.legacy as l (l.key)}
          <tr title={l.hint}>
            <td class="name">{l.label}</td>
            <td><Num parts={fmt(l.format, l.value)} /></td>
            <td class="ours">{#if l.ours !== undefined}<Num parts={fmt(l.format, l.ours)} />{:else}–{/if}</td>
          </tr>
        {/each}
      </tbody>
    </table>
  {/if}

  <h3 class="label">History</h3>
  <ol class="history">
    {#each v.history as h, i (i)}
      <li class:latest={i === v.history.length - 1}>
        <span class="when"><Num parts={cosmicTime(h.t)} /></span>
        <span class="what">{h.text}</span>
      </li>
    {/each}
  </ol>
</Panel>

