/**
 * A periodic box: whatever leaves one side comes back in through the opposite one. Cosmological
 * simulations stand a finite box in for endless, uniform space this way (periodic boundary
 * conditions), and the eras where space is uniform play in one: the whole view, its edges no walls
 * (what leaves at the top right comes back at the bottom left). Distances are measured through the
 * wrap, to the nearest copy of the other point; things near an edge are drawn on both sides of it, so
 * nothing pops as it crosses.
 */
export class Torus {
  /** Half extents and full sizes along each axis. */
  hx = 400;
  hy = 400;
  sx = 800;
  sy = 800;

  set(hx: number, hy = hx): void {
    this.hx = hx;
    this.hy = hy;
    this.sx = hx * 2;
    this.sy = hy * 2;
  }

  /** A coordinate brought back into the box. */
  wrapX(v: number): number {
    return v - this.sx * Math.floor((v + this.hx) / this.sx);
  }

  wrapY(v: number): number {
    return v - this.sy * Math.floor((v + this.hy) / this.sy);
  }

  /** The shortest way along one axis from one point to another, through the wrap. */
  dx(d: number): number {
    return d - this.sx * Math.round(d / this.sx);
  }

  dy(d: number): number {
    return d - this.sy * Math.round(d / this.sy);
  }

  /** The box's area. */
  get area(): number {
    return this.sx * this.sy;
  }

  /**
   * The offsets of the box's copies that show in a view of half extents `hw` by `hh` about the box's
   * centre (widen the view by a margin to catch what straddles an edge), as x, y pairs, the box first.
   */
  images(hw: number, hh: number, out: number[] = []): number[] {
    out.length = 0;
    out.push(0, 0);
    const nx = Math.max(0, Math.ceil((hw - this.hx) / this.sx));
    const ny = Math.max(0, Math.ceil((hh - this.hy) / this.sy));
    for (let j = -ny; j <= ny; j++) {
      for (let i = -nx; i <= nx; i++) if (i !== 0 || j !== 0) out.push(i * this.sx, j * this.sy);
    }
    return out;
  }
}
