<!--
  Root: the cosmos canvas, the HUD around it, overlays and panels. Wires input to the game.
-->
<script lang="ts">
  import { onMount } from 'svelte';
  import { Renderer } from '../render/renderer';
  import type { PointerInfo } from '../core/era';
  import Clock from './hud/Clock.svelte';
  import Energy from './hud/Energy.svelte';
  import Floaters from './hud/Floaters.svelte';
  import Hint from './hud/Hint.svelte';
  import Labels from './hud/Labels.svelte';
  import Menu from './hud/Menu.svelte';
  import Perf from './hud/Perf.svelte';
  import Phenomena from './hud/Phenomena.svelte';
  import Stocks from './hud/Stocks.svelte';
  import Timeline from './hud/Timeline.svelte';
  import Toasts from './hud/Toasts.svelte';
  import EraTitle from './overlays/EraTitle.svelte';
  import Offline from './overlays/Offline.svelte';
  import Codex from './panels/Codex.svelte';
  import Settings from './panels/Settings.svelte';
  import Universe from './panels/Universe.svelte';
  import Multiverse from './multiverse/Multiverse.svelte';
  import Ending from './overlays/Ending.svelte';
  import Frame from './frame/Frame.svelte';
  import Skip from './dev/Skip.svelte';
  import { frameEra } from './frame/eras';
  import { hotkeyTargets } from './hotkeys';
  import { advance } from './view';
  import { native } from '../platform/native';
  import { audio, game, still, track, ui } from './store.svelte';

  let { onReady }: { onReady: (r: Renderer) => void } = $props();

  const g = game();
  let canvas: HTMLCanvasElement;
  let failed = $state('');

  const hud = $derived.by(() => {
    track();
    return {
      hidden: (g.era?.hudHidden?.() ?? false) || g.state.meta.atMultiverse,
      /** Eras with the v2 look are seen through the frame; the rest keep the v1 HUD for now. */
      framed: frameEra(g.state.run.era) !== null,
      finale: g.inFinale,
      perf: g.state.settings.showPerf,
    };
  });

  onMount(() => {
    let renderer: Renderer;
    try {
      renderer = new Renderer(canvas);
    } catch (e) {
      failed = e instanceof Error ? e.message : String(e);
      return;
    }
    const fit = () => {
      renderer.resize(window.innerWidth, window.innerHeight, window.devicePixelRatio || 1);
      const [hw, hh] = g.viewportHalf();
      g.era?.resize?.(hw, hh);
    };
    fit();
    onReady(renderer);
    const applyStill = () => document.documentElement.classList.toggle('still', still());
    applyStill();
    const offSettings = g.bus.on('settings', applyStill);
    window.addEventListener('resize', fit);

    let mouseX = window.innerWidth / 2;
    let mouseY = window.innerHeight / 2;
    let spaceDown = false;
    // Whether focus was last moved with Tab (not a click): only then does a focused button take Space.
    let tabbed = false;
    const pointed = () => (tabbed = false);
    window.addEventListener('pointerdown', pointed, true);

    const send = (type: PointerInfo['type'], sx: number, sy: number, id: number, primary: boolean) => {
      const [x, y] = renderer.camera.screenToWorld(sx, sy, renderer.cssW, renderer.cssH);
      g.pointer({ type, x, y, sx, sy, id, primary });
    };
    // Pointers held on the cosmos, so a hold can be let go when the window loses focus mid-press.
    const held = new Set<number>();
    const down = (e: PointerEvent) => {
      audio().unlock();
      if (ui.panel) ui.panel = null;
      canvas.setPointerCapture(e.pointerId);
      held.add(e.pointerId);
      send('down', e.clientX, e.clientY, e.pointerId, e.isPrimary);
    };
    const move = (e: PointerEvent) => {
      mouseX = e.clientX;
      mouseY = e.clientY;
      send('move', e.clientX, e.clientY, e.pointerId, e.isPrimary);
    };
    const up = (e: PointerEvent) => {
      held.delete(e.pointerId);
      send('up', e.clientX, e.clientY, e.pointerId, e.isPrimary);
    };
    const cancel = (e: PointerEvent) => {
      held.delete(e.pointerId);
      send('cancel', e.clientX, e.clientY, e.pointerId, e.isPrimary);
    };
    /** Lets go of every hold (Space and pointers): no keyup or pointerup arrives once focus is gone. */
    const release = () => {
      if (spaceDown) {
        spaceDown = false;
        send('up', mouseX, mouseY, -1, true);
      }
      for (const id of held) send('cancel', mouseX, mouseY, id, true);
      held.clear();
    };
    // Ctrl+1–9 buys the most only in the desktop shell; in a browser those keys switch tabs.
    const ctrlDigits = native() !== null;
    canvas.addEventListener('pointerdown', down);
    canvas.addEventListener('pointermove', move);
    canvas.addEventListener('pointerup', up);
    canvas.addEventListener('pointercancel', cancel);
    canvas.addEventListener('contextmenu', (e) => e.preventDefault());

    const keydown = (e: KeyboardEvent) => {
      ui.shift = e.shiftKey;
      ui.ctrl = e.ctrlKey || e.metaKey;
      const target = e.target as HTMLElement | null;
      // Over the multiverse or the ending, panels would open unseen beneath them.
      const covered = g.state.meta.atMultiverse || ui.ending !== null;
      // Esc always backs out, even from a text field: the offline card first, then any panel.
      if (e.key === 'Escape' && !e.repeat) {
        audio().unlock();
        if (ui.offline) ui.offline = null;
        else if (ui.panel) ui.panel = null;
        else if (!covered) ui.panel = 'settings';
        return;
      }
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) return;
      if (e.key === 'Tab') tabbed = true;
      // A control reached by keyboard takes its own Space; one focused by a click leaves Space to the game.
      if (e.code === 'Space' && (tabbed || ui.offline) && target?.closest('button')) return;
      audio().unlock();
      if (e.code === 'Space') {
        e.preventDefault();
        if (!spaceDown) {
          spaceDown = true;
          send('down', mouseX, mouseY, -1, true);
        }
        return;
      }
      if (e.repeat || ui.offline) return;
      // By key position, so Shift+1 (which types "!") still buys ten.
      const digit = /^(?:Digit|Numpad)([1-9])$/.exec(e.code);
      if (digit && !e.altKey && !covered && (ctrlDigits || !ui.ctrl)) {
        const id = hotkeyTargets(g)[Number(digit[1]) - 1];
        if (id) {
          e.preventDefault();
          const mode = ui.ctrl ? Infinity : ui.shift ? 10 : ui.buyMode;
          if (g.buy(id, mode) === 0) audio().cue('ui.deny', {});
        }
        return;
      }
      // Browser and system shortcuts (Ctrl+C, Ctrl+T, Alt+U) are not game keys.
      if (e.ctrlKey || e.metaKey || e.altKey || covered) return;
      const k = e.key.toLowerCase();
      if (k === 't') advance(g);
      else if (k === 'c') ui.panel = ui.panel === 'codex' ? null : 'codex';
      else if (k === 'u') ui.panel = ui.panel === 'universe' ? null : 'universe';
    };
    const keyup = (e: KeyboardEvent) => {
      ui.shift = e.shiftKey;
      ui.ctrl = e.ctrlKey || e.metaKey;
      if (e.code === 'Space' && spaceDown) {
        spaceDown = false;
        send('up', mouseX, mouseY, -1, true);
      }
    };
    window.addEventListener('keydown', keydown);
    window.addEventListener('keyup', keyup);

    const vis = () => {
      if (document.hidden) release();
      g.setHidden(document.hidden);
      audio().setMuted(document.hidden && g.state.settings.muteOnBlur);
    };
    const blur = () => {
      release();
      ui.shift = false;
      ui.ctrl = false;
      if (g.state.settings.muteOnBlur) audio().setMuted(true);
    };
    const focus = () => audio().setMuted(false);
    document.addEventListener('visibilitychange', vis);
    window.addEventListener('blur', blur);
    window.addEventListener('focus', focus);
    window.addEventListener('pagehide', () => g.persist());

    return () => {
      window.removeEventListener('resize', fit);
      offSettings();
      window.removeEventListener('keydown', keydown);
      window.removeEventListener('keyup', keyup);
      window.removeEventListener('pointerdown', pointed, true);
      document.removeEventListener('visibilitychange', vis);
      window.removeEventListener('blur', blur);
      window.removeEventListener('focus', focus);
    };
  });
</script>

<canvas class="cosmos" bind:this={canvas} tabindex="-1"></canvas>

{#if failed}
  <div class="failed">
    <h1>This device can't draw the universe.</h1>
    <p>Ylem needs WebGL 2, which isn't available here ({failed}). Updating the browser or graphics driver usually fixes it.</p>
  </div>
{:else}
  <Floaters />
  <Labels />
  {#if hud.framed}
    <Frame hidden={hud.hidden} />
  {:else}
    <div class="scrim" class:hidden={hud.hidden} aria-hidden="true"></div>
    <div class="hud" class:hidden={hud.hidden} class:panel-open={ui.panel !== null} class:finale={hud.finale}>
      <div class="tl"><Clock /></div>
      <div class="tc"><Timeline /></div>
      <div class="tr">
        <Energy />
        <div class="ph"><Phenomena /></div>
      </div>
      <div class="bl"><Stocks /></div>
      <div class="br"><Menu /></div>
    </div>
    <div class="bottom" class:hidden={hud.hidden}>
      <Toasts />
      <Hint />
    </div>
  {/if}
  <EraTitle />
  <Offline />
  {#if ui.panel === 'codex'}<Codex />{/if}
  {#if ui.panel === 'universe'}<Universe />{/if}
  {#if ui.panel === 'settings'}<Settings />{/if}
  {#if hud.perf}<Perf />{/if}
  <Multiverse />
  <Ending />
  {#if import.meta.env.DEV}<Skip />{/if}
{/if}

<style>
  /*
   * A static, very soft darkening behind the HUD corners so small type stays legible over bright
   * scenes (the Soup, the Afterglow). Painted once; no filters, nothing animated per frame.
   */
  .scrim {
    position: fixed;
    inset: 0;
    pointer-events: none;
    background:
      radial-gradient(42rem 18rem at 0 0, rgb(0 0 0 / 0.34), transparent 70%),
      radial-gradient(36rem 14rem at 0 100%, rgb(0 0 0 / 0.32), transparent 70%),
      radial-gradient(30rem 16rem at 100% 0, rgb(0 0 0 / 0.3), transparent 70%),
      radial-gradient(30rem 10rem at 100% 100%, rgb(0 0 0 / 0.26), transparent 70%),
      radial-gradient(44rem 9rem at 50% 100%, rgb(0 0 0 / 0.22), transparent 70%);
    transition:
      opacity 1.4s var(--ease),
      visibility 1.4s;
  }
  .hud {
    text-shadow: var(--halo);
    position: fixed;
    inset: 0;
    padding: var(--gutter);
    display: grid;
    /* minmax(0, …): at large interface sizes the side columns shrink to fit instead of running off-screen. */
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
    pointer-events: none;
    transition:
      opacity 1.4s var(--ease),
      visibility 1.4s;
  }
  /* Hidden also takes the controls out of the Tab order, so focus never lands on something invisible. */
  .hidden {
    opacity: 0;
    visibility: hidden;
    pointer-events: none !important;
  }
  .hidden :global(*) {
    pointer-events: none !important;
  }
  .tl {
    grid-column: 1;
    grid-row: 1;
    align-self: start;
  }
  .tc {
    grid-column: 2;
    grid-row: 1;
    padding-top: 0.6rem;
  }
  .finale .ph {
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition:
      opacity 1.2s var(--ease),
      visibility 1.2s;
  }
  .panel-open .tr,
  .panel-open .br {
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
  }
  .tr,
  .br {
    transition:
      opacity 240ms var(--ease),
      visibility 240ms;
  }
  .tr {
    grid-column: 3;
    grid-row: 1 / 3;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    min-height: 0;
  }
  .ph {
    margin-top: 1.4rem;
    min-height: 0;
    display: flex;
    flex: 1;
  }
  .bl {
    grid-column: 1;
    grid-row: 3;
    align-self: end;
  }
  .br {
    grid-column: 3;
    grid-row: 3;
    justify-self: end;
    align-self: end;
  }
  .bottom {
    position: fixed;
    left: 50%;
    bottom: calc(var(--gutter) + 0.4rem);
    translate: -50% 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.9rem;
    pointer-events: none;
    width: min(46rem, 80vw);
    transition:
      opacity 1.4s var(--ease),
      visibility 1.4s;
  }
  .failed {
    position: fixed;
    inset: 0;
    display: grid;
    place-content: center;
    text-align: center;
    padding: 2rem;
  }
  .failed h1 {
    font-family: var(--serif);
    font-weight: 400;
    font-size: 2rem;
  }
  .failed p {
    color: var(--ink-3);
    max-width: 32rem;
  }
</style>
