/**
 * Rendered sound (version 2): files made offline by tools/sound and played back as they are, on the
 * engine's dry buses (they carry their own rooms). An era's bed is a set of synchronized looping stems
 * whose levels follow how busy the player is; effects come in variants (chord tones, levels) that the
 * era's cues choose between. Each era decodes what it plays often when it starts (before the first
 * gesture, for the era a session opens in), keeps the rest encoded until asked for, and lets go of
 * everything when it ends. A sound asked for before its file has decoded starts late, where it would
 * have reached.
 */
import type { AudioEngine, BusName } from './engine';

/** Where the files live, relative to the page (builds use relative asset paths). */
const BASE = 'audio/v2/';

/** Decoded PCM is float32 per channel per frame. */
const BYTES_PER_SAMPLE = 4;

/** Seconds a lazily decoded file stays decoded after it last played (past its own length). */
const LAZY_KEEP = 20;

export class SampleBank {
  private buffers = new Map<string, AudioBuffer>();
  private pending = new Map<string, Promise<AudioBuffer | null>>();
  /** Encoded files kept for lazy decoding: rare sounds decode when first played. */
  private encoded = new Map<string, Promise<ArrayBuffer | null>>();
  /** Files that could not be fetched or decoded: never asked for again (no retries, one warning). */
  private failed = new Set<string>();
  /** What the current era can request; null until an era has said. */
  private wanted: ReadonlySet<string> | null = null;
  private lazy = new Set<string>();
  /** Context time each lazily decoded file was last played until. */
  private busyUntil = new Map<string, number>();

  /**
   * `available` lists the files the build has (null: unknown, ask for anything); a file not on it is
   * never fetched, so an absent one costs no request and no console error.
   */
  constructor(
    private readonly engine: AudioEngine,
    private readonly available: ReadonlySet<string> | null = null,
  ) {}

  /** A file that cannot play: absent from the build, or it failed to fetch or decode. */
  missing(name: string): boolean {
    return this.failed.has(name) || (this.available !== null && !this.available.has(name));
  }

  /**
   * What an era can request: `eager` files decode now, `lazy` ones are fetched now and decode when
   * first played. Everything else is let go (a file still playing finishes; its voice holds it).
   */
  prepare(eager: Iterable<string>, lazy: Iterable<string>): void {
    const e = new Set(eager);
    this.lazy = new Set([...lazy].filter((n) => !e.has(n)));
    this.wanted = new Set([...e, ...this.lazy]);
    for (const k of [...this.buffers.keys()]) if (!this.wanted.has(k)) this.buffers.delete(k);
    for (const k of [...this.encoded.keys()]) if (!this.wanted.has(k)) this.encoded.delete(k);
    for (const k of [...this.busyUntil.keys()]) if (!this.wanted.has(k)) this.busyUntil.delete(k);
    for (const n of e) void this.load(n);
    for (const n of this.lazy) void this.fetchBytes(n);
  }

  load(name: string): Promise<AudioBuffer | null> {
    const hit = this.buffers.get(name);
    if (hit) return Promise.resolve(hit);
    const ctx = this.engine.ctx;
    if (!ctx || this.missing(name)) return Promise.resolve(null);
    let p = this.pending.get(name);
    if (!p) {
      p = this.fetchBytes(name)
        // A lazy file decodes from a copy: decoding takes the bytes it is given, and it may decode again.
        .then((b) => (b ? ctx.decodeAudioData(this.lazy.has(name) ? b.slice(0) : b) : null))
        .then((buf) => {
          // An era that has moved on no longer wants it.
          if (buf && (!this.wanted || this.wanted.has(name))) this.buffers.set(name, buf);
          // A lazy one is let go a while from now even if it never gets to play.
          if (buf) this.played(name, this.engine.now);
          return buf;
        })
        .catch((e: unknown) => this.fail(name, e))
        .finally(() => this.pending.delete(name));
      this.pending.set(name, p);
    }
    return p;
  }

  private fetchBytes(name: string): Promise<ArrayBuffer | null> {
    if (this.missing(name)) return Promise.resolve(null);
    let p = this.encoded.get(name);
    if (!p) {
      p = fetch(`${BASE}${name}.ogg`)
        .then((r) => (r.ok ? r.arrayBuffer() : Promise.reject(new Error(`${name}.ogg: ${r.status}`))))
        .catch((e: unknown) => this.fail(name, e));
      // Only lazy files keep their bytes; an eager one is decoded once and its bytes go.
      if (this.lazy.has(name)) this.encoded.set(name, p);
    }
    return p;
  }

  private fail(name: string, e: unknown): null {
    this.encoded.delete(name);
    if (this.failed.has(name)) return null;
    console.warn('[sound]', e);
    this.failed.add(name);
    this.onFail?.(name);
    return null;
  }

  /** A decoded file, if it is ready. */
  get(name: string): AudioBuffer | undefined {
    return this.buffers.get(name);
  }

  /** A file is playing until `until` (context time): a lazy one stays decoded until a while after. */
  played(name: string, until: number): void {
    if (this.lazy.has(name)) this.busyUntil.set(name, Math.max(until, this.busyUntil.get(name) ?? 0));
  }

  /** Called with the name of each file that fails (once per file). */
  onFail: ((name: string) => void) | null = null;

  /** Lets go of lazily decoded files that have not played for a while (call now and then). */
  sweep(): void {
    const t = this.engine.now;
    for (const [k, until] of this.busyUntil) {
      if (t < until + LAZY_KEEP) continue;
      this.buffers.delete(k);
      this.busyUntil.delete(k);
    }
  }

  /** Decoded PCM held now, in bytes (QA). */
  get residentBytes(): number {
    let n = 0;
    for (const b of this.buffers.values()) n += b.length * b.numberOfChannels * BYTES_PER_SAMPLE;
    return n;
  }

  /** Files decoded now (QA). */
  get resident(): string[] {
    return [...this.buffers.keys()];
  }
}

export interface SampleVoice {
  /** Null while its file is still decoding: it starts late, where it would have reached. */
  src: AudioBufferSourceNode | null;
  gain: GainNode;
  /** Set once stopped: a voice still waiting for its file then never starts. */
  stopped: boolean;
  /** Its place in the voice cap, once started (a voice played once). */
  claim?: { end: number };
}

export interface PlayOptions {
  bus?: BusName;
  gain?: number;
  /** −1 … 1 */
  pan?: number;
  /** Context time to start (default now) and where in the file. */
  at?: number;
  offset?: number;
  loop?: boolean;
  fadeIn?: number;
}

/**
 * How late an effect that waited for its file may still start (seconds): a click's sound a moment
 * late reads as the click's, later than that as something else. Music and loops always catch up.
 */
export const EFFECT_LATE = 0.25;

/** A voice with its gain (and pan) connected, waiting for a buffer. */
export function voiceFor(engine: AudioEngine, o: PlayOptions = {}): SampleVoice | null {
  const ctx = engine.ctx;
  if (!ctx) return null;
  const gain = ctx.createGain();
  gain.gain.value = 0;
  let out: AudioNode = gain;
  if (o.pan) {
    const p = ctx.createStereoPanner();
    p.pan.value = Math.max(-1, Math.min(1, o.pan));
    gain.connect(p);
    out = p;
  }
  out.connect(engine.dry(o.bus ?? 'sfx'));
  return { src: null, gain, stopped: false };
}

/**
 * Starts a waiting voice on its buffer. `o.at` is when it was meant to start: one that is late begins
 * now, music and loops at the offset they would have reached, effects from the top (or not at all
 * past EFFECT_LATE). Returns the context time it ends at (Infinity for a loop), or null if it did not start.
 */
export function startVoice(engine: AudioEngine, v: SampleVoice, buf: AudioBuffer, o: PlayOptions = {}): number | null {
  const ctx = engine.ctx;
  if (!ctx || v.stopped || v.src) return null;
  const now = ctx.currentTime;
  const meant = o.at ?? now;
  const late = Math.max(0, now - meant);
  const bus = o.bus ?? 'sfx';
  const catchUp = bus !== 'sfx' || !!o.loop;
  if (!catchUp && late > EFFECT_LATE) return null;
  let offset = Math.max(0, o.offset ?? 0) + (catchUp ? late : 0);
  if (o.loop) offset %= buf.duration;
  else if (offset >= buf.duration - 0.01) return null;
  const t = Math.max(meant, now);
  const src = ctx.createBufferSource();
  src.buffer = buf;
  src.loop = !!o.loop;
  const g = o.gain ?? 1;
  const p = v.gain.gain;
  // A sound caught up mid-way fades in briefly, so it does not start on a click.
  const fadeIn = o.fadeIn ?? (late > 0 && offset > 0 ? 0.03 : 0);
  if (fadeIn) {
    p.setValueAtTime(0, t);
    p.linearRampToValueAtTime(g, t + fadeIn);
  } else p.setValueAtTime(g, t);
  src.connect(v.gain);
  src.start(t, offset);
  v.src = src;
  const end = o.loop ? Infinity : t + buf.duration - offset;
  // An effect can be stolen when the cap is full (the oldest is deep in its room tail by then, so a
  // quick fade is not heard); music played once (a transition, a finale) never is.
  const steal = bus === 'sfx' ? () => fadeOutVoice(engine, v, 0.12) : undefined;
  if (!o.loop) v.claim = engine.claimVoice(end, steal);
  return end;
}

/** Plays a loaded buffer on a dry bus. */
export function playBuffer(engine: AudioEngine, buf: AudioBuffer, o: PlayOptions = {}): SampleVoice | null {
  const v = voiceFor(engine, o);
  if (!v) return null;
  return startVoice(engine, v, buf, o) === null ? null : v;
}

/** Fades a voice out and stops it (one still waiting for its file never starts). */
export function fadeOutVoice(engine: AudioEngine, v: SampleVoice | null, seconds: number): void {
  const ctx = engine.ctx;
  if (!ctx || !v || v.stopped) return;
  v.stopped = true;
  if (!v.src) return;
  const t = ctx.currentTime;
  const g = v.gain.gain;
  g.cancelScheduledValues(t);
  g.setValueAtTime(g.value, t);
  g.linearRampToValueAtTime(0, t + Math.max(0.01, seconds));
  try {
    v.src.stop(t + Math.max(0.01, seconds) + 0.05);
  } catch {
    // Already stopped.
  }
  if (v.claim) v.claim.end = Math.min(v.claim.end, t + Math.max(0.01, seconds) + 0.1);
}

/** Seconds ahead a late stem is scheduled, so it starts exactly where the loop is (sample-locked to the others). */
const STEM_LEAD = 0.05;

/**
 * An era's bed: stems that loop together. `layers` turns the activity (0 calm … 1 busy, smoothed)
 * into each stem's level, by stem; the first stem is the base, always on. Each stem starts as soon as
 * its file has decoded, where the loop is, so one that arrives late joins in time with the rest.
 */
export class StemBed {
  /** One per stem, in stem order (empty until that stem has started). */
  private voices: (SampleVoice | undefined)[] = [];
  private start = 0;
  private fadeEnd = 0;
  private level = 1;
  /** How busy the player is, smoothed over several seconds (0–1). */
  activity = 0;
  private busy = 0;
  private stopped = false;

  /** `busy`: events a second that read as fully busy (activity 1). */
  constructor(
    private readonly engine: AudioEngine,
    private readonly bank: SampleBank,
    readonly id: string,
    readonly names: readonly string[],
    readonly loop: number,
    private readonly layers: (activity: number) => number[],
    private readonly busyRate = 4,
  ) {}

  /**
   * Starts the stems together, fading in over `fade` seconds after `delay`; a stem whose file comes
   * later joins where the loop is. Resolves false if the base stem cannot play (the era then needs
   * another bed).
   */
  async begin(fade: number, delay = 0): Promise<boolean> {
    const ctx = this.engine.ctx;
    if (!ctx) return false;
    this.start = ctx.currentTime + 0.1 + delay;
    this.fadeEnd = this.start + fade;
    const started = await Promise.all(
      this.names.map(async (n, i) => {
        const b = await this.bank.load(n);
        if (b && !this.stopped) this.join(i, b);
        return !!b;
      }),
    );
    return started[0] ?? false;
  }

  private join(i: number, b: AudioBuffer): void {
    const ctx = this.engine.ctx;
    if (!ctx) return;
    const at = Math.max(this.start, ctx.currentTime + STEM_LEAD);
    const v = voiceFor(this.engine, { bus: 'music' });
    if (!v) return;
    startVoice(this.engine, v, b, { bus: 'music', loop: true, at, offset: at - this.start, gain: 0 });
    const level = this.levelOf(i);
    v.gain.gain.setValueAtTime(0, at);
    v.gain.gain.linearRampToValueAtTime(level, Math.max(this.fadeEnd, at + 1));
    this.voices[i] = v;
  }

  private levelOf(i: number): number {
    return (this.layers(this.activity)[i] ?? 0) * this.level;
  }

  /** Seconds into the loop now (where the harmony is). */
  position(): number {
    const ctx = this.engine.ctx;
    if (!ctx) return 0;
    const t = ctx.currentTime - this.start;
    return t < 0 ? 0 : t % this.loop;
  }

  /** Something happened (a click, an event): the bed grows busier. */
  bump(amount = 1): void {
    this.busy += amount;
  }

  /** Called ~20 times a second: smooth the activity and move the stems' levels toward it. */
  tick(dt: number): void {
    const ctx = this.engine.ctx;
    if (!ctx || this.stopped) return;
    // Events per second, smoothed over ~6 s, mapped to 0–1 (`busyRate` a second reads as busy). The
    // rate is smoothed before it is capped: a single event fills its tick many times over, so capping
    // each tick first would make four events a second read as 0.2. It runs while the stems load too,
    // so what happens meanwhile is spread over its own time rather than piled onto the first tick.
    this.activity = Math.min(1, this.activity + (this.busy / dt / this.busyRate - this.activity) * (1 - Math.exp(-dt / 6)));
    this.busy = 0;
    const t = ctx.currentTime;
    if (t < this.fadeEnd) return;
    this.voices.forEach((v, i) => v?.gain.gain.setTargetAtTime(this.levelOf(i), t, 1.2));
  }

  /** Ducks the whole bed (0–1) over `seconds`. */
  setLevel(level: number, seconds = 1.5): void {
    this.level = level;
    const ctx = this.engine.ctx;
    if (!ctx) return;
    this.voices.forEach((v, i) => v?.gain.gain.setTargetAtTime(this.levelOf(i), ctx.currentTime, seconds / 3));
  }

  stop(fade: number): void {
    this.stopped = true;
    for (const v of this.voices) if (v) fadeOutVoice(this.engine, v, fade);
    this.voices = [];
  }
}
