/**
 * UI state. The game model is plain TypeScript; the interface samples it on a fixed tick
 * (`ui.tick`, ~20 Hz) instead of making game state deeply reactive.
 */
import type { Game } from '../core/game';
import type { AudioDirector } from '../audio/director';
import type { NumParts } from '../core/format';

let gameRef: Game | null = null;
let audioRef: AudioDirector | null = null;

export function setGame(g: Game, a: AudioDirector): void {
  gameRef = g;
  audioRef = a;
}

export function game(): Game {
  if (!gameRef) throw new Error('Game not initialised');
  return gameRef;
}

export function audio(): AudioDirector {
  if (!audioRef) throw new Error('Audio not initialised');
  return audioRef;
}

export type Panel = 'codex' | 'universe' | 'settings' | null;

export interface Toast {
  id: number;
  text: string;
  tone: 'quiet' | 'milestone' | 'discovery';
  /** Codex id to open when clicked. */
  codex?: string;
  born: number;
  /** Discoveries merged into this toast (a kilonova can make several elements at once). */
  names?: string[];
}

export interface EraCard {
  key: number;
  title: string;
  epoch: string;
  time: NumParts;
}

export interface OfflineCard {
  seconds: number;
  energy: number;
  lines: { label: string; value: string }[];
}

export const ui = $state({
  tick: 0,
  panel: null as Panel,
  codexFocus: null as string | null,
  toasts: [] as Toast[],
  eraCard: null as EraCard | null,
  offline: null as OfflineCard | null,
  /** Buy multiplier for levelled phenomena: 1, 10 or Infinity (max). */
  buyMode: 1 as number,
  /** The ending's current movement, while it plays. */
  ending: null as 'words' | 'light' | 'title' | 'done' | null,
  shift: false,
  ctrl: false,
});

/**
 * Reduce motion is on (a new save takes it from the system preference). Transitions read it when
 * they start; CSS reads `--motion`, which App sets to 0 through the `still` class on the root.
 */
export function still(): boolean {
  return gameRef?.state.settings.reduceMotion ?? false;
}

/** Read inside `$derived.by` to recompute on every UI tick. */
export function track(): number {
  return ui.tick;
}

let toastId = 1;

/** Discoveries this close together read as one: "Gold · Platinum · Europium". */
const MERGE_MS = 700;

export function pushToast(text: string, tone: Toast['tone'], codex?: string): void {
  const now = performance.now();
  const last = ui.toasts[ui.toasts.length - 1];
  if (tone === 'discovery' && last?.tone === 'discovery' && now - last.born < MERGE_MS) {
    const names = [...(last.names ?? [last.text]), text];
    last.names = names;
    last.text = names.length <= 3 ? names.join(' · ') : `${names.slice(0, 3).join(' · ')} and ${names.length - 3} more`;
    last.born = now;
    return;
  }
  ui.toasts.push({ id: toastId++, text, tone, codex, born: now });
  if (ui.toasts.length > 4) ui.toasts.splice(0, ui.toasts.length - 4);
}

export function dismissToast(id: number): void {
  const i = ui.toasts.findIndex((t) => t.id === id);
  if (i >= 0) ui.toasts.splice(i, 1);
}
