/**
 * How the Soup looks (version 2). The simulation says what is where; this draws it.
 *
 * - The medium: a deep plasma glowing by its own heat, red-hot through and through early on (its dim
 *   matter glowing red like embers, gold where hottest, a deep blue fill in its coolest folds), with
 *   a storm of crisp white-hot specks in depth seething in slow eddies. It dims toward a dark red as
 *   the era advances, and the specks burn down to gold and ember.
 * - Quarks: white-hot points in a halo of their colour charge that light the plasma around them;
 *   antiquarks also wear a thin ring (antimatter is always shape-coded).
 * - Gluon strings: discharge streamers. A white-hot thread inside a translucent sheath whose colour
 *   turns around the hue circle from the quark's to the antiquark's, deepening toward its fringe,
 *   flaring into a glowing foot where it meets each quark; vibrating, brighter and thinner under
 *   tension.
 * - Photons: wave packets racing out of each annihilation.
 * - Effects (the era's FxPool, restyled): flashes are point spreads that light the medium; rings are
 *   light fronts through the plasma and pushes through the specks rather than drawn circles; sparks
 *   are streaks.
 */
import type { FxLook } from '../../render/fx';
import { Filaments } from '../../render/filaments';
import { Plasma } from '../../render/plasma';
import type { BackgroundDef, Renderer } from '../../render/renderer';
import type { PostParams } from '../../render/post';
import { Shape } from '../../render/sprites';
import { Storm, type StormKick, type StormLight } from '../../render/storm';
import type { VolumeFront, VolumeLight, VolumeTube } from '../../render/volume';
import { Best, packet } from './light';

type RGB = readonly [number, number, number];

const HOT: [number, number, number] = [1.0, 0.95, 0.88];
const GOLD: [number, number, number] = [1.0, 0.7, 0.36];
const ICE: [number, number, number] = [0.7, 0.82, 1.0];
/** The Soup's photons: hard light, a cool white against the warm plasma. */
const GAMMA: RGB = [0.5, 0.66, 1.0];
const WHITE: RGB = [1, 1, 1];

const BLACK: BackgroundDef = {
  id: 'soup-v2',
  fragment: /* glsl */ `
void main() {
  outColor = vec4(0.0006, 0.0005, 0.0008, 1.0);
}`,
};

/** The post settings this look is graded for. */
const POST: Partial<PostParams> = { bloom: 0.25, bloomThreshold: 1.4, glare: 0.35, glareThreshold: 3, saturation: 1.25, punch: 1.2, vignette: 0.45, grain: 0.012 };

const lum = (r: number, g: number, b: number) => 0.2126 * r + 0.7152 * g + 0.0722 * b;

/** Most points one string is drawn with (its curve, plus the feet past each end). */
const STRING_PTS = 72 + 1 + 2 * 5;
/** Points past each end of a string, where its foot closes round the quark. */
const FOOT_PTS = 5;

export class SoupLook implements FxLook {
  readonly plasma = new Plasma({ depth: 900, near: 450, focal: 1600, cellSize: 1100, heat: 0.7, brightness: 0.27, absorb: 0.0025, lanes: 0.95, fade: 300, scale: 0.6, boil: 0.015, ember: 1, cool: [0.05, 0.03, 0.2] });
  readonly storm = new Storm({
    count: 22000,
    depth: 900,
    focal: 1600,
    lifeMin: 1.5,
    lifeMax: 5,
    swirl: 16,
    swirlScale: 520,
    drag: 3,
    jitter: 6,
    spread: 0.004,
    faintest: 0.03,
    peak: 12,
    magnitudePower: 1,
    halo: 0,
    twinkle: 0.35,
    palette: [HOT, GOLD, ICE, [1.0, 0.36, 0.26], [0.4, 1.0, 0.5], [0.4, 0.58, 1.0], [1.1, 1.1, 1.2], HOT],
    weights: [3, 3, 1.4, 0.06, 0.06, 0.06, 0.6, 1],
  });
  readonly filaments = new Filaments();
  /** The storm's settings before confinement calms it. */
  private readonly calm = { ...this.storm.config };
  private r: Renderer | null = null;
  private saved: Partial<PostParams> = {};
  private readonly lights = new Best<VolumeLight>(8, () => ({ x: 0, y: 0, z: 0, radius: 1, color: [0, 0, 0] }));
  private readonly fronts = new Best<VolumeFront>(4, () => ({ x: 0, y: 0, radius: 1, width: 1, color: [0, 0, 0] }));
  private readonly kicks = new Best<StormKick>(4, () => ({ x: 0, y: 0, radius: 1, push: 0 }));
  private readonly speckLights = new Best<StormLight>(8, () => ({ x: 0, y: 0, intensity: 0, radius: 1, width: 0 }));
  private readonly tubes = new Best<VolumeTube>(6, () => ({ ax: 0, ay: 0, az: 0, bx: 0, by: 0, bz: 0, radius: 1, color: [0, 0, 0] }));
  /** Scratch for one string (the filaments copy it), and for a spark's streak. */
  private readonly sPts = new Float32Array(STRING_PTS * 2);
  private readonly sCore = new Float32Array(STRING_PTS);
  private readonly sSheath = new Float32Array(STRING_PTS);
  private readonly sHalf = new Float32Array(STRING_PTS);
  private readonly kPts = new Float32Array(6);
  private readonly kCore = new Float32Array(3);
  private readonly kSheath = new Float32Array(3);
  private readonly kColor: [number, number, number] = [0, 0, 0];
  private time = 0;
  /** The last `cooling` (the specks' heat follows it). */
  private cooled = 0;

  constructor() {
    this.filaments.ribbon = true;
    this.filaments.arc = true;
  }

  attach(r: Renderer): void {
    this.r = r;
    r.setBackground(BLACK);
    r.setLayers([this.plasma, this.storm, this.filaments]);
    const post = r.post as unknown as Record<string, unknown>;
    for (const [k, v] of Object.entries(POST)) {
      (this.saved as Record<string, unknown>)[k] = post[k];
      post[k] = v;
    }
  }

  detach(r: Renderer): void {
    r.setLayers([]);
    Object.assign(r.post, this.saved);
    this.r = null;
  }

  /**
   * How far the era has cooled, 0 (the start) to 1 (confinement). Early the plasma is red-hot through
   * and through (its dim matter glowing red, never brown) and seething with white-hot specks; it
   * dims toward a dark red as it cools, and its specks burn down to gold and ember.
   */
  set cooling(c: number) {
    this.cooled = c;
    const p = this.plasma.config;
    p.heat = 0.7 - 0.32 * c;
    p.brightness = 0.27 - 0.07 * c;
    const w = this.storm.config.weights;
    const hot = 1 - c;
    w[0] = 2.6 + 1.9 * hot;
    w[1] = 2.2 + 1.2 * c;
    w[3] = 0.06 + 0.5 * c;
    w[6] = 0.4 + 1.0 * hot;
  }

  /** The confinement crossover, 0 → 1: the specks the plasma carries calm, slow and fade with it. */
  set confinement(c: number) {
    const s = this.storm.config;
    const b = this.calm;
    const hot = 1 - this.cooled;
    s.jitter = b.jitter * (1 - 0.75 * c);
    s.swirl = b.swirl * (1 - 0.55 * c);
    s.peak = b.peak * (1 + 0.7 * hot) * (1 - 0.6 * c);
    s.faintest = b.faintest * (1 + 0.6 * hot) * (1 - 0.55 * c);
    s.twinkle = b.twinkle * (1 - 0.6 * c);
  }

  /**
   * Drawing a copy of the periodic box (the view around the frame's field shows its copies, so space
   * visibly goes on): matter is drawn, but nothing reaches the medium (no lights, tubes, fronts or
   * pushes), which is one continuous space and already lit by the box itself.
   */
  ghost = false;

  /** Starts a frame (the effect lists refill every frame); `t` is the era's clock. */
  begin(r: Renderer, t = this.time): void {
    this.r = r;
    this.time = t;
    this.lights.reset();
    this.fronts.reset();
    this.kicks.reset();
    this.speckLights.reset();
    this.tubes.reset();
  }

  /** A light inside the medium; `key` (non-zero) names a light that persists from frame to frame. */
  light(x: number, y: number, radius: number, c: RGB, key = 0): void {
    this.glow(x, y, radius, c[0], c[1], c[2], key);
  }

  /** `light` with its colour given channel by channel. */
  glow(x: number, y: number, radius: number, r: number, g: number, b: number, key = 0): void {
    if (this.ghost) return;
    const L = this.lights.take(lum(r, g, b) * radius, key);
    if (!L) return;
    L.x = x;
    L.y = y;
    L.z = 0;
    L.radius = radius;
    L.color[0] = r;
    L.color[1] = g;
    L.color[2] = b;
  }

  /** A quark (or antiquark, with its ring): a white-hot point in a halo of its colour that lights the plasma. */
  quark(x: number, y: number, c: RGB, k: number, anti: boolean, heavy = false, t = 0, seed = 0): void {
    const r = this.r;
    if (!r || k <= 0) return;
    const s = heavy ? 1.25 : 1;
    r.top.push(x, y, 2.2 * s, 16 * k, 15.5 * k, 15 * k, 1, Shape.Glow);
    r.top.push(x, y, 10 * s, c[0] * 2.2 * k, c[1] * 2.2 * k, c[2] * 2.2 * k, 1, Shape.Glow);
    r.top.push(x, y, 34 * s, c[0] * 0.22 * k, c[1] * 0.22 * k, c[2] * 0.22 * k, 1, Shape.Glow);
    if (anti) r.top.push(x, y, 8 * s, c[0] * 1.6 * k, c[1] * 1.6 * k, c[2] * 1.6 * k, 1, Shape.Ring, 0.12);
    else {
      // Two or three sparks of virtual gluons flickering close around it.
      for (let i = 0; i < 3; i++) {
        const a = t * (7 + i * 2.3) + seed + (i * Math.PI * 2) / 3;
        const rad = 6 + 3 * Math.sin(t * 5 + i * 1.7 + seed);
        const f = (0.5 + 0.5 * Math.sin(t * 17 + i * 2.1 + seed)) ** 2 * k;
        r.top.push(x + Math.cos(a) * rad, y + Math.sin(a) * rad, 1.2, c[0] * 4 * f, c[1] * 4 * f, c[2] * 4 * f, 1, Shape.Glow);
      }
    }
    // A faint light of its colour in the plasma (a field of green quarks shouldn't turn the medium green).
    this.glow(x, y, 70, c[0] * 0.28 * k, c[1] * 0.28 * k, c[2] * 0.28 * k);
  }

  /**
   * A gluon string from a to b, drawn as a discharge streamer: a white-hot thread in a translucent
   * sheath whose colour turns from `ca` to `cb`, vibrating in standing waves that quicken with
   * `tension` (0–1), energy crawling along the thread, flickering just before it breaks. Where it
   * meets each quark it flares into a glowing foot (`feet` scales them; 0 for none). It also glows
   * softly in the plasma.
   */
  string(ax: number, ay: number, bx: number, by: number, ca: RGB, cb: RGB, tension: number, t: number, k: number, seed: number, feet = 1): void {
    if (k <= 0) return;
    const dx = bx - ax;
    const dy = by - ay;
    const len = Math.hypot(dx, dy) || 1;
    const nx = -dy / len;
    const ny = dx / len;
    const amp = (1.5 + 7 * tension) * Math.min(1, len / 80);
    const w = 8 + 30 * tension;
    const flicker = tension > 0.85 ? 0.55 + 0.45 * Math.abs(Math.sin(t * 90 + seed) * Math.sin(t * 53)) : 1;
    const segs = this.filaments.segments(Math.max(12, Math.min(72, Math.round(len / 5))));
    const { sPts: pts, sCore: core, sSheath: sheath, sHalf: half } = this;
    const E = FOOT_PTS;
    const m = segs + 1 + 2 * E;
    // The curve itself.
    for (let j = 0; j <= segs; j++) {
      const s = j / segs;
      const off = amp * (Math.sin(Math.PI * s) * Math.sin(w * t + seed) + 0.5 * Math.sin(2 * Math.PI * s) * Math.sin(w * 1.7 * t + 1 + seed) + 0.25 * Math.sin(3 * Math.PI * s) * Math.sin(w * 2.6 * t + 2));
      pts[(j + E) * 2] = ax + dx * s + nx * off;
      pts[(j + E) * 2 + 1] = ay + dy * s + ny * off;
    }
    const e = (0.8 + 2.6 * tension * tension) * flicker * k;
    const hw = 8.5 - 3 * tension;
    // The foot: the sheath widens toward each quark and closes round past it (a cap as wide as the foot).
    const wide = 0.75 * feet;
    const ext = hw * (1 + wide);
    // Past each end, straight on along the end of the curve.
    for (let end = 0; end < 2; end++) {
      const o = end ? segs + E : E;
      const p = end ? o - 1 : o + 1;
      const ex = pts[o * 2] - pts[p * 2];
      const ey = pts[o * 2 + 1] - pts[p * 2 + 1];
      const el = Math.hypot(ex, ey) || 1;
      for (let q = 1; q <= E; q++) {
        const i = end ? o + q : o - q;
        pts[i * 2] = pts[o * 2] + (ex / el) * ext * (q / E);
        pts[i * 2 + 1] = pts[o * 2 + 1] + (ey / el) * ext * (q / E);
      }
    }
    const reach = Math.min(16, len * 0.2);
    for (let i = 0; i < m; i++) {
      const s = Math.min(1, Math.max(0, (i - E) / segs));
      // How far past an end this point is (0 on the string), as a share of the cap.
      const over = i < E ? (E - i) / E : i > segs + E ? (i - segs - E) / E : 0;
      const da = s * len;
      const db = len - da;
      const foot = Math.max(Math.exp(-(da * da) / (reach * reach)), Math.exp(-(db * db) / (reach * reach)));
      const crawl = 1 + 0.45 * Math.sin(26 * s - 15 * t + seed) * Math.sin(9 * s + 6 * t);
      // The sheath breathes a little along its length, as a streamer's does.
      const breathe = 1 + 0.16 * Math.sin(5 * s - 2.2 * t + seed * 1.3) * (1 - foot);
      half[i] = hw * breathe * (1 + wide * foot) * Math.sqrt(Math.max(0, 1 - over * over));
      // The thread ends in the quark's own white-hot point; past it the foot's light rounds off.
      const thread = over > 0 ? Math.max(0, 1 - over * 2.5) ** 2 : 1;
      const round = (1 - over) * (1 - over);
      core[i] = 1.25 * e * crawl * (1 + 0.5 * foot * feet) * thread;
      sheath[i] = 0.5 * e * (1 + 0.12 * (crawl - 1)) * (1 + 0.8 * foot * feet) * round;
    }
    this.filaments.push(pts, ca, cb, half, core, sheath, false, m);
    const g = 0.0011 * (1 + 2 * tension) * flicker * k;
    const tube = this.ghost ? null : this.tubes.take(g * len * lum(ca[0] + cb[0], ca[1] + cb[1], ca[2] + cb[2]));
    if (tube) {
      tube.ax = ax;
      tube.ay = ay;
      tube.bx = bx;
      tube.by = by;
      tube.radius = 26;
      tube.color[0] = (ca[0] + cb[0]) * 0.5 * g;
      tube.color[1] = (ca[1] + cb[1]) * 0.5 * g;
      tube.color[2] = (ca[2] + cb[2]) * 0.5 * g;
    }
  }

  // ─── FxLook: the era's effects, restyled

  flash(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * (1 - t);
    const rr = this.r;
    if (!rr || f <= 0.003) return;
    rr.top.push(x, y, Math.min(4, 1.5 + size * 0.06), r * f * 1.6, g * f * 1.6, b * f * 1.6, 1, Shape.Glow);
    rr.top.push(x, y, size * 0.7, r * f * 0.35, g * f * 0.35, b * f * 0.35, 1, Shape.Glow);
    // The light it leaves in the plasma heats it: warmer than the flash itself (white light over the
    // red-hot medium reads as grey haze).
    this.glow(x, y, size * 2.2, r * f * 0.5, g * f * 0.32, b * f * 0.18);
  }

  ring(x: number, y: number, radius: number, r: number, g: number, b: number, t: number): void {
    const f = Math.pow(1 - t, 1.6);
    if (f <= 0.01 || this.ghost) return;
    const l = lum(r, g, b);
    const front = this.fronts.take(l * f);
    if (front) {
      front.x = x;
      front.y = y;
      front.radius = radius;
      front.width = 30 + radius * 0.08;
      front.color[0] = r * 0.06 * f;
      front.color[1] = g * 0.06 * f;
      front.color[2] = b * 0.06 * f;
    }
    const kick = this.kicks.take(l * f);
    if (kick) {
      kick.x = x;
      kick.y = y;
      kick.radius = radius;
      kick.push = 1800 * Math.min(2, l) * f;
    }
    const sl = this.speckLights.take(l * f);
    if (sl) {
      sl.x = x;
      sl.y = y;
      sl.intensity = (6 * l * f) / (1 + radius / 900);
      sl.radius = radius;
      sl.width = 40 + radius * 0.1;
    }
  }

  spark(x: number, y: number, vx: number, vy: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = 1 - t;
    const k = Math.min(3, size * 0.35) * f;
    if (k <= 0.01) return;
    const tx = x - vx * 0.035;
    const ty = y - vy * 0.035;
    // The streak's colour at unit brightness (its intensity comes from k).
    const l = Math.max(1, lum(r, g, b));
    const c = this.kColor;
    c[0] = r / l;
    c[1] = g / l;
    c[2] = b / l;
    const p = this.kPts;
    p[0] = tx;
    p[1] = ty;
    p[2] = (tx + x) / 2;
    p[3] = (ty + y) / 2;
    p[4] = x;
    p[5] = y;
    this.kCore[0] = 0;
    this.kCore[1] = 0.5 * k;
    this.kCore[2] = 1.6 * k;
    this.kSheath[0] = 0;
    this.kSheath[1] = 0.05 * k;
    this.kSheath[2] = 0.12 * k;
    this.filaments.push(p, c, WHITE, 3.5, this.kCore, this.kSheath, false);
  }

  /** A photon: a wave packet racing out of an annihilation, faint and cool against the plasma. */
  photon(x: number, y: number, vx: number, vy: number, size: number, _r: number, _g: number, _b: number, t: number): void {
    const k = Math.min(1.25, size * 0.24) * Math.min(1, t * 10) * (1 - t * t);
    packet(this.filaments, x, y, vx, vy, k, GAMMA, 10 + 1.6 * size, 12, this.time);
  }

  puff(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * Math.min(1, t * 6);
    if (f > 0.01) this.glow(x, y, size, r * 0.3 * f, g * 0.3 * f, b * 0.3 * f);
  }

  /** Ends the frame: the strongest lights, fronts and pushes go to the layers (each has a few slots). */
  end(): void {
    this.plasma.lights = this.lights.list();
    this.plasma.fronts = this.fronts.list();
    this.plasma.tubes = this.tubes.list();
    this.storm.kicks = this.kicks.list();
    this.storm.lights = this.speckLights.list();
  }
}
