/**
 * How hadrons look (version 2): the bound states confinement makes, drawn in the Soup's vocabulary
 * of point lights and luminous filaments.
 *
 * - A nucleon: a white-hot point where the three colours cancel, shining into the plasma, with three
 *   sparks rattling almost freely close around it (asymptotic freedom), each tied to it by a faint
 *   string (a Y, as in a real baryon). Gluons keep passing colour between the quarks, so each spark's
 *   colour keeps changing while the three together stay white: up close a nucleon shimmers through
 *   the colours like a scintillating star.
 * - An antinucleon: the same in the three anticolours, inside a thin ring (antimatter is always
 *   shape-coded).
 * - A meson: a quark and its antiquark spinning on a short string, the pair glowing white.
 */
import type { Renderer } from '../../render/renderer';
import { Shape } from '../../render/sprites';
import type { SoupLook } from './look';

type RGB = readonly [number, number, number];

/** The white a proton glows (a touch warm) and a neutron's (a touch cool). */
const PROTON: RGB = [1.0, 0.9, 0.8];
const NEUTRON: RGB = [0.84, 0.9, 1.0];

/** Points along a short string. */
const SEG = 8;

export class Hadrons {
  private readonly pts = new Float32Array((SEG + 1) * 2);
  private readonly core = new Float32Array(SEG + 1);
  private readonly sheath = new Float32Array(SEG + 1);
  private readonly qx = [0, 0, 0];
  private readonly qy = [0, 0, 0];
  private readonly qc: [number, number, number][] = [
    [0, 0, 0],
    [0, 0, 0],
    [0, 0, 0],
  ];

  constructor(private readonly look: SoupLook) {}

  /**
   * A short taut string from a to b: a bright filament that barely trembles (it is short and pulled
   * tight), shading from `ca` to `cb`, energy running along it.
   */
  bond(ax: number, ay: number, bx: number, by: number, ca: RGB, cb: RGB, k: number, t: number, seed: number, half: number): void {
    if (k <= 0.003) return;
    const dx = bx - ax;
    const dy = by - ay;
    const len = Math.hypot(dx, dy) || 1;
    const nx = -dy / len;
    const ny = dx / len;
    const amp = 0.35 + 0.03 * len;
    const { pts, core, sheath } = this;
    for (let j = 0; j <= SEG; j++) {
      const s = j / SEG;
      const off = amp * (Math.sin(Math.PI * s) * Math.sin(t * 57 + seed) + 0.4 * Math.sin(2 * Math.PI * s) * Math.sin(t * 89 + seed * 1.3));
      pts[j * 2] = ax + dx * s + nx * off;
      pts[j * 2 + 1] = ay + dy * s + ny * off;
      const crawl = 1 + 0.3 * Math.sin(14 * s - 19 * t + seed);
      core[j] = 0.5 * k * crawl;
      sheath[j] = 0.24 * k * crawl;
    }
    this.look.filaments.push(pts, ca, cb, half, core, sheath);
  }

  /**
   * One leg of a baryon's Y: a short string from a quark to the junction, shading from the quark's
   * colour to white and brightening toward the junction (the colours cancel there).
   */
  private leg(ax: number, ay: number, jx: number, jy: number, c: RGB, white: RGB, k: number, t: number, seed: number, half: number): void {
    const dx = jx - ax;
    const dy = jy - ay;
    const len = Math.hypot(dx, dy) || 1;
    const nx = -dy / len;
    const ny = dx / len;
    const amp = 0.25 + 0.03 * len;
    const { pts, core, sheath } = this;
    for (let j = 0; j <= SEG; j++) {
      const s = j / SEG;
      const off = amp * Math.sin(Math.PI * s) * Math.sin(t * 61 + seed);
      pts[j * 2] = ax + dx * s + nx * off;
      pts[j * 2 + 1] = ay + dy * s + ny * off;
      const crawl = 1 + 0.25 * Math.sin(12 * s - 17 * t + seed);
      core[j] = (0.08 + 0.32 * s) * k * crawl;
      sheath[j] = (0.16 - 0.06 * s) * k * crawl;
    }
    this.look.filaments.push(pts, c, white, half, core, sheath);
  }

  /** A colour charge held inside a hadron: a white-hot point in a small halo of its colour. */
  private charge(r: Renderer, x: number, y: number, c: RGB, k: number, size: number): void {
    r.top.push(x, y, 1.6 * size, (8 + 4 * c[0]) * k, (8 + 4 * c[1]) * k, (8 + 4 * c[2]) * k, 1, Shape.Glow);
    r.top.push(x, y, 8 * size, c[0] * 1.3 * k, c[1] * 1.3 * k, c[2] * 1.3 * k, 1, Shape.Glow);
  }

  /**
   * A nucleon at (x, y): `size` scales it (1 is a settled nucleon), `a` its presence, `rot` the
   * Y's turn, `colors` the three charges (colours, or anticolours for `anti`), `hue` how much
   * of them shows (1 all, 0 washed to white), `glow` extra light where they cancel.
   */
  nucleon(r: Renderer, x: number, y: number, size: number, a: number, rot: number, t: number, seed: number, colors: readonly RGB[], proton: boolean, anti: boolean, hue: number, glow: number): void {
    if (a <= 0.003) return;
    const tint = proton ? PROTON : NEUTRON;
    const R = 6 * size;
    const { qx, qy, qc } = this;
    // The colours hand on from quark to quark, a step about every half second: each holds its colour,
    // then slides into the next quark's in a quick blend.
    const phase = t * 2.1 + seed * 3.7;
    const step = Math.floor(phase);
    const u = Math.min(1, Math.max(0, (phase - step - 0.65) / 0.35));
    const blend = u * u * (3 - 2 * u);
    let jx = 0;
    let jy = 0;
    for (let k = 0; k < 3; k++) {
      // Inside, the quarks rattle almost freely: each keeps its own distance and drift (two
      // incommensurate wobbles, so the shape never repeats or settles).
      const ang = rot + (k * Math.PI * 2) / 3 + 0.28 * Math.sin(t * 2.3 + seed + k * 2.1) + 0.12 * Math.sin(t * 5.3 + seed * 0.7 + k);
      const rad = R * (0.72 + 0.18 * Math.sin(t * 3.1 + seed * 1.7 + k * 2.4) + 0.1 * Math.sin(t * 7.7 + seed + k * 1.3));
      qx[k] = x + Math.cos(ang) * rad;
      qy[k] = y + Math.sin(ang) * rad;
      jx += qx[k] / 3;
      jy += qy[k] / 3;
      const c0 = colors[(k + step) % 3];
      const c1 = colors[(k + step + 1) % 3];
      for (let m = 0; m < 3; m++) qc[k][m] = 1 + (c0[m] + (c1[m] - c0[m]) * blend - 1) * hue;
    }
    // The field: a faint string from each quark to the junction.
    for (let k = 0; k < 3; k++) this.leg(qx[k], qy[k], jx, jy, qc[k], tint, a, t, seed + k * 1.9, 2 * size);
    // The sparks: small, crisp, each in a tight halo of its colour of the moment.
    for (let k = 0; k < 3; k++) {
      const c = qc[k];
      r.top.push(qx[k], qy[k], 1.1 * size, (3 + 5 * c[0]) * a, (3 + 5 * c[1]) * a, (3 + 5 * c[2]) * a, 1, Shape.Glow);
      r.top.push(qx[k], qy[k], 4 * size, c[0] * 0.8 * a, c[1] * 0.8 * a, c[2] * 0.8 * a, 1, Shape.Glow);
    }
    // Where the colours cancel: a white-hot point, and the light it sheds into the plasma.
    const w = a * (1 + glow);
    r.top.push(jx, jy, 1.5 * size, tint[0] * 8 * w, tint[1] * 8 * w, tint[2] * 8 * w, 1, Shape.Glow);
    r.top.push(jx, jy, 6 * size, tint[0] * 0.35 * w, tint[1] * 0.35 * w, tint[2] * 0.35 * w, 1, Shape.Glow);
    r.top.push(x, y, 30 * size, tint[0] * 0.03 * w, tint[1] * 0.03 * w, tint[2] * 0.03 * w, 1, Shape.Glow);
    if (anti) r.top.push(x, y, R * 2.4, tint[0] * 0.4 * a, tint[1] * 0.4 * a, tint[2] * 0.4 * a, 1, Shape.Ring, 0.04);
    // The light it sheds into the plasma: a saturated version of its white (a near-white light over the
    // cooling plasma greys it), kept tight, and keyed so it holds its slot among the plasma's few lights.
    // A flare brightens the point far more than the plasma (thirty flaring at once would fog it).
    const lw = 0.13 * a * (1 + 0.3 * glow);
    this.look.glow(x, y, 40 + 8 * glow, tint[0] ** 3 * lw, tint[1] ** 3 * lw, tint[2] ** 3 * lw, seed + 1);
  }

  /**
   * A meson: the quark at (x + ux, y + uy), its antiquark opposite, on a short string; `bound` (0–1)
   * how tightly they have closed, which turns the pair white.
   */
  meson(r: Renderer, x: number, y: number, ux: number, uy: number, cq: RGB, ca: RGB, k: number, bound: number, t: number, seed: number): void {
    if (k <= 0.003) return;
    const sep = 2 * Math.hypot(ux, uy);
    if (sep > 16) this.look.string(x + ux, y + uy, x - ux, y - uy, cq, ca, 0.35, t, (0.7 - 0.4 * bound) * k, seed);
    else this.bond(x + ux, y + uy, x - ux, y - uy, cq, ca, 1.1 * k, t, seed, 3.2);
    this.charge(r, x + ux, y + uy, cq, k, 1);
    this.charge(r, x - ux, y - uy, ca, k, 1);
    r.top.push(x - ux, y - uy, 5, ca[0] * 1.2 * k, ca[1] * 1.2 * k, ca[2] * 1.2 * k, 1, Shape.Ring, 0.14);
    const w = bound * k;
    r.top.push(x, y, 2, 2.4 * w, 2.4 * w, 2.5 * w, 1, Shape.Glow);
    r.top.push(x, y, 11, 0.4 * w, 0.4 * w, 0.42 * w, 1, Shape.Glow);
    this.look.glow(x, y, 40, (0.3 + 0.2 * cq[0]) * w, (0.3 + 0.2 * cq[1]) * w, (0.3 + 0.2 * cq[2]) * w);
  }
}
