/**
 * The serializable game state. Everything that must survive a reload lives here; everything else
 * (macro-particles, GPU buffers, audio voices) is rebuilt from it.
 */
import type { Fate, InsightBreakdown } from './multiverse';
import type { Notation } from './format';

export const SAVE_VERSION = 2;

export type EraId = 'prologue' | 'soup' | 'nucleo' | 'afterglow' | 'dawn' | 'forge' | 'galaxies' | 'night';

export const ERA_ORDER: readonly EraId[] = [
  'prologue',
  'soup',
  'nucleo',
  'afterglow',
  'dawn',
  'forge',
  'galaxies',
  'night',
];

/** Rees' six numbers. Stored as logs where the real value spans orders of magnitude. */
export interface Constants {
  /** log10 of N, the ratio of electric force to gravity between two protons (ours: 36). */
  logN: number;
  /** Fraction of mass released when hydrogen fuses to helium (ours: 0.007). */
  epsilon: number;
  /** Matter density relative to critical (ours: ~0.3). */
  omega: number;
  /** Dark-energy density relative to critical (ours: ~0.7). */
  lambda: number;
  /** log10 of Q, the amplitude of primordial ripples (ours: -5). */
  logQ: number;
  /** Spatial dimensions. Not negotiable. */
  D: 3;
  /** Dark energy's equation of state (ours: -1, a cosmological constant). Rarely changes. */
  w: number;
  /** log10 of the vacuum's lifetime in years (ours: ~139, Andreassen, Frost & Schwartz 2018). Rarely changes. */
  logVacuum: number;
}

export const OUR_CONSTANTS: Readonly<Constants> = Object.freeze({
  logN: 36,
  epsilon: 0.007,
  omega: 0.3,
  lambda: 0.7,
  logQ: -5,
  D: 3,
  w: -1,
  logVacuum: 139,
});

export type Quality = 'auto' | 'low' | 'medium' | 'high';

export interface Settings {
  masterVolume: number;
  musicVolume: number;
  sfxVolume: number;
  ambienceVolume: number;
  muteOnBlur: boolean;
  reduceFlashes: boolean;
  reduceMotion: boolean;
  floatingNumbers: boolean;
  notation: Notation;
  /**
   * The player's choice. What Auto settles on is kept per device, not here: Steam Cloud carries the
   * save to the player's other machines, and one machine's level means nothing on another.
   */
  quality: Quality;
  uiScale: number;
  showPerf: boolean;
}

export interface HistoryEntry {
  /** Cosmic time in seconds. */
  t: number;
  era: EraId;
  text: string;
  /** Universe play time (s) when it happened. */
  at: number;
}

export interface RunState {
  /** Position in the lineage (1 = the first universe). */
  index: number;
  /** The universe this one budded from (null for the first). */
  parent: number | null;
  /** Codex entries first discovered in this universe. */
  finds: number;
  seed: number;
  rng: [number, number, number, number];
  startedAt: number;
  playTime: number;
  constants: Constants;
  era: EraId;
  /** Index of the epoch step reached within the current era (0 = era start). */
  step: number;
  /** Cosmic time in seconds (derived from era + step, cached for display/history). */
  time: number;
  /** Energy in electronvolts. */
  energy: number;
  energyTotal: number;
  /** One-way display switch to joules after the first joule. */
  joules: boolean;
  phenomena: Record<string, number>;
  revealed: Record<string, true>;
  /** Per-era serializable state, owned and typed by each era module. */
  eras: Partial<Record<EraId, unknown>>;
  /** Era results that flow forward (η, Yₚ, …). */
  legacy: Record<string, number>;
  history: HistoryEntry[];
  flags: Record<string, boolean>;
  /** Smoothed per-second rates persisted for offline credit (energy and era stocks). */
  meters: Record<string, number>;
  /** Non-numeric era results passed forward (e.g. this universe's CMB map), as compact strings. */
  artifacts: Record<string, string>;
}

export interface CodexState {
  /** Entry id → real timestamp of first discovery. Persists across universes. */
  discovered: Record<string, number>;
  /** Entries the player has opened (to show "new" markers). */
  read: Record<string, true>;
}

export interface LineageEntry {
  index: number;
  parent: number | null;
  constants: Constants;
  fate: string | null;
  blackHoles: number;
  playTime: number;
  legacy: Record<string, number>;
  /** Insight it taught. */
  insight: number;
}

/** How the last universe ended, for the multiverse screen. */
export interface UniverseEnd {
  index: number;
  fate: Fate | 'barren';
  title: string;
  text: string;
  insight: InsightBreakdown;
  blackHoles: number;
  playTime: number;
  finds: number;
}

export interface MetaState {
  universesCompleted: number;
  insight: number;
  knowledge: Record<string, number>;
  lineage: LineageEntry[];
  unlocked: boolean;
  /** Between universes: the multiverse screen is up. */
  atMultiverse: boolean;
  /** The seeds offered (kept so a reload offers the same ones). */
  seeds: Constants[];
  /** The universe whose black holes hold them (the last one, or an ancestor if it made none). */
  seedFrom: number;
  last: UniverseEnd | null;
  /** The first pull-back into the multiverse has been seen. */
  revealSeen: boolean;
  /** The ending (something looking back) has been seen. */
  endingSeen: boolean;
  /** Seconds the foam has been budding on its own (eternal inflation), and milestones reached. */
  inflationT: number;
  inflationMilestones: number;
}

export interface LifetimeStats {
  playTime: number;
  clicks: number;
  energyTotal: number;
  firstPlayed: number;
}

export interface GameState {
  v: number;
  created: number;
  saved: number;
  settings: Settings;
  run: RunState;
  codex: CodexState;
  meta: MetaState;
  lifetime: LifetimeStats;
}

export function defaultSettings(): Settings {
  return {
    masterVolume: 0.8,
    musicVolume: 0.7,
    sfxVolume: 0.8,
    ambienceVolume: 0.7,
    muteOnBlur: false,
    reduceFlashes: false,
    // A new save starts with the system's reduced-motion preference.
    reduceMotion: typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches,
    floatingNumbers: true,
    notation: 'scientific',
    quality: 'auto',
    uiScale: 1,
    showPerf: false,
  };
}

export function newRun(index: number, seed: number, constants: Constants, now: number, parent: number | null = null): RunState {
  return {
    index,
    parent,
    finds: 0,
    seed,
    rng: [0, 0, 0, 0],
    startedAt: now,
    playTime: 0,
    constants: { ...constants },
    era: 'prologue',
    step: 0,
    time: 1e-36,
    energy: 0,
    energyTotal: 0,
    joules: false,
    phenomena: {},
    revealed: {},
    eras: {},
    legacy: {},
    history: [],
    flags: {},
    meters: {},
    artifacts: {},
  };
}

export function defaultState(seed: number, now: number): GameState {
  return {
    v: SAVE_VERSION,
    created: now,
    saved: now,
    settings: defaultSettings(),
    run: newRun(1, seed, OUR_CONSTANTS, now),
    codex: { discovered: {}, read: {} },
    meta: { universesCompleted: 0, insight: 0, knowledge: {}, lineage: [], unlocked: false, atMultiverse: false, seeds: [], seedFrom: 0, last: null, revealSeen: false, endingSeen: false, inflationT: 0, inflationMilestones: 0 },
    lifetime: { playTime: 0, clicks: 0, energyTotal: 0, firstPlayed: now },
  };
}
