/**
 * The audio engine. Synthesized sound, made here at runtime, plays on three buses (music, effects,
 * ambience) into a reverb send, a glue compressor and a brick-wall limiter. Rendered sound (version 2
 * files) plays on three dry buses beside them that skip all of that: the files were mastered offline
 * with their own rooms, dynamics and ceilings, so only the volume sliders, mute, a fixed lift to the
 * synthesized path's loudness and a safety limiter stand between them and the speakers. Both paths
 * meet at that limiter.
 *
 * The context is made early (armed) and suspended, so the current era's files decode before the
 * first gesture; that gesture resumes it.
 *
 * Mix discipline: a global voice cap, per-cue minimum intervals, and density-aware attenuation so a
 * flurry of events thins into texture instead of piling up into noise.
 */

export interface Volumes {
  master: number;
  music: number;
  sfx: number;
  ambience: number;
}

export type BusName = 'music' | 'sfx' | 'ambience';

const MAX_VOICES = 28;

/**
 * The safety limiter's threshold (dBFS): at the rendered files' −1 dBTP ceiling, so one file at full
 * volume never reaches it; only sums that would otherwise clip do.
 */
const SAFETY_DB = -1;
const SAFETY_RATIO = 20;
/**
 * Web Audio compressors add makeup gain of their own (the gain their curve takes from full scale, to
 * the power 0.6): taken back after the safety limiter so it passes everything below its threshold
 * unchanged.
 */
const SAFETY_TRIM = 10 ** ((0.6 * (SAFETY_DB - SAFETY_DB / SAFETY_RATIO)) / 20);
/**
 * The synthesized path comes out of its compressors about 6.6 dB louder than it went in (their own
 * makeup gain outweighs what they take at the levels it runs at). The rendered path gets the same lift
 * as a plain gain, so the two meet at one loudness and an era handing over to one in the other form
 * doesn't jump in level; the safety limiter catches the rare summed peak the lift takes past −1 dBFS.
 */
const RENDERED_LIFT = 10 ** (6.6 / 20);

export class AudioEngine {
  ctx: AudioContext | null = null;
  private master!: GainNode;
  /** The rendered path's master: the same volume and mute as `master`, without its dynamics. */
  private renderedMaster!: GainNode;
  private glue!: DynamicsCompressorNode;
  private limiter!: DynamicsCompressorNode;
  private safety!: DynamicsCompressorNode;
  private out!: GainNode;
  private buses!: Record<BusName, GainNode>;
  /** After the effects buses (synthesized and rendered): pushed down while a step introduces itself. */
  private effectsDuck: GainNode[] = [];
  private dryBuses!: Record<BusName, GainNode>;
  private sends!: Record<BusName, GainNode>;
  private reverb!: ConvolverNode;
  private noiseBuf!: AudioBuffer;
  /**
   * The voices currently sounding, for the cap: end times (context seconds), and for voices that can
   * be cut short (rendered files, whose long room tails would otherwise hold the cap), how to fade them.
   */
  private voiceEnds: { end: number; steal?: () => void }[] = [];
  /** Set when running on an injected (offline) context: timers then follow context time, not the wall clock. */
  private offline = false;
  private timers: { at: number; fn: () => void }[] = [];
  private lastCue = new Map<string, number>();
  private density = new Map<string, number>();
  private volumes: Volumes = { master: 0.8, music: 0.7, sfx: 0.8, ambience: 0.7 };
  private muted = false;
  /** Set by the first gesture browsers accept for audio: sound may play from then on. */
  private unlocked = false;

  /**
   * Makes the context and its graph without starting it, so files can decode before the first
   * gesture (decoding needs a context, not a running one). Where nothing blocks audio (the desktop
   * shell), the context is suspended anyway: sound begins with the first gesture everywhere.
   */
  arm(): void {
    if (this.ctx || typeof window === 'undefined') return;
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return;
    const ctx = new Ctor({ latencyHint: 'interactive' });
    if (ctx.state === 'running') void ctx.suspend();
    this.build(ctx);
  }

  /**
   * Call from a user gesture (browsers block audio until then); safe to call repeatedly. True only for
   * the call that unlocks. An event browsers do not count as a gesture for audio (Esc, by the HTML
   * standard) leaves it locked, and the next one unlocks. The context resumes a moment after this
   * returns: what is scheduled meanwhile plays from then. `injected` runs the engine on a context the
   * caller owns (e.g. an `OfflineAudioContext` for QA renders); the caller then drives deferred work
   * with `pump()`.
   */
  unlock(injected?: BaseAudioContext): boolean {
    if (injected && !this.ctx) {
      // Only the BaseAudioContext surface is used past this point (resume() is skipped when offline).
      this.offline = true;
      this.build(injected as AudioContext);
    }
    this.arm();
    const ctx = this.ctx;
    if (!ctx || this.unlocked) {
      if (ctx && !this.offline && ctx.state === 'suspended') void ctx.resume();
      return false;
    }
    if (!this.offline) {
      const act = (navigator as Navigator & { userActivation?: { isActive: boolean; hasBeenActive: boolean } }).userActivation;
      if (act && !act.isActive && !act.hasBeenActive) return false;
      if (ctx.state === 'suspended') void ctx.resume();
    }
    this.unlocked = true;
    return true;
  }

  private build(ctx: AudioContext): void {
    this.ctx = ctx;

    const glue = (this.glue = ctx.createDynamicsCompressor());
    glue.threshold.value = -20;
    glue.knee.value = 12;
    glue.ratio.value = 2.5;
    glue.attack.value = 0.012;
    glue.release.value = 0.28;
    const limiter = (this.limiter = ctx.createDynamicsCompressor());
    limiter.threshold.value = -2.5;
    limiter.knee.value = 0;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.001;
    limiter.release.value = 0.12;

    const safety = (this.safety = ctx.createDynamicsCompressor());
    safety.threshold.value = SAFETY_DB;
    safety.knee.value = 0;
    safety.ratio.value = SAFETY_RATIO;
    safety.attack.value = 0.001;
    safety.release.value = 0.1;
    this.out = ctx.createGain();
    this.out.gain.value = SAFETY_TRIM;
    safety.connect(this.out).connect(ctx.destination);

    // Sub-sonic energy (sub drones, low thumps) is inaudible on most speakers but still drives the
    // compressor and eats headroom, so it is trimmed before the dynamics.
    const rumble = ctx.createBiquadFilter();
    rumble.type = 'highpass';
    rumble.frequency.value = 28;
    rumble.Q.value = 0.6;
    this.master = ctx.createGain();
    this.master.connect(rumble).connect(glue).connect(limiter).connect(safety);
    this.renderedMaster = ctx.createGain();
    this.renderedMaster.connect(safety);

    this.reverb = ctx.createConvolver();
    this.reverb.buffer = this.impulse(4.2, 2.6);
    const wet = ctx.createGain();
    wet.gain.value = 0.9;
    this.reverb.connect(wet).connect(this.master);

    const duck = () => {
      const d = ctx.createGain();
      this.effectsDuck.push(d);
      return d;
    };
    this.effectsDuck = [];
    const mk = (send: number, through?: GainNode) => {
      const bus = ctx.createGain();
      const s = ctx.createGain();
      s.gain.value = send;
      const from = through ? (bus.connect(through), through) : bus;
      from.connect(this.master);
      from.connect(s).connect(this.reverb);
      return [bus, s] as const;
    };
    const [music, musicSend] = mk(0.45);
    const [sfx, sfxSend] = mk(0.28, duck());
    const [ambience, ambSend] = mk(0.55);
    this.buses = { music, sfx, ambience };
    this.sends = { music: musicSend, sfx: sfxSend, ambience: ambSend };
    const dry = (through?: GainNode) => {
      const g = ctx.createGain();
      if (through) g.connect(through).connect(this.renderedMaster);
      else g.connect(this.renderedMaster);
      return g;
    };
    this.dryBuses = { music: dry(), sfx: dry(duck()), ambience: dry() };

    const len = ctx.sampleRate * 2;
    this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;

    this.applyVolumes();
  }

  /** Sound may play: unlocked (the context may still be resuming; what is scheduled meanwhile plays from then). */
  get ready(): boolean {
    return !!this.ctx && this.unlocked && this.ctx.state !== 'closed';
  }

  /** Made, so files can decode, though perhaps not yet unlocked. */
  get armed(): boolean {
    return !!this.ctx;
  }

  /**
   * The context's clock is running. Just after the unlocking gesture it is not yet: starting the
   * output device takes from a few tens of milliseconds to over half a second, and the clock stands
   * still meanwhile, so whatever is scheduled then starts that much late.
   */
  get running(): boolean {
    return !!this.ctx && (this.offline || this.ctx.state === 'running');
  }

  /** Resolves once the context's clock is running. */
  whenRunning(): Promise<void> {
    const ctx = this.ctx;
    if (!ctx || this.running) return Promise.resolve();
    return new Promise((resolve) => {
      const on = () => {
        if (ctx.state !== 'running') return;
        ctx.removeEventListener('statechange', on);
        resolve();
      };
      ctx.addEventListener('statechange', on);
    });
  }

  /**
   * Run `fn` after `seconds` of audio time: wall-clock timers live, context time when offline.
   * Used for node cleanup and slow generative changes.
   */
  after(seconds: number, fn: () => void): void {
    if (!this.offline) {
      setTimeout(fn, Math.max(0, seconds * 1000));
      return;
    }
    this.timers.push({ at: this.now + Math.max(0, seconds), fn });
  }

  /** Offline only: run every deferred callback that is due at the context's current time. */
  pump(): void {
    const t = this.now + 1e-6;
    for (;;) {
      const due = this.timers.filter((x) => x.at <= t);
      if (!due.length) return;
      this.timers = this.timers.filter((x) => x.at > t);
      for (const x of due) x.fn();
    }
  }

  get now(): number {
    return this.ctx?.currentTime ?? 0;
  }

  setVolumes(v: Volumes): void {
    this.volumes = { ...v };
    this.applyVolumes();
  }

  setMuted(muted: boolean): void {
    this.muted = muted;
    this.applyVolumes();
  }

  private applyVolumes(): void {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const v = this.volumes;
    // Perceptual taper: slider position squared.
    const master = this.muted ? 0 : v.master * v.master;
    this.master.gain.setTargetAtTime(master, t, 0.05);
    this.renderedMaster.gain.setTargetAtTime(master * RENDERED_LIFT, t, 0.05);
    for (const b of [this.buses, this.dryBuses]) {
      b.music.gain.setTargetAtTime(v.music * v.music, t, 0.05);
      b.sfx.gain.setTargetAtTime(v.sfx * v.sfx, t, 0.05);
      b.ambience.gain.setTargetAtTime(v.ambience * v.ambience, t, 0.05);
    }
  }

  bus(name: BusName): GainNode {
    return this.buses[name];
  }

  /**
   * Pushes every effect down to `level` (0–1) for `hold` seconds, then lets it back over `release`: so
   * what introduces a step (played on the music bus) is heard over a run of clicks instead of under it.
   */
  duckEffects(level: number, hold: number, release: number): void {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    for (const d of this.effectsDuck) {
      const g = d.gain;
      g.cancelScheduledValues(t);
      g.setValueAtTime(g.value, t);
      g.linearRampToValueAtTime(level, t + 0.06);
      g.setValueAtTime(level, t + 0.06 + hold);
      g.linearRampToValueAtTime(1, t + 0.06 + hold + release);
    }
  }

  /** The dry twin of a bus (no reverb send), for rendered sound. */
  dry(name: BusName): GainNode {
    return this.dryBuses[name];
  }

  /** Raise or lower how much of a bus goes to the reverb (scale grows with the universe). */
  setReverbSend(name: BusName, amount: number): void {
    if (!this.ctx) return;
    this.sends[name].gain.setTargetAtTime(amount, this.ctx.currentTime, 0.5);
  }

  noise(): AudioBuffer {
    return this.noiseBuf;
  }

  /**
   * Admission control for event sounds. Returns a gain multiplier (0 = don't play).
   * `minInterval` throttles repeats of one cue; density attenuates sustained bursts.
   */
  admit(cue: string, minInterval: number): number {
    if (!this.ready) return 0;
    const t = this.now;
    // A cue never heard before is always admitted (even in the first second of the context).
    const last = this.lastCue.get(cue);
    if (last !== undefined && t - last < minInterval) return 0;
    this.voiceEnds = this.voiceEnds.filter((v) => v.end > t);
    // A full cap makes room by fading the oldest voice that can be cut short (by now deep in its
    // tail), so a click is never silent because earlier sounds are still ringing out.
    if (this.voiceEnds.length >= MAX_VOICES && !this.steal()) return 0;
    const prev = this.density.get(cue) ?? 0;
    const decayed = last === undefined ? 0 : prev * Math.exp(-(t - last) * 2.2);
    const dens = decayed + 1;
    this.density.set(cue, dens);
    this.lastCue.set(cue, t);
    return 1 / Math.sqrt(dens);
  }

  /**
   * Track a voice for the cap until `endTime`. The claim is returned: a voice stopped early moves its
   * `end` forward, so it stops counting once it is silent.
   */
  claimVoice(endTime: number, steal?: () => void): { end: number } {
    // Tracked in context time so the cap is right even when timers are throttled (background tabs).
    const claim = { end: Math.max(endTime, this.now) + 0.05, steal };
    this.voiceEnds.push(claim);
    return claim;
  }

  /** Cuts short the oldest voice that allows it; false if none does. */
  private steal(): boolean {
    const i = this.voiceEnds.findIndex((v) => v.steal);
    if (i < 0) return false;
    const [v] = this.voiceEnds.splice(i, 1);
    v.steal?.();
    return true;
  }

  /**
   * QA and debugging: the points a capture taps (the synthesized master into its dynamics, the final
   * output after the safety limiter, the dry music and effects buses) and the three compressors, for
   * their gain reduction.
   */
  get taps(): {
    input: AudioNode;
    output: AudioNode;
    music: AudioNode;
    sfx: AudioNode;
    glue: DynamicsCompressorNode;
    limiter: DynamicsCompressorNode;
    safety: DynamicsCompressorNode;
  } | null {
    if (!this.ctx) return null;
    return { input: this.master, output: this.out, music: this.dryBuses.music, sfx: this.dryBuses.sfx, glue: this.glue, limiter: this.limiter, safety: this.safety };
  }

  /** Voices currently counted against the cap (QA and debugging). */
  get activeVoices(): number {
    const t = this.now;
    return this.voiceEnds.filter((v) => v.end > t).length;
  }

  /**
   * Snap a time to a soft rhythmic grid so emergent events fall into a pulse.
   * The wait is capped so direct actions never feel late.
   */
  quantize(grid: number, maxWait = 0.09): number {
    const t = this.now + 0.005;
    const next = Math.ceil(t / grid) * grid;
    return next - t <= maxWait ? next : t;
  }

  /** Generated stereo impulse response: decorrelated noise, exponential decay, darker tail. */
  private impulse(seconds: number, decay: number): AudioBuffer {
    const ctx = this.ctx as AudioContext;
    const rate = ctx.sampleRate;
    const len = Math.floor(rate * seconds);
    const buf = ctx.createBuffer(2, len, rate);
    const pre = Math.floor(rate * 0.018);
    for (let ch = 0; ch < 2; ch++) {
      const d = buf.getChannelData(ch);
      let lp = 0;
      for (let i = pre; i < len; i++) {
        const t = (i - pre) / len;
        const env = Math.pow(1 - t, decay) * Math.exp(-t * 2.5);
        // One-pole lowpass whose cutoff falls over the tail: highs die first, like a real room.
        const k = 0.55 - 0.42 * t;
        lp += (Math.random() * 2 - 1 - lp) * k;
        d[i] = lp * env;
      }
    }
    return buf;
  }
}
