/**
 * The Long Night: an almost black sky. The only light behind the stars is the galaxy's own unresolved
 * glow, gold, then red, then briefly blue as the last red dwarfs heat up, then the faint grey of dead
 * stars; in the Black Hole Era even that is gone.
 */
import type { RGB } from '../../render/color';
import type { BackgroundDef } from '../../render/renderer';

export interface NightBgParams {
  /** Brightness of the galaxy's diffuse starlight (0 = none). */
  glow: number;
  /** Colour of that light. */
  tint: RGB;
  /** 0 → 1: the last light going out. */
  dark: number;
  pulse: number;
}

export function nightBackground(params: NightBgParams): BackgroundDef {
  return {
    id: 'night',
    fragment: /* glsl */ `
uniform float uGlow;
uniform vec3 uTint;
uniform float uDark;
uniform float uPulse;

void main() {
  vec2 world = uView.xy + (vUv * 2.0 - 1.0) * uView.zw * vec2(1.0, -1.0);
  float t = uTime * 0.003;
  vec3 col = vec3(0.0016, 0.0016, 0.0022);

  // The galaxy's unresolved starlight: a soft cusp, flattened like the galaxy itself.
  vec2 q = world / vec2(1.0, 0.84);
  float r = length(q);
  float body = exp(-r / 110.0) * 0.5 + exp(-r * r / 40000.0) * 0.45 + exp(-r / 320.0) * 0.12;
  float n = 0.86 + 0.14 * fbm(vec3(world / 240.0, t), 3);
  col += uTint * uGlow * body * 0.05 * n;

  col *= 1.0 - 0.9 * uDark;
  outColor = vec4(col * (1.0 + uPulse), 1.0);
}`,
    uniforms: (p) => {
      p.f1('uGlow', params.glow).f1('uDark', params.dark).f1('uPulse', params.pulse);
      p.f3('uTint', params.tint[0], params.tint[1], params.tint[2]);
    },
  };
}
