/**
 * Macro-particles in structure-of-arrays form. Each particle stands for `w` real particles
 * (its weight), exactly as in cosmological N-body codes. Removal is deferred to `compact()` so
 * indices stay valid for the whole simulation step; stable ids survive compaction for links.
 */
export class Particles {
  readonly cap: number;
  n = 0;
  readonly x: Float32Array;
  readonly y: Float32Array;
  readonly vx: Float32Array;
  readonly vy: Float32Array;
  /** Collision/interaction radius in world units. */
  readonly r: Float32Array;
  /** Weight: how many real particles this one represents. */
  readonly w: Float64Array;
  readonly kind: Uint8Array;
  /** Era-defined subtype (colour charge, flavour, species). */
  readonly sub: Uint8Array;
  readonly age: Float32Array;
  /** Remaining lifetime for unstable particles (Infinity if stable). */
  readonly life: Float32Array;
  readonly flags: Uint8Array;
  readonly id: Uint32Array;
  /** Id of a linked particle (bond partner), 0 = none. */
  readonly link: Uint32Array;
  /** Two spare per-particle scalars for era logic (heat, phase, charge-up…). */
  readonly a: Float32Array;
  readonly b: Float32Array;
  private dead: Uint8Array;
  private nextId = 1;
  private index = new Map<number, number>();

  constructor(cap: number) {
    this.cap = cap;
    this.x = new Float32Array(cap);
    this.y = new Float32Array(cap);
    this.vx = new Float32Array(cap);
    this.vy = new Float32Array(cap);
    this.r = new Float32Array(cap);
    this.w = new Float64Array(cap);
    this.kind = new Uint8Array(cap);
    this.sub = new Uint8Array(cap);
    this.age = new Float32Array(cap);
    this.life = new Float32Array(cap);
    this.flags = new Uint8Array(cap);
    this.id = new Uint32Array(cap);
    this.link = new Uint32Array(cap);
    this.a = new Float32Array(cap);
    this.b = new Float32Array(cap);
    this.dead = new Uint8Array(cap);
  }

  get full(): boolean {
    return this.n >= this.cap;
  }

  /** Adds a particle; returns its index, or −1 when at capacity. */
  spawn(kind: number, x: number, y: number, vx: number, vy: number, r: number, w: number, sub = 0): number {
    if (this.n >= this.cap) return -1;
    const i = this.n++;
    this.x[i] = x;
    this.y[i] = y;
    this.vx[i] = vx;
    this.vy[i] = vy;
    this.r[i] = r;
    this.w[i] = w;
    this.kind[i] = kind;
    this.sub[i] = sub;
    this.age[i] = 0;
    this.life[i] = Infinity;
    this.flags[i] = 0;
    this.link[i] = 0;
    this.a[i] = 0;
    this.b[i] = 0;
    this.dead[i] = 0;
    const id = this.nextId++;
    this.id[i] = id;
    this.index.set(id, i);
    return i;
  }

  kill(i: number): void {
    this.dead[i] = 1;
  }

  isDead(i: number): boolean {
    return this.dead[i] === 1;
  }

  /** Index of a particle by stable id, or −1 if gone. */
  find(id: number): number {
    const i = this.index.get(id);
    return i === undefined || this.dead[i] ? -1 : i;
  }

  /** Remove killed particles (swap-with-last), keeping the id index consistent. */
  compact(): void {
    let i = 0;
    while (i < this.n) {
      if (!this.dead[i]) {
        i++;
        continue;
      }
      this.index.delete(this.id[i]);
      const last = --this.n;
      if (i !== last) this.move(last, i);
    }
  }

  private move(from: number, to: number): void {
    this.x[to] = this.x[from];
    this.y[to] = this.y[from];
    this.vx[to] = this.vx[from];
    this.vy[to] = this.vy[from];
    this.r[to] = this.r[from];
    this.w[to] = this.w[from];
    this.kind[to] = this.kind[from];
    this.sub[to] = this.sub[from];
    this.age[to] = this.age[from];
    this.life[to] = this.life[from];
    this.flags[to] = this.flags[from];
    this.id[to] = this.id[from];
    this.link[to] = this.link[from];
    this.a[to] = this.a[from];
    this.b[to] = this.b[from];
    this.dead[to] = this.dead[from];
    this.index.set(this.id[to], to);
  }

  clear(): void {
    this.n = 0;
    this.index.clear();
  }

  /** Sum of weights of particles of a kind. */
  weightOf(kind: number): number {
    let s = 0;
    for (let i = 0; i < this.n; i++) if (this.kind[i] === kind && !this.dead[i]) s += this.w[i];
    return s;
  }

  countOf(kind: number): number {
    let c = 0;
    for (let i = 0; i < this.n; i++) if (this.kind[i] === kind && !this.dead[i]) c++;
    return c;
  }
}
