/**
 * Pitch helpers. Event sounds are drawn from the current era's scale so that random events land on
 * notes that belong together.
 */

/** MIDI note number → frequency in Hz (A4 = 69 = 440 Hz). */
export function mtof(m: number): number {
  return 440 * 2 ** ((m - 69) / 12);
}

export const SCALES = {
  /** Bright and open: the Soup. */
  lydian: [0, 2, 4, 6, 7, 9, 11],
  /** Warm, no tension: pentatonic majors for constant events. */
  majorPentatonic: [0, 2, 4, 7, 9],
  /** Suspended, modal: Afterglow, Dark Ages. */
  dorian: [0, 2, 3, 5, 7, 9, 10],
  /** Sparse and grave: the Long Night. */
  minorPentatonic: [0, 3, 5, 7, 10],
} as const;

export interface Key {
  root: number;
  scale: readonly number[];
}

/** The `degree`-th note of a key (degrees wrap into higher octaves). */
export function note(key: Key, degree: number): number {
  const n = key.scale.length;
  const oct = Math.floor(degree / n);
  const idx = ((degree % n) + n) % n;
  return key.root + oct * 12 + key.scale[idx];
}
