<!--
  Hover / focus / long-press tooltip. Positions itself on the side with the most room.
-->
<script lang="ts">
  import type { Snippet } from 'svelte';

  let {
    children,
    tip,
    side = 'auto',
    width = '18rem',
  }: { children: Snippet; tip: Snippet | null; side?: 'auto' | 'below' | 'above' | 'left' | 'right'; width?: string } =
    $props();

  let open = $state(false);
  let host: HTMLElement | undefined = $state();
  let pos = $state({ x: 0, y: 0, place: 'below' as 'below' | 'above' | 'left' | 'right' });
  let pressTimer: ReturnType<typeof setTimeout> | null = null;

  /** The host is `display: contents` (no box of its own), so measure what it wraps. */
  function measure(el: HTMLElement): DOMRect {
    const range = document.createRange();
    range.selectNodeContents(el);
    const r = range.getBoundingClientRect();
    return r.width || r.height ? r : el.getBoundingClientRect();
  }

  function show() {
    if (!host || !tip) return;
    const r = measure(host);
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    let place = side;
    if (place === 'auto') {
      if (r.left > vw * 0.62) place = 'left';
      else if (r.bottom < vh * 0.55) place = 'below';
      else place = 'above';
    }
    const p = place as 'below' | 'above' | 'left' | 'right';
    if (p === 'below') pos = { x: r.left, y: r.bottom + 8, place: p };
    else if (p === 'above') pos = { x: r.left, y: r.top - 8, place: p };
    else if (p === 'left') pos = { x: r.left - 10, y: r.top, place: p };
    else pos = { x: r.right + 10, y: r.top, place: p };
    open = true;
  }

  function hide() {
    open = false;
    if (pressTimer) clearTimeout(pressTimer);
    pressTimer = null;
  }

  function touchStart() {
    pressTimer = setTimeout(show, 420);
  }
</script>

<span
  class="host"
  bind:this={host}
  onmouseenter={show}
  onmouseleave={hide}
  onfocusin={show}
  onfocusout={hide}
  ontouchstart={touchStart}
  ontouchend={hide}
  role="presentation"
>
  {@render children()}
</span>

{#if open && tip}
  <div
    class="tip {pos.place}"
    style="--x:{pos.x}px; --y:{pos.y}px; --w:{width}"
    role="tooltip"
  >
    {@render tip()}
  </div>
{/if}

<style>
  .host {
    display: contents;
  }
  .tip {
    position: fixed;
    z-index: 50;
    width: var(--w);
    max-width: calc(100vw - 24px);
    box-sizing: border-box;
    padding: 0.75rem 0.9rem 0.8rem;
    background: var(--panel-solid);
    border: 1px solid var(--line-2);
    border-top-color: var(--accent-line);
    box-shadow: 0 12px 40px rgb(0 0 0 / 0.6);
    font-family: var(--sans);
    font-size: max(0.82rem, var(--min-text));
    line-height: 1.5;
    text-align: left;
    text-shadow: none;
    color: var(--ink-2);
    pointer-events: none;
    animation: tip-in var(--fast) var(--ease) both;
  }
  .tip.below {
    left: clamp(12px, var(--x), calc(100vw - var(--w) - 12px));
    top: var(--y);
  }
  .tip.above {
    left: clamp(12px, var(--x), calc(100vw - var(--w) - 12px));
    bottom: calc(100vh - var(--y));
  }
  .tip.left {
    right: calc(100vw - var(--x));
    top: clamp(12px, var(--y), calc(100vh - 12rem));
  }
  .tip.right {
    left: var(--x);
    top: clamp(12px, var(--y), calc(100vh - 12rem));
  }
  .tip.left {
    animation-name: tip-in-left;
  }
  @keyframes tip-in {
    from {
      opacity: 0;
      transform: translateY(calc(3px * var(--motion)));
    }
  }
  @keyframes tip-in-left {
    from {
      opacity: 0;
      transform: translateX(calc(3px * var(--motion)));
    }
  }
</style>
