/**
 * Light nuclei and the Big Bang nucleosynthesis reaction network (simplified, real Q-values).
 *
 * No stable nucleus has 5 or 8 nucleons, which is why the network stalls at lithium and beryllium:
 * there's no stepping stone to anything heavier.
 */

export const Sp = {
  P: 0,
  N: 1,
  D: 2,
  T: 3,
  He3: 4,
  He4: 5,
  Li7: 6,
  Be7: 7,
} as const;
export type Sp = (typeof Sp)[keyof typeof Sp];

export interface Species {
  id: Sp;
  symbol: string;
  /** Protons. */
  Z: number;
  /** Nucleons. */
  A: number;
  codex: string;
}

export const SPECIES: readonly Species[] = [
  { id: Sp.P, symbol: 'p', Z: 1, A: 1, codex: 'proton' },
  { id: Sp.N, symbol: 'n', Z: 0, A: 1, codex: 'neutron' },
  { id: Sp.D, symbol: 'D', Z: 1, A: 2, codex: 'deuterium' },
  { id: Sp.T, symbol: 'T', Z: 1, A: 3, codex: 'tritium' },
  { id: Sp.He3, symbol: '³He', Z: 2, A: 3, codex: 'helium-3' },
  { id: Sp.He4, symbol: '⁴He', Z: 2, A: 4, codex: 'helium-4' },
  { id: Sp.Li7, symbol: '⁷Li', Z: 3, A: 7, codex: 'lithium-7' },
  { id: Sp.Be7, symbol: '⁷Be', Z: 4, A: 7, codex: 'beryllium-7' },
];

export interface Reaction {
  a: Sp;
  b: Sp;
  /** Products: the visible nucleus that remains, and an optional ejected nucleon. */
  product: Sp;
  ejects?: Sp;
  /** Energy released, MeV (real values). */
  q: number;
  /** Requires the Reaction Network phenomenon (beyond the first step, p + n → D). */
  network?: 1 | 2;
  /** Chance that contact actually reacts (tiny cross sections for the rare branches). Default 1. */
  chance?: number;
}

/** Reactions keyed by unordered species pair. Alternatives (D + D) are chosen at random. */
export const REACTIONS: readonly Reaction[] = [
  { a: Sp.P, b: Sp.N, product: Sp.D, q: 2.22 },
  { a: Sp.D, b: Sp.P, product: Sp.He3, q: 5.49, network: 1 },
  { a: Sp.D, b: Sp.N, product: Sp.T, q: 6.26, network: 1 },
  { a: Sp.D, b: Sp.D, product: Sp.He3, ejects: Sp.N, q: 3.27, network: 1 },
  { a: Sp.D, b: Sp.D, product: Sp.T, ejects: Sp.P, q: 4.03, network: 1 },
  { a: Sp.T, b: Sp.D, product: Sp.He4, ejects: Sp.N, q: 17.59, network: 1 },
  { a: Sp.He3, b: Sp.D, product: Sp.He4, ejects: Sp.P, q: 18.35, network: 1 },
  { a: Sp.He3, b: Sp.N, product: Sp.T, ejects: Sp.P, q: 0.76, network: 1 },
  { a: Sp.T, b: Sp.P, product: Sp.He4, q: 19.81, network: 1 },
  { a: Sp.T, b: Sp.He4, product: Sp.Li7, q: 2.47, network: 2, chance: 0.0003 },
  { a: Sp.He3, b: Sp.He4, product: Sp.Be7, q: 1.59, network: 2, chance: 0.0003 },
];

const table = new Map<number, Reaction[]>();
for (const r of REACTIONS) {
  const key = r.a < r.b ? r.a * 16 + r.b : r.b * 16 + r.a;
  const list = table.get(key) ?? [];
  list.push(r);
  table.set(key, list);
}

export function reactionsFor(a: Sp, b: Sp): readonly Reaction[] | undefined {
  return table.get(a < b ? a * 16 + b : b * 16 + a);
}

/** Visual radius of a nucleus in world units (grows like A^(1/3), as real nuclei do). */
export function radiusOf(sp: Sp): number {
  return 9 * Math.cbrt(SPECIES[sp].A) + 1.5;
}
