/**
 * How the First Three Minutes look (version 2). The simulation says what is where; this draws it.
 *
 * - The medium: about a billion kelvin, cooler and calmer than the Soup. A dark, slow plasma with
 *   only a faint warm glow left in its cell cores and a cold blue-grey in its folds (a violet cast
 *   while the light can still split deuterium), and a sparse storm of crisp specks in depth, receding
 *   as space expands. Hydrogen that sinks out of the play joins the storm as faint warm specks.
 * - Nucleons: crisp point lights, protons warm and neutrons cool; a free one breathes gently (it is
 *   there to be grabbed), and a free neutron shivers as its time runs out.
 * - Nuclei: tight lit clusters of those point lights in depth (the back ones dimmer), held together by
 *   short streamers of light that flare into a foot at each nucleon. Helium-4, the closed shell, is a
 *   knot of light instead: a glowing gold body with a crisp, limb-bright rim, its nucleons sparks
 *   inside it.
 * - Effects (the era's FxPool, restyled): a fusion is a point spread of light that lights the medium
 *   and the specks; rings are light fronts racing through the plasma that push the specks outward;
 *   sparks are streaks; photons are faint wave packets racing across.
 */
import type { FxLook } from '../../render/fx';
import { Filaments } from '../../render/filaments';
import { Plasma } from '../../render/plasma';
import type { BackgroundDef, Renderer } from '../../render/renderer';
import type { PostParams } from '../../render/post';
import { Shape } from '../../render/sprites';
import { Storm, type StormKick, type StormLight } from '../../render/storm';
import type { VolumeFront, VolumeLight, VolumeTube } from '../../render/volume';
import { Best, packet } from '../soup/light';

type RGB = readonly [number, number, number];

/** Point-light tints: a proton burns warm, a neutron cool (they differ in lightness too). */
export const PROTON_LIGHT: RGB = [1.0, 0.56, 0.32];
export const NEUTRON_LIGHT: RGB = [0.62, 0.78, 1.0];
/** Closed-shell gold of helium-4 bonds. */
export const GOLD_LIGHT: RGB = [1.0, 0.72, 0.34];
/** Pale ice of the lithium and beryllium bonds. */
export const ICE_LIGHT: RGB = [0.62, 0.84, 1.0];

const WHITE: [number, number, number] = [1.0, 0.97, 0.92];
const PALE: [number, number, number] = [0.78, 0.86, 1.0];
const EMBER: [number, number, number] = [1.0, 0.62, 0.36];
const SEA: [number, number, number] = [1.0, 0.5, 0.3];
const PAIR: [number, number, number] = [0.8, 0.9, 1.15];
const UNIT: RGB = [1, 1, 1];
/** Helium-4's rim, from its brightest arc (white-gold) to its dimmest (deep amber). */
/** The photons of the bath: hard light, violet while it can still split deuterium. */
const BATH: RGB = [0.62, 0.5, 1.0];
const NO_TUBES: VolumeTube[] = [];

const BLACK: BackgroundDef = {
  id: 'nucleo-v2',
  fragment: /* glsl */ `
void main() {
  outColor = vec4(0.0005, 0.00045, 0.0006, 1.0);
}`,
};

/** The post settings this look is graded for. */
const POST: Partial<PostParams> = { bloom: 0.22, bloomThreshold: 1.4, glare: 0.3, glareThreshold: 3, saturation: 1.12, punch: 1.2, vignette: 0.5, grain: 0.012 };

const lum = (r: number, g: number, b: number) => 0.2126 * r + 0.7152 * g + 0.0722 * b;

/** Points along a bond (its two feet included), and points around half of helium-4's rim. */
const BOND_PTS = 9;

export class NucleoLook implements FxLook {
  readonly plasma = new Plasma({ depth: 900, near: 450, focal: 1600, cellSize: 1500, heat: 0.44, brightness: 0.13, absorb: 0.0022, lanes: 0.95, fade: 260, scale: 0.5, steps: 40, boil: 0.007, warp: 0.6, charge: 0, cool: [0.035, 0.045, 0.1] });
  readonly storm = new Storm({
    count: 7000,
    depth: 900,
    focal: 1600,
    lifeMin: 3,
    lifeMax: 8,
    swirl: 7,
    swirlScale: 700,
    drag: 2,
    jitter: 2.5,
    spread: 0.008,
    faintest: 0.025,
    peak: 8,
    magnitudePower: 1,
    halo: 0,
    twinkle: 0.2,
    palette: [WHITE, PALE, EMBER, SEA, PAIR, WHITE, WHITE, WHITE],
    weights: [3, 2.2, 0.8, 0, 0, 0, 0, 0],
  });
  readonly filaments = new Filaments();
  private r: Renderer | null = null;
  private saved: Partial<PostParams> = {};
  private readonly lights = new Best<VolumeLight>(8, () => ({ x: 0, y: 0, z: 0, radius: 1, color: [0, 0, 0] }));
  private readonly fronts = new Best<VolumeFront>(4, () => ({ x: 0, y: 0, radius: 1, width: 1, color: [0, 0, 0] }));
  private readonly kicks = new Best<StormKick>(4, () => ({ x: 0, y: 0, radius: 1, push: 0 }));
  private readonly speckLights = new Best<StormLight>(8, () => ({ x: 0, y: 0, intensity: 0, radius: 1, width: 0 }));
  /** Scratch for strips (the filaments copy what they are given). */
  private readonly seg = new Float32Array(Math.max(BOND_PTS, 16) * 2);
  private readonly segCore = new Float32Array(Math.max(BOND_PTS, 16));
  private readonly segSheath = new Float32Array(Math.max(BOND_PTS, 16));
  private readonly segHalf = new Float32Array(BOND_PTS);
  private readonly kColor: [number, number, number] = [0, 0, 0];
  private time = 0;

  constructor() {
    this.filaments.ribbon = true;
    this.filaments.arc = true;
  }

  attach(r: Renderer): void {
    this.r = r;
    r.setBackground(BLACK);
    r.setLayers([this.plasma, this.storm, this.filaments]);
    const post = r.post as unknown as Record<string, unknown>;
    for (const [k, v] of Object.entries(POST)) {
      (this.saved as Record<string, unknown>)[k] = post[k];
      post[k] = v;
    }
  }

  detach(r: Renderer): void {
    r.setLayers([]);
    Object.assign(r.post, this.saved);
    this.r = null;
  }

  /**
   * The state of the medium: `cool` 0 → 1 across the era, `gamma` 1 while light can still split
   * deuterium, `pulse` an event's lift, `freeze` 0 → 1 in the finale, `fizz` the electron–positron
   * glitter, `sea` how much hydrogen has sunk out of the play into the deep field.
   */
  medium(cool: number, gamma: number, pulse: number, freeze: number, fizz: number, sea: number): void {
    const p = this.plasma.config;
    p.heat = 0.48 - 0.16 * cool;
    p.brightness = (0.2 - 0.07 * cool) * (1 + 0.6 * pulse) * (1 - 0.65 * freeze);
    p.cool = [0.035 + 0.04 * gamma, 0.045 + 0.005 * gamma, 0.1 + 0.06 * gamma];
    const s = this.storm.config;
    s.twinkle = 0.2 + 0.45 * Math.min(1, fizz);
    s.swirl = 7 * (1 - 0.6 * freeze);
    s.spread = 0.008 * (1 - 0.5 * cool);
    s.weights[3] = 1.6 * sea;
    s.weights[4] = 1.4 * Math.min(1.5, fizz);
  }

  /** Starts a frame (the effect lists refill every frame); `t` is the era's clock. */
  /**
   * Drawing a copy of the periodic box (the view around the frame's field shows its copies): matter is
   * drawn, but nothing reaches the medium, which the box itself already lights.
   */
  ghost = false;

  begin(r: Renderer, t = this.time): void {
    this.r = r;
    this.time = t;
    this.lights.reset();
    this.fronts.reset();
    this.kicks.reset();
    this.speckLights.reset();
  }

  /**
   * A light inside the medium (it brightens and tints the plasma around it): colour `c` times `k`;
   * `key` (non-zero) names a light that persists from frame to frame.
   */
  light(x: number, y: number, radius: number, c: RGB, k = 1, key = 0): void {
    if (this.ghost) return;
    const L = this.lights.take(lum(c[0], c[1], c[2]) * k * radius, key);
    if (!L) return;
    L.x = x;
    L.y = y;
    L.z = 0;
    L.radius = radius;
    L.color[0] = c[0] * k;
    L.color[1] = c[1] * k;
    L.color[2] = c[2] * k;
  }

  /**
   * One nucleon as a crisp point light: a white-hot pinpoint in a tight halo of its colour (warm for
   * a proton, cool for a neutron). `depth` (-1 back … 1 front) dims and shrinks the ones behind;
   * `hot` (0–1) whitens and brightens a newborn. A `free` one (0–1) breathes slowly in a wider halo:
   * it is there to be grabbed, not a star behind the play.
   */
  nucleon(x: number, y: number, proton: boolean, k: number, depth = 0, hot = 0, shell: RGB | null = null, free = 0, seed = 0): void {
    const r = this.r;
    if (!r || k <= 0.003) return;
    const n = proton ? PROTON_LIGHT : NEUTRON_LIGHT;
    // Inside a closed shell the halo takes on the shell's colour (helium-4's gold), the core keeps its own.
    const c0 = shell ? n[0] * 0.4 + shell[0] * 0.6 : n[0];
    const c1 = shell ? n[1] * 0.4 + shell[1] * 0.6 : n[1];
    const c2 = shell ? n[2] * 0.4 + shell[2] * 0.6 : n[2];
    const d = 0.62 + 0.38 * (0.5 + 0.5 * depth);
    const breath = 1 + free * 0.22 * Math.sin(this.time * 2.3 + seed * 6.283);
    const e = k * d * (1 + 1.5 * hot);
    const s = 0.85 + 0.15 * d;
    const halo = 1 + 0.35 * free;
    // Light, not a disc: a tiny overexposed core (the bloom gives it its natural falloff), a tight rim
    // of its colour, and only a whisper of aura (on the dark medium a wide coloured halo reads as a
    // soft dot).
    r.top.push(x, y, 1.9 * s, 22 * e, 21.5 * e, 20.8 * e, 1, Shape.Glow);
    r.top.push(x, y, 5.2 * s * halo, (c0 + hot) * 1.1 * e * breath, (c1 + hot) * 1.1 * e * breath, (c2 + hot) * 1.1 * e * breath, 1, Shape.Glow);
    r.top.push(x, y, 18 * s * halo, c0 * 0.06 * e * breath, c1 * 0.06 * e * breath, c2 * 0.06 * e * breath, 1, Shape.Glow);
  }

  /**
   * A short bond between two nucleons of a nucleus, shading from `ca` to `cb`: a streamer of light,
   * mostly a translucent sheath around a faint thread (so the nucleons' point lights stay what the eye
   * reads), widening into a foot where it meets each nucleon.
   */
  bond(ax: number, ay: number, bx: number, by: number, ca: RGB, cb: RGB, k: number): void {
    if (k <= 0.003) return;
    const { seg: p, segCore: core, segSheath: sheath, segHalf: half } = this;
    for (let j = 0; j < BOND_PTS; j++) {
      const s = j / (BOND_PTS - 1);
      p[j * 2] = ax + (bx - ax) * s;
      p[j * 2 + 1] = ay + (by - ay) * s;
      // Narrowest at the middle; the ends fade into the nucleons' own light.
      const mid = Math.sin(Math.PI * s);
      const foot = 1 - mid;
      const cap = Math.min(1, mid * 3.2);
      half[j] = 2.6 + 3.2 * foot;
      core[j] = 0.3 * k * cap;
      sheath[j] = 0.45 * k * (0.7 + 0.6 * foot) * cap;
    }
    this.filaments.push(p, ca, cb, half, core, sheath, false, BOND_PTS);
  }

  /**
   * Helium-4, the closed shell, as a knot of light: the tightest-bound thing in the era, a white-gold
   * point brighter than any lone nucleon (its bloom gives it its falloff), in a tight gold glow of
   * radius `R` and a faint wide aura; its four nucleons glimmer inside it (drawn by the caller). `k` its
   * presence, `hot` a newborn's white heat. (A crescent drawn on its limb read as a stamp at this size.)
   */
  knot(x: number, y: number, R: number, k: number, hot: number): void {
    const r = this.r;
    if (!r || k <= 0.003) return;
    const w = k * (1 + 1.2 * hot);
    r.top.push(x, y, 2.2, 26 * w, 22 * w, 15 * w, 1, Shape.Glow);
    r.top.push(x, y, R * 0.6, 1.3 * w, 0.82 * w, 0.36 * w, 1, Shape.Glow);
    r.top.push(x, y, R * 2.2, 0.07 * w, 0.045 * w, 0.02 * w, 1, Shape.Glow);
  }

  /**
   * The wake of a flung or fast nucleus: a streak of light along its recent path (newest first in
   * `pts`), brightest at its head.
   */
  wake(pts: ArrayLike<number>, n: number, c: RGB, k: number): void {
    if (n < 3 || k <= 0.01) return;
    const m = Math.min(n, 16);
    const { seg: xy, segCore: core, segSheath: sheath } = this;
    for (let i = 0; i < m; i++) {
      // Oldest first, so the head is the end that keeps its brightness.
      const src = m - 1 - i;
      xy[i * 2] = pts[src * 2];
      xy[i * 2 + 1] = pts[src * 2 + 1];
      const f = (i + 1) / m;
      core[i] = 1.5 * f * f * k;
      sheath[i] = 0.22 * f * k;
    }
    this.filaments.push(xy, c, UNIT, 6, core, sheath, false, m);
  }

  // ─── FxLook: the era's effects, restyled

  flash(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * (1 - t);
    const rr = this.r;
    if (!rr || f <= 0.003) return;
    rr.top.push(x, y, Math.min(3.5, 1.4 + size * 0.04), r * f * 1.5, g * f * 1.5, b * f * 1.5, 1, Shape.Glow);
    rr.top.push(x, y, size * 0.5, r * f * 0.22, g * f * 0.22, b * f * 0.22, 1, Shape.Glow);
    this.kColor[0] = r;
    this.kColor[1] = g;
    this.kColor[2] = b;
    this.light(x, y, size * 2.4, this.kColor, f * 0.45);
    const l = lum(r, g, b) * f;
    const sl = this.speckLights.take(l * size * 0.02);
    if (sl) {
      sl.x = x;
      sl.y = y;
      sl.intensity = 2.5 * l;
      sl.radius = size * 1.6;
      sl.width = 0;
    }
  }

  ring(x: number, y: number, radius: number, r: number, g: number, b: number, t: number): void {
    const f = Math.pow(1 - t, 1.6);
    if (f <= 0.01) return;
    const l = lum(r, g, b);
    const front = this.fronts.take(l * f);
    if (front) {
      front.x = x;
      front.y = y;
      front.radius = radius;
      front.width = 26 + radius * 0.1;
      front.color[0] = r * 0.05 * f;
      front.color[1] = g * 0.05 * f;
      front.color[2] = b * 0.05 * f;
    }
    const kick = this.kicks.take(l * f);
    if (kick) {
      kick.x = x;
      kick.y = y;
      kick.radius = radius;
      kick.push = 2200 * Math.min(2, l) * f;
    }
    const sl = this.speckLights.take(l * f);
    if (sl) {
      sl.x = x;
      sl.y = y;
      sl.intensity = (5 * l * f) / (1 + radius / 900);
      sl.radius = radius;
      sl.width = 30 + radius * 0.12;
    }
  }

  spark(x: number, y: number, vx: number, vy: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = 1 - t;
    if (Math.hypot(vx, vy) > 1000) {
      // Anything this fast is light.
      this.photon(x, y, vx, vy, size, r, g, b, t);
      return;
    }
    // Debris from a reaction: short, quick streaks that fade fast.
    const k = Math.min(2, size * 0.3) * f * f;
    if (k <= 0.01) return;
    // The streak's colour at unit brightness (its intensity comes from k).
    const l = Math.max(1, lum(r, g, b));
    const c = this.kColor;
    c[0] = r / l;
    c[1] = g / l;
    c[2] = b / l;
    const tx = x - vx * 0.03;
    const ty = y - vy * 0.03;
    const { seg: p, segCore: core, segSheath: sheath } = this;
    p[0] = tx;
    p[1] = ty;
    p[2] = (tx + x) / 2;
    p[3] = (ty + y) / 2;
    p[4] = x;
    p[5] = y;
    core[0] = 0;
    core[1] = 0.4 * k;
    core[2] = 1.2 * k;
    sheath[0] = 0;
    sheath[1] = 0.04 * k;
    sheath[2] = 0.08 * k;
    this.filaments.push(p, c, UNIT, 3, core, sheath, false, 3);
  }

  /**
   * A photon (the bath's, a capture's gamma ray, an annihilation's): a faint wave packet racing
   * across, tinted by its colour. Faint on purpose: the bath is everywhere, and the nucleons are what
   * the eye should find.
   */
  photon(x: number, y: number, vx: number, vy: number, size: number, r: number, g: number, b: number, t: number): void {
    const k = Math.min(0.45, size * 0.1) * Math.min(1, t * 12, (1 - t) * 4);
    const c = this.kColor;
    c[0] = r;
    c[1] = g;
    c[2] = b;
    packet(this.filaments, x, y, vx, vy, k, b > r * 1.6 ? BATH : c, 9 + 2 * size, 13, this.time);
  }

  puff(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * Math.min(1, t * 6);
    if (f <= 0.01) return;
    this.kColor[0] = r;
    this.kColor[1] = g;
    this.kColor[2] = b;
    this.light(x, y, size, this.kColor, 0.3 * f);
  }

  /** Ends the frame: the strongest lights, fronts and pushes go to the layers (each has a few slots). */
  end(): void {
    this.plasma.lights = this.lights.list();
    this.plasma.fronts = this.fronts.list();
    this.plasma.tubes = NO_TUBES;
    this.storm.kicks = this.kicks.list();
    this.storm.lights = this.speckLights.list();
  }
}
