/**
 * The First Three Minutes simulation.
 *
 * Charged nuclei repel with an inverse-square force, so slow ones swerve apart and only fast ones
 * touch; touching means they beat the Coulomb barrier, and they fuse (near misses may tunnel).
 * Neutrons feel no repulsion. Free neutrons decay into protons. Until the bottleneck breaks, light
 * splits deuterium almost as soon as it forms. Nucleons stream in from the horizon, about one
 * neutron for every six or seven protons; locking those neutrons into helium-4 is the whole game.
 */
import type { EraModule, OfflineReport, PointerInfo, StockView, WorldLabel } from '../../core/era';
import type { Game } from '../../core/game';
import { fieldHalf } from '../../core/field';
import { count, percent, toText } from '../../core/format';
import { RateMeter } from '../../core/meter';
import type { RGB } from '../../render/color';
import { Fx, FxPool } from '../../render/fx';
import { LineStyle } from '../../render/lines';
import type { Renderer } from '../../render/renderer';
import { Shape } from '../../render/sprites';
import { Grid } from '../../physics/grid';
import { Particles } from '../../physics/particles';
import { Torus } from '../../physics/torus';
import type { NucleoBgParams } from './background';
import { GOLD_LIGHT, ICE_LIGHT, NEUTRON_LIGHT, NucleoLook, PROTON_LIGHT } from './look';
import { SPECIES, Sp, radiusOf, reactionsFor, type Reaction } from './reactions';

const F_HELD = 1;
const F_FLUNG = 2;
const F_FADE = 4;
const F_FAST = 8;

const MEV = 1e6;
/**
 * How many free protons the field keeps in focus at each step. The field is a thin slice of the
 * universe, and as it expands the slice holds fewer nuclei: the rest of the hydrogen lies outside
 * it, a soft out-of-focus sea behind the play. Stocks count every proton either way.
 */
const FOCUS_P = [120, 140, 130, 120, 110, 100, 100];
/** Settled helium-4 in focus; the oldest sink into the sea so new fusions stay easy to see. */
const FOCUS_HE4 = 48;
/** Seconds the sea takes to forget hydrogen that sank into it (cosmetic brightness only). */
const SEA_MEMORY = 40;
const NEUTRON_LIFETIME = 110;
/** Coulomb strength: tuned so a single-charge pair needs ~200 world units/s to touch. */
const COULOMB = 3.0e5;
const COULOMB_RANGE = 90;
const FLING_MAX = 720;
/** A fast neutron's speed (world units a second): it crosses the field once, then it is gone. */
const FAST_SPEED = 300;

/** Photodisintegration rate of deuterium (per nucleus per second) at each epoch step. */
const PHOTO = [2.4, 1.5, 0.85, 0.03, 0.004, 0, 0];
/** Thermal speed scale per step (world units per second). */
const VTH = [125, 112, 100, 90, 80, 70, 60];
/**
 * Neutron share of incoming nucleons per step: one neutron for every six protons at freeze-out,
 * falling to one for every seven as neutrons decay. A share of 1 in 8 caps helium-4 at 25 % by mass.
 */
const NEUTRON_SHARE = [1 / 7, 1 / 7.3, 1 / 7.6, 1 / 8, 1 / 8, 1 / 8, 1 / 8];
/** Capture chance on contact for neutron reactions (no barrier, but not every touch sticks). */
const CAPTURE: Partial<Record<number, number>> = { [Sp.P]: 0.7, [Sp.D]: 0.35, [Sp.He3]: 0.45 };

/** Closed-shell gold of helium-4: the prize (the census columns use it). */
const GOLD: RGB = [1.0, 0.74, 0.36];
/** White-hot tint a newborn nucleus cools from. */
const HOT: RGB = [1.7, 1.45, 1.1];

/** Nucleon size inside a nucleus (world units): sets the spacing of its point lights. */
const NUC_R = 8.2;
/** The freeze-out census: nuclei per row in a column, and their spacing (world units). */
const CENSUS_ROW = 5;
const CENSUS_GAP = 21;
/** Centre-to-centre spacing of bound nucleons, in nucleon radii (they overlap, as bound things do). */
const BOND = 1.5;

interface Nucleon {
  x: number;
  y: number;
  z: number;
  p: boolean;
}

/**
 * Nucleon positions in 3D, in units of one bond length. Planar nuclei (D, T, ³He) spin in the
 * screen plane with a slight wobble so they never collapse to a single ball; helium-4 (a
 * tetrahedron) and the seven-nucleon nuclei tumble freely.
 */
const S3 = 0.3536;
const SHAPE3D: Record<number, Nucleon[]> = {
  [Sp.P]: [{ x: 0, y: 0, z: 0, p: true }],
  [Sp.N]: [{ x: 0, y: 0, z: 0, p: false }],
  [Sp.D]: [
    { x: -0.5, y: 0, z: 0, p: true },
    { x: 0.5, y: 0, z: 0, p: false },
  ],
  [Sp.T]: [
    { x: 0, y: -0.577, z: 0, p: true },
    { x: -0.5, y: 0.289, z: 0, p: false },
    { x: 0.5, y: 0.289, z: 0, p: false },
  ],
  [Sp.He3]: [
    { x: 0, y: -0.577, z: 0, p: false },
    { x: -0.5, y: 0.289, z: 0, p: true },
    { x: 0.5, y: 0.289, z: 0, p: true },
  ],
  [Sp.He4]: [
    { x: S3, y: S3, z: S3, p: true },
    { x: -S3, y: -S3, z: S3, p: true },
    { x: S3, y: -S3, z: -S3, p: false },
    { x: -S3, y: S3, z: -S3, p: false },
  ],
  [Sp.Li7]: hex7([true, false, true, false, false, true, false]),
  [Sp.Be7]: hex7([false, true, true, false, true, true, false]),
};

/**
 * The bonds drawn inside each nucleus: index pairs of nucleons about one bond length apart in 3D
 * (every pair in the planar nuclei and helium-4's tetrahedron; the centre and ring neighbours of the
 * seven-nucleon ones).
 */
const BONDS: Record<number, number[]> = Object.fromEntries(
  Object.entries(SHAPE3D).map(([sp, ns]) => {
    const out: number[] = [];
    for (let i = 0; i < ns.length; i++)
      for (let j = i + 1; j < ns.length; j++) if (Math.hypot(ns[i].x - ns[j].x, ns[i].y - ns[j].y, ns[i].z - ns[j].z) < 1.2) out.push(i, j);
    return [sp, out];
  }),
);

/** A colour scaled by a brightness. */
const tint = (c: readonly [number, number, number], k: number): [number, number, number] => [c[0] * k, c[1] * k, c[2] * k];

/** A centre nucleon ringed by six, the ring slightly puckered so it reads as a solid body. */
function hex7(protons: boolean[]): Nucleon[] {
  const out: Nucleon[] = [{ x: 0, y: 0, z: 0, p: protons[0] }];
  for (let k = 0; k < 6; k++) {
    const a = (k / 6) * Math.PI * 2;
    out.push({ x: Math.cos(a) * 0.95, y: Math.sin(a) * 0.95, z: k % 2 ? 0.28 : -0.28, p: protons[k + 1] });
  }
  return out;
}

/** Stable 0..1 value per particle id (cosmetic variation only). */
function idHash(id: number): number {
  let h = Math.imul(id ^ 0x9e3779b9, 0x85ebca6b);
  h ^= h >>> 13;
  h = Math.imul(h, 0xc2b2ae35);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

/** Seconds the electron–positron annihilation takes to sweep the field (cosmetic). */
const SWEEP_T = 1.4;

/** Trail history for flung and fast nuclei (cosmetic). */
const TRAIL = 14;
interface Trail {
  x: Float32Array;
  y: Float32Array;
  n: number;
  seen: number;
}

export interface NucleoState {
  /** Real number of nuclei of each species in the region (index = Sp). */
  count: number[];
  decayed: number;
  fusions: number;
  yp: number;
  heRate: number;
  inflowRate: number;
  everFlung: boolean;
  everFused: boolean;
  everCaught: boolean;
  fastClock: number;
}

function defaults(): NucleoState {
  return {
    count: [0, 0, 0, 0, 0, 0, 0, 0],
    decayed: 0,
    fusions: 0,
    yp: 0,
    heRate: 0,
    inflowRate: 0,
    everFlung: false,
    everFused: false,
    everCaught: false,
    fastClock: 30,
  };
}

interface Census {
  label: string;
  share: number;
  x: number;
  species: Sp[];
  /** How many nuclei the column shows: proportional to the real mass share. */
  slots: number;
}

export class NucleoEra implements EraModule {
  private readonly p = new Particles(900);
  private readonly grid = new Grid(COULOMB_RANGE, 900);
  private readonly fx = new FxPool(900);
  private readonly s: NucleoState;
  private readonly bgParams: NucleoBgParams = { cool: 0, gamma: 1, pulse: 0, freeze: 0, fizz: 0, sea: 0 };
  /** How it all looks (version 2): the dim plasma, the sparse storm, nucleons as point lights, the effects. */
  private readonly look = new NucleoLook();
  private halfW = 889;
  private halfH = 500;
  /** The frame's field, a periodic box: a nucleus flung off one side comes back in through the other. */
  private readonly box = new Torus();
  private readonly images: number[] = [];
  private t = 0;
  private idle = 0;

  private inflow = 2;
  private tail = 1;
  private tunnel = 0.03;
  private energyMult = 1;
  private capture = 0;
  private cross = 1;
  private network = 0;
  private fling = 1;
  private photoMult = 1;
  private barrier = 1;
  private etaFactor = 1;
  private w0 = 1e12;

  private inflowAcc = 0;
  /** Free protons in focus (recounted by thinOut, kept current by arrivals). */
  private focusP = 0;
  /** Hydrogen that recently sank into the sea, for its glow. */
  private sunk = 0;
  private held = 0;
  private grabX = 0;
  private grabY = 0;
  private pX = 0;
  private pY = 0;
  private readonly heMeter = new RateMeter(20);
  private readonly inflowMeter = new RateMeter(20);
  private fizz = 0;
  /** Visual only: the electron–positron annihilation's sweep (seconds in, -1 when none) and its pairs to come. */
  private sweepT = -1;
  private sweepAcc = 0;
  private hintClock = 0;
  private sawBottleneckBreak = false;
  private unsub: (() => void)[] = [];

  private finaleT = -1;
  private finaleDone: (() => void) | null = null;
  private census: Census[] | null = null;
  private tallied = false;

  constructor(private readonly g: Game) {
    const run = g.state.run;
    this.s = (run.eras.nucleo as NucleoState | undefined) ?? defaults();
    run.eras.nucleo = this.s;
    const baryons = run.legacy.baryons ?? 3.5e7;
    this.w0 = 1e11 * Math.min(3, Math.max(0.3, Math.sqrt(baryons / 3.5e7)));
    // More matter per photon (η, from the Soup) means fewer photons able to split each deuteron.
    const eta = run.legacy.eta ?? 0.05;
    this.etaFactor = Math.min(2, Math.max(0.5, Math.pow(0.05 / Math.max(eta, 1e-6), 0.3)));
  }

  // ───────────────────────────────────────── lifecycle

  enter(fresh: boolean): void {
    const g = this.g;
    if (g.renderer) this.look.attach(g.renderer);
    this.refreshStats();
    this.unsub.push(g.stats.onChange(() => this.refreshStats()));
    this.heMeter.reset(this.s.heRate);
    this.inflowMeter.reset(this.s.inflowRate);
    this.syncStepFlags();
    const step = g.state.run.step;
    this.bgParams.cool = step / 6;
    this.bgParams.gamma = step >= 3 ? 0 : 1;
    this.sawBottleneckBreak = step >= 3;
    if (fresh) {
      const w = this.weight;
      for (let k = 0; k < 70; k++) this.spawnNucleon(k < 10 ? Sp.N : Sp.P, true);
      // The camera arrives drawing back from the Soup, whose whole field is smaller than one proton
      // here: that field, its quarks now confined, is the proton at the centre.
      const c = this.spawnNucleon(Sp.P, true);
      if (c >= 0) {
        this.p.x[c] = 0;
        this.p.y[c] = 0;
        this.p.vx[c] *= 0.25;
        this.p.vy[c] *= 0.25;
      }
      this.s.count[Sp.P] = 61 * w;
      this.s.count[Sp.N] = 10 * w;
      this.fizz = 1;
    } else {
      this.resample();
      this.fizz = step === 0 ? 1 : 0;
    }
  }

  exit(): void {
    if (this.g.renderer) this.look.detach(this.g.renderer);
    for (const u of this.unsub) u();
    this.unsub = [];
  }

  resize(halfW: number, halfH: number): void {
    this.halfW = halfW;
    this.halfH = halfH;
    // The era plays in a periodic box the size of the whole view, as a simulation of uniform space does:
    // what leaves at one edge of the screen comes back at the opposite one.
    this.box.set(halfW, halfH);
    this.grid.setBounds(-halfW, -halfH, halfW, halfH, true);
    const p = this.p;
    for (let i = 0; i < p.n; i++) {
      p.x[i] = this.box.wrapX(p.x[i]);
      p.y[i] = this.box.wrapY(p.y[i]);
    }
  }

  private refreshStats(): void {
    const st = this.g.stats;
    this.inflow = st.get('nucleo.inflow');
    this.tail = st.get('nucleo.tail');
    this.tunnel = st.get('nucleo.tunnel');
    this.energyMult = st.get('nucleo.energyMult');
    this.capture = st.get('nucleo.capture');
    this.cross = st.get('nucleo.cross');
    this.network = st.get('nucleo.network');
    this.fling = st.get('nucleo.fling');
    this.photoMult = st.get('nucleo.photoMult');
    this.barrier = st.get('nucleo.barrier');
  }

  private get step(): number {
    return this.g.state.run.step;
  }

  private get weight(): number {
    return this.w0 * 10 ** this.step;
  }

  private syncStepFlags(): void {
    for (let i = 1; i <= 6; i++) this.g.setFlag(`nucleo.step${i}`, this.step >= i);
  }

  /** Rebuild a visible sample from the stocks after loading a save. */
  private resample(): void {
    const c = this.s.count;
    const total = c.reduce((a, b) => a + b, 0) || 1;
    const n = 160;
    for (let sp = 0; sp < 8; sp++) {
      // Never more dots than the stock holds whole nuclei, or a fusion could drive it negative.
      const k = Math.min(Math.round((c[sp] / total) * n), Math.floor(c[sp] / this.weight), 120, this.focusCap(sp as Sp));
      for (let j = 0; j < k; j++) this.spawnNucleon(sp as Sp, true);
    }
  }

  // ───────────────────────────────────────── spawning and events

  private spawnNucleon(sp: Sp, anywhere: boolean): number {
    const rng = this.g.sim;
    let x: number;
    let y: number;
    let vx: number;
    let vy: number;
    const v = VTH[this.step] * rng.range(0.6, 1.3);
    // Anywhere: a periodic box has no edge to arrive from, so newcomers (light from farther away bringing
    // more of the universe into view) fade in where they are.
    x = rng.range(-this.box.hx, this.box.hx);
    y = rng.range(-this.box.hy, this.box.hy);
    const a = rng.angle();
    vx = Math.cos(a) * v * (anywhere ? 1 : 1.2);
    vy = Math.sin(a) * v * (anywhere ? 1 : 1.2);
    const i = this.p.spawn(sp, x, y, vx, vy, radiusOf(sp), 1);
    if (i < 0) return -1;
    this.p.a[i] = rng.angle();
    if (sp === Sp.N) this.p.life[i] = rng.exp(NEUTRON_LIFETIME);
    return i;
  }

  private arrive(dt: number): void {
    const s = this.s;
    const rng = this.g.sim;
    this.inflowAcc += this.inflow * dt;
    while (this.inflowAcc >= 1) {
      this.inflowAcc -= 1;
      const sp = rng.chance(NEUTRON_SHARE[this.step]) ? Sp.N : Sp.P;
      const w = this.weight;
      s.count[sp] += w;
      this.inflowMeter.add(w);
      // A proton arriving while the slice is full joins the sea instead (it still counts).
      if (sp === Sp.P && this.focusP >= FOCUS_P[this.step]) this.sunk++;
      else if (this.p.n < this.p.cap - 40 && this.spawnNucleon(sp, false) >= 0 && sp === Sp.P) this.focusP++;
    }
  }

  /** How many nuclei of a species the field keeps in focus. */
  private focusCap(sp: Sp): number {
    return sp === Sp.P ? FOCUS_P[this.step] : sp === Sp.He4 ? FOCUS_HE4 : Infinity;
  }

  /**
   * Keep the screen readable: beyond the focus caps the oldest free protons and settled helium sink
   * out of the slice into the sea (stocks untouched). Anything held or in flight stays.
   */
  private thinOut(): void {
    const p = this.p;
    const P: number[] = [];
    const He4: number[] = [];
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i) || p.flags[i] & (F_FADE | F_HELD | F_FLUNG | F_FAST)) continue;
      const sp = p.kind[i];
      if (sp === Sp.P) P.push(i);
      else if (sp === Sp.He4) He4.push(i);
    }
    const byAge = (a: number, b: number) => p.age[b] - p.age[a];
    const sink = (list: number[], cap: number) => {
      if (list.length <= cap) return 0;
      list.sort(byAge);
      const n = list.length - cap;
      for (let k = 0; k < n; k++) {
        p.flags[list[k]] |= F_FADE;
        p.b[list[k]] = 1;
      }
      return n;
    };
    const sunkP = sink(P, FOCUS_P[this.step]);
    this.sunk += sunkP;
    this.focusP = P.length - sunkP;
    sink(He4, FOCUS_HE4);
  }

  private fuse(i: number, j: number, r: Reaction): void {
    const p = this.p;
    const g = this.g;
    const s = this.s;
    const w = this.weight;
    const ai = SPECIES[p.kind[i]].A;
    const aj = SPECIES[p.kind[j]].A;
    const x = (p.x[i] * ai + p.x[j] * aj) / (ai + aj);
    const y = (p.y[i] * ai + p.y[j] * aj) / (ai + aj);
    const vx = (p.vx[i] * ai + p.vx[j] * aj) / (ai + aj);
    const vy = (p.vy[i] * ai + p.vy[j] * aj) / (ai + aj);
    const flung = (p.flags[i] | p.flags[j]) & F_FLUNG;
    s.count[p.kind[i]] -= w;
    s.count[p.kind[j]] -= w;
    p.kill(i);
    p.kill(j);
    const k = p.spawn(r.product, x, y, vx * 0.6, vy * 0.6, radiusOf(r.product), 1);
    if (k >= 0) p.a[k] = g.fx.angle();
    s.count[r.product] += w;
    if (r.ejects !== undefined) {
      const a = g.sim.angle();
      const e = p.spawn(r.ejects, x, y, Math.cos(a) * 260, Math.sin(a) * 260, radiusOf(r.ejects), 1);
      if (e >= 0 && r.ejects === Sp.N) p.life[e] = g.sim.exp(NEUTRON_LIFETIME);
      s.count[r.ejects] += w;
    }
    // A flung collision also releases the energy it was thrown with.
    const e = r.q * MEV * w * this.energyMult * (flung ? 1.9 : 1);
    if (flung || r.product === Sp.He4) g.gain(e, x, y);
    else g.gain(e);
    s.fusions += w;
    s.everFused = true;
    if (r.product === Sp.He4) this.heMeter.add(w);

    const big = r.q > 10;
    const he = r.product === Sp.He4;
    // A white-hot pin of light, a warm bloom around it, a crisp shell of light and a spray of sparks.
    this.fx.spawn(Fx.Flash, x, y, 0.14, big ? 18 : 12, 5, 4.4, 3.6, big ? 40 : 24);
    this.fx.spawn(Fx.Flash, x, y, big ? 0.5 : 0.32, big ? 40 : 24, big ? 2.4 : 1.6, big ? 1.8 : 1.25, big ? 1.0 : 0.75, big ? 120 : 70);
    this.fx.spawn(Fx.Ring, x, y, big ? 0.5 : 0.34, 12, big ? 1.8 : 1.1, big ? 1.4 : 0.9, big ? 0.85 : 0.6, big ? 320 : 210);
    if (he) this.fx.spawn(Fx.Ring, x, y, 0.9, 20, 1.0, 0.74, 0.36, 110);
    const sparks = big ? 9 : 4;
    for (let k = 0; k < sparks; k++) {
      const a = g.fx.angle();
      const v = g.fx.range(260, big ? 620 : 420);
      this.fx.spawn(Fx.Spark, x, y, g.fx.range(0.25, 0.45), 2.2, 2.2, 1.6, 0.8, 0, Math.cos(a) * v, Math.sin(a) * v, 5);
    }
    // The gamma ray carried off by radiative capture.
    if (r.ejects === undefined) {
      const a = g.fx.angle();
      this.fx.spawn(Fx.Photon, x, y, 0.25, 4, 1.6, 1.3, 2.6, 0, Math.cos(a) * 1200, Math.sin(a) * 1200);
    }
    if (big) {
      g.renderer?.shock(x, y, 0.25, 0.7, 0.8);
      g.renderer?.camera.addTrauma(0.05);
    }
    if (r.product === Sp.He4) g.sfx('nucleo.he4', x);
    else g.sfx('nucleo.fuse', x, 1, r.product);
    g.discover(SPECIES[r.product].codex);
    if (r.ejects !== undefined) g.discover(SPECIES[r.ejects].codex);
  }

  private breakDeuteron(i: number): void {
    const p = this.p;
    const g = this.g;
    const w = this.weight;
    const x = p.x[i];
    const y = p.y[i];
    p.kill(i);
    this.s.count[Sp.D] -= w;
    this.s.count[Sp.P] += w;
    this.s.count[Sp.N] += w;
    const a = g.sim.angle();
    const c = Math.cos(a);
    const sn = Math.sin(a);
    const pi = p.spawn(Sp.P, x + c * 6, y + sn * 6, c * 150, sn * 150, radiusOf(Sp.P), 1);
    const ni = p.spawn(Sp.N, x - c * 6, y - sn * 6, -c * 150, -sn * 150, radiusOf(Sp.N), 1);
    if (pi >= 0) p.a[pi] = 0;
    if (ni >= 0) p.life[ni] = g.sim.exp(NEUTRON_LIFETIME);
    // The photon that did it: a violet streak arriving from afar.
    const b = g.fx.angle();
    const bc = Math.cos(b);
    const bs = Math.sin(b);
    this.fx.spawn(Fx.Photon, x - bc * 160, y - bs * 160, 0.12, 4, 1.8, 1.3, 3.8, 0, bc * 1300, bs * 1300);
    this.fx.spawn(Fx.Photon, x, y, 0.3, 3, 1.0, 0.75, 2.2, 0, bc * 1300, bs * 1300);
    this.fx.spawn(Fx.Flash, x, y, 0.22, 14, 1.4, 1.0, 2.8, 40);
    this.fx.spawn(Fx.Ring, x, y, 0.3, 8, 0.9, 0.6, 1.8, 150);
    g.sfx('nucleo.break', x);
  }

  /**
   * The electron–positron annihilation, cosmetic: behind the front sweeping out from the centre, the
   * pairs it reaches burn into light, each a point flash and two photons racing apart back to back.
   */
  private sweepAnnihilation(dt: number): void {
    const g = this.g;
    const reach = Math.hypot(this.box.hx, this.box.hy);
    const r0 = reach * Math.min(1, this.sweepT / SWEEP_T);
    this.sweepT += dt;
    const r1 = reach * Math.min(1, this.sweepT / SWEEP_T);
    // As many pairs as the front's new band covers (about sixty across the whole field).
    this.sweepAcc += (60 * (r1 * r1 - r0 * r0)) / (reach * reach);
    while (this.sweepAcc >= 1) {
      this.sweepAcc -= 1;
      const a = g.fx.angle();
      const d = Math.sqrt(g.fx.range(r0 * r0, r1 * r1));
      const x = Math.cos(a) * d;
      const y = Math.sin(a) * d;
      if (Math.abs(x) > this.box.hx || Math.abs(y) > this.box.hy) continue;
      this.fx.spawn(Fx.Flash, x, y, g.fx.range(0.3, 0.7), g.fx.range(10, 24), 1.5, 1.7, 2.4, 40);
      const b = g.fx.angle();
      const c = Math.cos(b) * 1300;
      const s = Math.sin(b) * 1300;
      this.fx.spawn(Fx.Photon, x, y, 0.5, 2.8, 1.0, 1.15, 1.7, 0, c, s);
      this.fx.spawn(Fx.Photon, x, y, 0.5, 2.8, 1.0, 1.15, 1.7, 0, -c, -s);
    }
    if (this.sweepT >= SWEEP_T) {
      this.sweepT = -1;
      this.sweepAcc = 0;
    }
  }

  private decayNeutron(i: number): void {
    const p = this.p;
    const g = this.g;
    const w = this.weight;
    p.kind[i] = Sp.P;
    p.r[i] = radiusOf(Sp.P);
    p.life[i] = Infinity;
    this.s.count[Sp.N] -= w;
    this.s.count[Sp.P] += w;
    this.s.decayed += w;
    const a = g.fx.angle();
    this.fx.spawn(Fx.Spark, p.x[i], p.y[i], 0.5, 2.5, 1.6, 1.8, 2.2, 0, Math.cos(a) * 520, Math.sin(a) * 520);
    this.fx.spawn(Fx.Flash, p.x[i], p.y[i], 0.25, 18, 1.2, 1.3, 1.6, 20);
    g.sfx('nucleo.decay', p.x[i]);
  }

  // ───────────────────────────────────────── simulation

  update(dt: number): void {
    const g = this.g;
    const p = this.p;
    const rng = g.sim;
    this.t += dt;
    this.idle += dt;
    this.hintClock += dt;
    const inFinale = this.finaleT >= 0;

    if (!inFinale) {
      this.arrive(dt);
      this.updateFast(dt);
    } else this.updateFinale(dt);

    // Electron–positron fizz before the annihilation step (purely visual).
    const pairs = this.fizz > 0 && this.step === 0;
    if (pairs && g.fx.chance(dt * 10)) {
      // A pair blinks into being, flies apart a little and is gone.
      const x = g.fx.range(-this.box.hx, this.box.hx);
      const y = g.fx.range(-this.box.hy, this.box.hy);
      const a = g.fx.angle();
      const c = Math.cos(a) * 170;
      const sn = Math.sin(a) * 170;
      this.fx.spawn(Fx.Flash, x, y, 0.22, 7, 1.3, 1.5, 2.1, 16);
      this.fx.spawn(Fx.Spark, x, y, 0.3, 2, 1.0, 1.25, 1.9, 0, c, sn, 4);
      this.fx.spawn(Fx.Spark, x, y, 0.3, 2, 1.0, 1.25, 1.9, 0, -c, -sn, 4);
    }
    const fz = this.bgParams.fizz;
    this.bgParams.fizz = pairs ? fz + (1 - fz) * Math.min(1, dt * 2) : fz * Math.exp(-dt * 0.9);
    if (this.sweepT >= 0) this.sweepAnnihilation(dt);
    // While light can still split deuterium, hard photons streak across the bath.
    const hard = inFinale ? 0 : PHOTO[this.step] * this.photoMult * this.etaFactor;
    if (hard > 0.02 && g.fx.chance(dt * 5 * Math.min(1, hard))) {
      const a = g.fx.angle();
      const c = Math.cos(a);
      const sn = Math.sin(a);
      const ox = g.fx.range(-this.box.hx, this.box.hx) * 0.8;
      const oy = g.fx.range(-this.box.hy, this.box.hy) * 0.8;
      const back = Math.max(this.box.hx, this.box.hy);
      this.fx.spawn(Fx.Photon, ox - c * back, oy - sn * back, 1.4, 2.6, 0.75, 0.55, 1.9, 0, c * 1500, sn * 1500);
    }

    const sub = 2;
    const h = dt / sub;
    const vth = VTH[this.step];
    const photo = PHOTO[this.step] * this.photoMult * this.etaFactor;
    const kickRate = inFinale ? 0 : 0.035 * this.tail;
    const box = this.box;
    for (let k = 0; k < sub; k++) {
      this.grid.build(p);
      for (let i = 0; i < p.n; i++) {
        if (p.isDead(i)) continue;
        const sp = p.kind[i] as Sp;
        if (p.flags[i] & F_HELD) {
          p.vx[i] = 0;
          p.vy[i] = 0;
          continue;
        }
        if (p.flags[i] & F_FADE) {
          // Sinking out of the slice: it slows and drifts, past the reach of anything in focus.
          const damp = Math.exp(-2.2 * h);
          p.vx[i] *= damp;
          p.vy[i] *= damp;
          p.x[i] = box.wrapX(p.x[i] + p.vx[i] * h);
          p.y[i] = box.wrapY(p.y[i] + p.vy[i] * h);
          continue;
        }
        const Zi = SPECIES[sp].Z;
        const Ai = SPECIES[sp].A;
        let ax = 0;
        let ay = 0;
        // Coulomb repulsion between charged nuclei; neutrons drawn toward nuclei with Neutron Capture.
        this.grid.near(p.x[i], p.y[i], COULOMB_RANGE, (j) => {
          if (j === i || p.isDead(j) || p.flags[j] & F_FADE) return;
          const Zj = SPECIES[p.kind[j]].Z;
          const dx = box.dx(p.x[i] - p.x[j]);
          const dy = box.dy(p.y[i] - p.y[j]);
          const d2 = dx * dx + dy * dy;
          if (d2 > COULOMB_RANGE * COULOMB_RANGE || d2 < 1) return;
          const d = Math.sqrt(d2);
          if (Zi > 0 && Zj > 0) {
            const f = (COULOMB * this.barrier * Zi * Zj) / (d2 + 60) / Ai;
            ax += (dx / d) * f;
            ay += (dy / d) * f;
          } else if (Zi === 0 && Zj > 0 && this.capture > 0 && !inFinale) {
            const f = (this.capture * 140) / Ai;
            ax -= (dx / d) * f;
            ay -= (dy / d) * f;
          }
        });
        // Thermal kicks: the fast tail of the distribution.
        if (kickRate > 0 && rng.chance(kickRate * h)) {
          const a = rng.angle();
          const v = vth * (1 + rng.exp(0.62 + 0.08 * this.tail));
          p.vx[i] = Math.cos(a) * v;
          p.vy[i] = Math.sin(a) * v;
        }
        // Gentle relaxation toward thermal speed.
        const speed = Math.hypot(p.vx[i], p.vy[i]);
        const relax = speed > vth * 1.2 ? Math.exp(-0.35 * h) : 1;
        p.vx[i] = (p.vx[i] + ax * h) * relax;
        p.vy[i] = (p.vy[i] + ay * h) * relax;
        if (inFinale) {
          const damp = Math.exp(-1.6 * h);
          p.vx[i] *= damp;
          p.vy[i] *= damp;
        }
        p.x[i] = box.wrapX(p.x[i] + p.vx[i] * h);
        p.y[i] = box.wrapY(p.y[i] + p.vy[i] * h);
      }
      if (!inFinale) this.collide(rng, h);
    }

    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      p.age[i] += dt;
      p.a[i] += dt * 0.6;
      if (p.flags[i] & F_FLUNG) {
        p.b[i] -= dt;
        if (p.b[i] <= 0) p.flags[i] &= ~F_FLUNG;
      }
      if (p.flags[i] & F_FADE) {
        p.b[i] -= dt * 0.8;
        if (p.b[i] <= 0) p.kill(i);
        continue;
      }
      const sp = p.kind[i];
      if (sp === Sp.N && !(p.flags[i] & F_FAST)) {
        p.life[i] -= dt * (inFinale ? 8 : 1);
        if (p.life[i] <= 0) {
          this.decayNeutron(i);
          continue;
        }
      }
      if (sp === Sp.D && photo > 0 && !inFinale && rng.chance(photo * dt)) this.breakDeuteron(i);
    }

    if (!inFinale && this.t % 0.5 < dt) this.thinOut();
    p.compact();
    this.fx.update(dt);
    this.heMeter.tick(dt);
    this.inflowMeter.tick(dt);
    this.s.heRate = this.heMeter.rate;
    this.s.inflowRate = this.inflowMeter.rate;
    this.updateYp();
    this.bgParams.pulse *= Math.exp(-dt * 2);
    this.sunk *= Math.exp(-dt / SEA_MEMORY);
    const sea = 1 - Math.exp(-this.sunk / 120);
    this.bgParams.sea += (sea - this.bgParams.sea) * Math.min(1, dt * 0.5);
  }

  private collide(rng: Game['sim'], h: number): void {
    const p = this.p;
    const box = this.box;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i) || p.flags[i] & (F_HELD | F_FADE | F_FAST)) continue;
      const ri = p.r[i] * this.cross;
      this.grid.near(p.x[i], p.y[i], 40, (j) => {
        if (j <= i || p.isDead(i) || p.isDead(j) || p.flags[j] & (F_HELD | F_FADE | F_FAST)) return;
        const dx = box.dx(p.x[j] - p.x[i]);
        const dy = box.dy(p.y[j] - p.y[i]);
        const rr = (ri + p.r[j] * this.cross) * 0.88;
        const d2 = dx * dx + dy * dy;
        const si = p.kind[i] as Sp;
        const sj = p.kind[j] as Sp;
        const Zi = SPECIES[si].Z;
        const Zj = SPECIES[sj].Z;
        if (d2 > rr * rr) {
          // Near miss between charged nuclei: a small chance per second of closeness to tunnel through.
          if (Zi > 0 && Zj > 0 && d2 < rr * rr * 2.6 && this.tunnel > 0) {
            const list = reactionsFor(si, sj);
            if (list && rng.chance((this.tunnel * 0.6 * h) / (Zi * Zj))) {
              const r = this.pick(list, rng);
              if (r && rng.chance(r.chance ?? 1)) this.fuse(i, j, r);
            }
          }
          return;
        }
        const d = Math.sqrt(d2) || 1;
        const nx = dx / d;
        const ny = dy / d;
        const list = reactionsFor(si, sj);
        const r = list ? this.pick(list, rng) : null;
        if (r && rng.chance(r.chance ?? 1)) {
          const neutral = Zi === 0 || Zj === 0;
          const partner = Zi === 0 ? sj : si;
          if (!neutral || rng.chance(CAPTURE[partner] ?? 0.4)) {
            this.fuse(i, j, r);
            return;
          }
        }
        // Elastic bounce, mass-weighted.
        const ai = SPECIES[si].A;
        const aj = SPECIES[sj].A;
        const rel = (p.vx[i] - p.vx[j]) * nx + (p.vy[i] - p.vy[j]) * ny;
        if (rel <= 0) return;
        const imp = (2 * rel) / (ai + aj);
        p.vx[i] -= imp * aj * nx;
        p.vy[i] -= imp * aj * ny;
        p.vx[j] += imp * ai * nx;
        p.vy[j] += imp * ai * ny;
        const push = (rr - d) * 0.5;
        p.x[i] = box.wrapX(p.x[i] - nx * push);
        p.y[i] = box.wrapY(p.y[i] - ny * push);
        p.x[j] = box.wrapX(p.x[j] + nx * push);
        p.y[j] = box.wrapY(p.y[j] + ny * push);
        if (rel > 260) this.g.sfx('nucleo.bounce', p.x[i]);
      });
    }
  }

  /** Choose an allowed reaction for this pair (the Reaction Network gates most of them). */
  private pick(list: readonly Reaction[], rng: Game['sim']): Reaction | null {
    const allowed = list.filter((r) => (r.network ?? 0) <= this.network);
    if (!allowed.length) return null;
    return allowed.length === 1 ? allowed[0] : allowed[rng.int(allowed.length)];
  }

  private updateYp(): void {
    const c = this.s.count;
    let mass = 0;
    for (let sp = 0; sp < 8; sp++) mass += Math.max(0, c[sp]) * SPECIES[sp].A;
    this.s.yp = mass > 0 ? (4 * Math.max(0, c[Sp.He4])) / mass : 0;
  }

  // ───────────────────────────────────────── fast neutrons

  private fast: { id: number } | null = null;

  private updateFast(dt: number): void {
    const g = this.g;
    if (g.level('nucleo.fast') <= 0) return;
    const p = this.p;
    if (this.fast) {
      const i = p.find(this.fast.id);
      // One crossing of the view, then it is gone (in a periodic box nothing leaves: it escapes in time).
      if (i < 0 || p.age[i] > this.box.sx / FAST_SPEED) {
        if (i >= 0) p.kill(i);
        this.fast = null;
      }
      return;
    }
    this.s.fastClock -= dt;
    if (this.s.fastClock > 0) return;
    this.s.fastClock = Math.max(18, g.sim.exp(55));
    const fromLeft = g.sim.chance(0.5);
    // Across the field, where it can be seen and caught.
    const F = fieldHalf(this.halfW, this.halfH);
    const y = g.sim.range(-F * 0.7, F * 0.7);
    const i = p.spawn(Sp.N, fromLeft ? -this.box.hx : this.box.hx, y, (fromLeft ? 1 : -1) * FAST_SPEED, g.sim.range(-40, 40), radiusOf(Sp.N), 1);
    if (i < 0) return;
    p.flags[i] |= F_FAST;
    this.fast = { id: p.id[i] };
    g.sfx('nucleo.fast', p.x[i]);
  }

  private catchFast(i: number): void {
    const g = this.g;
    const p = this.p;
    const e = 60 * 2.22 * MEV * this.weight * this.energyMult;
    g.gain(e, p.x[i], p.y[i]);
    p.flags[i] &= ~F_FAST;
    p.vx[i] *= 0.15;
    p.vy[i] *= 0.15;
    p.life[i] = g.sim.exp(NEUTRON_LIFETIME * 2);
    this.s.count[Sp.N] += this.weight;
    this.s.everCaught = true;
    this.fast = null;
    this.fx.spawn(Fx.Flash, p.x[i], p.y[i], 0.45, 40, 2, 2.2, 2.8, 60);
    this.fx.spawn(Fx.Ring, p.x[i], p.y[i], 0.5, 10, 0.8, 0.9, 1.2, 220);
    g.renderer?.shock(p.x[i], p.y[i], 0.4, 0.8, 1);
    g.sfx('nucleo.fast.catch', p.x[i]);
  }

  // ───────────────────────────────────────── steps

  onStep(index: number): void {
    const g = this.g;
    const r = g.renderer;
    for (let sp = 0; sp < 8; sp++) this.s.count[sp] *= 10;
    this.s.decayed *= 10;
    this.syncStepFlags();
    this.bgParams.cool = index / 6;
    this.bgParams.pulse = Math.min(1, this.bgParams.pulse + 0.4);
    r?.camera.breathe(0.05, 1.5);
    const p = this.p;
    for (let i = 0; i < p.n; i++) {
      p.vx[i] += p.x[i] * 0.4;
      p.vy[i] += p.y[i] * 0.4;
    }
    if (index === 1) {
      // Electrons and positrons annihilate: a front of light sweeps out across everything, and the
      // pairs it reaches burn into light behind it (see sweepAnnihilation).
      this.fizz = 0;
      this.bgParams.fizz = 2.5;
      this.sweepT = 0;
      this.fx.spawn(Fx.Ring, 0, 0, SWEEP_T + 0.3, 30, 1.3, 1.45, 2.1, Math.hypot(this.halfW, this.halfH) / SWEEP_T);
      for (let k = 0; k < 10; k++) setTimeout(() => g.sfx('nucleo.annihilate', g.fx.range(-this.halfW, this.halfW)), k * 70);
      g.discover('electron');
      r?.addFlash(0.25);
    }
    if (index === 3) {
      this.bgParams.gamma = 0;
      this.sawBottleneckBreak = true;
      this.hintClock = 0;
      g.sfx('nucleo.bottleneck');
      g.discover('bottleneck');
      r?.shock(0, 0, 0.7, 0.6, 2.2);
      g.toast('The bottleneck breaks. Deuterium survives now, and fusion runs on toward helium.', 'milestone');
    }
  }

  // ───────────────────────────────────────── finale: freeze-out

  finale(): Promise<void> {
    const g = this.g;
    const s = this.s;
    const run = g.state.run;
    this.updateYp();
    const c = s.count;
    const H = Math.max(1, c[Sp.P]);
    run.legacy.yp = s.yp;
    run.legacy.dh = Math.max(0, c[Sp.D]) / H;
    run.legacy.he3h = Math.max(0, c[Sp.He3]) / H;
    run.legacy.lih = Math.max(0, c[Sp.Li7] + c[Sp.Be7]) / H;
    this.finaleT = 0;
    this.releaseHeld();
    return new Promise((resolve) => {
      this.finaleDone = resolve;
    });
  }

  private updateFinale(dt: number): void {
    const g = this.g;
    const p = this.p;
    this.finaleT += dt;
    const t = this.finaleT;
    this.bgParams.freeze = Math.min(1, t / 4);
    if (t > 3 && !this.census) this.buildCensus();
    if (this.census) {
      // Glide each assigned nucleus to its slot in its species' column.
      const base = this.censusBase();
      for (let i = 0; i < p.n; i++) {
        if (p.isDead(i)) continue;
        const slot = this.slotOf.get(p.id[i]);
        if (!slot) continue;
        const tx = slot.x + ((slot.n % CENSUS_ROW) - (CENSUS_ROW - 1) / 2) * CENSUS_GAP;
        const ty = base - CENSUS_GAP * 0.7 - Math.floor(slot.n / CENSUS_ROW) * CENSUS_GAP;
        p.vx[i] = (tx - p.x[i]) * 2.4;
        p.vy[i] = (ty - p.y[i]) * 2.4;
      }
    }
    if (t >= 5.2 && !this.tallied) {
      this.tallied = true;
      g.sfx('nucleo.freeze');
      g.renderer?.addFlash(0.2);
      const yp = g.state.run.legacy.yp ?? 0;
      g.toast(
        `Freeze-out. Helium is ${toText(percent(yp, 3))} of all ordinary matter by mass. Ours: 24.5 %.`,
        'milestone',
      );
    }
    if (t >= 9 && this.finaleDone) {
      const done = this.finaleDone;
      this.finaleDone = null;
      done();
    }
  }

  private slotOf = new Map<number, { x: number; n: number }>();

  /** The census's baseline: in the lower half of the frame's field, which it fits inside. */
  private censusBase(): number {
    return fieldHalf(this.halfW, this.halfH) * 0.55;
  }

  private buildCensus(): void {
    const c = this.s.count;
    const p = this.p;
    let mass = 0;
    for (let sp = 0; sp < 8; sp++) mass += Math.max(0, c[sp]) * SPECIES[sp].A;
    const share = (sps: Sp[]) => sps.reduce<number>((a, sp) => a + Math.max(0, c[sp]) * SPECIES[sp].A, 0) / Math.max(1, mass);
    const cols: Omit<Census, 'x' | 'slots'>[] = [
      { label: 'Hydrogen', share: share([Sp.P, Sp.N]), species: [Sp.P, Sp.N] },
      { label: 'Helium-4', share: share([Sp.He4]), species: [Sp.He4] },
      { label: 'Deuterium', share: share([Sp.D, Sp.T]), species: [Sp.D, Sp.T] },
      { label: 'Helium-3', share: share([Sp.He3]), species: [Sp.He3] },
      { label: 'Lithium', share: share([Sp.Li7, Sp.Be7]), species: [Sp.Li7, Sp.Be7] },
    ];
    // Five columns across the frame's field, with room at its edges.
    const span = fieldHalf(this.halfW, this.halfH) * 1.6;
    const TOTAL = 60;
    this.census = cols.map((cc, k) => ({
      ...cc,
      x: -span / 2 + (k * span) / (cols.length - 1),
      slots: cc.share > 0 ? Math.max(1, Math.round(cc.share * TOTAL)) : 0,
    }));
    // Assign visible nuclei to slots; spawn stand-ins where a column needs more than are on screen.
    const taken = new Set<number>();
    for (const col of this.census) {
      let n = 0;
      for (let i = 0; i < p.n && n < col.slots; i++) {
        if (p.isDead(i) || taken.has(i) || !col.species.includes(p.kind[i] as Sp)) continue;
        taken.add(i);
        this.slotOf.set(p.id[i], { x: col.x, n: n++ });
      }
      while (n < col.slots) {
        const k = this.spawnNucleon(col.species[0], false);
        if (k < 0) break;
        p.life[k] = Infinity;
        taken.add(k);
        this.slotOf.set(p.id[k], { x: col.x, n: n++ });
      }
    }
    for (let i = 0; i < p.n; i++) {
      if (!taken.has(i) && !p.isDead(i)) {
        p.flags[i] |= F_FADE;
        p.b[i] = Math.min(p.b[i] || 1, 1);
      }
    }
  }

  private releaseHeld(): void {
    const i = this.held ? this.p.find(this.held) : -1;
    if (i >= 0) this.p.flags[i] &= ~F_HELD;
    this.held = 0;
  }

  // ───────────────────────────────────────── rendering

  private readonly trails = new Map<number, Trail>();
  private frame = 0;
  private lastMove = -10;
  /** Scratch for the nucleons of one nucleus: x, y, depth, proton per entry. */
  private readonly nb = new Float32Array(7 * 4);
  /** Scratch for a wake's points (x, y pairs, newest first). */
  private readonly trailPts = new Float32Array(TRAIL * 2);

  render(r: Renderer): void {
    const t = this.t;
    const look = this.look;
    const bg = this.bgParams;
    this.frame++;
    const inFinale = this.finaleT >= 0;
    const censusOn = this.census !== null;
    look.begin(r, t);
    look.medium(bg.cool, bg.gamma, bg.pulse, bg.freeze, bg.fizz, bg.sea);
    // The view is a periodic box: what straddles an edge is drawn on both sides of it (its copies across
    // the edges, matter only), so nothing pops as it wraps. The census is the field's own, so its copies
    // are left out while it is taken.
    const ims = this.box.images(this.halfW + 80, this.halfH + 80, this.images);
    const copies = censusOn ? 2 : ims.length;
    for (let n = 0; n < copies; n += 2) {
      look.ghost = n > 0;
      this.renderNuclei(r, ims[n], ims[n + 1], t, censusOn);
    }
    look.ghost = false;
    if (this.frame % 30 === 0) {
      for (const [id, tr] of this.trails) if (this.frame - tr.seen > 2) this.trails.delete(id);
    }

    if (!inFinale) {
      this.drawHover(r);
      this.drawSling(r);
    }
    if (censusOn) this.drawCensus(r);

    this.fx.render(r, look);
    look.end();
  }

  /**
   * One nucleus as a tight cluster of point lights in depth (the ones behind dimmer), its nucleons
   * joined by short filament bonds; helium-4's bonds burn gold, lithium's and beryllium's ice.
   */
  private drawNucleus(sp: Sp, x: number, y: number, a: number, hid: number, alpha: number, hot: number, lift: number, free = 0): void {
    const look = this.look;
    const shape = SHAPE3D[sp];
    const m = shape.length;
    const h = Math.min(1, hot * 0.8);
    if (m === 1) {
      look.nucleon(x, y, shape[0].p, alpha * (0.9 + 0.2 * hid) * lift, 0.4, h, null, free, hid);
      return;
    }
    const nb = this.nb;
    const tumble = sp === Sp.He4 || sp === Sp.Li7 || sp === Sp.Be7;
    // Planar nuclei turn in the screen plane and wobble; the rest tumble about a tilted axis.
    const yaw = tumble ? a * 0.9 : Math.sin(a * 0.7 + hid * 6) * 0.45;
    const tilt = tumble ? 0.55 + 0.6 * hid : 0.35 + 0.25 * Math.sin(a * 0.5 + hid * 9);
    const roll = tumble ? a * 0.25 + hid * 6 : a + hid * 6;
    const cy = Math.cos(yaw);
    const sy = Math.sin(yaw);
    const ct = Math.cos(tilt);
    const st = Math.sin(tilt);
    const cr = Math.cos(roll);
    const sr = Math.sin(roll);
    const nr = NUC_R * lift * (1 + 0.15 * hot);
    const unit = nr * BOND;
    for (let k = 0; k < m; k++) {
      const n = shape[k];
      // Roll in the plane, then yaw about the vertical axis, then tilt toward the viewer.
      const x0 = n.x * cr - n.y * sr;
      const y0 = n.x * sr + n.y * cr;
      const x1 = x0 * cy + n.z * sy;
      const z1 = -x0 * sy + n.z * cy;
      nb[k * 4] = x + x1 * unit;
      nb[k * 4 + 1] = y + (y0 * ct - z1 * st) * unit;
      nb[k * 4 + 2] = Math.max(-1, Math.min(1, (y0 * st + z1 * ct) * 1.6));
      nb[k * 4 + 3] = n.p ? 1 : 0;
    }
    if (sp === Sp.He4) {
      // The closed shell: one knot of light, its four nucleons a faint glimmer inside it.
      look.knot(x, y, nr * 1.3, alpha, h);
      for (let k = 0; k < m; k++) look.nucleon(nb[k * 4], nb[k * 4 + 1], nb[k * 4 + 3] > 0, alpha * 0.22, nb[k * 4 + 2], h, GOLD_LIGHT);
      return;
    }
    const bondTint = sp === Sp.Li7 || sp === Sp.Be7 ? ICE_LIGHT : null;
    const bonds = BONDS[sp];
    for (let q = 0; q < bonds.length; q += 2) {
      const i = bonds[q] * 4;
      const j = bonds[q + 1] * 4;
      const depth = 0.5 + 0.25 * (nb[i + 2] + nb[j + 2]);
      const ca = bondTint ?? (nb[i + 3] ? PROTON_LIGHT : NEUTRON_LIGHT);
      const cb = bondTint ?? (nb[j + 3] ? PROTON_LIGHT : NEUTRON_LIGHT);
      look.bond(nb[i], nb[i + 1], nb[j], nb[j + 1], ca, cb, alpha * (0.45 + 0.55 * depth) * (bondTint ? 1.25 : 0.8) * (1 + h));
    }
    for (let k = 0; k < m; k++) look.nucleon(nb[k * 4], nb[k * 4 + 1], nb[k * 4 + 3] > 0, alpha, nb[k * 4 + 2], h);
  }

  /** A streak of light behind flung (gold) and fast (cool) nuclei, brightest at the head. */
  private drawTrail(i: number, cool: boolean, alpha: number, ox: number, oy: number): void {
    const p = this.p;
    const id = p.id[i];
    let tr = this.trails.get(id);
    if (!tr) {
      tr = { x: new Float32Array(TRAIL), y: new Float32Array(TRAIL), n: 0, seen: 0 };
      this.trails.set(id, tr);
    }
    if (ox === 0 && oy === 0) {
      tr.seen = this.frame;
      tr.x.copyWithin(1, 0, TRAIL - 1);
      tr.y.copyWithin(1, 0, TRAIL - 1);
      tr.x[0] = p.x[i];
      tr.y[0] = p.y[i];
      tr.n = Math.min(TRAIL, tr.n + 1);
    }
    // Back from the head through the wrap, so a wake that crossed an edge stays one stroke (the copy
    // beside it shows the rest).
    const pts = this.trailPts;
    const box = this.box;
    let x = tr.x[0] + ox;
    let y = tr.y[0] + oy;
    for (let s = 0; s < tr.n; s++) {
      if (s > 0) {
        x += box.dx(tr.x[s] - tr.x[s - 1]);
        y += box.dy(tr.y[s] - tr.y[s - 1]);
      }
      pts[s * 2] = x;
      pts[s * 2 + 1] = y;
    }
    const k = (cool ? 1 : Math.min(1, p.b[i])) * alpha;
    this.look.wake(pts, tr.n, cool ? NEUTRON_LIGHT : GOLD_LIGHT, k);
  }

  /** The nucleus a click would grab (same rule as the pointer), ringed while the mouse is active. */
  private drawHover(r: Renderer): void {
    if (this.held || this.t - this.lastMove > 2.5) return;
    const i = this.pickAt(this.pX, this.pY);
    if (i < 0) return;
    const p = this.p;
    const fadeOut = Math.min(1, (2.5 - (this.t - this.lastMove)) / 0.5);
    const k = (0.55 + 0.15 * Math.sin(this.t * 5)) * fadeOut;
    // On the copy under the pointer.
    const x = this.pX + this.box.dx(p.x[i] - this.pX);
    const y = this.pY + this.box.dy(p.y[i] - this.pY);
    r.over.push(x, y, p.r[i] + 14, 1.0 * k, 0.85 * k, 0.6 * k, 1, Shape.Shock, 0.045);
  }

  /** Nearest grabbable nucleus within reach of a point (the pointer's grab rule). */
  private pickAt(x: number, y: number): number {
    const p = this.p;
    let best = -1;
    let bestD = 52 * 52;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i) || p.flags[i] & (F_FADE | F_FAST)) continue;
      const d = this.box.dx(p.x[i] - x) ** 2 + this.box.dy(p.y[i] - y) ** 2;
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  /** The slingshot: elastic band, a power ring with the barrier marked, marching aim dots, a target. */
  private drawSling(r: Renderer): void {
    const p = this.p;
    const hi = this.held ? p.find(this.held) : -1;
    if (hi < 0) return;
    const vx = (this.grabX - this.pX) * 3.2;
    const vy = (this.grabY - this.pY) * 3.2;
    const raw = Math.hypot(vx, vy);
    const max = FLING_MAX * this.fling;
    const speed = Math.min(max, raw);
    const need = 200 * this.barrier;
    const ok = speed >= need;
    const x = this.grabX;
    const y = this.grabY;
    const t = this.t;

    // Band back to the cursor, with a grip dot.
    r.lines.push(x, y, this.pX, this.pY, 3.2, 1.2, LineStyle.Glow, 0.7, 0.6, 0.48, 0.45, 0.5, 0.42, 0.34, 0.25);
    r.glow.push(this.pX, this.pY, 6, 0.8, 0.7, 0.55, 1, Shape.Glow);

    // Power ring: fills clockwise from the top; gold once past the barrier tick.
    const R = p.r[hi] + 26;
    const SEG = 48;
    const filled = Math.round((speed / max) * SEG);
    const gap = 0.012;
    for (let k = 0; k < SEG; k++) {
      const a0 = -Math.PI / 2 + (k / SEG) * Math.PI * 2 + gap;
      const a1 = -Math.PI / 2 + ((k + 1) / SEG) * Math.PI * 2 - gap;
      const on = k < filled;
      const cr = on ? (ok ? 2.0 : 0.9) : 0.55;
      const cg = on ? (ok ? 1.5 : 0.72) : 0.48;
      const cb = on ? (ok ? 0.8 : 0.55) : 0.42;
      r.lines.push(x + Math.cos(a0) * R, y + Math.sin(a0) * R, x + Math.cos(a1) * R, y + Math.sin(a1) * R, 2.4, 2.4, LineStyle.Crisp, cr, cg, cb, on ? 0.95 : 0.16);
    }
    const ab = -Math.PI / 2 + Math.min(1, need / max) * Math.PI * 2;
    const ca = Math.cos(ab);
    const sa = Math.sin(ab);
    r.lines.push(x + ca * (R - 6), y + sa * (R - 6), x + ca * (R + 6), y + sa * (R + 6), 2, 2, LineStyle.Crisp, 1.4, 1.25, 1.0, 0.9);

    if (speed <= 1) return;
    const ux = vx / raw;
    const uy = vy / raw;
    const len = speed * 0.55;

    // Target: the first nucleus whose body crosses the aim line.
    let tj = -1;
    let ts = len * 1.6;
    for (let j = 0; j < p.n; j++) {
      if (j === hi || p.isDead(j) || p.flags[j] & F_FADE) continue;
      const dx = p.x[j] - x;
      const dy = p.y[j] - y;
      const s = dx * ux + dy * uy;
      if (s <= 0 || s >= ts) continue;
      if (Math.abs(dx * uy - dy * ux) < p.r[j] + p.r[hi] * 0.6) {
        ts = s;
        tj = j;
      }
    }
    const end = tj >= 0 ? Math.min(len, ts - p.r[tj] - 10) : len;

    // Marching dots along the predicted path.
    const STEP = 20;
    const off = (t * 70) % STEP;
    for (let s = R + off; s < end; s += STEP) {
      const f = 1 - s / (len + 1);
      const k = (ok ? 1.0 : 0.38) * (0.35 + 0.65 * f);
      r.glow.push(x + ux * s, y + uy * s, 3.2 + 1.6 * f, (ok ? 1.9 : 0.9) * k, (ok ? 1.4 : 0.8) * k, (ok ? 0.75 : 0.65) * k, 1, Shape.Glow);
    }
    if (tj >= 0) {
      const pulse = 0.5 + 0.5 * Math.sin(t * 8);
      const k = ok ? 1.1 + 0.3 * pulse : 0.45;
      r.over.push(p.x[tj], p.y[tj], p.r[tj] + 16, (ok ? 1.6 : 0.8) * k, (ok ? 1.2 : 0.75) * k, (ok ? 0.65 : 0.7) * k, 1, Shape.Shock, 0.05);
    }
  }

  /**
   * The nuclei, drawn shifted by (ox, oy): the field itself or one of the copies its periodic box shows
   * around it (a copy's nuclei only where the view can show them).
   */
  private renderNuclei(r: Renderer, ox: number, oy: number, t: number, censusOn: boolean): void {
    const p = this.p;
    const look = this.look;
    const mx = this.halfW + 80;
    const my = this.halfH + 80;
    for (let i = 0; i < p.n; i++) {
      if (p.isDead(i)) continue;
      const x = p.x[i] + ox;
      const y = p.y[i] + oy;
      if (Math.abs(x) > mx || Math.abs(y) > my) continue;
      const sp = p.kind[i] as Sp;
      const fade = p.flags[i] & F_FADE ? Math.max(0, p.b[i]) : 1;
      const appear = Math.min(1, p.age[i] * 4);
      const alpha = fade * appear;
      if (alpha <= 0.003) continue;
      const flung = p.flags[i] & F_FLUNG;
      const fast = p.flags[i] & F_FAST;
      const held = p.flags[i] & F_HELD;
      const hid = idHash(p.id[i]);
      // Newborn nuclei burn white-hot and cool over half a second.
      const hot = p.age[i] < 0.5 ? (1 - p.age[i] / 0.5) ** 2 : 0;

      if (flung || fast) this.drawTrail(i, fast !== 0, alpha, ox, oy);

      // Each nucleus lights the medium around it in its species' colour, helium-4 gold and strongest.
      const key = p.id[i] + 1;
      if (sp === Sp.He4) look.light(x, y, 120, GOLD_LIGHT, (censusOn ? 0.12 : 0.3) * alpha, key);
      else if (sp === Sp.Li7 || sp === Sp.Be7) look.light(x, y, 110, ICE_LIGHT, 0.26 * alpha, key);
      else if (sp === Sp.D || sp === Sp.T || sp === Sp.He3) look.light(x, y, 70, PROTON_LIGHT, 0.1 * alpha, key);
      if (hot > 0) look.light(x, y, 70, HOT, 0.45 * hot * alpha);
      if (flung) look.light(x, y, 90, GOLD_LIGHT, Math.min(1, p.b[i]) * 0.35 * alpha);

      // A free neutron's instability: its light flickers, faster and harder as its time runs out.
      let shiver = 0;
      let flicker = 1;
      if (sp === Sp.N && !fast) {
        const left = p.life[i];
        const urgency = Number.isFinite(left) ? Math.max(0, Math.min(1, 1 - left / 12)) : 0;
        const fl = 0.5 + 0.5 * Math.sin(t * (5 + 22 * urgency) + hid * 40);
        flicker = 0.85 + 0.15 * fl + urgency * (1.4 * fl - 0.5);
        shiver = Math.sin(t * 41 + p.id[i]) * (0.5 + 1.6 * urgency);
      }

      // A nucleus sinking out of the slice shrinks as it fades, falling back into the sea.
      const sink = p.flags[i] & F_FADE ? 0.55 + 0.45 * fade : 1;
      // A free nucleon in play breathes, to read as something to grab (not one sinking into the sea).
      const free = sp === Sp.P && !(p.flags[i] & (F_FADE | F_FAST)) ? 1 : 0;
      this.drawNucleus(sp, x + shiver, y, p.a[i], hid, alpha * flicker, hot, held ? 1.1 : sink, free);

      const vr = p.r[i];
      if (fast) {
        const pulse = 0.5 + 0.5 * Math.sin(t * 9);
        look.nucleon(x, y, false, 1.4);
        look.light(x, y, 130, NEUTRON_LIGHT, 0.5);
        // The catch area, drawn where the click actually lands.
        r.over.push(x, y, 50 + 4 * pulse, 0.5 + 0.3 * pulse, 0.6 + 0.3 * pulse, 0.9 + 0.3 * pulse, 1, Shape.Shock, 0.035);
      }
      if (held) r.over.push(x, y, vr + 16, 1.2, 1.0, 0.7, 0.9, Shape.Shock, 0.05);
    }
  }

  /** Freeze-out census: a soft light column and a baseline under each species. */
  private drawCensus(r: Renderer): void {
    const census = this.census;
    if (!census) return;
    const o = Math.max(0, Math.min(1, (this.finaleT - 3.2) / 1.6));
    if (o <= 0) return;
    const base = this.censusBase();
    const half = (CENSUS_ROW * CENSUS_GAP) / 2 + 8;
    for (const col of census) {
      const rows = Math.ceil(col.slots / CENSUS_ROW);
      const he = col.species[0] === Sp.He4;
      const c = he ? GOLD : ([1.0, 0.8, 0.62] as RGB);
      r.lines.push(col.x - half, base, col.x + half, base, 1.4, 1.4, LineStyle.Crisp, c[0] * 0.8, c[1] * 0.8, c[2] * 0.8, 0.45 * o);
      if (rows > 0) {
        // The column lights the medium behind it, strongest for helium.
        const k = (he ? 0.5 : 0.2) * o;
        const h = rows * CENSUS_GAP + CENSUS_GAP;
        this.look.light(col.x, base - h / 2, Math.max(110, h * 0.8), tint(c, k));
      }
    }
  }

  // ───────────────────────────────────────── input

  pointer(e: PointerInfo): void {
    if (!e.primary) return;
    const p = this.p;
    const box = this.box;
    // Where the pointer is on screen (the field or one of its copies: the same space).
    this.pX = e.x;
    this.pY = e.y;
    this.lastMove = this.t;
    if (e.type === 'down') {
      this.idle = 0;
      if (this.finaleT >= 0) return;
      // Fast neutron first: it's the thing that's about to leave.
      if (this.fast) {
        const fi = p.find(this.fast.id);
        if (fi >= 0 && Math.hypot(box.dx(p.x[fi] - e.x), box.dy(p.y[fi] - e.y)) < 55) {
          this.catchFast(fi);
          return;
        }
      }
      const best = this.pickAt(e.x, e.y);
      if (best >= 0) {
        this.held = p.id[best];
        p.flags[best] |= F_HELD;
        // The sling pulls from the copy that was pressed, where the pointer is.
        this.grabX = e.x + box.dx(p.x[best] - e.x);
        this.grabY = e.y + box.dy(p.y[best] - e.y);
        this.g.sfx('nucleo.grab', p.x[best]);
      }
    } else if (e.type === 'up' || e.type === 'cancel') {
      const i = this.held ? p.find(this.held) : -1;
      this.held = 0;
      if (i < 0) return;
      p.flags[i] &= ~F_HELD;
      const vx = (this.grabX - e.x) * 3.2;
      const vy = (this.grabY - e.y) * 3.2;
      const len = Math.hypot(vx, vy);
      if (len < 25) return;
      const k = Math.min(1, (FLING_MAX * this.fling) / len);
      p.vx[i] = vx * k;
      p.vy[i] = vy * k;
      p.flags[i] |= F_FLUNG;
      p.b[i] = 1.4;
      this.s.everFlung = true;
      this.g.sfx('nucleo.fling', p.x[i], (len * k) / 400);
    }
  }

  // ───────────────────────────────────────── HUD

  stocks(): StockView[] {
    const s = this.s;
    return [
      {
        id: 'neutrons',
        label: 'Free neutrons',
        value: Math.max(0, s.count[Sp.N]),
        format: 'count',
        hint: 'Free neutrons decay in about fifteen minutes. Every one locked into helium is saved.',
      },
      {
        id: 'he4',
        label: 'Helium-4',
        value: Math.max(0, s.count[Sp.He4]),
        format: 'count',
        rate: this.heMeter.rate,
        hint: 'Two protons and two neutrons: the safest place a neutron can be.',
      },
      {
        id: 'yp',
        label: 'Helium by mass',
        value: s.yp,
        format: 'percent',
        ours: 0.245,
        hint: 'Yₚ, the helium mass fraction: the more neutrons locked into helium before they decay, the higher it climbs.',
      },
    ];
  }

  dotScale(): { value: number; unit: string } | null {
    return { value: this.weight, unit: 'nuclei' };
  }

  labels(): WorldLabel[] {
    if (!this.census || this.finaleT < 3.4) return [];
    const o = Math.min(1, (this.finaleT - 3.4) / 1.2);
    return this.census.map((cc) => ({
      id: 'census-' + cc.label,
      x: cc.x,
      y: this.censusBase() + 22,
      text: `${cc.label} ${cc.share <= 0 ? 'none' : cc.share < 1e-4 ? 'trace' : toText(percent(cc.share, 3))}`,
      tone: 'value' as const,
      opacity: o,
    }));
  }

  offline(seconds: number): OfflineReport {
    const s = this.s;
    const he = this.heMeter.rate * seconds;
    const inflow = this.inflowMeter.rate * seconds;
    // Arrivals split as they would have; the neutrons that arrived either became helium or decayed.
    const share = NEUTRON_SHARE[this.step];
    const neutrons = inflow * share;
    const locked = Math.min(neutrons / 2, he);
    s.count[Sp.He4] += locked;
    s.count[Sp.P] += inflow * (1 - share) - locked * 2 + (neutrons - locked * 2);
    s.decayed += Math.max(0, neutrons - locked * 2);
    this.updateYp();
    return { lines: [{ label: 'Helium-4', value: toText(count(locked)) }] };
  }

  accent(): RGB {
    const c = this.bgParams.cool;
    return [1.0, 0.78 - 0.18 * c, 0.5 - 0.2 * c];
  }

  hint(): string | null {
    if (this.finaleT >= 0) return null;
    if (!this.s.everFlung && this.idle > 2.5) return 'Grab a nucleus, pull back and let go.';
    if (this.s.everFlung && !this.s.everFused && this.idle > 6) return 'Faster. Slow nuclei repel each other before they touch.';
    if (this.fast && !this.s.everCaught) return 'A fast neutron. Click it before it gets away.';
    if (this.sawBottleneckBreak && this.step === 3 && this.hintClock < 9 && this.network > 0) return 'Fling deuterium into deuterium.';
    if (this.step < 3 && this.network > 0 && this.s.everFused && this.hintClock > 20 && this.hintClock < 32)
      return 'Too hot for now: light breaks deuterium apart almost as soon as it forms. It holds after three minutes.';
    return null;
  }
}
