/**
 * The Dark Ages → Cosmic Dawn backdrop: what lies behind the gas.
 *
 * At first the sky itself glows: the afterglow, mottled with this universe's own microwave pattern (the
 * map the Afterglow recorded, whose peaks became the dark-matter halos), orange at 3,000 K, then deep
 * red, then nothing as it redshifts out of the visible. Then black. In the finale, once the bubbles have
 * merged and the gas is clear, the cosmic web the halos sit on glows faintly (ionized gas along the dark
 * matter, shining in Lyman alpha), brightest at its nodes, and the first galaxies show far behind.
 *
 * Two CPU-built data textures keep the per-pixel cost flat: `uCmb` (the microwave pattern, 0–1, over
 * the play area) and `uDm` (dark-matter density: halos plus the filaments between them).
 */
import type { BackgroundDef, BgTexture } from '../../render/renderer';

export interface DawnBgParams {
  /** Remaining afterglow, 1 at the start of the era → 0. */
  glow: number;
  /** Visibility of the gas and the dark-matter web (21-cm upgrade raises it). */
  web: number;
  pulse: number;
  /** Finale progress 0 → 1: the last neutral gas clears. */
  finale: number;
  /** World rectangle the field textures cover: minX, minY, maxX, maxY. */
  rect: Float32Array;
}

export interface DawnBgFields {
  cmb: Omit<BgTexture, 'name'>;
  dm: Omit<BgTexture, 'name'>;
}

/** `play` holds the play area's half extents (the microwave pattern spans it). */
export function dawnBackground(params: DawnBgParams, fields: DawnBgFields, play: Float32Array): BackgroundDef {
  return {
    id: 'dawn-v2',
    fragment: /* glsl */ `
uniform float uGlow;
uniform float uWeb;
uniform float uPulse;
uniform float uFinale;
uniform vec4 uRect;
uniform vec2 uPlay;
uniform sampler2D uCmb;
uniform sampler2D uDm;

/**
 * The afterglow's colour times brightness at a point of the pattern m (−0.5 coldest … 0.5 hottest):
 * at first as the Afterglow's own map left it (crimson in the cold spots, gold toward white in the hot
 * ones), then reddening and dimming as it redshifts out of the visible: orange, deep red, then into the
 * infrared.
 */
vec3 afterglow(float g, float m) {
  float hot = clamp(0.5 + 1.6 * m - 0.6 * (1.0 - g), 0.0, 1.0);
  vec3 c = mix(vec3(0.55, 0.04, 0.05), vec3(1.0, 0.34, 0.1), smoothstep(0.15, 0.6, hot));
  c = mix(c, vec3(1.0, 0.78, 0.5), smoothstep(0.6, 1.0, hot) * g * g);
  return c * (g * g * 0.9 + g * 0.1);
}

/** Cubic B-spline weights for a texel fraction. */
vec4 bspline(float v) {
  vec4 n = vec4(1.0, 2.0, 3.0, 4.0) - v;
  vec4 c = n * n * n;
  float x = c.x;
  float y = c.y - 4.0 * c.x;
  float z = c.z - 4.0 * c.y + 6.0 * c.x;
  return vec4(x, y, z, 6.0 - x - y - z) / 6.0;
}

/**
 * The pattern read smoothly: its texture is coarse (48 by 27 over the whole play), and plain bilinear
 * magnification of so few texels leaves diamonds and squares, so it is read as a cubic B-spline (four
 * bilinear taps), which gives round soft blobs.
 */
float smoothCmb(vec2 uv) {
  vec2 size = vec2(textureSize(uCmb, 0));
  vec2 p = uv * size - 0.5;
  vec2 f = fract(p);
  p -= f;
  vec4 xc = bspline(f.x);
  vec4 yc = bspline(f.y);
  vec4 c = p.xxyy + vec2(-0.5, 1.5).xyxy;
  vec4 s = vec4(xc.xz + xc.yw, yc.xz + yc.yw);
  vec4 o = (c + vec4(xc.yw, yc.yw) / s) / size.xxyy;
  float sx = s.x / (s.x + s.y);
  float sy = s.z / (s.z + s.w);
  return mix(mix(texture(uCmb, o.yw).r, texture(uCmb, o.xw).r, sx), mix(texture(uCmb, o.yz).r, texture(uCmb, o.xz).r, sx), sy);
}

void main() {
  vec2 world = uView.xy + (vUv * 2.0 - 1.0) * uView.zw * vec2(1.0, -1.0);
  float t = uTime;
  vec3 col = vec3(0.00032, 0.00032, 0.00055);

  // The afterglow: the pattern this universe was born with, smoothly mottled, a finer grain on top.
  vec2 cuv = world / (2.0 * uPlay) + 0.5;
  float m = smoothCmb(clamp(cuv, 0.0, 1.0)) - 0.5;
  float grain = fbm(vec3(world / 260.0, t * 0.01), 3);
  // Exponential in the pattern, so the sky glows where its hot spots are and falls nearly black in
  // its troughs (a range of about ten): a luminous sky the gas can stand against, not a flat wash.
  float mottle = exp(2.4 * m + 0.35 * grain - 0.3);
  col += afterglow(uGlow, m) * 0.12 * mottle * (1.0 + 0.6 * uPulse);

  // The finale: the web glows where the halos lie and along the threads between them.
  vec2 fuv = clamp((world - uRect.xy) / (uRect.zw - uRect.xy), 0.0, 1.0);
  float dm = texture(uDm, fuv).r;
  float web = smoothstep(0.08, 1.4, dm) * (0.6 + 0.4 * fbm(vec3(world / 180.0, t * 0.02), 2));
  col += vec3(0.32, 0.36, 1.0) * web * 0.011 * uFinale;

  // Far behind, the first galaxies: small warm smudges that show once the gas is clear.
  vec2 cell = floor(world / 90.0);
  vec2 h = hash22(cell);
  if (h.x > 0.86) {
    vec2 c = (cell + 0.2 + 0.6 * hash22(cell + 7.1)) * 90.0;
    vec2 d = world - c;
    float a = h.y * 6.2832;
    vec2 e = vec2(dot(d, vec2(cos(a), sin(a))), dot(d, vec2(-sin(a), cos(a)))) / vec2(5.0, 2.4);
    float g = exp(-dot(e, e)) * (0.4 + 0.6 * hash12(cell + 3.3));
    col += vec3(1.0, 0.8, 0.62) * g * 0.05 * uFinale * uFinale;
  }
  outColor = vec4(col, 1.0);
}`,
    uniforms: (p) => {
      p.f1('uGlow', params.glow).f1('uWeb', params.web).f1('uPulse', params.pulse).f1('uFinale', params.finale);
      const r = params.rect;
      p.f4('uRect', r[0], r[1], r[2], r[3]);
      p.f2('uPlay', Math.max(1, play[0]), Math.max(1, play[1]));
    },
    textures: [
      { name: 'uCmb', ...fields.cmb },
      { name: 'uDm', ...fields.dm },
    ],
  };
}
