/**
 * The Galaxies sound wide and deep: a slow, open Lydian pad over a low drone, as if heard from very
 * far away. A fling is a soft rush of air; a flyby a swell; a merger lands with weight and a chord;
 * a quasar flares as a bright, hard-edged tone; two black holes chirp upward before they meet; a
 * galaxy slipping over the horizon fades on a falling note.
 */
import type { EraAudio } from '../../audio/director';
import { bell, noise, pluck, swell, thump } from '../../audio/patches';
import { SCALES, mtof, note, type Key } from '../../audio/scales';

const KEY: Key = { root: 39, scale: SCALES.lydian };

export const GALAXIES_AUDIO: EraAudio = {
  key: KEY,
  bed: {
    id: 'galaxies',
    chords: [
      [39, 51, 58, 62, 69],
      [37, 49, 56, 63, 68],
      [42, 49, 58, 61, 66],
      [34, 46, 53, 58, 65],
    ],
    chordSeconds: 32,
    pad: { gain: 0.05, type: 'sine', cutoff: 900, detune: 9, lfo: 0.018 },
    drone: { note: 27, gain: 0.03 },
    air: { freq: 600, q: 0.4, gain: 0.006, drift: 0.01 },
    shimmer: { gain: 0.006, rate: 0.1 },
    level: 1.26,
  },
  cues: {
    'galaxies.grab': (a, p, c) => {
      const g = a.admit('galaxies.grab', 0.2);
      if (g) pluck(a, mtof(note(c.key, 9)), { gain: 0.045 * g, decay: 0.5, tone: 3, pan: c.pan(p.x) });
    },
    'galaxies.fling': (a, p, c) => {
      const g = a.admit('galaxies.fling', 0.2);
      if (g) noise(a, { dur: 1.2, freq: 300, to: 1400, q: 0.7, gain: 0.04 * g * (p.intensity ?? 1), attack: 0.08, pan: c.pan(p.x) });
    },
    'galaxies.flyby': (a, _p, c) => {
      const g = a.admit('galaxies.flyby', 1.5);
      if (g) swell(a, [2, 4, 6].map((d) => mtof(note(c.key, d + 7))), { attack: 1.4, hold: 0.8, release: 4, gain: 0.07 * g, cutoff: 1600 });
    },
    'galaxies.merge': (a, p, c) => {
      if (!a.admit('galaxies.merge', 0.6)) return;
      const t = a.now;
      thump(a, 31, { time: t, gain: 0.32, dur: 2.6, pan: c.pan(p.x) });
      swell(a, [39, 46, 51, 55, 58, 62].map(mtof), { time: t + 0.1, attack: 1.2, hold: 1.5, release: 6, gain: 0.14, cutoff: 2200 });
    },
    'galaxies.starburst': (a, p, c) => {
      const g = a.admit('galaxies.starburst', 0.6);
      if (!g) return;
      const t = a.now;
      [0, 2, 4, 7, 9].forEach((d, i) => bell(a, mtof(note(c.key, 14 + d)), { time: t + i * 0.07, gain: 0.03 * g, decay: 1.8, ratio: 2, bright: 0.6, pan: c.pan(p.x) }));
    },
    'galaxies.quasar': (a, p, c) => {
      if (!a.admit('galaxies.quasar', 0.8)) return;
      const t = a.now;
      noise(a, { time: t, dur: 2.5, freq: 7000, to: 900, q: 1.4, gain: 0.08, attack: 0.01, pan: c.pan(p.x) });
      bell(a, mtof(note(c.key, 18)), { time: t + 0.05, gain: 0.07, decay: 5, ratio: 3, bright: 1.3, pan: c.pan(p.x) });
      swell(a, [51, 58, 63, 70].map(mtof), { time: t, attack: 0.2, hold: 2, release: 5, gain: 0.08, cutoff: 5000 });
    },
    'galaxies.chirp': (a, p, c) => {
      const g = a.admit('galaxies.chirp', 2);
      if (g) noise(a, { dur: 2.6, freq: 60, to: 900, q: 10, gain: 0.05 * g, attack: 2.1, pan: c.pan(p.x) });
    },
    'galaxies.bhmerge': (a, p, c) => {
      if (!a.admit('galaxies.bhmerge', 0.6)) return;
      thump(a, 29, { time: a.now, gain: 0.35, dur: 3, pan: c.pan(p.x) });
    },
    'galaxies.ring': (a, p, c) => {
      if (!a.admit('galaxies.ring', 0.4)) return;
      const t = a.now;
      [0, 4, 7, 11].forEach((d, i) => bell(a, mtof(note(c.key, 7 + d)), { time: t + i * 0.12, gain: 0.05, decay: 3, ratio: 2, bright: 0.4, pan: c.pan(p.x) }));
    },
    'galaxies.capture': (a, p, c) => {
      if (!a.admit('galaxies.capture', 0.2)) return;
      const t = a.now;
      pluck(a, mtof(note(c.key, 7)), { time: t, gain: 0.05, decay: 1, tone: 4, pan: c.pan(p.x) });
      pluck(a, mtof(note(c.key, 11)), { time: t + 0.1, gain: 0.05, decay: 1.2, tone: 4, pan: c.pan(p.x) });
    },
    'galaxies.lost': (a, p, c) => {
      if (!a.admit('galaxies.lost', 0.4)) return;
      const t = a.now;
      bell(a, mtof(note(c.key, 9)), { time: t, gain: 0.05, decay: 3.5, ratio: 2, bright: 0.2, pan: c.pan(p.x) });
      bell(a, mtof(note(c.key, 5)), { time: t + 0.5, gain: 0.04, decay: 4, ratio: 2, bright: 0.15, pan: c.pan(p.x) });
    },
    'galaxies.milestone': (a, _p, c) => {
      const t = a.now;
      swell(a, [39, 46, 51, 58, 62].map(mtof), { bus: 'music', time: t, attack: 2, hold: 1.2, release: 6, gain: 0.12, cutoff: 1500 });
      bell(a, mtof(note(c.key, 11)), { bus: 'music', time: t + 0.7, gain: 0.04, decay: 4, ratio: 2, bright: 0.3 });
    },
    'galaxies.complete': (a) => {
      const t = a.now;
      thump(a, 27, { time: t, gain: 0.25, dur: 3 });
      swell(a, [39, 46, 51, 55, 58, 62, 69].map(mtof), { time: t + 0.5, attack: 4, hold: 3, release: 10, gain: 0.18, cutoff: 2400 });
    },
  },
};
