/**
 * Fixed-timestep loop: the simulation always advances in 1/60 s steps (deterministic, frame-rate
 * independent); rendering happens once per animation frame with the leftover fraction as `alpha`.
 * Long gaps (tab hidden, debugger) are not replayed here; offline credit handles them.
 */
export const STEP = 1 / 60;
const MAX_STEPS_PER_FRAME = 6;
const MAX_FRAME_DT = 0.25;

export class Loop {
  timeScale = 1;
  running = false;
  private acc = 0;
  private last = 0;
  private raf = 0;

  constructor(
    private readonly update: (dt: number) => void,
    private readonly render: (alpha: number, frameDt: number) => void,
  ) {}

  start(): void {
    if (this.running) return;
    this.running = true;
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.frame);
  }

  stop(): void {
    this.running = false;
    cancelAnimationFrame(this.raf);
  }

  /** Drop any accumulated time (after offline credit has been applied for a gap). */
  resync(): void {
    this.acc = 0;
    this.last = performance.now();
  }

  private frame = (now: number): void => {
    if (!this.running) return;
    const frameDt = Math.min(MAX_FRAME_DT, Math.max(0, (now - this.last) / 1000));
    this.last = now;
    this.acc += frameDt * this.timeScale;
    let steps = 0;
    while (this.acc >= STEP && steps < MAX_STEPS_PER_FRAME * Math.max(1, Math.ceil(this.timeScale))) {
      this.update(STEP);
      this.acc -= STEP;
      steps++;
    }
    if (this.acc > STEP * MAX_STEPS_PER_FRAME) this.acc = 0;
    this.render(this.acc / STEP, frameDt);
    this.raf = requestAnimationFrame(this.frame);
  };
}
