<!--
  The Codex: each era's iconic chart, filled in by discovery. Undiscovered tiles keep their place
  in the chart so the shape of what's missing is visible.
-->
<script lang="ts">
  import Panel from './Panel.svelte';
  import PeriodicTable from './PeriodicTable.svelte';
  import { CHART_TITLES, type ChartId, type CodexEntry } from '../../core/codex';
  import { game, track, ui } from '../store.svelte';

  const g = game();

  const charts = $derived.by(() => {
    track();
    const all = g.allCodex();
    const byChart = new Map<ChartId, CodexEntry[]>();
    for (const e of all) {
      if (!byChart.has(e.chart)) byChart.set(e.chart, []);
      byChart.get(e.chart)!.push(e);
    }
    const out: { id: ChartId; title: string; entries: CodexEntry[]; found: number }[] = [];
    for (const [id, entries] of byChart) {
      const found = entries.filter((e) => g.isDiscovered(e.id)).length;
      if (found > 0) out.push({ id, title: CHART_TITLES[id], entries, found });
    }
    return out;
  });

  const focusEntry = ui.codexFocus ? g.codexEntry(ui.codexFocus) : undefined;
  let tab = $state<ChartId | null>(focusEntry?.chart ?? null);
  let selected = $state<string | null>(ui.codexFocus);
  ui.codexFocus = null;

  // A discovery clicked while the Codex is already open jumps to its entry.
  $effect(() => {
    const id = ui.codexFocus;
    if (!id) return;
    ui.codexFocus = null;
    const e = g.codexEntry(id);
    if (!e) return;
    tab = e.chart;
    selected = id;
  });

  const current = $derived(charts.find((c) => c.id === tab) ?? charts[0]);
  const entry = $derived(selected ? g.codexEntry(selected) : undefined);

  $effect(() => {
    if (!current) return;
    for (const e of current.entries) if (g.isDiscovered(e.id)) g.state.codex.read[e.id] = true;
  });

  /** "ν_μ" → base "ν" + subscript "μ". */
  function sym(text: string): { base: string; sub: string } {
    const i = text.indexOf('_');
    return i < 0 ? { base: text, sub: '' } : { base: text.slice(0, i), sub: text.slice(i + 1) };
  }

  const grid = $derived.by(() => {
    if (!current) return null;
    const placed = current.entries.filter((e) => e.layout);
    if (placed.length === 0) return null;
    const cols = Math.max(...placed.map((e) => e.layout!.col)) + 1;
    const rows = Math.max(...placed.map((e) => e.layout!.row)) + 1;
    return { cols, rows, placed };
  });
</script>

<Panel title="Codex" wide>
  {#if charts.length === 0}
    <p class="empty">Nothing discovered yet.</p>
  {:else}
    <nav class="tabs" aria-label="Charts">
      {#each charts as c (c.id)}
        <button class:on={current?.id === c.id} aria-pressed={current?.id === c.id} onclick={() => ((tab = c.id), (selected = null))}>
          {c.title}<span class="count">{c.found}/{c.entries.length}</span>
        </button>
      {/each}
    </nav>

    {#if current}
      {#if current.id === 'elements'}
        <PeriodicTable {g} focus={selected?.startsWith('el-') ? Number(selected.slice(3)) : null} />
      {:else if grid}
        <div class="grid" style="--cols:{grid.cols}; --rows:{grid.rows}">
          {#each grid.placed as e (e.id)}
            {@const found = g.isDiscovered(e.id)}
            <button
              class="tile {e.layout?.group ?? ''}"
              class:found
              class:sel={selected === e.id}
              style="grid-column:{e.layout!.col + 1}; grid-row:{e.layout!.row + 1}"
              onclick={() => found && (selected = e.id)}
              disabled={!found}
              aria-pressed={found ? selected === e.id : undefined}
              aria-label={found ? e.title : 'Undiscovered'}
            >
              {#if found}
                {@const sy = sym(e.symbol ?? e.title.slice(0, 2))}
                <span class="sym">{sy.base}{#if sy.sub}<sub>{sy.sub}</sub>{/if}</span>
              {:else}
                <span class="sym">?</span>
              {/if}
              <span class="nm">{found ? e.title : ''}</span>
            </button>
          {/each}
        </div>
      {:else}
        <ul class="list">
          {#each current.entries as e (e.id)}
            {#if g.isDiscovered(e.id)}
              <li><button class:sel={selected === e.id} aria-pressed={selected === e.id} onclick={() => (selected = e.id)}>{e.title}</button></li>
            {/if}
          {/each}
        </ul>
      {/if}

      {#if current.id === 'elements'}
        <!-- The periodic table shows its own detail. -->
      {:else if entry && g.isDiscovered(entry.id)}
        <article class="entry">
          <h3>
            {entry.title}{#if entry.symbol}{@const sy = sym(entry.symbol)}<span class="esym"
                >{sy.base}{#if sy.sub}<sub>{sy.sub}</sub>{/if}</span
              >{/if}
          </h3>
          <p>{entry.text}</p>
          {#if entry.bonus}<p class="bonus"><span class="label">Bonus</span> {entry.bonus.text}</p>{/if}
        </article>
      {:else}
        <p class="pick">Select a tile to read about it.</p>
      {/if}
    {/if}
  {/if}
</Panel>

