/**
 * Generative ambient beds: each era gets a slowly evolving harmonic field instead of a looping track.
 * Chord tones glide to the nearest tones of the next voicing (smooth voice leading), filters drift on
 * slow LFOs, and an optional noise layer gives the medium its texture (plasma roar, interstellar hiss).
 *
 * The harmony (pad, drone, shimmer) plays on the music bus and the medium's noise on the ambience bus,
 * so the Music and Ambience sliders each control what their names say.
 */
import type { AudioEngine, BusName } from './engine';
import { mtof } from './scales';

export interface BedSpec {
  id: string;
  /** Voicings as MIDI notes; the bed moves through them in order, forever. */
  chords: readonly (readonly number[])[];
  chordSeconds: number;
  /** Pad: detuned oscillators per chord tone. */
  pad: { gain: number; type: OscillatorType; cutoff: number; detune: number; lfo: number };
  /** Optional sub drone on a fixed note. */
  drone?: { note: number; gain: number };
  /** Optional filtered noise: centre frequency, Q, gain, drift rate. */
  air?: { freq: number; q: number; gain: number; drift: number };
  /** Optional high shimmer partials (octave above the top chord tone), with tremolo. */
  shimmer?: { gain: number; rate: number };
  /**
   * Overall level of the whole bed (linear, default 1), set from offline loudness measurements
   * (`npm run audio-qa`) so every era's bed sits at the same perceived level unless meant not to.
   */
  level?: number;
}

interface Voice {
  osc: OscillatorNode[];
}

/**
 * Fixed trim on every bed. Measured offline, the beds sat 3–4 dB too hot against the event cues
 * (−21 LUFS beds under −35 LUFS bells), so the cues read as decoration instead of events.
 */
const BED_TRIM = 0.65;

/** Segments of the piecewise-linear equal-power fade: fine enough that its corners are inaudible. */
const FADE_STEPS = 16;

export class Bed {
  /** Fade stages: one per bus the bed plays on, always moved together. */
  private readonly faders: GainNode[] = [];
  private readonly music: GainNode;
  private readonly ambience: GainNode;
  private voices: Voice[] = [];
  private nodes: AudioNode[] = [];
  private sources: AudioScheduledSourceNode[] = [];
  private running = true;
  private chord = 0;
  private shimmerOsc: OscillatorNode[] = [];

  constructor(
    private readonly a: AudioEngine,
    readonly spec: BedSpec,
  ) {
    this.music = this.output('music');
    this.ambience = this.output('ambience');
    this.build();
  }

  /** A silent fade stage and the bed's trim, into one bus. */
  private output(bus: BusName): GainNode {
    const ctx = this.a.ctx as AudioContext;
    const fader = ctx.createGain();
    fader.gain.value = 0;
    const trim = ctx.createGain();
    trim.gain.value = BED_TRIM * (this.spec.level ?? 1);
    fader.connect(trim).connect(this.a.bus(bus));
    this.faders.push(fader);
    this.nodes.push(fader, trim);
    return fader;
  }

  private build(): void {
    const ctx = this.a.ctx as AudioContext;
    const s = this.spec;
    const t = ctx.currentTime;

    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = s.pad.cutoff;
    lp.Q.value = 0.6;
    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = s.pad.lfo;
    lfoGain.gain.value = s.pad.cutoff * 0.35;
    lfo.connect(lfoGain).connect(lp.frequency);
    lfo.start(t);
    const padGain = ctx.createGain();
    padGain.gain.value = s.pad.gain / Math.sqrt(Math.max(1, s.chords[0].length));
    lp.connect(padGain).connect(this.music);
    this.nodes.push(lp, lfoGain, padGain);
    this.sources.push(lfo);

    for (const n of s.chords[0]) {
      const v: Voice = { osc: [] };
      for (const det of [-s.pad.detune, s.pad.detune]) {
        const osc = ctx.createOscillator();
        osc.type = s.pad.type;
        osc.frequency.value = mtof(n);
        osc.detune.value = det;
        osc.connect(lp);
        osc.start(t);
        v.osc.push(osc);
        this.sources.push(osc);
      }
      this.voices.push(v);
    }

    if (s.drone) {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = mtof(s.drone.note);
      const g = ctx.createGain();
      g.gain.value = s.drone.gain;
      osc.connect(g).connect(this.music);
      osc.start(t);
      this.sources.push(osc);
      this.nodes.push(g);
    }

    if (s.air) {
      const src = ctx.createBufferSource();
      src.buffer = this.a.noise();
      src.loop = true;
      const bp = ctx.createBiquadFilter();
      bp.type = 'bandpass';
      bp.frequency.value = s.air.freq;
      bp.Q.value = s.air.q;
      const drift = ctx.createOscillator();
      const driftGain = ctx.createGain();
      drift.frequency.value = s.air.drift;
      driftGain.gain.value = s.air.freq * 0.4;
      drift.connect(driftGain).connect(bp.frequency);
      const g = ctx.createGain();
      g.gain.value = s.air.gain;
      src.connect(bp).connect(g).connect(this.ambience);
      src.start(t);
      drift.start(t);
      this.sources.push(src, drift);
      this.nodes.push(bp, driftGain, g);
    }

    if (s.shimmer) {
      const g = ctx.createGain();
      g.gain.value = 0;
      const trem = ctx.createOscillator();
      const tremGain = ctx.createGain();
      trem.frequency.value = s.shimmer.rate;
      tremGain.gain.value = s.shimmer.gain;
      trem.connect(tremGain).connect(g.gain);
      g.connect(this.music);
      const top = Math.max(...s.chords[0]);
      for (const k of [12, 19]) {
        const osc = ctx.createOscillator();
        osc.frequency.value = mtof(top + k);
        osc.connect(g);
        osc.start(t);
        this.shimmerOsc.push(osc);
        this.sources.push(osc);
      }
      trem.start(t);
      this.sources.push(trem);
      this.nodes.push(g, tremGain);
    }

    this.scheduleChord();
  }

  private scheduleChord(): void {
    this.a.after(this.spec.chordSeconds, () => {
      if (!this.running) return;
      this.nextChord();
      this.scheduleChord();
    });
  }

  private nextChord(): void {
    const ctx = this.a.ctx;
    if (!ctx) return;
    this.chord = (this.chord + 1) % this.spec.chords.length;
    const target = [...this.spec.chords[this.chord]];
    const t = ctx.currentTime;
    // Voice leading: each voice glides to the closest unused target note.
    const used = new Set<number>();
    for (const v of this.voices) {
      const cur = 69 + 12 * Math.log2(v.osc[0].frequency.value / 440);
      let best = -1;
      let bestD = Infinity;
      target.forEach((n, i) => {
        if (used.has(i)) return;
        const d = Math.abs(n - cur);
        if (d < bestD) {
          bestD = d;
          best = i;
        }
      });
      if (best < 0) continue;
      used.add(best);
      for (const o of v.osc) o.frequency.setTargetAtTime(mtof(target[best]), t, this.spec.chordSeconds * 0.12);
    }
    const top = Math.max(...target);
    this.shimmerOsc.forEach((o, i) => o.frequency.setTargetAtTime(mtof(top + (i ? 19 : 12)), t, 2));
  }

  /**
   * Move every fade stage from where it is now to `level` over `seconds`, on an equal-power curve
   * (rising along a sine, falling along a cosine): two uncorrelated beds crossing in opposite
   * directions keep their summed power, so an era handover has no hole in the middle.
   */
  private fade(level: number, seconds: number): void {
    const ctx = this.a.ctx;
    if (!ctx) return;
    const t = ctx.currentTime;
    for (const f of this.faders) {
      const p = f.gain;
      const from = p.value;
      p.cancelScheduledValues(t);
      p.setValueAtTime(from, t);
      for (let i = 1; i <= FADE_STEPS; i++) {
        const x = i / FADE_STEPS;
        const w = level > from ? Math.sin((x * Math.PI) / 2) : 1 - Math.cos((x * Math.PI) / 2);
        p.linearRampToValueAtTime(from + (level - from) * w, t + x * seconds);
      }
    }
  }

  fadeIn(seconds = 4, level = 1): void {
    this.fade(level, seconds);
  }

  /** Scale the whole bed (0..1) smoothly, e.g. to make room for a big moment. */
  setLevel(level: number, seconds = 1.5): void {
    this.fade(level, seconds);
  }

  stop(seconds = 4): void {
    const ctx = this.a.ctx;
    this.running = false;
    if (!ctx) return;
    this.fade(0, seconds);
    const t = ctx.currentTime;
    for (const s of this.sources) s.stop(t + seconds + 0.1);
    this.a.after(seconds + 0.3, () => {
      for (const n of this.nodes) n.disconnect();
    });
  }
}
