/**
 * How the Afterglow looks (version 2). The simulation says what is where; this draws it.
 *
 * - The medium: an opaque fog glowing by its own heat (background.ts). Sound waves are spherical
 *   pressure fronts through it, hotter and brighter where compressed, interfering where they cross;
 *   it thins and breaks into wisps as electrons are caught, so the eye reaches deeper and deeper.
 *   A storm of crisp specks in depth carries its grain: free electrons jittering fast, blue-white,
 *   that calm into dim atoms as recombination proceeds.
 * - Electrons: fast blue-white sparks with a short streak along their motion.
 * - Nuclei: crisp point lights, protons warm and helium gold. Atoms: the same points, quieter, with
 *   their bound electrons as faint cool clouds and a spark circling inside.
 * - Captures: a flash that lights the fog around it, and the photon it frees as a wave packet that
 *   travels a little farther the thinner the fog. Resonance nodes are blooms of light with fronts
 *   drawing in; dark matter wells are slow violet heartbeats in the fog.
 * - Effects (the era's FxPool, restyled): flashes light the fog, rings are light fronts and pushes
 *   through the specks, sparks are wave packets (or, once the light streams free, long straight
 *   streaks), puffs are glows in the fog.
 */
import type { FxLook } from '../../render/fx';
import { Filaments } from '../../render/filaments';
import type { BackgroundDef, Renderer } from '../../render/renderer';
import type { PostParams } from '../../render/post';
import { Shape } from '../../render/sprites';
import { Storm, type StormKick, type StormLight } from '../../render/storm';
import type { VolumeFront, VolumeLight } from '../../render/volume';
import { Fog, type AfterglowBgParams, type Imprint } from './background';

type RGB = readonly [number, number, number];

/** A free electron's light, a proton's, helium's, and the cool of a bound electron's cloud. */
export const ELECTRON_LIGHT: RGB = [0.62, 0.8, 1.0];
export const PROTON_LIGHT: RGB = [1.0, 0.62, 0.36];
export const HELIUM_LIGHT: RGB = [1.0, 0.78, 0.4];
const BOUND: RGB = [0.55, 0.7, 1.0];
/** Lyman-α and the other recombination photons are ultraviolet: drawn as violet-white light. */
const PHOTON: RGB = [0.78, 0.7, 1.0];
const WELL: RGB = [0.5, 0.3, 1.0];

const SPECK_E: [number, number, number] = [0.72, 0.86, 1.0];
const SPECK_E2: [number, number, number] = [0.9, 0.95, 1.0];
const SPECK_N: [number, number, number] = [1.0, 0.7, 0.45];
const SPECK_ATOM: [number, number, number] = [0.6, 0.66, 0.85];

const BLACK: BackgroundDef = {
  id: 'afterglow-v2',
  fragment: /* glsl */ `
void main() {
  outColor = vec4(0.0005, 0.00045, 0.0006, 1.0);
}`,
};

/** The post settings this look is graded for. */
const POST: Partial<PostParams> = { bloom: 0.24, bloomThreshold: 1.3, glare: 0.3, glareThreshold: 3, saturation: 1.18, punch: 1.2, vignette: 0.42, grain: 0.012 };

const lum = (c: RGB) => 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];

interface Ranked<T> {
  weight: number;
  item: T;
}

export class AfterglowLook implements FxLook {
  readonly fog: Fog;
  readonly storm = new Storm({
    count: 9000,
    depth: 420,
    focal: 1600,
    lifeMin: 1.5,
    lifeMax: 4.5,
    swirl: 3,
    swirlScale: 700,
    drag: 3.5,
    jitter: 36,
    spread: 0,
    faintest: 0.035,
    peak: 7,
    magnitudePower: 1.1,
    halo: 0,
    twinkle: 0.45,
    palette: [SPECK_E, SPECK_E2, SPECK_N, SPECK_ATOM, SPECK_E, SPECK_E, SPECK_E, SPECK_E],
    weights: [3, 0.7, 0.5, 0, 0, 0, 0, 0],
  });
  readonly filaments = new Filaments();
  private readonly baseBright: number;
  private r: Renderer | null = null;
  private saved: Partial<PostParams> = {};
  private lights: Ranked<VolumeLight>[] = [];
  private fronts: Ranked<VolumeFront>[] = [];
  private kicks: Ranked<StormKick>[] = [];
  private speckLights: Ranked<StormLight>[] = [];
  /** How thick the fog is now (the free-electron share, 1 → 0), and whether the light streams free. */
  private thick = 1;
  private free = false;
  private seg = new Float32Array(6);
  private packet = new Float32Array(34);
  private packetCore = new Float32Array(17);
  private packetSheath = new Float32Array(17);

  constructor(params: AfterglowBgParams, imprint: Imprint) {
    this.fog = new Fog(params, imprint);
    this.baseBright = this.fog.config.brightness;
  }

  attach(r: Renderer): void {
    this.r = r;
    r.setBackground(BLACK);
    r.setLayers([this.fog, this.storm, this.filaments]);
    const post = r.post as unknown as Record<string, unknown>;
    for (const [k, v] of Object.entries(POST)) {
      (this.saved as Record<string, unknown>)[k] = post[k];
      post[k] = v;
    }
  }

  detach(r: Renderer): void {
    r.setLayers([]);
    Object.assign(r.post, this.saved);
    this.r = null;
  }

  /**
   * The state of the medium: `xe` the share of electrons still free (the fog's thickness), `reveal`
   * 0 → 1 as First Light shows the frozen pattern, `lift` a brief brightening (the era's opening),
   * `crest` the colour of compressed plasma (a little hotter than the bath), `amp` a freshly rung
   * wave's amplitude (the waves are drawn relative to it), `warmth` 0 (white-hot) → 1 (candle light).
   */
  medium(xe: number, reveal: number, lift: number, crest: RGB, amp: number, warmth: number): void {
    this.thick = xe;
    this.free = reveal > 0;
    // Warm light is graded richer, so candle orange glows instead of greying toward brown.
    if (this.r) this.r.post.saturation = (POST.saturation ?? 1.18) + 0.3 * warmth;
    this.fog.config.brightness = this.baseBright * (1 + lift);
    this.fog.crestColor = [crest[0], crest[1], crest[2]];
    this.fog.ampRef = amp;
    const s = this.storm.config;
    const calm = 1 - reveal;
    // Free electrons jitter fast and twinkle; as they are caught the storm calms into dim atoms.
    s.weights[0] = 3 * xe;
    s.weights[1] = 0.7 * xe;
    s.weights[2] = 0.5 * xe;
    s.weights[3] = 2.4 * (1 - xe) + 0.05;
    s.jitter = 36 * (0.2 + 0.8 * xe);
    s.twinkle = 0.12 + 0.33 * xe;
    s.faintest = 0.035 * (0.15 + 0.85 * calm);
    s.peak = 7 * (0.1 + 0.9 * calm);
  }

  /** Starts a frame (the effect lists refill every frame). */
  begin(r: Renderer): void {
    this.r = r;
    this.lights.length = 0;
    this.fronts.length = 0;
    this.kicks.length = 0;
    this.speckLights.length = 0;
  }

  /** A light inside the fog (it brightens and tints the medium around it). */
  light(x: number, y: number, radius: number, c: RGB): void {
    this.lights.push({ weight: lum(c) * radius, item: { x, y, z: 0, radius, color: [c[0], c[1], c[2]] } });
  }

  /** A light front racing through the fog (and through the specks, pushing them). */
  front(x: number, y: number, radius: number, width: number, c: RGB, push: number): void {
    const l = lum(c);
    this.fronts.push({ weight: l, item: { x, y, radius, width, color: [c[0], c[1], c[2]] } });
    if (push !== 0) this.kicks.push({ weight: Math.abs(push), item: { x, y, radius, push } });
    this.speckLights.push({ weight: l, item: { x, y, intensity: Math.min(4, l * 40), radius, width: width * 1.4 } });
  }

  /**
   * A free electron: a white-hot pinpoint in a tight blue halo, with a short streak along its motion.
   * `k` its brightness (0–1), `depth` (0 near … 1 far) how deep in the fog it seems.
   */
  electron(x: number, y: number, vx: number, vy: number, k: number, depth: number): void {
    const r = this.r;
    if (!r || k <= 0.01) return;
    const e = k * (1 - 0.45 * depth);
    r.top.push(x, y, 1.5, 4.2 * e, 5.2 * e, 7 * e, 1, Shape.Glow);
    r.top.push(x, y, 5, 0.12 * e, 0.2 * e, 0.42 * e, 1, Shape.Glow);
    const p = this.seg;
    p[0] = x - vx * 0.022;
    p[1] = y - vy * 0.022;
    p[2] = x - vx * 0.01;
    p[3] = y - vy * 0.01;
    p[4] = x;
    p[5] = y;
    this.filaments.push(p, ELECTRON_LIGHT, [1, 1, 1], 2.4, [0, 0.25 * e, 0.8 * e], [0, 0.03 * e, 0.07 * e], false);
  }

  /**
   * A bare nucleus as a crisp point light: warm for a proton, gold for helium. `hot` (0–1) whitens
   * one that just lost its electron; `depth` dims and shrinks one that seems deeper in the fog.
   */
  nucleus(x: number, y: number, helium: boolean, k: number, depth: number, hot = 0): void {
    const r = this.r;
    if (!r || k <= 0.01) return;
    const c = helium ? HELIUM_LIGHT : PROTON_LIGHT;
    const s = (helium ? 1.2 : 1) * (1 - 0.2 * depth);
    const e = k * (1 - 0.4 * depth) * (helium ? 1.2 : 1) * (1 + hot);
    r.top.push(x, y, 2.1 * s, 9 * e, 8.6 * e, 8 * e, 1, Shape.Glow);
    r.top.push(x, y, 7 * s, (c[0] + hot) * 1.1 * e, (c[1] + hot) * 1.1 * e, (c[2] + hot) * 1.1 * e, 1, Shape.Glow);
    r.top.push(x, y, 20 * s, c[0] * 0.06 * e, c[1] * 0.06 * e, c[2] * 0.06 * e, 1, Shape.Glow);
  }

  /**
   * An atom: its nucleus, quieter now (a neutral atom no longer scatters the light), inside the faint
   * cool cloud of its bound electron(s), with a spark circling close. `electrons` 1 or 2.
   */
  atom(x: number, y: number, helium: boolean, electrons: number, phase: number, k: number, depth: number): void {
    const r = this.r;
    if (!r || k <= 0.01) return;
    const c = helium ? HELIUM_LIGHT : PROTON_LIGHT;
    const d = 1 - 0.4 * depth;
    const e = k * d;
    const cloud = helium ? 11 : 9.5;
    r.top.push(x, y, 1.7, 5.5 * e, 5.3 * e, 5 * e, 1, Shape.Glow);
    r.top.push(x, y, 5, c[0] * 0.5 * e, c[1] * 0.5 * e, c[2] * 0.5 * e, 1, Shape.Glow);
    r.top.push(x, y, cloud * 1.6, BOUND[0] * 0.1 * e, BOUND[1] * 0.1 * e, BOUND[2] * 0.1 * e, 1, Shape.Glow);
    for (let j = 0; j < electrons; j++) {
      const a = phase * (helium ? 2.1 : 2.6) + j * Math.PI;
      // A tilted orbit, so the circling spark reads in depth (brighter on the near side).
      const ex = x + Math.cos(a) * cloud * 0.62;
      const ey = y + Math.sin(a) * cloud * 0.3;
      const near = 0.6 + 0.4 * Math.sin(a);
      r.top.push(ex, ey, 1.2, 2.2 * e * near, 2.8 * e * near, 3.8 * e * near, 1, Shape.Glow);
    }
  }

  /** A sound wave's crest sweeping through the specks: it shoves them outward as it passes. */
  wave(x: number, y: number, radius: number, amp: number): void {
    if (amp > 0.02) this.kicks.push({ weight: amp, item: { x, y, radius, push: 1100 * amp } });
  }

  /** Where crests cross, the compressed plasma flares: a hot light in the fog, `s` its strength (0–1). */
  crossing(x: number, y: number, s: number, c: RGB): void {
    if (s <= 0.02) return;
    this.light(x, y, 16 + 14 * s, [c[0] * 0.45 * s, c[1] * 0.45 * s, c[2] * 0.45 * s]);
  }

  /**
   * A resonance node, `a` its strength (0–1) and `age` in seconds: a bloom of light in the fog with a
   * white-hot heart and fronts drawing in toward it, asking to be clicked.
   */
  node(x: number, y: number, a: number, age: number, c: RGB): void {
    const r = this.r;
    if (!r || a <= 0.01) return;
    const beat = 0.8 + 0.2 * Math.sin(age * 9);
    r.top.push(x, y, 3.2, 20 * a * beat, 19 * a * beat, 18 * a * beat, 1, Shape.Glow);
    r.top.push(x, y, 14, c[0] * 2.4 * a * beat, c[1] * 2.4 * a * beat, c[2] * 2.4 * a * beat, 1, Shape.Glow);
    r.top.push(x, y, 48, c[0] * 0.18 * a, c[1] * 0.18 * a, c[2] * 0.18 * a, 1, Shape.Glow);
    this.light(x, y, 46, [c[0] * 2.2 * a * beat, c[1] * 2.2 * a * beat, c[2] * 2.2 * a * beat]);
    // Two fronts drawing in, one after the other.
    for (let j = 0; j < 2; j++) {
      const pull = (age * 0.9 + j * 0.5) % 1;
      const k = a * Math.sin(Math.PI * pull);
      const g = 0.05 * k;
      this.front(x, y, 150 - 120 * pull, 14, [c[0] * g, c[1] * g, c[2] * g], -260 * k);
    }
  }

  /** A dark matter well: unseen, felt as a slow violet heartbeat in the fog. */
  well(x: number, y: number, beat: number, k: number): void {
    const r = this.r;
    if (!r || k <= 0.01) return;
    this.light(x, y, 50 + 15 * beat, [WELL[0] * 0.16 * beat * k, WELL[1] * 0.16 * beat * k, WELL[2] * 0.16 * beat * k]);
    r.top.push(x, y, 1.6, 1.2 * beat * k, 0.9 * beat * k, 2.4 * beat * k, 1, Shape.Glow);
  }

  // ─── FxLook: the era's effects, restyled

  flash(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * (1 - t);
    const rr = this.r;
    if (!rr || f <= 0.003) return;
    rr.top.push(x, y, Math.min(3.5, 1.4 + size * 0.04), r * f * 1.6, g * f * 1.6, b * f * 1.6, 1, Shape.Glow);
    rr.top.push(x, y, size * 0.45, r * f * 0.2, g * f * 0.2, b * f * 0.2, 1, Shape.Glow);
    // In thick fog a flash lights a small, dense glow; as the fog thins its light reaches farther.
    const reach = size * (1.6 + 1.4 * (1 - this.thick));
    this.light(x, y, reach, [r * f * 0.6, g * f * 0.6, b * f * 0.6]);
    const l = lum([r, g, b]) * f;
    this.speckLights.push({ weight: l * size * 0.02, item: { x, y, intensity: 2.2 * l, radius: reach, width: 0 } });
  }

  ring(x: number, y: number, radius: number, r: number, g: number, b: number, t: number): void {
    const f = Math.pow(1 - t, 1.6);
    if (f <= 0.01) return;
    const l = lum([r, g, b]);
    const k = 0.05 * f;
    this.front(x, y, radius, 22 + radius * 0.08, [r * k, g * k, b * k], 2000 * Math.min(2, l) * f);
  }

  spark(x: number, y: number, vx: number, vy: number, size: number, r: number, g: number, b: number, t: number): void {
    const speed = Math.hypot(vx, vy) || 1;
    const ux = vx / speed;
    const uy = vy / speed;
    // The streak's colour at unit brightness (its intensity comes from k).
    const l = Math.max(1, lum([r, g, b]));
    const c: RGB = [r / l, g / l, b / l];
    if (this.free) {
      // The light streams free: a long, straight, crisp streak, unscattered at last.
      const k = Math.min(1, size * 0.3) * Math.min(1, (1 - t) * 2.5) * Math.min(1, t * 8);
      if (k <= 0.01) return;
      const len = 18 + 30 * t;
      const p = this.seg;
      p[0] = x - ux * len;
      p[1] = y - uy * len;
      p[2] = x - ux * len * 0.4;
      p[3] = y - uy * len * 0.4;
      p[4] = x;
      p[5] = y;
      this.filaments.push(p, c, [1, 1, 1], 2.2, [0, 0.25 * k, 1.2 * k], [0, 0.02 * k, 0.06 * k], false);
      return;
    }
    // A captured electron's photon: a wave packet that scatters out of sight within a mean free path,
    // which grows as the fog thins (so the same photon now travels a little farther).
    const reach = 0.22 + 1.1 * (1 - this.thick) ** 1.5;
    const k = Math.min(1.2, size * 0.35) * Math.exp(-t / reach) * Math.min(1, t * 12);
    if (k <= 0.01) return;
    const n = 16;
    const len = 30;
    const lam = 6.5;
    const amp = 2.4;
    const ph = t * 55;
    const pts = this.packet;
    for (let j = 0; j <= n; j++) {
      const s = (j / n - 0.5) * len;
      const env = Math.exp(-((s / (0.3 * len)) ** 2));
      const w = amp * env * Math.sin((2 * Math.PI * s) / lam - ph);
      pts[j * 2] = x + ux * s - uy * w;
      pts[j * 2 + 1] = y + uy * s + ux * w;
      this.packetCore[j] = env * 1.1 * k;
      this.packetSheath[j] = env * 0.12 * k;
    }
    this.filaments.push(pts, PHOTON, PHOTON, 3, this.packetCore, this.packetSheath, false);
  }

  puff(x: number, y: number, size: number, r: number, g: number, b: number, t: number): void {
    const f = (1 - t) * Math.min(1, t * 6);
    if (f > 0.01) this.light(x, y, size, [r * 0.4 * f, g * 0.4 * f, b * 0.4 * f]);
  }

  /** Ends the frame: the strongest lights, fronts and pushes go to the layers (each has a few slots). */
  end(): void {
    const top = <T>(list: Ranked<T>[], n: number): T[] => list.sort((a, b) => b.weight - a.weight).slice(0, n).map((x) => x.item);
    this.fog.lights = top(this.lights, 12);
    this.fog.fronts = top(this.fronts, 6);
    this.storm.kicks = top(this.kicks, 4);
    this.storm.lights = top(this.speckLights, 8);
  }
}
