<!--
  Energy: the one currency, in real units, with a tangible comparison on hover.
-->
<script lang="ts">
  import { energy, power } from '../../core/format';
  import { energyComparison } from '../../content/comparisons';
  import Num from '../common/Num.svelte';
  import Tip from '../common/Tip.svelte';
  import { game, track } from '../store.svelte';

  const g = game();

  const v = $derived.by(() => {
    track();
    const run = g.state.run;
    const unit = (run.joules ? 'J' : 'eV') as 'J' | 'eV';
    return {
      e: energy(run.energy, unit, g.state.settings.notation),
      rate: power(g.energyMeter.rate, unit, g.state.settings.notation),
      hasRate: g.energyMeter.rate > 0,
      compare: energyComparison(run.energy),
      total: energy(run.energyTotal, unit, g.state.settings.notation),
    };
  });
</script>

<section class="energy">
  <div class="label flush-right">Energy</div>
  <Tip side="left" width="17rem">
    <!-- svelte-ignore a11y_no_noninteractive_tabindex (focusable so keyboard players get the tooltip) -->
    <div class="value" tabindex="0"><Num parts={v.e} /></div>
    {#snippet tip()}
      {#if v.compare}<p class="cmp">{v.compare}</p>{/if}
      <p class="small">Released by physical processes and spent to bring about new ones. Total this universe: <Num parts={v.total} /></p>
    {/snippet}
  </Tip>
  <div class="rate" class:dim={!v.hasRate}><Num parts={v.rate} sign="+" /></div>
</section>

