/**
 * What the frame reads right now: the time and temperature above the field, and the field's true
 * width under the scale bar. At rest they are the era's own. Through a pull-back between eras they
 * follow the camera (Powers of Ten): the bar counts from one era's length up to the next's in step
 * with the camera's move, and the clock and the thermometer run on from where the one era ended to
 * where the next begins, the same share of the way.
 *
 * Nothing here knows any era: it reads the two eras' entries (eras.ts), the receding era's `pullBack`
 * distance and the camera, so a new entry plugs in as it is.
 */
import type { Game } from '../../core/game';
import { ERA_ORDER, type EraId } from '../../core/state';
import { CLOSE } from '../../render/pullback';
import { barMeters, frameEra, type FrameEra } from './eras';
import { lengthInWords } from './lengths';

export interface FrameReadings {
  /** Cosmic time in seconds. */
  t: number;
  /** Temperature in kelvin. */
  T: number;
  /** The scale bar's length in meters; null in an era without the frame. */
  meters: number | null;
  /** That length in plain words. */
  compare: string;
  /**
   * Through a pull-back, the old era's field on the screen, as a share of the frame's (1 as it starts
   * to recede, shrinking as the camera draws back); 0 at rest and when the camera doesn't move.
   */
  old: number;
}

export type ReadingsHost = Pick<Game, 'state' | 'renderer' | 'currentStep' | 'steps' | 'eraDefOf'>;

/** The nearest era before (−1) or after (+1) `era` that this build has. */
function neighbour(g: ReadingsHost, era: EraId, dir: -1 | 1): EraId | null {
  for (let i = ERA_ORDER.indexOf(era) + dir; i >= 0 && i < ERA_ORDER.length; i += dir) if (g.eraDefOf(ERA_ORDER[i])) return ERA_ORDER[i];
  return null;
}

/** The value `p` of the way from `a` to `b`, by ratio. */
const between = (a: number, b: number, p: number) => a * (b / a) ** p;

/** Each era's own words hold within this ratio of its own length; counted words fill the rest. */
const OWN_WORDS = 1.15;

/**
 * A step is time passing: for a moment after one is taken, the clock and the thermometer run from the
 * step before to the new one (by ratio, eased), so the jump in the date is seen to happen.
 */
const ROLL = 1.4;
let roll: { t0: number; T0: number; t1: number; T1: number; at: number } | null = null;

/** A step was just taken (from `from` to `to`); with reduce motion the readings change at once. */
export function markStep(from: { t: number; T: number }, to: { t: number; T: number }, still = false, now = performance.now()): void {
  roll = still ? null : { t0: from.t, T0: from.T, t1: to.t, T1: to.T, at: now };
}

/** The rolling date and temperature, while a step's roll lasts (the step itself must still be current). */
function rolling(t: number, T: number, now: number): { t: number; T: number } | null {
  if (!roll || roll.t1 !== t || roll.T1 !== T) return null;
  const u = (now - roll.at) / 1000 / ROLL;
  if (u >= 1 || u < 0) {
    roll = null;
    return null;
  }
  // Fast at first, settling on the new date.
  const e = 1 - (1 - u) ** 3;
  return { t: between(roll.t0, roll.t1, e), T: between(roll.T0, roll.T1, e) };
}

export function frameReadings(g: ReadingsHost, now = performance.now()): FrameReadings {
  const run = g.state.run;
  const era = frameEra(run.era);
  const T0 = g.currentStep.T;
  const rest: FrameReadings = { t: run.time, T: T0, meters: era ? barMeters(era, T0) : null, compare: era?.compare ?? '', old: 0 };
  const r0 = rolling(rest.t, rest.T, now);
  if (r0) {
    rest.t = r0.t;
    rest.T = r0.T;
    // A patch of the expanding universe grows as it cools: the bar rolls with the thermometer.
    if (era && typeof era.meters !== 'number') rest.meters = era.meters(r0.T);
  }
  if (rest.meters !== null && !era?.compare) rest.compare = lengthInWords(rest.meters) ?? '';
  const r = g.renderer;
  if (!era || !r || r.pullBack.phase === 'idle') return rest;

  // Receding (and held at the end of it), this era hands over to the next; arriving, it took over from
  // the one before.
  const phase = r.pullBack.phase;
  const arriving = phase === 'arrive';
  const from = arriving ? neighbour(g, run.era, -1) : run.era;
  const to = arriving ? run.era : neighbour(g, run.era, 1);
  const A = from ? frameEra(from) : null;
  const B = to ? frameEra(to) : null;
  // Each end's length where the move meets it: the last step of the era handing over, the first of the one arriving.
  const lastT = (id: EraId) => {
    const s = g.steps(id);
    return s[s.length - 1].T;
  };
  const aM = A && from ? barMeters(A, lastT(from)) : 0;
  const bM = B && to ? barMeters(B, g.steps(to)[0].T) : 0;
  // How far the camera has drawn back so far (×), out of the whole move: the recede (the receding
  // era's `pullBack`, clamped as PullBack clamps it), then the arrival settling back from CLOSE.
  const reach = Math.max(1.5, (from && g.eraDefOf(from)?.pullBack) || 1);
  const d = r.camera.distance;
  // Settling back, the arrival's share comes on top of the whole recede. Held at the end of the recede
  // the screen rests where it ended, though the camera may already be set up close for the arrival;
  // and until the arrival's first frame the camera still holds the recede's end. (With reduce motion
  // the camera never moves: the readings change at the hand-over, with the scene's cross-fade.)
  const moved = arriving && d <= 1 ? reach * CLOSE * d : phase === 'held' && d < 1 ? reach : d;

  let meters: number;
  if (A && B) {
    // From one era's length to the next's, the same share of the way as the camera's move: true to
    // the camera when the two lengths agree with it, and landing on the new era's length when not.
    meters = between(aM, bM, Math.log(moved) / Math.log(reach * CLOSE));
  } else if (arriving) {
    // Arriving from an era without the frame: only the arrival's own move.
    meters = barMeters(era, T0) * Math.min(1, d);
  } else meters = barMeters(era, T0) * moved;

  const near = (e: FrameEra | null, m: number): boolean => !!e && !!e.compare && Math.abs(Math.log(meters / m)) < Math.log(OWN_WORDS);
  const own = near(A, aM) ? A : near(B, bM) ? B : null;
  const out: FrameReadings = { ...rest, meters, compare: own?.compare ?? lengthInWords(meters) ?? '', old: r.pullBack.still ? 0 : 1 / Math.max(1, moved) };
  if (!from || !to || !A || !B || aM === bM) return out;
  // How far along the move the bar is, by scale; the clock and the thermometer go the same share of
  // the way from the last step of one era to the first of the next.
  const p = Math.min(1, Math.max(0, Math.log(meters / aM) / Math.log(bM / aM)));
  const ended = g.steps(from);
  const last = ended[ended.length - 1];
  const first = g.steps(to)[0];
  return { ...out, t: between(last.t, first.t, p), T: between(last.T, first.T, p) };
}
