<!--
  Optional performance readout (Settings → Performance readout).
-->
<script lang="ts">
  import { game, track } from '../store.svelte';

  const g = game();
  const v = $derived.by(() => {
    track();
    const r = g.renderer;
    return {
      fps: Math.round(1000 / Math.max(1, g.frameMs)),
      ms: g.frameMs.toFixed(1),
      sprites: r?.stats.sprites ?? 0,
      lines: r?.stats.lines ?? 0,
      cpu: (r?.stats.cpuMs ?? 0).toFixed(2),
      scale: r ? Math.round(r.renderScale * 100) : 0,
    };
  });
</script>

<div class="perf num">
  {v.fps} fps · {v.ms} ms · render {v.cpu} ms · {v.sprites} sprites · {v.lines} lines · {v.scale}%
</div>

<style>
  .perf {
    position: fixed;
    left: 50%;
    top: 3px;
    translate: -50% 0;
