<!--
  Settings: sound, visuals, accessibility, saves.
-->
<script lang="ts">
  import Panel from './Panel.svelte';
  import { exportString, importString } from '../../core/save';
  import type { Quality, Settings } from '../../core/state';
  import { native } from '../../platform/native';
  import { game } from '../store.svelte';

  // The desktop shell: fullscreen and quitting from inside the game.
  const bridge = native();
  let fullscreen = $state(bridge?.isFullscreen() ?? false);
  function toggleFullscreen(): void {
    if (!bridge) return;
    fullscreen = !fullscreen;
    bridge.setFullscreen(fullscreen);
  }

  const g = game();
  let s = $state({ ...g.state.settings });
  let exported = $state('');
  let importText = $state('');
  let importError = $state('');
  let resetArmed = $state(false);

  function apply<K extends keyof Settings>(key: K, value: Settings[K]) {
    s[key] = value;
    g.state.settings[key] = value;
    g.bus.emit('settings', {});
    g.persist();
  }

  const volumes: { key: 'masterVolume' | 'musicVolume' | 'sfxVolume' | 'ambienceVolume'; label: string }[] = [
    { key: 'masterVolume', label: 'Master' },
    { key: 'musicVolume', label: 'Music' },
    { key: 'sfxVolume', label: 'Effects' },
    { key: 'ambienceVolume', label: 'Ambience' },
  ];
  const toggles: { key: 'reduceFlashes' | 'reduceMotion' | 'floatingNumbers' | 'muteOnBlur' | 'showPerf'; label: string; note: string }[] = [
    { key: 'reduceFlashes', label: 'Reduce flashes', note: 'Caps the brightness and rate of flashes.' },
    { key: 'reduceMotion', label: 'Reduce motion', note: 'No screen shake; softer camera moves.' },
    { key: 'floatingNumbers', label: 'Floating numbers', note: 'Show energy where it is released.' },
    { key: 'muteOnBlur', label: 'Mute in background', note: 'Silence when the game is not focused.' },
    { key: 'showPerf', label: 'Performance readout', note: 'Frame time and particle counts.' },
  ];
  const qualities: { q: Quality; label: string }[] = [
    { q: 'auto', label: 'Auto' },
    { q: 'low', label: 'Low' },
    { q: 'medium', label: 'Medium' },
    { q: 'high', label: 'High' },
  ];

  function doExport() {
    exported = exportString(g.state);
    navigator.clipboard?.writeText(exported).catch(() => {});
  }

  function doImport() {
    importError = '';
    try {
      const st = importString(importText, Date.now());
      g.adopt(st);
      location.reload();
    } catch (e) {
      importError = e instanceof Error ? e.message : 'That save could not be read.';
    }
  }

  function doReset() {
    if (!resetArmed) {
      resetArmed = true;
      setTimeout(() => (resetArmed = false), 4000);
      return;
    }
    g.hardReset();
    location.reload();
  }
</script>

<Panel title="Settings">
  <h3 class="label">Sound</h3>
  {#each volumes as v (v.key)}
    <label class="row">
      <span>{v.label}</span>
      <input
        type="range"
        min="0"
        max="1"
        step="0.01"
        value={s[v.key]}
        aria-valuetext="{Math.round(s[v.key] * 100)} percent"
        oninput={(e) => apply(v.key, Number((e.currentTarget as HTMLInputElement).value))}
      />
      <span class="num pct" aria-hidden="true">{Math.round(s[v.key] * 100)}</span>
    </label>
  {/each}

  <h3 class="label">Display</h3>
  <div class="row">
    <span>Quality</span>
    <div class="seg" role="group" aria-label="Quality">
      {#each qualities as q (q.q)}
        <button class:on={s.quality === q.q} aria-pressed={s.quality === q.q} onclick={() => apply('quality', q.q)}>{q.label}</button>
      {/each}
    </div>
  </div>
  <div class="row">
    <span>Numbers</span>
    <div class="seg" role="group" aria-label="Numbers">
      <button class:on={s.notation === 'scientific'} aria-pressed={s.notation === 'scientific'} aria-label="Scientific" onclick={() => apply('notation', 'scientific')}>4.2 × 10<sup>45</sup></button>
      <button class:on={s.notation === 'engineering'} aria-pressed={s.notation === 'engineering'} aria-label="Engineering" onclick={() => apply('notation', 'engineering')}>42 × 10<sup>44</sup></button>
    </div>
  </div>
  <label class="row">
    <span>Interface size</span>
    <input
      type="range"
      min="0.8"
      max="1.5"
      step="0.05"
      value={s.uiScale}
      aria-valuetext="{Math.round(s.uiScale * 100)} percent"
      oninput={(e) => apply('uiScale', Number((e.currentTarget as HTMLInputElement).value))}
    />
    <span class="num pct" aria-hidden="true">{Math.round(s.uiScale * 100)}</span>
  </label>
  {#each toggles as t (t.key)}
    <button class="toggle" class:on={s[t.key]} aria-pressed={s[t.key]} onclick={() => apply(t.key, !s[t.key])}>
      <span class="box" aria-hidden="true"></span>
      <span class="tl">{t.label}<small>{t.note}</small></span>
    </button>
  {/each}

  {#if bridge}
    <h3 class="label">Window</h3>
    <button class="toggle" class:on={fullscreen} aria-pressed={fullscreen} onclick={toggleFullscreen}>
      <span class="box" aria-hidden="true"></span>
      <span class="tl">Fullscreen<small>F11 also works</small></span>
    </button>
    <div class="actions">
      <button class="act" onclick={() => { g.persist(); bridge.quit(); }}>Quit to desktop</button>
    </div>
  {/if}

  <h3 class="label">Save</h3>
  <p class="note">The game saves itself every few seconds and whenever you leave.</p>
  <div class="actions">
    <button class="act" onclick={doExport}>Export</button>
    <button class="act danger" class:armed={resetArmed} onclick={doReset}>{resetArmed ? 'Press again to erase everything' : 'Start over'}</button>
  </div>
  {#if exported}
    <textarea class="io" readonly rows="3" aria-label="Exported save" value={exported} onfocus={(e) => (e.currentTarget as HTMLTextAreaElement).select()}></textarea>
    <p class="note">Copied to the clipboard.</p>
  {/if}
  <textarea class="io" rows="3" placeholder="Paste a save here to load it" aria-label="Paste a save to load" bind:value={importText}></textarea>
  {#if importText.trim()}
    <button class="act" onclick={doImport}>Load this save</button>
  {/if}
  {#if importError}<p class="err">{importError}</p>{/if}

  <p class="credit">Instrument recordings from VSCO 2 Community Edition and VCSL, by Versilian Studios (CC0).</p>
  <p class="foot">Ylem · v0.1 · Esc closes this panel</p>
</Panel>

