/**
 * The Dark Ages are almost silent: a sub drone and cold air. Each first star ignites with a slow
 * swell, the warmest sound the universe has made so far; supernovae answer with weight.
 */
import type { EraAudio } from '../../audio/director';
import { bell, noise, pluck, swell, thump } from '../../audio/patches';
import { SCALES, mtof, note, type Key } from '../../audio/scales';

const KEY: Key = { root: 40, scale: SCALES.dorian };

export const DAWN_AUDIO: EraAudio = {
  key: KEY,
  bed: {
    id: 'dawn',
    chords: [
      [28, 40, 47],
      [26, 38, 45],
      [28, 40, 43],
      [24, 36, 43],
    ],
    chordSeconds: 34,
    pad: { gain: 0.06, type: 'sine', cutoff: 520, detune: 4, lfo: 0.02 },
    drone: { note: 28, gain: 0.045 },
    air: { freq: 1600, q: 0.4, gain: 0.02, drift: 0.015 },
    // Deliberately about 2 dB under the other beds: the Dark Ages are nearly silent until the first star.
    level: 1,
  },
  cues: {
    'dawn.gather': (a, p, c) => {
      const g = a.admit('dawn.gather', 0.45);
      if (g) noise(a, { dur: 0.9, freq: 220, to: 520, q: 1.2, gain: 0.08 * g, attack: 0.25, pan: c.pan(p.x), bus: 'ambience' });
    },
    'dawn.merge': (a, p, c) => {
      const g = a.admit('dawn.merge', 0.12);
      if (g) thump(a, 70, { gain: 0.08 * g, dur: 0.35, pan: c.pan(p.x) });
    },
    'dawn.critical': (a, p, c) => {
      const g = a.admit('dawn.critical', 0.5);
      if (g) bell(a, mtof(note(c.key, 11)), { gain: 0.04 * g, decay: 2.5, ratio: 2, bright: 0.3, pan: c.pan(p.x) });
    },
    'dawn.ignite': (a, p, c) => {
      const g = a.admit('dawn.ignite', 0.3);
      if (!g) return;
      const t = a.now;
      thump(a, 48, { time: t, gain: 0.25 * g, dur: 1.2, pan: c.pan(p.x) });
      swell(a, [52, 59, 64, 68, 71].map(mtof), { time: t, attack: 1.4, hold: 1.2, release: 6, gain: 0.16 * g, cutoff: 3000 });
      [7, 9, 11, 14].forEach((d, i) => bell(a, mtof(note(c.key, d + 7)), { time: t + 0.3 + i * 0.12, gain: 0.04 * g, decay: 3, ratio: 2, bright: 0.6, pan: c.pan(p.x) }));
    },
    'dawn.sn': (a, p, c) => {
      if (!a.admit('dawn.sn', 0.25)) return;
      const t = a.now;
      thump(a, 36, { time: t, gain: 0.32, dur: 2.2, pan: c.pan(p.x) });
      noise(a, { time: t, dur: 3, freq: 4200, to: 220, q: 0.6, gain: 0.12, attack: 0.005, pan: c.pan(p.x) });
      bell(a, mtof(note(c.key, 0)), { time: t + 0.05, gain: 0.06, decay: 4, ratio: 3.5, bright: 1.2, pan: c.pan(p.x) });
    },
    'dawn.bh': (a, p, c) => {
      if (!a.admit('dawn.bh', 0.5)) return;
      const t = a.now;
      thump(a, 33, { time: t + 0.6, gain: 0.3, dur: 2.8, pan: c.pan(p.x) });
      noise(a, { time: t + 0.4, dur: 1.6, freq: 1800, to: 90, q: 2, gain: 0.05, attack: 0.6, pan: c.pan(p.x) });
    },
    'dawn.halo': (a, p, c) => {
      if (!a.admit('dawn.halo', 0.6)) return;
      noise(a, { dur: 2.4, freq: 160, to: 900, q: 0.8, gain: 0.05, attack: 1.2, pan: c.pan(p.x), bus: 'ambience' });
      bell(a, mtof(note(c.key, 4)), { time: a.now + 0.8, gain: 0.04, decay: 3, ratio: 2, bright: 0.4, pan: c.pan(p.x) });
    },
    'dawn.metal': (a, p, c) => {
      const g = a.admit('dawn.metal', 0.15);
      if (g) pluck(a, mtof(note(c.key, 16 + Math.floor(Math.random() * 4))), { gain: 0.04 * g, decay: 0.4, tone: 8, pan: c.pan(p.x) });
    },
    'dawn.milestone': (a, _p, c) => {
      const t = a.now;
      swell(a, [40, 47, 52, 56, 59].map(mtof), { bus: 'music', time: t, attack: 1.8, hold: 1, release: 5, gain: 0.14, cutoff: 1600 });
      bell(a, mtof(note(c.key, 7)), { bus: 'music', time: t + 0.5, gain: 0.05, decay: 3.5, ratio: 2, bright: 0.4 });
    },
    'dawn.complete': (a) => {
      const t = a.now;
      thump(a, 33, { time: t, gain: 0.3, dur: 2.5 });
      swell(a, [40, 47, 52, 56, 59, 64, 71].map(mtof), { time: t + 0.3, attack: 2.5, hold: 2.5, release: 8, gain: 0.22, cutoff: 3200 });
    },
  },
};
