/** Tones the effects come in (tools/sound/cues/era2-sfx.ts): B♭ major. */
const TONES = ['Bb', 'C', 'D', 'Eb', 'F', 'G', 'A'];

/** The bed's loop, s (tools/sound/cues/era2.ts: 36 bars at 72 beats a minute). */
const LOOP = 120;

/**
 * The bed's chords as [start s, the effect tones inside it, root first] (era2Tones in
 * tools/sound/cues/era2.ts, which a test keeps this table in step with): B♭(add9), C/B♭, Gm9, E♭maj7,
 * B♭/D, E♭(add9), Cm7, Dm7, D (only D and A of it are among the effects' tones), Gm(add9), E♭maj9,
 * F sus4, F.
 */
const CHORDS: [number, readonly string[]][] = [
  [0, ['Bb', 'D', 'F', 'C']],
  [10, ['Bb', 'G', 'C']],
  [20, ['G', 'Bb', 'D', 'F', 'A']],
  [30, ['Eb', 'G', 'Bb', 'D']],
  [40, ['Bb', 'F', 'C', 'D']],
  [50, ['Eb', 'G', 'Bb', 'F']],
  [60, ['C', 'Eb', 'G', 'Bb']],
  [70, ['D', 'F', 'A', 'C']],
  [80, ['D', 'A']],
  [90, ['G', 'Bb', 'D', 'A']],
  [100, ['Eb', 'G', 'D', 'F', 'Bb']],
  [110, ['F', 'Bb', 'C']],
  [116 + 2 / 3, ['F', 'A', 'C']],
];

/**
 * The effect tones inside the chord playing at `t` seconds into the bed's loop, root first. The one
 * place in the game that knows the bed's harmony.
 */
export function tonesAt(t: number): readonly string[] {
  const u = ((t % LOOP) + LOOP) % LOOP;
  let k = 0;
  while (k + 1 < CHORDS.length && CHORDS[k + 1][0] <= u) k++;
  return CHORDS[k][1];
}

const pick = <T>(xs: readonly T[]): T => xs[Math.floor(Math.random() * xs.length)];
const smooth = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};
/** A tone inside the chord playing. */
const inChord = (s: SoundApi) => pick(tonesAt(s.position()));
/** The chord playing's root (or bass): the big moments swell on it in octaves. */
const root = (s: SoundApi) => tonesAt(s.position())[0];
/** Products heavier than deuterium (tritium, helium-3, lithium-7, beryllium-7) fuse an octave lower. */
const heavy = (species: number) => species >= 3;
/** One of an effect's two variants: the second (decoded lazily) once it has decoded, the first meanwhile. */
const variant = (s: SoundApi, base: string) => (Math.random() < 0.5 && s.ready(`${base}-1`) ? `${base}-1` : `${base}-0`);

/** Era II in rendered sound: the era2 bed, and every event in the chord playing. */
export const NUCLEO_SOUND: EraSound = {
  stems: { id: 'era2', names: ['era2-calm', 'era2-active', 'era2-theme'], loop: LOOP, layers: (a) => [1, smooth(0.1, 0.45, a), 0.9 * smooth(0.45, 0.85, a)] },
  load: [
    ...TONES.flatMap((t) => [`e2-fuse-${t}-0`, `e2-he4-${t}-0`]),
    ...TONES.flatMap((t) => ['fuse-low', 'break', 'decay', 'grab', 'glint'].map((k) => `e2-${k}-${t}`)),
    ...[0, 1, 2, 3].map((k) => `e2-bounce-${k}`),
    ...[0, 1, 2].map((k) => `e2-fling-${k}`),
    ...Array.from({ length: 8 }, (_, k) => `e2-buy-${k}`),
  ],
  // A few times an era (the swells, the arpeggios, the fast neutron), or a second variant that plays
  // only once it has decoded (until then the first stands in): decoded when asked for.
  lazy: [
    ...TONES.flatMap((t) => [`e2-fuse-${t}-1`, `e2-he4-${t}-1`]),
    ...TONES.flatMap((t) => ['catch', 'discover', 'step', 'bottleneck', 'freeze'].map((k) => `e2-${k}-${t}`)),
    'e2-fast',
  ],
  cues: {
    'nucleo.fuse': (s, p) => {
      const g = s.admit('nucleo.fuse', 0.05);
      if (!g) return;
      const name = heavy(Math.round(p.pitch ?? 2)) ? `e2-fuse-low-${inChord(s)}` : variant(s, `e2-fuse-${inChord(s)}`);
      s.play(name, { x: p.x, gain: 0.8 * g * Math.min(1.3, p.intensity ?? 1) });
    },
    'nucleo.he4': (s, p) => {
      const g = s.admit('nucleo.he4', 0.07);
      if (g) s.play(variant(s, `e2-he4-${inChord(s)}`), { x: p.x, gain: 0.8 * g });
    },
    'nucleo.break': (s, p) => {
      const g = s.admit('nucleo.break', 0.06);
      if (g) s.play(`e2-break-${inChord(s)}`, { x: p.x, gain: 0.6 * g });
    },
    'nucleo.decay': (s, p) => {
      const g = s.admit('nucleo.decay', 0.1);
      if (g) s.play(`e2-decay-${inChord(s)}`, { x: p.x, gain: 0.6 * g });
    },
    'nucleo.bounce': (s, p) => {
      const g = s.admit('nucleo.bounce', 0.1);
      if (g) s.play(`e2-bounce-${Math.floor(Math.random() * 4)}`, { x: p.x, gain: 0.7 * g });
    },
    'nucleo.grab': (s, p) => {
      const g = s.admit('nucleo.grab', 0.05);
      if (g) s.play(`e2-grab-${inChord(s)}`, { x: p.x, gain: 0.9 * g });
    },
    'nucleo.fling': (s, p) => {
      const g = s.admit('nucleo.fling', 0.05);
      if (!g) return;
      const k = p.intensity ?? 1;
      s.play(`e2-fling-${k < 0.6 ? 0 : k < 1.1 ? 1 : 2}`, { x: p.x, gain: 0.9 * g });
    },
    // Electrons and positrons annihilate: ten calls in 0.7 s, a glitter across the chord.
    'nucleo.annihilate': (s, p) => {
      const g = s.admit('nucleo.annihilate', 0.04);
      if (g) s.play(`e2-glint-${inChord(s)}`, { x: p.x, gain: 0.7 * g });
    },
    // A step's own introduction is music: heard over the effects, which duck under it.
    'nucleo.bottleneck': (s) => s.play(`e2-bottleneck-${root(s)}`, { gain: 1, bus: 'music' }),
    'nucleo.fast': (s, p) => {
      if (s.admit('nucleo.fast', 0.3)) s.play('e2-fast', { x: p.x, gain: 0.8 });
    },
    'nucleo.fast.catch': (s, p) => {
      if (s.admit('nucleo.fast.catch', 0.4)) s.play(`e2-catch-${inChord(s)}`, { x: p.x, gain: 0.9 });
    },
    'nucleo.freeze': (s) => s.play(`e2-freeze-${root(s)}`, { gain: 1 }),
    // The interface in this era's key (the shared ones are in the Soup's D; the shared deny has no pitch).
    'ui.buy': (s) => {
      const g = s.admit('ui.buy', 0.05);
      if (!g) return;
      const k = buyUp(s);
      s.play(k >= 0 ? `e2-buy-${k}` : `e2-decay-${inChord(s)}`, { gain: 0.9 * g });
    },
    'ui.step': (s) => s.play(`e2-step-${root(s)}`, { gain: 0.9 }),
    'ui.discover': (s) => {
      if (s.admit('ui.discover', 0.3)) s.play(`e2-discover-${inChord(s)}`, { gain: 0.8 });
    },
    'ui.open': (s) => {
      const g = s.admit('ui.open', 0.08);
      if (g) s.play(`e2-decay-${inChord(s)}`, { gain: 0.35 * g });
    },
  },
};

/** The tone of each purchase chime, e2-buy-0 … 7 (BUY_SCALE in tools/sound/cues/era2-sfx.ts: B♭ pentatonic over two octaves). */
const BUY_TONES = ['Bb', 'C', 'D', 'F', 'G', 'Bb', 'C', 'D'];
let lastBuy = -1;

/**
 * Purchases climb: the next chime up whose tone is in the chord playing, back to the lowest past the
 * top. −1 if none is (the chord holds only tones the chimes lack).
 */
function buyUp(s: SoundApi): number {
  const tones = tonesAt(s.position());
  const fits = BUY_TONES.flatMap((t, k) => (tones.includes(t) ? [k] : []));
  if (!fits.length) return -1;
  lastBuy = fits.find((k) => k > lastBuy) ?? fits[0];
  return lastBuy;
}
