/**
 * What a galaxy is and what collisions do to it, as pure functions: Hubble types, light, and the
 * outcome of a merger. Masses in units of 10¹⁰ Suns, black holes in Suns.
 *
 * Major mergers (mass ratio 1:4 or closer) destroy both disks and leave an elliptical; minor ones
 * leave the bigger galaxy's shape and add to its bulge (Sb → Sa), or raise shells around an
 * elliptical. Ellipticals and lenticulars hold old stars and give less light per mass.
 */

export type Morph = 'spiral' | 'barred' | 'lenticular' | 'elliptical' | 'irregular' | 'dwarf';

export interface GalaxyProps {
  morph: Morph;
  stars: number;
  gas: number;
  /** Total mass including dark matter. */
  mass: number;
  bh: number;
  /** Bulge share of the stars, 0..1: high for Sa, low for Sc. */
  bulge: number;
  /** Ellipticals: 1 − b/a (0 round … 0.7 flattest). */
  flat: number;
}

export const MAJOR_RATIO = 0.25;

/** "Sb", "SBa", "E3", "S0", "Irr", "dSph". */
export function hubbleType(g: GalaxyProps): string {
  const letter = g.bulge > 0.34 ? 'a' : g.bulge > 0.17 ? 'b' : 'c';
  switch (g.morph) {
    case 'elliptical':
      return `E${Math.max(0, Math.min(7, Math.round(g.flat * 10)))}`;
    case 'lenticular':
      return 'S0';
    case 'spiral':
      return `S${letter}`;
    case 'barred':
      return `SB${letter}`;
    case 'irregular':
      return 'Irr';
    default:
      return 'dSph';
  }
}

const CHARTED_E = [0, 3, 5, 7];

/** Codex id of the chart tile for a Hubble type (ellipticals snap to the charted E0, E3, E5, E7). */
export function hubbleTile(type: string): string {
  if (type.startsWith('E')) {
    const n = Number(type.slice(1));
    let best = CHARTED_E[0];
    for (const c of CHARTED_E) if (Math.abs(c - n) < Math.abs(best - n)) best = c;
    return `gal-E${best}`;
  }
  return `gal-${type}`;
}

export function isDisk(m: Morph): boolean {
  return m === 'spiral' || m === 'barred';
}

/** Light of old stars per unit stellar mass: ellipticals and lenticulars are older and redder. */
export function oldLight(g: GalaxyProps): number {
  return g.stars * (g.morph === 'elliptical' || g.morph === 'lenticular' ? 0.6 : 1);
}

export interface MergeResult {
  remnant: GalaxyProps;
  major: boolean;
  /** An elliptical swallowed a small galaxy: shells. */
  shells: boolean;
  /** Stars formed in the merger's starburst (10¹⁰ Suns). */
  burstStars: number;
}

/**
 * Two galaxies become one. `u` is a uniform random number in [0, 1) for the remnant's shape.
 * Masses add; a major merger's starburst turns half the gas into stars.
 */
export function mergeOutcome(a: GalaxyProps, b: GalaxyProps, u: number): MergeResult {
  const big = a.mass >= b.mass ? a : b;
  const small = big === a ? b : a;
  const ratio = small.mass / big.mass;
  const major = ratio >= MAJOR_RATIO;
  const gas = a.gas + b.gas;
  const burstStars = gas * (major ? 0.5 : 0.15);
  const remnant: GalaxyProps = {
    morph: big.morph,
    stars: a.stars + b.stars + burstStars,
    gas: gas - burstStars,
    mass: a.mass + b.mass,
    bh: a.bh + b.bh,
    bulge: big.bulge,
    flat: big.flat,
  };
  let shells = false;
  if (major) {
    remnant.morph = 'elliptical';
    remnant.bulge = 1;
    // Remnants of equal-mass mergers come out rounder on average.
    remnant.flat = Math.min(0.7, u * (0.35 + 0.5 * (1 - ratio)));
  } else if (isDisk(big.morph)) {
    remnant.bulge = Math.min(0.6, big.bulge + 1.2 * ratio + 0.03);
  } else if (big.morph === 'elliptical') {
    shells = true;
  } else if (big.morph === 'irregular' && ratio > 0.1) {
    remnant.morph = 'irregular';
  }
  return { remnant, major, shells, burstStars };
}
