/**
 * The frame's square field (the version 2 interface, src/ui/frame/Frame.svelte): the smaller of 76 %
 * of the view's height and 54 % of its width, centred. The eras seen through the frame play inside
 * it; this is the one place its size is decided, for the interface's layout and the simulations alike.
 */
export const FIELD_OF_HEIGHT = 0.76;
export const FIELD_OF_WIDTH = 0.54;

/** The field's half side in world units, for a view of half extents `halfW` by `halfH`. */
export function fieldHalf(halfW: number, halfH: number): number {
  return Math.min(FIELD_OF_HEIGHT * halfH, FIELD_OF_WIDTH * halfW);
}
