<!--
  The ending, in three movements: a few words over the Sun and its pale blue dot; black, and the point
  of light everything began as; the title. Then the universe simply goes on.
-->
<script lang="ts">
  import { ui } from '../store.svelte';

  const WORDS = ['One of these stars has a small rocky planet.', 'There is water on it, and time.', 'On it, the universe has made something that can look back.'];
  let shown = $state(0);

  const phase = $derived(ui.ending);
  $effect(() => {
    if (phase !== 'words') return;
    shown = 0;
    const timers = WORDS.map((_, i) => setTimeout(() => (shown = i + 1), 600 + i * 4000));
    return () => timers.forEach(clearTimeout);
  });
</script>

{#if phase}
  <div class="ending" class:dark={phase === 'light' || phase === 'title'} class:out={phase === 'done'} aria-live="polite">
    {#if phase === 'words'}
      <div class="words">
        {#each WORDS.slice(0, shown) as w, i (i)}<p>{w}</p>{/each}
      </div>
    {:else if phase === 'light'}
      <div class="point"></div>
      <p class="began">It began as a point of light.</p>
    {:else if phase === 'title' || phase === 'done'}
      <div class="title">
        <h1>Ylem</h1>
        <p>Thank you for playing.</p>
        <p class="small">Your universes are still here.</p>
      </div>
    {/if}
  </div>
{/if}

