/**
 * Instanced line segments with round caps, per-end colours and widths, and two profiles:
 * a crisp antialiased stroke and a soft glowing filament (for gluon strings, filaments, jets).
 */
import { HEADER } from './glsl';
import { tryProgram, type Program } from './gl';

export const LineStyle = {
  Crisp: 0,
  Glow: 1,
} as const;
export type LineStyle = (typeof LineStyle)[keyof typeof LineStyle];

const FLOATS = 16;

const VS = HEADER + /* glsl */ `
layout(location = 0) in vec2 aCorner;   // x: 0..1 along, y: -1..1 across
layout(location = 1) in vec4 iSeg;      // x0, y0, x1, y1
layout(location = 2) in vec4 iParams;   // width0, width1, style, unused
layout(location = 3) in vec4 iColor0;
layout(location = 4) in vec4 iColor1;
uniform vec4 uView;
uniform float uPxPerUnit;
uniform float uMinPx;
out vec2 vP;
out float vLen;
out vec4 vColor;
flat out int vStyle;
void main() {
  vec2 p0 = iSeg.xy;
  vec2 p1 = iSeg.zw;
  vec2 d = p1 - p0;
  float L = length(d);
  vec2 t = L > 1e-6 ? d / L : vec2(1.0, 0.0);
  vec2 n = vec2(-t.y, t.x);
  float w = mix(iParams.x, iParams.y, aCorner.x);
  float gain = 1.0;
  float px = w * uPxPerUnit;
  if (px < uMinPx) {
    gain = px / uMinPx;
    w = uMinPx / uPxPerUnit;
  }
  float hw = 0.5 * w;
  float along = aCorner.x * (L + 2.0 * hw) - hw;
  vec2 world = p0 + t * along + n * aCorner.y * hw * 1.25;
  vec2 ndc = (world - uView.xy) / uView.zw;
  gl_Position = vec4(ndc.x, -ndc.y, 0.0, 1.0);
  vP = vec2(along / hw, aCorner.y * 1.25);
  vLen = L / hw;
  vec4 c = mix(iColor0, iColor1, aCorner.x);
  vColor = vec4(c.rgb * gain, c.a);
  vStyle = int(iParams.z + 0.5);
}`;

const FS = HEADER + /* glsl */ `
in vec2 vP;
in float vLen;
in vec4 vColor;
flat in int vStyle;
uniform float uGain;      // light into the scene's range (1 with HDR)
out vec4 outColor;
void main() {
  float dx = max(max(-vP.x, vP.x - vLen), 0.0);
  float d = length(vec2(dx, vP.y));
  float a;
  if (vStyle == 1) {
    a = (exp(-d * d * 6.0) + 0.6 * exp(-d * d * 40.0)) * (1.0 - smoothstep(1.0, 1.25, d));
  } else {
    float aa = max(fwidth(d), 1e-4);
    a = 1.0 - smoothstep(1.0 - aa, 1.0 + aa, d);
  }
  a *= vColor.a;
  if (a <= 0.0) discard;
  outColor = vec4(vColor.rgb * a * uGain, a);
}`;

export class LineBatch {
  private data: Float32Array;
  private count = 0;
  private vao: WebGLVertexArrayObject;
  private instanceBuf: WebGLBuffer;
  private cornerBuf: WebGLBuffer;

  constructor(
    private readonly gl: WebGL2RenderingContext,
    /** Null when the driver rejected it: the batch then queues and draws nothing. */
    private readonly program: Program | null,
    private capacity = 2048,
  ) {
    this.data = new Float32Array(capacity * FLOATS);
    const vao = gl.createVertexArray();
    const ib = gl.createBuffer();
    const cb = gl.createBuffer();
    if (!vao || !ib || !cb) throw new Error('Could not allocate line buffers');
    this.vao = vao;
    this.instanceBuf = ib;
    this.cornerBuf = cb;
    gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, cb);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([0, -1, 1, -1, 0, 1, 1, 1]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    gl.bindBuffer(gl.ARRAY_BUFFER, ib);
    gl.bufferData(gl.ARRAY_BUFFER, this.data.byteLength, gl.DYNAMIC_DRAW);
    for (let loc = 1; loc <= 4; loc++) {
      gl.enableVertexAttribArray(loc);
      gl.vertexAttribPointer(loc, 4, gl.FLOAT, false, FLOATS * 4, (loc - 1) * 16);
      gl.vertexAttribDivisor(loc, 1);
    }
    gl.bindVertexArray(null);
  }

  get size(): number {
    return this.count;
  }

  /** Queue a segment. Colours are linear HDR with alpha as intensity. */
  push(
    x0: number,
    y0: number,
    x1: number,
    y1: number,
    w0: number,
    w1: number,
    style: LineStyle,
    r0: number,
    g0: number,
    b0: number,
    a0: number,
    r1 = r0,
    g1 = g0,
    b1 = b0,
    a1 = a0,
  ): void {
    if (this.count >= this.capacity) this.grow();
    const o = this.count * FLOATS;
    const d = this.data;
    d[o] = x0;
    d[o + 1] = y0;
    d[o + 2] = x1;
    d[o + 3] = y1;
    d[o + 4] = w0;
    d[o + 5] = w1;
    d[o + 6] = style;
    d[o + 7] = 0;
    d[o + 8] = r0;
    d[o + 9] = g0;
    d[o + 10] = b0;
    d[o + 11] = a0;
    d[o + 12] = r1;
    d[o + 13] = g1;
    d[o + 14] = b1;
    d[o + 15] = a1;
    this.count++;
  }

  private grow(): void {
    this.capacity *= 2;
    const next = new Float32Array(this.capacity * FLOATS);
    next.set(this.data);
    this.data = next;
    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.instanceBuf);
    gl.bufferData(gl.ARRAY_BUFFER, next.byteLength, gl.DYNAMIC_DRAW);
  }

  /** `gain` takes light into the scene's range (below 1 when the scene is 8-bit). */
  draw(view: Float32Array, pxPerUnit: number, minPx: number, gain = 1): void {
    if (this.count === 0 || !this.program) return;
    const gl = this.gl;
    this.program.use();
    gl.uniform4fv(this.program.loc('uView'), view);
    this.program.f1('uPxPerUnit', pxPerUnit).f1('uMinPx', minPx).f1('uGain', gain);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.instanceBuf);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.data, 0, this.count * FLOATS);
    gl.blendFunc(gl.ONE, gl.ONE);
    gl.bindVertexArray(this.vao);
    gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, this.count);
    gl.bindVertexArray(null);
  }

  clear(): void {
    this.count = 0;
  }

  dispose(): void {
    const gl = this.gl;
    gl.deleteVertexArray(this.vao);
    gl.deleteBuffer(this.instanceBuf);
    gl.deleteBuffer(this.cornerBuf);
  }
}

/** The line program, or null when the driver rejects it (lines are then left out). */
export function createLineProgram(gl: WebGL2RenderingContext): Program | null {
  return tryProgram(gl, VS, FS, 'lines');
}
