/**
 * Any length in plain words, measured in things a player can picture: "half a proton’s width",
 * "seven protons side by side", "a hundred thousand atoms side by side", "fifty thousand light-years".
 * The scale bar counts in these while the camera draws back between eras, so they cover every scale
 * the game reaches, from inside a proton to the observable universe.
 */

interface Measure {
  /** Its size in meters. */
  m: number;
  /** One of it: "a proton’s width". */
  one: string;
  /** Said after a number: "protons side by side". */
  many: string;
}

/** Smallest first. Each takes over from the one before once a length is at least 0.7 of it. */
const MEASURES: readonly Measure[] = [
  // Twice the proton's charge radius, 0.84 femtometers.
  { m: 1.7e-15, one: 'a proton’s width', many: 'protons side by side' },
  // A hydrogen atom, about a tenth of a nanometer across.
  { m: 1.1e-10, one: 'an atom’s width', many: 'atoms side by side' },
  { m: 1e-4, one: 'a hair’s width', many: 'hairs side by side' },
  { m: 1.7, one: 'a person’s height', many: 'people head to toe' },
  { m: 1.27e7, one: 'the Earth’s width', many: 'Earths side by side' },
  { m: 1.39e9, one: 'the Sun’s width', many: 'Suns side by side' },
  { m: 1.5e11, one: 'the distance from the Earth to the Sun', many: 'times the distance from the Earth to the Sun' },
  { m: 9.46e15, one: 'a light-year', many: 'light-years' },
  { m: 8.8e26, one: 'the width of the observable universe', many: 'times the width of the observable universe' },
];

/** Below a whole proton: the nearest of these fractions (by ratio). */
const FRACTIONS: [ratio: number, words: string][] = [
  [0.001, 'a thousandth of a proton’s width'],
  [0.01, 'a hundredth of a proton’s width'],
  [0.1, 'a tenth of a proton’s width'],
  [0.25, 'a quarter of a proton’s width'],
  [0.5, 'half a proton’s width'],
];

const ONES = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'];
const TENS = ['', 'ten', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
const GROUPS = ['', 'thousand', 'million', 'billion', 'trillion'];

/** A count in words: exact up to ten, then to one figure ("sixty", "a hundred thousand"). */
function count(n: number): string | null {
  if (n < 10.5) return Math.round(n) === 10 ? 'ten' : ONES[Math.round(n)];
  let k = Math.floor(Math.log10(n));
  let d = Math.round(n / 10 ** k);
  if (d === 10) {
    d = 1;
    k++;
  }
  const group = GROUPS[Math.floor(k / 3)];
  if (group === undefined) return null;
  const tail = group ? ` ${group}` : '';
  const a = d === 1 ? 'a' : ONES[d];
  switch (k % 3) {
    case 0:
      return group ? `${a}${tail}` : ONES[d];
    case 1:
      return `${TENS[d]}${tail}`;
    default:
      return `${a} hundred${tail}`;
  }
}

/** A length in plain words, or null for one too small to put into words. */
export function lengthInWords(meters: number): string | null {
  if (!(meters > 0) || !Number.isFinite(meters)) return null;
  let i = 0;
  while (i + 1 < MEASURES.length && meters >= MEASURES[i + 1].m * Math.SQRT1_2) i++;
  const M = MEASURES[i];
  const r = meters / M.m;
  if (r < Math.SQRT1_2) {
    // Only the smallest measure is ever split.
    if (r < Math.sqrt(0.1) * FRACTIONS[0][0]) return null;
    for (let f = 0; f < FRACTIONS.length - 1; f++) if (r < Math.sqrt(FRACTIONS[f][0] * FRACTIONS[f + 1][0])) return FRACTIONS[f][1];
    return FRACTIONS[FRACTIONS.length - 1][1];
  }
  if (r < 1.5) return M.one;
  const n = count(r);
  return n && `${n} ${M.many}`;
}
