<!--
  The title card when a new era begins: the era's name and the cosmic time, nothing else. In an era
  seen through the frame the name is shown in the frame's time caption instead; the card's timer runs
  either way.
-->
<script lang="ts">
  import Num from '../common/Num.svelte';
  import { frameEra } from '../frame/eras';
  import { game, track, ui } from '../store.svelte';

  const g = game();
  const framed = $derived.by(() => {
    track();
    return frameEra(g.state.run.era) !== null;
  });

  $effect(() => {
    const card = ui.eraCard;
    if (!card) return;
    const t = setTimeout(() => {
      if (ui.eraCard?.key === card.key) ui.eraCard = null;
    }, 5600);
    return () => clearTimeout(t);
  });
</script>

{#if ui.eraCard && !framed}
  {#key ui.eraCard.key}
    <div class="card">
      <div class="label epoch">{ui.eraCard.epoch}</div>
      <h2 class="title">{ui.eraCard.title}</h2>
      <span class="rule" aria-hidden="true"></span>
      <div class="time"><Num parts={ui.eraCard.time} /></div>
    </div>
  {/key}
{/if}

<style>
  .card {
    position: fixed;
    left: 50%;
    top: 40%;
    translate: -50% -50%;
    text-align: center;
    pointer-events: none;
    animation: card 5.6s var(--ease) both;
    text-shadow: 0 0 30px rgb(0 0 0 / 0.9);
  }
  /* Opacity and transform only: no per-frame layout or blur over the scene. */
  @keyframes card {
    0% {
      opacity: 0;
      transform: translateY(calc(8px * var(--motion))) scale(calc(1 - 0.015 * var(--motion)));
    }
    22% {
      opacity: 1;
      transform: none;
    }
    74% {
      opacity: 1;
      transform: none;
    }
    100% {
      opacity: 0;
      transform: translateY(calc(-4px * var(--motion)));
    }
  }
  .rule {
    display: block;
    width: 2.5rem;
    height: 1px;
    margin: 1.1rem auto 0.9rem;
    background: var(--accent);
    box-shadow: 0 0 10px var(--accent-soft);
    animation: rule 5.6s var(--ease) both;
  }
  @keyframes rule {
    0%,
    12% {
      transform: scaleX(0);
    }
    40%,
    100% {
      transform: scaleX(1);
    }
  }
  .title {
    margin: 0.7rem 0 0;
    font-family: var(--serif);
    font-weight: 400;
    font-size: 4.4rem;
    line-height: 1;
    letter-spacing: -0.005em;
    color: var(--ink);
  }
  .epoch {
    color: var(--ink-2);
    letter-spacing: 0.32em;
    margin-right: -0.32em;
  }
  .time {
    font-size: 1rem;
    color: var(--ink-2);
  }
</style>
