<!--
  A universe's numbers as a compact strip (Rees' six), with arrows against a parent's when given.
  The two rarely-changing laws show only when they differ from ours.
-->
<script lang="ts">
  import { OUR_CONSTANTS, type Constants } from '../../core/state';

  let { c, parent = null }: { c: Constants; parent?: Constants | null } = $props();

  const MINUS = '−';
  const signed = (x: number, d: number) => (x < 0 ? MINUS : '') + Math.abs(x).toFixed(d);
  const trim = (x: number, d: number) => (Number.isInteger(x) ? String(Math.abs(x)) : Math.abs(x).toFixed(d));

  const cells = $derived([
    { k: 'N', tip: 'How much stronger the electric force is than gravity (between two protons)', pow: true, v: trim(c.logN, 1), neg: c.logN < 0, d: parent ? c.logN - parent.logN : 0 },
    { k: 'ε', tip: 'Share of mass turned to energy when hydrogen fuses to helium', pow: false, v: c.epsilon.toFixed(4), neg: false, d: parent ? c.epsilon - parent.epsilon : 0 },
    { k: 'Ω', tip: 'Amount of matter, relative to the critical density', pow: false, v: c.omega.toFixed(2), neg: false, d: parent ? c.omega - parent.omega : 0 },
    { k: 'λ', tip: 'Amount of dark energy, relative to the critical density', pow: false, v: signed(c.lambda, 2), neg: false, d: parent ? c.lambda - parent.lambda : 0 },
    { k: 'Q', tip: 'Strength of the ripples left by inflation', pow: true, v: trim(c.logQ, 1), neg: c.logQ < 0, d: parent ? c.logQ - parent.logQ : 0 },
    { k: 'D', tip: "Dimensions of space. Some things you don't get to change.", pow: false, v: '3', neg: false, d: 0 },
  ]);
  const w = $derived(c.w !== OUR_CONSTANTS.w ? signed(c.w, 2) : null);
  const vacuum = $derived(c.logVacuum !== OUR_CONSTANTS.logVacuum ? Math.round(c.logVacuum) : null);
</script>

<div class="wrap">
  <div class="strip">
    {#each cells as cell (cell.k)}
      <div class="cell" title={cell.tip}>
        <span class="k">{cell.k}</span>
        <span class="v">
          {#if cell.pow}10<sup>{cell.neg ? MINUS : ''}{cell.v}</sup>{:else}{cell.v}{/if}
          {#if Math.abs(cell.d) > 1e-9}<span class="d" class:up={cell.d > 0}>{cell.d > 0 ? '↑' : '↓'}</span>{/if}
        </span>
      </div>
    {/each}
  </div>
  {#if w !== null || vacuum !== null}
    <div class="odd">
      {#if w !== null}<span title="Dark energy's equation of state (−1 for a cosmological constant)">w {w}</span>{/if}
      {#if w !== null && vacuum !== null}<span> · </span>{/if}
      {#if vacuum !== null}<span title="How long the vacuum lasts before it decays">vacuum 10<sup>{vacuum}</sup> yr</span>{/if}
    </div>
  {/if}
</div>

<style>
  .wrap {
    container-type: inline-size;
  }
  .strip {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
  }
  .cell {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.15rem;
    padding: 0.45rem 0.1rem 0.5rem;
    border-left: 1px solid var(--line);
    cursor: help;
  }
  .cell:first-child {
    border-left: none;
  }
  .k {
    font-family: var(--serif);
    font-style: italic;
    font-size: 0.95rem;
    color: var(--ink-3);
  }
  .v {
    font-family: var(--mono);
    font-size: 0.74rem;
    color: var(--ink);
    white-space: nowrap;
  }
  sup {
    font-size: 0.7em;
    vertical-align: 0.5em;
    line-height: 0;
  }
  .d {
    margin-left: 0.18rem;
    color: var(--ink-3);
  }
  .d.up {
    color: var(--accent);
  }
  /* A narrow card: the six numbers in two rows of three, so none of them overlap. */
  @container (max-width: 17rem) {
    .strip {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .cell:nth-child(4) {
      border-left: none;
    }
    .cell:nth-child(n + 4) {
      border-top: 1px solid var(--line);
    }
    .v {
      font-size: 0.7rem;
    }
  }
  .odd {
    margin-top: 0.4rem;
    font-family: var(--mono);
    font-size: 0.66rem;
    color: var(--accent);
    text-align: center;
  }
</style>
