/**
 * Prologue: Inflation.
 *
 * A single point of light: a patch of space far smaller than a proton. Hold, and it inflates: the
 * e-fold count accelerates toward 60 (a growth factor of e⁶⁰ ≈ 10²⁶, roughly what's needed to explain
 * how flat and even our universe is), and the point grows into a sphere of light while space streams
 * away around it, surging at every tenth e-fold. Let go early and it settles back, no penalty. At 60 it
 * is larger than everything in view: you are inside it, and its energy floods out as a hot plasma
 * (reheating). The point of light is the universe.
 */
import type { EraDef, EraModule, PointerInfo, WorldLabel } from '../../core/era';
import type { Game } from '../../core/game';
import type { RGB } from '../../render/color';
import type { BackgroundDef, Renderer } from '../../render/renderer';
import { Shape } from '../../render/sprites';
import { Storm, type StormKick, type StormLight } from '../../render/storm';
import { bell, noise, swell, thump, riser } from '../../audio/patches';
import { SCALES, mtof } from '../../audio/scales';
import type { EraAudio, EraSound } from '../../audio/director';
import type { SampleVoice } from '../../audio/samples';
import { Patch } from './patch';

const TARGET_EFOLDS = 60;

/** The grade the version 2 look is lit for (shared with the Soup, so reheating hands over seamlessly). */
const GRADE = { bloom: 0.25, bloomThreshold: 1.4, glare: 0.35, glareThreshold: 3, saturation: 1.25, punch: 1.2, vignette: 0.5, grain: 0.012 };

/** The patch at rest (world units): a point. */
const POINT = 2.4;

let stopRiser: ((fade?: number) => void) | null = null;

/** Seconds of holding it takes to inflate from 0 to `n` e-folds (the dynamics in update()). */
const timeTo = (n: number) => Math.log(1 + (n * 0.28) / 3) / 0.28;
let inflating: SampleVoice | null = null;

/**
 * The Prologue in rendered sound: the void (a point of light, the faint sky, falling whistlers) loops
 * while nothing happens. Holding plays inflation from the point matching the e-folds already gained
 * (the stem runs on the same clock and peaks at 60); letting go fades it as space relaxes. Reheating
 * cuts it dead and strikes the first chord; the Soup's bed waits under its ring.
 */
const sound: EraSound = {
  // At 1 the void plays near −31 LUFS in the game, 4–5 dB under the Soup's bed: faint, as meant
  // (measured with tools/scenarios/opening-mix.ts; at 2 it came out louder than the Soup's bed).
  stems: { id: 'prologue', names: ['prologue-void'], loop: 48, layers: () => [1] },
  load: ['prologue-inflation', 'prologue-reheating', ...[0, 1, 2, 3, 4, 5].map((k) => `sfx-combo-${k}`)],
  cues: {
    'prologue.hold': (s, p) => {
      s.stop(inflating, 0.06);
      inflating = s.play('prologue-inflation', { bus: 'music', offset: timeTo(p.intensity ?? 0), fadeIn: 0.1 });
      s.duck(0.5, 1);
    },
    'prologue.release': (s) => {
      s.stop(inflating, 0.9);
      inflating = null;
      s.duck(1, 2.5);
    },
    'prologue.efold': (s, p) => {
      const g = s.admit('prologue.efold', 0.08);
      // At 0.35 the marks sat 10 dB under the rising inflation (peaks 7 dB under): masked.
      if (g) s.play(`sfx-combo-${Math.max(0, Math.min(5, (p.intensity ?? 1) - 1))}`, { gain: 0.5 * g });
    },
    'prologue.reheat': (s) => {
      // The reheating file opens on 34 ms of silence and its strike takes a few tens of ms to build:
      // played from the top under a 15 ms cut, that left a 50 ms, 15 dB hole at the climax. It starts
      // at its onset now, and inflation's cut lasts as long as the strike's attack.
      s.stop(inflating, 0.06);
      inflating = null;
      s.play('prologue-reheating', { bus: 'music', gain: 1, offset: 0.03 });
      s.handover(1.5, 7);
    },
    // Nothing is for sale here: no purchase sounds to hold.
    'ui.buy': () => {},
  },
};

const audio: EraAudio = {
  key: { root: 48, scale: SCALES.lydian },
  bed: {
    id: 'prologue',
    chords: [[36, 43]],
    chordSeconds: 60,
    pad: { gain: 0.07, type: 'triangle', cutoff: 600, detune: 4, lfo: 0.03 },
    air: { freq: 220, q: 0.9, gain: 0.012, drift: 0.02 },
    level: 1.12,
  },
  cues: {
    'prologue.hold': (a) => {
      stopRiser?.(0.15);
      stopRiser = riser(a, { base: 41.2, seconds: 7.5, gain: 0.2 });
    },
    'prologue.release': () => {
      stopRiser?.(0.9);
      stopRiser = null;
    },
    'prologue.efold': (a, p) => {
      const g = a.admit('prologue.efold', 0.08);
      if (!g) return;
      bell(a, mtof(72 + Math.round((p.intensity ?? 0) * 2)), { gain: 0.035 * g, decay: 0.9, ratio: 2, bright: 0.5 });
    },
    'prologue.reheat': (a) => {
      stopRiser?.(0.08);
      stopRiser = null;
      const t = a.now;
      thump(a, 38, { time: t, gain: 0.55, dur: 1.8 });
      noise(a, { time: t, dur: 3.5, freq: 6000, to: 400, q: 0.5, gain: 0.16, attack: 0.005 });
      swell(a, [mtof(48), mtof(55), mtof(64), mtof(71), mtof(78)], { time: t + 0.25, attack: 1.4, hold: 1.2, release: 5, gain: 0.22, cutoff: 3200 });
    },
  },
  sound,
};

class Prologue implements EraModule {
  /** The patch that inflates: a point, then a sphere of light growing past the edges of the screen. */
  private readonly patch = new Patch();
  /**
   * Space around it, as specks of the vacuum in depth: still and faint while nothing happens; holding,
   * streaming away on inflation's own accelerating clock (the faster, the longer their streaks), lit
   * and thrown outward by the fronts the patch sends off its limb. GPU particles.
   */
  private readonly storm = new Storm({
    count: 7000,
    depth: 900,
    focal: 1600,
    lifeMin: 2,
    lifeMax: 6,
    swirl: 0,
    drag: 2.5,
    jitter: 1.5,
    spread: 0.004,
    faintest: 0.022,
    peak: 9,
    magnitudePower: 1,
    halo: 0,
    twinkle: 0.5,
    streak: 0,
    streakFrom: 0.5,
    palette: [
      [0.85, 0.9, 1.0],
      [0.66, 0.78, 1.0],
      [1.0, 0.92, 0.8],
      [0.75, 0.7, 1.0],
      [0.9, 0.95, 1.0],
      [0.66, 0.78, 1.0],
      [1.0, 1.0, 1.05],
      [0.85, 0.9, 1.0],
    ],
    weights: [3, 2, 0.6, 0.6, 1, 1, 1, 1],
  });
  /** How brightly space itself glows (linear HDR): black while it inflates, white-hot at reheating. */
  private glow = 0;
  /** Behind everything: one colour, flooding white at reheating wherever the patch doesn't yet cover. */
  private readonly medium: BackgroundDef = {
    id: 'prologue-v4',
    fragment: /* glsl */ `
uniform float uGlow;
void main() {
  outColor = vec4(vec3(0.96, 0.98, 1.0) * uGlow, 1.0);
}`,
    uniforms: (p) => p.f1('uGlow', this.glow),
  };
  private saved: Record<string, number> = {};
  private efolds = 0;
  private holding = false;
  private idle = 0;
  private ended = false;
  private reheat = -1;
  private lastMark = 0;
  private halfW = 900;
  private halfH = 500;
  private t = 0;
  /** Seconds of the closing beat left, and what to call when it is over. */
  private closing = -1;
  private closed: (() => void) | null = null;
  /**
   * Visual only: fronts racing outward from the patch's limb, lighting and throwing the specks they
   * cross (radius and strength): a faint one each e-fold, a strong one each tenth.
   */
  private ripples: { r: number; b: number }[] = [];
  private lastRipple = 0;
  private lastTenth = 0;
  private rippleCd = 0;
  /** Seconds since the last tenth e-fold's surge, and how strong it was. */
  private surgeAge = 99;
  private surgeStrength = 0;
  /** The patch's drawn radius (world units), eased so letting go settles it back smoothly. */
  private radius = POINT;

  constructor(private readonly g: Game) {}

  /** E-folds gained so far (all 60 once inflation has ended). */
  get folds(): number {
    return this.ended ? TARGET_EFOLDS : this.efolds;
  }

  /**
   * The patch's radius at N e-folds. Space really grows by e every e-fold, faster and faster; the screen
   * can show only a few hundredfold of it. So the sphere grows by the same factor every second of
   * holding (about 2.5×), from the first moment until it passes the screen's corners near 58 e-folds,
   * and the tenth e-folds' surges, coming quicker and quicker, carry the acceleration. A function of N
   * alone, so letting go runs it back.
   */
  private radiusAt(N: number): number {
    const reach = Math.hypot(this.halfW, this.halfH) * 1.02;
    return POINT * Math.exp((timeTo(N) / timeTo(58)) * Math.log(reach / POINT));
  }

  enter(): void {
    const r = this.g.renderer;
    if (!r) return;
    r.setBackground(this.medium);
    r.setLayers([this.storm, this.patch]);
    const post = r.post as unknown as Record<string, number>;
    for (const [k, v] of Object.entries(GRADE)) {
      this.saved[k] = post[k];
      post[k] = v;
    }
  }

  exit(): void {
    const r = this.g.renderer;
    if (!r) return;
    r.setLayers([]);
    Object.assign(r.post, this.saved);
  }

  resize(halfW: number, halfH: number): void {
    this.halfW = halfW;
    this.halfH = halfH;
  }

  update(dt: number): void {
    this.t += dt;
    if (this.closing >= 0) {
      this.closing -= dt;
      if (this.closing < 0) this.closed?.();
    }
    if (this.ended) return;
    const N = this.efolds;
    if (this.holding) {
      this.idle = 0;
      this.efolds = Math.min(TARGET_EFOLDS, N + (3 + 0.28 * N) * dt);
      const mark = Math.floor(this.efolds / 10);
      if (mark > this.lastMark) {
        this.lastMark = mark;
        this.g.sfx('prologue.efold', 0, mark);
      }
      this.g.renderer?.camera.addTrauma(dt * (0.02 + this.efolds / 600) * 0.6);
      if (this.efolds >= TARGET_EFOLDS) this.finish();
    } else {
      this.idle += dt;
      this.efolds = Math.max(0, N - Math.max(8, N * 0.8) * dt);
      this.lastMark = Math.floor(this.efolds / 10);
    }
  }

  skip(): boolean {
    if (this.ended) return false;
    this.efolds = TARGET_EFOLDS;
    this.finish();
    return true;
  }

  private finish(): void {
    this.ended = true;
    this.holding = false;
    this.reheat = 0;
    this.g.sfx('prologue.reheat');
    const r = this.g.renderer;
    if (r) {
      r.addFlash(0.6);
      r.addAberration(0.008);
      r.camera.addTrauma(0.55);
    }
    this.g.advance();
  }

  render(r: Renderer, dt: number): void {
    if (this.reheat >= 0) this.reheat += dt;
    const N = this.folds;
    const k = N / TARGET_EFOLDS;
    const breathe = 0.5 + 0.5 * Math.sin(this.t * 1.7);
    const calm = r.reduceFlashes ? 0.4 : 1;

    // Every tenth e-fold the patch surges (a quick swell that settles) and sends a strong front off its
    // limb; every e-fold a faint one.
    if (!this.ended) {
      this.rippleCd -= dt;
      const whole = Math.floor(N);
      const tenth = Math.floor(N / 10);
      if (tenth > this.lastTenth) {
        this.lastRipple = whole;
        this.rippleCd = 0.07;
        this.surgeAge = 0;
        this.surgeStrength = 0.6 + 0.08 * tenth;
        this.ripples.push({ r: this.radius, b: 1.4 + k });
      } else if (whole > this.lastRipple && this.rippleCd <= 0) {
        this.lastRipple = whole;
        this.rippleCd = 0.07;
        if (this.ripples.length < 24) this.ripples.push({ r: this.radius, b: 0.22 + k * 0.3 });
      }
      if (whole < this.lastRipple) this.lastRipple = whole;
      this.lastTenth = tenth;
    }
    this.surgeAge += dt;
    const a = this.surgeAge;
    const surge = a < 4 ? this.surgeStrength * (1 - Math.exp(-a * 14)) * Math.exp(-a * 2.2) : 0;

    // The patch: a point at rest, breathing; holding, a sphere of light growing by e every few e-folds.
    const target = this.radiusAt(N) * (1 + 0.28 * surge * calm) * (1 + 0.06 * breathe * (1 - k));
    this.radius += (target - this.radius) * (1 - Math.exp(-dt * 18));
    const R = this.radius;
    const reach = Math.hypot(this.halfW, this.halfH);
    const p = this.patch;
    p.radius = R;
    p.horizon = 5;
    p.surge = surge * calm;
    // Its light swells as it engulfs the view.
    p.bright = 1.1 + 0.8 * Math.max(0, Math.min(1, (R / reach - 0.45) / 0.55)) ** 2;
    p.halo = 0.5 + 0.6 * k;

    // Fronts race outward from the limb, faster as inflation runs away.
    const speed = this.ended ? 4200 : N * N * 0.9 + N * 6;
    const fronts: { r: number; b: number }[] = [];
    for (let n = this.ripples.length - 1; n >= 0; n--) {
      const rp = this.ripples[n];
      rp.r += (220 + speed * 1.4 + (rp.r - R) * 0.8) * dt;
      const f = 1 - (rp.r - R) / Math.max(1, reach - R);
      if (f <= 0 || rp.r > reach * 1.2) {
        this.ripples.splice(n, 1);
        continue;
      }
      fronts.push({ r: rp.r, b: rp.b * f * f });
    }
    // Not drawn rings: the specks a front crosses light up and are thrown outward.
    fronts.sort((x, y) => y.b - x.b);
    const kicks: StormKick[] = fronts.slice(0, 4).map((fr) => ({ x: 0, y: 0, radius: fr.r, push: 1400 * fr.b }));
    const lights: StormLight[] = fronts.slice(0, 7).map((fr) => ({ x: 0, y: 0, intensity: 4 * fr.b, radius: fr.r, width: 18 + fr.r * 0.04 }));

    // Space around it: a sparse field of faint specks at rest; holding, it streams away from the patch on
    // inflation's own clock, its streaks lengthening with the speed.
    const c = this.storm.config;
    c.spread = this.ended ? 0.03 : 0.004 + 0.0016 * N * N;
    c.streak = this.ended ? 0.06 : 0.11 * Math.min(1, k * 1.4);
    c.faintest = this.ended ? 0.3 + 6 * this.reheat : 0.022 + 0.05 * k + 0.12 * k * k;
    if (!this.ended) lights.push({ x: 0, y: 0, intensity: (0.5 + 9 * k) * (0.75 + 0.5 * breathe), radius: R + 70 + 160 * k, width: 0 });
    this.storm.kicks = kicks;
    this.storm.lights = lights;

    if (!this.ended) {
      // While it is still a point, its light is a point spread (white-hot core and glow); it hands over
      // to the sphere as the sphere outgrows a few pixels. Glare once it is bright.
      const small = 1 - Math.min(1, Math.max(0, (R - 4) / 10));
      if (small > 0) {
        const inten = (6 + 22 * k + breathe * 1.6) * small;
        r.top.push(0, 0, 2.2 + 2.4 * k, inten, inten, inten * 1.05, 1, Shape.Glow);
        r.top.push(0, 0, 10 + 30 * k, 0.22 * inten * 0.7, 0.22 * inten * 0.8, 0.22 * inten, 1, Shape.Glow);
      }
      // Lens glare belongs to the bright point; the sphere's own limb takes over as it grows.
      const glare = k * (1 - Math.min(1, Math.max(0, (R - 12) / 40)));
      if (glare > 0.02) r.top.push(0, 0, 60 + 160 * k, 0.5 * glare, 0.55 * glare, 0.65 * glare, 1, Shape.Star, 1);
    } else {
      // Reheating: inflation's energy becomes heat everywhere at once. The frozen pattern on the face
      // that now fills the screen burns from violet through rose to white, hot spots first, and floods.
      const t = this.reheat;
      p.heat = (r.reduceFlashes ? 0.85 : 1.4) * Math.pow(Math.min(1, t / 0.3), 1.15);
      const fill = Math.min(1, Math.max(0, (t - 0.18) * 3));
      p.white = fill * fill * (r.reduceFlashes ? 0.25 : 1);
      p.surge = 0;
      this.glow = (r.reduceFlashes ? 1.4 : 7) * fill * fill;
      r.post.vignette = 0.5 * (1 - fill);
    }
  }

  pointer(e: PointerInfo): void {
    if (this.ended || !e.primary) return;
    if (e.type === 'down') {
      this.holding = true;
      this.g.sfx('prologue.hold', 0, this.efolds);
    } else if (e.type === 'up' || e.type === 'cancel') {
      if (this.holding) this.g.sfx('prologue.release');
      this.holding = false;
    }
  }

  onStep(): void {}

  stocks() {
    return [];
  }

  offline() {
    return { lines: [] };
  }

  finale(): Promise<void> {
    // Long enough for the light to burn white (on game time, so it waits while the game is paused);
    // the Soup takes it from there.
    return new Promise((resolve) => {
      this.closing = 0.6;
      this.closed = resolve;
    });
  }

  accent(): RGB {
    return [0.85, 0.9, 1];
  }

  hint(): string | null {
    return null;
  }

  hudHidden(): boolean {
    return true;
  }

  labels(): WorldLabel[] {
    const out: WorldLabel[] = [];
    const showHold = !this.holding && !this.ended && this.efolds < 1;
    if (showHold) {
      const fade = Math.min(1, Math.max(0, (this.idle - 3) / 1.5));
      if (fade > 0) out.push({ id: 'hold', x: 0, y: 70, text: 'Hold', tone: 'hint', opacity: fade });
    }
    // The count sits under the sphere while it fits on the screen; once you are inside, it is gone.
    const y = Math.max(74, this.radius + 36);
    if (this.efolds >= 0.5 && !this.ended && y < this.halfH - 24) {
      out.push({ id: 'efolds', x: 0, y, text: `${Math.floor(this.efolds)} e-folds`, tone: 'value' });
    }
    return out;
  }
}

export const prologue: EraDef = {
  id: 'prologue',
  title: 'Inflation',
  epoch: 'Before the hot Big Bang',
  steps: [
    {
      t: 1e-36,
      T: 1e27,
      label: 'Inflation',
      history: 'In the leading theory, a patch of false vacuum far smaller than a proton begins to inflate.',
      cost: 0,
    },
    {
      t: 1e-32,
      T: 1e27,
      label: 'Reheating',
      history: 'After 60 e-folds, inflation ends. Its energy pours out as a hot plasma of particles.',
      cost: 0,
      goal: (g) => ({
        text: `Hold to inflate the point to ${TARGET_EFOLDS} e-folds`,
        detail: 'Each e-fold makes it 2.7 times wider. Let go and it settles back.',
        progress: (g.era instanceof Prologue ? g.era.folds : 0) / TARGET_EFOLDS,
      }),
    },
  ],
  phenomena: [],
  stats: [],
  codex: [],
  audio,
  create: (g) => new Prologue(g),
};
