/**
 * The neutral gas of the Dark Ages, as a medium the eye reads mostly by how it moves. Rays march
 * through a slab around the game plane (at reduced resolution, averaged over frames). Where the gas is
 * comes from the simulation: its parcels and clumps are splatted on the CPU into a density field that
 * a few boiling octaves of baked noise break up in depth, so the mist slides into the dark-matter
 * wells and toward the hand exactly as the parcels do. It has almost no light of its own: a faint
 * cold grey, the afterglow while it lasts, the heat of compressed clumps glowing from inside, and
 * whatever shines in it (stars, flashes, light fronts racing through).
 *
 * Ionized bubbles are spheres carved out of it, centred in the plane: inside, the gas glows faintly
 * (blue-violet near its stars, magenta, pink-red toward the edge), and the ionization front burns
 * where the starlight eats into neutral gas. Seen through, a thin spherical front is brightest at its
 * limb, so each bubble shows a crisp bright rim round a softly lit body.
 *
 * The layer is also the flow the particle storm rides (velocity and light, built by the look over the
 * current view), so the specks stream with the gas and glint where it is lit.
 */
import { FULLSCREEN_VS, Program, Target, drawFullscreen, type GLCaps } from '../../render/gl';
import { HEADER } from '../../render/glsl';
import { NOISE_SIZE, noiseVolume } from '../../render/noise3d';
import type { LayerFrame, RenderLayer } from '../../render/renderer';
import type { FlowSource } from '../../render/storm';
import type { VolumeFront, VolumeLight } from '../../render/volume';

export interface MediumConfig {
  /** Resolution relative to the scene, and steps per ray. */
  scale: number;
  steps: number;
  /** How far behind the plane the slab reaches, how far in front of it it starts, the camera distance. */
  depth: number;
  near: number;
  focal: number;
  /** Half-thickness (gaussian sigma) of the layer the simulation's gas lives in (world units). */
  thick: number;
  /** World units per noise tile, tiles per second of boiling, warp amount. */
  noiseScale: number;
  boil: number;
  warp: number;
  /** World units per tile of the threads carried along the flow, and seconds before a copy is renewed. */
  detail: number;
  period: number;
  /** Density of the simulation's gas per unit of the field, and of the faint gas everywhere else. */
  density: number;
  far: number;
  /** Absorption per unit density (neutral gas only: ionized gas is clear). */
  absorb: number;
}

export function defaultMedium(): MediumConfig {
  return { scale: 0.5, steps: 30, depth: 700, near: 420, focal: 1600, thick: 110, noiseScale: 760, boil: 0.006, warp: 0.75, detail: 330, period: 3, density: 15, far: 0.025, absorb: 0.0042 };
}

/** The per-frame light the medium is graded with (linear colours). */
export interface MediumLight {
  /** The neutral gas's own faint light, per unit density. */
  ambient: [number, number, number];
  /** The afterglow lighting the gas. */
  glow: [number, number, number];
  /** Gain on the clumps' heat glow, on the ionized gas and its fronts. */
  heat: number;
  ion: number;
  /** 0 → 1: the last neutral gas clears (the finale). */
  clear: number;
}

/** Field sizes: gas (density, heat glow, glow × temperature, enriched density) and ionization. */
export const FIELD_W = 192;
export const FIELD_H = 112;
export const ION_W = 128;
export const ION_H = 76;
/** The flow the storm rides, over the current view. */
export const FLOW_W = 64;
export const FLOW_H = 36;

const MARCH_FS = HEADER + /* glsl */ `
precision highp sampler3D;
in vec2 vUv;
out vec4 outColor;
uniform sampler3D uNoise;
uniform sampler2D uField;
uniform sampler2D uIon;
uniform sampler2D uFlow;
uniform vec2 uFlowScale;
uniform float uPeriod;
uniform float uDetail;
uniform vec4 uRect;
uniform vec4 uView;
uniform float uFocal;
uniform float uDepth;
uniform float uNear;
uniform float uThick;
uniform float uTime;
uniform int uSteps;
uniform float uScale;
uniform float uBoil;
uniform float uWarp;
uniform float uDensity;
uniform float uFar;
uniform float uAbsorb;
uniform float uFrame;
uniform vec3 uAmbient;
uniform vec3 uGlow;
uniform float uHeat;
uniform float uIonGain;
uniform float uClear;
uniform vec4 uLight[8];
uniform vec3 uLightCol[8];
uniform int uLightCount;
uniform vec4 uFront[8];
uniform vec3 uFrontCol[8];
uniform int uFrontCount;

/** Path length (world units) through which a unit of density shows its gains at full brightness. */
const float COLUMN = 220.0;

float N(vec3 p) { return texture(uNoise, p).r; }

/** Interleaved gradient noise (Jimenez 2014): a spatially even jitter that converges fast over frames. */
float ign(vec2 p) { return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715)))); }

/** Heat glow by how hot a clump runs: a dull red, orange, then gold. */
vec3 heatColor(float t) {
  vec3 c = mix(vec3(0.6, 0.06, 0.02), vec3(1.0, 0.3, 0.06), smoothstep(0.0, 0.5, t));
  return mix(c, vec3(1.0, 0.66, 0.3), smoothstep(0.45, 1.0, t));
}

void main() {
  vec2 ndc = vUv * 2.0 - 1.0;
  vec3 onPlane = vec3(uView.x + ndc.x * uView.z, uView.y - ndc.y * uView.w, 0.0);
  vec3 cam = vec3(uView.xy, -uFocal);
  vec3 dir = normalize(onPlane - cam);
  float t0 = (-uNear - cam.z) / dir.z;
  float t1 = (uDepth - cam.z) / dir.z;
  float stepLen = (t1 - t0) / float(uSteps);
  float t = t0 + stepLen * fract(ign(gl_FragCoord.xy) + uFrame * 0.6180339887);
  vec2 ext = uRect.zw - uRect.xy;
  float tb = uTime * uBoil;
  // Flow-map phases: copy A carried for phA of a period, copy B half a period out of step.
  float phA = fract(uTime / uPeriod);
  float phB = fract(phA + 0.5);
  float wA = 1.0 - abs(2.0 * phA - 1.0);
  vec3 L = vec3(0.0);
  float T = 1.0;
  for (int i = 0; i < 96; i++) {
    if (i >= uSteps || T < 0.02) break;
    vec3 p = cam + dir * t;
    vec2 fuv = (p.xy - uRect.xy) / ext;
    // Outside the field there is only the faint gas everywhere.
    float within = step(0.0, fuv.x) * step(fuv.x, 1.0) * step(0.0, fuv.y) * step(fuv.y, 1.0);
    vec4 F = texture(uField, fuv) * within;
    vec4 I = texture(uIon, fuv);
    float layer = exp(-p.z * p.z / (2.0 * uThick * uThick));
    // Billows: boiling noise, warped.
    vec3 q = p / uScale;
    float w = N(q * 0.43 + vec3(0.17, 0.61, tb)) - 0.5;
    q += vec3(w, -w, 0.6 * w) * uWarp;
    float billow = smoothstep(0.3, 0.78, N(q + vec3(0.0, 0.0, tb * 0.5)));
    // Threads: finer ridged noise carried along the gas's own flow (two copies, each renewed while the
    // other is strongest), so the mist visibly streams where the gas moves: into the halos, to the hand.
    vec2 vuv = vec2((p.x - uView.x) / (2.0 * uView.z) + 0.5, 0.5 - (p.y - uView.y) / (2.0 * uView.w));
    vec2 vel = texture(uFlow, vuv).xy * uFlowScale * (0.25 + 0.75 * layer);
    vec3 qd = p / uDetail + vec3(w * 0.4, -w * 0.4, 0.0);
    float dA = N(qd - vec3(vel * phA * uPeriod / uDetail, 0.0) + vec3(0.37, 0.11, tb * 1.7));
    float dB = N(qd - vec3(vel * phB * uPeriod / uDetail, 0.0) + vec3(0.71, 0.53, tb * 1.7));
    float thread = mix(dB, dA, wA);
    // Thin ridges where the noise crosses its middle: threads, not blobs.
    thread = 1.0 - min(1.0, abs(2.0 * thread - 1.0) * 3.5);
    thread *= thread;
    float form = billow * (0.12 + 2.2 * thread) + 0.02;
    // The simulation's gas saturates softly (a clump is denser, not a hundred times brighter).
    float sim = F.r * uDensity;
    sim = sim / (1.0 + 0.35 * sim);
    float gas = (sim * layer + uFar) * form;

    // Ionized bubbles: spheres round their centres in the plane, from the signed distance in the plane.
    float sd = I.r;
    float R = I.g;
    float sd3 = R > 0.5 ? R - sqrt((R - sd) * (R - sd) + p.z * p.z) : sd;
    float inside = max(smoothstep(-4.0, 4.0, sd3), uClear);
    float neutral = gas * (1.0 - inside);
    float ionized = gas * inside;

    vec3 lit = vec3(0.0);
    for (int k = 0; k < 8; k++) {
      if (k >= uLightCount) break;
      vec3 dl = p - uLight[k].xyz;
      float r = uLight[k].w;
      float qq = 1.0 + dot(dl, dl) / (r * r);
      lit += uLightCol[k] / (qq * sqrt(qq));
    }
    for (int k = 0; k < 8; k++) {
      if (k >= uFrontCount) break;
      float x = (length(p - vec3(uFront[k].xy, 0.0)) - uFront[k].z) / uFront[k].w;
      lit += uFrontCol[k] * exp(-x * x);
    }

    // The clumps' heat: their own glow from inside, through their threads, coloured by how hot they run.
    float hg = F.g / (1.0 + 0.6 * F.g);
    float heat = hg * layer * (0.015 + 2.6 * thread * (0.4 + 0.6 * billow));
    vec3 hc = heatColor(F.b / max(F.g, 1e-5));
    // Gas enriched with the first metals keeps a faint warmer cast.
    float metal = clamp(F.a / max(F.r, 1e-4), 0.0, 1.0);
    vec3 own = uAmbient * mix(vec3(1.0), vec3(1.25, 1.05, 0.7), metal);

    // The ionized gas by depth into its sphere: blue-violet near the stars, magenta, pink-red outside.
    float rho = R > 0.5 ? clamp(1.0 - sd3 / R, 0.0, 1.0) : 1.0;
    vec3 body = mix(vec3(0.34, 0.3, 1.0), vec3(0.95, 0.2, 0.62), smoothstep(0.1, 0.65, rho));
    body = mix(body, vec3(1.0, 0.24, 0.34), smoothstep(0.65, 1.0, rho));
    float flux = I.b;
    // The front, where the starlight eats into neutral gas: brightest where that gas is dense, white-pink
    // while stars feed it, deepening to red as its stars go.
    float rim = exp(-sd3 * sd3 / 22.0) * (1.0 - uClear);
    vec3 rimCol = mix(vec3(0.85, 0.08, 0.16), vec3(1.0, 0.5, 0.68), clamp(flux, 0.0, 1.0));

    vec3 S = neutral * (own + uGlow + lit) + heat * hc * uHeat
      + ionized * (body * flux * uIonGain + lit * 0.7)
      + rim * (gas + 0.01) * rimCol * (0.25 + flux) * uIonGain * 18.0;
    // Gains are the brightness of a typical column of gas (unit density through the gas layer).
    L += T * S * (stepLen / COLUMN);
    T *= exp(-neutral * uAbsorb * stepLen);
    t += stepLen;
  }
  outColor = vec4(L, 1.0 - T);
}`;

/**
 * Folds this frame's march into the running average, reprojected with the camera at the depth most of
 * the light comes from, and kept inside the range of this frame's neighbourhood (what reprojection can't
 * follow, moving gas and racing fronts, doesn't smear).
 */
const ACCUM_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uCur;
uniform sampler2D uPrev;
uniform vec4 uView;
uniform vec4 uPrevView;
uniform float uBlend;
uniform vec2 uTexel;
out vec4 outColor;
void main() {
  vec4 cur = texture(uCur, vUv);
  vec2 ndc = vUv * 2.0 - 1.0;
  vec2 w = uView.xy + vec2(ndc.x, -ndc.y) * uView.zw;
  vec2 pn = (w - uPrevView.xy) / uPrevView.zw;
  vec2 puv = vec2(pn.x, -pn.y) * 0.5 + 0.5;
  if (uBlend >= 1.0 || any(lessThan(puv, vec2(0.0))) || any(greaterThan(puv, vec2(1.0)))) {
    outColor = cur;
    return;
  }
  vec4 lo = cur;
  vec4 hi = cur;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec4 n = texture(uCur, vUv + vec2(float(x), float(y)) * uTexel);
      lo = min(lo, n);
      hi = max(hi, n);
    }
  }
  outColor = mix(clamp(texture(uPrev, puv), lo, hi), cur, uBlend);
}`;

const COMPOSITE_FS = HEADER + /* glsl */ `
in vec2 vUv;
uniform sampler2D uSrc;
out vec4 outColor;
void main() { outColor = texture(uSrc, vUv); }`;

interface DataTexture {
  tex: WebGLTexture;
  version: number;
}

export class GasMedium implements RenderLayer, FlowSource {
  readonly stage = 'media' as const;
  config: MediumConfig;
  light: MediumLight = { ambient: [0, 0, 0], glow: [0, 0, 0], heat: 1, ion: 1, clear: 0 };
  /** Refilled by the look every frame. */
  lights: VolumeLight[] = [];
  fronts: VolumeFront[] = [];
  /** The world rectangle the gas and ionization fields cover: minX, minY, maxX, maxY. */
  readonly rect = new Float32Array([-1000, -600, 1000, 600]);
  /** Gas field (RGBA per texel) and ionization field (RGBA), written by the look; bump the versions. */
  readonly field = new Float32Array(FIELD_W * FIELD_H * 4);
  readonly ion = new Float32Array(ION_W * ION_H * 4);
  fieldVersion = 0;
  ionVersion = 0;
  /** The storm's flow over the current view: velocity (cells per second, y up) and light. */
  readonly flowVelocity = new Float32Array(FLOW_W * FLOW_H * 2);
  readonly flowLight = new Float32Array(FLOW_W * FLOW_H * 4);
  flowVersion = 0;
  private gl: WebGL2RenderingContext | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private march: Program | null = null;
  private accum: Program | null = null;
  private comp: Program | null = null;
  private noise: WebGLTexture | null = null;
  private fieldTex: DataTexture | null = null;
  private ionTex: DataTexture | null = null;
  private velTex: DataTexture | null = null;
  private lightTex: DataTexture | null = null;
  private target: Target | null = null;
  private history: [Target, Target] | null = null;
  private fresh = true;
  private prevView = new Float32Array(4);
  private frameNo = 0;
  private time = 0;
  private lightA = new Float32Array(32);
  private lightC = new Float32Array(24);
  private frontA = new Float32Array(32);
  private frontC = new Float32Array(24);

  constructor(config: Partial<MediumConfig> = {}) {
    this.config = { ...defaultMedium(), ...config };
  }

  // ─── FlowSource: what the storm rides
  get velocityTexture(): WebGLTexture | null {
    return this.velTex?.tex ?? null;
  }
  get dyeTexture(): WebGLTexture | null {
    return this.lightTex?.tex ?? null;
  }
  simSize(): [number, number] {
    return [FLOW_W, FLOW_H];
  }

  init(gl: WebGL2RenderingContext, caps: GLCaps, emptyVao: WebGLVertexArrayObject): void {
    this.gl = gl;
    this.vao = emptyVao;
    this.march = this.accum = this.comp = null;
    this.fieldTex = this.ionTex = this.velTex = this.lightTex = null;
    if (!caps.hdr) return;
    try {
      this.march = new Program(gl, FULLSCREEN_VS, MARCH_FS, 'dawn-gas:march');
      this.accum = new Program(gl, FULLSCREEN_VS, ACCUM_FS, 'dawn-gas:accumulate');
      this.comp = new Program(gl, FULLSCREEN_VS, COMPOSITE_FS, 'dawn-gas:composite');
    } catch (e) {
      console.error(e);
      this.march = this.accum = this.comp = null;
      return;
    }
    const tex = gl.createTexture();
    if (tex) {
      gl.bindTexture(gl.TEXTURE_3D, tex);
      gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
      gl.texImage3D(gl.TEXTURE_3D, 0, gl.R8, NOISE_SIZE, NOISE_SIZE, NOISE_SIZE, 0, gl.RED, gl.UNSIGNED_BYTE, noiseVolume());
      gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      for (const w of [gl.TEXTURE_WRAP_S, gl.TEXTURE_WRAP_T, gl.TEXTURE_WRAP_R]) gl.texParameteri(gl.TEXTURE_3D, w, gl.REPEAT);
      gl.bindTexture(gl.TEXTURE_3D, null);
    }
    this.noise = tex;
    this.fieldTex = dataTexture(gl);
    this.ionTex = dataTexture(gl);
    this.velTex = dataTexture(gl);
    this.lightTex = dataTexture(gl);
    this.target = new Target(gl, 1, 1, true);
    this.history = [new Target(gl, 1, 1, true), new Target(gl, 1, 1, true)];
    this.fresh = true;
  }

  /** Uploads what changed since the last frame (the flow first: the storm reads it this frame too). */
  private upload(gl: WebGL2RenderingContext): void {
    const up = (t: DataTexture | null, version: number, w: number, h: number, internal: number, format: number, data: Float32Array) => {
      if (!t || t.version === version) return;
      t.version = version;
      gl.bindTexture(gl.TEXTURE_2D, t.tex);
      gl.texImage2D(gl.TEXTURE_2D, 0, internal, w, h, 0, format, gl.FLOAT, data);
    };
    gl.activeTexture(gl.TEXTURE0);
    up(this.velTex, this.flowVersion, FLOW_W, FLOW_H, gl.RG16F, gl.RG, this.flowVelocity);
    up(this.lightTex, this.flowVersion, FLOW_W, FLOW_H, gl.RGBA16F, gl.RGBA, this.flowLight);
    up(this.fieldTex, this.fieldVersion, FIELD_W, FIELD_H, gl.RGBA16F, gl.RGBA, this.field);
    up(this.ionTex, this.ionVersion, ION_W, ION_H, gl.RGBA16F, gl.RGBA, this.ion);
    gl.bindTexture(gl.TEXTURE_2D, null);
  }

  draw(frame: LayerFrame): void {
    const gl = this.gl;
    const m = this.march;
    const acc = this.accum;
    if (!gl || !m || !acc || !this.comp || !this.noise || !this.fieldTex || !this.ionTex || !this.target || !this.history) return;
    this.upload(gl);
    const c = this.config;
    const q = frame.quality;
    this.time += frame.dt;
    const t = this.target;
    const [prev, next] = this.history;
    // Lower quality: fewer steps at a lower resolution, more frames averaged to make up for them.
    const scale = c.scale * q.volume;
    const steps = Math.max(6, Math.min(96, Math.round(c.steps * q.steps)));
    const blend = Math.min(1, 0.16 * (steps / Math.max(6, c.steps)));
    const w0 = t.width;
    const h0 = t.height;
    t.resize(frame.scene.width * scale, frame.scene.height * scale);
    prev.resize(t.width, t.height);
    next.resize(t.width, t.height);
    if (t.width !== w0 || t.height !== h0) this.fresh = true;

    const nl = Math.min(8, this.lights.length);
    for (let i = 0; i < nl; i++) {
      const L = this.lights[i];
      this.lightA.set([L.x, L.y, L.z, Math.max(1, L.radius)], i * 4);
      this.lightC.set(L.color, i * 3);
    }
    const nf = Math.min(8, this.fronts.length);
    for (let i = 0; i < nf; i++) {
      const f = this.fronts[i];
      this.frontA.set([f.x, f.y, f.radius, Math.max(1, f.width)], i * 4);
      this.frontC.set(f.color, i * 3);
    }
    const lt = this.light;

    gl.disable(gl.BLEND);
    t.bind();
    m.use().f1('uFocal', c.focal).f1('uDepth', c.depth).f1('uNear', c.near).f1('uThick', c.thick).f1('uTime', this.time);
    m.f1('uScale', c.noiseScale).f1('uBoil', c.boil).f1('uWarp', c.warp).f1('uDensity', c.density).f1('uFar', c.far).f1('uAbsorb', c.absorb);
    m.f1('uDetail', c.detail).f1('uPeriod', c.period).f2('uFlowScale', (2 * frame.view[2]) / FLOW_W, (-2 * frame.view[3]) / FLOW_H);
    m.f1('uFrame', (this.frameNo = (this.frameNo + 1) % 1024));
    m.f3('uAmbient', ...lt.ambient).f3('uGlow', ...lt.glow).f1('uHeat', lt.heat).f1('uIonGain', lt.ion).f1('uClear', lt.clear);
    m.f4('uRect', this.rect[0], this.rect[1], this.rect[2], this.rect[3]);
    gl.uniform1i(m.loc('uSteps'), steps);
    gl.uniform4fv(m.loc('uView'), frame.view);
    gl.uniform4fv(m.loc('uLight'), this.lightA);
    gl.uniform3fv(m.loc('uLightCol'), this.lightC);
    gl.uniform1i(m.loc('uLightCount'), nl);
    gl.uniform4fv(m.loc('uFront'), this.frontA);
    gl.uniform3fv(m.loc('uFrontCol'), this.frontC);
    gl.uniform1i(m.loc('uFrontCount'), nf);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_3D, this.noise);
    m.i1('uNoise', 0);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, this.fieldTex.tex);
    m.i1('uField', 1);
    gl.activeTexture(gl.TEXTURE2);
    gl.bindTexture(gl.TEXTURE_2D, this.ionTex.tex);
    m.i1('uIon', 2);
    gl.activeTexture(gl.TEXTURE3);
    gl.bindTexture(gl.TEXTURE_2D, this.velTex?.tex ?? this.ionTex.tex);
    m.i1('uFlow', 3);
    drawFullscreen(gl, this.vao!);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.activeTexture(gl.TEXTURE2);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_3D, null);

    next.bind();
    acc.use().i1('uCur', 0).i1('uPrev', 1).f1('uBlend', this.fresh ? 1 : blend).f2('uTexel', 1 / t.width, 1 / t.height);
    gl.uniform4fv(acc.loc('uView'), frame.view);
    gl.uniform4fv(acc.loc('uPrevView'), this.fresh ? frame.view : this.prevView);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, prev.tex);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, t.tex);
    drawFullscreen(gl, this.vao!);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, null);
    gl.activeTexture(gl.TEXTURE0);
    this.history = [next, prev];
    this.prevView.set(frame.view);
    this.fresh = false;

    frame.scene.bind();
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    this.comp.use().i1('uSrc', 0);
    gl.bindTexture(gl.TEXTURE_2D, next.tex);
    drawFullscreen(gl, this.vao!);
    gl.bindTexture(gl.TEXTURE_2D, null);
  }

  dispose(): void {
    const gl = this.gl;
    if (!gl) return;
    this.march?.dispose();
    this.accum?.dispose();
    this.comp?.dispose();
    if (this.noise) gl.deleteTexture(this.noise);
    for (const d of [this.fieldTex, this.ionTex, this.velTex, this.lightTex]) if (d) gl.deleteTexture(d.tex);
    this.target?.dispose();
    for (const h of this.history ?? []) h.dispose();
    this.march = this.accum = this.comp = null;
    this.noise = null;
    this.fieldTex = this.ionTex = this.velTex = this.lightTex = null;
    this.target = this.history = null;
  }
}

/** A linearly filtered, edge-clamped texture that a version number says when to refill. */
function dataTexture(gl: WebGL2RenderingContext): DataTexture | null {
  const tex = gl.createTexture();
  if (!tex) return null;
  gl.bindTexture(gl.TEXTURE_2D, tex);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  // Something valid to sample before the first fill.
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, 1, 1, 0, gl.RGBA, gl.FLOAT, new Float32Array(4));
  gl.bindTexture(gl.TEXTURE_2D, null);
  return { tex, version: -1 };
}
