/**
 * The multiverse's rules, kept pure for tests: what a universe's numbers do to each era, which
 * universes die young and why, how a universe ends, how a seed's numbers drift from its parent's, what
 * the change would mean in plain words, and how much a finished universe teaches (Insight).
 *
 * The traits are Rees' six numbers (Just Six Numbers, 1999) plus two laws that rarely change: dark
 * energy's equation of state w (a Big Rip needs w < −1) and the vacuum's lifetime (ours ~10¹³⁹ yr,
 * Andreassen, Frost & Schwartz 2018). Ours give exactly ×1 everywhere.
 */
import type { Rng } from './rng';
import type { Constants, EraId } from './state';
import { OUR_CONSTANTS } from './state';
import type { Modifier } from './stats';

export type Fate = 'heat-death' | 'crunch' | 'rip' | 'vacuum';

/** Why a universe died young: shown on its closing card. */
export interface Barren {
  title: string;
  text: string;
  /** Codex-style label for the lineage. */
  label: string;
  /** No star ever formed, so whatever an era counted, no black hole was left to hold a seed. */
  starless?: boolean;
}

/** Relative factors: gravity, fusion, matter, dark energy, ripples (all 1 for ours). The three linear ones are floored at 1/20: none, or less, still means "very little". */
export function factors(c: Constants): { g: number; e: number; m: number; l: number; q: number } {
  return {
    g: 10 ** (OUR_CONSTANTS.logN - c.logN),
    e: Math.max(0.05, c.epsilon / OUR_CONSTANTS.epsilon),
    m: Math.max(0.05, c.omega / OUR_CONSTANTS.omega),
    l: Math.max(0.05, c.lambda / OUR_CONSTANTS.lambda),
    q: 10 ** (c.logQ - OUR_CONSTANTS.logQ),
  };
}

function isOurs(c: Constants): boolean {
  const o = OUR_CONSTANTS;
  return c.logN === o.logN && c.epsilon === o.epsilon && c.omega === o.omega && c.lambda === o.lambda && c.logQ === o.logQ;
}

/** The widest a universe's numbers can push one stat: ×⅓ to ×3. */
export const MODIFIER_SPAN = 3;

/**
 * Soft limit on a multiplier: near-identity for small changes (×1.5 stays ×1.47), keeps its direction,
 * and never leaves ×⅓–×3 however far a lineage drifts (nothing kills a universe for weak gravity or
 * thin matter, so N and Ω can wander well past the friendly range).
 */
export function compress(x: number): number {
  const span = Math.log(MODIFIER_SPAN);
  return Math.exp(span * Math.tanh(Math.log(x) / span));
}

/** What a universe's numbers do to the eras: multipliers on their stats (none for ours). */
export function constantsModifiers(c: Constants): Modifier[] {
  if (isOurs(c)) return [];
  const { g, e, m, l, q } = factors(c);
  const out: Modifier[] = [];
  // `power`: how steeply the era's income follows the stat (income ∝ stat^power). The bound is on the
  // income, so a stat the income squares gets the root of the compressed effect.
  const mul = (stat: string, raw: number, source: string, power = 1) => {
    const value = compress(raw) ** (1 / power);
    if (Math.abs(value - 1) > 1e-6) out.push({ stat, kind: 'mul', value, source, sid: 'constants' });
  };
  const add = (stat: string, value: number, source: string) => {
    if (Math.abs(value) > 1e-6) out.push({ stat, kind: 'add', value, source, sid: 'constants' });
  };
  // Era II: how strongly nuclei bind sets how fast and how hot fusion runs.
  mul('nucleo.cross', e ** 3, 'Fusion (ε)');
  mul('nucleo.energyMult', e, 'Fusion (ε)');
  // Era III: the ripples' strength, and whole dark-matter wells: one more per ten times our matter
  // (from Ω ≈ 0.95), one fewer below a tenth of it.
  // Crossing crests pay (amplitude × amplitude)^0.85, so the income goes as amplitude^1.7.
  mul('afterglow.amp', q ** 0.25, 'Ripples (Q)', 1.7);
  add('afterglow.wells', Math.round(Math.log10(m)), 'Matter (Ω)');
  // Era IV: how fast the first wells pull gas in; dark energy thins the cosmic web.
  mul('dawn.pull', q ** 0.3 * m ** 0.3 * g ** 0.1, 'Ripples, matter and gravity');
  mul('dawn.web', l ** -0.3, 'Dark energy (λ)');
  // Era V: gravity sets how fast stars form, fusion how hard they explode, matter how much gas falls in.
  mul('forge.sfr', g ** 0.15, 'Gravity (N)');
  mul('forge.snEnergy', e, 'Fusion (ε)');
  mul('forge.inflow', m ** 0.3, 'Matter (Ω)');
  // Era VI: gravity drags galaxies together; dark energy sets how far a group can hold on.
  mul('galaxies.friction', g ** 0.15, 'Gravity (N)');
  mul('galaxies.halo', l ** (-1 / 3), 'Dark energy (λ)');
  mul('galaxies.inflow', m ** 0.3, 'Matter (Ω)');
  // Era VII: once the galaxy has evaporated, Hawking light and final flashes are all the night earns,
  // so gravity acts on them only slightly (×0.8 at the weak friendly edge keeps that stretch alive).
  mul('night.hawking', g ** 0.03, 'Gravity (N)');
  mul('night.refill', m ** 0.2, 'Matter (Ω)');
  return out;
}

/** How many more (or fewer) black holes this universe forms than ours: the seeds of the next. */
export function blackHoleFactor(c: Constants): number {
  const { g, q } = factors(c);
  return Math.min(100, q ** 0.5 * g ** 0.2);
}

/** Checked when `era` ends: the reason this universe can go no further, or null. */
export function diesYoung(c: Constants, era: EraId): Barren | null {
  if (era === 'nucleo') {
    if (c.epsilon < 0.006)
      return {
        label: 'Only hydrogen',
        title: 'A universe of hydrogen',
        text: 'Nuclear forces here are a little too weak to hold a proton and a neutron together, so deuterium falls apart as soon as it forms. Without it there is no step up to helium or anything heavier: this universe will only ever hold hydrogen, and no star will make anything else.',
      };
    if (c.epsilon > 0.008)
      return {
        label: 'Hydrogen burned away',
        title: 'The hydrogen burned away',
        text: 'Nuclear forces here are a little too strong: even two protons can stick together. Fusion ran away in the first minutes and turned the hydrogen into heavier nuclei, leaving no fuel for slow, long-lived stars, and no water.',
      };
  }
  if (era === 'afterglow' && c.omega > 3 && c.lambda < 0.3)
    return {
      label: 'Fell back too soon',
      title: 'It fell back together',
      text: 'There is so much matter here that the expansion slowed, stopped and reversed before the first star could form. The universe ends as it began, hot and dense, a few hundred million years in.',
    };
  if (era === 'dawn') {
    if (c.logQ < -6)
      return {
        label: 'Too smooth',
        starless: true,
        title: 'Too smooth to collapse',
        text: 'The ripples left by inflation are too faint here. Gas never gathers densely enough to collapse, so no star ever lights and no galaxy ever forms: a dark, even haze, cooling forever.',
      };
    if (c.logQ > -4)
      return {
        label: 'Black holes everywhere',
        title: 'A universe of black holes',
        text: 'The ripples here are so strong that whole regions collapse straight into black holes instead of stars. Nothing stable is left to shine, but the black holes themselves are many: seeds for what comes next.',
      };
    if (c.lambda > 3)
      return {
        label: 'Torn apart early',
        title: 'Dark energy won early',
        text: 'Dark energy is so strong here that the expansion speeds up before gas can gather into galaxies. The first stars are left scattered and alone, and soon even they are out of sight of one another.',
      };
    if (c.logN < 33)
      return {
        label: 'Stars burned out',
        title: 'Stars that burn out in moments',
        text: 'Gravity is so strong here that stars are tiny and crushed hot. Each one burns through its fuel in a flash; nothing lasts long enough to build heavier elements, let alone anything more.',
      };
  }
  return null;
}

/** How this universe ends if it lives that long. */
export function fateOf(c: Constants): Fate {
  if (c.logVacuum < 100) return 'vacuum';
  if (c.w < -1) return 'rip';
  if (c.lambda < 0 || (c.omega > 1.2 && c.lambda < 0.2)) return 'crunch';
  return 'heat-death';
}

export const FATE_NAME: Record<Fate, string> = {
  'heat-death': 'Heat death',
  crunch: 'Big Crunch',
  rip: 'Big Rip',
  vacuum: 'Vacuum decay',
};

/** One line on how a universe that lived to its fate ended. */
export const FATE_TEXT: Record<Fate, string> = {
  'heat-death': 'The last black hole evaporated, and the universe settled into the evenness of heat death: nothing left to happen, forever.',
  crunch: 'The expansion stopped and turned around. Everything fell back together into one hot point.',
  rip: 'Dark energy grew without limit and tore apart galaxies, then stars, then atoms.',
  vacuum: 'A bubble of a lower-energy vacuum appeared and swept outward at nearly the speed of light, rewriting everything it touched.',
};

export interface MutateOptions {
  /** Knowledge "Steady hand": mutations shrink by this factor. */
  scale?: number;
}

/** A seed's numbers: the parent's, each drifted a little (two laws rarely change at all). */
export function mutate(parent: Constants, rng: Rng, o: MutateOptions = {}): Constants {
  const k = o.scale ?? 1;
  const c: Constants = { ...parent };
  c.logN = round(parent.logN + rng.gauss() * 0.5 * k, 2);
  c.epsilon = round(parent.epsilon + rng.gauss() * 0.0004 * k, 5);
  c.omega = round(parent.omega * Math.exp(rng.gauss() * 0.35 * k), 3);
  c.lambda = round(parent.lambda + rng.gauss() * 0.2 * k, 3);
  c.logQ = round(parent.logQ + rng.gauss() * 0.35 * k, 2);
  if (rng.chance(0.08)) c.w = round(parent.w + rng.gauss() * 0.15, 3);
  if (rng.chance(0.08)) c.logVacuum = round(parent.logVacuum + rng.gauss() * 40, 0);
  return c;
}

function round(x: number, digits: number): number {
  const f = 10 ** digits;
  return Math.round(x * f) / f;
}

function degree(d: number, small: number): string {
  const a = Math.abs(d);
  if (a < small) return 'slightly';
  if (a < small * 3) return 'a little';
  return 'much';
}

/** What a seed's numbers would mean, compared with its parent's, in plain words (most notable first). */
export function predictions(parent: Constants, c: Constants): string[] {
  const out: { w: number; text: string }[] = [];
  const dN = c.logN - parent.logN;
  if (Math.abs(dN) >= 0.1)
    out.push({
      w: Math.abs(dN) / 0.5,
      text: dN < 0 ? `Gravity ${degree(dN, 0.3)} stronger: stars form faster and burn out sooner, and more end as black holes.` : `Gravity ${degree(dN, 0.3)} weaker: structure grows more slowly and stars live longer.`,
    });
  const dE = c.epsilon - parent.epsilon;
  if (Math.abs(dE) >= 0.0001)
    out.push({
      w: Math.abs(dE) / 0.0004,
      text: dE > 0 ? `Fusion ${degree(dE, 0.0002)} more powerful: brighter stars and faster nucleosynthesis.` : `Fusion ${degree(dE, 0.0002)} weaker: dimmer stars and slower nucleosynthesis.`,
    });
  const dM = Math.log(c.omega / parent.omega);
  if (Math.abs(dM) >= 0.08)
    out.push({
      w: Math.abs(dM) / 0.35,
      text: dM > 0 ? `${degree(dM, 0.2) === 'much' ? 'Much more' : 'More'} matter: galaxies gather sooner and grow larger.` : `${degree(dM, 0.2) === 'much' ? 'Much less' : 'Less'} matter: galaxies form later and smaller.`,
    });
  const dL = c.lambda - parent.lambda;
  if (Math.abs(dL) >= 0.05)
    out.push({
      w: Math.abs(dL) / 0.2,
      text: dL > 0 ? 'Stronger dark energy: groups of galaxies hold together over a smaller region.' : 'Weaker dark energy: more of the sky stays within reach.',
    });
  const dQ = c.logQ - parent.logQ;
  if (Math.abs(dQ) >= 0.08)
    out.push({
      w: Math.abs(dQ) / 0.35,
      text: dQ > 0 ? 'Stronger ripples: the first structures collapse sooner, leaving more black holes.' : 'Fainter ripples: the Dark Ages last longer before the first stars.',
    });
  if (c.w !== parent.w)
    out.push({ w: 3, text: c.w < -1 ? 'Dark energy that grows stronger with time.' : c.w > -1 ? 'Dark energy that slowly weakens.' : 'Dark energy that stays the same.' });
  if (c.logVacuum !== parent.logVacuum) out.push({ w: 3, text: c.logVacuum < parent.logVacuum ? 'A less stable vacuum.' : 'A more stable vacuum.' });
  return out
    .sort((a, b) => b.w - a.w)
    .slice(0, 3)
    .map((o) => o.text);
}

/** Warnings for numbers outside the friendly range (what would go wrong). */
export function warnings(c: Constants): string[] {
  const out: string[] = [];
  if (c.epsilon < 0.006) out.push('Deuterium could not hold together: nothing but hydrogen, ever.');
  if (c.epsilon > 0.008) out.push('Pairs of protons would bind: the hydrogen would burn away in the first minutes.');
  if (c.omega > 3 && c.lambda < 0.3) out.push('So much matter that it would fall back together before any star.');
  if (c.logQ < -6) out.push('Ripples too faint: gas would never collapse into stars.');
  if (c.logQ > -4) out.push('Ripples so strong that everything would collapse into black holes.');
  if (c.lambda > 3) out.push('Dark energy so strong that galaxies could never form.');
  if (c.logN < 33) out.push('Gravity so strong that stars would burn out in moments.');
  if (c.lambda < 0) out.push('Negative dark energy: this universe would end in a Big Crunch.');
  else if (c.omega > 1.2 && c.lambda < 0.2) out.push('Too little dark energy to stop the fall: a Big Crunch.');
  if (c.w < -1) out.push('Dark energy that grows stronger: a Big Rip.');
  if (c.logVacuum < 100) out.push('A vacuum that would decay before the last black hole is gone.');
  return out;
}

/** Whether every number sits in the friendly range (and the universe would live to its fate). */
export function friendly(c: Constants): boolean {
  return c.epsilon >= 0.006 && c.epsilon <= 0.008 && c.logN >= 33 && c.logN <= 39 && c.omega >= 0.1 && c.omega <= 3 && c.lambda < 3 && c.logQ >= -6 && c.logQ <= -4;
}

/** Whether a player who knows what to look for would find life here: friendly numbers, close to ours. */
export function lifeNoticed(c: Constants): boolean {
  return friendly(c) && strangeness(c) <= 1;
}

/** How far a universe's numbers sit from ours (0 for ours; ~1 for a clearly different one). */
export function strangeness(c: Constants): number {
  const o = OUR_CONSTANTS;
  const d = [(c.logN - o.logN) / 3, (c.epsilon - o.epsilon) / 0.001, Math.log10(c.omega / o.omega), c.lambda - o.lambda, c.logQ - o.logQ, (c.w - o.w) / 0.3, Math.min(1, Math.abs(c.logVacuum - o.logVacuum) / 60)];
  return Math.sqrt(d.reduce((t, x) => t + x * x, 0));
}

/** Universes in the lineage before the foam starts budding on its own. */
export const INFLATION_AFTER = 5;

/**
 * Eternal inflation: log₁₀ of the universes the foam has budded on its own after `seconds`. It grows
 * exponentially (a googol in ~9 minutes, 10⁵⁰⁰ in ~12, a googolplex in ~8 hours).
 */
export function inflationLog(seconds: number): number {
  // Past ~23.6 hours the count's log no longer fits in a double; the milestones are long passed.
  return Math.exp(Math.min(seconds / 120, 709));
}

/**
 * The count for display, as 10ⁿ or, once n itself is huge, 10^(10ᵐ). The outer exponent comes
 * straight from the time, so it keeps counting long after the count itself would overflow.
 */
export function inflationTower(seconds: number): { inner: string; outer: string | null } {
  const log = inflationLog(seconds);
  if (log < 1e6) return { inner: String(Math.floor(log)), outer: null };
  const loglog = seconds / (120 * Math.LN10);
  return { inner: loglog.toFixed(loglog < 10 ? 2 : 1), outer: '10' };
}

export interface InflationMilestone {
  /** log₁₀ of the count. */
  at: number;
  /** What the number is called. */
  name: string;
  insight: number;
  text: string;
}

export const INFLATION_MILESTONES: readonly InflationMilestone[] = [
  { at: 100, name: 'a googol', insight: 2, text: 'The foam has budded a googol of universes on its own: ten to the hundredth.' },
  { at: 500, name: '10⁵⁰⁰', insight: 5, text: 'The foam has passed 10⁵⁰⁰ universes, about the number of different vacua string theory is thought to allow.' },
  { at: 1e10, name: 'ten to the ten billionth', insight: 10, text: 'The foam has budded ten to the ten billionth universes.' },
  { at: 1e100, name: 'a googolplex', insight: 25, text: 'A googolplex of universes: a one followed by a googol of zeros. By one estimate, that is already more than any observer could ever tell apart.' },
];

export interface InsightInput {
  constants: Constants;
  /** Codex entries first discovered in this universe. */
  newDiscoveries: number;
  blackHoles: number;
  fate: Fate | 'barren';
  /** Knowledge multiplier (Long memory). */
  mult?: number;
}

export interface InsightBreakdown {
  lines: { label: string; value: number }[];
  total: number;
}

const FATE_INSIGHT: Record<Fate | 'barren', number> = { 'heat-death': 5, crunch: 10, rip: 15, vacuum: 20, barren: 2 };

/** What a finished universe teaches: Insight, with its breakdown. */
export function insightFor(i: InsightInput): InsightBreakdown {
  const lines = [
    { label: 'A universe completed', value: 10 },
    { label: 'Discoveries made in it', value: 2 * i.newDiscoveries },
    { label: 'Black holes it formed', value: Math.round(Math.log10(Math.max(1, i.blackHoles))) },
    { label: i.fate === 'barren' ? 'It died young' : FATE_NAME[i.fate], value: FATE_INSIGHT[i.fate] },
    { label: 'Strangeness', value: Math.round(5 * strangeness(i.constants)) },
  ].filter((l) => l.value > 0);
  const mult = i.mult ?? 1;
  if (mult !== 1) lines.push({ label: 'Long memory', value: Math.round(lines.reduce((t, l) => t + l.value, 0) * (mult - 1)) });
  return { lines, total: lines.reduce((t, l) => t + l.value, 0) };
}
